"use client";

import { use, useCallback, useEffect, useState, useRef } from "react";
import { useSearchParams } from "next/navigation";
import { useRouter, Link } from "@/lib/i18n-navigation";
import {
  CreditCard,
  Check,
  ExternalLink,
  Loader2,
  AlertTriangle,
  Users,
  Info,
  ArrowRight,
  X,
  Wallet,
} from "lucide-react";
import { api } from "@/lib/api";
import { useTranslations } from "next-intl";
import { useToast } from "@/components/Toast";
import { Skeleton } from "@/components/Skeleton";
import QRCode from "qrcode";

type Plan = "free" | "pro";
type PaymentMethod = "card" | "wechat" | "alipay";

interface BillingStatus {
  plan: Plan;
  seatLimit: number;
  memberCount: number;
  seatsUsed: number;
  role: "owner" | "admin" | "member";
  stripeReady: boolean;
  subscription: {
    status: string;
    quantity: number;
    currentPeriodEnd: string | null;
    canManage: boolean;
  } | null;
}

// 套餐卡数据（阶段 2-6 i18n）：nameKey/unitKey/seatsKey/details 均为 billing ns
// 翻译 key，渲染处经 t() 解析；price 保持字面量（币种格式随通道不同）。
// M3 修复：移除 features 字段，将 features 内容合并到 details，消除 pro 的数据重复。
const PLANS: {
  id: Plan;
  nameKey: string;
  price: string;
  unitKey: string;
  seatsKey: string;
  details: string[];
}[] = [
  {
    id: "free",
    nameKey: "planFree",
    price: "¥0",
    unitKey: "unitForever",
    seatsKey: "seatsFree",
    details: [
      "featBoard",
      "featComments",
      "featIm",
      "featDecisions10",
      "featCalendar",
      "featNotif",
      "detailSeats10",
      "detailDecisions10",
      "detailBasicExport",
      "detailCommunity",
    ],
  },
  {
    id: "pro",
    nameKey: "planPro",
    price: "¥29.9",
    unitKey: "unitPerSeatMonth",
    seatsKey: "seatsPerSeat",
    details: [
      "featUnlimitedDecisions",
      "featFilterViews",
      "featAttachments50",
      "featEmail",
      "featCsv",
      "seatsPerSeat",
      "featEmailSupport",
    ],
  },
];

const SUB_STATUS_LABEL: Record<string, { labelKey: string; tone: "ok" | "warn" | "muted" }> = {
  active: { labelKey: "subActive", tone: "ok" },
  trialing: { labelKey: "subTrialing", tone: "ok" },
  past_due: { labelKey: "subPastDue", tone: "warn" },
  canceled: { labelKey: "subCanceled", tone: "muted" },
  incomplete: { labelKey: "subIncomplete", tone: "warn" },
};

export default function BillingPage({ params }: { params: Promise<{ wid: string }> }) {
  const { wid } = use(params);
  const router = useRouter();

  const t = useTranslations("billing");
  const tButton = useTranslations("button");
  const { toast } = useToast();
  const search = useSearchParams();
  const [status, setStatus] = useState<BillingStatus | null>(null);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState<string | null>(null);
  // Phase 2：支付方式选择（缺省 card 保持存量行为）
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>("card");
  // 计费周期（v2 定价：年付 ¥299/人/年，相当于每月 ¥24.9）
  const [billingPeriod, setBillingPeriod] = useState<"monthly" | "yearly">("monthly");
  // 微信二维码模态框状态
  const [wechatQr, setWechatQr] = useState<{ url: string; orderId: string } | null>(null);
  // R8B-06：本地生成的 QR 码 Data URL（替代外部 api.qrserver.com，避免订单 code_url 发送第三方）
  const [qrDataUrl, setQrDataUrl] = useState<string>("");
  // 轮询定时器引用
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const justPaid = search.get("success") === "1";
  const canceled = search.get("canceled") === "1";

  const load = useCallback(async () => {
    try {
      setStatus(await api<BillingStatus>(`/api/v1/workspaces/${wid}/billing/status`));
    } catch (e) {
      setError(e instanceof Error ? e.message : t("loadFailed"));
    }
  }, [wid]);

  useEffect(() => {
    load();
  }, [load]);

  // 清理轮询定时器
  useEffect(() => {
    return () => {
      if (pollRef.current) clearInterval(pollRef.current);
    };
  }, []);

  // M7 修复：微信二维码模态框打开时锁定 body 滚动 + Esc 关闭
  useEffect(() => {
    if (!wechatQr) return;
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        closeWechatQr();
      }
    };
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.body.style.overflow = prevOverflow;
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [wechatQr]);

  // R8B-06：wechatQr 变化时本地生成 QR 码 Data URL（替代外部 api.qrserver.com）
  useEffect(() => {
    if (!wechatQr) {
      setQrDataUrl("");
      return;
    }
    QRCode.toDataURL(wechatQr.url, { width: 240, margin: 1 })
      .then(setQrDataUrl)
      .catch(() => setQrDataUrl(""));
  }, [wechatQr]);

  async function upgrade(plan: Plan) {
    setError("");
    // 支付方式 → provider 参数映射
    const providerMap: Record<PaymentMethod, "stripe" | "wechatpay-native" | "alipay-page"> = {
      card: "stripe",
      wechat: "wechatpay-native",
      alipay: "alipay-page",
    };
    const provider = providerMap[paymentMethod];

    // 跳转型通道（信用卡/支付宝）需确认；微信扫码弹模态框无需 confirm
    if (paymentMethod !== "wechat") {
      const channelLabel = paymentMethod === "card" ? "Stripe" : t("alipay");
      toast("info", t("payRedirectConfirm", { channel: channelLabel }));
    }

    setBusy(plan);
    try {
      const resp = await api<{
        url?: string;
        qrCodeUrl?: string;
        providerOrderId?: string;
        providerId?: string;
      }>(`/api/v1/workspaces/${wid}/billing/checkout`, {
        method: "POST",
        body: JSON.stringify({ planId: plan, provider, period: billingPeriod }),
      });

      if (resp.qrCodeUrl) {
        // 微信 Native 支付：显示二维码模态框并轮询订阅状态
        setWechatQr({ url: resp.qrCodeUrl, orderId: resp.providerOrderId ?? "" });
        startPolling();
      } else if (resp.url) {
        // Stripe / 支付宝：跳转到通道页面
        router.push(resp.url);
      } else {
        setError(t("payNoResult"));
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : t("payCreateFailed"));
    } finally {
      setBusy(null);
    }
  }

  /** 微信支付状态轮询：每 3 秒查一次 status，订阅变 active 即关闭模态框 */
  function startPolling() {
    if (pollRef.current) clearInterval(pollRef.current);
    let attempts = 0;
    const maxAttempts = 60; // 最长轮询 3 分钟（60 × 3s）
    pollRef.current = setInterval(async () => {
      attempts++;
      if (attempts > maxAttempts) {
        if (pollRef.current) clearInterval(pollRef.current);
        setError(t("payPollTimeout"));
        setWechatQr(null);
        return;
      }
      try {
        const s = await api<BillingStatus>(`/api/v1/workspaces/${wid}/billing/status`);
        setStatus(s);
        if (s.plan === "pro" && s.subscription?.status === "active") {
          if (pollRef.current) clearInterval(pollRef.current);
          setWechatQr(null);
        }
      } catch {
        // 轮询失败不中断，继续重试
      }
    }, 3000);
  }

  /** 关闭微信二维码模态框并停止轮询 */
  function closeWechatQr() {
    if (pollRef.current) clearInterval(pollRef.current);
    setWechatQr(null);
  }

  async function openPortal() {
    setError("");
    setBusy("portal");
    try {
      const { url } = await api<{ url: string }>(`/api/v1/workspaces/${wid}/billing/portal`, {
        method: "POST",
      });
      if (url) router.push(url);
    } catch (e) {
      setError(e instanceof Error ? e.message : t("portalFailed"));
    } finally {
      setBusy(null);
    }
  }

  const isOwner = status?.role === "owner";
  const sub = status?.subscription;
  const subMeta = sub
    ? (SUB_STATUS_LABEL[sub.status] ?? { label: sub.status, tone: "muted" })
    : null;
  const seatsUsed = status?.seatsUsed ?? 0;
  const seatLimit = status?.seatLimit ?? 0;

  return (
    <div className="max-w-[var(--container-max)] mx-auto px-[var(--space-4)] sm:px-0">
      <div className="mb-6">
        <h1 className="flex items-center gap-2 text-[length:var(--text-2xl)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
          <CreditCard size={20} className="text-[var(--muted)]" />
          {t("title")}
        </h1>
        <p className="mt-1 text-[length:var(--text-sm)] text-[var(--muted)]">{t("subtitle")}</p>
        {/* 互链到 /pricing 定价页（spec §1，当前窗口跳转走 next/link 客户端路由） */}
        <Link
          href="/pricing"
          className="mt-3 inline-flex items-center gap-1 text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--accent)] hover:text-[var(--accent-hover)] transition-colors duration-[var(--motion-base)]"
        >
          {t("viewFullComparison")} <ArrowRight size={14} aria-hidden="true" />
        </Link>
      </div>

      {justPaid && (
        <div className="mb-4 flex items-start gap-2 px-4 py-3 rounded-[var(--radius-md)] bg-[var(--success-soft)] text-[var(--success-fg)] text-[length:var(--text-sm)]">
          <Check size={16} className="shrink-0 mt-0.5 text-[var(--success)]" />
          <span>{t("justPaid")}</span>
        </div>
      )}
      {canceled && (
        <div className="mb-4 px-4 py-3 rounded-[var(--radius-md)] bg-[var(--surface-2)] text-[var(--fg-2)] text-[length:var(--text-sm)] border border-[var(--border)]">
          {t("checkoutCanceled")}
        </div>
      )}
      {error && (
        <div className="mb-4 flex items-start gap-2 px-4 py-3 rounded-[var(--radius-md)] bg-[var(--danger-soft)] text-[var(--danger-fg)] text-[length:var(--text-sm)]">
          <AlertTriangle size={16} className="shrink-0 mt-0.5 text-[var(--danger)]" />
          <span>{error}</span>
        </div>
      )}

      {/* 当前状态 */}
      <div className="bg-[var(--surface)] border border-[var(--border)] rounded-[var(--radius-lg)] shadow-[var(--elev-sm)] p-4 sm:p-5 mb-5 sm:mb-6">
        {!status ? (
          <div className="space-y-3" aria-busy="true" aria-label={t("loadingStatus")}>
            <div className="space-y-1.5">
              <Skeleton className="h-3 w-16" />
              <Skeleton className="h-5 w-28" />
            </div>
            <div className="space-y-1.5">
              <Skeleton className="h-3 w-12" />
              <Skeleton className="h-5 w-20" />
              <Skeleton className="h-1 w-32 rounded-full" />
            </div>
          </div>
        ) : (
          <div className="flex flex-col sm:flex-row sm:flex-wrap sm:items-start sm:justify-between gap-4">
            <div>
              <div className="text-[length:var(--text-xs)] text-[var(--meta)] mb-1">
                {t("currentPlan")}
              </div>
              <div className="flex items-center gap-2">
                <span className="text-[length:var(--text-lg)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
                  {t(PLANS.find((p) => p.id === status.plan)?.nameKey ?? "planFree")}
                </span>
                {subMeta && (
                  <span
                    className={`px-2 py-0.5 rounded-full text-[length:var(--text-xs)] ${
                      subMeta.tone === "ok"
                        ? "bg-[var(--success-soft)] text-[var(--success-fg)]"
                        : subMeta.tone === "warn"
                          ? "bg-[var(--warn-soft)] text-[var(--warn-fg)]"
                          : "bg-[var(--surface-2)] text-[var(--muted)]"
                    }`}
                  >
                    {t(subMeta.labelKey)}
                  </span>
                )}
              </div>
              {sub?.currentPeriodEnd && (
                <div className="mt-1 text-[length:var(--text-xs)] text-[var(--meta)]">
                  {t("currentPeriodEnd", {
                    date: new Date(sub.currentPeriodEnd).toLocaleDateString(),
                  })}
                </div>
              )}
            </div>

            <div>
              <div className="flex items-center gap-1.5 text-[length:var(--text-xs)] text-[var(--meta)] mb-1">
                <Users size={13} />
                {t("seats")}
              </div>
              <div className="text-[length:var(--text-lg)] font-[weight:var(--weight-semibold)] text-[var(--fg)] tabular-nums">
                {seatsUsed}
                {seatLimit > 0 && (
                  <span className="text-[length:var(--text-sm)] font-[weight:var(--weight-regular)] text-[var(--muted)]">
                    {" "}
                    / {seatLimit}
                  </span>
                )}
              </div>
              {seatLimit > 0 && (
                <div className="mt-1.5 w-32 h-1 rounded-full bg-[var(--surface-3)] overflow-hidden">
                  <div
                    className="h-full rounded-full transition-[width] duration-[var(--motion-slow)]"
                    style={{
                      width: `${Math.min(100, (seatsUsed / seatLimit) * 100)}%`,
                      background: seatsUsed >= seatLimit ? "var(--warn)" : "var(--accent)",
                    }}
                  />
                </div>
              )}
            </div>

            {isOwner && sub?.canManage && (
              <button
                onClick={openPortal}
                disabled={busy === "portal"}
                className="w-full sm:w-auto inline-flex items-center justify-center gap-1.5 h-9 px-3 border border-[var(--border)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] disabled:opacity-50 transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
              >
                {busy === "portal" ? (
                  <Loader2 size={15} className="animate-spin" />
                ) : (
                  <ExternalLink size={15} />
                )}
                {t("manageBilling")}
              </button>
            )}
          </div>
        )}
      </div>

      {/* 支付方式选择（Phase 2：国内支付接入） */}
      {isOwner && status?.stripeReady && (
        <div className="mb-5 sm:mb-6 bg-[var(--surface)] border border-[var(--border)] rounded-[var(--radius-lg)] shadow-[var(--elev-sm)] p-4 sm:p-5">
          <div className="text-[length:var(--text-xs)] text-[var(--meta)] mb-3">
            {t("paymentMethod")}
          </div>
          <div className="flex flex-wrap gap-2" role="group" aria-label={t("paymentMethod")}>
            <button
              onClick={() => setPaymentMethod("card")}
              aria-pressed={paymentMethod === "card"}
              className={`inline-flex items-center gap-2 h-10 px-4 rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] ${
                paymentMethod === "card"
                  ? "bg-[var(--accent)] text-[var(--accent-fg)]"
                  : "bg-[var(--surface-2)] text-[var(--fg-2)] hover:bg-[var(--surface-3)]"
              }`}
            >
              <CreditCard size={16} />
              {t("methodCard")}
            </button>
            <button
              onClick={() => setPaymentMethod("wechat")}
              aria-pressed={paymentMethod === "wechat"}
              className={`inline-flex items-center gap-2 h-10 px-4 rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] ${
                paymentMethod === "wechat"
                  ? "bg-[var(--accent)] text-[var(--accent-fg)]"
                  : "bg-[var(--surface-2)] text-[var(--fg-2)] hover:bg-[var(--surface-3)]"
              }`}
            >
              <Wallet size={16} />
              {t("methodWechat")}
            </button>
            <button
              onClick={() => setPaymentMethod("alipay")}
              aria-pressed={paymentMethod === "alipay"}
              className={`inline-flex items-center gap-2 h-10 px-4 rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] ${
                paymentMethod === "alipay"
                  ? "bg-[var(--accent)] text-[var(--accent-fg)]"
                  : "bg-[var(--surface-2)] text-[var(--fg-2)] hover:bg-[var(--surface-3)]"
              }`}
            >
              <Wallet size={16} />
              {t("methodAlipay")}
            </button>
          </div>
          <p className="mt-2 text-[length:var(--text-xs)] text-[var(--meta)]">
            {paymentMethod === "card" && t("descCard")}
            {paymentMethod === "wechat" && t("descWechat")}
            {paymentMethod === "alipay" && t("descAlipay")}
          </p>
        </div>
      )}

      {/* 计费周期切换（年付对齐定价页口径：¥299/人/年，立省 ¥59.8） */}
      {isOwner && (
        <div className="mb-4 flex items-center gap-2">
          <button
              onClick={() => setBillingPeriod("monthly")}
              className={`h-9 px-3 rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 ${
              billingPeriod === "monthly"
                ? "bg-[var(--accent)] text-[var(--accent-fg)]"
                : "bg-[var(--surface-2)] text-[var(--fg-2)] hover:bg-[var(--surface-3)]"
            }`}
          >
            {t("periodMonthly")}
          </button>
          <button
              onClick={() => setBillingPeriod("yearly")}
              className={`h-9 px-3 rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 ${
              billingPeriod === "yearly"
                ? "bg-[var(--accent)] text-[var(--accent-fg)]"
                : "bg-[var(--surface-2)] text-[var(--fg-2)] hover:bg-[var(--surface-3)]"
            }`}
          >
            {t("periodYearly")}
          </button>
        </div>
      )}

      {/* 套餐卡片 */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        {PLANS.map((p) => {
          const current = status?.plan === p.id;
          const upgradable = isOwner && !current && p.id !== "free" && status?.stripeReady;
          // Pro 卡片价格/单位随计费周期切换；免费档固定 ¥0
          const price = p.id === "pro" && billingPeriod === "yearly" ? "¥299" : p.price;
          const unit =
            p.id === "pro"
              ? billingPeriod === "yearly"
                ? t("unitPerSeatYear")
                : t("unitPerSeatMonth")
              : t(p.unitKey);
          const seats =
            p.id === "pro" && billingPeriod === "yearly" ? t("yearlyAvg") : t(p.seatsKey);
          return (
            <div
              key={p.id}
              className={`flex flex-col bg-[var(--surface)] rounded-[var(--radius-lg)] p-4 sm:p-5 shadow-[var(--elev-sm)] ${current ? "border-2 border-[var(--accent)]" : "border border-[var(--border)]"}`}
            >
              <div className="flex items-baseline justify-between">
                <span className="text-[length:var(--text-md)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
                  {t(p.nameKey)}
                </span>
                {current && (
                  <span className="px-2 py-0.5 rounded-full bg-[var(--accent-soft)] text-[var(--accent)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)]">
                    {t("currentBadge")}
                  </span>
                )}
              </div>

              <div className="mt-3 flex items-baseline gap-1">
                <span className="text-[length:var(--text-3xl)] font-[weight:var(--weight-semibold)] text-[var(--fg)] tabular-nums tracking-[var(--tracking-display)]">
                  {price}
                </span>
                <span className="text-[length:var(--text-xs)] text-[var(--meta)]">{unit}</span>
              </div>
              <div className="mt-1 text-[length:var(--text-xs)] text-[var(--meta)]">{seats}</div>

              <ul className="mt-4 space-y-2 flex-1">
                {p.details.map((f) => (
                  <li
                    key={f}
                    className="flex items-start gap-2 text-[length:var(--text-sm)] text-[var(--fg-2)]"
                  >
                    <Check size={14} className="shrink-0 mt-0.5 text-[var(--success)]" />
                    {t(f)}
                  </li>
                ))}
              </ul>

              <button
                onClick={() => upgrade(p.id)}
                disabled={!upgradable || busy === p.id}
                title={!upgradable ? t("upgradeDisabledTitle") : undefined}
                className={`mt-5 h-9 w-full rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] transition-colors duration-[var(--motion-base)] flex items-center justify-center gap-1.5 disabled:cursor-not-allowed disabled:opacity-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 ${
                  upgradable
                    ? "bg-[var(--accent)] text-[var(--accent-fg)]"
                    : "bg-[var(--surface-2)] text-[var(--meta)]"
                }`}
              >
                {busy === p.id && <Loader2 size={15} className="animate-spin" />}
                {current
                  ? t("inUse")
                  : p.id === "free"
                    ? t("included")
                    : upgradable
                      ? tButton("upgrade")
                      : t("unavailable")}
              </button>

              <details className="mt-3 group">
                <summary className="cursor-pointer text-[length:var(--text-xs)] text-[var(--meta)] hover:text-[var(--fg-2)] transition-colors duration-[var(--motion-fast)] select-none">
                  {t("fullComparison")}
                </summary>
                <ul className="mt-2 space-y-1.5">
                  {p.details.map((d) => (
                    <li
                      key={d}
                      className="flex items-start gap-1.5 text-[length:var(--text-xs)] text-[var(--fg-2)]"
                    >
                      <Check size={12} className="shrink-0 mt-0.5 text-[var(--success)]" />
                      {t(d)}
                    </li>
                  ))}
                </ul>
              </details>
            </div>
          );
        })}
      </div>

      {status && !status.stripeReady && (
        <div className="mt-5 flex items-start gap-2 px-4 py-3 rounded-[var(--radius-md)] bg-[var(--surface-2)] text-[var(--fg-2)] text-[length:var(--text-sm)]">
          <Info size={16} className="shrink-0 mt-0.5 text-[var(--muted)]" />
          <span>
            {t("stripeNotConfiguredPrefix")}
            <code className="font-[family-name:var(--font-mono)] text-[length:var(--text-xs)]">
              STRIPE_SECRET_KEY
            </code>
            {" / "}
            <code className="font-[family-name:var(--font-mono)] text-[length:var(--text-xs)]">
              STRIPE_PRICE_ID
            </code>
            {t("stripeNotConfiguredSuffix")}
          </span>
        </div>
      )}

      {status && !isOwner && (
        <p className="mt-5 text-[length:var(--text-xs)] text-[var(--meta)]">
          {t("ownerOnlyNotice")}
        </p>
      )}

      {/* 微信支付二维码模态框（Phase 2：Native 扫码支付） */}
      {wechatQr && (
        <div
          className="fixed inset-0 z-[var(--z-modal)] flex items-center justify-center bg-[var(--overlay)]"
          role="dialog"
          aria-modal="true"
          aria-label={t("wechatQrAria")}
          onClick={closeWechatQr}
        >
          <div
            className="bg-[var(--surface)] rounded-[var(--radius-lg)] shadow-[var(--elev-lg)] p-6 max-w-sm w-full mx-4"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-[length:var(--text-lg)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
                {t("wechatPayTitle")}
              </h2>
              <button
                onClick={closeWechatQr}
                className="text-[var(--muted)] hover:text-[var(--fg)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
                aria-label={tButton("close")}
              >
                <X size={20} />
              </button>
            </div>
            <div className="flex flex-col items-center">
              {/* R8B-06：本地生成 QR 码（qrcode npm 包），避免订单 code_url 发送第三方 API */}
              {/* M8 修复：保留 onError 兜底；referrerPolicy/crossOrigin 对 Data URL 无害但保留 */}
              { }
              {qrDataUrl && (
                <img
                  src={qrDataUrl}
                  alt={t("wechatQr")}
                  width={240}
                  height={240}
                  referrerPolicy="no-referrer"
                  crossOrigin="anonymous"
                  className="rounded-[var(--radius-md)]"
                  onError={(e) => {
                    const img = e.currentTarget;
                    img.style.display = "none";
                    const fallback = img.nextElementSibling as HTMLElement | null;
                    if (fallback) fallback.style.display = "block";
                  }}
                />
              )}
              {/* QR 加载失败兜底：显示链接文本 */}
              <p
                className="hidden mt-0 p-4 text-[length:var(--text-sm)] text-[var(--fg-2)] text-center break-all"
                aria-live="polite"
              >
                {t("wechatQrFallback")}
                <br />
                <code className="font-[family-name:var(--font-mono)] text-[length:var(--text-xs)]">
                  {wechatQr.url}
                </code>
              </p>
              <p className="mt-4 text-[length:var(--text-sm)] text-[var(--fg-2)] text-center">
                {t("wechatScanHint")}
              </p>
              <div className="mt-3 flex items-center gap-2 text-[length:var(--text-xs)] text-[var(--meta)]">
                <Loader2 size={12} className="animate-spin" />
                {t("waitingPayment")}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

/**
 * 任务看板 · /w/[wid]/board
 *
 * 重构后职责：
 *  - 状态管理（tasks / view / 拖拽 / 多选 / 分页）
 *  - 数据加载 + 乐观更新
 *  - 编排子组件（BoardColumn / ListTable / ListCards / ViewToggle / BatchToolbar）
 *
 * 拆分前 751 行，拆分后主组件 ~280 行，子组件在 board-parts.tsx。
 * 共享类型/常量/工具从 lib/types、lib/task-meta、lib/format import，消除重复。
 */

import { use, useCallback, useEffect, useRef, useState } from "react";
import type { TouchEvent as ReactTouchEvent } from "react";

import { Plus, AlertCircle, CheckSquare, Loader2, ChevronDown } from "lucide-react";
import { useTranslations } from "next-intl";
import { api } from "@/lib/api";
import { track } from "@/lib/analytics";
import {
  TaskFilterBar,
  EMPTY_FILTER,
  filterToQuery,
  type TaskFilter,
} from "@/components/TaskFilterBar";
import NewTaskDialog from "@/components/NewTaskDialog";
import { ViewToggle } from "@/components/ViewToggle";
import { BatchToolbar } from "@/components/BatchToolbar";
import { MilestoneFilter } from "@/components/MilestoneFilter";
import EmptyState from "@/components/EmptyState";
import {
  BoardColumn,
  ListTable,
  ListCards,
  BoardSkeleton,
  type DragStart,
} from "@/components/board-parts";
import type { Task, Status, Priority } from "@/lib/types";
import { COLUMNS } from "@/lib/task-meta";
import type { ViewMode } from "@/components/types";

const LIST_PAGE_SIZE = 50;

export default function BoardPage({ params }: { params: Promise<{ wid: string }> }) {
  const { wid } = use(params);
  const t = useTranslations("task");
  const tErr = useTranslations("error");
  const tButton = useTranslations("button");
  const tEmpty = useTranslations("empty");
  const tStatus = useTranslations("status");

  const [tasks, setTasks] = useState<Task[]>([]);
  const [loading, setLoading] = useState(true);
  const [showNew, setShowNew] = useState(false);
  const [view, setView] = useState<ViewMode>("board");
  // 里程碑筛选：'all' | 'null' | milestoneId
  const [milestoneFilter, setMilestoneFilter] = useState<string>("all");
  // 筛选与自定义视图（阶段 2-2）
  const [taskFilter, setTaskFilter] = useState<TaskFilter>(EMPTY_FILTER);
  const [isPro, setIsPro] = useState(false);
  const [filterMembers, setFilterMembers] = useState<
    Array<{ id: string; name: string | null; email: string }>
  >([]);
  const [filterLabels, setFilterLabels] = useState<
    Array<{ id: string; name: string; color: string }>
  >([]);
  const [currentUserId, setCurrentUserId] = useState("");
  // < md 单列选择器当前选中列
  const [activeColumn, setActiveColumn] = useState<Task["status"]>("todo");
  // 拖拽视觉反馈
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [dragError, setDragError] = useState<string | null>(null);
  // 列表视图分页
  const [listPage, setListPage] = useState(1);
  // 多选模式（P2 批量操作）
  const [selectionMode, setSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [error, setError] = useState<string | null>(null);

  const dragStartRef = useRef<DragStart>(null);
  // T3.3：拖拽请求序号，防止旧请求覆盖新状态
  const dragSeqRef = useRef(0);

  // 筛选/视图辅助数据 + 当前用户（一次性拉取；members 含本人用于负责人下拉）
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const [status, members, labels, me] = await Promise.all([
          api<{ plan: string }>(`/api/v1/workspaces/${wid}/billing/status`),
          api<{ items: Array<{ id: string; name: string | null; email: string }>; total: number; hasMore: boolean }>(
            `/api/v1/workspaces/${wid}/members`,
          ),
          api<Array<{ id: string; name: string; color: string }>>(
            `/api/v1/workspaces/${wid}/labels`,
          ),
          api<{ user: { id: string } }>("/api/v1/users/me"),
        ]);
        if (cancelled) return;
        setIsPro(status.plan === "pro");
        setFilterMembers(members.items);
        setFilterLabels(labels);
        setCurrentUserId(me.user.id);
      } catch {
        // 辅助数据失败不阻断看板：筛选器降级为仅状态/负责人（plan 默认 free）
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [wid]);

  useEffect(() => {
    setLoading(true);
    // milestone 与筛选器 query 合并（两者独立语义：AND）
    const msQuery = milestoneFilter !== "all" ? `milestone=${milestoneFilter}` : "";
    const fq = filterToQuery(taskFilter);
    const query =
      msQuery || fq ? `?${[msQuery, fq.replace(/^\?/, "")].filter(Boolean).join("&")}` : "";
    api<{ items: Task[]; total: number; hasMore: boolean }>(`/api/v1/workspaces/${wid}/tasks${query}`)
      .then((data) => {
        setError(null);
        setTasks(data.items);
      })
      .catch((e) => {
        setError(
          e instanceof Error && e.message.includes("fetch")
            ? tErr("networkConnectFailed")
            : tErr("loadFailed"),
        );
        setTasks([]);
      })
      .finally(() => setLoading(false));
  }, [wid, milestoneFilter, taskFilter]);

  const load = useCallback(async () => {
    try {
      setError(null);
      const msQuery = milestoneFilter !== "all" ? `milestone=${milestoneFilter}` : "";
      const fq = filterToQuery(taskFilter);
      const query =
        msQuery || fq ? `?${[msQuery, fq.replace(/^\?/, "")].filter(Boolean).join("&")}` : "";
      const resp = await api<{ items: Task[]; total: number; hasMore: boolean }>(`/api/v1/workspaces/${wid}/tasks${query}`);
      setTasks(resp.items);
    } catch (e) {
      setError(
        e instanceof Error && e.message.includes("fetch")
          ? tErr("networkConnectFailed")
          : tErr("loadFailed"),
      );
      setTasks([]);
    }
  }, [wid, milestoneFilter, taskFilter, tErr]);

  // ─── 下拉刷新（pull-to-refresh，M3 移动端手势交互） ─────────
  // 触摸事件 + translateY 阈值判断，不依赖外部库。
  // 仅在页面滚动到顶部（window.scrollY <= 0）时触发，避免与内容滚动冲突。
  // 阻尼 0.5：下拉 140px 实际显示 70px，上限 100px，超过 70px 阈值触发刷新。
  const PULL_THRESHOLD = 70;
  const PULL_MAX = 100;
  const PULL_DAMPING = 0.5;
  // pullDistance / isRefreshing 需触发渲染；isPulling 用 ref 避免无谓重渲染
  const [pullDistance, setPullDistance] = useState(0);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const isPullingRef = useRef(false);
  const isRefreshingRef = useRef(false);
  const touchStartYRef = useRef(0);
  const pullDistanceRef = useRef(0);

  const handlePullStart = useCallback((e: ReactTouchEvent) => {
    if (isRefreshingRef.current) return;
    // 仅在页面顶部触发下拉刷新
    if (window.scrollY <= 0) {
      touchStartYRef.current = e.touches[0].clientY;
      isPullingRef.current = true;
    }
  }, []);

  const handlePullMove = useCallback((e: ReactTouchEvent) => {
    if (!isPullingRef.current || isRefreshingRef.current) return;
    const pull = e.touches[0].clientY - touchStartYRef.current;
    if (pull > 0) {
      // 阻尼：下拉距离 * 0.5，上限 100px
      const dist = Math.min(pull * PULL_DAMPING, PULL_MAX);
      pullDistanceRef.current = dist;
      setPullDistance(dist);
    }
  }, []);

  const handlePullEnd = useCallback(() => {
    if (!isPullingRef.current) return;
    isPullingRef.current = false;
    if (pullDistanceRef.current >= PULL_THRESHOLD) {
      // 超过阈值：触发刷新，保持 50px 高度显示 spinner
      isRefreshingRef.current = true;
      setIsRefreshing(true);
      pullDistanceRef.current = 50;
      setPullDistance(50);
      load().finally(() => {
        isRefreshingRef.current = false;
        setIsRefreshing(false);
        pullDistanceRef.current = 0;
        setPullDistance(0);
      });
    } else {
      // 未超阈值：回弹归零
      pullDistanceRef.current = 0;
      setPullDistance(0);
    }
  }, [load]);

  // ─── 拖拽排序 ───────────────────────────────────────────

  function computeSortOrder(
    tasks: Task[],
    column: Status,
    targetIndex: number,
    excludeId: string,
  ): number {
    const columnTasks = tasks
      .filter((t) => t.status === column && t.id !== excludeId)
      .sort((a, b) => (a.sortOrder ?? 0) - (b.sortOrder ?? 0));
    if (columnTasks.length === 0) return 0;
    if (targetIndex <= 0) return (columnTasks[0].sortOrder ?? 0) - 1;
    if (targetIndex >= columnTasks.length) {
      return (columnTasks[columnTasks.length - 1].sortOrder ?? 0) + 1;
    }
    const prev = columnTasks[targetIndex - 1];
    const next = columnTasks[targetIndex];
    return ((prev.sortOrder ?? 0) + (next.sortOrder ?? 0)) / 2;
  }

  const handleReorder = useCallback(
    async (taskId: string, targetIndex: number, column: Status) => {
      if (!tasks.some((t) => t.id === taskId)) return;
      const newSortOrder = computeSortOrder(tasks, column, targetIndex, taskId);
      const seq = ++dragSeqRef.current;
      setTasks((prev) =>
        prev.map((t) => (t.id === taskId ? { ...t, status: column, sortOrder: newSortOrder } : t)),
      );
      try {
        await api(`/api/v1/workspaces/${wid}/tasks/${taskId}`, {
          method: "PATCH",
          body: JSON.stringify({ status: column, sortOrder: newSortOrder }),
        });
      } catch {
        // 仅当没有更新的拖拽操作时才回滚
        if (seq === dragSeqRef.current) {
          setDragError(t("dragFailed"));
          await load();
          setTimeout(() => setDragError(null), 5000);
        }
      }
    },
    [tasks, wid, t, load],
  );

  const moveTaskByStep = useCallback(
    async (taskId: string, delta: -1 | 1) => {
      const task = tasks.find((t) => t.id === taskId);
      if (!task) return;
      const columnTasks = tasks
        .filter((t) => t.status === task.status)
        .sort((a, b) => (a.sortOrder ?? 0) - (b.sortOrder ?? 0));
      const currentIndex = columnTasks.findIndex((t) => t.id === taskId);
      if (currentIndex < 0) return;
      const targetIndex = currentIndex + delta;
      if (targetIndex < 0 || targetIndex >= columnTasks.length) return;
      await handleReorder(taskId, targetIndex, task.status);
    },
    [tasks, handleReorder],
  );

  const handleDropOnTask = useCallback(
    async (sourceTaskId: string, targetTaskId: string) => {
      if (sourceTaskId === targetTaskId) return;
      const target = tasks.find((t) => t.id === targetTaskId);
      if (!target) return;
      const column = target.status;
      const columnTasksExcl = tasks
        .filter((t) => t.status === column && t.id !== sourceTaskId)
        .sort((a, b) => (a.sortOrder ?? 0) - (b.sortOrder ?? 0));
      const targetIndex = columnTasksExcl.findIndex((t) => t.id === targetTaskId);
      if (targetIndex < 0) return;
      await handleReorder(sourceTaskId, targetIndex, column);
    },
    [tasks, handleReorder],
  );

  const handleDropOnColumn = useCallback(
    async (sourceTaskId: string, targetStatus: Status) => {
      if (!tasks.some((t) => t.id === sourceTaskId)) return;
      const columnTasksExcl = tasks
        .filter((t) => t.status === targetStatus && t.id !== sourceTaskId)
        .sort((a, b) => (a.sortOrder ?? 0) - (b.sortOrder ?? 0));
      await handleReorder(sourceTaskId, columnTasksExcl.length, targetStatus);
    },
    [tasks, handleReorder],
  );

  // ─── 多选 + 批量操作（P2） ───────────────────────────────

  const toggleSelect = useCallback((id: string) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  function clearSelection() {
    setSelectedIds(new Set());
    setSelectionMode(false);
  }

  async function handleBatchUpdate(patch: { status?: Status; priority?: Priority }) {
    const ids = Array.from(selectedIds);
    const resp = await api<{ updated: number; skipped: number }>(
      `/api/v1/workspaces/${wid}/tasks/batch`,
      {
        method: "POST",
        body: JSON.stringify({ ids, action: "update", ...patch }),
      },
    );
    track("task_status_change", { batch: true, count: resp.updated, ...patch });
    await load();
    clearSelection();
    return resp;
  }

  async function handleBatchDelete() {
    const ids = Array.from(selectedIds);
    const resp = await api<{ deleted: number; skipped: number }>(
      `/api/v1/workspaces/${wid}/tasks/batch`,
      {
        method: "POST",
        body: JSON.stringify({ ids, action: "delete" }),
      },
    );
    await load();
    clearSelection();
    return resp;
  }

  // ─── 列表视图排序 + 分页 ─────────────────────────────────

  const sortedListTasks = tasks.slice().sort((a, b) => {
    const sa = COLUMNS.findIndex((c) => c.id === a.status);
    const sb = COLUMNS.findIndex((c) => c.id === b.status);
    if (sa !== sb) return sa - sb;
    return (a.sortOrder ?? 0) - (b.sortOrder ?? 0);
  });

  const listTotalPages = Math.max(1, Math.ceil(sortedListTasks.length / LIST_PAGE_SIZE));
  const safeListPage = Math.min(listPage, listTotalPages);
  const paginatedListTasks = sortedListTasks.slice(
    (safeListPage - 1) * LIST_PAGE_SIZE,
    safeListPage * LIST_PAGE_SIZE,
  );
  const showListPagination = sortedListTasks.length > LIST_PAGE_SIZE;

  // ─── 渲染 ───────────────────────────────────────────────

  return (
    <>
      {dragError && (
        <div
          role="alert"
          aria-live="assertive"
          className="mb-[var(--space-4)] flex items-center gap-[var(--space-2)] px-[var(--space-4)] py-2.5 rounded-[var(--radius-md)] border bg-[color-mix(in_srgb,var(--danger)_10%,transparent)] border-[color-mix(in_srgb,var(--danger)_30%,transparent)] text-[var(--danger)]"
        >
          <AlertCircle size={16} className="shrink-0" />
          <span className="text-[length:var(--text-sm)] font-[weight:var(--weight-medium)]">{dragError}</span>
        </div>
      )}

      {error && (
        <div
          className="mb-[var(--space-4)] rounded-[var(--radius-md)] p-3 text-[length:var(--text-sm)] flex items-center justify-between bg-[color-mix(in_srgb,var(--danger)_10%,transparent)] border border-[color-mix(in_srgb,var(--danger)_30%,transparent)] text-[var(--danger)]"
        >
          <span>{error}</span>
          <button
            onClick={() => {
              setError(null);
              load();
            }}
            className="underline hover:opacity-80 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 text-[var(--danger)]"
          >
            {tButton("retry")}
          </button>
        </div>
      )}

      {loading ? (
        <BoardSkeleton />
      ) : tasks.length === 0 ? (
        <EmptyState
          type="inbox"
          title={tEmpty("noTasks")}
          description={tEmpty("noTasksHint")}
          action={{ label: tStatus("newTask"), onClick: () => setShowNew(true) }}
        />
      ) : (
        <div
          onTouchStart={handlePullStart}
          onTouchMove={handlePullMove}
          onTouchEnd={handlePullEnd}
        >
          {/* 下拉刷新指示器（M3 移动端手势）：高度随下拉距离变化，超过阈值显示 spinner */}
          <div
            className="flex items-center justify-center overflow-hidden transition-[height] duration-[var(--motion-base)]"
            style={{ height: pullDistance }}
            aria-hidden={pullDistance === 0}
          >
            {isRefreshing ? (
              <Loader2 size={20} className="animate-spin text-[var(--accent)]" />
            ) : pullDistance > 0 ? (
              <ChevronDown
                size={20}
                className={`text-[var(--muted)] transition-transform duration-[var(--motion-fast)] ${pullDistance >= 70 ? "rotate-180" : ""}`}
              />
            ) : null}
          </div>
          {/* 标题行 + 操作 */}
          <div className="flex items-center justify-between mb-[var(--space-6)] gap-[var(--space-3)] flex-wrap">
            <div>
              <h1 className="text-[length:var(--text-2xl)] font-[weight:var(--weight-semibold)] text-[var(--fg)] mb-[var(--space-1)]">
                {t("boardTitle")}
              </h1>
              <p className="text-[var(--muted)] text-[length:var(--text-sm)]">
                {tasks.length} {t("countUnit")}
                {selectionMode && ` · ${t("selected", { count: selectedIds.size })}`}
              </p>
            </div>
            <div className="flex items-center gap-[var(--space-3)] flex-wrap">
              <MilestoneFilter wid={wid} value={milestoneFilter} onChange={setMilestoneFilter} />
              <ViewToggle view={view} onChange={setView} />
              {/* 多选切换按钮 */}
              <button
                onClick={() => {
                  setSelectionMode((v) => !v);
                  if (selectionMode) setSelectedIds(new Set());
                }}
                aria-pressed={selectionMode}
                className={`flex items-center gap-1.5 px-3 py-[var(--space-2)] min-h-[44px] md:min-h-0 rounded-[var(--radius-md)] text-[length:var(--text-sm)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 ${
                  selectionMode
                    ? "bg-[var(--accent-soft)] text-[var(--accent)]"
                    : "bg-[var(--surface-2)] text-[var(--muted)] hover:text-[var(--fg)]"
                }`}
                aria-label={t("multiSelect")}
              >
                <CheckSquare size={16} />
                <span className="hidden sm:inline">{t("multiSelect")}</span>
              </button>
              <button
                onClick={() => setShowNew(true)}
                className="flex items-center gap-[var(--space-2)] px-[var(--space-4)] py-[var(--space-2)] min-h-[44px] md:min-h-0 bg-[var(--accent)] text-[var(--accent-fg)] rounded-[var(--radius-md)] hover:bg-[var(--accent-hover)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
              >
                <Plus size={16} />
                {t("create")}
              </button>
            </div>
          </div>

          {/* 筛选与自定义视图（阶段 2-2：Pro 卖点兑现） */}
          <TaskFilterBar
            value={taskFilter}
            onChange={(f) => setTaskFilter(f)}
            isPro={isPro}
            members={filterMembers}
            labels={filterLabels}
            userId={currentUserId}
            wid={wid}
          />

          {view === "board" ? (
            <BoardView
              wid={wid}
              tasks={tasks}
              activeColumn={activeColumn}
              setActiveColumn={setActiveColumn}
              draggingId={draggingId}
              setDraggingId={setDraggingId}
              dragStartRef={dragStartRef}
              selectedIds={selectedIds}
              selectionMode={selectionMode}
              onToggleSelect={toggleSelect}

              onDropOnTask={handleDropOnTask}
              onDropOnColumn={handleDropOnColumn}
              onMoveByStep={moveTaskByStep}
            />
          ) : (
            <ListView
              wid={wid}
              paginatedTasks={paginatedListTasks}
              selectedIds={selectedIds}
              selectionMode={selectionMode}
              onToggleSelect={toggleSelect}
              showListPagination={showListPagination}
              safeListPage={safeListPage}
              listTotalPages={listTotalPages}
              onPrevPage={() => setListPage((p) => Math.max(1, p - 1))}
              onNextPage={() => setListPage((p) => Math.min(listTotalPages, p + 1))}
            />
          )}
        </div>
      )}

      <NewTaskDialog wid={wid} open={showNew} onClose={() => setShowNew(false)} onCreated={load} />

      {/* P2 批量操作工具栏 */}
      <BatchToolbar
        selectedIds={Array.from(selectedIds)}
        onClear={clearSelection}
        onUpdate={handleBatchUpdate}
        onDelete={handleBatchDelete}
      />
    </>
  );
}

