"use client";

/**
 * 决策记录页 · /w/[wid]/decisions
 *
 * 时间线列表展示工作区内全部任务的决策记录：
 *  - 顶部搜索栏：按 markdown 内容关键词检索，debounce 300ms
 *  - 时间线卡片：左侧圆点 + 竖线连接，按 createdAt 降序
 *  - 卡片含关联任务标题（可跳转）、版本 badge、内容摘要、作者与时间
 *  - 底部"加载更多"分页，每次 20 条
 *
 * 设计参考概览页（max-w 容器、surface 卡片、Skeleton 占位）与
 * 任务详情页的决策卡片（版本 badge、相对时间）。
 * 所有色值走 var(--token)，间距/字号/圆角走 token，图标仅用 lucide-react。
 */

import { use, useCallback, useEffect, useRef, useState } from "react";
import { Link } from "@/lib/i18n-navigation";
import { Search, Loader2, ChevronRight, X, Sparkles, ClipboardCopy, ListChecks } from "lucide-react";
import { api } from "@/lib/api";
import { Skeleton } from "@/components/Skeleton";
import { useToast } from "@/components/Toast";
import EmptyState from "@/components/EmptyState";
import { useTranslations } from "next-intl";
import { relativeTime as sharedRelativeTime } from "@/lib/format";

interface Decision {
  id: string;
  taskId: string;
  taskTitle: string;
  markdown: string;
  version: number;
  authorId: string | null;
  authorName: string;
  createdAt: string;
  updatedAt: string;
  /**
   * 执行进度（F1 决策驱动执行）：
   *  - actionItemCount：行动项总数（null=后端尚未返回，前端不显示进度列）
   *  - actionItemCompleted：已完成行动项数
   * 由决策列表 API 内嵌（可选）；缺失时不渲染进度列，保持向后兼容。
   */
  actionItemCount?: number | null;
  actionItemCompleted?: number | null;
}

interface DecisionsResp {
  items: Decision[];
  page: number;
  limit: number;
  total: number;
  hasMore: boolean;
}

const PAGE_SIZE = 20;
const SUMMARY_LIMIT = 200;
const DEBOUNCE_MS = 300;

// 相对时间戳：走共享 format.ts（阶段 2-6 i18n——经 useTranslations("time") 输出当前语言）

/**
 * 将 markdown 转为纯文本并截取前 N 字符作为摘要。
 * 仅做轻量剥离（标题符号、强调、链接、代码、列表标记、HTML），
 * 不引入 markdown 解析依赖；摘要仅用于列表预览，完整内容在任务详情查看。
 */
function markdownToPlainText(md: string, limit = SUMMARY_LIMIT): string {
  const text = md
    // 去除标题井号
    .replace(/^#{1,6}\s+/gm, "")
    // 去除强调/加粗/斜体
    .replace(/(\*{1,3}|_{1,3})(.+?)\1/g, "$2")
    // 去除行内代码反引号
    .replace(/`([^`]+)`/g, "$1")
    // 去除图片
    .replace(/!\[([^\]]*)\]\([^)]+\)/g, "$1")
    // 链接保留文本
    .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
    // 去除无序列表标记
    .replace(/^\s*[-*+]\s+/gm, "")
    // 去除有序列表标记
    .replace(/^\s*\d+\.\s+/gm, "")
    // 去除引用块 >
    .replace(/^\s*>\s?/gm, "")
    // 去除水平分隔线
    .replace(/^---+\s*$/gm, "")
    // 去除 HTML 标签
    .replace(/<[^>]+>/g, "")
    // 折叠多余空白
    .replace(/\n{2,}/g, "\n")
    .trim();
  return text.length > limit ? `${text.slice(0, limit)}…` : text;
}

export default function DecisionsPage({ params }: { params: Promise<{ wid: string }> }) {
  const { wid } = use(params);

  const t = useTranslations("decisions");
  const tTime = useTranslations("time");
  const tEmpty = useTranslations("empty");
  const { toast } = useToast();
  const relativeTime = (iso?: string) => sharedRelativeTime(iso, tTime);
  const [decisions, setDecisions] = useState<Decision[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [error, setError] = useState("");

  // 搜索：inputValue 即时跟随输入，query 为 debounce 后下发 API 的值
  const [inputValue, setInputValue] = useState("");
  const [query, setQuery] = useState("");
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // 页码（从 1 开始），搜索条件变化时重置
  const pageRef = useRef(1);
  // T3.2：AbortController 用于取消上一次未完成的搜索请求
  const abortRef = useRef<AbortController | null>(null);

  const base = `/api/v1/workspaces/${wid}/decisions`;

  // AI 提炼对话框状态
  const [aiOpen, setAiOpen] = useState(false);
  const [aiSource, setAiSource] = useState("");
  const [aiBusy, setAiBusy] = useState(false);
  const [aiResult, setAiResult] = useState<{ title: string; markdown: string } | null>(null);
  const [aiErr, setAiErr] = useState("");

  async function handleExtract() {
    if (aiBusy) return;
    if (aiSource.trim().length < 10) {
      setAiErr(t("aiSourceTooShort"));
      return;
    }
    setAiBusy(true);
    setAiErr("");
    setAiResult(null);
    try {
      const j = await api<{ title: string; markdown: string }>(`${base}/extract`, {
        method: "POST",
        body: JSON.stringify({ sourceText: aiSource }),
      });
      setAiResult(j);
    } catch (e) {
      setAiErr(e instanceof Error ? e.message : t("aiFailed"));
    } finally {
      setAiBusy(false);
    }
  }

  async function copyAiMarkdown() {
    if (!aiResult) return;
    try {
      await navigator.clipboard.writeText(aiResult.markdown);
      toast("success", t("aiCopySuccess"));
    } catch {
      toast("error", t("aiCopyFailed"));
    }
  }

  function closeAi() {
    if (aiBusy) return;
    setAiOpen(false);
    setAiSource("");
    setAiResult(null);
    setAiErr("");
  }

  /**
   * 拉取决策列表。
   * @param q    搜索关键词
   * @param page 页码
   * @param append true=追加（加载更多），false=覆盖（首次/搜索）
   */
  const fetchDecisions = useCallback(
    async (q: string, page: number, append: boolean) => {
      if (!append) setLoading(true);
      else setLoadingMore(true);
      setError("");
      // 取消上一次未完成的请求
      abortRef.current?.abort();
      const controller = new AbortController();
      abortRef.current = controller;
      try {
        const params = new URLSearchParams({
          page: String(page),
          limit: String(PAGE_SIZE),
        });
        if (q.trim()) params.set("q", q.trim());
        const resp = await api<DecisionsResp>(`${base}?${params.toString()}`, {
          signal: controller.signal,
        });
        setTotal(resp.total);
        setDecisions((prev) => (append ? [...prev, ...resp.items] : resp.items));
      } catch (e) {
        setError(e instanceof Error ? e.message : t("loadFailed"));
        if (!append) setDecisions([]);
      } finally {
        setLoading(false);
        setLoadingMore(false);
      }
    },
    [base],
  );

  // 首次加载
  useEffect(() => {
    fetchDecisions("", 1, false);
  }, [fetchDecisions]);

  /**
   * 搜索输入 debounce 300ms：
   * 输入变化时清除上一次定时器，300ms 后才更新 query 并重置页码、重新拉取。
   */
  function handleSearchChange(value: string) {
    setInputValue(value);
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      pageRef.current = 1;
      setQuery(value);
      fetchDecisions(value, 1, false);
    }, DEBOUNCE_MS);
  }

  // 卸载时清掉定时器和未完成请求，避免 setState on unmounted
  useEffect(() => {
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
      abortRef.current?.abort();
    };
  }, []);

  /** 加载更多：页码 +1，追加拉取 */
  function handleLoadMore() {
    if (loadingMore) return;
    const next = pageRef.current + 1;
    pageRef.current = next;
    fetchDecisions(query, next, true);
  }

  /** 清空搜索 */
  function handleClearSearch() {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    setInputValue("");
    setQuery("");
    pageRef.current = 1;
    fetchDecisions("", 1, false);
  }

  const hasMore = decisions.length < total;
  const isSearching = query.trim().length > 0;
  const isEmpty = !loading && decisions.length === 0;

  return (
    <div className="max-w-[var(--container-max)] mx-auto">
      {/* ── 标题栏 ── */}
      <div className="mb-[var(--space-6)] flex flex-col sm:flex-row sm:items-start sm:justify-between gap-[var(--space-3)]">
        <div className="min-w-0">
          <h1 className="text-[length:var(--text-2xl)] font-[weight:var(--weight-semibold)] text-[var(--fg)] tracking-[var(--tracking-tight)]">
            {t("title")}
          </h1>
          <p className="mt-[var(--space-1)] text-[length:var(--text-sm)] text-[var(--muted)]">
            {loading ? t("loading") : t("count", { count: total })}
          </p>
        </div>
        <button
          onClick={() => setAiOpen(true)}
          className="inline-flex items-center gap-1.5 h-9 px-[var(--space-3)] rounded-[var(--radius-md)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] transition-colors duration-[var(--motion-fast)] shrink-0 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
        >
          <Sparkles size={14} />
          {t("aiExtract")}
        </button>
      </div>

      {/* ── 搜索栏 ── */}
      <div className="mb-[var(--space-5)]">
        <div className="relative">
          <Search
            size={15}
            className="absolute left-[var(--space-3)] top-1/2 -translate-y-1/2 text-[var(--meta)] pointer-events-none"
          />
          <input
            type="text"
            value={inputValue}
            onChange={(e) => handleSearchChange(e.target.value)}
            placeholder={t("searchPlaceholder")}
            aria-label={t("searchAria")}
            className="w-full h-10 pl-9 pr-9 bg-[var(--surface)] border border-[var(--border)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] text-[var(--fg)] placeholder:text-[var(--meta)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:border-[var(--accent)] transition-colors duration-[var(--motion-fast)]"
          />
          {inputValue && (
            <button
              type="button"
              onClick={handleClearSearch}
              aria-label={t("clearSearch")}
              className="absolute right-[var(--space-2)] top-1/2 -translate-y-1/2 inline-flex items-center justify-center w-[var(--icon-lg)] h-[var(--icon-lg)] rounded-[var(--radius-sm)] text-[var(--meta)] hover:bg-[var(--surface-2)] hover:text-[var(--fg-2)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
            >
              <X size={14} />
            </button>
          )}
        </div>
        {/* 结果计数：搜索时显示，避免与标题栏 total 重复 */}
        {isSearching && !loading && (
          <p className="mt-[var(--space-2)] text-[length:var(--text-xs)] text-[var(--meta)]">
            {t("matchCount", { matched: decisions.length, total })}
          </p>
        )}
      </div>

      {/* ── 错误提示 ── */}
      {error && (
        <div className="mb-[var(--space-4)] px-[var(--space-4)] py-[var(--space-3)] rounded-[var(--radius-md)] bg-[var(--danger-soft)] text-[var(--danger-fg)] text-[length:var(--text-sm)]">
          {error}
        </div>
      )}

      {/* ── 内容区 ── */}
      {loading ? (
        <DecisionsSkeleton count={4} />
      ) : isEmpty ? (
        isSearching ? (
          <EmptyState
            type="search"
            title={t("noResultsMatch")}
            description={t("tryDifferentKeyword")}
          />
        ) : (
          <EmptyState
            type="folder"
            title={tEmpty("noDecisions")}
            description={tEmpty("noDecisionsHint")}
          />
        )
      ) : (
        <>
          <ol className="relative">
            {decisions.map((d, i) => {
              const isLast = i === decisions.length - 1;
              const summary = markdownToPlainText(d.markdown);
              const createdRel = relativeTime(d.createdAt);
              const updatedRel = relativeTime(d.updatedAt);
              const isUpdated =
                d.updatedAt &&
                d.createdAt &&
                new Date(d.updatedAt).getTime() > new Date(d.createdAt).getTime();
              return (
                <li key={d.id} className="relative pl-[var(--space-4)] sm:pl-[var(--space-8)]">
                  {/* 时间线竖线：非末项时显示，连接到下一项节点 */}
                  {!isLast && (
                    <span
                      aria-hidden
                      className="absolute left-[7px] top-[18px] bottom-0 w-px bg-[var(--border)]"
                    />
                  )}
                  {/* 时间线圆点节点 */}
                  <span
                    aria-hidden
                    className="absolute left-0 top-[10px] w-[15px] h-[15px] rounded-full border-2 border-[var(--accent)] bg-[var(--surface)]"
                  />

                  <article className="mb-[var(--space-4)] bg-[var(--surface)] border border-[var(--border)] rounded-[var(--radius-lg)] shadow-[var(--elev-sm)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] overflow-hidden">
                    {/* 顶部：关联任务标题 + 版本 badge */}
                    <header className="flex items-center gap-[var(--space-2)] px-[var(--space-4)] py-[var(--space-2)] border-b border-[var(--border-soft)]">
                      <Link
                        href={`/w/${wid}/task/${d.taskId}`}
                        className="flex items-center gap-[var(--space-1)] min-w-0 flex-1 text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg)] hover:text-[var(--accent)] transition-colors duration-[var(--motion-fast)]"
                      >
                        <span className="truncate">{d.taskTitle || t("unnamedTask")}</span>
                        <ChevronRight size={13} className="shrink-0 text-[var(--meta)]" />
                      </Link>
                      <span className="shrink-0 px-[var(--space-1)] py-0.5 rounded-[var(--radius-sm)] bg-[var(--surface-2)] border border-[var(--border)] text-[length:var(--text-xs)] font-[family-name:var(--font-mono)] text-[var(--fg-2)]">
                        v{d.version}
                      </span>
                    </header>

                    {/* 中间：markdown 内容摘要（纯文本，截取 200 字符） */}
                    <div className="px-[var(--space-4)] py-[var(--space-3)] text-[length:var(--text-sm)] text-[var(--fg-2)] leading-[var(--leading-relaxed)]">
                      {summary ? (
                        <p className="whitespace-pre-wrap break-words">{summary}</p>
                      ) : (
                        <span className="text-[var(--meta)]">{t("noContent")}</span>
                      )}
                    </div>

                    {/* 底部：作者 + 创建时间 + 更新时间 + 执行进度 */}
                    <footer className="flex items-center gap-[var(--space-2)] px-[var(--space-4)] py-[var(--space-2)] border-t border-[var(--border-soft)] text-[length:var(--text-xs)] text-[var(--meta)]">
                      <span className="truncate">{d.authorName || t("unknownAuthor")}</span>
                      {createdRel && (
                        <>
                          <span className="shrink-0">·</span>
                          <span className="shrink-0 tabular-nums">{createdRel}</span>
                        </>
                      )}
                      {isUpdated && updatedRel && (
                        <>
                          <span className="shrink-0">·</span>
                          <span className="shrink-0 tabular-nums">
                            {t("updatedAtRel", { time: updatedRel })}
                          </span>
                        </>
                      )}
                      {/* F1 执行进度列：仅当后端返回 actionItemCount 时渲染 */}
                      {typeof d.actionItemCount === "number" && d.actionItemCount > 0 && (
                        <>
                          <span className="shrink-0">·</span>
                          <span className="shrink-0 inline-flex items-center gap-[var(--space-1)] tabular-nums">
                            <ListChecks size={11} className="text-[var(--muted)]" />
                            {/* 迷你进度条：宽度按完成率填充 */}
                            <span className="inline-flex items-center gap-[var(--space-1)]">
                              <span className="relative inline-block w-10 h-1.5 rounded-full bg-[var(--surface-3)] overflow-hidden">
                                <span
                                  className="absolute inset-y-0 left-0 rounded-full transition-[width] duration-[var(--motion-base)]"
                                  style={{
                                    width: `${Math.round(
                                      ((d.actionItemCompleted ?? 0) / (d.actionItemCount ?? 1)) * 100,
                                    )}%`,
                                    background:
                                      (d.actionItemCompleted ?? 0) >= (d.actionItemCount ?? 0)
                                        ? "var(--success)"
                                        : "var(--accent)",
                                  }}
                                />
                              </span>
                              <span>
                                {d.actionItemCompleted ?? 0}/{d.actionItemCount}
                              </span>
                            </span>
                          </span>
                        </>
                      )}
                    </footer>
                  </article>
                </li>
              );
            })}
          </ol>

          {/* ── 加载更多 ── */}
          {hasMore && (
            <div className="flex justify-center pt-[var(--space-2)]">
              <button
                onClick={handleLoadMore}
                disabled={loadingMore}
                className="inline-flex items-center gap-[var(--space-2)] h-9 px-[var(--space-5)] bg-[var(--surface)] border border-[var(--border)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] hover:border-[var(--muted)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
              >
                {loadingMore ? (
                  <>
                    <Loader2 size={14} className="animate-spin" />
                    {t("loadingMore")}
                  </>
                ) : (
                  <>{t("loadMore")}</>
                )}
              </button>
            </div>
          )}
        </>
      )}

      {/* AI 提炼对话框：粘贴原始讨论 → 生成 markdown 草稿 → 复制后到任务详情粘贴 */}
      {aiOpen && (
        <div
          className="fixed inset-0 z-[var(--z-modal)] flex items-center justify-center bg-[var(--overlay)] px-[var(--space-4)]"
          role="dialog"
          aria-modal="true"
          aria-label={t("aiDialogTitle")}
          onClick={(e) => {
            if (e.target === e.currentTarget) closeAi();
          }}
        >
          <div className="w-full max-w-2xl bg-[var(--surface)] border border-[var(--border)] rounded-[var(--radius-lg)] shadow-[var(--elev-lg)] overflow-hidden max-h-[85dvh] flex flex-col">
            <div className="px-[var(--space-4)] py-[var(--space-3)] border-b border-[var(--border-soft)] flex items-center justify-between">
              <h2 className="text-[length:var(--text-md)] font-[weight:var(--weight-semibold)] text-[var(--fg)] flex items-center gap-[var(--space-2)]">
                <Sparkles size={16} className="text-[var(--accent)]" />
                {t("aiDialogTitle")}
              </h2>
              <button
                onClick={closeAi}
                aria-label={t("aiClose")}
                className="p-[var(--space-1)] rounded-[var(--radius-sm)] text-[var(--muted)] hover:bg-[var(--surface-2)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
              >
                <X size={16} />
              </button>
            </div>
            <div className="px-[var(--space-4)] py-[var(--space-3)] overflow-y-auto flex-1">
              <label className="block text-[length:var(--text-xs)] text-[var(--muted)] mb-[var(--space-1)]">
                {t("aiSourceLabel")}
              </label>
              <textarea
                value={aiSource}
                onChange={(e) => setAiSource(e.target.value)}
                placeholder={t("aiSourcePlaceholder")}
                rows={8}
                className="w-full px-[var(--space-3)] py-[var(--space-2)] border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[var(--fg)] text-[length:var(--text-sm)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] placeholder:text-[var(--meta)] resize-y font-[family-name:var(--font-mono)]"
              />
              {aiErr && (
                <p className="mt-[var(--space-2)] text-[length:var(--text-xs)] text-[var(--danger-fg)]">{aiErr}</p>
              )}
              {aiResult && (
                <div className="mt-[var(--space-4)] border border-[var(--border)] rounded-[var(--radius-md)] overflow-hidden">
                  <div className="px-[var(--space-3)] py-[var(--space-2)] bg-[var(--surface-2)] flex items-center justify-between gap-[var(--space-2)]">
                    <span className="text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] truncate">
                      {aiResult.title}
                    </span>
                    <button
                      onClick={copyAiMarkdown}
                      className="inline-flex items-center gap-[var(--space-1)] px-[var(--space-2)] h-7 text-[length:var(--text-xs)] text-[var(--fg-2)] rounded-[var(--radius-sm)] border border-[var(--border)] hover:bg-[var(--surface)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
                    >
                      <ClipboardCopy size={12} />
                      {t("aiCopy")}
                    </button>
                  </div>
                  <pre className="px-[var(--space-3)] py-[var(--space-2)] text-[length:var(--text-xs)] text-[var(--fg-2)] overflow-x-auto whitespace-pre-wrap break-words">
                    {aiResult.markdown}
                  </pre>
                </div>
              )}
            </div>
            <div className="px-[var(--space-4)] py-[var(--space-3)] border-t border-[var(--border-soft)] flex items-center justify-end gap-[var(--space-2)]">
              <button
                onClick={closeAi}
                className="h-9 px-[var(--space-3)] text-[length:var(--text-sm)] text-[var(--fg-2)] rounded-[var(--radius-md)] hover:bg-[var(--surface-2)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
              >
                {t("aiClose")}
              </button>
              <button
                onClick={handleExtract}
                disabled={aiBusy || aiSource.trim().length < 10}
                className="inline-flex items-center gap-1.5 h-9 px-[var(--space-4)] bg-[var(--accent)] text-[var(--accent-fg)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] disabled:opacity-50 disabled:cursor-not-allowed focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
              >
                {aiBusy && <Loader2 size={14} className="animate-spin" />}
                {aiResult ? t("aiReGenerate") : t("aiGenerate")}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * 决策列表 Skeleton：与时间线卡片尺寸对齐。
 * 渲染 count 条骨架，每条含节点占位 + 卡片（标题行 + 摘要 2 行 + 底部行）。
 */
function DecisionsSkeleton({ count = 4 }: { count?: number }) {
  return (
    <div aria-busy="true" className="relative">
      {Array.from({ length: count }).map((_, i) => (
        <div key={i} className="relative pl-[var(--space-4)] sm:pl-[var(--space-8)]">
          {/* 竖线 */}
          {i < count - 1 && (
            <span
              aria-hidden
              className="absolute left-[7px] top-[18px] bottom-0 w-px bg-[var(--border)]"
            />
          )}
          {/* 圆点 */}
          <Skeleton className="absolute left-0 top-[10px] w-[15px] h-[15px] rounded-full" />
          <div className="mb-[var(--space-4)] bg-[var(--surface)] border border-[var(--border)] rounded-[var(--radius-lg)] shadow-[var(--elev-sm)] overflow-hidden">
            {/* 标题行 */}
            <div className="flex items-center gap-[var(--space-2)] px-[var(--space-4)] py-[var(--space-2)] border-b border-[var(--border-soft)]">
              <Skeleton
                className="flex-1 h-[14px]"
                style={{ maxWidth: `${55 + ((i * 23) % 30)}%` }}
              />
              <Skeleton className="shrink-0 w-8 h-[18px] rounded-[var(--radius-sm)]" />
            </div>
            {/* 摘要占位 2 行 */}
            <div className="px-[var(--space-4)] py-[var(--space-3)] space-y-[var(--space-2)]">
              <Skeleton className="w-full h-[12px]" />
              <Skeleton className="w-3/4 h-[12px]" />
            </div>
            {/* 底部行 */}
            <div className="flex items-center gap-[var(--space-2)] px-[var(--space-4)] py-[var(--space-2)] border-t border-[var(--border-soft)]">
              <Skeleton className="w-16 h-[11px]" />
              <Skeleton className="w-20 h-[11px]" />
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

/**
 * 空状态已统一使用 @/components/EmptyState（6 种 SVG 插画）。
 * 搜索无结果 → type="search"；工作区无决策 → type="folder"。
 */

"use client";

import { use, useCallback, useEffect, useState, type ReactNode } from "react";
import { Link } from "@/lib/i18n-navigation";
import { ClipboardList, ChevronDown, SearchX } from "lucide-react";
import { api } from "@/lib/api";
import { Skeleton } from "@/components/Skeleton";
import EmptyStateBase from "@/components/EmptyState";
import { AnimatedList, AnimatedItem } from "@/components/AnimatedList";
import { VirtualList } from "@/components/VirtualList";
import { useTranslations } from "next-intl";

/** 任务列表虚拟化阈值：超过此数量启用 VirtualList，否则保持 AnimatedList 原渲染 */
const TASKS_VIRTUAL_THRESHOLD = 50;

interface Task {
  id: string;
  title: string;
  status: "todo" | "in_progress" | "review" | "done";
  priority: "low" | "medium" | "high" | "urgent";
  dueDate?: string;
  sortOrder?: number;
  createdAt: string;
  updatedAt: string;
}

type StatusFilter = "all" | Task["status"];
type SortKey = "recent" | "due" | "priority";

// 状态分组/筛选项/标签/徽章/色条/排序：走共享 lib/task-meta（单一编辑源，消除跨页色值漂移）
import {
  STATUS_FILTERS,
  STATUS_LABEL_KEYS,
  STATUS_BADGE_STYLES,
  PRIORITY_BAR_COLORS,
  PRIORITY_ORDER,
  COLUMNS as STATUS_GROUPS,
} from "@/lib/task-meta";

// formatRelativeDueDate：走共享 lib/format.ts（tTime 注入渲染当前语言）
import { formatRelativeDueDate as sharedFormatRelativeDueDate } from "@/lib/format";

/**
 * 分组内排序：
 * - recent：按 updatedAt 倒序（默认）
 * - due：按截止日期升序，无截止日期排最后
 * - priority：urgent > high > medium > low
 */
function sortTasks(tasks: Task[], sortKey: SortKey): Task[] {
  const arr = tasks.slice();
  if (sortKey === "due") {
    arr.sort((a, b) => {
      const aDue = a.dueDate ? new Date(a.dueDate).getTime() : Infinity;
      const bDue = b.dueDate ? new Date(b.dueDate).getTime() : Infinity;
      return aDue - bDue;
    });
  } else if (sortKey === "priority") {
    arr.sort((a, b) => PRIORITY_ORDER[a.priority] - PRIORITY_ORDER[b.priority]);
  } else {
    arr.sort((a, b) => (b.updatedAt ?? "").localeCompare(a.updatedAt ?? ""));
  }
  return arr;
}

export default function MyTasksPage({ params }: { params: Promise<{ wid: string }> }) {
  const { wid } = use(params);

  const t = useTranslations("task");
  const tStatus = useTranslations("status");
  const tErr = useTranslations("error");
  const tNav = useTranslations("nav");
  const [tasks, setTasks] = useState<Task[]>([]);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState<StatusFilter>("all");
  const [sortKey, setSortKey] = useState<SortKey>("recent");
  const [error, setError] = useState<string | null>(null);

  const loadTasks = useCallback(() => {
    setLoading(true);
    let cancelled = false;
    api<{ items: Task[]; total: number; hasMore: boolean }>(
      `/api/v1/workspaces/${wid}/tasks?assignee=me`,
    )
      .then((data) => {
        if (cancelled) return;
        setError(null);
        setTasks(data?.items ?? []);
      })
      .catch((e) => {
        if (!cancelled) {
          setError(
            e instanceof Error && e.message.includes("fetch")
              ? tErr("networkConnectFailed")
              : tErr("loadFailed"),
          );
          // M-1 修复：不 setTasks([]) — 保留旧数据（首次加载为 [] 初始值），
          // 让 error UI 可达。原逻辑 setTasks([]) 后 tasks.length===0 恒真，
          // 进入 EmptyState 分支，错误提示+重试按钮在 else 分支内永不显示。
        }
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [wid, tErr]);

  useEffect(() => {
    return loadTasks();
  }, [loadTasks]);

  /** 当前筛选下需要展示的状态分组 */
  const visibleGroups =
    statusFilter === "all" ? STATUS_GROUPS : STATUS_GROUPS.filter((g) => g.id === statusFilter);

  /**
   * 筛选后无结果：有任务但当前筛选下所有可见组都为空。
   * 仅在单状态筛选且该状态无任务时触发（全部筛选下 tasks 非空必有一组非空）。
   */
  const filteredEmpty =
    !loading &&
    tasks.length > 0 &&
    visibleGroups.every((g) => tasks.filter((t) => t.status === g.id).length === 0);

  return (
    <div className="max-w-[var(--container-max)] mx-auto">
      {/* 标题区 */}
      <div className="mb-[var(--space-6)]">
        <h1 className="text-[length:var(--text-2xl)] font-[weight:var(--weight-semibold)] text-[var(--fg)] tracking-[var(--tracking-tight)]">
          {tNav("menu.myTasks")}
        </h1>
        <p className="mt-[var(--space-1)] text-[length:var(--text-sm)] text-[var(--muted)]">
          {loading ? t("loading") : t("myTasksCount", { count: tasks.length })}
        </p>
      </div>

      {/* 筛选栏：状态筛选（移动端横向滚动）+ 排序下拉 */}
      <div className="mb-[var(--space-5)] flex items-center gap-[var(--space-3)]">
        <div className="flex-1 min-w-0 overflow-x-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
          <div className="inline-flex items-center gap-[var(--space-1)] p-[var(--space-1)] bg-[var(--surface-2)] rounded-[var(--radius-md)]">
            {STATUS_FILTERS.map((f) => (
              <button
                key={f.id}
                onClick={() => setStatusFilter(f.id)}
                aria-pressed={statusFilter === f.id}
                className={`flex items-center gap-1.5 px-[var(--space-3)] py-[var(--space-1)] rounded-[var(--radius-sm)] text-[length:var(--text-sm)] whitespace-nowrap transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 ${
                  statusFilter === f.id
                    ? "bg-[var(--surface)] text-[var(--fg)] shadow-[var(--elev-sm)] font-[weight:var(--weight-medium)]"
                    : "text-[var(--muted)] hover:text-[var(--fg)]"
                }`}
              >
                {f.color && (
                  <span
                    className="w-1.5 h-1.5 rounded-full shrink-0"
                    style={{ background: f.color }}
                  />
                )}
                {tStatus(f.titleKey)}
              </button>
            ))}
          </div>
        </div>
        {/* 排序下拉：appearance-none + 自定义 lucide 箭头 */}
        <div className="relative shrink-0">
          <select
            value={sortKey}
            onChange={(e) => setSortKey(e.target.value as SortKey)}
            aria-label={t("sortAria")}
            className="appearance-none text-[length:var(--text-sm)] text-[var(--fg-2)] bg-[var(--surface-2)] border border-[var(--border)] rounded-[var(--radius-md)] pl-[var(--space-3)] pr-[var(--space-8)] py-[var(--space-1)] cursor-pointer focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:outline-none"
          >
            <option value="recent">{t("sortRecent")}</option>
            <option value="due">{t("sortDue")}</option>
            <option value="priority">{t("sortPriority")}</option>
          </select>
          <ChevronDown
            size={14}
            className="pointer-events-none absolute right-2.5 top-1/2 -translate-y-1/2 text-[var(--muted)]"
          />
        </div>
      </div>

      {/* 内容区 */}
      {loading ? (
        <MyTasksSkeleton />
      ) : error && tasks.length === 0 ? (
        // M-1 修复：首次加载失败（tasks 仍为 [] 初始值）时显示错误提示+重试按钮。
        // 原逻辑因 catch 中 setTasks([]) 导致 tasks.length===0 恒真进入 EmptyState，
        // 错误 UI 被困在 else 分支内不可达。
        <div className="rounded-[var(--radius-md)] bg-[var(--danger-soft)] p-[var(--space-4)] text-[length:var(--text-sm)] text-[var(--danger-fg)] flex items-center justify-between">
          <span>{error}</span>
          <button
            onClick={() => {
              setError(null);
              loadTasks();
            }}
            className="text-[var(--danger)] underline hover:text-[var(--danger-fg)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
          >
            {tErr("retry")}
          </button>
        </div>
      ) : tasks.length === 0 ? (
        <EmptyState />
      ) : filteredEmpty ? (
        <NoResultState />
      ) : (
        <div className="space-y-[var(--space-4)]">
          {error && (
            <div className="mb-[var(--space-4)] rounded-[var(--radius-md)] bg-[var(--danger-soft)] p-[var(--space-4)] text-[length:var(--text-sm)] text-[var(--danger-fg)] flex items-center justify-between">
              <span>{error}</span>
              <button
                onClick={() => {
                  setError(null);
                  loadTasks();
                }}
                className="text-[var(--danger)] underline hover:text-[var(--danger-fg)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
              >
                {tErr("retry")}
              </button>
            </div>
          )}
          {visibleGroups.map((group) => {
            const groupTasks = sortTasks(
              tasks.filter((t) => t.status === group.id),
              sortKey,
            );
            // 全部筛选下跳过空组，避免空占位；单状态筛选由 filteredEmpty 兜底
            if (statusFilter === "all" && groupTasks.length === 0) return null;
            return (
              <StatusGroup
                key={group.id}
                title={tStatus(group.titleKey)}
                color={group.color}
                count={groupTasks.length}
                tasks={groupTasks}
                renderTask={(task) => (
                  <TaskCard task={task} href={`/w/${wid}/task/${task.id}`} />
                )}
              />
            );
          })}
        </div>
      )}
    </div>
  );
}

/** 状态分组容器：标题（状态点 + 名称 + 计数）+ 卡片列表
 *
 * 渲染策略：
 *  - tasks.length > TASKS_VIRTUAL_THRESHOLD：启用 VirtualList 虚拟化，
 *    仅渲染可视区域 + overscan，避免长列表卡顿。每项用 AnimatedItem 包裹
 *    保留进场动画（stagger 在虚拟模式下退化为各自 fadeUp）。
 *  - 否则：AnimatedList + AnimatedItem，保留 stagger 进场动画。
 */
function StatusGroup<T extends { id: string }>({
  title,
  color,
  count,
  tasks,
  renderTask,
}: {
  title: string;
  color: string;
  count: number;
  tasks: T[];
  renderTask: (task: T) => ReactNode;
}) {
  const useVirtual = tasks.length > TASKS_VIRTUAL_THRESHOLD;
  return (
    <section className="bg-[var(--surface)] border border-[var(--border)] rounded-[var(--radius-lg)] shadow-[var(--elev-sm)] overflow-hidden">
      <header className="flex items-center gap-[var(--space-2)] px-[var(--space-4)] sm:px-[var(--space-5)] py-[var(--space-3)] border-b border-[var(--border-soft)]">
        <span className="w-2 h-2 rounded-full shrink-0" style={{ background: color }} />
        <h2 className="text-[length:var(--text-md)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
          {title}
        </h2>
        <span className="ml-auto text-[length:var(--text-xs)] text-[var(--muted)] bg-[var(--surface-2)] px-[var(--space-2)] py-0.5 rounded-full tabular-nums">
          {count}
        </span>
      </header>
      {useVirtual ? (
        // 虚拟列表：TaskCard 高度约 56px（py-[var(--space-3)]=24px + 内容约 32px）
        <VirtualList
          items={tasks}
          renderItem={(task) => (
            <AnimatedItem key={task.id} className="border-b border-[var(--border-soft)] last:border-b-0">
              {renderTask(task)}
            </AnimatedItem>
          )}
          estimateSize={56}
          className="divide-y divide-[var(--border-soft)]"
        />
      ) : (
        <AnimatedList className="divide-y divide-[var(--border-soft)]">
          {tasks.map((task) => (
            <AnimatedItem key={task.id}>{renderTask(task)}</AnimatedItem>
          ))}
        </AnimatedList>
      )}
    </section>
  );
}

/** 任务卡片：左侧 4px 优先级色条 + 标题 + 右侧截止日期与状态 badge */
function TaskCard({ task, href }: { task: Task; href: string }) {
  const tStatus = useTranslations("status");
  const tTime = useTranslations("time");
  const due = task.dueDate ? sharedFormatRelativeDueDate(task.dueDate, tTime) : null;
  return (
    <Link
      href={href}
      className="flex w-full items-center gap-[var(--space-3)] px-[var(--space-4)] sm:px-[var(--space-5)] py-[var(--space-3)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:outline-none"
      style={{ borderLeft: `4px solid ${PRIORITY_BAR_COLORS[task.priority]}` }}
    >
      <span className="flex-1 min-w-0 text-[length:var(--text-base)] text-[var(--fg)] truncate">
        {task.title}
      </span>
      {/* 截止日期：逾期用 --danger，今天用 --warn，其余 --muted */}
      {due && (
        <span
          className={`shrink-0 text-[length:var(--text-xs)] tabular-nums ${
            due.tone === "overdue"
              ? "text-[var(--danger)]"
              : due.tone === "today"
                ? "text-[var(--warn)]"
                : "text-[var(--muted)]"
          }`}
        >
          {due.text}
        </span>
      )}
      {/* 状态 badge */}
      <span
        className="shrink-0 text-[length:var(--text-xs)] px-[var(--space-1)] py-0.5 rounded-[var(--radius-sm)]"
        style={STATUS_BADGE_STYLES[task.status]}
      >
        {tStatus(STATUS_LABEL_KEYS[task.status])}
      </span>
    </Link>
  );
}

/** 空状态：当前用户没有任何被分配的任务，统一使用 @/components/EmptyState 的 inbox 插画。 */
function EmptyState() {
  const tEmpty = useTranslations("empty");
  return (
    <EmptyStateBase
      type="inbox"
      title={tEmpty("noTasks")}
      description={tEmpty("noTasksForYou")}
    />
  );
}

/** 筛选后无结果：有任务但当前筛选条件下无匹配，用 search 插画。 */
function NoResultState() {
  const tEmpty = useTranslations("empty");
  return <EmptyStateBase type="search" title={tEmpty("noTasksMatch")} />;
}

/**
 * 加载骨架：标题 + 筛选栏 + 2 个分组占位，每组 3 行卡片占位。
 * 尺寸与正式布局对齐，避免加载完成时布局跳动。
 */
function MyTasksSkeleton() {
  return (
    <div aria-busy="true" aria-live="polite">
      {/* 标题骨架 */}
      <div className="mb-[var(--space-6)]">
        <Skeleton className="h-8 w-32 mb-[var(--space-2)]" />
        <Skeleton className="h-4 w-20" />
      </div>
      {/* 筛选栏骨架 */}
      <div className="mb-[var(--space-5)] flex items-center gap-[var(--space-3)]">
        <Skeleton className="h-9 w-72 rounded-[var(--radius-md)]" />
        <Skeleton className="h-9 w-28 rounded-[var(--radius-md)]" />
      </div>
      {/* 分组骨架 × 2 */}
      <div className="space-y-[var(--space-4)]">
        {Array.from({ length: 2 }).map((_, i) => (
          <div
            key={i}
            className="bg-[var(--surface)] border border-[var(--border)] rounded-[var(--radius-lg)] shadow-[var(--elev-sm)] overflow-hidden"
          >
            {/* 组头 */}
            <div className="flex items-center gap-[var(--space-2)] px-[var(--space-4)] sm:px-[var(--space-5)] py-[var(--space-3)] border-b border-[var(--border-soft)]">
              <Skeleton className="w-2 h-2 rounded-full" />
              <Skeleton className="h-4 w-16" />
              <Skeleton className="ml-auto h-5 w-8 rounded-full" />
            </div>
            {/* 卡片行骨架 × 3 */}
            <div className="divide-y divide-[var(--border-soft)]">
              {Array.from({ length: 3 }).map((_, j) => (
                <div key={j} className="flex items-center gap-[var(--space-3)] px-[var(--space-4)] sm:px-[var(--space-5)] py-[var(--space-3)]">
                  <Skeleton
                    className="flex-1 h-4"
                    // 宽度在 65%~94% 间错落，避免机械感
                    style={{ maxWidth: `${65 + ((j * 17) % 30)}%` }}
                  />
                  <Skeleton className="shrink-0 w-12 h-3" />
                  <Skeleton className="shrink-0 w-12 h-5 rounded-[var(--radius-sm)]" />
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

"use client";

/**
 * 通知中心 · /w/[wid]/notifications
 *
 * 列表型页面，参考概览页（w/[wid]/page.tsx）的布局与 token 体系：
 *  - 所有颜色走 var(--token)，无裸 hex
 *  - 图标统一来自 lucide-react
 *  - 间距 / 字号 / 圆角 / 阴影 / 动效全部走 token
 *
 * 数据流：
 *  - GET  /api/v1/workspaces/[wid]/notifications → { notifications: Notification[] }
 *  - PATCH /api/v1/workspaces/[wid]/notifications body { id?: string, all?: boolean } → 标记已读
 *
 * 交互：
 *  - 顶部 segmented 筛选（全部 / 未读），客户端过滤
 *  - 「全部已读」按钮仅在有未读时出现，乐观更新 + PATCH all=true
 *  - 单条点击：乐观标记已读 + 跳转 /w/[wid]/task/{entityId}
 *
 * 状态：
 *  - 加载中：NotificationListSkeleton 骨架屏
 *  - 空列表：Bell 图标 + 引导文案
 *  - 筛选未读无结果：精简空状态「没有未读通知」
 */

import { use, useCallback, useEffect, useMemo, useState } from "react";
import { useRouter } from "@/lib/i18n-navigation";
import { relativeTime as sharedRelativeTime } from "@/lib/format";
import {
  AtSign,
  UserPlus,
  RefreshCw,
  MessageSquare,
  FileText,
  Bell,
  CheckCheck,
  Loader2,
} from "lucide-react";
import { api } from "@/lib/api";
import { Skeleton } from "@/components/Skeleton";
import EmptyStateBase from "@/components/EmptyState";
import { AnimatedList, AnimatedItem } from "@/components/AnimatedList";
import { VirtualList } from "@/components/VirtualList";
import { SwipeToDismiss } from "@/components/SwipeToDismiss";

import { useTranslations } from "next-intl";

/** 通知列表虚拟化阈值：超过此数量启用 VirtualList，否则保持 AnimatedList 原渲染 */
const NOTIFICATIONS_VIRTUAL_THRESHOLD = 30;

type NotificationType =
  | "mention" | "task_assigned" | "task_updated" | "comment_added" | "decision_updated" | "ai_push";

interface Notification {
  id: string;
  type: NotificationType;
  entityId: string;
  entityTitle: string;
  read: boolean;
  createdAt: string;
}

type Filter = "all" | "unread" | "mention" | "assigned";

const FILTER_TABS: { id: Filter; labelKey: string }[] = [
  { id: "all", labelKey: "filterAll" },
  { id: "unread", labelKey: "filterUnread" },
  { id: "mention", labelKey: "filterMention" },
  { id: "assigned", labelKey: "filterAssigned" },
];

/** 过滤条件：哪些 type 对应到各 tab */
function matchFilter(n: Notification, f: Filter): boolean {
  if (f === "all") return true;
  if (f === "unread") return !n.read;
  if (f === "mention") return n.type === "mention";
  if (f === "assigned") return n.type === "task_assigned";
  return true;
}

/**
 * 通知类型元数据：图标 + 图标色 + 文案 key（阶段 2-6 i18n：模板经
 * notifications ns 的 key 渲染，title 由调用方以 values 注入）。
 *
 * 颜色映射（遵循设计规范，已对齐项目实际 token）：
 *  - mention         → AtSign        · var(--accent)   （提到我）
 *  - task_assigned   → UserPlus      · var(--success)  （分配任务）
 *  - task_updated    → RefreshCw     · var(--accent)   （规范写 var(--info)，项目无 --info，用 --accent 代替）
 *  - comment_added   → MessageSquare · var(--warn)     （规范写 var(--warning)，项目 token 为 --warn）
 *  - decision_updated→ FileText      · var(--fg-2)     （决策更新）
 *  - ai_push         → Bell          · var(--accent)   （AI 推送）
 */
const TYPE_META: Record<NotificationType, { icon: typeof AtSign; color: string; textKey: string }> =
  {
    mention: { icon: AtSign, color: "var(--accent)", textKey: "mentionText" },
    task_assigned: { icon: UserPlus, color: "var(--success)", textKey: "assignedText" },
    task_updated: { icon: RefreshCw, color: "var(--accent)", textKey: "updatedText" },
    comment_added: { icon: MessageSquare, color: "var(--warn)", textKey: "commentText" },
    decision_updated: { icon: FileText, color: "var(--fg-2)", textKey: "decisionText" },
    ai_push: { icon: Bell, color: "var(--accent)", textKey: "aiPushText" },
  };

// 相对时间戳：共享 format.ts（阶段 2-6 i18n——经 useTranslations("time") 输出当前语言）

export default function NotificationsPage({ params }: { params: Promise<{ wid: string }> }) {
  const { wid } = use(params);
  const router = useRouter();

  const [all, setAll] = useState<Notification[]>([]);
  const tNotif = useTranslations("notifications");
  const tTime = useTranslations("time");
  const tErr = useTranslations("error");

  const relativeTime = (iso?: string) => sharedRelativeTime(iso, tTime);
  const [loaded, setLoaded] = useState(false);
  const [filter, setFilter] = useState<Filter>("all");
  const [marking, setMarking] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    try {
      setError(null);
      const res = await api<{ items: Notification[]; total: number; hasMore: boolean }>(
        `/api/v1/workspaces/${wid}/notifications`,
      );
      setAll(res?.items ?? []);
    } catch (e) {
      setError(
        e instanceof Error && e.message.includes("fetch")
          ? tErr("networkConnectFailed")
          : tErr("loadFailed"),
      );
      setAll([]);
    } finally {
      setLoaded(true);
    }
  }, [wid]);

  useEffect(() => {
    load();
  }, [load]);

  const unreadCount = useMemo(() => all.filter((n) => !n.read).length, [all]);

  // 当前筛选下的可见列表，按 createdAt 降序
  const visible = useMemo(() => {
    const list = all.filter((n) => matchFilter(n, filter));
    return [...list].sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  }, [all, filter]);

  /** 全部已读：乐观更新本地，再 PATCH all=true；失败回滚重新加载 */
  async function markAllRead() {
    if (marking || unreadCount === 0) return;
    setMarking(true);
    setAll((prev) => prev.map((n) => ({ ...n, read: true })));
    try {
      await api(`/api/v1/workspaces/${wid}/notifications`, {
        method: "PATCH",
        body: JSON.stringify({ all: true }),
      });
    } catch {
      await load();
    } finally {
      setMarking(false);
    }
  }

  /** 单条点击：乐观标记已读（fire-and-forget）+ 跳转对应详情
   *  跳转目标按通知类型区分：
   *    - task_assigned / task_updated / comment_added / mention → 任务详情
   *    - decision_updated → 任务详情的决策区（hash 锚点 #decisions）
   *    - ai_push → AI 工具中心（/w/[wid]/ai-tools）
   *  除 ai_push 外，通知的 entityId 均指向关联任务，故统一跳 /task/{entityId}，
   *  decision_updated 追加 #decisions 锚点以便定位到决策记录区。
   */
  function openNotification(n: Notification) {
    if (!n.read) {
      setAll((prev) => prev.map((x) => (x.id === n.id ? { ...x, read: true } : x)));
      // 不阻塞跳转，失败时下次进入页面会重新加载纠正
      api(`/api/v1/workspaces/${wid}/notifications`, {
        method: "PATCH",
        body: JSON.stringify({ id: n.id }),
      }).catch(() => {
        // 标记已读失败：router.push 已先执行导航，toast 在新页面弹出会误导用户，降级为 console.warn
        console.warn("openNotification: 标记已读失败，下次进入页面会重新加载纠正");
      });
    }
    // AI 推送通知跳转 AI 工具中心
    if (n.type === "ai_push") {
      router.push(`/w/${wid}/ai-tools`);
      return;
    }
    const target = `/w/${wid}/task/${n.entityId}`;
    router.push(n.type === "decision_updated" ? `${target}#decisions` : target);
  }

  /** 横滑删除：乐观从本地列表移除，PATCH 标记已读；失败回滚重新加载 */
  function dismissNotification(n: Notification) {
    setAll((prev) => prev.filter((x) => x.id !== n.id));
    api(`/api/v1/workspaces/${wid}/notifications`, {
      method: "PATCH",
      body: JSON.stringify({ id: n.id }),
    }).catch(() => {
      // 删除失败：重新加载恢复列表
      load();
    });
  }

  return (
    <div className="max-w-[var(--container-max)] mx-auto px-[var(--space-4)]">
      {/* 页头：标题 + 未读计数 badge */}
      <header className="flex items-end justify-between mb-[var(--space-6)] gap-[var(--space-4)]">
        <div className="flex items-center gap-[var(--space-3)]">
          <h1 className="text-[length:var(--text-2xl)] font-[weight:var(--weight-semibold)] text-[var(--fg)] tracking-[var(--tracking-tight)]">
            {tNotif("title")}
          </h1>
          {loaded && unreadCount > 0 && (
            <span
              className="inline-flex items-center justify-center min-w-[20px] h-5 px-1.5 rounded-full bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] tabular-nums"
              aria-label={tNotif("unreadCount", { count: unreadCount })}
            >
              {unreadCount}
            </span>
          )}
        </div>
      </header>

      {/* 操作栏：左侧筛选 segmented · 右侧全部已读 */}
      <div className="flex items-center justify-between mb-[var(--space-4)] gap-[var(--space-3)]">
        <div
          role="tablist"
          aria-label={tNotif("filterAria")}
          className="inline-flex flex-1 min-w-0 overflow-x-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden p-0.5 bg-[var(--surface-2)] border border-[var(--border)] rounded-[var(--radius-md)]"
        >
          {FILTER_TABS.map((tab) => (
            <button
              key={tab.id}
              role="tab"
              aria-selected={filter === tab.id}
              onClick={() => setFilter(tab.id)}
              className={`px-3 h-7 rounded-[var(--radius-sm)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none ${
                filter === tab.id
                  ? "bg-[var(--surface)] text-[var(--fg)] shadow-[var(--elev-sm)]"
                  : "text-[var(--muted)] hover:text-[var(--fg-2)]"
              }`}
            >
              {tNotif(tab.labelKey)}
            </button>
          ))}
        </div>

        {loaded && unreadCount > 0 && (
          <button
            onClick={markAllRead}
            disabled={marking}
            className="flex items-center gap-1.5 h-8 px-3 text-[length:var(--text-sm)] text-[var(--muted)] hover:text-[var(--fg)] hover:bg-[var(--surface-2)] rounded-[var(--radius-md)] transition-colors duration-[var(--motion-fast)] disabled:opacity-50 disabled:cursor-not-allowed focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:outline-none"
          >
            {marking ? <Loader2 size={14} className="animate-spin" /> : <CheckCheck size={14} />}
            {tNotif("markAllRead")}
          </button>
        )}
      </div>

      {/* 列表区：加载骨架 / 空状态 / 通知卡片 */}
      {!loaded ? (
        <NotificationListSkeleton count={6} />
      ) : visible.length === 0 ? (
        <EmptyState filter={filter} />
      ) : (
        <>
          {error && (
            <div className="mb-4 rounded-[var(--radius-md)] bg-[var(--danger-soft)] p-3 text-[length:var(--text-sm)] text-[var(--danger-fg)] flex items-center justify-between">
              <span>{error}</span>
              <button
                onClick={() => {
                  setError(null);
                  load();
                }}
                className="text-[var(--danger)] underline hover:text-[var(--danger-fg)]"
              >
                {tErr("retry")}
              </button>
            </div>
          )}
          {visible.length > NOTIFICATIONS_VIRTUAL_THRESHOLD ? (
            // 虚拟列表：通知卡片高度约 68px（py-3.5=28px + 图标行约 40px）
            <VirtualList
              items={visible}
              renderItem={(n) => {
                const meta = TYPE_META[n.type];
                const Icon = meta.icon;
                const rel = relativeTime(n.createdAt);
                const text = tNotif(meta.textKey, { title: n.entityTitle });
                return (
                  <AnimatedItem key={n.id}>
                    <SwipeToDismiss onDismiss={() => dismissNotification(n)} dismissLabel={tNotif("markRead")}>
                      <button
                        type="button"
                        onClick={() => openNotification(n)}
                        aria-label={`${text}${n.read ? "" : tNotif("unreadSuffix")}`}
                        className={`w-full flex items-start gap-3 px-4 py-3.5 rounded-[var(--radius-lg)] border border-[var(--border)] text-left transition-colors duration-[var(--motion-fast)] hover:border-[var(--muted)] focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:outline-none ${
                          n.read ? "bg-[var(--surface)]" : "bg-[var(--surface-2)]"
                        }`}
                      >
                        <Icon size={16} className="shrink-0 mt-0.5" style={{ color: meta.color }} />
                        <div className="flex-1 min-w-0">
                          <p
                            className={`text-[length:var(--text-base)] truncate ${
                              n.read ? "text-[var(--fg-2)]" : "text-[var(--fg)]"
                            }`}
                          >
                            {text}
                          </p>
                          {rel && (
                            <p className="mt-0.5 text-[length:var(--text-xs)] text-[var(--meta)] tabular-nums">
                              {rel}
                            </p>
                          )}
                        </div>
                        {!n.read && (
                          <span
                            className="shrink-0 mt-1 w-2 h-2 rounded-full bg-[var(--accent)]"
                            aria-hidden="true"
                          />
                        )}
                      </button>
                    </SwipeToDismiss>
                  </AnimatedItem>
                );
              }}
              estimateSize={68}
              className="flex flex-col gap-[var(--space-3)]"
            />
          ) : (
            <AnimatedList className="flex flex-col gap-[var(--space-3)]">
              {visible.map((n) => {
                const meta = TYPE_META[n.type];
                const Icon = meta.icon;
                const rel = relativeTime(n.createdAt);
                const text = tNotif(meta.textKey, { title: n.entityTitle });
                return (
                  <AnimatedItem key={n.id}>
                    <SwipeToDismiss onDismiss={() => dismissNotification(n)} dismissLabel={tNotif("markRead")}>
                      <button
                        type="button"
                        onClick={() => openNotification(n)}
                        aria-label={`${text}${n.read ? "" : tNotif("unreadSuffix")}`}
                        className={`w-full flex items-start gap-3 px-4 py-3.5 rounded-[var(--radius-lg)] border border-[var(--border)] text-left transition-colors duration-[var(--motion-fast)] hover:border-[var(--muted)] focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:outline-none ${
                          n.read ? "bg-[var(--surface)]" : "bg-[var(--surface-2)]"
                        }`}
                      >
                        <Icon size={16} className="shrink-0 mt-0.5" style={{ color: meta.color }} />
                        <div className="flex-1 min-w-0">
                          <p
                            className={`text-[length:var(--text-base)] truncate ${
                              n.read ? "text-[var(--fg-2)]" : "text-[var(--fg)]"
                            }`}
                          >
                            {text}
                          </p>
                          {rel && (
                            <p className="mt-0.5 text-[length:var(--text-xs)] text-[var(--meta)] tabular-nums">
                              {rel}
                            </p>
                          )}
                        </div>
                        {!n.read && (
                          <span
                            className="shrink-0 mt-1 w-2 h-2 rounded-full bg-[var(--accent)]"
                            aria-hidden="true"
                          />
                        )}
                      </button>
                    </SwipeToDismiss>
                  </AnimatedItem>
                );
              })}
            </AnimatedList>
          )}
        </>
      )}
    </div>
  );
}

/**
 * 通知列表骨架
 * 渲染 count 张与正式卡片尺寸一致的占位块：
 *   左侧图标 16px + 标题行 + 时间行 + 右侧未读圆点
 * 宽度在 60%~95% 间错落，避免机械感（与 TaskListSkeleton 同思路）。
 */
function NotificationListSkeleton({ count = 6 }: { count?: number }) {
  return (
    <div className="flex flex-col gap-[var(--space-3)]" aria-busy="true">
      {Array.from({ length: count }).map((_, i) => (
        <div
          key={i}
          className="flex items-start gap-3 px-4 py-3.5 rounded-[var(--radius-lg)] border border-[var(--border)] bg-[var(--surface)]"
        >
          <Skeleton className="shrink-0 mt-0.5 w-4 h-4 rounded-full" />
          <div className="flex-1">
            <Skeleton className="h-[14px]" style={{ maxWidth: `${60 + ((i * 37) % 36)}%` }} />
            <Skeleton className="mt-1 w-16 h-[12px]" />
          </div>
          <Skeleton className="shrink-0 mt-1 w-2 h-2 rounded-full" />
        </div>
      ))}
    </div>
  );
}

/**
 * 空状态：按不同 filter 给不同提示，统一使用 @/components/EmptyState 的 SVG 插画。
 *  - all      → inbox  + 「暂无通知」+ 引导文案
 *  - unread   → inbox  + 「没有未读通知」
 *  - mention  → inbox  + 「没有提及通知」
 *  - assigned → users  + 「没有分配通知」
 */
function EmptyState({ filter }: { filter: Filter }) {
  const t = useTranslations("empty");
  if (filter === "unread") {
    return <EmptyStateBase type="inbox" title={t("noUnreadNotifications")} />;
  }
  if (filter === "mention") {
    return <EmptyStateBase type="inbox" title={t("noMentionNotifications")} />;
  }
  if (filter === "assigned") {
    return <EmptyStateBase type="users" title={t("noAssignedNotifications")} />;
  }
  return (
    <EmptyStateBase
      type="inbox"
      title={t("noNotifications")}
      description={t("emptyHint")}
    />
  );
}

"use client";

/**
 * 工作区首页（仪表盘）· /w/[wid]
 *
 * F3 改造：从固定布局改为可拖拽 Widget 仪表盘。
 *
 * 结构：
 *  - 顶部：欢迎语 + 「添加 Widget」按钮 + 「编辑布局」开关
 *  - 主体：<DashboardGrid>（RGL 容器，内部渲染各 Widget）
 *  - Onboarding 引导保留（无任务时显示）
 *
 * 数据流：
 *  - workspace context：GET /api/v1/workspaces → 获取当前 workspace 的 role
 *  - 布局：DashboardGrid 内部管理（GET/PUT /dashboard/layout）
 *  - Widget 数据：各 Widget 独立 fetch /dashboard/widgets/:widgetId
 *
 * 设计：
 *  - 所有色值走 var(--token)，图标来自 lucide-react
 *  - i18n 使用 useTranslations hook
 *  - 响应式：移动端 DashboardGrid 自动切换为单列纵向堆叠
 */

import { use, useCallback, useEffect, useRef, useState } from "react";
import { Plus, Pencil, Check, LayoutDashboard, Download, Upload, LayoutGrid, Move, Minimize2, Square, Maximize2, ChevronDown } from "lucide-react";
import { api } from "@/lib/api";
import { useTranslations } from "next-intl";
import { useToast } from "@/components/Toast";
import type { WorkspaceSummary, Role } from "@/lib/types";
import Onboarding from "@/components/Onboarding";
import DashboardGrid, { type DashboardGridHandle } from "@/components/dashboard/DashboardGrid";
import AddWidgetDialog from "@/components/dashboard/AddWidgetDialog";
import WidgetGrid from "@/components/WidgetGrid";
import TaskSummaryWidget from "@/components/widgets/TaskSummaryWidget";
import ActivityWidget from "@/components/widgets/ActivityWidget";
import AiInsightWidget from "@/components/widgets/AiInsightWidget";

/** 仪表盘间距密度预设 */
type Density = "compact" | "comfortable" | "spacious";

export default function HomePage({ params }: { params: Promise<{ wid: string }> }) {
  const { wid } = use(params);

  const t = useTranslations("dashboard");
  const tNav = useTranslations("nav");
  const tTask = useTranslations("task");
  const { toast } = useToast();

  // workspace context（获取 role + 判断 onboarding）
  const [workspace, setWorkspace] = useState<WorkspaceSummary | null>(null);
  const [wsLoaded, setWsLoaded] = useState(false);
  // Onboarding 引导：用户完成或跳过后本地标记，避免重复弹窗
  const [onboardingDismissed, setOnboardingDismissed] = useState(false);
  // 任务数（用于 Onboarding 判断是否显示）
  const [taskCount, setTaskCount] = useState(0);

  // 仪表盘状态
  const [editing, setEditing] = useState(false);
  const [addDialogOpen, setAddDialogOpen] = useState(false);
  /** 当前布局中的 Widget id 列表（用于 AddWidgetDialog 灰显已添加项） */
  const [layoutIds, setLayoutIds] = useState<string[]>([]);
  const gridRef = useRef<DashboardGridHandle>(null);
  // F7 自由拼接：布局模式（网格 / 自由）+ 间距密度预设
  const [freeMode, setFreeMode] = useState(false);
  const [density, setDensity] = useState<Density>("comfortable");
  const [homeView, setHomeView] = useState<"dashboard" | "widgets">("dashboard");
  // 编辑模式工具栏下拉菜单（< lg 时折叠）
  const [toolbarMenuOpen, setToolbarMenuOpen] = useState(false);

  useEffect(() => {
    try {
      setHomeView(localStorage.getItem(`${wid}_home_view`) === "widgets" ? "widgets" : "dashboard");
    } catch {
      setHomeView("dashboard"); // 隐私模式下存储不可用，仍可正常切换。
    }
    setEditing(false);
    setAddDialogOpen(false);
  }, [wid]);

  function changeHomeView(view: "dashboard" | "widgets") {
    setHomeView(view);
    setEditing(false);
    setAddDialogOpen(false);
    try {
      localStorage.setItem(`${wid}_home_view`, view);
    } catch {
      // 存储权限受限时仅保留当前会话偏好。
    }
  }

  // ─── 加载 workspace context ───
  const loadWorkspace = useCallback(async () => {
    try {
      const wsList = await api<WorkspaceSummary[]>("/api/v1/workspaces");
      const cur = wsList.find((w) => w.id === wid);
      if (cur) setWorkspace(cur);
    } catch {
      // 忽略：DashboardGrid 会用 viewer 默认布局兜底
    } finally {
      setWsLoaded(true);
    }
  }, [wid]);

  useEffect(() => {
    loadWorkspace();
  }, [loadWorkspace]);

  // ─── 加载任务数（用于 Onboarding 判断） ───
  useEffect(() => {
    api<{ items?: unknown[] } | unknown[]>(`/api/v1/workspaces/${wid}/tasks`)
      .then((res) => {
        const count = Array.isArray(res) ? res.length : (res as { items?: unknown[] }).items?.length ?? 0;
        setTaskCount(count);
      })
      .catch(() => {
        /* 忽略：Onboarding 不显示即可 */
      });
  }, [wid]);

  const role: Role = workspace?.role ?? "viewer";

  // ─── 添加 Widget ───
  const handleAddWidget = useCallback((widgetId: string) => {
    gridRef.current?.addWidget(widgetId);
  }, []);

  // ─── 布局变化回调：更新 layoutIds ───
  const handleLayoutChange = useCallback((layout: { i: string }[]) => {
    setLayoutIds(layout.map((item) => item.i));
  }, []);

  // ─── F7 布局模式 / 密度切换 ───
  const handleFreeModeChange = useCallback((v: boolean) => setFreeMode(v), []);
  const handleDensityChange = useCallback((v: Density) => setDensity(v), []);

  // ─── 导出布局 ───
  const handleExportLayout = useCallback(async () => {
    try {
      const data = await gridRef.current?.exportLayout();
      if (!data) return;
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `dashboard-layout-${new Date().toISOString().slice(0, 10)}.json`;
      a.click();
      URL.revokeObjectURL(url);
    } catch {
      toast("error", t("exportLayoutFailed"));
    }
  }, []);

  // ─── 导入布局 ───
  const fileInputRef = useRef<HTMLInputElement>(null);
  const handleImportLayout = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const text = await file.text();
      const data = JSON.parse(text);
      await gridRef.current?.importLayout(data);
    } catch {
      toast("error", t("importLayoutFailed"));
    }
    e.target.value = ""; // 重置以便重复导入同一文件
  }, []);

  // ─── 工具栏按钮样式：激活态高亮，非激活态弱化 + hover ───
  const toolbarBtnClass = (active: boolean) =>
    `flex items-center gap-1.5 h-9 px-3 rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] transition-colors duration-[var(--motion-base)] focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:outline-none ${
      active
        ? "bg-[var(--surface-2)] text-[var(--fg)]"
        : "text-[var(--meta)] hover:bg-[var(--surface-2)] hover:text-[var(--fg)]"
    }`;

  return (
    <div className="max-w-[var(--container-max)] mx-auto">
      {/* 顶部：欢迎语 + 操作区 */}
      <div className="flex items-end justify-between mb-[var(--space-6)] gap-[var(--space-4)]">
        <div>
          <h1 className="flex items-center gap-2 text-[length:var(--text-2xl)] font-[weight:var(--weight-semibold)] text-[var(--fg)] tracking-[var(--tracking-tight)]">
            <LayoutDashboard size={20} className="text-[var(--muted)]" />
            {tNav("menu.overview")}
          </h1>
          <p className="mt-1 text-[length:var(--text-sm)] text-[var(--muted)]">
            {t("subtitle")}
          </p>
        </div>
        <div className="relative flex items-center justify-end gap-2 flex-wrap">
          <div className="flex items-center gap-1 p-1 rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)]" role="group" aria-label={t("homeView")}>
            <button type="button" className={toolbarBtnClass(homeView === "dashboard")} aria-pressed={homeView === "dashboard"} onClick={() => changeHomeView("dashboard")}>
              <LayoutGrid size={16} />{t("gridMode")}
            </button>
            <button type="button" className={toolbarBtnClass(homeView === "widgets")} aria-pressed={homeView === "widgets"} onClick={() => changeHomeView("widgets")}>
              <Move size={16} />{t("widgetView")}
            </button>
          </div>
          {/* 编辑布局开关 */}
          <button
            type="button"
            onClick={() => setEditing((v) => !v)}
            className={[
              "flex items-center gap-1.5 h-9 px-3 rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] transition-colors duration-[var(--motion-base)] focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:outline-none",
              editing
                ? "bg-[var(--accent)] text-[var(--accent-fg)] hover:bg-[var(--accent-hover)]"
                : "bg-[var(--surface)] border border-[var(--border)] text-[var(--fg-2)] hover:bg-[var(--surface-2)]",
            ].join(" ")}
            aria-pressed={editing}
          >
            {editing ? <Check size={15} /> : <Pencil size={15} />}
            <span className="hidden sm:inline">{editing ? t("exitEdit") : t("editLayout")}</span>
          </button>
          {/* 编辑模式工具栏：布局模式 + 密度 + 导出/导入（仅编辑模式） */}
          {editing && homeView === "dashboard" && (
            <>
              {/* < lg：折叠为下拉菜单触发按钮 */}
              <button
                type="button"
                onClick={() => setToolbarMenuOpen((v) => !v)}
                aria-expanded={toolbarMenuOpen}
                aria-label={t("layoutOptions")}
                className="flex items-center gap-1.5 h-9 px-3 lg:hidden rounded-[var(--radius-md)] bg-[var(--surface)] border border-[var(--border)] text-[var(--fg-2)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-base)] focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:outline-none"
              >
                <LayoutGrid size={16} />
                <ChevronDown size={14} className={`transition-transform duration-[var(--motion-fast)] ${toolbarMenuOpen ? "rotate-180" : ""}`} />
              </button>
              {/* < lg：下拉菜单面板 */}
              {toolbarMenuOpen && (
                <div className="lg:hidden absolute right-0 top-full mt-1 z-50 min-w-[200px] p-2 rounded-[var(--radius-md)] bg-[var(--surface)] border border-[var(--border)] shadow-[var(--elev-md)]">
                  {/* 布局模式切换 */}
                  <div className="px-2 py-1 text-[length:var(--text-xs)] text-[var(--muted)] font-[weight:var(--weight-medium)]">{t("layoutMode")}</div>
                  <div className="flex items-center gap-1 p-1" role="group" aria-label={t("layoutMode")}>
                    <button
                      type="button"
                      onClick={() => handleFreeModeChange(false)}
                      className={toolbarBtnClass(!freeMode)}
                      aria-pressed={!freeMode}
                      title={t("gridMode")}
                    >
                      <LayoutGrid size={16} />
                      <span>{t("gridMode")}</span>
                    </button>
                    <button
                      type="button"
                      onClick={() => handleFreeModeChange(true)}
                      className={toolbarBtnClass(freeMode)}
                      aria-pressed={freeMode}
                      title={t("freeMode")}
                    >
                      <Move size={16} />
                      <span>{t("freeMode")}</span>
                    </button>
                  </div>
                  {/* 分隔线 */}
                  <div className="h-px my-1 bg-[var(--border)]" aria-hidden="true" />
                  {/* 密度选择器 */}
                  <div className="px-2 py-1 text-[length:var(--text-xs)] text-[var(--muted)] font-[weight:var(--weight-medium)]">{t("layoutDensity")}</div>
                  <div className="flex items-center gap-1 p-1" role="group" aria-label={t("layoutDensity")}>
                    <button
                      type="button"
                      onClick={() => handleDensityChange("compact")}
                      className={toolbarBtnClass(density === "compact")}
                      aria-pressed={density === "compact"}
                      title={t("compact")}
                    >
                      <Minimize2 size={16} />
                      <span>{t("compact")}</span>
                    </button>
                    <button
                      type="button"
                      onClick={() => handleDensityChange("comfortable")}
                      className={toolbarBtnClass(density === "comfortable")}
                      aria-pressed={density === "comfortable"}
                      title={t("comfortable")}
                    >
                      <Square size={16} />
                      <span>{t("comfortable")}</span>
                    </button>
                    <button
                      type="button"
                      onClick={() => handleDensityChange("spacious")}
                      className={toolbarBtnClass(density === "spacious")}
                      aria-pressed={density === "spacious"}
                      title={t("spacious")}
                    >
                      <Maximize2 size={16} />
                      <span>{t("spacious")}</span>
                    </button>
                  </div>
                  {/* 分隔线 */}
                  <div className="h-px my-1 bg-[var(--border)]" aria-hidden="true" />
                  {/* 导出/导入布局 */}
                  <button
                    type="button"
                    onClick={() => { handleExportLayout(); setToolbarMenuOpen(false); }}
                    className="w-full flex items-center gap-1.5 h-9 px-3 rounded-[var(--radius-md)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-base)] focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:outline-none"
                  >
                    <Download size={15} />
                    <span>{t("exportLayout")}</span>
                  </button>
                  <button
                    type="button"
                    onClick={() => { fileInputRef.current?.click(); setToolbarMenuOpen(false); }}
                    className="w-full flex items-center gap-1.5 h-9 px-3 rounded-[var(--radius-md)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-base)] focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:outline-none"
                  >
                    <Upload size={15} />
                    <span>{t("importLayout")}</span>
                  </button>
                </div>
              )}
              {/* ≥ lg：平铺展示完整工具栏 */}
              <div className="hidden lg:flex items-center gap-2">
                {/* 分隔线 */}
                <span className="w-px h-5 bg-[var(--border)]" aria-hidden="true" />
                {/* 布局模式切换：网格 / 自由 */}
                <div className="flex items-center gap-1" role="group" aria-label={t("layoutMode")}>
                  <button
                    type="button"
                    onClick={() => handleFreeModeChange(false)}
                    className={toolbarBtnClass(!freeMode)}
                    aria-pressed={!freeMode}
                    title={t("gridMode")}
                  >
                    <LayoutGrid size={16} />
                    <span className="hidden sm:inline">{t("gridMode")}</span>
                  </button>
                  <button
                    type="button"
                    onClick={() => handleFreeModeChange(true)}
                    className={toolbarBtnClass(freeMode)}
                    aria-pressed={freeMode}
                    title={t("freeMode")}
                  >
                    <Move size={16} />
                    <span className="hidden sm:inline">{t("freeMode")}</span>
                  </button>
                </div>
                {/* 分隔线 */}
                <span className="w-px h-5 bg-[var(--border)]" aria-hidden="true" />
                {/* 密度选择器：紧凑 / 舒适 / 宽敞 */}
                <div className="flex items-center gap-1" role="group" aria-label={t("layoutDensity")}>
                  <button
                    type="button"
                    onClick={() => handleDensityChange("compact")}
                    className={toolbarBtnClass(density === "compact")}
                    aria-pressed={density === "compact"}
                    title={t("compact")}
                  >
                    <Minimize2 size={16} />
                    <span className="hidden sm:inline">{t("compact")}</span>
                  </button>
                  <button
                    type="button"
                    onClick={() => handleDensityChange("comfortable")}
                    className={toolbarBtnClass(density === "comfortable")}
                    aria-pressed={density === "comfortable"}
                    title={t("comfortable")}
                  >
                    <Square size={16} />
                    <span className="hidden sm:inline">{t("comfortable")}</span>
                  </button>
                  <button
                    type="button"
                    onClick={() => handleDensityChange("spacious")}
                    className={toolbarBtnClass(density === "spacious")}
                    aria-pressed={density === "spacious"}
                    title={t("spacious")}
                  >
                    <Maximize2 size={16} />
                    <span className="hidden sm:inline">{t("spacious")}</span>
                  </button>
                </div>
                {/* 分隔线 */}
                <span className="w-px h-5 bg-[var(--border)]" aria-hidden="true" />
                {/* 导出/导入布局 */}
                <button
                  type="button"
                  onClick={handleExportLayout}
                  className="flex items-center gap-1.5 h-9 px-3 bg-[var(--surface)] border border-[var(--border)] text-[var(--fg-2)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-base)] focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:outline-none"
                  aria-label={t("exportLayout")}
                  title={t("exportLayout")}
                >
                  <Download size={15} />
                  <span className="hidden sm:inline">{t("exportLayout")}</span>
                </button>
                <button
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="flex items-center gap-1.5 h-9 px-3 bg-[var(--surface)] border border-[var(--border)] text-[var(--fg-2)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-base)] focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:outline-none"
                  aria-label={t("importLayout")}
                  title={t("importLayout")}
                >
                  <Upload size={15} />
                  <span className="hidden sm:inline">{t("importLayout")}</span>
                </button>
              </div>
              <input
                ref={fileInputRef}
                type="file"
                accept="application/json"
                onChange={handleImportLayout}
                className="hidden"
              />
            </>
          )}
          {/* 添加 Widget 仅适用于原仪表盘 */}
          {homeView === "dashboard" && <button
            type="button"
            onClick={() => setAddDialogOpen(true)}
            className="flex items-center gap-1.5 h-9 px-3 bg-[var(--accent)] text-[var(--accent-fg)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] active:bg-[var(--accent-active)] transition-colors duration-[var(--motion-base)] focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:outline-none"
          >
            <Plus size={15} />
            <span className="hidden sm:inline">{t("addWidgetTitle")}</span>
          </button>}
        </div>
      </div>

      {/* 主体：仪表盘网格 */}
      {!wsLoaded ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3" aria-busy="true">
          {Array.from({ length: 4 }).map((_, i) => (
            <div
              key={i}
              className="h-32 bg-[var(--surface)] border border-[var(--border)] rounded-[var(--radius-lg)] shadow-[var(--elev-sm)] animate-pulse"
            />
          ))}
        </div>
      ) : homeView === "widgets" ? (
        <WidgetGrid
          key={wid}
          readOnly={!editing}
          widgets={[
            { id: "summary", title: t("taskStats"), component: <TaskSummaryWidget wid={wid} />, defaultPosition: { x: 0, y: 0, w: 4, h: 5 } },
            { id: "activity", title: t("recentActivity"), component: <ActivityWidget wid={wid} />, defaultPosition: { x: 4, y: 0, w: 4, h: 5 } },
            { id: "insight", title: t("aiInsight"), component: <AiInsightWidget wid={wid} />, defaultPosition: { x: 8, y: 0, w: 4, h: 5 } },
          ]}
        />
      ) : (
        <DashboardGrid
          ref={gridRef}
          wid={wid}
          role={role}
          locale=""
          editing={editing}
          onLayoutChange={handleLayoutChange}
          freeMode={freeMode}
          onFreeModeChange={handleFreeModeChange}
          density={density}
          onDensityChange={handleDensityChange}
        />
      )}

      {/* 添加 Widget 对话框 */}
      <AddWidgetDialog
        open={addDialogOpen}
        addedIds={layoutIds}
        onAdd={handleAddWidget}
        onClose={() => setAddDialogOpen(false)}
      />

      {/* Onboarding 引导：仅在工作区无任务且未标记完成时显示 */}
      {wsLoaded && taskCount === 0 && !onboardingDismissed && (
        <Onboarding
          wid={wid}
          taskCount={taskCount}
          memberCount={0}
          onDismiss={() => setOnboardingDismissed(true)}
        />
      )}
    </div>
  );
}

"use client";

import { use, useCallback, useEffect, useRef, useState } from "react";

import {
  Calendar as CalendarIcon,
  Check,
  Loader2,
  AlertTriangle,
  RefreshCw,
  Link2,
  Unlink,
  Mail,
  Clock,
} from "lucide-react";
import { useTranslations } from "next-intl";
import { api } from "@/lib/api";
import { useToast } from "@/components/Toast";
import { relTime as sharedRelTime } from "@/lib/format";

/** 连接状态 */
interface ConnectionStatus {
  provider: string;
  email: string;
  connected: boolean;
  lastSyncAt: string | null;
  syncStatus: string;
  syncError: string | null;
}

/** 同步设置（本地存储） */
interface SyncSettings {
  syncDueDateOnly: boolean;
  remindOneDay: boolean;
  remindOneHour: boolean;
}

// R8B-12：localStorage key 按工作区隔离，防止不同工作区的同步设置互相覆盖
const getSyncSettingsKey = (wid: string) => `corps_calendar_sync_settings_${wid}`;

function loadSyncSettings(wid: string): SyncSettings {
  try {
    const raw = localStorage.getItem(getSyncSettingsKey(wid));
    if (raw) return JSON.parse(raw) as SyncSettings;
  } catch {
    /* ignore */
  }
  return { syncDueDateOnly: true, remindOneDay: true, remindOneHour: false };
}

function saveSyncSettings(wid: string, s: SyncSettings): void {
  localStorage.setItem(getSyncSettingsKey(wid), JSON.stringify(s));
}

export default function CalendarSettingsPage({ params }: { params: Promise<{ wid: string }> }) {
  const { wid } = use(params);

  const t = useTranslations("calendar");
  const tTime = useTranslations("time");
  const { toast } = useToast();
  const relTime = (iso: string | null) => (iso ? sharedRelTime(iso, tTime) : "—");
  const [connections, setConnections] = useState<ConnectionStatus[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [syncing, setSyncing] = useState(false);
  const [syncMsg, setSyncMsg] = useState<{ kind: "success" | "error"; text: string } | null>(null);
  const [disconnecting, setDisconnecting] = useState<string | null>(null);
  const [syncSettings, setSyncSettings] = useState<SyncSettings>({
    syncDueDateOnly: true,
    remindOneDay: true,
    remindOneHour: false,
  });
  // 回调参数（连接成功/失败）
  const [callbackMsg, setCallbackMsg] = useState<{
    kind: "success" | "error";
    text: string;
  } | null>(null);
  // R9B-09：存储同步消息自动清除的 timeout ID，组件卸载时清理避免在已卸载组件上 setState
  const syncMsgTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const load = useCallback(async () => {
    try {
      const data = await api<{ connections: ConnectionStatus[] }>(
        `/api/v1/workspaces/${wid}/calendar/status`,
      );
      setConnections(data.connections);
    } catch (e) {
      setError(e instanceof Error ? e.message : t("loadFailed"));
    } finally {
      setLoading(false);
    }
  }, [wid]);

  useEffect(() => {
    load();
    setSyncSettings(loadSyncSettings(wid));
    // 解析回调参数（?connected=google / ?error=xxx）
    const url = new URL(window.location.href);
    const connected = url.searchParams.get("connected");
    const errParam = url.searchParams.get("error");
    if (connected) {
      setCallbackMsg({ kind: "success", text: t("connected") });
      // 清理 URL 参数
      url.searchParams.delete("connected");
      window.history.replaceState({}, "", url.toString());
    } else if (errParam) {
      setCallbackMsg({ kind: "error", text: errParam });
      url.searchParams.delete("error");
      window.history.replaceState({}, "", url.toString());
    }
  }, [load, t, wid]);

