import { NextRequest, NextResponse } from "next/server";
import { runWithAuthOp, runWithWorkspace } from "@/lib/auth";
import { apiMsg } from "@/lib/api-messages";
import { generatePush, type PushCapability } from "@/lib/ai/push-runner";
import { logger } from "@/lib/logger";

/**
 * GET /api/cron/ai-push-runner — AI 主动推送自动执行器（每 30 分钟定时调用）
 *
 * 遍历所有 enabled 的 AiPushSchedule，对到期的 schedule 调用 generatePush 生成推送内容，
 * 成功后创建站内通知（Notification type=ai_push）。
 *
 * 逻辑：
 *  1. CRON_SECRET Bearer 鉴权（与 /api/cron/check-overdue-actions 同模式）
 *  2. runWithAuthOp("cron") 跨工作区查询 enabled schedule
 *  3. 对每个 schedule 用 isDueNow 判断到期（cron 表达式 + lastRunAt 去重）
 *  4. 到期的调用 generatePush（不传 tx，内部自建 RLS 事务，避免跨工作区串行失败传染）
 *  5. generatePush 成功后创建 Notification（type=ai_push, entityId=record.id）
 *  6. 返回 { checked, triggered, notified, skipped }
 *
 * 鉴权：CRON_SECRET Bearer（与 /api/cron/* 路由约定一致）。
 * 调度建议：每 30 分钟调用一次（entrypoint-cron.sh 中配置）。
 */

/** cron 字段匹配（支持 * / , - / 步进语法，与标准 cron 语义一致） */
function matchesCronField(
  field: string,
  value: number,
  min: number,
  max: number,
): boolean {
  if (field === "*") return true;
  for (const part of field.split(",")) {
    if (part.includes("/")) {
      const [range, step] = part.split("/");
      const stepNum = parseInt(step, 10);
      const lo = range === "*" ? min : parseInt(range, 10);
      if ((value - lo) % stepNum === 0 && value >= lo) return true;
    } else if (part.includes("-")) {
      const [lo, hi] = part.split("-").map(Number);
      if (value >= lo && value <= hi) return true;
    } else {
      if (value === parseInt(part, 10)) return true;
    }
  }
  return false;
}

/**
 * 判断 schedule 是否在当前时刻到期。
 *
 * 简化语义（满足业务场景：每日简报 / 风险预警 / 进度异常均为日级推送）：
 *  - 仅检查 minute / hour / day-of-week 三个字段（day-of-month / month 忽略）
 *  - lastRunAt 去重：若今天已运行过（lastRunAt >= todayStart）则不再触发
 *
 * 这意味着每个 schedule 每天最多触发一次，与 AiPushRecord 的语义一致。
 */
function isDueNow(cron: string, lastRunAt: Date | null, now: Date): boolean {
  const parts = cron.trim().split(/\s+/);
  if (parts.length !== 5) return false;
  const [min, hour, , , dow] = parts;
  if (!matchesCronField(min, now.getMinutes(), 0, 59)) return false;
  if (!matchesCronField(hour, now.getHours(), 0, 23)) return false;
  if (!matchesCronField(dow, now.getDay(), 0, 6)) return false;
  const todayStart = new Date(now);
  todayStart.setHours(0, 0, 0, 0);
  if (lastRunAt && lastRunAt >= todayStart) return false;
  return true;
}

export async function GET(req: NextRequest) {
  const secret = process.env.CRON_SECRET;
  if (!secret) {
    return NextResponse.json(
      { code: 500, message: apiMsg(req, "cronSecretNotConfigured"), data: null },
      { status: 500 },
    );
  }
  const authHeader = req.headers.get("authorization");
  if (authHeader !== `Bearer ${secret}`) {
    return NextResponse.json(
      { code: 401, message: apiMsg(req, "unauthorized"), data: null },
      { status: 401 },
    );
  }

  try {
    const now = new Date();

    // P1-fix: Notification 创建需要 workspace_id GUC，runWithAuthOp 事务内
    // 未设置该 GUC 会触发 RLS 拒绝。改为：事务内只读 schedule + 调 generatePush，
    // 把需要创建通知的成功结果收集到 triggeredSchedules；事务结束后逐个用
    // runWithWorkspace 包裹创建 Notification（每个独立 RLS 事务，失败仅 warn）。
    const triggeredSchedules: Array<{
      userId: string;
      workspaceId: string;
      capability: string;
      recordId: string;
    }> = [];

    // cron op 逃生口：跨工作区只读 schedule（与 check-overdue-actions 同模式）
    const result = await runWithAuthOp("cron", async (tx) => {
      // 1) 查询所有 enabled 的推送计划
      const schedules = await tx.aiPushSchedule.findMany({
        where: { enabled: true },
        select: {
          id: true,
          workspaceId: true,
          userId: true,
          capability: true,
          cron: true,
          lastRunAt: true,
        },
      });

      let triggered = 0;
      let skipped = 0;

      for (const schedule of schedules) {
        // 2) 判断是否到期
        if (!isDueNow(schedule.cron, schedule.lastRunAt, now)) {
          skipped++;
          continue;
        }

        // 3) 调用 generatePush 生成推送内容
        //    不传 tx：每个 schedule 独立 RLS 事务，避免跨工作区串行失败传染
        const pushResult = await generatePush({
          capability: schedule.capability as PushCapability,
          workspaceId: schedule.workspaceId,
          userId: schedule.userId,
          scheduleId: schedule.id,
        }).catch((e: unknown) => {
          logger.warn("[cron ai-push-runner] generatePush 抛异常", {
            error: e instanceof Error ? e.message : String(e),
            scheduleId: schedule.id,
            capability: schedule.capability,
            workspaceId: schedule.workspaceId,
          });
          return null;
        });

        if (!pushResult) {
          skipped++;
          continue;
        }
        triggered++;

        // 4) 收集成功结果，事务外再创建 Notification
        triggeredSchedules.push({
          userId: schedule.userId,
          workspaceId: schedule.workspaceId,
          capability: schedule.capability,
          recordId: pushResult.recordId,
        });
      }

      return { checked: schedules.length, triggered, skipped };
    });

    // 5) 事务结束后，逐个用 runWithWorkspace 包裹创建 Notification
    //    entityTitle 存储 i18n key（ai_push_${capability}），前端按 locale 翻译
    //    entityId = AiPushRecord.id，前端可查询推送详情
    //    type = "ai_push" 用于前端识别通知类型
    let notified = 0;
    for (const item of triggeredSchedules) {
      const ok = await runWithWorkspace(
        item.workspaceId,
        (tx) =>
          tx.notification.create({
            data: {
              userId: item.userId,
              workspaceId: item.workspaceId,
              type: "ai_push",
              entityId: item.recordId,
              entityTitle: `ai_push_${item.capability}`,
            },
          }),
        item.userId,
      )
        .then(() => true)
        .catch((e: unknown) => {
          logger.warn("[ai-push-runner] notification create failed", {
            error: e instanceof Error ? e.message : String(e),
            userId: item.userId,
            workspaceId: item.workspaceId,
            recordId: item.recordId,
          });
          return false;
        });
      if (ok) notified++;
    }

    return NextResponse.json({
      code: 200,
      data: { ...result, notified },
    });
  } catch (error) {
    logger.error("[cron ai-push-runner] error", {
      error: error instanceof Error ? error.message : String(error),
    });
    return NextResponse.json(
      { code: 500, message: apiMsg(req, "internalError"), data: null },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { apiMsg } from "@/lib/api-messages";
import { logger } from "@/lib/logger";

/**
 * 真实健康检查（而非静态 200）：
 * Docker healthcheck 与 CI 启动等待（curl /api/health）都依赖本端点判断服务
 * 是否真正可用——若只返回静态 JSON，DB 未就绪时容器也会被判定 healthy，
 * 流量会被路由到一个必然报错的实例。因此这里真实执行一条 SELECT 1 探测。
 */
export async function GET(req: NextRequest) {
  // Promise.race：DB 探测与 2 秒超时赛跑，防止 DB 挂起时 healthcheck 长时间阻塞
  const TIMEOUT_MS = 2_000;
  try {
    let timer: ReturnType<typeof setTimeout>;
    await Promise.race([
      prisma.$queryRaw`SELECT 1`,
      new Promise<never>((_, reject) => {
        timer = setTimeout(() => reject(new Error("Database probe timeout")), TIMEOUT_MS);
      }),
    ]);
    clearTimeout(timer!);
    return NextResponse.json({
      code: 200,
      data: {
        status: "ok",
        db: "up",
        // 进程运行秒数：供监控判断进程是否频繁重启（如 OOM/崩溃循环）
        uptimeSec: Math.round(process.uptime()),
      },
    });
  } catch (error) {
    logger.error("database probe failed", { endpoint: "health" });
    return NextResponse.json(
      {
        code: 503,
        data: { status: "degraded", db: "down" },
        message: apiMsg(req, "databaseUnreachable"),
      },
      { status: 503 },
    );
  }
}

// POST /api/v1/ai/approval-advice — AI 审批风控建议（流式 + 阶段化进度）
// 输入：{ wid, approvalInstanceId }
// 输出：text/event-stream（Vercel AI SDK UI Message Stream）
//   - data-progress part：{ stage, message } 阶段化进度
//   - data-result part：{ riskLevel, riskFactors, suggestion, similarCases } 最终结果
//
// 使用 deepseek-reasoner 推理模型分析审批内容 + 同类型历史审批，
// 为审批人提供风险等级、风险因素、建议和相似案例参考。
// 不替审批人做决定，仅提供分析参考。

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { requireReasonerModel, withCoT } from "@/lib/ai/deepseek";
import {
  getUserId,
  unauthorizedResponse,
  aiNotConfiguredResponse,
  isAiConfigured,
} from "@/lib/ai/shared";
import { checkRateLimit } from "@/lib/rate-limit";
import { getWorkspaceContext, runWithWorkspace } from "@/lib/auth";
import { cleanJsonResponse } from "@/lib/ai/orchestrator";
import { apiMsg } from "@/lib/api-messages";
import { buildApprovalAdviceSystemPrompt, buildUserPrompt } from "@/lib/ai/prompts/approval-advice";
import { createAiJsonProgressStream } from "@/lib/ai/stream";

const schema = z.object({
  wid: z.string().uuid(),
  approvalInstanceId: z.string().uuid(),
});

/** AI 返回的风控建议结构 */
interface ApprovalAdvice {
  riskLevel: "low" | "medium" | "high";
  riskFactors: string[];
  suggestion: string;
  similarCases: {
    title: string;
    result: "approved" | "rejected";
    amount: number;
  }[];
}


/** 日期 → YYYY-MM-DD */
function dateStr(d: Date): string {
  return d.toISOString().split("T")[0];
}

/**
 * 将审批实例 + 历史审批聚合成 markdown 上下文供 LLM 使用。
 */
function buildContext(
  instance: {
    title: string;
    description: string | null;
    content: unknown;
    status: string;
    templateId: string | null;
    submittedAt: Date;
  },
  history: {
    title: string;
    status: string;
    content: unknown;
    submittedAt: Date;
  }[],
): string {
  const sections: string[] = [];

  // 当前审批
  sections.push(
    [
      "## 当前审批",
      `- 标题: ${instance.title}`,
      `- 描述: ${instance.description ?? "无"}`,
      `- 状态: ${instance.status}`,
      `- 提交时间: ${dateStr(instance.submittedAt)}`,
      `- 审批内容: ${JSON.stringify(instance.content)}`,
    ].join("\n"),
  );

  // 历史审批
  if (history.length > 0) {
    const lines = history.map(
      (h) =>
        `- ${h.title} (结果: ${h.status === "approved" ? "通过" : "驳回"}, 提交: ${dateStr(h.submittedAt)})`,
    );
    sections.push(
      `## 同类型历史审批（最近 ${history.length} 条）\n${lines.join("\n")}`,
    );
  } else {
    sections.push("## 同类型历史审批\n无");
  }

  return sections.join("\n\n");
}

export async function POST(req: NextRequest) {
  // 1) 认证
  const userId = await getUserId(req);
  if (!userId) return unauthorizedResponse(req);

  // 2) AI 服务配置检查
  if (!isAiConfigured()) return aiNotConfiguredResponse(req);

  // 3) 速率限制：每分钟 10 次
  const limited = await checkRateLimit(req, "ai-approval-advice", {
    windowMs: 60_000,
    max: 10,
  });
  if (limited) return limited;

  // 4) body 校验
  let body: z.infer<typeof schema>;
  try {
    body = schema.parse(await req.json());
  } catch (e) {
    if (e instanceof z.ZodError) {
      return NextResponse.json(
        {
          code: 400,
          message: e.issues[0]?.message ?? apiMsg(req, "validationFailed"),
          data: null,
        },
        { status: 400 },
      );
    }
    return NextResponse.json(
      { code: 400, message: apiMsg(req, "invalidBody"), data: null },
      { status: 400 },
    );
  }

  // 5) 工作区认证（RLS 成员资格校验）
  const ctx = await getWorkspaceContext(req, body.wid);
  if (!ctx) {
    return NextResponse.json(
      { code: 401, message: apiMsg(req, "unauthorized"), data: null },
      { status: 401 },
    );
  }

  try {
    // 6) 流式生成审批建议（带阶段化进度反馈）
    //    buildPrompt 封装审批实例查询 + 历史审批聚合 + 上下文构建，
    //    让进度阶段有真实时序：
    //    阶段 1（聚合审批数据）→ 查询+聚合 → 阶段 2（分析风险）→ 阶段 3（生成建议）→ LLM → 结果 data part
    return createAiJsonProgressStream<ApprovalAdvice>(
      {
        model: requireReasonerModel(),
        system: withCoT(buildApprovalAdviceSystemPrompt(), requireReasonerModel()),
        buildPrompt: async () => {
          try {
            const data = await runWithWorkspace(
              body.wid,
              async (tx) => {
                const inst = await tx.approvalInstance.findFirst({
                  where: { id: body.approvalInstanceId, workspaceId: body.wid },
                  select: {
                    title: true,
                    description: true,
                    content: true,
                    status: true,
                    templateId: true,
                    submittedAt: true,
                  },
                });

                if (!inst) return null;

                // 同类型历史审批：相同 templateId，排除当前实例，最近 20 条已处理
                const hist = await tx.approvalInstance.findMany({
                  where: {
                    workspaceId: body.wid,
                    id: { not: body.approvalInstanceId },
                    status: { in: ["approved", "rejected"] },
                    ...(inst.templateId ? { templateId: inst.templateId } : {}),
                  },
                  take: 20,
                  orderBy: { submittedAt: "desc" },
                  select: {
                    title: true,
                    status: true,
                    content: true,
                    submittedAt: true,
                  },
                });

                return { instance: inst, history: hist };
              },
              // 用 JWT payload.sub 而非 getUserId 返回值，与 daily-report/project-insight 一致
              ctx.payload.sub,
            );

            if (!data) {
              // 审批实例不存在，抛异常 → stream error part → 前端显示错误
              throw new Error("approval instance not found");
            }

            const context = buildContext(data.instance, data.history);
            return buildUserPrompt(context);
          } catch (e) {
            // 内部错误不泄露给前端（可能包含 Prisma 错误消息等敏感信息）
            if (
              e instanceof Error &&
              e.message === "approval instance not found"
            ) {
              throw new Error("审批实例不存在");
            }
            throw new Error("获取审批数据失败");
          }
        },
        parseResult: (text: string): ApprovalAdvice => {
          try {
            const parsed = JSON.parse(cleanJsonResponse(text)) as Partial<ApprovalAdvice>;
            return {
              riskLevel: parsed.riskLevel ?? "low",
              riskFactors: Array.isArray(parsed.riskFactors)
                ? parsed.riskFactors.filter(
                    (f): f is string => typeof f === "string",
                  )
                : [],
              suggestion:
                typeof parsed.suggestion === "string" ? parsed.suggestion : "",
              similarCases: Array.isArray(parsed.similarCases)
                ? parsed.similarCases.filter(
                    (c): c is ApprovalAdvice["similarCases"][number] =>
                      c != null &&
                      typeof c.title === "string" &&
                      (c.result === "approved" || c.result === "rejected") &&
                      typeof c.amount === "number",
                  )
                : [],
            };
          } catch {
            // JSON 解析失败，返回降级空建议
            return {
              riskLevel: "low",
              riskFactors: [],
              suggestion: "",
              similarCases: [],
            };
          }
        },
        usageTracking: {
          workspaceId: body.wid,
          userId: ctx.payload.sub,
          capability: "approval-advice",
          model: requireReasonerModel().modelId,
        },
      },
      {
        context: "正在聚合审批数据…",
        analyzing: "正在分析审批风险…",
        generating: "正在生成审批建议…",
      },
    );
  } catch (error) {
    console.error("[ai/approval-advice] error:", error);
    return NextResponse.json(
      { code: 500, message: apiMsg(req, "internalError"), data: null },
      { status: 500 },
    );
  }
}

// GET /api/v1/ai/assistant/suggestions — AI 助理建议能力列表
//
// 输入：?phase=in_progress（query param，默认 in_progress）
// 流程：
//   1. 认证
//   2. 按 phase 返回建议能力列表（getSuggestionsForPhase）
//
// 用途：前端在任务详情页根据当前阶段展示 AI 助理可用的能力入口。
//
// 来源：P2 后端任务 318（AI 助理编排引擎 + 对话 API）

import { NextRequest, NextResponse } from "next/server";
import { getUserId, unauthorizedResponse } from "@/lib/ai/shared";
import { checkRateLimit } from "@/lib/rate-limit";
import { apiMsg } from "@/lib/api-messages";
import {
  getSuggestionsForPhase,
  type TaskPhase,
} from "@/lib/ai/assistant/orchestrator";

/** 合法阶段集合（与 orchestrator.ts TaskPhase 保持一致） */
const VALID_PHASES = new Set<TaskPhase>([
  "created",
  "in_progress",
  "review",
  "completed",
  "blocked",
]);

/** GET /api/v1/ai/assistant/suggestions — 按任务阶段返回建议能力 */
export async function GET(req: NextRequest) {
  // 1) 认证
  const userId = await getUserId(req);
  if (!userId) return unauthorizedResponse(req);

  // P1-fix: 速率限制——每分钟 60 次，防止前端轮询/滥用
  const limited = await checkRateLimit(req, "ai-assistant-suggestions", {
    windowMs: 60_000,
    max: 60,
  });
  if (limited) return limited;

  // 2) 解析 phase query param（默认 in_progress，非法值降级为 in_progress）
  const rawPhase = req.nextUrl.searchParams.get("phase") ?? "in_progress";
  const phase: TaskPhase = VALID_PHASES.has(rawPhase as TaskPhase)
    ? (rawPhase as TaskPhase)
    : "in_progress";

  // 3) 返回建议能力列表
  const suggestions = getSuggestionsForPhase(phase);

  return NextResponse.json({ code: 0, data: { phase, suggestions } });
}

// POST /api/v1/ai/knowledge/query — 基于知识图谱的深度问答（非流式）
// 输入：{ wid, question: string }
// 输出：{ code: 200, data: { answer: string, relatedNodes: KnowledgeNode[] } }
//
// 流程：
//   1. 认证 + AI 配置检查 + 限流 + body 校验 + 工作区上下文校验
//   2. 在 RLS 事务内检索相关节点（关键词匹配 label/content）
//   3. generateText（defaultModel + withCoT）基于检索到的知识点生成回答
//   4. withUsageTracking 包装

import { NextRequest, NextResponse } from "next/server";
import { generateText } from "ai";
import { z } from "zod";
import { requireDefaultModel, withCoT } from "@/lib/ai/deepseek";
import {
  getUserId,
  unauthorizedResponse,
  aiNotConfiguredResponse,
  isAiConfigured,
} from "@/lib/ai/shared";
import { withUsageTracking } from "@/lib/ai/usage-middleware";
import { getWorkspaceContext, runWithWorkspace } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { apiMsg } from "@/lib/api-messages";

const schema = z.object({
  wid: z.string().uuid(),
  question: z.string().min(1).max(2000),
});

/** 检索相关节点的最大数量 */
const MAX_RELATED_NODES = 20;
/** 单个关键词最大长度 */
const MAX_KEYWORD_LEN = 50;

/**
 * 从问题中提取检索关键词（简单分词）。
 * 按空格/标点分割，过滤空字符串和过长 token。
 */
function extractKeywords(question: string): string[] {
  return question
    .split(/[\s,，。.!?！？;；:：、（）()【】\[\]{}""''`]+/)
    .map((s) => s.trim())
    .filter((s) => s.length > 0 && s.length <= MAX_KEYWORD_LEN)
    .slice(0, 10);
}

export async function POST(req: NextRequest) {
  // 1) 认证
  const userId = await getUserId(req);
  if (!userId) return unauthorizedResponse(req);

  // 2) AI 服务配置检查
  if (!isAiConfigured()) return aiNotConfiguredResponse(req);

  // 3) 速率限制：每分钟 10 次
  const limited = await checkRateLimit(req, "ai-knowledge-query", {
    windowMs: 60_000,
    max: 10,
  });
  if (limited) return limited;

  // 4) body 校验
  let body: z.infer<typeof schema>;
  try {
    body = schema.parse(await req.json());
  } catch (e) {
    if (e instanceof z.ZodError) {
      return NextResponse.json(
        {
          code: 400,
          message: e.issues[0]?.message ?? apiMsg(req, "validationFailed"),
          data: null,
        },
        { status: 400 },
      );
    }
    return NextResponse.json(
      { code: 400, message: apiMsg(req, "invalidBody"), data: null },
      { status: 400 },
    );
  }

  // 5) 工作区上下文校验
  const ctx = await getWorkspaceContext(req, body.wid);
  if (!ctx) {
    return NextResponse.json(
      { code: 401, message: apiMsg(req, "unauthorized"), data: null },
      { status: 401 },
    );
  }

  // 6) 检索相关节点 + AI 生成回答
  try {
    // 6.1) 在 RLS 事务内检索相关节点（关键词匹配 label/content）
    const keywords = extractKeywords(body.question);

    const relatedNodes = await runWithWorkspace(
      body.wid,
      async (tx) => {
        if (keywords.length === 0) return [];

        // 用 OR 条件检索：label 或 content 包含任一关键词
        // Prisma 的 contains + mode: insensitive 支持大小写不敏感
        const orConditions = keywords.flatMap((kw) => [
          { label: { contains: kw, mode: "insensitive" as const } },
          { content: { contains: kw, mode: "insensitive" as const } },
        ]);

        return tx.knowledgeNode.findMany({
          where: {
            workspaceId: body.wid,
            OR: orConditions,
          },
          take: MAX_RELATED_NODES,
          orderBy: { updatedAt: "desc" },
          select: {
            id: true,
            type: true,
            label: true,
            content: true,
            sourceType: true,
            sourceId: true,
          },
        });
      },
      ctx.payload.sub,
    );

    // 6.2) 组装上下文
    const contextMarkdown =
      relatedNodes.length > 0
        ? relatedNodes
            .map(
              (n) =>
                `### ${n.label}（类型：${n.type}）\n${n.content}\n来源：${n.sourceType}`,
            )
            .join("\n\n")
        : "（未检索到相关知识点）";

    const systemPrompt = withCoT(
      `你是企业知识图谱问答助手。基于检索到的知识图谱节点回答用户问题。

## 回答规则
1. 仅基于提供的知识点回答，不要编造不存在的信息
2. 如果知识点不足以回答，明确告知用户并建议补充更多知识来源
3. 回答用 Markdown 格式，结构清晰
4. 引用知识点时标注其类型和来源
5. 中文回答

## 检索到的知识点
${contextMarkdown}`,
      requireDefaultModel(),
    );

    // 6.3) AI 生成回答（非流式，withUsageTracking 包装）
    const answer = await withUsageTracking(
      {
        workspaceId: body.wid,
        userId: ctx.payload.sub,
        capability: "knowledge-query",
        model: requireDefaultModel().modelId,
      },
      async () => {
        const llmResult = await generateText({
          model: requireDefaultModel(),
          system: systemPrompt,
          prompt: body.question,
        });
        return {
          result: llmResult.text,
          usage: {
            inputTokens: llmResult.usage.inputTokens ?? 0,
            outputTokens: llmResult.usage.outputTokens ?? 0,
          },
        };
      },
    );

    return NextResponse.json({
      code: 200,
      data: { answer, relatedNodes },
    });
  } catch (error) {
    console.error("[ai/knowledge/query] error:", error);
    return NextResponse.json(
      { code: 500, message: apiMsg(req, "internalError"), data: null },
      { status: 500 },
    );
  }
}

// POST /api/v1/ai/meeting-summary — AI 生成完整会议纪要（非流式）
// 输入：{ wid, transcript (1-50000), meetingTitle?, sessionId? }
// 输出：{ code: 0, data: { title, keyPoints, decisions, actionItems, participants }, message }
//
// 流程：
//   1. 认证 + AI 配置检查 + 速率限制
//   2. body 校验（transcript 1-50000 字符）
//   3. 工作区认证（RLS 成员资格校验）
//   4. reasonerModel 生成完整纪要（withCoT + withUsageTracking）
//   5. cleanJsonResponse + JSON.parse 解析 JSON 结果
//   6. 规范化提取 title / keyPoints / decisions / actionItems / participants
//   7. 返回纪要
//
// 来源：
//  - 经验 2026-09-15-usage-tracking-per-call-site-integration-by-mode（withUsageTracking 非流式包装）
//  - 经验 2026-09-15-ai-route-streaming-mode-and-model-pairing-rules（reasonerModel + withCoT）
//  - 经验 2026-09-15-ai-route-unified-pattern-audit-checklist（checkRateLimit + try-catch）

import { NextRequest, NextResponse } from "next/server";
import { generateText } from "ai";
import { z } from "zod";
import { requireReasonerModel, withCoT } from "@/lib/ai/deepseek";
import {
  getUserId,
  unauthorizedResponse,
  aiNotConfiguredResponse,
  isAiConfigured,
} from "@/lib/ai/shared";
import { withUsageTracking } from "@/lib/ai/usage-middleware";
import { cleanJsonResponse } from "@/lib/ai/orchestrator";
import { getWorkspaceContext } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { apiMsg } from "@/lib/api-messages";
import {
  buildMeetingSummarySystemPrompt,
  buildMeetingSummaryUserPrompt,
} from "@/lib/ai/prompts/meeting-summary";

/** 请求 body schema */
const schema = z.object({
  wid: z.string().uuid(),
  transcript: z.string().min(1).max(50000),
  meetingTitle: z.string().max(200).optional(),
  sessionId: z.string().uuid().optional(),
});

/** 有效的优先级枚举 */
const VALID_PRIORITIES = new Set(["low", "medium", "high", "urgent"]);

/** 规范化后的决策项 */
interface NormalizedDecision {
  title: string;
  description: string;
}

/** 规范化后的待办事项 */
interface NormalizedActionItem {
  title: string;
  assignee: string | null;
  dueDate: string | null;
  priority: "low" | "medium" | "high" | "urgent";
}

/** 规范化后的会议纪要（返回给前端） */
interface MeetingSummary {
  title: string;
  keyPoints: string[];
  decisions: NormalizedDecision[];
  actionItems: NormalizedActionItem[];
  participants: string[];
}

/**
 * 规范化 AI 返回的会议纪要。
 *
 * 校验各字段类型，截断超长字段，丢弃非法条目。
 *
 * @param raw JSON.parse 后的原始对象
 * @returns 规范化后的 MeetingSummary，校验失败返回 null
 */
function normalizeMeetingSummary(raw: unknown): MeetingSummary | null {
  if (raw == null || typeof raw !== "object") return null;
  const obj = raw as Record<string, unknown>;

  // title：必填字符串，截断至 100
  const title =
    typeof obj.title === "string" && obj.title.trim()
      ? obj.title.slice(0, 100)
      : "";

  // keyPoints：字符串数组，最多 15 条，每条截断至 200
  const keyPoints: string[] = [];
  if (Array.isArray(obj.keyPoints)) {
    for (const point of obj.keyPoints) {
      if (typeof point !== "string" || !point.trim()) continue;
      keyPoints.push(point.slice(0, 200));
      if (keyPoints.length >= 15) break;
    }
  }

  // decisions：数组，最多 20 条
  const decisions: NormalizedDecision[] = [];
  if (Array.isArray(obj.decisions)) {
    for (const item of obj.decisions) {
      if (item == null || typeof item !== "object") continue;
      const d = item as Record<string, unknown>;
      if (typeof d.title !== "string" || !d.title.trim()) continue;
      decisions.push({
        title: d.title.slice(0, 200),
        description:
          typeof d.description === "string" ? d.description.slice(0, 500) : "",
      });
      if (decisions.length >= 20) break;
    }
  }

  // actionItems：数组，最多 20 条
  const actionItems: NormalizedActionItem[] = [];
  if (Array.isArray(obj.actionItems)) {
    for (const item of obj.actionItems) {
      if (item == null || typeof item !== "object") continue;
      const a = item as Record<string, unknown>;
      if (typeof a.title !== "string" || !a.title.trim()) continue;
      // 校验截止日期格式（YYYY-MM-DD）
      let dueDate: string | null = null;
      if (typeof a.dueDate === "string" && a.dueDate.trim()) {
        const parsed = new Date(a.dueDate);
        if (!isNaN(parsed.getTime())) {
          dueDate = parsed.toISOString().slice(0, 10);
        }
      }
      // 校验优先级
      const priority =
        typeof a.priority === "string" && VALID_PRIORITIES.has(a.priority)
          ? (a.priority as NormalizedActionItem["priority"])
          : "medium";
      actionItems.push({
        title: a.title.slice(0, 200),
        assignee:
          typeof a.assignee === "string" && a.assignee.trim()
            ? a.assignee.slice(0, 100)
            : null,
        dueDate,
        priority,
      });
      if (actionItems.length >= 20) break;
    }
  }

  // participants：字符串数组，去重，每个截断至 100
  const participants: string[] = [];
  if (Array.isArray(obj.participants)) {
    const seen = new Set<string>();
    for (const p of obj.participants) {
      if (typeof p !== "string" || !p.trim()) continue;
      const name = p.slice(0, 100);
      if (seen.has(name)) continue;
      seen.add(name);
      participants.push(name);
    }
  }

  return { title, keyPoints, decisions, actionItems, participants };
}

/**
