/**
 * GET /v1/workspaces/{wid}/approvals/instances/{aid} — 审批详情
 * 含 operations 操作记录（按 createdAt 正序）
 * 返回字段：
 *  - applicant: { id, name, email } 嵌套对象
 *  - operations[].operator: { id, name, email } 嵌套对象
 *  - templateName: 关联模板名称（无模板时为 null）
 *  - currentApproverIds: 当前审批节点的审批人用户 ID 数组（status !== pending 时为 []）
 *  - aiSuggestion: AI 审批建议（M4，未配置 AI 时为 null）
 *  - entityType / entityId: 审批关联的实体类型和 ID（M6，从 content JSON 提取）
 */
export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ wid: string; aid: string }> },
) {
  const { wid, aid } = await params;
  const ctx = await getWorkspaceContext(req, wid);
  if (!ctx) return NextResponse.json({ code: 401, message: apiMsg(req, "unauthorized"), data: null }, { status: 401 });

  try {
    const result = await runWithWorkspace(
      wid,
      async (tx) => {
        const instance = await tx.approvalInstance.findUnique({
          where: { id: aid },
          include: {
            applicant: { select: { id: true, name: true, email: true } },
            template: { select: { id: true, name: true } },
            operations: {
              orderBy: [{ createdAt: "asc" }],
              include: {
                operator: { select: { id: true, name: true, email: true } },
              },
            },
          },
        });

        if (!instance || instance.workspaceId !== wid) {
          return { kind: "notFound" as const };
        }

        // 计算当前审批节点的审批人 ID 数组
        let currentApproverIds: string[] = [];
        if (instance.status === "pending") {
          const nodes = instance.nodes as unknown as ApprovalNode[];
          const currentNode = nodes[instance.currentNode];
          if (currentNode) {
            const approverIds = new Set<string>();
            // 节点直接指定的审批人
            if (currentNode.approverUserId) {
              approverIds.add(currentNode.approverUserId);
            }
            // 按角色指定的审批人：查询该工作区下该角色的所有成员
            if (currentNode.approverRole) {
              const roleMembers = await tx.member.findMany({
                where: { workspaceId: wid, role: currentNode.approverRole },
                select: { userId: true },
              });
              for (const m of roleMembers) approverIds.add(m.userId);
            }
            currentApproverIds = Array.from(approverIds);
          }
        }

        return {
          kind: "ok" as const,
          instance,
          currentApproverIds,
          templateName: instance.template?.name ?? null,
        };
      },
      ctx.payload.sub,
    );

    if (result.kind === "notFound") {
      return NextResponse.json(
        { code: 404, message: apiMsg(req, "approvalNotFound"), data: null },
        { status: 404 },
      );
    }

    // 响应：扁平化 templateName + currentApproverIds，保留 applicant/operator 嵌套对象
    const { template, ...instanceRest } = result.instance;

    // M6: 从 content JSON 中提取 entityType / entityId（支持审批关联到任务/文档/自定义实体）
    const contentObj = result.instance.content as Record<string, unknown> | null;
    const entityType =
      contentObj && typeof contentObj.entityType === "string"
        ? contentObj.entityType
        : null;
    const entityId =
      contentObj && typeof contentObj.entityId === "string"
        ? contentObj.entityId
        : null;

    // M4: AI 审批建议 — 使用 isAiConfigured() 检查，未配置时返回 null
    // 配置时返回 { available: true }，前端可调用 /api/v1/ai/approval-advice 流式获取实际建议
    const aiSuggestion = isAiConfigured()
      ? { available: true as const }
      : null;

    return NextResponse.json({
      code: 200,
      data: {
        ...instanceRest,
        templateName: result.templateName,
        currentApproverIds: result.currentApproverIds,
        // M4: AI 审批建议
        aiSuggestion,
        // M6: content 无强关联 — 提取 entityType / entityId
        entityType,
        entityId,
      },
    });
  } catch (error) {
    console.error("[GET approval-instance] error:", error);
    return NextResponse.json(
      { code: 500, data: null, message: apiMsg(req, "internalError") },
      { status: 500 },
    );
  }
}
/**
 * DELETE /v1/workspaces/{wid}/approvals/instances/{aid} — 撤销审批实例（L4）
 * 仅允许申请人撤销 pending 状态的实例
 * 创建 ApprovalOperation(action="withdraw")，设 status="withdrawn", completedAt=now
 * 保留审计记录，不实际删除行
 */
export async function DELETE(
  req: NextRequest,
  { params }: { params: Promise<{ wid: string; aid: string }> },
) {
  const { wid, aid } = await params;
  const ctx = await getWorkspaceContext(req, wid);
  if (!ctx)
    return NextResponse.json(
      { code: 401, message: apiMsg(req, "unauthorized"), data: null },
      { status: 401 },
    );

  try {
    const result = await runWithWorkspace(
      wid,
      async (tx) => {
        const instance = await tx.approvalInstance.findUnique({
          where: { id: aid },
        });
        if (!instance || instance.workspaceId !== wid) {
          return { kind: "notFound" as const };
        }
        // 只有申请人可操作
        if (instance.applicantId !== ctx.payload.sub) {
          return { kind: "notApplicant" as const };
        }
        // status 必须为 pending
        if (instance.status !== "pending") {
          return { kind: "notPending" as const };
        }

        // 创建撤回操作记录
        await tx.approvalOperation.create({
          data: {
            instanceId: aid,
            workspaceId: wid,
            operatorId: ctx.payload.sub,
            action: "withdraw",
            nodeIndex: instance.currentNode,
          },
        });

        // 撤销：设 status="withdrawn", completedAt=now（保留审计记录）
        const updated = await tx.approvalInstance.update({
          where: { id: aid },
          data: { status: "withdrawn", completedAt: new Date() },
        });

        return { kind: "ok" as const, data: updated };
      },
      ctx.payload.sub,
    );

    if (result.kind === "notFound") {
      return NextResponse.json(
        { code: 404, message: apiMsg(req, "approvalNotFound"), data: null },
        { status: 404 },
      );
    }
    if (result.kind === "notApplicant") {
      return NextResponse.json(
        { code: 403, message: apiMsg(req, "notApplicant"), data: null },
        { status: 403 },
      );
    }
    if (result.kind === "notPending") {
      return NextResponse.json(
        { code: 409, message: apiMsg(req, "approvalNotPending"), data: null },
        { status: 409 },
      );
    }

    return NextResponse.json({ code: 200, data: result.data });
  } catch (error) {
    console.error("[DELETE approval-instance] error:", error);
    return NextResponse.json(
      { code: 500, data: null, message: apiMsg(req, "internalError") },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getWorkspaceContext, runWithWorkspace } from "@/lib/auth";
import { z } from "zod";
import { apiMsg } from "@/lib/api-messages";
import { handlePrismaError } from "@/lib/prisma-error";

/**
 * 跨内容全文搜索 API
 *
 * GET /v1/workspaces/{wid}/search?q=keyword&type=all|document|task|decision&limit=20
 *
 * 搜索范围：
 *  - Document: title + markdown（ILIKE 模糊匹配）
 *  - Task:     title + description（ILIKE）
 *  - Decision: markdown（ILIKE；Decision 无 title 字段，用所属 task title 作展示标题）
 *
 * 返回统一格式：{ items: [{ type, id, title, snippet, href, updatedAt }] }
 *  - snippet 是匹配上下文摘要（匹配关键词前后各 50 字符），已 escapeHtml
 *  - 每类型最多 10 条，总上限 20
 *  - 权限：runWithWorkspace 确保租户隔离
 */

const querySchema = z.object({
  q: z.string().min(1).max(200),
  type: z.enum(["all", "document", "task", "decision"]).default("all"),
  limit: z.string().nullish(),
});

/** 每类型返回上限 */
const PER_TYPE_LIMIT = 10;
/** 默认总上限 */
const DEFAULT_LIMIT = 20;
/** 总上限硬顶（防止过大 take 拖垮查询） */
const MAX_LIMIT = 100;
/** snippet 上下文半径（匹配关键词前后各 50 字符） */
const SNIPPET_RADIUS = 50;

/** 搜索结果统一项 */
interface SearchItem {
  type: "document" | "task" | "decision";
  id: string;
  title: string;
  snippet: string;
  href: string;
  updatedAt: string;
}

/**
 * 生成匹配上下文 snippet：在 text 中定位 query 命中位置，
 * 截取前后各 SNIPPET_RADIUS 字符。
 *
 * 返回原始文本（未 HTML 转义）——前端用 React JSX 渲染时自动转义防 XSS，
 * 且 highlight 函数可正常在 snippet 上高亮关键词。
 * escapeHtml() 函数保留供非 React 客户端使用。
 *
 * 若 text 为空或未命中，返回 text 的前 (2 * SNIPPET_RADIUS) 字符摘要。
 */
function buildSnippet(text: string | null | undefined, query: string): string {
  const content = text ?? "";
  if (!content) return "";
  const lower = content.toLowerCase();
  const idx = lower.indexOf(query.toLowerCase());
  if (idx === -1) {
    // 未在 content 命中（可能在 title 命中）：返回开头摘要
    return content.slice(0, SNIPPET_RADIUS * 2);
  }
  const start = Math.max(0, idx - SNIPPET_RADIUS);
  const end = Math.min(content.length, idx + query.length + SNIPPET_RADIUS);
  const prefix = start > 0 ? "…" : "";
  const suffix = end < content.length ? "…" : "";
  return prefix + content.slice(start, end) + suffix;
}

/**
 * HTML 转义：防 snippet 注入 XSS（<>&"' 五个字符）。
 * 保留供非 React 客户端（如导出、邮件）使用；前端 React JSX 渲染自动转义。
 */
function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/** GET /v1/workspaces/{wid}/search — 跨内容全文搜索 */
export async function GET(req: NextRequest, { params }: { params: Promise<{ wid: string }> }) {
  const { wid } = await params;
  const ctx = await getWorkspaceContext(req, wid);
  if (!ctx)
    return NextResponse.json(
      { code: 401, message: apiMsg(req, "unauthorized"), data: null },
      { status: 401 },
    );

  try {
    const url = new URL(req.url);
    const parsed = querySchema.safeParse({
      q: url.searchParams.get("q"),
      type: url.searchParams.get("type") ?? "all",
      limit: url.searchParams.get("limit"),
    });
    if (!parsed.success) {
      return NextResponse.json(
        { code: 400, message: apiMsg(req, "validationFailed"), errors: parsed.error.errors, data: null },
        { status: 400 },
      );
    }

    const q = parsed.data.q.trim();
    // trim 后若为空字符串（纯空格输入），返回 400 避免匹配全部记录
    if (!q) {
      return NextResponse.json(
        { code: 400, message: apiMsg(req, "searchQueryBlank"), data: null },
        { status: 400 },
      );
    }

    // parseInt 后可能为 NaN，需兜底为默认值；clamp 到 [1, MAX_LIMIT]
    const parsedLimit = parseInt(parsed.data.limit ?? String(DEFAULT_LIMIT), 10);
    const limit = Number.isNaN(parsedLimit)
      ? DEFAULT_LIMIT
      : Math.min(Math.max(parsedLimit, 1), MAX_LIMIT);

    const type = parsed.data.type;
    const items: SearchItem[] = [];

    await runWithWorkspace(wid, async (tx) => {
      // ── Document 搜索：title + markdown ──
      if (type === "all" || type === "document") {
        const docs = await tx.document.findMany({
          where: {
            workspaceId: wid,
            OR: [
              { title: { contains: q, mode: "insensitive" } },
              { markdown: { contains: q, mode: "insensitive" } },
            ],
          },
          select: { id: true, title: true, markdown: true, updatedAt: true },
          take: PER_TYPE_LIMIT,
          orderBy: { updatedAt: "desc" },
        });
        for (const d of docs) {
          items.push({
            type: "document",
            id: d.id,
            title: d.title,
            snippet: buildSnippet(d.markdown, q),
            href: `/w/${wid}/documents/${d.id}`,
            updatedAt: d.updatedAt.toISOString(),
          });
        }
      }

      // ── Task 搜索：title + description ──
      if (type === "all" || type === "task") {
        const tasks = await tx.task.findMany({
          where: {
            workspaceId: wid,
            OR: [
              { title: { contains: q, mode: "insensitive" } },
              { description: { contains: q, mode: "insensitive" } },
            ],
          },
          select: { id: true, title: true, description: true, updatedAt: true },
          take: PER_TYPE_LIMIT,
          orderBy: { updatedAt: "desc" },
        });
        for (const t of tasks) {
          items.push({
            type: "task",
            id: t.id,
            title: t.title,
            snippet: buildSnippet(t.description, q),
            href: `/w/${wid}/task/${t.id}`,
            updatedAt: t.updatedAt.toISOString(),
          });
        }
      }

      // ── Decision 搜索：markdown（Decision 无 title 字段，用 task title 作展示标题）──
      if (type === "all" || type === "decision") {
        const decisions = await tx.decision.findMany({
          where: {
            workspaceId: wid,
            markdown: { contains: q, mode: "insensitive" },
          },
          select: {
            id: true,
            markdown: true,
            version: true,
            taskId: true,
            updatedAt: true,
            task: { select: { title: true } },
          },
          take: PER_TYPE_LIMIT,
          orderBy: { updatedAt: "desc" },
        });
        for (const d of decisions) {
          items.push({
            type: "decision",
            id: d.id,
            // 决策无独立 title：用所属任务标题 + 版本号作展示标题
            title: `${d.task.title} · v${d.version}`,
            snippet: buildSnippet(d.markdown, q),
            // 选中决策后跳转到决策列表页（任务要求）
            href: `/w/${wid}/decisions`,
            updatedAt: d.updatedAt.toISOString(),
          });
        }
      }
    });

    // 按 updatedAt 倒序排列，并截断到 limit
    items.sort((a, b) => (a.updatedAt < b.updatedAt ? 1 : -1));
    const capped = items.slice(0, limit);

    return NextResponse.json({
      code: 200,
      data: { items: capped, total: capped.length },
    });
  } catch (error) {
    console.error("[GET search] error:", error);
    return handlePrismaError(error, req);
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getWorkspaceContext, runWithWorkspace } from "@/lib/auth";
import { z } from "zod";
import { apiMsg } from "@/lib/api-messages";
import { handlePrismaError } from "@/lib/prisma-error";

/**
 * 知识库空间 API · /api/v1/workspaces/{wid}/spaces
 * 设计文档 §2.2 — Workspace → Space → Folder → Document 层级
 *
 * - GET：列出工作区所有空间（按 sortOrder 排序）
 * - POST：创建空间（仅 owner/admin）
 */

/** GET /v1/workspaces/{wid}/spaces — 列出工作区所有空间 */
export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ wid: string }> },
) {
  const { wid } = await params;
  const ctx = await getWorkspaceContext(req, wid);
  if (!ctx)
    return NextResponse.json(
      { code: 401, message: apiMsg(req, "unauthorized"), data: null },
      { status: 401 },
    );

  try {
    const spaces = await runWithWorkspace(
      wid,
      (tx) =>
        tx.space.findMany({
          where: { workspaceId: wid },
          orderBy: { sortOrder: "asc" },
          // 上限保护：单工作区空间数量不会很多，取 200 兜底
          take: 200,
        }),
      ctx.payload.sub,
    );
    return NextResponse.json({ code: 200, data: { items: spaces, total: spaces.length } });
  } catch (error) {
    console.error("[GET spaces] error:", error);
    return NextResponse.json(
      { code: 500, data: null, message: apiMsg(req, "internalError") },
      { status: 500 },
    );
  }
}

const createSpaceSchema = z.object({
  name: z.string().min(1).max(100),
  icon: z.string().max(50).optional(),
  color: z.string().max(50).optional(),
  sortOrder: z.number().optional(),
});

/** POST /v1/workspaces/{wid}/spaces — 创建空间（仅 owner/admin） */
export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ wid: string }> },
) {
  const { wid } = await params;
  const ctx = await getWorkspaceContext(req, wid);
  if (!ctx)
    return NextResponse.json(
      { code: 401, message: apiMsg(req, "unauthorized"), data: null },
      { status: 401 },
    );
  // 权限：仅 owner/admin 可创建空间（复用标签创建权限语义）
  if (!["owner", "admin"].includes(ctx.member.role)) {
    return NextResponse.json(
      { code: 403, message: apiMsg(req, "onlyOwnerAdminCreateLabels"), data: null },
      { status: 403 },
    );
  }

  try {
    const validated = createSpaceSchema.parse(await req.json());

    const space = await runWithWorkspace(
      wid,
      (tx) =>
        tx.space.create({
          data: {
            workspaceId: wid,
            name: validated.name,
            icon: validated.icon ?? "book",
            color: validated.color ?? "var(--accent)",
            sortOrder: validated.sortOrder ?? 0,
          },
        }),
      ctx.payload.sub,
    );

    return NextResponse.json({ code: 201, data: space }, { status: 201 });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return NextResponse.json(
        {
          code: 400,
          message: error.issues[0]?.message ?? apiMsg(req, "validationFailed"),
          data: null,
          errors: error.errors,
        },
        { status: 400 },
      );
    }
    console.error("[POST space] error:", error);
    return handlePrismaError(error, req);
  }
}

const updateSpaceSchema = z.object({
  name: z.string().min(1).max(100).optional(),
  icon: z.string().max(50).optional(),
  color: z.string().max(50).optional(),
  sortOrder: z.number().optional(),
});

/** PATCH /v1/workspaces/{wid}/spaces — 更新空间（名称/图标/颜色/排序）
 *  Body: { id, name?, icon?, color?, sortOrder? }
 *  权限：仅 owner/admin
 */
export async function PATCH(
  req: NextRequest,
  { params }: { params: Promise<{ wid: string }> },
) {
  const { wid } = await params;
  const ctx = await getWorkspaceContext(req, wid);
  if (!ctx)
    return NextResponse.json(
      { code: 401, message: apiMsg(req, "unauthorized"), data: null },
      { status: 401 },
    );
  if (!["owner", "admin"].includes(ctx.member.role)) {
    return NextResponse.json(
      { code: 403, message: apiMsg(req, "noPermission"), data: null },
      { status: 403 },
    );
  }

  try {
    const body = await req.json();
    const idSchema = z.object({
      id: z.string().uuid(),
      name: z.string().min(1).max(100).optional(),
      icon: z.string().max(50).optional(),
      color: z.string().max(50).optional(),
      sortOrder: z.number().optional(),
    });
    const validated = idSchema.parse(body);
    // 至少需要一个可更新字段
    if (
      validated.name === undefined &&
      validated.icon === undefined &&
      validated.color === undefined &&
      validated.sortOrder === undefined
    ) {
      return NextResponse.json(
        { code: 400, message: apiMsg(req, "validationFailed"), data: null },
        { status: 400 },
      );
    }

    const result = await runWithWorkspace(
      wid,
      async (tx) => {
        const existing = await tx.space.findFirst({
          where: { id: validated.id, workspaceId: wid },
          select: { id: true },
        });
        if (!existing) return { kind: "notFound" as const, data: null };

        const data: {
          name?: string;
          icon?: string;
          color?: string;
          sortOrder?: number;
        } = {};
        if (validated.name !== undefined) data.name = validated.name;
        if (validated.icon !== undefined) data.icon = validated.icon;
        if (validated.color !== undefined) data.color = validated.color;
        if (validated.sortOrder !== undefined) data.sortOrder = validated.sortOrder;

        const updated = await tx.space.update({ where: { id: validated.id }, data });
        return { kind: "ok" as const, data: updated };
      },
      ctx.payload.sub,
    );

    if (result.kind === "notFound") {
      return NextResponse.json(
        { code: 404, message: apiMsg(req, "prismaRecordNotFound"), data: null },
        { status: 404 },
      );
    }
    return NextResponse.json({ code: 200, data: result.data });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return NextResponse.json(
        {
          code: 400,
          message: error.issues[0]?.message ?? apiMsg(req, "validationFailed"),
          data: null,
          errors: error.errors,
        },
        { status: 400 },
      );
    }
    console.error("[PATCH space] error:", error);
    return handlePrismaError(error, req);
  }
}

const deleteSpaceSchema = z.object({
  id: z.string().uuid(),
});

/** DELETE /v1/workspaces/{wid}/spaces — 删除空间
 *  Body: { id }
 *  权限：仅 owner/admin
 *  语义：空间删除后，其下文档的 spaceId/folderId 被 SetNull 置空，归入"未分类"
 */
export async function DELETE(
  req: NextRequest,
  { params }: { params: Promise<{ wid: string }> },
) {
  const { wid } = await params;
  const ctx = await getWorkspaceContext(req, wid);
  if (!ctx)
    return NextResponse.json(
      { code: 401, message: apiMsg(req, "unauthorized"), data: null },
      { status: 401 },
    );
  if (!["owner", "admin"].includes(ctx.member.role)) {
    return NextResponse.json(
      { code: 403, message: apiMsg(req, "noPermission"), data: null },
      { status: 403 },
    );
  }

  try {
    const validated = deleteSpaceSchema.parse(await req.json());

    const result = await runWithWorkspace(
      wid,
      async (tx) => {
        const existing = await tx.space.findFirst({
          where: { id: validated.id, workspaceId: wid },
          select: { id: true },
        });
        if (!existing) return { kind: "notFound" as const };
        // 空间删除：Folder 级联删除，Document.spaceId/folderId 被 SetNull 置空
        await tx.space.delete({ where: { id: validated.id } });
        return { kind: "ok" as const };
      },
      ctx.payload.sub,
    );

    if (result.kind === "notFound") {
      return NextResponse.json(
        { code: 404, message: apiMsg(req, "prismaRecordNotFound"), data: null },
        { status: 404 },
      );
    }
    return NextResponse.json({ code: 200, data: { id: validated.id, deleted: true } });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return NextResponse.json(
        {
          code: 400,
          message: error.issues[0]?.message ?? apiMsg(req, "validationFailed"),
          data: null,
          errors: error.errors,
        },
        { status: 400 },
      );
    }
    console.error("[DELETE space] error:", error);
    return handlePrismaError(error, req);
  }
}

"use client";

/**
 * 决策执行追踪面板 · ActionItemPanel
 *
 * F1 决策驱动执行：把决策记录中的「行动项」结构化展示，
 * 让决策不止于记录，还能落到具体负责人 + 截止日 + 优先级 + 关联任务。
 *
 * 功能：
 *  - 行动项列表：勾选框 + 负责人头像 + 截止日 + 优先级标签 + 任务链接
 *  - 顶部完成率：已完成/总数 + 迷你环形进度条（SVG）
 *  - 「同步到任务」按钮：手动触发 sync-actions 端点（保存决策时也会自动同步）
 *  - 无行动项时显示「暂无行动项」空状态
 *
 * 数据来源：
 *  - GET /api/v1/workspaces/{wid}/tasks/{taskId}/decisions/{decisionId}/action-items
 *  - POST /api/v1/workspaces/{wid}/tasks/{taskId}/decisions/{decisionId}/sync-actions
 *
 * 设计：
 *  - 所有色值走 var(--token)，间距/字号/圆角走 token
 *  - 优先级标签复用 PRIORITY_BADGE_STYLES（与看板/详情页一致）
 *  - 负责人头像：项目无 Avatar 组件，用首字母圆形 + 语义色背景
 *  - 环形进度条：纯 SVG（与 analytics 页同模式，不引第三方库）
 *  - 图标仅用 lucide-react
 *
 * i18n：键命名空间 "decision"（actionItems / actionProgress / syncActions /
 *  noActions / actionCreated / actionUpdated）+ "priority"（low/medium/high/urgent）。
 *  翻译键已在 messages/{locale}.json 中补齐。
 */

import { useCallback, useEffect, useState } from "react";
import { Link } from "@/lib/i18n-navigation";
import { RefreshCw, Loader2, ListChecks, ExternalLink, Calendar, Plus } from "lucide-react";
import { api } from "@/lib/api";
import { useToast } from "@/components/Toast";
import { useTranslations } from "next-intl";
import { PRIORITY_BADGE_STYLES } from "@/lib/task-meta";
import { ACTION_TEMPLATES } from "@/lib/decision-action-parser";
import type { Priority, Person } from "@/lib/types";

/** 行动项形态：决策记录中结构化提取的可执行条目。 */
export interface ActionItem {
  id: string;
  /** 行动项标题（决策中提炼的待办描述） */
  title: string;
  /** 是否已完成（勾选框状态） */
  completed: boolean;
  /** 负责人（同步到任务后关联 assignee；决策草稿阶段可能为 null） */
  assignee?: Person | null;
  /** 负责人显示名（assignee 为 null 时仍可能从草稿中保留名字） */
  assigneeName?: string | null;
  /** 截止日期（ISO 字符串或 null） */
  dueDate?: string | null;
  /** 优先级：与任务体系一致（low/medium/high/urgent） */
  priority: Priority;
  /** 关联任务 ID（同步到任务后产生；null 表示尚未同步） */
  taskId?: string | null;
}

/** sync-actions 端点响应：返回创建/更新的任务数。 */
interface SyncActionsResp {
  created?: number;
  updated?: number;
  /** 同步后的完整行动项列表（部分实现可能直接返回最新列表） */
  items?: ActionItem[];
}

interface ActionItemPanelProps {
  decisionId: string;
  workspaceId: string;
  taskId: string;
  /** 当前 locale（i18n-navigation 的 Link 自动处理 locale 前缀，此字段保留以备定制场景） */
  locale: string;
  /** 外部传入的初始行动项（决策详情内嵌时直接用，避免首次额外请求） */
  initialItems?: ActionItem[];
  /** 外部触发刷新的签名（父组件保存决策后 +1，触发本面板重新拉取） */
  refreshSignal?: number;
  /**
   * 插入模板回调（父组件将模板 markdown 插入到决策编辑器）。
   * 未提供时不显示「插入模板」按钮。模板中的 {dueDate} 占位符已替换为
   * 当前日期 + 7 天（YYYY-MM-DD）。
   */
  onInsertTemplate?: (markdown: string) => void;
}

/** 环形进度条尺寸常量（SVG viewBox） */
const RING_SIZE = 28;
const RING_STROKE = 3;
const RING_RADIUS = (RING_SIZE - RING_STROKE) / 2;
const RING_CIRCUMFERENCE = 2 * Math.PI * RING_RADIUS;

/**
 * 负责人头像：项目无 Avatar 组件，用首字母圆形 + 语义色背景。
 * 取 name 首字母（无 name 取 email 首字母），背景色按 hash 落到 accent/success/warn/danger 四档。
 */
function AssigneeAvatar({ name, email }: { name: string | null; email?: string | null }) {
  const display = name?.trim() || email?.trim() || "?";
  const initial = display.charAt(0).toUpperCase();
  // 简易 hash → 4 档语义色，保证同一人稳定着色
  const hash = display.charCodeAt(0) + (display.charCodeAt(1) || 0);
  const palette = ["var(--accent)", "var(--success)", "var(--warn)", "var(--danger)"];
  const bg = palette[hash % palette.length];
  return (
    <span
      aria-label={display}
      title={display}
      className="inline-flex items-center justify-center w-5 h-5 rounded-full text-[length:var(--text-xs)] font-[weight:var(--weight-semibold)] text-[var(--accent-fg)] shrink-0"
      style={{ background: bg }}
    >
      {initial}
    </span>
  );
}

/** 优先级标签：复用 PRIORITY_BADGE_STYLES，与看板/详情页一致。 */
function PriorityBadge({ priority, label }: { priority: Priority; label: string }) {
  const style = PRIORITY_BADGE_STYLES[priority];
  return (
    <span
      className="inline-flex items-center px-1.5 py-0.5 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] shrink-0"
      style={{ background: style.background, color: style.color }}
    >
      {label}
    </span>
  );
}

/**
 * 迷你环形进度条：SVG circle + stroke-dasharray 控制进度。
 * 与 analytics 页 SVG 图表同模式，不引第三方库。
 */
function ProgressRing({ percent }: { percent: number }) {
  const clamped = Math.max(0, Math.min(100, percent));
  const offset = RING_CIRCUMFERENCE * (1 - clamped / 100);
  const color = clamped === 100 ? "var(--success)" : "var(--accent)";
  return (
    <svg
      width={RING_SIZE}
      height={RING_SIZE}
      viewBox={`0 0 ${RING_SIZE} ${RING_SIZE}`}
      className="shrink-0"
      role="img"
      aria-label={`${clamped}%`}
    >
      {/* 背景轨道 */}
      <circle
        cx={RING_SIZE / 2}
        cy={RING_SIZE / 2}
        r={RING_RADIUS}
        fill="none"
        stroke="var(--surface-3)"
        strokeWidth={RING_STROKE}
      />
      {/* 进度弧 */}
      <circle
        cx={RING_SIZE / 2}
        cy={RING_SIZE / 2}
        r={RING_RADIUS}
        fill="none"
        stroke={color}
        strokeWidth={RING_STROKE}
        strokeLinecap="round"
        strokeDasharray={RING_CIRCUMFERENCE}
        strokeDashoffset={offset}
        transform={`rotate(-90 ${RING_SIZE / 2} ${RING_SIZE / 2})`}
        className="transition-[stroke-dashoffset] duration-[var(--motion-base)]"
      />
    </svg>
  );
}

export function ActionItemPanel({
  decisionId,
  workspaceId,
  taskId,
  initialItems,
  refreshSignal = 0,
  onInsertTemplate,
}: ActionItemPanelProps) {

  const t = useTranslations("decision");
  const tPriority = useTranslations("priority");
  const { toast } = useToast();

  const [items, setItems] = useState<ActionItem[]>(initialItems ?? []);
  const [loading, setLoading] = useState<boolean>(initialItems == null);
  const [error, setError] = useState<string>("");
  const [syncing, setSyncing] = useState(false);
  // 勾选中的行动项 ID（loading 反馈，避免重复点击）
  const [togglingId, setTogglingId] = useState<string | null>(null);
  // 模板下拉菜单开关
  const [templateMenuOpen, setTemplateMenuOpen] = useState(false);

  // Escape 关闭模板下拉菜单
  useEffect(() => {
    if (!templateMenuOpen) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setTemplateMenuOpen(false);
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [templateMenuOpen]);

  const endpoint = `/api/v1/workspaces/${workspaceId}/tasks/${taskId}/decisions/${decisionId}/action-items`;
  const syncEndpoint = `/api/v1/workspaces/${workspaceId}/tasks/${taskId}/decisions/${decisionId}/sync-actions`;

  /** 拉取行动项列表。 */
  const loadItems = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      const resp = await api<ActionItem[] | { items: ActionItem[] }>(endpoint);
      // 兼容两种响应形态：直接数组 或 { items: [] }
      const list = Array.isArray(resp) ? resp : resp.items;
      setItems(list ?? []);
    } catch (e) {
      // API 可能尚未存在（404），此时不显示错误，仅置空列表
      const msg = e instanceof Error ? e.message : "";
      if (msg.includes("404") || msg.toLowerCase().includes("not found")) {
        setItems([]);
      } else {
        setError(msg || t("loadFailed"));
      }
    } finally {
      setLoading(false);
    }
  }, [endpoint]);

  // 首次挂载：若无 initialItems 则拉取；有则跳过首次请求
  useEffect(() => {
    if (initialItems == null) {
      loadItems();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // 外部 refreshSignal 变化时重新拉取（父组件保存决策后 +1）
  useEffect(() => {
    if (refreshSignal > 0) {
      loadItems();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [refreshSignal]);

  /** 手动同步到任务：POST sync-actions。 */
  async function handleSync() {
    if (syncing) return;
    setSyncing(true);
    setError("");
    try {
      const resp = await api<SyncActionsResp>(syncEndpoint, { method: "POST" });
      const created = resp.created ?? 0;
      const updated = resp.updated ?? 0;
      // 优先用响应里的 items，否则重新拉取
      if (resp.items) {
        setItems(resp.items);
      } else {
        await loadItems();
      }
      if (created > 0 && updated > 0) {
        toast("success", `${t("actionCreated", { count: created })} · ${t("actionUpdated", { count: updated })}`);
      } else if (created > 0) {
        toast("success", t("actionCreated", { count: created }));
      } else if (updated > 0) {
        toast("success", t("actionUpdated", { count: updated }));
      } else {
        toast("info", t("actionItems"));
      }
    } catch (e) {
      const msg = e instanceof Error ? e.message : t("syncFailed");
      setError(msg);
      toast("error", msg);
    } finally {
      setSyncing(false);
    }
  }

  /** 勾选/取消勾选行动项。 */
  async function handleToggle(item: ActionItem) {
    if (togglingId) return;
    setTogglingId(item.id);
    // 乐观更新
    setItems((prev) => prev.map((it) => (it.id === item.id ? { ...it, completed: !it.completed } : it)));
    try {
      await api(`${endpoint}/${item.id}`, {
        method: "PATCH",
        body: JSON.stringify({ completed: !item.completed }),
      });
    } catch (e) {
      // 回滚
      setItems((prev) => prev.map((it) => (it.id === item.id ? { ...it, completed: item.completed } : it)));
      toast("error", e instanceof Error ? e.message : t("updateFailed"));
    } finally {
      setTogglingId(null);
    }
  }

  /**
   * 插入模板：将 {dueDate} 占位符替换为当前日期 + 7 天（YYYY-MM-DD）后回调父组件。
   */
  function handleInsertTemplate(md: string) {
    const due = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
    const dueDateStr = due.toISOString().slice(0, 10);
    const filled = md.replace(/\{dueDate\}/g, dueDateStr);
    onInsertTemplate?.(filled);
    setTemplateMenuOpen(false);
  }

  const total = items.length;
  const completed = items.filter((it) => it.completed).length;
  const percent = total > 0 ? Math.round((completed / total) * 100) : 0;

  // 加载中骨架
  if (loading) {
    return (
      <section
        className="mt-[var(--space-3)] rounded-[var(--radius-md)] border border-[var(--border-soft)] bg-[var(--surface-2)] px-[var(--space-3)] py-[var(--space-2)]"
        aria-busy="true"
        aria-label={t("actionItems")}
      >
        <div className="flex items-center gap-2 text-[length:var(--text-xs)] text-[var(--meta)]">
          <Loader2 size={12} className="animate-spin" />
          {t("actionItems")}
        </div>
      </section>
    );
  }

  return (
    <section
      className="mt-[var(--space-3)] rounded-[var(--radius-md)] border border-[var(--border-soft)] bg-[var(--surface-2)] overflow-hidden"
      aria-label={t("actionItems")}
    >
      {/* 顶部：标题 + 完成率 + 环形进度 + 同步按钮 */}
      <header className="flex items-center gap-[var(--space-2)] px-[var(--space-3)] py-2 border-b border-[var(--border-soft)]">
        <ListChecks size={13} className="shrink-0 text-[var(--muted)]" />
        <span className="text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--fg-2)]">
          {t("actionItems")}
        </span>
        {total > 0 && (
          <span className="flex items-center gap-1.5 ml-1 text-[length:var(--text-xs)] text-[var(--meta)] tabular-nums">
            <ProgressRing percent={percent} />
            <span>
              {completed}/{total}
            </span>
          </span>
        )}
        {/* 插入模板按钮（仅当 onInsertTemplate 提供时显示） */}
        {onInsertTemplate && (
          <div className="relative ml-auto">
            <button
              onClick={() => setTemplateMenuOpen((v) => !v)}
              title={t("insertTemplate")}
              aria-label={t("insertTemplate")}
              className="inline-flex items-center gap-1 h-6 px-2 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] text-[var(--fg-2)] hover:bg-[var(--surface)] active:bg-[var(--surface-3)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
            >
              <Plus size={11} />
              <span className="hidden sm:inline">{t("insertTemplate")}</span>
            </button>
            {templateMenuOpen && (
              <>
                {/* 点击外部关闭 */}
                <div
                  className="fixed inset-0 z-10"
                  onClick={() => setTemplateMenuOpen(false)}
                  aria-hidden="true"
                />
                <ul className="absolute right-0 top-7 z-20 min-w-[200px] rounded-[var(--radius-md)] border border-[var(--border-soft)] bg-[var(--surface-2)] shadow-md py-1">
                  {ACTION_TEMPLATES.map((tpl) => (
                    <li key={tpl.id}>
                      <button
                        onClick={() => handleInsertTemplate(tpl.markdown)}
                        className="w-full text-left px-3 py-1.5 hover:bg-[var(--surface)] transition-colors duration-[var(--motion-fast)]"
                      >
                        <div className="text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--fg-2)]">
                          {tpl.name}
                        </div>
                        <div className="text-[length:var(--text-xs)] text-[var(--meta)]">
                          {tpl.description}
                        </div>
                      </button>
                    </li>
                  ))}
                </ul>
              </>
            )}
          </div>
        )}
        <button
          onClick={handleSync}
          disabled={syncing}
          title={t("syncActions")}
          aria-label={t("syncActions")}
          className={`${onInsertTemplate ? "" : "ml-auto"} inline-flex items-center gap-1 h-6 px-2 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] text-[var(--fg-2)] hover:bg-[var(--surface)] active:bg-[var(--surface-3)] disabled:opacity-50 transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2`}
        >
          {syncing ? <Loader2 size={11} className="animate-spin" /> : <RefreshCw size={11} />}
          <span className="hidden sm:inline">{t("syncActions")}</span>
        </button>
      </header>

      {/* 错误提示 */}
      {error && (
        <div className="px-[var(--space-3)] py-1.5 text-[length:var(--text-xs)] text-[var(--danger-fg)] bg-[var(--danger-soft)]">
          {error}
        </div>
      )}

      {/* 行动项列表 */}
      {total === 0 ? (
        <div className="px-[var(--space-3)] py-[var(--space-3)] text-center text-[length:var(--text-xs)] text-[var(--meta)]">
          {t("noActions")}
        </div>
      ) : (
        <ul className="divide-y divide-[var(--border-soft)]">
          {items.map((item) => {
            const isToggling = togglingId === item.id;
            const assigneeDisplay = item.assignee?.name ?? item.assigneeName ?? item.assignee?.email ?? null;
            const due = item.dueDate ? new Date(item.dueDate) : null;
            const isOverdue = due && !item.completed && due.getTime() < Date.now();
            return (
              <li
                key={item.id}
                className="flex items-center gap-[var(--space-2)] px-[var(--space-3)] py-2"
              >
                {/* 勾选框 */}
                {isToggling ? (
                  <Loader2
                    size={14}
                    className="shrink-0 animate-spin text-[var(--meta)]"
                    aria-label="loading"
                  />
                ) : (
                  <input
                    type="checkbox"
                    checked={item.completed}
                    onChange={() => handleToggle(item)}
                    className="shrink-0 accent-[var(--accent)]"
                    aria-label={item.title}
                  />
                )}

                {/* 标题 + 任务链接 */}
                <div className="flex-1 min-w-0 flex items-center gap-1">
                  <span
                    className={`truncate text-[length:var(--text-sm)] ${
                      item.completed
                        ? "text-[var(--meta)] line-through"
                        : "text-[var(--fg-2)]"
                    }`}
                    title={item.title}
                  >
                    {item.title}
                  </span>
                  {item.taskId && (
                    <Link
                      href={`/w/${workspaceId}/task/${item.taskId}`}
                      className="shrink-0 inline-flex items-center text-[var(--accent)] hover:underline"
                      aria-label="open task"
                    >
                      <ExternalLink size={11} />
                    </Link>
                  )}
                </div>

                {/* 优先级标签 */}
                <PriorityBadge
                  priority={item.priority}
                  label={tPriority(item.priority)}
                />

                {/* 负责人头像 */}
                {assigneeDisplay && (
                  <AssigneeAvatar
                    name={item.assignee?.name ?? item.assigneeName ?? null}
                    email={item.assignee?.email ?? null}
                  />
                )}

                {/* 截止日 */}
                {due && (
                  <span
                    className={`shrink-0 inline-flex items-center gap-0.5 text-[length:var(--text-xs)] tabular-nums ${
                      isOverdue ? "text-[var(--danger-fg)]" : "text-[var(--meta)]"
                    }`}
                    title={due.toLocaleDateString()}
                  >
                    <Calendar size={10} />
                    {due.toLocaleDateString(undefined, { month: "short", day: "numeric" })}
                  </span>
                )}
              </li>
            );
          })}
        </ul>
      )}
    </section>
  );
}

export default ActionItemPanel;

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { api } from "@/lib/api";
import { useTranslations } from "next-intl";
import { RefreshCw } from "lucide-react";
import type { ChatMessage, Person, AttachmentMeta } from "./chat/types";
import { useChatStream } from "./chat/useChatStream";
import { ChatHeader } from "./chat/ChatHeader";
import { MessageList } from "./chat/MessageList";
import { MessageInput } from "./chat/MessageInput";

/**
 * 任务级即时聊天面板（IM 升级版）
 *
 * 升级内容：
 *  - SSE 实时推送替代 5s 轮询（降级时自动回退轮询）
 *  - 消息已读状态 + 双勾✓✓回执
 *  - 在线状态指示
 *  - 文件附件分享（图片预览 + 文档下载）
 *  - UI 打磨：消息气泡、时间戳分组、滚动动画、未读高亮、消息搜索
 *
 * Props 接口保持与旧版兼容：{ wid, taskId }
 *
 * 架构：
 *  - useChatStream(taskId)：SSE 连接管理 + 断线重连 + 降级轮询
 *  - ChatHeader：标题 + 搜索 + 在线状态栏
 *  - MessageList：消息列表 + 时间分组 + 滚动 + 未读高亮
 *  - MessageInput：文件按钮 + 文本框 + 发送按钮
 */

/** 已读标记防抖延迟 */
const MARK_READ_DEBOUNCE_MS = 1000;

export default function ChatPanel({ wid, taskId }: { wid: string; taskId: string }) {
  const t = useTranslations("chat");
  const base = `/api/v1/workspaces/${wid}/tasks/${taskId}/messages`;
  const streamUrl = `${base}/stream`;
  const sendUrl = `${base}/send`;
  const readUrl = `${base}/read`;
  const uploadUrl = `${base}/attachments`;
  const membersUrl = `/api/v1/workspaces/${wid}/members`;

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [members, setMembers] = useState<Person[]>([]);
  const [currentUserId, setCurrentUserId] = useState<string>("");
  const [sending, setSending] = useState(false);
  const [loading, setLoading] = useState(true);
  // 初始加载失败错误提示（替代静默失败）
  const [loadError, setLoadError] = useState("");
  const [searchOpen, setSearchOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");

  // 未读消息 ID 集合（他人发的、尚未标记已读的）
  const [unreadIds, setUnreadIds] = useState<Set<string>>(new Set());
  // 已读标记防抖定时器
  const markReadTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  // 增量游标（用于 SSE 断线重连补偿）
  const sinceRef = useRef<string | null>(null);

  /** 更新增量游标 */
  const updateCursor = useCallback((createdAt: string) => {
    const prev = sinceRef.current;
    if (!prev || new Date(createdAt) > new Date(prev)) {
      sinceRef.current = createdAt;
    }
  }, []);

  /** 首次加载：消息列表 */
  const loadInitial = useCallback(async () => {
    try {
      const msgs = await api<ChatMessage[]>(base);
      setMessages(msgs);
      if (msgs.length > 0) {
        updateCursor(msgs[msgs.length - 1].createdAt);
      }
      setLoadError("");
    } catch (e) {
      // 初始加载失败：显示错误提示而非静默
      setLoadError(e instanceof Error ? e.message : t("loadFailed"));
    } finally {
      setLoading(false);
    }
  }, [base, updateCursor, t]);

  /** 加载工作区成员（用于在线状态头像 + 当前用户 ID） */
  const loadMembers = useCallback(async () => {
    try {
      const data = await api<(Person & { isSelf?: boolean })[]>(membersUrl);
      setMembers(data);
      // 从 isSelf 字段获取当前用户 ID
      const self = data.find((m) => m.isSelf);
      if (self) {
        setCurrentUserId(self.id);
        // 计算未读消息（他人发的、没有自己已读记录的）
        setMessages((prev) => {
          const unread = new Set<string>();
          for (const m of prev) {
            if (m.authorId !== self.id && !m.reads?.some((r) => r.userId === self.id)) {
              unread.add(m.id);
            }
          }
          setUnreadIds(unread);
          return prev;
        });
      }
    } catch {
      // 静默失败
    }
  }, [membersUrl]);

  useEffect(() => {
    loadInitial();
    loadMembers();
  }, [loadInitial, loadMembers]);

  /** SSE onMessage 回调：追加新消息 */
  const handleNewMessage = useCallback(
    (message: ChatMessage) => {
      setMessages((prev) => {
        // 去重（断线重连补偿可能重复）
        if (prev.some((m) => m.id === message.id)) return prev;
        return [...prev, message];
      });
      updateCursor(message.createdAt);

      // 如果是他人消息，加入未读集合
      if (message.authorId !== currentUserId) {
        setUnreadIds((prev) => new Set(prev).add(message.id));
      }
    },
    [currentUserId, updateCursor],
  );

  /** SSE onRead 回调：更新已读回执 */
  const handleRead = useCallback(
    (messageId: string, userId: string, readAt: string) => {
      setMessages((prev) =>
        prev.map((m) => {
          if (m.id !== messageId) return m;
          const reads = m.reads ?? [];
          // 去重
          if (reads.some((r) => r.userId === userId)) return m;
          return { ...m, reads: [...reads, { userId, readAt }] };
        }),
      );
      // 如果是自己已读，从未读集合移除
      if (userId === currentUserId) {
        setUnreadIds((prev) => {
          const next = new Set(prev);
          next.delete(messageId);
          return next;
        });
      }
    },
    [currentUserId],
  );

  /** SSE 连接 */
  const { connected, onlineUsers, reconnect, fallback } = useChatStream({
    streamUrl,
    pollUrl: base,
    enabled: !loading,
    onMessage: handleNewMessage,
    onRead: handleRead,
    currentUserId,
  });

  /** 批量标记未读消息为已读（防抖） */
  const markUnreadAsRead = useCallback(async () => {
    if (!currentUserId || unreadIds.size === 0) return;
    const ids = Array.from(unreadIds);
    setUnreadIds(new Set()); // 乐观更新
    try {
      await api(readUrl, {
        method: "PATCH",
        body: JSON.stringify({ messageIds: ids }),
      });
    } catch {
      // 失败回滚
      setUnreadIds((prev) => new Set([...prev, ...ids]));
    }
  }, [currentUserId, unreadIds, readUrl]);

  // 防抖标记已读（消息变化或面板可见时触发）
  useEffect(() => {
    if (loading || !currentUserId || unreadIds.size === 0) return;
    if (markReadTimerRef.current) clearTimeout(markReadTimerRef.current);
    markReadTimerRef.current = setTimeout(markUnreadAsRead, MARK_READ_DEBOUNCE_MS);
    return () => {
      if (markReadTimerRef.current) clearTimeout(markReadTimerRef.current);
    };
  }, [loading, currentUserId, unreadIds, markUnreadAsRead]);

  /** 发送消息 */
  // 依赖不含 sending：sending 变化会重建此回调 → MessageInput（memo）随之
  // 重渲染 → 发送期间受控 textarea 被 React 回写清空，用户/测试正在输入的
  // 文本丢失。防重入用 ref 判定，回调引用保持稳定。
  const sendingRef = useRef(false);
  const handleSend = useCallback(
    async (body: string, attachments: AttachmentMeta[]) => {
      if (sendingRef.current) return;
      sendingRef.current = true;
      setSending(true);
      try {
        const created = await api<ChatMessage>(sendUrl, {
          method: "POST",
          body: JSON.stringify({
            body,
            attachments: attachments.length > 0 ? attachments : undefined,
          }),
        });
        // 乐观更新（SSE 也会推送，但自己发的消息不等 SSE）
        setMessages((prev) => {
          if (prev.some((m) => m.id === created.id)) return prev;
          return [...prev, created];
        });
        updateCursor(created.createdAt);
      } finally {
        sendingRef.current = false;
        setSending(false);
      }
    },
    [sendUrl, updateCursor],
  );

  /** 上传文件 */
  const handleUploadFile = useCallback(
    async (file: File): Promise<AttachmentMeta> => {
      const formData = new FormData();
      formData.append("file", file);
      const res = await fetch(uploadUrl, {
        method: "POST",
        body: formData,
        credentials: "include",
      });
      if (!res.ok) {
        const json = await res.json().catch(() => ({ message: t("uploadFailed") }));
        throw new Error(json.message || `${t("uploadFailed")} (${res.status})`);
      }
      const json = await res.json();
      return json.data as AttachmentMeta;
    },
    [uploadUrl],
  );

  // 搜索结果计数
  const searchResultCount = useMemo(() => {
    if (!searchQuery.trim()) return 0;
    const q = searchQuery.toLowerCase();
    return messages.filter((m) => m.body.toLowerCase().includes(q)).length;
  }, [messages, searchQuery]);

  return (
    <section className="mt-[var(--space-6)]">
      <ChatHeader
        messageCount={messages.length}
        onlineUsers={onlineUsers}
        members={members}
        searchQuery={searchQuery}
        onSearchChange={setSearchQuery}
        searchOpen={searchOpen}
        onToggleSearch={() => {
          setSearchOpen((prev) => !prev);
          if (searchOpen) setSearchQuery("");
        }}
      />

      {searchOpen && searchQuery.trim() && (
        <div className="mb-2 text-[length:var(--text-xs)] text-[var(--meta)]">
          {searchResultCount > 0 ? t("resultCount", { count: searchResultCount }) : t("noResults")}
        </div>
      )}

      {/* 初始加载失败错误提示 */}
      {loadError && (
        <div className="mb-2 px-3 py-2 rounded-[var(--radius-md)] bg-[var(--danger-soft)] border border-[var(--danger)] text-[length:var(--text-sm)] text-[var(--danger)]">
          {loadError}
        </div>
      )}

      {/* L7 修复：SSE 断开重连按钮——连接断开且非加载中时显示 */}
      {!connected && !loading && !loadError && (
        <div className="mb-2 flex items-center gap-2 px-3 py-2 rounded-[var(--radius-md)] bg-[var(--surface-2)] border border-[var(--border)] text-[length:var(--text-sm)] text-[var(--muted)]">
          <span className="w-1.5 h-1.5 rounded-full bg-[var(--meta)] animate-pulse" />
          {fallback ? t("fallbackPolling") : t("disconnected")}
          <button
            onClick={reconnect}
            className="ml-auto inline-flex items-center gap-1 px-2 h-7 rounded-[var(--radius-sm)] text-[var(--accent)] hover:bg-[var(--surface-3)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
            aria-label={t("reconnect")}
          >
            <RefreshCw size={12} />
            {t("reconnect")}
          </button>
        </div>
      )}

      <MessageList
        messages={messages}
        currentUserId={currentUserId}
        unreadIds={unreadIds}
        searchQuery={searchQuery}
        loading={loading}
        connected={connected}
      />

      <MessageInput
        onSend={handleSend}
        onUploadFile={handleUploadFile}
        sending={sending}
        uploadUrl={uploadUrl}
      />
    </section>
  );
}

"use client";

/**
 * 协同编辑 Provider（Phase 2，对应 design/FEATURE-DESIGN-cloud-doc.md §3.1.3 / §3.4）。
 *
 * 职责：
 * - 创建 Yjs Doc + WebSocket Provider + IndexedDB Provider，生命周期与组件绑定。
 * - 通过 React Context 向子组件暴露 ydoc / wsProvider / indexeddbProvider / awareness。
 * - 维护连接状态（connecting / online / offline）与离线缓存加载状态，供 PresenceIndicator 消费。
 * - 离线时长检测：断线时记录时间戳，重连后若离线超过 7 天，暴露 offlineTooLong 供 UI 提示。
 * - 设置 awareness user 信息（name / color / avatar），光标颜色基于用户 ID 哈希稳定分配。
 *
 * 设计取舍：
 * - "use client" 隔离：y-websocket / y-indexeddb 仅浏览器端可用，SSR 不初始化。
 * - 资源在 useEffect 中创建（保证浏览器环境），卸载时按 IndexedDB → WS → Doc 顺序 destroy，
 *   避免 WS 重连写入已销毁 Doc。
 * - 离线数据加载完成后才连接 WebSocket（IndexeddbPersistence synced 后才 wsProvider.connect()），
 *   避免空文档闪现：若 WS 先连上，服务端会推送最新状态覆盖本地空 Doc，随后 IndexedDB 加载
 *   的旧状态又覆盖回去，造成闪烁。先加载本地缓存再连 WS，CRDT 自动合并差异。
 * - 光标色板前 4 色复用语义 token（--accent/--success/--warn/--danger），后 4 色用
 *   --cursor-purple/pink/teal/orange，由下方 <style> 注入到 :root（与 design-tokens.css
 *   同模式：hex 仅出现在 token 定义处，使用处全走 var(--*)）。
 * - WS URL 默认读 NEXT_PUBLIC_COLLAB_WS_URL，未配置时回退 ws://localhost:1234（开发态）。
 * - access token 通过 props 传入（string 或取值函数），作为 ws 连接的 params.token，
 *   由 y-websocket 以 query string 发送，服务端按 token 鉴权。
 *
 * i18n 说明：本组件无面向用户文案。PresenceIndicator 的状态文案定义在
 * messages/{en,zh}.json 的 collaboration 命名空间，由 PresenceIndicator 通过
 * useTranslations("collaboration") 消费。
 */

import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  useCallback,
  type ReactNode,
} from "react";
import * as Y from "yjs";
import { WebsocketProvider } from "y-websocket";
import { IndexeddbPersistence } from "y-indexeddb";

// ── 离线时长检测 ───────────────────────────────────────────────────────────
// 断线时把时间戳存 localStorage，重连后读取计算离线时长。
// 超过 7 天则暴露 offlineTooLong，供 PresenceIndicator 提示用户检查合并结果。

/** 离线过长阈值：7 天（毫秒）。 */
const OFFLINE_TOO_LONG_MS = 7 * 24 * 60 * 60 * 1000;

/** 离线开始时间戳的 localStorage key（按文档隔离）。 */
function offlineSinceKey(documentId: string): string {
  return `corps-offline-since-${documentId}`;
}

/** 记算离线时长（毫秒）。若未记录离线开始时间或已过期则返回 0。 */
function getOfflineDurationMs(documentId: string): number {
  try {
    const raw = localStorage.getItem(offlineSinceKey(documentId));
    if (!raw) return 0;
    const since = Number(raw);
    if (!Number.isFinite(since)) return 0;
    return Date.now() - since;
  } catch {
    // localStorage 不可用（隐私模式等），跳过检测。
    return 0;
  }
}

/** 记算离线时长（毫秒）。若未记录离线开始时间或已过期则返回 0。 */
function recordOfflineStart(documentId: string): void {
  try {
    localStorage.setItem(offlineSinceKey(documentId), String(Date.now()));
  } catch {
    // localStorage 不可用，跳过记录。
  }
}

/** 清除离线开始时间记录（重连成功后调用）。 */
function clearOfflineStart(documentId: string): void {
  try {
    localStorage.removeItem(offlineSinceKey(documentId));
  } catch {
    // localStorage 不可用，跳过清除。
  }
}

// ── 光标色板（§3.2.1）──────────────────────────────────────────────────────
// 前 4 色复用语义 token；后 4 色用自定义光标 token（在组件 <style> 中定义）。
// 使用处全走 var(--*)，hex 仅出现在下方 CURSOR_TOKEN_STYLE 的 token 定义处，
// 与 design-tokens.css 的模式一致。
const CURSOR_COLORS = [
  "var(--accent)", // 蓝
  "var(--success)", // 绿
  "var(--warn)", // 黄
  "var(--danger)", // 红
  "var(--cursor-purple)", // 紫
  "var(--cursor-pink)", // 粉
  "var(--cursor-teal)", // 青
  "var(--cursor-orange)", // 橙
] as const;

/**
 * 光标色 token 定义。仅此处出现 hex（token 定义点），与 design-tokens.css 同模式。
 * 注入到 :root，使用方通过 var(--cursor-*) 消费，无裸 hex 散落在样式中。
 */
const CURSOR_TOKEN_STYLE = `
:root {
  --cursor-purple: #8B5CF6;
  --cursor-pink: #EC4899;
  --cursor-teal: #14B8A6;
  --cursor-orange: #F97316;
}
`;

/**
 * 基于用户 ID 哈希生成稳定光标颜色（§3.2.1）。
 * 同一用户在任何客户端、任何文档中都拿到相同颜色，避免抖动。
 */
export function getUserColor(userId: string): string {
  const hash = userId.split("").reduce((acc, c) => acc + c.charCodeAt(0), 0);
  return CURSOR_COLORS[hash % CURSOR_COLORS.length];
}

// ── 类型 ────────────────────────────────────────────────────────────────────

/** 协同用户信息（写入 awareness.user）。 */
export interface CollaborationUser {
  id: string;
  name: string;
  color: string;
  avatar?: string | null;
}

/** WS 连接状态。offline 表示已断开（可能正在指数退避重连）。 */
export type ConnectionStatus = "connecting" | "online" | "offline";

/** Awareness 实例类型，从 WebsocketProvider 实例属性推导，避免直接依赖 y-protocols。 */
export type CollaborationAwareness = InstanceType<typeof WebsocketProvider>["awareness"];

interface CollaborationContextValue {
  /** Yjs 文档，ProseMirror 内容挂在 ydoc.getXmlFragment("prosemirror")。 */
  ydoc: Y.Doc;
  /** y-websocket Provider，负责 CRDT 同步 + awareness 广播。 */
  wsProvider: WebsocketProvider;
  /** y-indexeddb Provider，负责离线持久化。 */
  indexeddbProvider: IndexeddbPersistence;
  /** WS Provider 的 awareness 实例，供 CollaborationCursor / PresenceIndicator 订阅。 */
  awareness: CollaborationAwareness;
  /** 当前用户信息（已写入 awareness）。 */
  user: CollaborationUser;
  /** WS 连接状态。 */
  connectionStatus: ConnectionStatus;
  /** 离线缓存是否已从 IndexedDB 加载完成（首次同步完成）。 */
  offlineSynced: boolean;
  /** 离线时长是否超过 7 天（重连后检测一次，true 时 UI 应提示用户检查合并结果）。 */
  offlineTooLong: boolean;
  /** 关闭"离线过长"提示（用户确认后调用）。 */
  dismissOfflineTooLong: () => void;
}

// ── Context ────────────────────────────────────────────────────────────────

const CollaborationContext = createContext<CollaborationContextValue | null>(null);

/**
 * 消费协同上下文。必须在 <CollaborationProvider> 内调用。
 * 返回 ydoc / wsProvider / awareness 等，供 CollaborationCursor、PresenceIndicator
 * 或业务组件接入。
 */
export function useCollaboration(): CollaborationContextValue {
  const ctx = useContext(CollaborationContext);
  if (!ctx) {
    throw new Error("useCollaboration 必须在 <CollaborationProvider> 内使用");
  }
  return ctx;
}

// ── Provider ───────────────────────────────────────────────────────────────

interface CollaborationProviderProps {
  /** 文档 ID，作为 y-websocket roomname 与 IndexedDB 数据库 key。 */
  documentId: string;
  /** 当前用户基本信息（id 用于光标色哈希，name/avatar 写入 awareness）。 */
  user: { id: string; name: string; image?: string | null };
  /**
   * y-websocket 服务端地址。默认读 NEXT_PUBLIC_COLLAB_WS_URL，
   * 未配置回退 ws://localhost:1234（开发态）。
   */
  wsUrl?: string;
  /**
   * 访问令牌，作为 WS 连接的 params.token（y-websocket 以 query string 发送）。
   * 支持 string 或取值函数（函数在连接时求值，便于读取最新 token）。
   */
  token?: string | (() => string | null);
  /** ProseMirror 内容在 Yjs Doc 上的 field 名，默认 "prosemirror"。 */
  field?: string;
  children: ReactNode;
}

/** 默认 WS 服务端地址（开发态回退）。 */
const DEFAULT_WS_URL =
  process.env.NEXT_PUBLIC_COLLAB_WS_URL ?? "ws://localhost:1234";

export function CollaborationProvider({
  documentId,
  user,
  wsUrl,
  token,
  field = "prosemirror",
  children,
}: CollaborationProviderProps) {
  // 协同上下文对象在首次挂载时创建，卸载时销毁。
  // 用 ref 持有，避免 React 严格模式双调用 effect 时重复创建（effect 内做幂等守卫）。
  const ctxRef = useRef<CollaborationContextValue | null>(null);
  const [connectionStatus, setConnectionStatus] =
    useState<ConnectionStatus>("connecting");
  const [offlineSynced, setOfflineSynced] = useState(false);
  const [offlineTooLong, setOfflineTooLong] = useState(false);

  /** 关闭"离线过长"提示。 */
  const dismissOfflineTooLong = useCallback(
    () => setOfflineTooLong(false),
    [],
  );

  // 稳定的用户信息（color 由 id 哈希得出），写入 awareness。
  const collabUser = useMemo<CollaborationUser>(
    () => ({
      id: user.id,
      name: user.name,
      color: getUserColor(user.id),
      avatar: user.image ?? null,
    }),
    [user.id, user.name, user.image],
  );

  // 解析 WS URL 与 token params（token 可能是函数，在创建 provider 时求值）。
  const resolvedWsUrl = wsUrl ?? DEFAULT_WS_URL;
  const tokenParams = useMemo(() => {
    if (token == null) return undefined;
    const tokenValue = typeof token === "function" ? token() : token;
    if (!tokenValue) return undefined;
    return { token: tokenValue };
  }, [token]);

  useEffect(() => {
    // ── 创建 Yjs Doc + Providers（仅浏览器端）──────────────────────────────
    const ydoc = new Y.Doc();

    // 离线持久化：IndexedDB key 用 corps-doc-${documentId}，保证同一文档跨连接复用缓存。
    // 先创建 IndexeddbPersistence 并等待 synced（离线数据加载到 ydoc），再连接 WebSocket，
    // 避免空文档闪现（WS 先连会用服务端状态覆盖本地空 Doc，随后 IndexedDB 旧状态又覆盖回去）。
    const indexeddbProvider = new IndexeddbPersistence(`corps-doc-${documentId}`, ydoc);

    // WebSocket 协同：CRDT 同步 + awareness 广播。
    // connect: false — 先不连接，等 IndexedDB synced 后再 connect()。
    const wsProvider = new WebsocketProvider(
      resolvedWsUrl,
      documentId,
      ydoc,
      {
        // 延迟连接：等离线数据加载完成后再 connect()，避免空文档闪现。
        connect: false,
        // 透传 token params（undefined 时 y-websocket 忽略）。
        params: tokenParams,
      },
    );

    // 写入 awareness user 信息（光标颜色 / 名称 / 头像）。
    // CollaborationCursor 扩展自动维护 cursor 字段，这里只设置 user 元数据。
    wsProvider.awareness.setLocalStateField("user", {
      name: collabUser.name,
      color: collabUser.color,
      avatar: collabUser.avatar,
    });

    // ── 监听连接状态（y-websocket ObservableV2 'status' 事件）──────────────
    // 同时管理离线时长记录：断线时记录时间戳，重连时检测是否超过 7 天。
    const handleStatus = (event: { status: "connected" | "disconnected" | "connecting" }) => {
      if (event.status === "connected") {
        setConnectionStatus("online");
        // 重连成功：检测离线时长，超过 7 天则提示用户检查合并结果。
        const offlineDuration = getOfflineDurationMs(documentId);
        if (offlineDuration > OFFLINE_TOO_LONG_MS) {
          setOfflineTooLong(true);
        }
        clearOfflineStart(documentId);
      } else if (event.status === "disconnected") {
        setConnectionStatus("offline");
        // 断线时记录开始时间（若尚未记录，避免反复刷新覆盖最早时间）。
        if (getOfflineDurationMs(documentId) === 0) {
          recordOfflineStart(documentId);
        }
      } else {
        setConnectionStatus("connecting");
      }
    };
    wsProvider.on("status", handleStatus);

    // ── 监听离线缓存加载完成（IndexeddbPersistence 'synced' 事件）──────────
    // synced 后：① 标记离线数据已加载；② 连接 WebSocket（延迟连接策略）。
    const handleIdbSynced = () => {
      setOfflineSynced(true);
      // 离线数据已加载到 ydoc，现在连接 WebSocket，CRDT 自动合并差异。
      wsProvider.connect();
    };
    indexeddbProvider.on("synced", handleIdbSynced);

    // 暴露上下文（触发子组件 re-render 拿到 providers）。
    const ctxValue: CollaborationContextValue = {
      ydoc,
      wsProvider,
      indexeddbProvider,
      awareness: wsProvider.awareness,
      user: collabUser,
      connectionStatus: "connecting",
      offlineSynced: false,
      offlineTooLong: false,
      dismissOfflineTooLong,
    };
    ctxRef.current = ctxValue;
    // 强制更新一次，让 useCollaboration 拿到非 null 值。
    setInitialized((n) => n + 1);

    // ── cleanup：按 IndexedDB → WS → Doc 顺序销毁 ──────────────────────────
    // 先停 IndexedDB（停止向 Doc 写入），再断 WS（停止同步），最后销毁 Doc。
    return () => {
      wsProvider.off("status", handleStatus);
      indexeddbProvider.off("synced", handleIdbSynced);
      // 清除本地 awareness，让其他客户端看到本用户离线。
      try {
        wsProvider.awareness.setLocalState(null);
      } catch {
        // awareness 可能已随 provider 销毁，忽略。
      }
      void indexeddbProvider.destroy();
      wsProvider.destroy();
      ydoc.destroy();
      ctxRef.current = null;
    };
    // documentId / resolvedWsUrl / collabUser / tokenParams 变化时重建连接。
    // collabUser 由 user.id/name/image 派生，已 memo 化。
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [documentId, resolvedWsUrl, collabUser, tokenParams]);

  // 初始化完成标记（effect 内 setInitialized 触发首次渲染拿到 ctx）。
  const [, setInitialized] = useState(0);

  // 当前上下文值（合并最新 connectionStatus / offlineSynced / offlineTooLong）。
  const value = useMemo<CollaborationContextValue | null>(() => {
    const base = ctxRef.current;
    if (!base) return null;
    return {
      ...base,
      connectionStatus,
      offlineSynced,
      offlineTooLong,
      dismissOfflineTooLong,
    };
  }, [connectionStatus, offlineSynced, offlineTooLong, dismissOfflineTooLong]);

  return (
    <>
      {/* 光标色 token 注入（仅此处出现 hex，与 design-tokens.css 同模式） */}
      <style dangerouslySetInnerHTML={{ __html: CURSOR_TOKEN_STYLE }} />
      <CollaborationContext.Provider value={value}>
        {value ? children : null}
      </CollaborationContext.Provider>
    </>
  );
}

// ── 便捷 hook：在线用户列表 ────────────────────────────────────────────────
// 从 awareness 读取所有已上线用户（state.user 存在即视为在线）。
// 供 PresenceIndicator 使用，也方便业务组件直接消费。

/** awareness 中的用户元数据形态。 */
export interface AwarenessUser {
  name: string;
  color: string;
  avatar?: string | null;
}

/** awareness state 形态（user 元数据 + CollaborationCursor 维护的 cursor）。 */
export interface AwarenessState {
  user?: AwarenessUser;
  cursor?: { anchor: unknown; head: unknown } | null;
}

/**
 * 订阅 awareness 变化，返回在线用户列表（排除本地客户端）。
 * 在 <CollaborationProvider> 内使用。返回值按 clientID 排序保证稳定顺序。
 */
export function useOnlineUsers(): Array<{ clientId: number; user: AwarenessUser }> {
  const { awareness } = useCollaboration();
  const [users, setUsers] = useState<Array<{ clientId: number; user: AwarenessUser }>>([]);

  // awareness 引用稳定（同一 wsProvider 实例），effect 只订阅一次。
  const awarenessRef = useRef(awareness);
  awarenessRef.current = awareness;

  useEffect(() => {
    const compute = () => {
      const next: Array<{ clientId: number; user: AwarenessUser }> = [];
      awarenessRef.current.getStates().forEach((state: AwarenessState, clientId: number) => {
        if (state.user) {
          next.push({ clientId, user: state.user });
        }
      });
      next.sort((a, b) => a.clientId - b.clientId);
      setUsers(next);
    };

    compute();
    awarenessRef.current.on("change", compute);
    return () => {
      awarenessRef.current.off("change", compute);
    };
  }, [awareness]);

  return users;
}

// ── 便捷 hook：连接状态（带重连动作）──────────────────────────────────────

/**
 * 返回连接状态与手动重连方法。
 * offline 时调用 reconnect() 触发 wsProvider.connect()。
 */
export function useConnection() {
  const { wsProvider, connectionStatus } = useCollaboration();
  const reconnect = useCallback(() => {
    // y-websocket 内部已有指数退避重连，这里提供手动触发入口。
    wsProvider.connect();
  }, [wsProvider]);
  return { connectionStatus, reconnect };
}

"use client";

/**
 * 文档编辑器：标题输入 + markdown 大文本框（自动保存到 working draft）+ 操作栏。
 *
 * 设计取舍：
 * - 用纯 textarea 而非第三方 markdown 编辑器：决策记录那套 textarea+Markdown 预览
 *   已被任务详情页验证可用，复用一致 UX；不引入富文本以免增加 bundle 与 XSS 面。
 * - 自动保存：onBlur（与任务描述/决策编辑器同模式）——避免每键保存风暴，
 *   失焦节流足够覆盖 99% 输入完成场景。
 * - 发布 = 把当前 markdown 快照到 publishedMarkdown + 打 publishedAt。
 * - 分享（F5 增强）：点击「分享」打开设置对话框，可配置有效期 / 密码保护 /
 *   查看访问日志 / 撤销分享。调用 PATCH /share 保存，GET /share/logs 拉日志。
 * - 导出（F4）：点击「导出」打开 ExportPreview 模态框，预览 + 打印/保存 PDF。
 */

import { useState, useRef, useTransition, useEffect } from "react";
import { useTranslations } from "next-intl";
import { useRouter } from "@/lib/i18n-navigation";
import {
  Loader2,
