export interface DocumentEditorProps {
  wid: string;
  id: string;
  initial: {
    title: string;
    markdown: string;
    publishedMarkdown: string | null;
    publishedAt: string | null;
    shareToken: string | null;
  };
}

/** 分享访问日志条目（与 ShareAccessLog Prisma 模型对应） */
interface ShareAccessLog {
  id: string;
  entityType: string;
  entityId: string;
  ip: string;
  userAgent: string | null;
  accessedAt: string;
}

/** 分享有效期选择模式 */
type ExpiryMode = "never" | "7d" | "30d" | "custom";

/** 从 User-Agent 提取浏览器摘要（用于访问日志展示） */
function uaSummary(ua: string | null): string {
  if (!ua) return "—";
  if (/Edg\//.test(ua)) return "Edge";
  if (/Chrome\//.test(ua)) return "Chrome";
  if (/Firefox\//.test(ua)) return "Firefox";
  if (/Safari\//.test(ua)) return "Safari";
  if (/PostmanRuntime\//.test(ua)) return "Postman";
  if (/curl\//.test(ua)) return "curl";
  return ua.length > 40 ? ua.slice(0, 40) + "…" : ua;
}

export function DocumentEditor({ wid, id, initial }: DocumentEditorProps) {
  const t = useTranslations("document");
  const tDiagram = useTranslations("diagramQuick");
  const tDecision = useTranslations("decision");
  const router = useRouter();
  const { toast } = useToast();
  const [title, setTitle] = useState(initial.title);
  const [markdown, setMarkdown] = useState(initial.markdown);
  /** RichTextEditor 命令式句柄：模板/图表通过 insertMarkdown 在光标处插入 */
  const richTextRef = useRef<RichTextEditorHandle>(null);
  const [shareToken, setShareToken] = useState(initial.shareToken);
  const [publishedAt, setPublishedAt] = useState(initial.publishedAt);
  // S1 修复：SSR 阶段 window 未定义，需 typeof window 守卫避免 ReferenceError。
  // 仅在客户端且有 shareToken 时才构造 URL；服务端渲染返回 null，hydration 后由
  // 下方的 useEffect 同步补全（见下）。
  const [shareUrl, setShareUrl] = useState<string | null>(
    initial.shareToken && typeof window !== "undefined"
      ? `${window.location.origin}/documents/share/${initial.shareToken}`
      : null,
  );
  // S1 修复续：若 SSR 阶段跳过了 URL 构造（typeof window === "undefined"）但
  // initial.shareToken 存在，客户端 hydration 后补全 shareUrl，避免链接丢失。
  useEffect(() => {
    if (initial.shareToken && shareUrl === null && typeof window !== "undefined") {
      setShareUrl(`${window.location.origin}/documents/share/${initial.shareToken}`);
    }
    // 仅在挂载时执行一次
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  const [preview, setPreview] = useState(false);
  /** 分屏模式（v0.6）：编辑与预览并排实时渲染（Obsidian 式），与单页切换互斥 */
  const [split, setSplit] = useState(false);
  const [busy, setBusy] = useState<"save" | "publish" | "share" | null>(null);
  const [error, setError] = useState("");
  const [, startTransition] = useTransition();
  // LI-10：复制分享链接成功反馈（短暂打勾替代文案，2s 后恢复）
  const [copied, setCopied] = useState(false);
  // 自动保存成功反馈：短暂显示"已保存"提示（2s 后消失）
  const [savedFlash, setSavedFlash] = useState(false);
  // setTimeout timer refs — 组件卸载时清理，防止在已卸载组件上调用 setState
  const savedFlashTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const copiedTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const shareTriggerRef = useRef<HTMLButtonElement | null>(null);
  const shareCloseRef = useRef<HTMLButtonElement | null>(null);

  // ── F5：分享设置对话框状态 ──
  const [shareDialogOpen, setShareDialogOpen] = useState(false);
  const [shareExpiresAt, setShareExpiresAt] = useState<string | null>(null);
  const [hasPassword, setHasPassword] = useState(false);
  const [sharePasswordInput, setSharePasswordInput] = useState("");
  const [expiryMode, setExpiryMode] = useState<ExpiryMode>("never");
  const [customExpiryDate, setCustomExpiryDate] = useState("");
  const [accessLogs, setAccessLogs] = useState<ShareAccessLog[]>([]);
  const [logsExpanded, setLogsExpanded] = useState(false);
  const [logsLoading, setLogsLoading] = useState(false);
  const [revokeConfirm, setRevokeConfirm] = useState(false);

  // ── F4：导出预览模态框 ──
  const [exportOpen, setExportOpen] = useState(false);

  // ── 评论/批注面板（可折叠）──
  const [commentsOpen, setCommentsOpen] = useState(false);


  /** 快速图表对话框：插入 ```mermaid 块到正文（追加到末尾，编辑器语义里"出一张图"） */
  const [quickDiagramOpen, setQuickDiagramOpen] = useState(false);

  // ── F1 增强：行动项模板插入下拉菜单 ──
  const [templateMenuOpen, setTemplateMenuOpen] = useState(false);

  // ── 窄屏"更多"菜单（折叠低频操作）──
  const [moreMenuOpen, setMoreMenuOpen] = useState(false);

  // Escape 关闭模板下拉菜单
  useEffect(() => {
    if (!templateMenuOpen) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setTemplateMenuOpen(false);
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [templateMenuOpen]);

  // 组件卸载时清除所有 setTimeout，防止在已卸载组件上调用 setState
  useEffect(() => {
    return () => {
      if (savedFlashTimerRef.current !== null) clearTimeout(savedFlashTimerRef.current);
      if (copiedTimerRef.current !== null) clearTimeout(copiedTimerRef.current);
    };
  }, []);

  // ── F5 增强：分享自定义路径（shareSlug）──
  const [shareSlug, setShareSlug] = useState<string>("");
  const [shareSlugSaved, setShareSlugSaved] = useState<string | null>(null);

  function insertDiagramBlock(block: string) {
    // 通过 RichTextEditor ref 在光标处插入（富文本/Markdown 源码模式均适用）
    richTextRef.current?.insertMarkdown(block);
  }

  /**
   * F1 增强：插入行动项模板到编辑器。
   * - 模板中的 {dueDate} 占位符替换为当前日期 + 7 天（YYYY-MM-DD）
   * - 通过 RichTextEditor ref.insertMarkdown 在光标处插入（富文本/源码模式均适用）
   */
  function handleInsertTemplate(templateMarkdown: string) {
    const due = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
    const dueDateStr = due.toISOString().slice(0, 10);
    const filled = templateMarkdown.replace(/\{dueDate\}/g, dueDateStr);
    richTextRef.current?.insertMarkdown(filled);
    setTemplateMenuOpen(false);
  }

  async function save(opts: { publish?: boolean } = {}) {
    if (busy) return;
    setBusy(opts.publish ? "publish" : "save");
    setError("");
    try {
      const res = await api<{
        id: string;
        publishedMarkdown: string | null;
        publishedAt: string | null;
      }>(`/api/v1/workspaces/${wid}/documents/${id}`, {
        method: "PATCH",
        body: JSON.stringify({ title, markdown, publish: !!opts.publish }),
      });
      if (opts.publish && res.publishedAt) {
        setPublishedAt(res.publishedAt);
      }
      // 自动保存成功：短暂显示"已保存"提示（非发布场景）
      if (!opts.publish) {
        setSavedFlash(true);
        if (savedFlashTimerRef.current !== null) clearTimeout(savedFlashTimerRef.current);
        savedFlashTimerRef.current = setTimeout(() => setSavedFlash(false), 2000);
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : t("saveFailed"));
    } finally {
      setBusy(null);
    }
  }

  /** LI-10：复制分享链接并给出 2s 视觉反馈 */
  async function copyShareUrl() {
    if (!shareUrl) return;
    try {
      await navigator.clipboard.writeText(shareUrl);
      setCopied(true);
      if (copiedTimerRef.current !== null) clearTimeout(copiedTimerRef.current);
      copiedTimerRef.current = setTimeout(() => setCopied(false), 2000);
    } catch {
      /* 剪贴板权限失败：提示用户复制失败 */
      toast("error", t("copyFailed"));
    }
  }

  // ── F5：分享设置对话框 ──────────────────────────────────────────

  /** 打开分享对话框：若无 token 先生成，再加载当前设置 + 访问日志 */
  async function openShareDialog() {
    if (busy) return;
    setError("");
    let token = shareToken;
    // 若还没有 shareToken，先生成（PATCH shareToken="rotate" 触发服务端生成）
    if (!token) {
      setBusy("share");
      try {
        const res = await api<{ id: string; shareToken: string | null }>(
          `/api/v1/workspaces/${wid}/documents/${id}`,
          {
            method: "PATCH",
            body: JSON.stringify({ shareToken: "rotate" }),
          },
        );
        if (res.shareToken) {
          token = res.shareToken;
          setShareToken(token);
          setShareUrl(`${window.location.origin}/documents/share/${token}`);
        }
      } catch (e) {
        setError(e instanceof Error ? e.message : t("shareFailed"));
        setBusy(null);
        return;
      }
      setBusy(null);
    }
    setShareDialogOpen(true);
    setRevokeConfirm(false);
    setSharePasswordInput("");
    // 加载当前分享设置（GET /share）
    try {
      const settings = await api<{
        shareToken: string | null;
        shareExpiresAt: string | null;
        hasPassword: boolean;
        shareSlug?: string | null;
      }>(`/api/v1/workspaces/${wid}/documents/${id}/share`);
      setHasPassword(settings.hasPassword);
      // F5 增强：加载已保存的自定义路径
      const slug = settings.shareSlug ?? "";
      setShareSlug(slug);
      setShareSlugSaved(slug);
      if (settings.shareExpiresAt) {
        setShareExpiresAt(settings.shareExpiresAt);
        const days = Math.round(
          (new Date(settings.shareExpiresAt).getTime() - Date.now()) / 86400000,
        );
        if (days >= 6 && days <= 8) setExpiryMode("7d");
        else if (days >= 29 && days <= 31) setExpiryMode("30d");
        else {
          setExpiryMode("custom");
          setCustomExpiryDate(settings.shareExpiresAt.slice(0, 10));
        }
      } else {
        setShareExpiresAt(null);
        setExpiryMode("never");
      }
    } catch {
      // 加载设置失败：用默认值，不阻断对话框
      setExpiryMode("never");
      setHasPassword(false);
      setShareExpiresAt(null);
    }
    // 加载访问日志
    loadAccessLogs();
  }

  /** 加载访问日志（GET /share/logs，取最近 20 条） */
  async function loadAccessLogs() {
    setLogsLoading(true);
    try {
      const res = await api<{
        items: ShareAccessLog[];
        pagination: { page: number; pageSize: number; total: number; totalPages: number };
      }>(`/api/v1/workspaces/${wid}/documents/${id}/share/logs?pageSize=20`);
      setAccessLogs(res.items);
    } catch {
      toast("error", t("shareLoadLogsFailed"));
    } finally {
      setLogsLoading(false);
    }
  }

  /** 保存分享设置（PATCH /share：有效期 + 密码 + 自定义路径） */
  async function saveShareSettings() {
    if (busy) return;
    setBusy("share");
    setError("");
    try {
      const body: {
        expiresAt: string | null;
        password?: string;
        shareSlug?: string | null;
      } = {
        expiresAt: null,
      };
      // 计算过期时间
      if (expiryMode === "7d") {
        body.expiresAt = new Date(Date.now() + 7 * 86400000).toISOString();
      } else if (expiryMode === "30d") {
        body.expiresAt = new Date(Date.now() + 30 * 86400000).toISOString();
      } else if (expiryMode === "custom" && customExpiryDate) {
        body.expiresAt = new Date(customExpiryDate + "T23:59:59").toISOString();
      }
      // 密码（仅当用户输入了新密码时才传）
      if (sharePasswordInput) {
        body.password = sharePasswordInput;
      }
      // F5 增强：自定义路径（仅当用户修改了 slug 才传，避免无谓写）
      if (shareSlug !== (shareSlugSaved ?? "")) {
        body.shareSlug = shareSlug.trim() || null;
      }
      await api(`/api/v1/workspaces/${wid}/documents/${id}/share`, {
        method: "PATCH",
        body: JSON.stringify(body),
      });
      if (sharePasswordInput) setHasPassword(true);
      setSharePasswordInput("");
      setShareExpiresAt(body.expiresAt);
      // 同步已保存 slug 状态
      if (body.shareSlug !== undefined) {
        setShareSlugSaved(body.shareSlug ?? "");
      }
      toast("success", t("shareSettingsSaved"));
    } catch (e) {
      setError(e instanceof Error ? e.message : t("shareFailed"));
    } finally {
      setBusy(null);
    }
  }

  /** 移除密码保护（PATCH /share password=null） */
  async function removePassword() {
    if (busy) return;
    setBusy("share");
    setError("");
    try {
      await api(`/api/v1/workspaces/${wid}/documents/${id}/share`, {
        method: "PATCH",
        body: JSON.stringify({ password: null }),
      });
      setHasPassword(false);
      setSharePasswordInput("");
      toast("success", t("shareSettingsSaved"));
    } catch (e) {
      setError(e instanceof Error ? e.message : t("shareFailed"));
    } finally {
      setBusy(null);
    }
  }

  /** 撤销分享（清除 shareToken + shareExpiresAt + sharePassword） */
  async function revokeShare() {
    if (busy) return;
    setBusy("share");
    setError("");
    try {
      // 先清除 token（PATCH document shareToken=null）
      await api(`/api/v1/workspaces/${wid}/documents/${id}`, {
        method: "PATCH",
        body: JSON.stringify({ shareToken: null }),
      });
      // 再清除过期 + 密码（PATCH /share）
      await api(`/api/v1/workspaces/${wid}/documents/${id}/share`, {
        method: "PATCH",
        body: JSON.stringify({ expiresAt: null, password: null }),
      });
      setShareToken(null);
      setShareUrl(null);
      setShareExpiresAt(null);
      setHasPassword(false);
      setSharePasswordInput("");
      setExpiryMode("never");
      setShareDialogOpen(false);
      setRevokeConfirm(false);
      toast("success", t("shareRevoked"));
    } catch (e) {
      setError(e instanceof Error ? e.message : t("shareFailed"));
    } finally {
      setBusy(null);
    }
  }

  // 分享对话框 Escape 关闭 + body 滚动锁
  useEffect(() => {
    if (!shareDialogOpen) return;
    const onKey = (e: globalThis.KeyboardEvent) => {
      if (e.key === "Escape") {
        setShareDialogOpen(false);
        setRevokeConfirm(false);
      }
    };
    window.addEventListener("keydown", onKey);
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", onKey);
      document.body.style.overflow = prevOverflow;
    };
  }, [shareDialogOpen]);

  function back() {
    startTransition(() => router.push(`/w/${wid}/documents`));
  }

  /** 今日日期 YYYY-MM-DD（用于 date input min 属性） */
  const todayStr = new Date().toISOString().slice(0, 10);

  return (
    <div className="max-w-3xl mx-auto px-[var(--space-4)] py-[var(--space-6)]">
      {/* 标题区 — 微妙视差（应用内 ≤ 10px），正文为前景层不移动 */}
      <Parallax offset={4}>
        {/* 标题 */}
        <input
        value={title}
        onChange={(e) => setTitle(e.target.value)}
        onBlur={() => save()}
        maxLength={255}
        placeholder={t("titlePlaceholder")}
        className="w-full px-0 py-[var(--space-2)] bg-transparent text-[length:var(--text-3xl)] font-[weight:var(--weight-semibold)] text-[var(--fg)] tracking-[var(--tracking-tight)] outline-none border-b border-transparent focus:border-[var(--border)] placeholder:text-[var(--meta)]"
      />

      {/* 工具栏 */}
      <div className="flex items-center justify-between mt-[var(--space-3)] mb-[var(--space-4)] gap-[var(--space-2)] flex-nowrap overflow-x-auto scrollbar-hide">
        <div className="flex items-center gap-[var(--space-2)] text-[length:var(--text-xs)] text-[var(--muted)] min-w-0">
          {/* LI-10：自动保存中指示器 */}
          {busy === "save" && (
            <span className="inline-flex items-center gap-1">
              <Loader2 size={14} className="animate-spin" />
              {t("saving")}
            </span>
          )}
          {/* 自动保存成功反馈：短暂显示"已保存"提示 */}
          {savedFlash && busy !== "save" && (
            <span className="inline-flex items-center gap-1 text-[var(--success)]">
              <Check size={14} />
              {t("saved")}
            </span>
          )}
          {publishedAt && (
            <span>
              {t("publishedAt", {
                date: new Date(publishedAt).toLocaleString(),
              })}
            </span>
          )}
        </div>
        <div className="flex items-center gap-[var(--space-2)] flex-nowrap justify-end shrink-0">
          <button
            onClick={back}
            className="inline-flex items-center gap-1.5 h-8 px-[var(--space-3)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] text-[var(--muted)] hover:text-[var(--fg-2)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)]"
          >
            <X size={14} />
            <span className="hidden md:inline">{t("backToList")}</span>
          </button>
          <button
            onClick={() => setPreview((v) => !v)}
            className="inline-flex items-center gap-1.5 h-8 px-[var(--space-3)] rounded-[var(--radius-md)] border border-[var(--border)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)]"
          >
            <Eye size={14} />
            <span className="hidden md:inline">{preview ? t("editMode") : t("previewMode")}</span>
          </button>
          <button
            onClick={() => {
              setSplit((v) => !v);
              setPreview(false);
            }}
            aria-pressed={split}
            className={`inline-flex items-center gap-1.5 h-8 px-[var(--space-3)] rounded-[var(--radius-md)] border text-[length:var(--text-sm)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)] ${
              split
                ? "border-[var(--accent)] text-[var(--accent)] bg-[var(--surface-2)]"
                : "border-[var(--border)] text-[var(--fg-2)] hover:bg-[var(--surface-2)]"
            }`}
            title={t("splitHint")}
          >
            <Columns2 size={14} />
            <span className="hidden md:inline">{t("splitMode")}</span>
          </button>
          {/* 窄屏"更多"菜单：折叠快速图表 + 插入模板 */}
          <div className="relative md:hidden">
            <button
              onClick={() => setMoreMenuOpen((v) => !v)}
              title={t("moreActions")}
              aria-label={t("moreActions")}
              aria-expanded={moreMenuOpen}
              aria-haspopup="menu"
              className="inline-flex items-center gap-1.5 h-8 px-[var(--space-3)] rounded-[var(--radius-md)] border border-[var(--border)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)]"
            >
              <MoreHorizontal size={14} />
            </button>
            {moreMenuOpen && (
              <>
                <div
                  className="fixed inset-0 z-10"
                  onClick={() => setMoreMenuOpen(false)}
                  aria-hidden="true"
                />
                <ul
                  role="menu"
                  aria-label={t("moreActions")}
                  className="absolute right-0 top-9 z-20 min-w-[180px] rounded-[var(--radius-md)] border border-[var(--border-soft)] bg-[var(--surface)] shadow-[var(--elev-md)] py-1"
                >
                  <li role="menuitem">
                    <button
                      onClick={() => { setQuickDiagramOpen(true); setMoreMenuOpen(false); }}
                      className="w-full text-left px-[var(--space-3)] py-1.5 hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
                    >
                      <div className="flex items-center gap-1.5 text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)]">
                        <Zap size={14} />
                        {tDiagram("title")}
                      </div>
                    </button>
                  </li>
                  <li role="menuitem">
                    <button
                      onClick={() => { setTemplateMenuOpen(true); setMoreMenuOpen(false); }}
                      className="w-full text-left px-[var(--space-3)] py-1.5 hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
                    >
                      <div className="flex items-center gap-1.5 text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)]">
                        <Plus size={14} />
                        {tDecision("insertTemplate")}
                      </div>
                    </button>
                  </li>
                </ul>
              </>
            )}
          </div>
          {/* 快速图表（宽屏显示）：不进正文也能出图，确认后一键插入（v0.6 增补） */}
          <button
            onClick={() => setQuickDiagramOpen(true)}
            className="hidden md:inline-flex items-center gap-1.5 h-8 px-[var(--space-3)] rounded-[var(--radius-md)] border border-[var(--border)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)]"
            title={tDiagram("title")}
          >
            <Zap size={14} />
            <span>{tDiagram("title")}</span>
          </button>
          {/* F1 增强：插入行动项模板（宽屏显示，下拉菜单，复用 ACTION_TEMPLATES） */}
          <div className="relative hidden md:block">
            <button
              onClick={() => setTemplateMenuOpen((v) => !v)}
              title={tDecision("insertTemplate")}
              aria-label={tDecision("insertTemplate")}
              aria-expanded={templateMenuOpen}
              aria-haspopup="menu"
              className="inline-flex items-center gap-1.5 h-8 px-[var(--space-3)] rounded-[var(--radius-md)] border border-[var(--border)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)]"
            >
              <Plus size={14} />
              <span className="hidden sm:inline">{tDecision("insertTemplate")}</span>
              <ChevronDown size={14} className="text-[var(--muted)]" />
            </button>
            {templateMenuOpen && (
              <>
                {/* 点击外部关闭 */}
                <div
                  className="fixed inset-0 z-10"
                  onClick={() => setTemplateMenuOpen(false)}
                  aria-hidden="true"
                />
                <ul
                  role="menu"
                  aria-label={tDecision("templateMenuOpen")}
                  className="absolute right-0 top-9 z-20 min-w-[220px] rounded-[var(--radius-md)] border border-[var(--border-soft)] bg-[var(--surface)] shadow-[var(--elev-md)] py-1"
                >
                  {ACTION_TEMPLATES.map((tpl) => (
                    <li key={tpl.id} role="menuitem">
                      <button
                        onClick={() => handleInsertTemplate(tpl.markdown)}
                        className="w-full text-left px-[var(--space-3)] py-1.5 hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
                      >
                        <div className="text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)]">
                          {tpl.name}
                        </div>
                        <div className="text-[length:var(--text-xs)] text-[var(--meta)]">
                          {tpl.description}
                        </div>
                      </button>
                    </li>
                  ))}
                </ul>
              </>
            )}
          </div>
          {/* F5：分享按钮 → 打开分享设置对话框 */}
          <button
            ref={shareTriggerRef}
            onClick={openShareDialog}
            disabled={busy !== null}
            title={busy !== null ? t("saving") : undefined}
            className="inline-flex items-center gap-1.5 h-8 px-[var(--space-3)] rounded-[var(--radius-md)] border border-[var(--border)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] disabled:opacity-50 transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)]"
          >
            <Share2 size={14} />
            <span className="hidden md:inline">{t("share")}</span>
          </button>
          {/* F4：导出按钮 → 打开 ExportPreview 模态框 */}
          <button
            onClick={() => setExportOpen(true)}
            title={t("exportHint")}
            className="inline-flex items-center gap-1.5 h-8 px-[var(--space-3)] rounded-[var(--radius-md)] border border-[var(--border)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)]"
          >
            <Download size={14} />
            <span className="hidden md:inline">{t("export")}</span>
          </button>
          {/* 评论/批注面板开关 */}
          <button
            onClick={() => setCommentsOpen((v) => !v)}
            aria-pressed={commentsOpen}
            title={t("comments")}
            className={`inline-flex items-center gap-1.5 h-8 px-[var(--space-3)] rounded-[var(--radius-md)] border text-[length:var(--text-sm)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)] ${
              commentsOpen
                ? "border-[var(--accent)] text-[var(--accent)] bg-[var(--surface-2)]"
                : "border-[var(--border)] text-[var(--fg-2)] hover:bg-[var(--surface-2)]"
            }`}
          >
            <MessageSquare size={14} />
            <span className="hidden md:inline">{t("comments")}</span>
          </button>
          <button
            onClick={() => save({ publish: true })}
            disabled={busy !== null}
            title={busy !== null ? t("saving") : undefined}
            className="inline-flex items-center gap-1.5 h-8 px-[var(--space-3)] rounded-[var(--radius-md)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] disabled:opacity-50 transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)]"
          >
            {busy === "publish" ? (
              <Loader2 size={14} className="animate-spin" />
            ) : (
              <Globe size={14} />
            )}
            <Ripple>{t("publish")}</Ripple>
          </button>
        </div>
      </div>
      </Parallax>

      {/* 分享链接条（快捷展示，详细设置在对话框内） */}
      {shareUrl && (
        <div className="mb-[var(--space-3)] px-[var(--space-3)] py-[var(--space-2)] rounded-[var(--radius-md)] bg-[var(--surface-2)] border border-[var(--border)] flex items-center gap-[var(--space-2)] text-[length:var(--text-xs)]">
          <span className="text-[var(--muted)] shrink-0">{t("shareUrl")}:</span>
          <input
            value={shareUrl}
            readOnly
            className="flex-1 min-w-0 bg-transparent text-[var(--fg-2)] font-[family-name:var(--font-mono)] outline-none truncate"
          />
          <button
            onClick={copyShareUrl}
            className="shrink-0 inline-flex items-center gap-1 text-[var(--accent)] hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)] rounded-[var(--radius-sm)]"
          >
            {copied ? <Check size={14} /> : null}
            {copied ? t("copied") : t("copy")}
          </button>
          <button
            onClick={openShareDialog}
            className="shrink-0 inline-flex items-center gap-1 text-[var(--muted)] hover:text-[var(--fg-2)] hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)] rounded-[var(--radius-sm)]"
          >
            {t("shareSettings")}
          </button>
        </div>
      )}

      {/* 编辑/预览/分屏 */}
      {preview ? (
        <div className="prose prose-sm max-w-none rounded-[var(--radius-lg)] border border-[var(--border)] bg-[var(--surface)] p-[var(--space-6)] min-h-[60dvh]">
          <Markdown source={markdown} />
        </div>
      ) : (
        <RichTextEditor
          ref={richTextRef}
          value={markdown}
          onChange={setMarkdown}
          onBlur={() => save()}
          split={split}
          placeholder={t("markdownPlaceholder")}
        />
      )}

      {error && (
        <div className="mt-[var(--space-2)] flex items-start gap-[var(--space-2)] text-[length:var(--text-sm)] text-[var(--danger)]">
          <span className="flex-1">{error}</span>
          <button
            onClick={() => setError("")}
            className="shrink-0 opacity-60 hover:opacity-100 transition-opacity focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)] rounded-[var(--radius-sm)]"
            aria-label={t("backToList")}
          >
            <X size={14} />
          </button>
        </div>
      )}

      {/* 快速图表对话框（编辑模式下从顶栏唤起） */}
      <QuickDiagram
        open={quickDiagramOpen}
        onClose={() => setQuickDiagramOpen(false)}
        onInsert={insertDiagramBlock}
      />

      {/* ── F5：分享设置对话框 ── */}
      {shareDialogOpen && (
        <div
          role="dialog"
          aria-modal="true"
          aria-label={t("shareDialogTitle")}
          className="fixed inset-0 z-[var(--z-modal)] flex items-center justify-center bg-[var(--overlay)] p-4"
          onClick={() => {
            setShareDialogOpen(false);
            setRevokeConfirm(false);
            shareTriggerRef.current?.focus();
          }}
        >
          <div
            className="flex flex-col w-full max-w-lg max-h-[85dvh] rounded-[var(--radius-lg)] bg-[var(--surface)] border border-[var(--border)] shadow-[var(--elev-lg)] overflow-hidden"
            onClick={(e) => e.stopPropagation()}
          >
            {/* 头部 */}
            <header className="flex items-center gap-[var(--space-2)] px-[var(--space-4)] py-2.5 border-b border-[var(--border-soft)] shrink-0">
              <Share2 size={16} className="text-[var(--muted)]" />
              <span className="flex-1 min-w-0 text-[length:var(--text-base)] font-[weight:var(--weight-semibold)] text-[var(--fg)] truncate">
                {t("shareDialogTitle")}
              </span>
              <button
                ref={shareCloseRef}
                autoFocus
                onClick={() => {
                  setShareDialogOpen(false);
                  setRevokeConfirm(false);
                  shareTriggerRef.current?.focus();
                }}
                aria-label={t("close")}
                className="shrink-0 inline-flex items-center justify-center w-8 h-8 rounded-[var(--radius-sm)] text-[var(--meta)] hover:bg-[var(--surface-2)] hover:text-[var(--fg)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
              >
                <X size={16} />
              </button>
            </header>

            {/* 内容区 */}
            <div className="flex-1 min-h-0 overflow-auto px-[var(--space-5)] py-[var(--space-4)] space-y-[var(--space-5)]">
              {/* 分享链接 */}
              {shareUrl && (
                <div>
                  <label className="block text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] mb-1.5">
                    {t("shareUrl")}
                  </label>
                  <div className="flex items-center gap-[var(--space-2)] px-[var(--space-3)] py-[var(--space-2)] rounded-[var(--radius-md)] bg-[var(--surface-2)] border border-[var(--border)]">
                    <input
                      value={shareUrl}
                      readOnly
                      className="flex-1 min-w-0 bg-transparent text-[var(--fg-2)] font-[family-name:var(--font-mono)] text-[length:var(--text-xs)] outline-none truncate"
                    />
                    <button
                      onClick={copyShareUrl}
                      className="shrink-0 inline-flex items-center gap-1 text-[var(--accent)] hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] rounded-[var(--radius-sm)]"
                    >
                      {copied ? <Check size={14} /> : null}
                      {copied ? t("copied") : t("copy")}
                    </button>
                  </div>
                </div>
              )}

              {/* F5 增强：自定义路径（shareSlug） */}
              <div>
                <label className="flex items-center gap-1.5 text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] mb-1.5">
                  <Share2 size={14} className="text-[var(--muted)]" />
                  {t("customSlug")}
                </label>
                <div className="flex items-center gap-[var(--space-2)]">
                  <span className="shrink-0 inline-flex items-center h-9 px-[var(--space-3)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface-2)] text-[length:var(--text-sm)] text-[var(--meta)] font-[family-name:var(--font-mono)]">
                    {t("customSlugPrefix")}
                  </span>
                  <input
                    type="text"
                    value={shareSlug}
                    onChange={(e) => setShareSlug(e.target.value)}
                    placeholder={t("customSlugPlaceholder")}
                    maxLength={50}
                    pattern="[a-z0-9-]*"
                    className="flex-1 min-w-0 h-9 px-[var(--space-3)] border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[var(--fg)] text-[length:var(--text-sm)] font-[family-name:var(--font-mono)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)] placeholder:text-[var(--meta)]"
                  />
                </div>
                <p className="mt-1.5 text-[length:var(--text-xs)] text-[var(--meta)]">
                  {t("customSlugHint")}
                </p>
              </div>

              {/* 有效期 */}
              <div>
                <label className="flex items-center gap-1.5 text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] mb-2">
                  <Calendar size={14} className="text-[var(--muted)]" />
                  {t("shareExpiry")}
                </label>
                <div className="flex flex-wrap gap-[var(--space-2)]">
                  {(["never", "7d", "30d", "custom"] as const).map((mode) => (
                    <button
                      key={mode}
                      onClick={() => setExpiryMode(mode)}
                      aria-pressed={expiryMode === mode}
                      className={`h-8 px-[var(--space-3)] rounded-[var(--radius-md)] border text-[length:var(--text-sm)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)] ${
                        expiryMode === mode
                          ? "border-[var(--accent)] text-[var(--accent)] bg-[var(--surface-2)]"
                          : "border-[var(--border)] text-[var(--fg-2)] hover:bg-[var(--surface-2)]"
                      }`}
                    >
                      {t(`shareExpiry_${mode}`)}
                    </button>
                  ))}
                </div>
                {expiryMode === "custom" && (
                  <input
                    type="date"
                    value={customExpiryDate}
                    onChange={(e) => setCustomExpiryDate(e.target.value)}
                    min={todayStr}
                    className="mt-[var(--space-2)] w-full h-9 px-[var(--space-3)] border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[var(--fg)] text-[length:var(--text-sm)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)]"
                  />
                )}
                {shareExpiresAt && expiryMode !== "custom" && (
                  <p className="mt-1.5 text-[length:var(--text-xs)] text-[var(--meta)]">
                    {t("shareCurrentExpiry", {
                      date: new Date(shareExpiresAt).toLocaleString(),
                    })}
                  </p>
                )}
              </div>

              {/* 密码保护 */}
              <div>
                <label className="flex items-center gap-1.5 text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] mb-2">
                  <KeyRound size={14} className="text-[var(--muted)]" />
                  {t("sharePassword")}
                </label>
                {hasPassword && !sharePasswordInput && (
                  <div className="flex items-center gap-[var(--space-2)] mb-2">
                    <span className="inline-flex items-center gap-1.5 text-[length:var(--text-sm)] text-[var(--success)]">
                      <Lock size={14} />
                      {t("sharePasswordEnabled")}
                    </span>
                    <button
                      onClick={removePassword}
                      disabled={busy !== null}
                      className="shrink-0 text-[length:var(--text-xs)] text-[var(--danger)] hover:underline disabled:opacity-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] rounded-[var(--radius-sm)]"
                    >
                      {t("sharePasswordClear")}
                    </button>
                  </div>
                )}
                <input
                  type="password"
                  value={sharePasswordInput}
                  onChange={(e) => setSharePasswordInput(e.target.value)}
                  autoComplete="new-password"
                  placeholder={
                    hasPassword
                      ? t("sharePasswordChangePlaceholder")
                      : t("sharePasswordPlaceholder")
                  }
                  className="w-full h-9 px-[var(--space-3)] border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[var(--fg)] text-[length:var(--text-sm)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)] placeholder:text-[var(--meta)]"
                />
                {sharePasswordInput && (
                  <p className="mt-1.5 text-[length:var(--text-xs)] text-[var(--meta)]">
                    {t("sharePasswordSetHint")}
                  </p>
                )}
              </div>

              {/* 访问日志（可展开） */}
              <div>
                <button
                  onClick={() => setLogsExpanded((v) => !v)}
                  aria-expanded={logsExpanded}
                  className="flex items-center gap-1.5 text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] hover:text-[var(--fg)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] rounded-[var(--radius-sm)]"
                >
                  <ChevronDown
                    size={14}
                    className={`text-[var(--muted)] transition-transform duration-[var(--motion-fast)] ${
                      logsExpanded ? "" : "-rotate-90"
                    }`}
                  />
                  <History size={14} className="text-[var(--muted)]" />
                  {t("shareAccessLogs")}
                </button>
                {logsExpanded && (
                  <div className="mt-[var(--space-2)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface-2)] overflow-hidden">
                    {logsLoading ? (
                      <div className="px-[var(--space-3)] py-4 text-center text-[length:var(--text-sm)] text-[var(--muted)]">
                        <Loader2 size={14} className="inline animate-spin mr-1.5" />
                        {t("loading")}
                      </div>
                    ) : accessLogs.length === 0 ? (
                      <div className="px-[var(--space-3)] py-4 text-center text-[length:var(--text-sm)] text-[var(--meta)]">
                        {t("shareNoLogs")}
                      </div>
                    ) : (
                      <div className="divide-y divide-[var(--border-soft)]">
                        {accessLogs.map((log) => (
                          <div
                            key={log.id}
                            className="grid grid-cols-[1fr_auto_auto] gap-[var(--space-2)] px-[var(--space-3)] py-[var(--space-2)] text-[length:var(--text-xs)] items-center"
                          >
                            <span className="text-[var(--fg-2)] font-[family-name:var(--font-mono)] truncate">
                              {log.ip}
                            </span>
                            <span className="text-[var(--meta)] tabular-nums whitespace-nowrap">
                              {new Date(log.accessedAt).toLocaleString()}
                            </span>
                            <span className="text-[var(--meta)] whitespace-nowrap">
                              {uaSummary(log.userAgent)}
                            </span>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>

            {/* 底部操作栏 */}
            <footer className="flex items-center justify-between gap-[var(--space-2)] px-[var(--space-4)] py-[var(--space-3)] border-t border-[var(--border-soft)] shrink-0">
              {/* 撤销分享（两步确认） */}
              {revokeConfirm ? (
                <div className="flex items-center gap-[var(--space-2)]">
                  <span className="text-[length:var(--text-xs)] text-[var(--danger)]">
                    {t("shareRevokeConfirm")}
                  </span>
                  <button
                    onClick={revokeShare}
                    disabled={busy !== null}
                    className="inline-flex items-center gap-1 h-8 px-[var(--space-3)] rounded-[var(--radius-md)] bg-[var(--danger)] text-[var(--danger-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:opacity-90 disabled:opacity-50 transition-opacity focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
                  >
                    {busy === "share" ? (
                      <Loader2 size={14} className="animate-spin" />
                    ) : (
                      <Trash2 size={14} />
                    )}
                    {t("shareRevokeConfirmBtn")}
                  </button>
                  <button
                    onClick={() => setRevokeConfirm(false)}
                    className="h-8 px-[var(--space-3)] rounded-[var(--radius-md)] border border-[var(--border)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
                  >
                    {t("cancel")}
                  </button>
                </div>
              ) : (
                <button
                  onClick={() => setRevokeConfirm(true)}
                  className="inline-flex items-center gap-1.5 h-9 px-[var(--space-3)] rounded-[var(--radius-md)] border border-[var(--border)] text-[length:var(--text-sm)] text-[var(--danger)] hover:bg-[var(--danger-soft)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
                >
                  <Trash2 size={14} />
                  {t("shareRevoke")}
                </button>
              )}
              <button
                onClick={saveShareSettings}
                disabled={busy !== null}
                className="inline-flex items-center gap-1.5 h-9 px-[var(--space-4)] rounded-[var(--radius-md)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] disabled:opacity-50 transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
              >
                {busy === "share" && !revokeConfirm ? (
                  <Loader2 size={14} className="animate-spin" />
                ) : (
                  <Check size={14} />
                )}
                {t("shareSave")}
              </button>
            </footer>
          </div>
        </div>
      )}

      {/* ── F4：导出预览模态框 ── */}
      <ExportPreview
        title={title}
        markdown={markdown}
        open={exportOpen}
        onClose={() => setExportOpen(false)}
        metaLine={`corps · ${new Date().toLocaleString()}`}
      />

      <div className="mt-[var(--space-3)] flex items-center justify-between gap-3 print:hidden">
        <p className="text-[length:var(--text-xs)] text-[var(--muted)]">{t("autosaveHint")}</p>
        {/* 字数统计（v0.6）：去 Markdown 标记后的近似可读字数 */}
        <p className="text-[length:var(--text-xs)] text-[var(--meta)] tabular-nums">
          {t("wordCount", {
            count: markdown
              .replace(/[#>*`\-_|~[\]()]/g, " ")
              .split(/\s+/)
              .filter(Boolean).length,
          })}
        </p>
      </div>
      {/* 打印专用容器：仅在导出模态未打开时渲染（避免与 ExportPreview 的 print-area 重复） */}
      {!exportOpen && (
        <div className="hidden print:block print-area" aria-hidden="true">
          <h1 className="text-[length:var(--text-xl)] font-[weight:var(--weight-semibold)] mb-2">{title}</h1>
          <p className="text-[length:var(--text-xs)] text-[var(--meta)] mb-[var(--space-4)]">
            corps · {new Date().toLocaleString()}
          </p>
          <Markdown source={markdown} />
        </div>
      )}
    </div>
  );
}

"use client";

/**
 * 工作区文档列表页：搜索 + 新建 + 入口到编辑页 + 批量导出（F4）。
 *
 * 数据流：useEffect 拉 GET /documents 列表；搜索是受控 input + 拉取。
 * 新建：POST /documents 获取 id 后跳到编辑页。
 * 批量导出（F4 任务 188）：
 *  - 每个文档行添加复选框
 *  - 选中数量 > 0 时显示批量操作工具栏（全选/取消全选 + 批量导出 + 选中数量）
 *  - 点击"批量导出"：POST /documents/batch-export → 打开 ExportPreview 批量模式预览
 */

import { useEffect, useRef, useState, useDeferredValue, type ComponentProps, type FormEvent } from "react";
import { useTranslations } from "next-intl";
import { useRouter, Link } from "@/lib/i18n-navigation";
import { Plus, Search, FileText, Loader2, X, Download, CheckSquare, Square, Eye, MoreHorizontal, Share2, Pencil, Trash2, FolderInput } from "lucide-react";
import { DocumentPreview } from "@/components/DocumentPreview";
import { useToast } from "@/components/Toast";
import { api } from "@/lib/api";
import { ExportPreview, type BatchDocument } from "@/components/ExportPreview";
import { DocumentListSkeleton } from "@/components/Skeleton";
import { QuickActionMenu, type QuickAction } from "@/components/QuickActionMenu";
import { useLongPress } from "@/lib/use-long-press";
import { motion, AnimatePresence, LayoutGroup } from "framer-motion";
import { useMotionTokens } from "@/lib/motion-tokens";

interface DocumentListItem {
  id: string;
  title: string;
  publishedAt: string | null;
  updatedAt: string;
  author: { id: string; name: string | null; email: string } | null;
}

export function DocumentListView({ wid }: { wid: string }) {
  const t = useTranslations("document");
  const tExport = useTranslations("exportPreview");
  const router = useRouter();
  // 动画 token：感知 F6 三档 + prefers-reduced-motion（见 §2.2 列表布局动画）
  const { slow, easeOut, reduced } = useMotionTokens();
  const [items, setItems] = useState<DocumentListItem[]>([]);
  const [q, setQ] = useState("");
  // M3 修复：搜索防抖——useDeferredValue 让输入快速变化时不立即触发请求，
  // React 会在空闲时提交 deferredQ，避免每个按键都打一次 API。
  const deferredQ = useDeferredValue(q);
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);
  const [error, setError] = useState("");
  const { toast } = useToast();
  const [previewDocument, setPreviewDocument] = useState<ComponentProps<typeof DocumentPreview>["document"] | null>(null);
  const [previewId, setPreviewId] = useState<string | null>(null);
  const [menuId, setMenuId] = useState<string | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);
  const actionInFlight = useRef(false);
  const previewRequest = useRef<AbortController | null>(null);
  const previewDialog = useRef<HTMLDialogElement>(null);

  // ── 长按快捷菜单（QuickActionMenu）──
  const [longPressOpen, setLongPressOpen] = useState(false);
  const [longPressX, setLongPressX] = useState(0);
  const [longPressY, setLongPressY] = useState(0);
  const [longPressItem, setLongPressItem] = useState<DocumentListItem | null>(null);

  const longPressHandlers = useLongPress((pos) => {
    setLongPressX(pos.x);
    setLongPressY(pos.y);
    setLongPressOpen(true);
  });

  const longPressActions: QuickAction[] = longPressItem
    ? [
        {
          icon: Eye,
          label: t("previewMode"),
          onClick: () => openPreview(longPressItem),
        },
        {
          icon: Pencil,
          label: t("rename"),
          onClick: () => router.push(`/w/${wid}/documents/${longPressItem.id}`),
        },
        {
          icon: FolderInput,
          label: t("move"),
          onClick: () => router.push(`/w/${wid}/documents/${longPressItem.id}`),
        },
        {
          icon: Share2,
          label: t("share"),
          onClick: () => runDocumentAction(longPressItem, "share"),
        },
        {
          icon: Trash2,
          label: t("delete"),
          onClick: () => router.push(`/w/${wid}/documents/${longPressItem.id}`),
          danger: true,
        },
      ]
    : [];

  // 原生模态对话框提供焦点圈定、Escape 关闭及关闭后的焦点恢复。
  useEffect(() => {
    if (previewDocument) previewDialog.current?.showModal();
  }, [previewDocument]);

  useEffect(() => {
    return () => previewRequest.current?.abort();
  }, [wid]);

  useEffect(() => {
    if (!menuId) return;
    const closeMenu = (event: PointerEvent) => {
      if (!(event.target instanceof Element) || !event.target.closest("[data-document-actions]")) setMenuId(null);
    };
    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") setMenuId(null);
    };
    document.addEventListener("pointerdown", closeMenu);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("pointerdown", closeMenu);
      document.removeEventListener("keydown", onKey);
    };
  }, [menuId]);

  async function openPreview(item: DocumentListItem) {
    previewRequest.current?.abort();
    const controller = new AbortController();
    previewRequest.current = controller;
    setPreviewId(item.id);
    try {
      const doc = await api<{ title: string; markdown: string }>(
        `/api/v1/workspaces/${wid}/documents/${item.id}`,
        { signal: controller.signal },
      );
      if (!controller.signal.aborted) setPreviewDocument({ title: doc.title, content: doc.markdown, type: "markdown" });
    } catch {
      if (!controller.signal.aborted) toast("error", t("loadFailed"));
    } finally {
      if (!controller.signal.aborted) setPreviewId(null);
    }
  }

  async function runDocumentAction(item: DocumentListItem, action: "share" | "convert") {
    if (actionInFlight.current) return;
    actionInFlight.current = true;
    setBusyId(item.id);
    setMenuId(null);
    try {
      const path = `/api/v1/workspaces/${wid}/documents/${item.id}/${action}`;
      if (action === "share") {
        const result = await api<{ shareUrl: string }>(path, {
          method: "POST",
          body: JSON.stringify({ visibility: "private", expiresIn: 24 }),
        });
        if (!result.shareUrl) throw new Error("Missing share URL");
        try {
          await navigator.clipboard.writeText(new URL(result.shareUrl, window.location.origin).href);
          toast("success", t("shareLinkCopied"));
        } catch {
          toast("error", t("shareCopyFailed"));
        }
      } else {
        const result = await api<{ content: string }>(path, {
          method: "POST",
          body: JSON.stringify({ format: "html" }),
        });
        if (typeof result.content !== "string") throw new Error("Invalid converted content");
        const url = URL.createObjectURL(new Blob([result.content], { type: "text/html;charset=utf-8" }));
        const link = document.createElement("a");
        try {
          link.href = url;
          link.download = `${item.title.replace(/[<>:"/\\\\|?*\u0000-\u001f]/g, "_").slice(0, 120).trim() || item.id}.html`;
          document.body.appendChild(link);
          link.click();
          toast("success", t("exportStarted"));
        } finally {
          link.remove();
          // 下载开始后再释放 URL，避免部分浏览器读取到失效资源。
          window.setTimeout(() => URL.revokeObjectURL(url), 1000);
        }
      }
    } catch {
      toast("error", t(action === "share" ? "shareFailed" : "exportFailed"));
    } finally {
      actionInFlight.current = false;
      setBusyId(null);
    }
  }

  // ── 批量导出状态（F4 任务 188）──
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [batchExporting, setBatchExporting] = useState(false);
  const [batchPreviewOpen, setBatchPreviewOpen] = useState(false);
  const [batchDocuments, setBatchDocuments] = useState<BatchDocument[]>([]);
  const [batchTitle, setBatchTitle] = useState("");

  useEffect(() => {
    let cancelled = false;
    (async () => {
      setLoading(true);
      try {
        const params = new URLSearchParams();
        if (deferredQ) params.set("q", deferredQ);
        const data = await api<DocumentListItem[]>(
          `/api/v1/workspaces/${wid}/documents?${params.toString()}`,
        );
        if (!cancelled) setItems(data);
      } catch (e) {
        if (!cancelled) setError(e instanceof Error ? e.message : t("loadFailed"));
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [wid, deferredQ]);

  async function createDoc(e: FormEvent) {
    e.preventDefault();
    if (creating) return;
    setCreating(true);
    setError("");
    try {
      const res = await api<{ id: string; title: string }>(`/api/v1/workspaces/${wid}/documents`, {
        method: "POST",
        body: JSON.stringify({ title: t("untitledDoc") }),
      });
      router.push(`/w/${wid}/documents/${res.id}`);
    } catch (e) {
      setError(e instanceof Error ? e.message : t("createFailed"));
      setCreating(false);
    }
  }

  // ── 批量选择操作 ──
  function toggleSelect(id: string) {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }

  function toggleSelectAll() {
    if (selectedIds.size === items.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(items.map((d) => d.id)));
    }
  }

  // ── 批量导出 ──
  async function handleBatchExport() {
    if (selectedIds.size === 0 || batchExporting) return;
    setBatchExporting(true);
    setError("");
    try {
      const res = await api<{ html: string; documentCount: number }>(
        `/api/v1/workspaces/${wid}/documents/batch-export`,
        {
          method: "POST",
          body: JSON.stringify({
            documentIds: [...selectedIds],
            format: "pdf",
            includeTableOfContents: true,
          }),
        },
      );

      // 从返回的 HTML 中提取文档内容用于预览
      // API 返回完整 HTML 文档，这里提取每个 section 的内容用于 ExportPreview 预览
      const docs = extractDocumentsFromHtml(res.html);

      setBatchDocuments(docs);
      setBatchTitle(tExport("batchTitle", { count: res.documentCount }));
      setBatchPreviewOpen(true);
    } catch (e) {
      setError(e instanceof Error ? e.message : tExport("batchExportFailed"));
    } finally {
      setBatchExporting(false);
    }
  }

  /**
   * 从 batch-export API 返回的合并 HTML 中提取文档列表用于 ExportPreview 预览。
   * 解析 <section class="doc-section" id="doc-N"> 中的 <h1> 标题和后续内容。
   *
   * 兜底：若解析失败，返回单个文档占位（标题=批量导出，markdown=原始 HTML），
   * 保证预览不空白。
   */
  function extractDocumentsFromHtml(html: string): BatchDocument[] {
    try {
      const docs: BatchDocument[] = [];
      // 匹配每个 doc-section（排除 toc section）
      const sectionRegex =
        /<section class="doc-section" id="doc-(\d+)">([\s\S]*?)<\/section>/g;
      let match: RegExpExecArray | null;
      while ((match = sectionRegex.exec(html)) !== null) {
        const sectionContent = match[2];
        // 提取 <h1> 标题
        const titleMatch = sectionContent.match(/<h1>([\s\S]*?)<\/h1>/);
        const title = titleMatch ? titleMatch[1].trim() : t("untitledDoc");
        // 提取 <div class="doc-meta"> 后的内容作为 markdown（HTML 形式）
        const contentMatch = sectionContent.match(
          /<div class="doc-meta">[\s\S]*?<\/div>([\s\S]*)/,
        );
        const contentHtml = contentMatch ? contentMatch[1].trim() : sectionContent;
        docs.push({ title, markdown: contentHtml });
      }
      return docs.length > 0
        ? docs
        : [{ title: tExport("batchExport"), markdown: html }];
    } catch {
      return [{ title: tExport("batchExport"), markdown: html }];
    }
  }

  const selectedCount = selectedIds.size;
  const allSelected = items.length > 0 && selectedIds.size === items.length;

  return (
    <div className="max-w-[var(--container-max)] mx-auto px-[var(--space-4)] py-[var(--space-6)]">
      <div className="flex items-center justify-between mb-[var(--space-5)]">
        <h1 className="text-[length:var(--text-2xl)] font-[weight:var(--weight-semibold)] text-[var(--fg)] tracking-[var(--tracking-tight)]">
          {t("listTitle")}
        </h1>
        <button
          onClick={createDoc}
          disabled={creating}
          className="inline-flex items-center gap-1.5 h-9 px-[var(--space-3)] rounded-[var(--radius-md)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] disabled:opacity-50 transition-colors duration-[var(--motion-fast)]"
        >
          {creating ? <Loader2 size={14} className="animate-spin" /> : <Plus size={14} />}
          {t("newDocument")}
        </button>
      </div>

      {/* 搜索 */}
      <div className="relative mb-[var(--space-4)]">
        <Search
          size={14}
          className="absolute left-[var(--space-3)] top-1/2 -translate-y-1/2 text-[var(--meta)] pointer-events-none"
        />
        <input
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder={t("searchPlaceholder")}
          className="w-full h-9 pl-9 pr-9 rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] placeholder:text-[var(--meta)]"
        />
        {q && (
          <button
            onClick={() => setQ("")}
            className="absolute right-[var(--space-2)] top-1/2 -translate-y-1/2 p-1 rounded-[var(--radius-sm)] text-[var(--meta)] hover:text-[var(--fg)]"
            aria-label={t("clearSearch")}
          >
            <X size={14} />
          </button>
        )}
      </div>

      {/* 批量操作工具栏（选中数量 > 0 时显示） */}
      {selectedCount > 0 && (
        <div className="flex items-center gap-[var(--space-3)] mb-[var(--space-3)] px-[var(--space-4)] py-[var(--space-2)] rounded-[var(--radius-md)] bg-[var(--surface-2)] border border-[var(--border-soft)]">
          <span className="text-[length:var(--text-sm)] text-[var(--fg-2)]">
            {tExport("documentsSelectedInline", { count: selectedCount })}
          </span>
          <div className="flex-1" />
          <button
            onClick={toggleSelectAll}
            className="inline-flex items-center gap-1.5 h-8 px-[var(--space-3)] rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
          >
            {allSelected ? <CheckSquare size={14} /> : <Square size={14} />}
            {allSelected ? tExport("deselectAll") : tExport("selectAll")}
          </button>
          <button
            onClick={handleBatchExport}
            disabled={batchExporting}
            className="inline-flex items-center gap-1.5 h-8 px-[var(--space-3)] rounded-[var(--radius-sm)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] disabled:opacity-50 transition-colors duration-[var(--motion-fast)]"
          >
            {batchExporting ? <Loader2 size={14} className="animate-spin" /> : <Download size={14} />}
            {tExport("exportBatch")}
          </button>
        </div>
      )}

      {error && <p className="mb-[var(--space-3)] text-[length:var(--text-sm)] text-[var(--danger)]">{error}</p>}

      {loading ? (
        <DocumentListSkeleton count={5} />
      ) : items.length === 0 ? (
        <div className="py-[var(--space-12)] text-center text-[var(--muted)]">
          <FileText size={32} className="mx-auto mb-[var(--space-3)] opacity-50" />
          <p>{q ? t("noSearchResults") : t("emptyState")}</p>
        </div>
      ) : (
        <LayoutGroup>
          <ul className="divide-y divide-[var(--border-soft)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)]">
            <AnimatePresence initial={false}>
              {items.map((d) => {
                const author = d.author?.name || d.author?.email;
                const isSelected = selectedIds.has(d.id);
                return (
                  <motion.li
                    key={d.id}
                    // layout="position"：仅动画位置（等高项），跳过尺寸测量性能最优
                    // 删除/新增时剩余项自动平滑让位（见 §2.2）
                    layout={reduced ? false : "position"}
                    initial={reduced ? false : { opacity: 0, height: 0 }}
                    animate={reduced ? { opacity: 1 } : { opacity: 1, height: "auto" }}
                    // exit：fade + shrink（高度收折），剩余项 layout 让位
                    exit={reduced ? { opacity: 0 } : { opacity: 0, height: 0 }}
                    // var(--motion-slow) 220ms + var(--ease-out) 退场减速
                    transition={reduced ? { duration: 0 } : { duration: slow, ease: easeOut }}
                    className="relative"
                    onPointerDown={(e) => {
                      setLongPressItem(d);
                      longPressHandlers.onPointerDown(e);
                    }}
                    onPointerUp={longPressHandlers.onPointerUp}
                    onPointerLeave={longPressHandlers.onPointerLeave}
                    onPointerCancel={longPressHandlers.onPointerCancel}
                    onContextMenu={(e) => {
                      setLongPressItem(d);
                      longPressHandlers.onContextMenu(e);
                    }}
                  >
                    {/* 复选框（绝对定位在左侧） */}
                    <label
                      className="absolute left-[var(--space-3)] top-1/2 -translate-y-1/2 z-10 cursor-pointer inline-flex items-center justify-center w-4 h-4"
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={isSelected}
                        onChange={() => toggleSelect(d.id)}
                        className="w-4 h-4 rounded-[var(--radius-sm)] border border-[var(--border)] accent-[var(--accent)] cursor-pointer"
                      />
                    </label>
                    <Link
                      href={`/w/${wid}/documents/${d.id}`}
                      className="block px-[var(--space-4)] py-[var(--space-3)] pl-[var(--space-8)] pr-[6rem] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
                    >
                      <div className="flex items-center gap-2">
                        <FileText size={14} className="shrink-0 text-[var(--muted)]" />
                        <span className="flex-1 min-w-0 text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg)] truncate">
                          {d.title}
                        </span>
                        {d.publishedAt ? (
                          <span className="shrink-0 inline-flex items-center gap-1 text-[length:var(--text-xs)] text-[var(--success)]">
                            <span className="inline-block w-1.5 h-1.5 rounded-full bg-[var(--success)]" />
                            {t("publishedBadge")}
                          </span>
                        ) : (
                          <span className="shrink-0 text-[length:var(--text-xs)] text-[var(--muted)]">
                            {t("draftBadge")}
                          </span>
                        )}
                      </div>
                      <div className="mt-[var(--space-1)] ml-6 text-[length:var(--text-xs)] text-[var(--muted)] flex items-center gap-2">
                        {author && <span>{author}</span>}
                        <span>·</span>
                        <span>{t("updatedAt", { date: new Date(d.updatedAt).toLocaleString() })}</span>
                      </div>
                    </Link>
                    <div data-document-actions className="absolute right-[var(--space-3)] top-[var(--space-3)] flex items-center gap-1">
                      <button type="button" onClick={() => openPreview(d)} disabled={previewId === d.id} aria-label={t("previewMode")} title={t("previewMode")} className="p-2 rounded-[var(--radius-sm)] text-[var(--muted)] hover:bg-[var(--surface-2)] hover:text-[var(--fg)] disabled:opacity-50 focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]">
                        {previewId === d.id ? <Loader2 size={14} className="animate-spin" /> : <Eye size={14} />}
                      </button>
                      <button type="button" onClick={() => setMenuId(menuId === d.id ? null : d.id)} disabled={busyId !== null} aria-label={t("moreActions")} aria-expanded={menuId === d.id} aria-controls={`document-actions-${d.id}`} className="p-2 rounded-[var(--radius-sm)] text-[var(--muted)] hover:bg-[var(--surface-2)] hover:text-[var(--fg)] disabled:opacity-50 focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]">
                        {busyId === d.id ? <Loader2 size={14} className="animate-spin" /> : <MoreHorizontal size={14} />}
                      </button>
                      {menuId === d.id && (
                        <div id={`document-actions-${d.id}`} className="absolute right-0 top-full z-20 min-w-40 p-1 rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] shadow-[var(--elev-sm)]" onBlur={(event) => { if (!event.currentTarget.parentElement?.contains(event.relatedTarget)) setMenuId(null); }}>
                          <button type="button" onClick={() => runDocumentAction(d, "share")} className="flex w-full items-center gap-2 px-3 py-2 rounded-[var(--radius-sm)] text-[length:var(--text-sm)] text-[var(--fg)] hover:bg-[var(--surface-2)] focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"><Share2 size={14} />{t("share")}</button>
                          <button type="button" onClick={() => runDocumentAction(d, "convert")} className="flex w-full items-center gap-2 px-3 py-2 rounded-[var(--radius-sm)] text-[length:var(--text-sm)] text-[var(--fg)] hover:bg-[var(--surface-2)] focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"><Download size={14} />{t("export")}</button>
                        </div>
                      )}
                    </div>
                  </motion.li>
                );
              })}
            </AnimatePresence>
          </ul>
        </LayoutGroup>
      )}

      <dialog
        ref={previewDialog}
        aria-label={t("previewMode")}
        onClose={() => setPreviewDocument(null)}
        onClick={(event) => {
          if (event.target === event.currentTarget) {
            const bounds = event.currentTarget.getBoundingClientRect();
            if (event.clientX < bounds.left || event.clientX > bounds.right || event.clientY < bounds.top || event.clientY > bounds.bottom) previewDialog.current?.close();
          }
        }}
        className="m-auto w-[calc(100%-var(--space-8))] max-w-4xl max-h-[90dvh] rounded-[var(--radius-lg)] border border-[var(--border)] bg-[var(--surface)] p-[var(--space-4)] text-[var(--fg)] shadow-[var(--elev-sm)] backdrop:bg-[var(--overlay)]"
      >
        <div className="flex justify-end mb-[var(--space-2)]">
          <button type="button" autoFocus onClick={() => previewDialog.current?.close()} aria-label={t("close")} className="p-2 rounded-[var(--radius-sm)] text-[var(--muted)] hover:bg-[var(--surface-2)] focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"><X size={16} /></button>
        </div>
        {previewDocument && <DocumentPreview document={previewDocument} />}
      </dialog>

      {/* ── 批量导出预览模态框（F4）── */}
      <ExportPreview
        title={batchTitle}
        markdown=""
        open={batchPreviewOpen}
        onClose={() => setBatchPreviewOpen(false)}
        batchMode
        documents={batchDocuments}
      />

      {/* ── 长按快捷菜单 ── */}
      <QuickActionMenu
        open={longPressOpen}
        onClose={() => setLongPressOpen(false)}
        actions={longPressActions}
        x={longPressX}
        y={longPressY}
      />
    </div>
  );
}

"use client";

/**
 * QuickActionMenu — 长按触发的浮窗快捷操作菜单。
 *
 * framer-motion 弹簧入场（scale 0.8→1 + opacity 0→1 + y 8→0），
 * 点击外部或 Esc 关闭。z-index 用 var(--z-dropdown)。
 *
 * @see design/FEATURE-DESIGN-ui-polish.md §4.1 长按浮窗菜单
 */

import { AnimatePresence, motion } from "framer-motion";
import { type LucideIcon } from "lucide-react";
import { useEffect, useRef, type ReactNode } from "react";

export interface QuickAction {
  icon: LucideIcon;
  label: string;
  onClick: () => void;
  /** 危险操作（删除等），用 --danger 色 */
  danger?: boolean;
}

export interface QuickActionMenuProps {
  /** 是否显示 */
  open: boolean;
  /** 关闭回调 */
  onClose: () => void;
  /** 操作列表 */
  actions: QuickAction[];
  /** 触发位置（长按坐标） */
  x: number;
  y: number;
  /** 子元素（触发长按的元素） */
  children?: ReactNode;
}

export function QuickActionMenu({
  open,
  onClose,
  actions,
  x,
  y,
  children,
}: QuickActionMenuProps) {
  const menuRef = useRef<HTMLDivElement>(null);

  // Esc 关闭
  useEffect(() => {
    if (!open) return;
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", handleEsc);
    return () => window.removeEventListener("keydown", handleEsc);
  }, [open, onClose]);

  // 点击外部关闭
  useEffect(() => {
    if (!open) return;
    const handleClickOutside = (e: MouseEvent) => {
      if (
        menuRef.current &&
        !menuRef.current.contains(e.target as Node)
      ) {
        onClose();
      }
    };
    // 延迟绑定避免触发长按的 click 事件
    const timer = setTimeout(() => {
      window.addEventListener("pointerdown", handleClickOutside);
    }, 0);
    return () => {
      clearTimeout(timer);
      window.removeEventListener("pointerdown", handleClickOutside);
    };
  }, [open, onClose]);

  // Focus trap：菜单打开时聚焦首个可聚焦元素，Tab/Shift+Tab 在菜单内循环，
  // 关闭时恢复焦点到触发元素（WAI-ARIA Menu 浮窗规范）
  useEffect(() => {
    if (!open) return;

    // 记录打开前的焦点元素，关闭时恢复
    const previousActiveElement = document.activeElement as HTMLElement | null;

    // 获取菜单内所有可聚焦元素
    const getFocusableElements = () => {
      if (!menuRef.current) return [];
      return Array.from(
        menuRef.current.querySelectorAll<HTMLElement>(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        )
      ).filter((el) => !el.hasAttribute("disabled"));
    };

    // 初始聚焦首个可聚焦元素
    const initialFocusable = getFocusableElements();
    if (initialFocusable.length > 0) {
      initialFocusable[0].focus();
    }

    // Tab / Shift+Tab 在首尾元素间循环
    const handleTabKey = (e: KeyboardEvent) => {
      if (e.key !== "Tab") return;
      if (!menuRef.current) return;

      const focusable = getFocusableElements();
      if (focusable.length === 0) return;

      const firstElement = focusable[0];
      const lastElement = focusable[focusable.length - 1];

      if (e.shiftKey) {
        // Shift+Tab：从第一个跳到最后一个
        if (document.activeElement === firstElement) {
          e.preventDefault();
          lastElement.focus();
        }
      } else {
        // Tab：从最后一个跳到第一个
        if (document.activeElement === lastElement) {
          e.preventDefault();
          firstElement.focus();
        }
      }
    };

    window.addEventListener("keydown", handleTabKey);

    return () => {
      window.removeEventListener("keydown", handleTabKey);
      // 关闭时恢复焦点到触发元素
      if (previousActiveElement) {
        previousActiveElement.focus();
      }
    };
  }, [open]);

  return (
    <AnimatePresence>
      {open && (
        <motion.div
          ref={menuRef}
          initial={{ opacity: 0, scale: 0.8, y: 8 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.8, y: 8 }}
          transition={{ type: "spring", stiffness: 400, damping: 28, mass: 1 }}
          style={{
            position: "fixed",
            left: x,
            top: y,
            zIndex: "var(--z-dropdown)",
          }}
          className="min-w-[160px] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] shadow-[var(--elev-md)] overflow-hidden"
        >
          {actions.map((action) => {
            const Icon = action.icon;
            return (
              <button
                key={action.label}
                onClick={() => {
                  action.onClick();
                  onClose();
                }}
                className={`flex w-full items-center gap-[var(--space-2)] px-[var(--space-3)] py-[var(--space-2)] text-left text-[length:var(--text-sm)] transition-colors duration-[var(--motion-fast)] hover:bg-[var(--hover-soft)] ${
                  action.danger
                    ? "text-[var(--danger)]"
                    : "text-[var(--fg)]"
                }`}
              >
                <Icon size={16} className="shrink-0" />
                {action.label}
              </button>
            );
          })}
        </motion.div>
      )}
    </AnimatePresence>
  );
}

"use client";

/**
 * 回收站组件（阶段 6 任务 223）
 *
 * 功能：
 *  - 类型筛选标签页：全部 / 任务 / 文档
 *  - 列表表格：选择 | 名称 | 类型 | 删除时间 | 删除人 | 剩余保留天数 | 操作（恢复 | 永久删除）
 *  - 分页
 *  - 单项恢复（POST /recycle-bin/{id}）
 *  - 单项永久删除（DELETE /recycle-bin/{id}，自定义确认对话框）
 *  - 批量恢复（多选 + 批量恢复按钮）
 *  - 批量永久删除（多选 + 批量删除按钮，自定义确认对话框）
 *  - 清空回收站（永久删除所有项，自定义确认对话框）
 *  - 30 天保留期显示（剩余天数，到期标红）
 *  - 空状态提示
 *
 * 数据流：useEffect 拉 GET /recycle-bin 列表；类型筛选 / 翻页触发重新拉取。
 * 操作后乐观从列表移除并刷新计数。
 * 确认对话框为自定义 modal（焦点陷阱 + Escape 关闭），不使用 window.confirm。
 * Toast 通过全局 ToastProvider（useToast）显示操作结果。
 */

import { useEffect, useState, useCallback, useRef } from "react";
import { useTranslations } from "next-intl";
import {
  Trash2,
  RotateCcw,
  FileText,
  CheckSquare,
  Loader2,
  ChevronLeft,
  ChevronRight,
  AlertTriangle,
  X,
} from "lucide-react";
import { api, ApiError } from "@/lib/api";
import { useToast } from "@/components/Toast";

/** 回收站条目（与 API 响应一致） */
interface RecycleItem {
  id: string;
  type: "task" | "document";
  name: string;
  deletedAt: string;
  deletedBy: string | null;
}

/** 列表响应分页结构 */
interface RecycleListResponse {
  items: RecycleItem[];
  page: number;
  limit: number;
  total: number;
  hasMore: boolean;
}

/** 类型筛选值 */
type TypeFilter = "all" | "task" | "document";

/** 确认对话框状态 */
interface ConfirmState {
  open: boolean;
  title: string;
  message: string;
  /** 确认后的回调（已绑定具体操作） */
  onConfirm: () => void;
}

const PAGE_SIZE = 20;
/** 保留期天数（与后端约定一致） */
const RETENTION_DAYS = 30;
/** 一天的毫秒数 */
const ONE_DAY_MS = 24 * 60 * 60 * 1000;

/**
 * 计算剩余保留天数。
 * @param deletedAt ISO 字符串
 * @returns 剩余天数（>0 未过期；<=0 已过期）
 */
function getRemainingDays(deletedAt: string): number {
  const deleted = new Date(deletedAt).getTime();
  const elapsedDays = Math.floor((Date.now() - deleted) / ONE_DAY_MS);
  return RETENTION_DAYS - elapsedDays;
}

export function RecycleBin({ workspaceId }: { workspaceId: string }) {
  const t = useTranslations("recycleBin");
  const { toast } = useToast();

  const [items, setItems] = useState<RecycleItem[]>([]);
  const [filter, setFilter] = useState<TypeFilter>("all");
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [hasMore, setHasMore] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  // 单项操作 loading（按 id 记录，避免并发误操作）
  const [actionLoadingId, setActionLoadingId] = useState<string | null>(null);
  // 批量操作 loading
  const [batchLoading, setBatchLoading] = useState(false);
  // 清空操作 loading
  const [clearLoading, setClearLoading] = useState(false);

  // 多选：选中项 id 集合（用 type-id 复合键，避免 task/document id 冲突）
  const [selectedKeys, setSelectedKeys] = useState<Set<string>>(new Set());

  // 确认对话框状态
  const [confirm, setConfirm] = useState<ConfirmState>({
    open: false,
    title: "",
    message: "",
    onConfirm: () => {},
  });
  // 确认对话框执行中（禁用按钮 + 显示 spinner）
  const [confirmLoading, setConfirmLoading] = useState(false);
  // 确认对话框焦点陷阱 ref
  const confirmDialogRef = useRef<HTMLDivElement>(null);

  /** 生成列表项复合键 */
  const itemKey = (item: RecycleItem) => `${item.type}-${item.id}`;

  const fetchList = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      const params = new URLSearchParams();
      if (filter !== "all") params.set("type", filter);
      params.set("page", String(page));
      params.set("limit", String(PAGE_SIZE));
      const data = await api<RecycleListResponse>(
        `/api/v1/workspaces/${workspaceId}/recycle-bin?${params.toString()}`,
      );
      setItems(data.items);
      setTotal(data.total);
      setHasMore(data.hasMore);
    } catch (e) {
      setError(e instanceof Error ? e.message : t("loadFailed"));
    } finally {
      setLoading(false);
    }
  }, [workspaceId, filter, page, t]);

  useEffect(() => {
    fetchList();
  }, [fetchList]);

  // 切换筛选时回到第一页
  function changeFilter(next: TypeFilter) {
    if (next === filter) return;
    setFilter(next);
    setPage(1);
    setSelectedKeys(new Set());
  }

  // ─── 多选 ───────────────────────────────────────────────
  const toggleSelect = useCallback((key: string) => {
    setSelectedKeys((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  }, []);

  const allSelected = items.length > 0 && items.every((it) => selectedKeys.has(itemKey(it)));
  const someSelected = selectedKeys.size > 0;

  function toggleSelectAll() {
    if (allSelected) {
      setSelectedKeys(new Set());
    } else {
      setSelectedKeys(new Set(items.map(itemKey)));
    }
  }

  function clearSelection() {
    setSelectedKeys(new Set());
  }

  // ─── 确认对话框焦点管理 ──────────────────────────────────
  useEffect(() => {
    if (!confirm.open) return;
    const previouslyFocused = document.activeElement as HTMLElement | null;
    const container = confirmDialogRef.current;
    if (container) {
      const focusable = container.querySelector<HTMLElement>(
        'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
      );
      focusable?.focus();
    }
    return () => {
      previouslyFocused?.focus?.();
    };
  }, [confirm.open]);

  // Escape 关闭 + Tab focus trap
  useEffect(() => {
    if (!confirm.open) return;
    const container = confirmDialogRef.current;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && !confirmLoading) {
        e.preventDefault();
        setConfirm((c) => ({ ...c, open: false }));
        return;
      }
      if (e.key === "Tab" && container) {
        const focusables = Array.from(
          container.querySelectorAll<HTMLElement>(
            'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"]):not([disabled])',
          ),
        );
        if (focusables.length === 0) return;
        const first = focusables[0];
        const last = focusables[focusables.length - 1];
        if (e.shiftKey) {
          if (document.activeElement === first) {
            e.preventDefault();
            last.focus();
          }
        } else {
          if (document.activeElement === last) {
            e.preventDefault();
            first.focus();
          }
        }
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [confirm.open, confirmLoading]);

  function openConfirm(title: string, message: string, onConfirm: () => void) {
    setConfirm({ open: true, title, message, onConfirm });
  }

  function closeConfirm() {
    setConfirm((c) => ({ ...c, open: false }));
  }

  // ─── 单项恢复 ───────────────────────────────────────────
  async function handleRestore(item: RecycleItem) {
    if (actionLoadingId) return;
    setActionLoadingId(item.id);
    try {
      await api(`/api/v1/workspaces/${workspaceId}/recycle-bin/${item.id}`, {
        method: "POST",
      });
      // 乐观从列表移除
      const key = itemKey(item);
      setItems((prev) => prev.filter((it) => itemKey(it) !== key));
      setTotal((prev) => Math.max(0, prev - 1));
      setSelectedKeys((prev) => {
        const next = new Set(prev);
        next.delete(key);
        return next;
      });
      toast("success", t("restored"));
    } catch (e) {
      const msg = e instanceof ApiError ? e.message : e instanceof Error ? e.message : t("restoreFailed");
      toast("error", msg);
    } finally {
      setActionLoadingId(null);
    }
  }

  // ─── 单项永久删除（带确认对话框） ───────────────────────
  function handlePermanentDeleteClick(item: RecycleItem) {
    if (actionLoadingId) return;
    openConfirm(t("confirmDeleteTitle"), t("confirmDelete"), () => {
      runPermanentDelete(item);
    });
  }

  async function runPermanentDelete(item: RecycleItem) {
    setConfirmLoading(true);
    setActionLoadingId(item.id);
    try {
      await api(`/api/v1/workspaces/${workspaceId}/recycle-bin/${item.id}`, {
        method: "DELETE",
      });
      const key = itemKey(item);
      setItems((prev) => prev.filter((it) => itemKey(it) !== key));
      setTotal((prev) => Math.max(0, prev - 1));
      setSelectedKeys((prev) => {
        const next = new Set(prev);
        next.delete(key);
        return next;
      });
      toast("success", t("deleted"));
      closeConfirm();
    } catch (e) {
      const msg = e instanceof ApiError ? e.message : e instanceof Error ? e.message : t("deleteFailed");
      toast("error", msg);
    } finally {
      setConfirmLoading(false);
      setActionLoadingId(null);
    }
  }

  // ─── 批量恢复 ───────────────────────────────────────────
  async function handleBatchRestore() {
    if (batchLoading || selectedKeys.size === 0) return;
    setBatchLoading(true);
    // 选中项（当前页可见的）
    const selectedItems = items.filter((it) => selectedKeys.has(itemKey(it)));
    let successCount = 0;
    let lastError = "";
    // 串行调用（避免后端并发压力；回收站批量操作频率低）
    for (const item of selectedItems) {
      try {
        await api(`/api/v1/workspaces/${workspaceId}/recycle-bin/${item.id}`, {
          method: "POST",
        });
        successCount++;
      } catch (e) {
        lastError = e instanceof Error ? e.message : t("restoreFailed");
      }
    }
    if (successCount > 0) {
      // 乐观更新计数；具体列表由下方 fetchList 拉取保证一致性
      setTotal((prev) => Math.max(0, prev - successCount));
      clearSelection();
      toast("success", t("batchRestored", { count: successCount }));
    }
    if (lastError) {
      toast("error", lastError);
    }
    setBatchLoading(false);
    // 重新拉取列表以确保一致性
    await fetchList();
  }

  // ─── 批量永久删除（带确认对话框） ───────────────────────
  function handleBatchDeleteClick() {
    if (batchLoading || selectedKeys.size === 0) return;
    openConfirm(t("confirmBatchDeleteTitle"), t("confirmBatchDelete"), () => {
      runBatchDelete();
    });
  }

  async function runBatchDelete() {
    setConfirmLoading(true);
    setBatchLoading(true);
    const selectedItems = items.filter((it) => selectedKeys.has(itemKey(it)));
    let successCount = 0;
    let lastError = "";
    for (const item of selectedItems) {
      try {
        await api(`/api/v1/workspaces/${workspaceId}/recycle-bin/${item.id}`, {
          method: "DELETE",
        });
        successCount++;
      } catch (e) {
        lastError = e instanceof Error ? e.message : t("deleteFailed");
      }
    }
    if (successCount > 0) {
      setTotal((prev) => Math.max(0, prev - successCount));
      clearSelection();
      toast("success", t("batchDeleted", { count: successCount }));
      closeConfirm();
    }
    if (lastError) {
      toast("error", lastError);
    }
    setConfirmLoading(false);
    setBatchLoading(false);
    await fetchList();
  }

  // ─── 清空回收站（带确认对话框） ─────────────────────────
  function handleClearAllClick() {
    if (clearLoading || items.length === 0) return;
    openConfirm(t("confirmClearTitle"), t("confirmClearAll"), () => {
      runClearAll();
    });
  }

  async function runClearAll() {
    setConfirmLoading(true);
    setClearLoading(true);
    // 清空当前页所有项（分页场景下逐个删除当前可见项）
    // 注：回收站数据量通常较小（保留期 30 天），当前页删除后若 hasMore 可继续拉取
    let successCount = 0;
    let lastError = "";
    for (const item of items) {
      try {
        await api(`/api/v1/workspaces/${workspaceId}/recycle-bin/${item.id}`, {
          method: "DELETE",
        });
        successCount++;
      } catch (e) {
        lastError = e instanceof Error ? e.message : t("clearFailed");
      }
    }
    if (successCount > 0) {
      clearSelection();
      toast("success", t("cleared"));
      closeConfirm();
    }
    if (lastError) {
      toast("error", lastError);
    }
    setConfirmLoading(false);
    setClearLoading(false);
    // 重新拉取（若 hasMore 仍有剩余页项，会显示新的一页）
    setPage(1);
    await fetchList();
  }

  // ─── 渲染辅助 ───────────────────────────────────────────
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const filterTabs: { key: TypeFilter; label: string }[] = [
    { key: "all", label: t("all") },
    { key: "task", label: t("tasks") },
    { key: "document", label: t("documents") },
  ];

  return (
    <div className="max-w-[var(--container-max)] mx-auto px-[var(--space-4)] py-[var(--space-6)]">
      {/* 标题 + 顶部操作栏 */}
      <div className="flex items-center justify-between gap-[var(--space-4)] mb-[var(--space-5)] flex-wrap">
        <div className="flex items-center gap-2">
          <Trash2 size={20} className="text-[var(--muted)]" />
          <h1 className="text-[length:var(--text-2xl)] font-[weight:var(--weight-semibold)] text-[var(--fg)] tracking-[var(--tracking-tight)]">
            {t("title")}
          </h1>
        </div>
        {/* 顶部操作：批量恢复 / 清空回收站 */}
        {!loading && items.length > 0 && (
          <div className="flex items-center gap-[var(--space-2)]">
            <button
              onClick={handleBatchRestore}
              disabled={batchLoading || !someSelected}
              className="inline-flex items-center gap-1.5 h-8 px-[var(--space-3)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] bg-[var(--surface)] border border-[var(--border)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
            >
              {batchLoading ? (
                <Loader2 size={14} className="animate-spin" />
              ) : (
                <RotateCcw size={14} />
              )}
              {t("batchRestore")}
            </button>
            <button
              onClick={handleClearAllClick}
              disabled={clearLoading || batchLoading}
              className="inline-flex items-center gap-1.5 h-8 px-[var(--space-3)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] bg-[var(--surface)] border border-[var(--border)] text-[var(--danger)] hover:bg-[var(--danger-soft)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
            >
              {clearLoading ? (
                <Loader2 size={14} className="animate-spin" />
              ) : (
                <Trash2 size={14} />
              )}
              {t("clearAll")}
            </button>
          </div>
        )}
      </div>

      {/* 类型筛选标签页 */}
      <div className="flex items-center gap-1 mb-[var(--space-4)] border-b border-[var(--border-soft)]">
        {filterTabs.map((tab) => (
          <button
            key={tab.key}
            onClick={() => changeFilter(tab.key)}
            className={
              "inline-flex items-center gap-1.5 h-9 px-3 text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] transition-colors duration-[var(--motion-fast)] border-b-2 -mb-px " +
              (filter === tab.key
                ? "border-[var(--accent)] text-[var(--fg)]"
                : "border-transparent text-[var(--muted)] hover:text-[var(--fg)]")
            }
          >
            {tab.key === "task" && <CheckSquare size={14} />}
            {tab.key === "document" && <FileText size={14} />}
            {tab.label}
          </button>
        ))}
      </div>

      {/* 选中计数提示 */}
      {someSelected && (
        <div className="mb-[var(--space-3)] flex items-center gap-2 px-[var(--space-3)] py-[var(--space-2)] rounded-[var(--radius-md)] bg-[var(--accent-soft)] text-[var(--accent-soft-fg)] text-[length:var(--text-sm)]">
          <CheckSquare size={14} />
          <span>{t("selected", { count: selectedKeys.size })}</span>
          <button
            onClick={clearSelection}
            className="ml-auto inline-flex items-center gap-1 text-[var(--muted)] hover:text-[var(--fg)] transition-colors duration-[var(--motion-fast)]"
