// ── ProseMirror JSON doc 子集类型 ──────────────────────────────────────────
// 自定义而非导入 @tiptap/core 的 JSONContent，避免 pnpm 严格解析耦合；
// 结构与 TipTap getJSON() 返回值兼容，遍历只用到这几个字段。
interface DocNode {
  type?: string;
  content?: DocNode[];
  text?: string;
  attrs?: Record<string, unknown>;
  marks?: { type: string; attrs?: Record<string, unknown> }[];
}

// ── markdown → HTML（用于初始化 TipTap content）───────────────────────────
// 按行扫描的状态机，覆盖：标题 H1-H3、粗体/斜体/删除线/行内代码/链接、
// 无序/有序/任务列表、引用、代码块、分割线、段落。未覆盖语法降级为纯文本。
function escapeHtml(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

/** 行内标记 → HTML（先转义，再按顺序替换；行内代码内容不再二次处理） */
function inlineMdToHtml(s: string): string {
  // 先把行内代码提取占位，避免内容被后续规则破坏
  const codes: string[] = [];
  let r = escapeHtml(s).replace(/`([^`]+)`/g, (_m, code) => {
    codes.push(code);
    return `\u0000CODE${codes.length - 1}\u0000`;
  });
  r = r.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
  r = r.replace(/\*([^*]+)\*/g, "<em>$1</em>");
  r = r.replace(/~~([^~]+)~~/g, "<s>$1</s>");
  r = r.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, '<a href="$2">$1</a>');
  // 还原行内代码
  r = r.replace(/\u0000CODE(\d+)\u0000/g, (_m, idx) => `<code>${codes[Number(idx)]}</code>`);
  return r;
}

function markdownToHtml(md: string): string {
  if (!md.trim()) return "<p></p>";
  const lines = md.replace(/\r\n/g, "\n").split("\n");
  const out: string[] = [];
  let i = 0;
  let inCode = false;
  let codeBuf: string[] = [];
  let listOpen: "ul" | "ol" | "task" | null = null;
  let quoteBuf: string[] = [];

  const flushQuote = () => {
    if (quoteBuf.length) {
      out.push(`<blockquote><p>${quoteBuf.map(inlineMdToHtml).join("<br>")}</p></blockquote>`);
      quoteBuf = [];
    }
  };
  const flushList = () => {
    if (listOpen === "task") out.push("</ul>");
    else if (listOpen) out.push(`</${listOpen}>`);
    listOpen = null;
  };

  while (i < lines.length) {
    const line = lines[i];

    // 代码块围栏
    if (/^```/.test(line)) {
      if (!inCode) {
        flushQuote();
        flushList();
        inCode = true;
        codeBuf = [];
      } else {
        out.push(`<pre><code>${escapeHtml(codeBuf.join("\n"))}</code></pre>`);
        inCode = false;
      }
      i++;
      continue;
    }
    if (inCode) {
      codeBuf.push(line);
      i++;
      continue;
    }

    // 空行：结束当前块
    if (line.trim() === "") {
      flushQuote();
      flushList();
      i++;
      continue;
    }

    // 分割线
    if (/^(---|\*\*\*|___)\s*$/.test(line)) {
      flushQuote();
      flushList();
      out.push("<hr>");
      i++;
      continue;
    }

    // 标题 H1-H3
    const h = line.match(/^(#{1,3})\s+(.*)$/);
    if (h) {
      flushQuote();
      flushList();
      const lvl = h[1].length;
      out.push(`<h${lvl}>${inlineMdToHtml(h[2])}</h${lvl}>`);
      i++;
      continue;
    }

    // 引用
    const q = line.match(/^>\s?(.*)$/);
    if (q) {
      flushList();
      quoteBuf.push(q[1]);
      i++;
      continue;
    }
    flushQuote();

    // 任务列表项
    const tl = line.match(/^[-*]\s+\[([ xX])\]\s+(.*)$/);
    if (tl) {
      if (listOpen !== "task") {
        flushList();
        out.push('<ul data-type="taskList">');
        listOpen = "task";
      }
      const checked = tl[1].toLowerCase() === "x";
      out.push(
        `<li data-type="taskItem" data-checked="${checked}"><p>${inlineMdToHtml(tl[2])}</p></li>`,
      );
      i++;
      continue;
    }

    // 无序列表项
    const ul = line.match(/^[-*]\s+(.*)$/);
    if (ul) {
      if (listOpen !== "ul") {
        flushList();
        out.push("<ul>");
        listOpen = "ul";
      }
      out.push(`<li><p>${inlineMdToHtml(ul[1])}</p></li>`);
      i++;
      continue;
    }

    // 有序列表项
    const ol = line.match(/^\d+\.\s+(.*)$/);
    if (ol) {
      if (listOpen !== "ol") {
        flushList();
        out.push("<ol>");
        listOpen = "ol";
      }
      out.push(`<li><p>${inlineMdToHtml(ol[1])}</p></li>`);
      i++;
      continue;
    }

    // 普通段落
    flushList();
    out.push(`<p>${inlineMdToHtml(line)}</p>`);
    i++;
  }

  // 未闭合代码块兜底
  if (inCode) out.push(`<pre><code>${escapeHtml(codeBuf.join("\n"))}</code></pre>`);
  flushQuote();
  flushList();
  return out.join("");
}

// ── TipTap JSON doc → markdown ─────────────────────────────────────────────
/** 行内 marks → markdown 包裹 */
function inlineToMd(node: DocNode): string {
  const text = node.text ?? "";
  if (!node.marks || node.marks.length === 0) return text;
  return node.marks.reduce((acc, mark) => {
    switch (mark.type) {
      case "bold":
        return `**${acc}**`;
      case "italic":
        return `*${acc}*`;
      case "strike":
        return `~~${acc}~~`;
      case "code":
        return `\`${acc}\``;
      case "link": {
        const href = String(mark.attrs?.href ?? "");
        return href ? `[${acc}](${href})` : acc;
      }
      default:
        return acc;
    }
  }, text);
}

/** 递归把节点序列化为 markdown 片段 */
function nodeToMd(node: DocNode, depth = 0): string {
  const inline = (n: DocNode): string =>
    n.content?.map(inlineToMd).join("") ?? inlineToMd(n);

  switch (node.type) {
    case "heading": {
      const level = Number(node.attrs?.level ?? 1);
      return `${"#".repeat(Math.min(level, 3))} ${inline(node)}\n\n`;
    }
    case "paragraph":
      return `${inline(node)}\n\n`;
    case "bulletList":
      return (node.content ?? []).map((n) => listItemToMd(n, "- ")).join("");
    case "orderedList":
      return (node.content ?? [])
        .map((n, idx) => listItemToMd(n, `${idx + 1}. `))
        .join("");
    case "taskList":
      return (node.content ?? []).map((n) => taskItemToMd(n)).join("");
    case "blockquote":
      return (
        (node.content ?? [])
          .map((n) => nodeToMd(n, depth + 1).trimEnd())
          .join("\n")
          .split("\n")
          .map((l) => `> ${l}`)
          .join("\n") + "\n\n"
      );
    case "codeBlock": {
      const code = node.content?.[0]?.text ?? "";
      return "```\n" + code + "\n```\n\n";
    }
    case "horizontalRule":
      return "---\n\n";
    case "hardBreak":
      return "\n";
    case "text":
      return inlineToMd(node);
    case "decisionMark": {
      // 决策标记序列化为引用块占位 `> [decision:id title]`
      // 反向 markdown→html 时不还原为节点（降级为引用文本），但内容不丢
      const a = node.attrs ?? {};
      const id = String(a.decisionId ?? "");
      const title = String(a.title ?? "");
      const status = String(a.status ?? "todo");
      const due = a.dueDate ? ` due="${String(a.dueDate)}"` : "";
      const ver = a.version != null ? ` v="${String(a.version)}"` : "";
      return `> [decision:${id} "${title}" status=${status}${due}${ver}]\n\n`;
    }
    case "taskEmbed": {
      // 任务嵌入序列化为引用块占位 `> [task:id title]`
      const a = node.attrs ?? {};
      const id = String(a.taskId ?? "");
      const title = String(a.title ?? "");
      const status = String(a.status ?? "todo");
      const assignee = a.assigneeName ? ` assignee="${String(a.assigneeName)}"` : "";
      const due = a.dueDate ? ` due="${String(a.dueDate)}"` : "";
      return `> [task:${id} "${title}" status=${status}${assignee}${due}]\n\n`;
    }
    default:
      return inline(node);
  }
}

function listItemToMd(node: DocNode, marker: string): string {
  // listItem.content 通常是 paragraph[]
  const inner = (node.content ?? [])
    .map((n) => nodeToMd(n).trimEnd())
    .join("\n");
  return `${marker}${inner.replace(/\n/g, "\n  ")}\n`;
}

function taskItemToMd(node: DocNode): string {
  const checked = Boolean(node.attrs?.checked);
  const inner = (node.content ?? [])
    .map((n) => nodeToMd(n).trimEnd())
    .join("\n");
  return `- [${checked ? "x" : " "}] ${inner}\n`;
}

/** TipTap JSON doc → markdown 字符串 */
function tiptapToMarkdown(doc: DocNode): string {
  const raw = (doc.content ?? []).map((n) => nodeToMd(n)).join("");
  // 收敛连续空行（最多保留一个空行），去首尾空白
  return raw.replace(/\n{3,}/g, "\n\n").trim();
}

// ── 组件 ───────────────────────────────────────────────────────────────────

export interface RichTextEditorHandle {
  /** 在光标处插入 markdown 片段（模板/图表复用） */
  insertMarkdown: (md: string) => void;
  /** 聚焦编辑器 */
  focus: () => void;
}

interface RichTextEditorProps {
  /** markdown 字符串（受控值；富文本模式非反向同步，仅初始化与模式切换时消费） */
  value: string;
  /** 内容变更回调（始终传出 markdown 字符串） */
  onChange: (md: string) => void;
  /** 失焦回调（自动保存触发） */
  onBlur: () => void;
  /** 分屏模式：编辑与预览并排 */
  split?: boolean;
  /** 占位文案 */
  placeholder?: string;
  /** 容器附加类名 */
  className?: string;
  /** 当前 workspace id（用于决策/任务卡片点击跳转，可选） */
  wid?: string;
  /** Slash Menu 触发插入决策标记时回调（父组件打开决策选择器，可选） */
  onInsertDecision?: () => void;
  /** Slash Menu 触发插入任务嵌入时回调（父组件打开任务选择器，可选） */
  onInsertTask?: () => void;
}

/** 工具栏按钮基础类名（design token，与 MarkdownToolbar 风格一致） */
const TOOLBAR_BTN =
  "p-1.5 rounded-[var(--radius-sm)] text-[var(--fg-2)] hover:bg-[var(--surface)] hover:text-[var(--fg)] disabled:opacity-40 disabled:cursor-not-allowed transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]";
const TOOLBAR_BTN_ACTIVE = "bg-[var(--surface)] text-[var(--accent)]";

export const RichTextEditor = forwardRef<RichTextEditorHandle, RichTextEditorProps>(
  function RichTextEditor(
    { value, onChange, onBlur, split, placeholder, className, wid, onInsertDecision, onInsertTask },
    ref,
  ) {
    const t = useTranslations("editor");
    /** Slash Menu 命令文案（i18n） */
    const tSlash = useTranslations("editor.slashMenu");
    /** 编辑模式：richtext（TipTap）| markdown（源码 textarea） */
    const [mode, setMode] = useState<"richtext" | "markdown">("richtext");
    /** TipTap 重挂载 key：markdown→richtext 切换时递增，用最新 value 重新初始化 */
    const [richtextKey, setRichtextKey] = useState(0);

    // Slash Menu 命令文案映射（i18n → SlashCommandLabel）
    // 用 useMemo 缓存避免每次 render 重建对象触发 Suggestion items 重算
    const slashLabels = useMemo<Record<SlashCommandKey, SlashCommandLabel>>(
      () => ({
        h1: { label: tSlash("h1.label"), description: tSlash("h1.description") },
        h2: { label: tSlash("h2.label"), description: tSlash("h2.description") },
        bulletList: {
          label: tSlash("bulletList.label"),
          description: tSlash("bulletList.description"),
        },
        orderedList: {
          label: tSlash("orderedList.label"),
          description: tSlash("orderedList.description"),
        },
        taskList: {
          label: tSlash("taskList.label"),
          description: tSlash("taskList.description"),
        },
        quote: { label: tSlash("quote.label"), description: tSlash("quote.description") },
        codeBlock: {
          label: tSlash("codeBlock.label"),
          description: tSlash("codeBlock.description"),
        },
        divider: {
          label: tSlash("divider.label"),
          description: tSlash("divider.description"),
        },
        table: { label: tSlash("table.label"), description: tSlash("table.description") },
        image: { label: tSlash("image.label"), description: tSlash("image.description") },
        decision: {
          label: tSlash("decision.label"),
          description: tSlash("decision.description"),
        },
        task: { label: tSlash("task.label"), description: tSlash("task.description") },
      }),
      [tSlash],
    );
    const slashEmptyText = tSlash("empty");

    // 回调 ref：useEditor 的 onUpdate/onBlur 闭包只捕获一次，
    // 用 ref 始终调最新回调，避免父组件每次 render 新函数导致的 stale closure。
    const onChangeRef = useRef(onChange);
    const onBlurRef = useRef(onBlur);
    const valueRef = useRef(value);
    useEffect(() => {
      onChangeRef.current = onChange;
    });
    useEffect(() => {
      onBlurRef.current = onBlur;
    });
    useEffect(() => {
      valueRef.current = value;
    });

    // ── Markdown 源码模式 textarea ──
    const textareaRef = useRef<HTMLTextAreaElement>(null);
    const handleKeyDown = useEditorKeys({
      textareaRef,
      value,
      onChange,
    });

    // ── TipTap 编辑器 ──
    // 仅在 richtextKey 变化时重新构造（模式切换回富文本时重新初始化）。
    // content 用 markdownToHtml(valueRef.current) —— 闭包捕获挂载时刻的 value。
    const editor = useEditor(
      {
        extensions: [
          StarterKit.configure({
            heading: { levels: [1, 2, 3] },
            // StarterKit 默认含 codeBlock（无语法高亮），符合任务要求
          }),
          Placeholder.configure({
            placeholder: placeholder ?? "",
            emptyEditorClass: "is-editor-empty",
          }),
          TaskList,
          TaskItem.configure({ nested: true }),
          // Phase 1b：表格扩展（Slash Menu /table 命令需要）
          Table.configure({ resizable: true }),
          TableRow,
          TableCell,
          TableHeader,
          // Phase 1b：Slash Menu 命令面板
          SlashMenuExtension.configure({
            labels: slashLabels,
            emptyText: slashEmptyText,
            onInsertDecision,
            onInsertTask,
          }),
          // Phase 1b：决策标记块级节点
          DecisionMark.configure({ wid: wid ?? "" }),
          // Phase 1b：任务嵌入块级节点
          TaskEmbed.configure({ wid: wid ?? "" }),
        ],
        content: markdownToHtml(valueRef.current),
        editorProps: {
          attributes: {
            class:
              "tiptap-prose min-h-[60dvh] p-[var(--space-4)] outline-none text-[var(--fg)] text-[length:var(--text-sm)] leading-[var(--leading-normal)]",
          },
        },
        onUpdate: ({ editor }) => {
          onChangeRef.current(tiptapToMarkdown(editor.getJSON() as DocNode));
        },
      },
      [richtextKey],
    );

    // 监听 TipTap blur 触发自动保存（editorProps 无 handleBlur，用事件系统）
    useEffect(() => {
      if (!editor) return;
      const handler = () => onBlurRef.current();
      editor.on("blur", handler);
      return () => {
        editor.off("blur", handler);
      };
    }, [editor]);

    // 暴露 ref API 给父组件
    useImperativeHandle(
      ref,
      (): RichTextEditorHandle => ({
        insertMarkdown: (md: string) => {
          if (mode === "richtext" && editor) {
            // 富文本模式：转 HTML 插入光标处
            const html = markdownToHtml(md);
            editor.chain().focus().insertContent(html).run();
          } else {
            // Markdown 源码模式：在 textarea 光标处插入纯文本
            const ta = textareaRef.current;
            if (ta) {
              const start = ta.selectionStart ?? value.length;
              const end = ta.selectionEnd ?? value.length;
              const next = value.slice(0, start) + md + value.slice(end);
              onChange(next);
              requestAnimationFrame(() => {
                ta.focus();
                const pos = start + md.length;
                ta.setSelectionRange(pos, pos);
              });
            } else {
              // 无光标信息：追加
              const sep = value.endsWith("\n") || value === "" ? "" : "\n\n";
              onChange(value + sep + md);
            }
          }
        },
        focus: () => {
          if (mode === "richtext" && editor) {
            editor.commands.focus();
          } else {
            textareaRef.current?.focus();
          }
        },
      }),
      [editor, mode, value, onChange],
    );

    // ── 模式切换 ──
    function switchMode(next: "richtext" | "markdown") {
      if (next === mode) return;
      if (next === "richtext") {
        // markdown→richtext：用当前 value 重新初始化 TipTap
        valueRef.current = value;
        setRichtextKey((k) => k + 1);
      }
      setMode(next);
    }

    // ── 工具栏按钮（富文本模式）──
    const btn = (active: boolean) => `${TOOLBAR_BTN} ${active ? TOOLBAR_BTN_ACTIVE : ""}`;

    const richtextToolbar = editor ? (
      <div
        className="flex flex-nowrap items-center gap-0.5 p-1 rounded-[var(--radius-md)] bg-[var(--surface-2)] border border-[var(--border-soft)] overflow-x-auto scrollbar-hide"
        role="toolbar"
        aria-label={t("toolbarAria")}
      >
        <button
          type="button"
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => editor.chain().focus().toggleBold().run()}
          disabled={!editor.can().toggleBold()}
          className={btn(editor.isActive("bold"))}
          title={`${t("bold")} (Ctrl+B)`}
          aria-label={t("bold")}
          aria-pressed={editor.isActive("bold")}
        >
          <Bold size={15} />
        </button>
        <button
          type="button"
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => editor.chain().focus().toggleItalic().run()}
          disabled={!editor.can().toggleItalic()}
          className={btn(editor.isActive("italic"))}
          title={`${t("italic")} (Ctrl+I)`}
          aria-label={t("italic")}
          aria-pressed={editor.isActive("italic")}
        >
          <Italic size={15} />
        </button>
        <button
          type="button"
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => editor.chain().focus().toggleStrike().run()}
          disabled={!editor.can().toggleStrike()}
          className={btn(editor.isActive("strike"))}
          title={t("strike")}
          aria-label={t("strike")}
          aria-pressed={editor.isActive("strike")}
        >
          <Strikethrough size={15} />
        </button>
        <button
          type="button"
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => editor.chain().focus().toggleHeading({ level: 2 }).run()}
          className={btn(editor.isActive("heading", { level: 2 }))}
          title={t("heading")}
          aria-label={t("heading")}
          aria-pressed={editor.isActive("heading", { level: 2 })}
        >
          <Heading2 size={15} />
        </button>
        <span className="mx-0.5 h-4 w-px bg-[var(--border)]" aria-hidden="true" />
        <button
          type="button"
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => editor.chain().focus().toggleBulletList().run()}
          className={btn(editor.isActive("bulletList"))}
          title={t("bulletList")}
          aria-label={t("bulletList")}
          aria-pressed={editor.isActive("bulletList")}
        >
          <List size={15} />
        </button>
        <button
          type="button"
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => editor.chain().focus().toggleOrderedList().run()}
          className={btn(editor.isActive("orderedList"))}
          title={t("numberedList")}
          aria-label={t("numberedList")}
          aria-pressed={editor.isActive("orderedList")}
        >
          <ListOrdered size={15} />
        </button>
        <button
          type="button"
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => editor.chain().focus().toggleTaskList().run()}
          className={btn(editor.isActive("taskList"))}
          title={t("taskList")}
          aria-label={t("taskList")}
          aria-pressed={editor.isActive("taskList")}
        >
          <ListChecks size={15} />
        </button>
        <span className="mx-0.5 h-4 w-px bg-[var(--border)]" aria-hidden="true" />
        <button
          type="button"
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => editor.chain().focus().toggleBlockquote().run()}
          className={btn(editor.isActive("blockquote"))}
          title={t("quote")}
          aria-label={t("quote")}
          aria-pressed={editor.isActive("blockquote")}
        >
          <Quote size={15} />
        </button>
        <button
          type="button"
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => editor.chain().focus().toggleCodeBlock().run()}
          className={btn(editor.isActive("codeBlock"))}
          title={t("codeBlock")}
          aria-label={t("codeBlock")}
          aria-pressed={editor.isActive("codeBlock")}
        >
          <Code size={15} />
        </button>
        <span className="mx-0.5 h-4 w-px bg-[var(--border)]" aria-hidden="true" />
        <button
          type="button"
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => editor.chain().focus().undo().run()}
          disabled={!editor.can().undo()}
          className={TOOLBAR_BTN}
          title={`${t("undo")} (Ctrl+Z)`}
          aria-label={t("undo")}
        >
          <Undo2 size={15} />
        </button>
        <button
          type="button"
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => editor.chain().focus().redo().run()}
          disabled={!editor.can().redo()}
          className={TOOLBAR_BTN}
          title={`${t("redo")} (Ctrl+Y)`}
          aria-label={t("redo")}
        >
          <Redo2 size={15} />
        </button>
      </div>
    ) : null;

    // ── 模式切换按钮 ──
    const modeToggle = (
      <div className="flex items-center gap-0.5 p-0.5 rounded-[var(--radius-md)] bg-[var(--surface-2)] border border-[var(--border-soft)]">
        <button
          type="button"
          onClick={() => switchMode("richtext")}
          aria-pressed={mode === "richtext"}
          title={t("richtextMode")}
          className={`inline-flex items-center gap-1 px-2 py-1 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] ${
            mode === "richtext"
              ? "bg-[var(--surface)] text-[var(--fg)] shadow-[var(--elev-sm)]"
              : "text-[var(--muted)] hover:text-[var(--fg-2)]"
          }`}
        >
          <Eye size={13} />
          {t("richtext")}
        </button>
        <button
          type="button"
          onClick={() => switchMode("markdown")}
          aria-pressed={mode === "markdown"}
          title={t("markdownMode")}
          className={`inline-flex items-center gap-1 px-2 py-1 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] ${
            mode === "markdown"
              ? "bg-[var(--surface)] text-[var(--fg)] shadow-[var(--elev-sm)]"
              : "text-[var(--muted)] hover:text-[var(--fg-2)]"
          }`}
        >
          <FileCode size={13} />
          {t("markdown")}
        </button>
      </div>
    );

    // ── 编辑器主体 ──
    const editorSurface =
      mode === "richtext" && editor ? (
        <div className="rounded-[var(--radius-lg)] border border-[var(--border)] bg-[var(--surface)] overflow-hidden">
          <EditorContent editor={editor} />
          {/* AI 续写浮层：监听光标，停止输入 1.5s 后显示 ghost text */}
          <AiSuggestion editor={editor} />
          {/* AI 选中文本浮工具栏：摘要/翻译/格式化 */}
          <AiToolbar editor={editor} />
        </div>
      ) : (
        <textarea
          ref={textareaRef}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          onKeyDown={handleKeyDown}
          onBlur={() => onBlur()}
          placeholder={placeholder}
          className="w-full h-[60dvh] p-[var(--space-4)] rounded-[var(--radius-lg)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-sm)] font-[family-name:var(--font-mono)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] placeholder:text-[var(--meta)] resize-y"
        />
      );

    // 工具栏区（随模式切换）
    const toolbar =
      mode === "richtext" ? (
        richtextToolbar
      ) : (
        <MarkdownToolbar textareaRef={textareaRef} value={value} onChange={onChange} />
      );

    return (
      <div className={className}>
        {/* 顶栏：模式切换 + 格式化工具栏 */}
        <div className="mb-2 flex items-center gap-2 flex-wrap">
          {modeToggle}
          <div className="flex-1 min-w-0">{toolbar}</div>
        </div>

        {/* 编辑/分屏 */}
        {split ? (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-3 items-start">
            {editorSurface}
            <div className="prose prose-sm max-w-none rounded-[var(--radius-lg)] border border-[var(--border)] bg-[var(--surface)] p-[var(--space-4)] min-h-[60dvh] overflow-y-auto lg:max-h-[calc(60dvh+2rem)]">
              <Markdown source={value} />
            </div>
          </div>
        ) : (
          editorSurface
        )}
      </div>
    );
  },
);

"use client";

/**
 * 看板/列表视图筛选器（阶段 2-2：筛选与自定义视图——Pro 卖点兑现）。
 *
 * 设计：
 *  - 筛选维度：状态 / 负责人 / 优先级 / 标签（多选）/ 关键词
 *  - Pro 门控：free 工作区仅状态 + 负责人可用；其余锁定并显示升级提示
 *    （定价页口径：任务筛选与自定义视图为 Pro 能力）
 *  - 自定义视图：筛选组合可保存为命名视图（localStorage 按用户隔离，
 *    视图是个人偏好而非共享数据——不建表，避免迁移负担）
 *  - 变更即上抛 onChange（父层负责拼 query 重拉列表）
 */

import { useEffect, useState } from "react";
import { useTranslations } from "next-intl";
import { Filter, X, Save, Bookmark, Search, Lock } from "lucide-react";
import type { Priority, Status } from "@/lib/types";
import { track } from "@/lib/analytics";

export interface TaskFilter {
  status: Status | "all";
  assignee: string | "all"; // userId | "me" | "all"
  priority: Priority | "all";
  labels: string[]; // labelId 多选
  q: string;
}

export const EMPTY_FILTER: TaskFilter = {
  status: "all",
  assignee: "all",
  priority: "all",
  labels: [],
  q: "",
};

export interface SavedView {
  name: string;
  filter: TaskFilter;
}

/** localStorage 键：按用户隔离（个人偏好，不共享） */
const viewKey = (userId: string, wid: string) => `corps:views:${userId}:${wid}`;

export function loadViews(userId: string, wid: string): SavedView[] {
  try {
    return JSON.parse(localStorage.getItem(viewKey(userId, wid)) ?? "[]") as SavedView[];
  } catch {
    return [];
  }
}

function saveViews(userId: string, wid: string, views: SavedView[]): void {
  localStorage.setItem(viewKey(userId, wid), JSON.stringify(views));
}

/** 筛选是否为"空"（无任何条件） */
export function isEmptyFilter(f: TaskFilter): boolean {
  return (
    f.status === "all" &&
    f.assignee === "all" &&
    f.priority === "all" &&
    f.labels.length === 0 &&
    !f.q.trim()
  );
}

/** 筛选 → GET /tasks 查询串（milestone 由外层 MilestoneFilter 独立处理） */
export function filterToQuery(f: TaskFilter): string {
  const p = new URLSearchParams();
  if (f.status !== "all") p.set("status", f.status);
  if (f.assignee !== "all") p.set("assignee", f.assignee);
  if (f.priority !== "all") p.set("priority", f.priority);
  if (f.labels.length > 0) p.set("label", f.labels.join(","));
  if (f.q.trim()) p.set("q", f.q.trim());
  const s = p.toString();
  return s ? `?${s}` : "";
}

interface TaskFilterBarProps {
  value: TaskFilter;
  onChange: (f: TaskFilter) => void;
  /** 当前工作区 plan（free 锁定高级筛选） */
  isPro: boolean;
  /** 成员列表（负责人下拉） */
  members: Array<{ id: string; name: string | null; email: string }>;
  /** 标签列表（标签多选 chips） */
  labels: Array<{ id: string; name: string; color: string }>;
  /** 当前用户 ID（视图 localStorage 隔离） */
  userId: string;
  wid: string;
}

export function TaskFilterBar({
  value,
  onChange,
  isPro,
  members,
  labels,
  userId,
  wid,
}: TaskFilterBarProps) {
  const t = useTranslations("task.filter");
  const [views, setViews] = useState<SavedView[]>([]);
  const [viewName, setViewName] = useState("");
  const [saveOpen, setSaveOpen] = useState(false);

  useEffect(() => {
    setViews(loadViews(userId, wid));
  }, [userId, wid]);

  // 筛选埋点：非空筛选组合变更时打 filter_applied（维度数 + 是否 Pro）
  // deps 仅 [value]：activeCount/isPro 由其派生或慢变，入 deps 只会重复触发
  useEffect(() => {
    if (!isEmptyFilter(value)) {
      track("filter_applied", {
        dimensions: activeCount,
        isPro,
      });
    }
  }, [value]);

  const active = !isEmptyFilter(value);
  const activeCount =
    (value.status !== "all" ? 1 : 0) +
    (value.assignee !== "all" ? 1 : 0) +
    (value.priority !== "all" ? 1 : 0) +
    value.labels.length +
    (value.q.trim() ? 1 : 0);

  // Pro 锁定的筛选维度：优先级 / 标签 / 关键词
  const locked = !isPro;

  function handleSave() {
    const name = viewName.trim();
    if (!name || isEmptyFilter(value)) return;
    const next = [...views.filter((v) => v.name !== name), { name, filter: value }];
    setViews(next);
    saveViews(userId, wid, next);
    setViewName("");
    setSaveOpen(false);
    track("view_saved", { name });
  }

  function handleDeleteView(name: string) {
    const next = views.filter((v) => v.name !== name);
    setViews(next);
    saveViews(userId, wid, next);
  }

  const selectCls =
    "h-8 px-2 border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg-2)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] disabled:opacity-50 disabled:cursor-not-allowed";

  return (
    <div className="mb-4 flex flex-wrap items-center gap-2 sm:gap-3" data-testid="task-filter-bar">
      <span className="flex items-center gap-1.5 text-[length:var(--text-sm)] text-[var(--muted)]">
        <Filter size={15} />
        {t("title")}
        {active && (
          <span className="px-1.5 rounded-full bg-[var(--accent-soft)] text-[var(--accent)] text-[length:var(--text-xs)]">
            {activeCount}
          </span>
        )}
      </span>

      {/* 状态筛选（free 可用） */}
      <select
        aria-label={t("status")}
        value={value.status}
        onChange={(e) => onChange({ ...value, status: e.target.value as Status | "all" })}
        className={selectCls}
      >
        <option value="all">{t("allStatuses")}</option>
        <option value="todo">{t("statusTodo")}</option>
        <option value="in_progress">{t("statusInProgress")}</option>
        <option value="review">{t("statusReview")}</option>
        <option value="done">{t("statusDone")}</option>
      </select>

      {/* 负责人筛选（free 可用） */}
      <select
        aria-label={t("assignee")}
        value={value.assignee}
        onChange={(e) => onChange({ ...value, assignee: e.target.value })}
        className={selectCls}
      >
        <option value="all">{t("allAssignees")}</option>
        <option value="me">{t("assigneeMe")}</option>
        {members.map((m) => (
          <option key={m.id} value={m.id}>
            {m.name || m.email}
          </option>
        ))}
      </select>

      {/* 优先级（Pro） */}
      <select
        aria-label={t("priority")}
        value={value.priority}
        disabled={locked}
        onChange={(e) => onChange({ ...value, priority: e.target.value as Priority | "all" })}
        className={selectCls}
      >
        <option value="all">{t("allPriorities")}</option>
        <option value="urgent">{t("priorityUrgent")}</option>
        <option value="high">{t("priorityHigh")}</option>
        <option value="medium">{t("priorityMedium")}</option>
        <option value="low">{t("priorityLow")}</option>
      </select>

      {/* 标签多选 chips（Pro） */}
      {labels.length > 0 && (
        <div className="flex items-center gap-1 flex-wrap" aria-label={t("labels")}>
          {labels.slice(0, 8).map((l) => {
            const selected = value.labels.includes(l.id);
            return (
              <button
                key={l.id}
                disabled={locked}
                onClick={() =>
                  onChange({
                    ...value,
                    labels: selected
                      ? value.labels.filter((x) => x !== l.id)
                      : [...value.labels, l.id],
                  })
                }
                className={`px-2 h-7 rounded-full text-[length:var(--text-xs)] transition-colors duration-[var(--motion-fast)] disabled:opacity-50 disabled:cursor-not-allowed ${
                  selected
                    ? "text-[var(--accent-fg)]"
                    : "bg-[var(--surface-2)] text-[var(--fg-2)] hover:bg-[var(--surface-3)]"
                }`}
                style={selected ? { background: l.color } : undefined}
                aria-pressed={selected}
              >
                {l.name}
              </button>
            );
          })}
          {labels.length > 8 && (
            <span className="px-2 h-7 inline-flex items-center rounded-full text-[length:var(--text-xs)] text-[var(--meta)]">
              +{labels.length - 8}
            </span>
          )}
        </div>
      )}

      {/* 关键词（Pro） */}
      <div className="relative">
        <Search
          size={14}
          className="absolute left-2 top-1/2 -translate-y-1/2 text-[var(--muted)] pointer-events-none"
        />
        <input
          type="search"
          aria-label={t("keyword")}
          placeholder={t("keywordPlaceholder")}
          disabled={locked}
          value={value.q}
          onChange={(e) => onChange({ ...value, q: e.target.value })}
          className="h-8 pl-7 pr-2 w-40 border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg-2)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] placeholder:text-[var(--meta)] disabled:opacity-50 disabled:cursor-not-allowed"
        />
      </div>

      {locked && (
        <span
          className="flex items-center gap-1 text-[length:var(--text-xs)] text-[var(--muted)]"
          title={t("proLockHint")}
        >
          <Lock size={12} />
          {t("proLockLabel")}
        </span>
      )}

      {/* 清空 */}
      {active && (
        <button
          onClick={() => onChange({ ...EMPTY_FILTER })}
          className="flex items-center gap-1 h-7 px-2 rounded-[var(--radius-md)] text-[length:var(--text-xs)] text-[var(--muted)] hover:text-[var(--fg)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
        >
          <X size={13} />
          {t("clear")}
        </button>
      )}

      {/* 保存视图（Pro）：筛选非空时可命名保存 */}
      <div className="flex items-center gap-1.5 ms-auto">
        {views.map((v) => (
          <span
            key={v.name}
            className="group inline-flex items-center gap-1 h-7 px-2 rounded-full bg-[var(--surface-2)] text-[length:var(--text-xs)] text-[var(--fg-2)]"
          >
            <button
              onClick={() => onChange({ ...v.filter })}
              className="flex items-center gap-1 hover:text-[var(--accent)] transition-colors duration-[var(--motion-fast)]"
              aria-label={t("applyView", { name: v.name })}
            >
              <Bookmark size={11} />
              {v.name}
            </button>
            <button
              onClick={() => handleDeleteView(v.name)}
              className="opacity-0 group-hover:opacity-100 text-[var(--muted)] hover:text-[var(--danger)]"
              aria-label={t("deleteView", { name: v.name })}
            >
              <X size={11} />
            </button>
          </span>
        ))}
        {saveOpen ? (
          <span className="flex items-center gap-1">
            <input
              value={viewName}
              onChange={(e) => setViewName(e.target.value)}
              placeholder={t("viewNamePlaceholder")}
              maxLength={20}
              className="h-7 w-28 px-2 border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-xs)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
            />
            <button
              onClick={handleSave}
              disabled={!viewName.trim() || isEmptyFilter(value)}
              className="h-7 px-2 rounded-[var(--radius-md)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {t("saveConfirm")}
            </button>
          </span>
        ) : (
          <button
            onClick={() => setSaveOpen(true)}
            disabled={locked || isEmptyFilter(value)}
            className="flex items-center gap-1 h-7 px-2 rounded-[var(--radius-md)] text-[length:var(--text-xs)] text-[var(--muted)] hover:text-[var(--fg)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] disabled:opacity-50 disabled:cursor-not-allowed"
            title={t("saveViewHint")}
          >
            <Save size={12} />
            {t("saveView")}
          </button>
        )}
      </div>
    </div>
  );
}

"use client";

import {
  createContext,
  useContext,
  useState,
  useCallback,
  useRef,
  useEffect,
  type ReactNode,
} from "react";
import { X, Pause } from "lucide-react";
import { useTranslations } from "next-intl";
import { motion, AnimatePresence, useReducedMotion, type Variants } from "framer-motion";

type ToastType = "success" | "error" | "info" | "warning";

interface Toast {
  id: number;
  type: ToastType;
  message: string;
  createdAt: number;
}

interface ToastContextValue {
  toast: (type: ToastType, message: string) => void;
}

const ToastContext = createContext<ToastContextValue | null>(null);

/** Toast 自动关闭时长（ms） */
const TOAST_DURATION = 3500;

let _id = 0;

/** 格式化相对时间：刚刚 / Xs */
function formatElapsed(elapsedMs: number): string {
  const s = Math.floor(elapsedMs / 1000);
  if (s < 1) return "刚刚";
  return `${s}s`;
}

export function ToastProvider({ children }: { children: ReactNode }) {
  const tToast = useTranslations("toast");
  const [toasts, setToasts] = useState<Toast[]>([]);
  // 每个 toast 的自动关闭定时器
  const timersRef = useRef<Map<number, ReturnType<typeof setTimeout>>>(new Map());
  // 每个 toast 的剩余时间（暂停时记录）
  const remainingRef = useRef<Map<number, number>>(new Map());
  // 暂停的 toast id 集合
  const [pausedIds, setPausedIds] = useState<Set<number>>(new Set());
  // 当前时间戳，每秒更新用于动态显示相对时间
  const [now, setNow] = useState(() => Date.now());

  // 尊重 prefers-reduced-motion：降级时仅做 opacity 过渡，无位移 / 缩放
  const reduceMotion = useReducedMotion();

  // Toast 入场 / 退场动画 variants
  // 入场：从顶部滑入（y: -12 → 0）+ scale 0.95 → 1，spring 物理曲线
  // 退场：fade out + scale 1 → 0.95 + y: -8，tween 曲线（干脆不拖沓）
  // spring 参数对应设计文档 --spring-stiffness: 300 / --spring-damping: 30
  const toastVariants: Variants = reduceMotion
    ? {
        initial: { opacity: 0 },
        animate: { opacity: 1, transition: { duration: 0.15 } },
        exit: { opacity: 0, transition: { duration: 0.15 } },
      }
    : {
        initial: { opacity: 0, y: -12, scale: 0.95 },
        animate: {
          opacity: 1,
          y: 0,
          scale: 1,
          transition: { type: "spring", stiffness: 300, damping: 30 },
        },
        exit: {
          opacity: 0,
          y: -8,
          scale: 0.95,
          transition: { duration: 0.15, ease: [0.2, 0, 0, 1] },
        },
      };

  // 每秒 tick 更新动态时间显示
  useEffect(() => {
    if (toasts.length === 0) return;
    const interval = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(interval);
  }, [toasts.length]);

  // 清除指定 toast 的定时器
  const clearTimer = useCallback((id: number) => {
    const timer = timersRef.current.get(id);
    if (timer) {
      clearTimeout(timer);
      timersRef.current.delete(id);
    }
  }, []);

  // 设置指定 toast 的定时器（用指定时长）
  const setTimer = useCallback(
    (id: number, duration: number) => {
      clearTimer(id);
      const timer = setTimeout(() => {
        setToasts((prev) => prev.filter((t) => t.id !== id));
        timersRef.current.delete(id);
        remainingRef.current.delete(id);
      }, duration);
      timersRef.current.set(id, timer);
    },
    [clearTimer],
  );

  const addToast = useCallback(
    (type: ToastType, message: string) => {
      const id = ++_id;
      const createdAt = Date.now();
      setToasts((prev) => [...prev, { id, type, message, createdAt }]);
      remainingRef.current.set(id, TOAST_DURATION);
      setTimer(id, TOAST_DURATION);
    },
    [setTimer],
  );

  const remove = useCallback(
    (id: number) => {
      clearTimer(id);
      remainingRef.current.delete(id);
      setPausedIds((prev) => {
        const next = new Set(prev);
        next.delete(id);
        return next;
      });
      setToasts((prev) => prev.filter((t) => t.id !== id));
    },
    [clearTimer],
  );

  // onMouseEnter：暂停自动关闭
  const handleMouseEnter = useCallback(
    (id: number, createdAt: number) => {
      clearTimer(id);
      const elapsed = Date.now() - createdAt;
      const remaining = Math.max(0, remainingRef.current.get(id) ?? TOAST_DURATION) - elapsed;
      remainingRef.current.set(id, remaining);
      setPausedIds((prev) => new Set(prev).add(id));
    },
    [clearTimer],
  );

  // onMouseLeave：恢复自动关闭
  const handleMouseLeave = useCallback(
    (id: number) => {
      const remaining = remainingRef.current.get(id) ?? TOAST_DURATION;
      setPausedIds((prev) => {
        const next = new Set(prev);
        next.delete(id);
        return next;
      });
      if (remaining <= 0) {
        remove(id);
      } else {
        setTimer(id, remaining);
      }
    },
    [setTimer, remove],
  );

  // 组件卸载时清除所有定时器
  useEffect(() => {
    return () => {
      timersRef.current.forEach((timer) => clearTimeout(timer));
      timersRef.current.clear();
    };
  }, []);

  return (
    <ToastContext.Provider value={{ toast: addToast }}>
      {children}
      <div
        className="fixed bottom-[var(--space-4)] right-[var(--space-4)] pb-safe z-[var(--z-toast)] flex flex-col gap-2 pointer-events-none"
        aria-live="polite"
        aria-label={tToast("regionLabel")}
      >
        <AnimatePresence>
          {toasts.map((t) => {
            const elapsed = now - t.createdAt;
            const isPaused = pausedIds.has(t.id);
            return (
              <motion.div
                key={t.id}
                layout
                variants={toastVariants}
                initial="initial"
                animate="animate"
                exit="exit"
                className="pointer-events-auto flex items-start gap-[var(--space-3)] max-w-[calc(100vw-2rem)] px-[var(--space-4)] py-[var(--space-3)] rounded-[var(--radius-lg)] shadow-[var(--elev-lg)] border cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)]"
                style={{
                  background:
                    t.type === "success"
                      ? "var(--success-soft)"
                      : t.type === "error"
                        ? "var(--danger-soft)"
                        : t.type === "warning"
                          ? "var(--warn-soft)"
                          : "var(--surface)",
                  borderColor: "var(--border)",
                  color:
                    t.type === "success"
                      ? "var(--success)"
                      : t.type === "error"
                        ? "var(--danger)"
                        : t.type === "warning"
                          ? "var(--warn)"
                          : "var(--fg)",
                }}
                onClick={() => remove(t.id)}
                onMouseEnter={() => handleMouseEnter(t.id, t.createdAt)}
                onMouseLeave={() => handleMouseLeave(t.id)}
                role="alert"
              >
                <span className="text-[length:var(--text-sm)] flex-1">{t.message}</span>
                {/* 动态显示时间 */}
                <span
                  className="shrink-0 text-[length:var(--text-xs)] opacity-60 tabular-nums self-center"
                  aria-hidden="true"
                >
                  {isPaused ? <Pause size={14} /> : formatElapsed(elapsed)}
                </span>
                <button
                  className="shrink-0 opacity-60 hover:opacity-100 transition-opacity text-[length:var(--text-xs)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)] rounded-[var(--radius-sm)]"
                  onClick={(e) => {
                    e.stopPropagation();
                    remove(t.id);
                  }}
                  aria-label={tToast("close")}
                >
                  <X size={14} />
                </button>
              </motion.div>
            );
          })}
        </AnimatePresence>
      </div>
    </ToastContext.Provider>
  );
}

export function useToast(): ToastContextValue {
  const ctx = useContext(ToastContext);
  if (!ctx) throw new Error("useToast must be used within a ToastProvider");
  return ctx;
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useTranslations } from "next-intl";
import { Sparkles, Megaphone, Save, Loader2, Eye, Edit3 } from "lucide-react";
import Markdown from "@/components/Markdown";
import { consumeAiStream } from "@/components/editor/aiStream";
import { api } from "@/lib/api";
import { FeedbackButtons } from "./FeedbackButtons";

/**
 * AI 公告智能起草面板。
 *
 * 交互流程：
 *  1. 顶部主题输入框（可选）+ "生成"按钮（Sparkles 图标）
 *  2. 点击生成 → 流式渲染 markdown（逐字显示，onDelta 回调）
 *  3. 生成完成后可编辑（textarea）或预览（markdown）
 *  4. 底部"保存为公告"按钮 → POST /api/v1/workspaces/{wid}/announcements
 *
 * 流式消费走 consumeAiStream（见 aiStream.ts），零外部依赖。
 * 样式全走 design token（var(--*)），与项目设计系统一致。
 *
 * 来源：经验 2026-09-13-frontend-modification-five-dimension-verification
 *       （流式组件 useEffect cleanup + AbortController 模式）
 */

interface AnnouncementDraftPanelProps {
  wid: string;
}

/** 组件阶段 */
type Phase = "idle" | "streaming" | "done";


/**
 * 从生成的 markdown 中提取标题与正文。
 *
 * prompt 要求输出以 `# 标题` 开头。若首行匹配 `# xxx`，则提取为公告 title，
 * 剩余行作为 content；否则 title 留空（由调用方用默认标题兜底），content 取全文。
 */
function extractTitleAndContent(markdown: string): { title: string; content: string } {
  const lines = markdown.split("\n");
  const firstLine = lines[0]?.trim() ?? "";
  const m = /^#\s+(.+)$/.exec(firstLine);
  if (m) {
    const rest = lines.slice(1).join("\n").trim();
    return { title: m[1].trim(), content: rest };
  }
  return { title: "", content: markdown };
}

export function AnnouncementDraftPanel({ wid }: AnnouncementDraftPanelProps) {
  const t = useTranslations("ai.announcementDraft");


  const [topic, setTopic] = useState("");
  const [phase, setPhase] = useState<Phase>("idle");
  const [content, setContent] = useState("");
  const [editing, setEditing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);

  const abortRef = useRef<AbortController | null>(null);

  // 组件卸载时取消进行中的流式请求，避免 onDelta 回调在已卸载组件上触发 setContent
  useEffect(() => {
    return () => {
      abortRef.current?.abort();
    };
  }, []);

  /** 生成草稿：调用流式 API */
  const handleGenerate = useCallback(async () => {
    // 取消进行中请求
    if (abortRef.current) abortRef.current.abort();
    const ac = new AbortController();
    abortRef.current = ac;

    setPhase("streaming");
    setContent("");
    setError(null);
    setSaved(false);
    setEditing(false);

    try {
      const full = await consumeAiStream(
        "/api/v1/ai/announcement-draft",
        { wid, topic: topic.trim() || undefined },
        {
          signal: ac.signal,
          onDelta: (delta) => {
            setContent((prev) => prev + delta);
          },
        },
      );
      setContent(full);
      setPhase("done");
    } catch (e) {
      // abort 不视为错误
      if ((e as Error).name === "AbortError") return;
      setError(t("generateFailed"));
      setPhase("idle");
    } finally {
      if (abortRef.current === ac) abortRef.current = null;
    }
  }, [wid, topic]);

  /** 保存为公告：POST /api/v1/workspaces/{wid}/announcements */
  const handleSave = useCallback(async () => {
    if (!content.trim() || saving) return;
    setSaving(true);
    setError(null);
    try {
      // 从 markdown 提取标题（# 标题）与正文；无标题行时用默认标题兜底
      const { title: extracted, content: body } = extractTitleAndContent(content);
      const title = extracted || t("announcementTitle");
      const announcementContent = body || content;

      await api(`/api/v1/workspaces/${wid}/announcements`, {
        method: "POST",
        body: JSON.stringify({ title, content: announcementContent }),
      });
      setSaved(true);
    } catch {
      setError(t("saveFailed"));
    } finally {
      setSaving(false);
    }
  }, [content, saving, wid]);

  const isStreaming = phase === "streaming";
  const hasContent = phase === "done" && content.length > 0;

  return (
    <div className="flex h-full flex-col">
      {/* 顶部工具栏：标题 + 主题输入 + 生成按钮 */}
      <header className="flex flex-wrap items-center gap-[var(--space-3)] border-b border-[var(--border)] px-[var(--space-6)] py-[var(--space-4)]">
        <div className="flex items-center gap-[var(--space-2)]">
          <Megaphone size={16} className="text-[var(--accent)]" />
          <h1 className="text-[length:var(--text-lg)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
            {t("title")}
          </h1>
        </div>

        <div className="ml-auto flex flex-wrap items-center gap-[var(--space-3)]">
          {/* 主题输入（可选） */}
          <input
            type="text"
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            maxLength={500}
            disabled={isStreaming}
            placeholder={t("topicPlaceholder")}
            aria-label={t("topicPlaceholder")}
            className="w-64 rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] px-[var(--space-3)] py-[var(--space-2)] text-[length:var(--text-sm)] text-[var(--fg)] transition-colors duration-[var(--motion-fast)] focus:border-[var(--accent)] focus:outline-none focus:ring-2 focus:ring-[var(--accent-ring)] disabled:opacity-50"
          />

          {/* 生成按钮 */}
          <button
            type="button"
            onClick={handleGenerate}
            disabled={isStreaming}
            className="inline-flex items-center gap-[var(--space-2)] rounded-[var(--radius-md)] bg-[var(--accent)] px-[var(--space-4)] py-[var(--space-2)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--on-accent)] transition-colors duration-[var(--motion-fast)] hover:bg-[var(--accent-hover)] disabled:cursor-not-allowed disabled:opacity-40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
          >
            {isStreaming ? (
              <>
                <Loader2 size={14} className="animate-spin motion-reduce:animate-none" />
                {t("generating")}
              </>
            ) : (
              <>
                <Sparkles size={14} />
                {t("generate")}
              </>
            )}
          </button>
        </div>
      </header>

      {/* 主体内容区 */}
      <div className="flex-1 overflow-y-auto px-[var(--space-6)] py-[var(--space-5)]">
        {phase === "idle" && !error && (
          <div className="flex h-full flex-col items-center justify-center gap-[var(--space-3)] text-center">
            <Sparkles size={32} className="text-[var(--meta)]" />
            <p className="max-w-md text-[length:var(--text-sm)] text-[var(--meta)]">
              {t("empty")}
            </p>
          </div>
        )}

        {error && (
          <div className="mb-[var(--space-4)] rounded-[var(--radius-md)] border border-[var(--danger)] bg-[var(--danger-soft)] px-[var(--space-4)] py-[var(--space-3)] text-[length:var(--text-sm)] text-[var(--danger)]">
            {error}
          </div>
        )}

        {hasContent && (
          <div className="flex flex-col gap-[var(--space-3)]">
            {/* 预览/编辑切换 */}
            <div className="flex items-center gap-[var(--space-2)]">
              <button
                type="button"
                onClick={() => setEditing(false)}
                disabled={!editing}
                className="inline-flex items-center gap-[var(--space-1)] rounded-[var(--radius-sm)] px-[var(--space-2)] py-[var(--space-1)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] transition-colors duration-[var(--motion-fast)] hover:bg-[var(--surface-2)] disabled:opacity-40"
              >
                <Eye size={14} />
                {t("preview")}
              </button>
              <button
                type="button"
                onClick={() => setEditing(true)}
                disabled={editing}
                className="inline-flex items-center gap-[var(--space-1)] rounded-[var(--radius-sm)] px-[var(--space-2)] py-[var(--space-1)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] transition-colors duration-[var(--motion-fast)] hover:bg-[var(--surface-2)] disabled:opacity-40"
              >
                <Edit3 size={14} />
                {t("edit")}
              </button>
            </div>

            {/* 内容区：编辑模式 textarea / 预览模式 markdown */}
            {editing ? (
              <textarea
                value={content}
                onChange={(e) => {
                  setContent(e.target.value);
                  setSaved(false);
                }}
                className="min-h-[400px] w-full resize-y rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] px-[var(--space-4)] py-[var(--space-3)] font-[family-name:var(--font-mono)] text-[length:var(--text-sm)] text-[var(--fg)] leading-[var(--leading-relaxed)] transition-colors duration-[var(--motion-fast)] focus:border-[var(--accent)] focus:outline-none focus:ring-2 focus:ring-[var(--accent-ring)]"
                aria-label={t("edit")}
              />
            ) : (
              <div className="rounded-[var(--radius-md)] border border-[var(--border-soft)] bg-[var(--surface)] px-[var(--space-5)] py-[var(--space-4)]">
                <Markdown source={content} />
              </div>
            )}

            {/* AI 结果反馈按钮 */}
            <FeedbackButtons
              capability="announcement-draft"
              workspaceId={wid}
              originalOutput={content}
            />
          </div>
        )}

        {/* 流式生成中：实时渲染 markdown */}
        {isStreaming && content.length > 0 && (
          <div className="rounded-[var(--radius-md)] border border-[var(--border-soft)] bg-[var(--surface)] px-[var(--space-5)] py-[var(--space-4)]">
            <Markdown source={content} />
          </div>
        )}
      </div>

      {/* 底部操作栏：保存为公告 */}
      {hasContent && (
        <footer className="flex items-center justify-end gap-[var(--space-3)] border-t border-[var(--border)] px-[var(--space-6)] py-[var(--space-3)]">
          {saved && (
            <span className="text-[length:var(--text-xs)] text-[var(--success)]">
              {t("saved")}
            </span>
          )}
          <button
            type="button"
            onClick={handleSave}
            disabled={saving || !content.trim() || saved}
            className="inline-flex items-center gap-[var(--space-2)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] px-[var(--space-4)] py-[var(--space-2)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg)] transition-colors duration-[var(--motion-fast)] hover:bg-[var(--surface-2)] disabled:cursor-not-allowed disabled:opacity-40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
          >
            {saving ? (
              <>
                <Loader2 size={14} className="animate-spin motion-reduce:animate-none" />
                {t("saving")}
              </>
            ) : (
              <>
                <Save size={14} />
                {t("save")}
              </>
            )}
          </button>
        </footer>
      )}
    </div>
  );
}

"use client";

/**
 * AI 审批风控建议面板。
 *
 * 调用 POST /api/v1/ai/approval-advice（deepseek-reasoner）分析当前审批实例，
 * 展示：
 *  - 风险等级（low/medium/high，颜色标识）
 *  - 风险因素列表（每条带 AlertTriangle 图标）
 *  - AI 建议文字
 *  - 相似历史案例列表
 *
 * 面板加载时自动调用 API，失败可点击"重试"重新分析。
 *
 * Design token 颜色映射（先 grep 确认可用 token 后按语义降级）：
 *  - low    → var(--success)      ✓ 存在
 *  - medium → var(--status-warn)  ✓ 存在（= var(--warn)）
 *  - high   → var(--status-error) ✗ 不存在 → 降级为 var(--danger)
 *    来源：经验 2026-09-11-design-token-missing-semantic-fallback
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { useTranslations } from "next-intl";
import {
  Sparkles,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  Loader2,
} from "lucide-react";
import { consumeAiProgressStream, type AiProgressPart } from "@/components/editor/aiStream";
import { ProgressSteps, type ProgressStage } from "@/components/ai/ProgressSteps";
import { FeedbackButtons } from "./FeedbackButtons";

/** AI 风控建议响应结构（与后端 data 字段一致） */
interface ApprovalAdvice {
  riskLevel: "low" | "medium" | "high";
  riskFactors: string[];
  suggestion: string;
  similarCases: {
    title: string;
    result: "approved" | "rejected";
    amount: number;
  }[];
}

interface ApprovalAdvicePanelProps {
  wid: string;
  approvalInstanceId: string;
}

/** 风险等级 → 图标 + 颜色 token + i18n key */
function getRiskVisual(riskLevel: ApprovalAdvice["riskLevel"]) {
  switch (riskLevel) {
    case "low":
      return {
        icon: <CheckCircle2 size={14} className="shrink-0" />,
        color: "var(--success)",
        bg: "var(--success-soft)",
        labelKey: "riskLow",
      };
    case "medium":
      return {
        icon: <AlertTriangle size={14} className="shrink-0" />,
        color: "var(--status-warn)",
        bg: "var(--warn-soft)",
        labelKey: "riskMedium",
      };
    case "high":
      return {
        icon: <XCircle size={14} className="shrink-0" />,
        // --status-error 不存在，降级为 --danger（语义最接近的红色）
        // 来源：经验 2026-09-11-design-token-missing-semantic-fallback
        color: "var(--danger)",
        bg: "var(--danger-soft)",
        labelKey: "riskHigh",
      };
  }
}

export function ApprovalAdvicePanel({
  wid,
  approvalInstanceId,
}: ApprovalAdvicePanelProps) {
  const t = useTranslations("ai.approvalAdvice");
  const tp = useTranslations("ai.progress");

  const [advice, setAdvice] = useState<ApprovalAdvice | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  // 进度状态：当前阶段 + 阶段消息
  const [progressStage, setProgressStage] = useState<ProgressStage | null>(null);
  const [progressMessage, setProgressMessage] = useState<string>("");

  // cancelled 标志：组件卸载或依赖变化时置 true，analyze 内每次 setState 前检查，
  // 避免在已卸载组件上触发 setState（React 警告）。
  // 用 ref 而非 useEffect 内局部变量，是为了让重试按钮仍能调用同一个 analyze。
  const cancelledRef = useRef(false);

  // AbortController：组件卸载或依赖变化时中止进行中的 fetch 请求，
  // 避免请求继续消耗带宽与后端资源（与 DailyReportView/ProjectInsightView 一致）。
  // 来源：经验 2026-09-13-abortcontroller-null-access-after-abort-runtime-crash
  const abortRef = useRef<AbortController | null>(null);

  const analyze = async () => {
    if (cancelledRef.current) return;
    // 中止之前未完成的请求，避免并发请求互相覆盖
    abortRef.current?.abort();
    const controller = new AbortController();
    abortRef.current = controller;

    setLoading(true);
    setError(false);
    setAdvice(null);
    setProgressStage(null);
    setProgressMessage("");
    try {
      const { data } = await consumeAiProgressStream(
        "/api/v1/ai/approval-advice",
        { wid, approvalInstanceId },
        {
          signal: controller.signal,
          onProgress: (progress: AiProgressPart) => {
            if (cancelledRef.current || controller.signal.aborted) return;
            setProgressStage(progress.stage);
            setProgressMessage(progress.message);
          },
          onData: (result) => {
            if (cancelledRef.current || controller.signal.aborted) return;
            setAdvice(result as ApprovalAdvice);
          },
        },
      );
      if (cancelledRef.current || controller.signal.aborted) return;
      // data-result data part 已通过 onData 设置 advice，无需后备检查
      // （旧代码 `if (data && !advice)` 中 advice 是闭包陈旧值恒为 null，无效）
      void data;
    } catch (e) {
      if (cancelledRef.current || controller.signal.aborted) return;
      // AbortError 是主动中止，不显示错误状态
      if (e instanceof Error && e.name === "AbortError") return;
      // 流错误（如审批实例不存在、AI 服务不可用）均显示错误状态
      setError(true);
      if (e instanceof Error) {
        // 仅在开发环境输出错误日志，避免生产环境噪音
        if (process.env.NODE_ENV === "development") {
          console.error("[ApprovalAdvicePanel] error:", e.message);
        }
      }
    } finally {
      if (cancelledRef.current || controller.signal.aborted) return;
      setLoading(false);
      setProgressStage(null);
    }
  };

  // 面板加载时自动调用 API；卸载或依赖变化时标记 cancelled 并中止进行中的请求
  useEffect(() => {
    cancelledRef.current = false;
    void analyze();
    return () => {
      cancelledRef.current = true;
      abortRef.current?.abort();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [wid, approvalInstanceId]);

  // —— Loading ——
  if (loading) {
    return (
      <aside
        className="flex w-full flex-col gap-[var(--space-3)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] p-[var(--space-4)]"
        aria-label={t("title")}
      >
        <header className="flex items-center gap-[var(--space-2)]">
          <Sparkles size={14} className="shrink-0 text-[var(--accent)]" />
          <h2 className="text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
            {t("title")}
          </h2>
        </header>
        {progressStage ? (
          <ProgressSteps
            currentStage={progressStage}
            stageNames={[tp("context"), tp("analyzing"), tp("generating")]}
            currentMessage={progressMessage}
          />
        ) : (
          <div className="flex items-center justify-center gap-[var(--space-2)] py-[var(--space-4)]">
            <Loader2
              size={14}
              className="shrink-0 animate-spin text-[var(--muted)]"
            />
            <span className="text-[length:var(--text-xs)] text-[var(--meta)]">
              {t("analyzing")}
            </span>
          </div>
        )}
      </aside>
    );
  }

  // —— Error ——
  if (error) {
    return (
      <aside
        className="flex w-full flex-col gap-[var(--space-3)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] p-[var(--space-4)]"
        aria-label={t("title")}
      >
        <header className="flex items-center gap-[var(--space-2)]">
          <Sparkles size={14} className="shrink-0 text-[var(--accent)]" />
          <h2 className="text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
            {t("title")}
          </h2>
        </header>
        <div className="flex flex-col items-center gap-[var(--space-3)] py-[var(--space-3)]">
          <p className="text-[length:var(--text-xs)] text-[var(--danger)]">
            {t("error")}
          </p>
          <button
            type="button"
            onClick={() => void analyze()}
            className="inline-flex items-center gap-[var(--space-1)] rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface-2)] px-[var(--space-3)] py-[var(--space-1)] text-[length:var(--text-xs)] text-[var(--fg-2)] transition-colors duration-[var(--motion-fast)] hover:bg-[var(--surface-3)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
          >
            {t("retry")}
          </button>
        </div>
      </aside>
    );
  }

  // —— Result ——
  if (!advice) return null;

  const risk = getRiskVisual(advice.riskLevel);

  return (
    <aside
      className="flex w-full flex-col gap-[var(--space-3)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] p-[var(--space-4)]"
      aria-label={t("title")}
    >
      {/* 标题 */}
      <header className="flex items-center gap-[var(--space-2)]">
        <Sparkles size={14} className="shrink-0 text-[var(--accent)]" />
        <h2 className="text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
          {t("title")}
        </h2>
      </header>

      {/* 风险等级 */}
      <div
        className="flex items-center gap-[var(--space-2)] rounded-[var(--radius-sm)] px-[var(--space-3)] py-[var(--space-2)]"
        style={{ backgroundColor: risk.bg }}
      >
        <span style={{ color: risk.color }}>{risk.icon}</span>
        <span className="text-[length:var(--text-xs)] text-[var(--muted)]">
          {t("riskLevel")}
        </span>
        <span
          className="ml-auto text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)]"
          style={{ color: risk.color }}
        >
          {t(risk.labelKey)}
        </span>
      </div>

      {/* 风险因素 */}
      <div className="flex flex-col gap-[var(--space-1)]">
        <h3 className="text-[length:var(--text-xs)] font-[weight:var(--weight-semibold)] text-[var(--muted)]">
          {t("riskFactors")}
        </h3>
        {advice.riskFactors.length > 0 ? (
          <ul className="flex flex-col gap-[var(--space-1)]">
            {advice.riskFactors.map((factor, idx) => (
              <li
                key={`${factor}_${idx}`}
                className="flex items-start gap-[var(--space-2)] text-[length:var(--text-xs)] text-[var(--fg-2)]"
              >
                <AlertTriangle
                  size={14}
                  className="mt-0.5 shrink-0 text-[var(--warn)]"
                />
                <span className="break-words">{factor}</span>
              </li>
            ))}
          </ul>
        ) : (
          <p className="text-[length:var(--text-xs)] text-[var(--meta)]">
            {t("noRiskFactors")}
          </p>
        )}
      </div>

      {/* AI 建议 */}
      {advice.suggestion && (
        <div className="flex flex-col gap-[var(--space-1)]">
          <h3 className="text-[length:var(--text-xs)] font-[weight:var(--weight-semibold)] text-[var(--muted)]">
            {t("suggestion")}
          </h3>
          <p className="break-words text-[length:var(--text-xs)] leading-relaxed text-[var(--fg-2)]">
            {advice.suggestion}
          </p>
        </div>
      )}

      {/* 相似历史案例 */}
      <div className="flex flex-col gap-[var(--space-1)]">
        <h3 className="text-[length:var(--text-xs)] font-[weight:var(--weight-semibold)] text-[var(--muted)]">
          {t("similarCases")}
        </h3>
        {advice.similarCases.length > 0 ? (
          <ul className="flex flex-col gap-[var(--space-1)]">
            {advice.similarCases.map((c, idx) => (
              <li
                key={`${c.title}_${idx}`}
                className="flex items-center gap-[var(--space-2)] text-[length:var(--text-xs)] text-[var(--fg-2)]"
              >
                {c.result === "approved" ? (
                  <CheckCircle2
                    size={14}
                    className="shrink-0 text-[var(--success)]"
                  />
                ) : (
                  <XCircle
                    size={14}
                    className="shrink-0 text-[var(--danger)]"
                  />
                )}
                <span className="break-words">{c.title}</span>
                {c.amount > 0 && (
                  <span className="ml-auto shrink-0 text-[var(--meta)]">
                    ¥{c.amount}
                  </span>
                )}
              </li>
            ))}
          </ul>
        ) : (
          <p className="text-[length:var(--text-xs)] text-[var(--meta)]">
            {t("noSimilarCases")}
          </p>
        )}
      </div>

      {/* AI 结果反馈按钮 */}
      <FeedbackButtons
        capability="approval-advice"
        workspaceId={wid}
        originalOutput={advice}
      />
    </aside>
  );
}

