"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useTranslations } from "next-intl";
import { Sparkles, Calendar, Save, Loader2, Eye, Edit3 } from "lucide-react";
import Markdown from "@/components/Markdown";
import { consumeAiProgressStream, type AiProgressPart } from "@/components/editor/aiStream";
import { ProgressSteps, type ProgressStage } from "@/components/ai/ProgressSteps";
import { api } from "@/lib/api";
import { FeedbackButtons } from "./FeedbackButtons";

/**
 * AI 智能日报视图
 *
 * 交互流程：
 *  1. 顶部日期选择器（默认今天）+ "生成"按钮（Sparkles 图标）
 *  2. 点击生成 → 流式渲染 markdown（逐字显示，onDelta 回调）
 *  3. 生成完成后进入编辑模式（textarea 可修改）
 *  4. 底部"保存为文档"按钮 → POST /api/v1/workspaces/{wid}/documents
 *
 * 流式消费走 consumeAiStream（见 aiStream.ts），零外部依赖。
 * 样式全走 design token（var(--*)），与项目设计系统一致。
 *
 * 来源：经验 2026-09-13-dashboard-widget-registry-multi-file-extension
 *       （Widget Props 统一 { wid: string }）
 * 来源：经验 2026-09-10-tailwind-v4-utility-class-to-design-token-migration
 *       （先读取 design-tokens.css 确认可用 token，不假设名称）
 */

interface DailyReportViewProps {
  wid: string;
}

/** 组件阶段 */
type Phase = "idle" | "streaming" | "done";

export function DailyReportView({ wid }: DailyReportViewProps) {
  const t = useTranslations("ai.dailyReport");
  const tp = useTranslations("ai.progress");

  // 日期选择器：默认今天（YYYY-MM-DD）
  const todayStr = new Date().toISOString().split("T")[0]!;
  const [date, setDate] = useState(todayStr);
  const [phase, setPhase] = useState<Phase>("idle");
  const [content, setContent] = useState("");
  const [editing, setEditing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);

  // 进度状态：当前阶段 + 阶段消息
  const [progressStage, setProgressStage] = useState<ProgressStage | null>(null);
  const [progressMessage, setProgressMessage] = useState<string>("");

  const abortRef = useRef<AbortController | null>(null);

  // 组件卸载时取消进行中的流式请求，避免 onDelta 回调在已卸载组件上触发 setContent
  useEffect(() => {
    return () => {
      abortRef.current?.abort();
    };
  }, []);

  /** 生成日报：调用流式 API（带进度反馈） */
  const handleGenerate = useCallback(async () => {
    // 取消进行中请求
    if (abortRef.current) abortRef.current.abort();
    const ac = new AbortController();
    abortRef.current = ac;

    setPhase("streaming");
    setContent("");
    setError(null);
    setSaved(false);
    setEditing(false);
    setProgressStage(null);
    setProgressMessage("");

    // date input 值为 YYYY-MM-DD，转为 ISO datetime 传给 API（zod .datetime()）
    const dateIso = `${date}T00:00:00.000Z`;

    try {
      const { text: full } = await consumeAiProgressStream(
        "/api/v1/ai/daily-report",
        { wid, date: dateIso },
        {
          signal: ac.signal,
          onDelta: (delta) => {
            setContent((prev) => prev + delta);
          },
          onProgress: (progress: AiProgressPart) => {
            setProgressStage(progress.stage);
            setProgressMessage(progress.message);
          },
        },
      );
      setContent(full);
      setPhase("done");
      setProgressStage(null);
    } catch (e) {
      // abort 不视为错误
      if ((e as Error).name === "AbortError") return;
      setError(t("generateFailed"));
      setPhase("idle");
      setProgressStage(null);
    } finally {
      if (abortRef.current === ac) abortRef.current = null;
    }
  }, [wid, date]);

  /** 保存为文档：POST /api/v1/workspaces/{wid}/documents */
  const handleSave = useCallback(async () => {
    if (!content.trim() || saving) return;
    setSaving(true);
    setError(null);
    try {
      await api(`/api/v1/workspaces/${wid}/documents`, {
        method: "POST",
        body: JSON.stringify({
          title: `${t("docTitle")} - ${date}`,
          markdown: content,
        }),
      });
      setSaved(true);
    } catch {
      setError(t("saveFailed"));
    } finally {
      setSaving(false);
    }
  }, [content, saving, wid, date]);

  const isStreaming = phase === "streaming";
  const hasContent = phase === "done" && content.length > 0;

  return (
    <div className="flex h-full flex-col">
      {/* 顶部工具栏：日期选择 + 生成按钮 */}
      <header className="flex flex-wrap items-center gap-[var(--space-3)] border-b border-[var(--border)] px-[var(--space-6)] py-[var(--space-4)]">
        <h1 className="text-[length:var(--text-lg)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
          {t("title")}
        </h1>

        <div className="ml-auto flex items-center gap-[var(--space-3)]">
          {/* 日期选择器 */}
          <label className="flex items-center gap-[var(--space-2)] text-[length:var(--text-sm)] text-[var(--fg-2)]">
            <Calendar size={14} className="text-[var(--meta)]" />
            <span className="sr-only">{t("dateLabel")}</span>
            <input
              type="date"
              value={date}
              max={todayStr}
              disabled={isStreaming}
              onChange={(e) => setDate(e.target.value)}
              className="rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] px-[var(--space-2)] py-[var(--space-1)] text-[length:var(--text-sm)] text-[var(--fg)] transition-colors duration-[var(--motion-fast)] focus:border-[var(--accent)] focus:outline-none focus:ring-2 focus:ring-[var(--accent-ring)] disabled:opacity-50"
            />
          </label>

          {/* 生成按钮 */}
          <button
            type="button"
            onClick={handleGenerate}
            disabled={isStreaming || !date}
            className="inline-flex items-center gap-[var(--space-2)] rounded-[var(--radius-md)] bg-[var(--accent)] px-[var(--space-4)] py-[var(--space-2)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--on-accent)] transition-colors duration-[var(--motion-fast)] hover:bg-[var(--accent-hover)] disabled:cursor-not-allowed disabled:opacity-40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
          >
            {isStreaming ? (
              <>
                <Loader2 size={14} className="animate-spin motion-reduce:animate-none" />
                {t("generating")}
              </>
            ) : (
              <>
                <Sparkles size={14} />
                {t("generate")}
              </>
            )}
          </button>
        </div>
      </header>

      {/* 主体内容区 */}
      <div className="flex-1 overflow-y-auto px-[var(--space-6)] py-[var(--space-5)]">
        {phase === "idle" && !error && (
          <div className="flex h-full flex-col items-center justify-center gap-[var(--space-3)] text-center">
            <Sparkles size={32} className="text-[var(--meta)]" />
            <p className="max-w-md text-[length:var(--text-sm)] text-[var(--meta)]">
              {t("empty")}
            </p>
          </div>
        )}

        {/* 流式生成中：进度步骤指示器 */}
        {isStreaming && progressStage && (
          <div className="mb-[var(--space-4)]">
            <ProgressSteps
              currentStage={progressStage}
              stageNames={[tp("context"), tp("analyzing"), tp("generating")]}
              currentMessage={progressMessage}
            />
          </div>
        )}

        {error && (
          <div className="mb-[var(--space-4)] rounded-[var(--radius-md)] border border-[var(--danger)] bg-[var(--danger-soft)] px-[var(--space-4)] py-[var(--space-3)] text-[length:var(--text-sm)] text-[var(--danger)]">
            {error}
          </div>
        )}

        {hasContent && (
          <div className="flex flex-col gap-[var(--space-3)]">
            {/* 预览/编辑切换 */}
            <div className="flex items-center gap-[var(--space-2)]">
              <button
                type="button"
                onClick={() => setEditing(false)}
                disabled={!editing}
                className="inline-flex items-center gap-[var(--space-1)] rounded-[var(--radius-sm)] px-[var(--space-2)] py-[var(--space-1)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] transition-colors duration-[var(--motion-fast)] hover:bg-[var(--surface-2)] disabled:opacity-40"
              >
                <Eye size={14} />
                {t("preview")}
              </button>
              <button
                type="button"
                onClick={() => setEditing(true)}
                disabled={editing}
                className="inline-flex items-center gap-[var(--space-1)] rounded-[var(--radius-sm)] px-[var(--space-2)] py-[var(--space-1)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] transition-colors duration-[var(--motion-fast)] hover:bg-[var(--surface-2)] disabled:opacity-40"
              >
                <Edit3 size={14} />
                {t("edit")}
              </button>
            </div>

            {/* 内容区：编辑模式 textarea / 预览模式 markdown */}
            {editing ? (
              <textarea
                value={content}
                onChange={(e) => {
                  setContent(e.target.value);
                  setSaved(false);
                }}
                className="min-h-[400px] w-full resize-y rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] px-[var(--space-4)] py-[var(--space-3)] font-[family-name:var(--font-mono)] text-[length:var(--text-sm)] text-[var(--fg)] leading-[var(--leading-relaxed)] transition-colors duration-[var(--motion-fast)] focus:border-[var(--accent)] focus:outline-none focus:ring-2 focus:ring-[var(--accent-ring)]"
                aria-label={t("edit")}
              />
            ) : (
              <div className="rounded-[var(--radius-md)] border border-[var(--border-soft)] bg-[var(--surface)] px-[var(--space-5)] py-[var(--space-4)]">
                <Markdown source={content} />
              </div>
            )}

            {/* AI 结果反馈按钮 */}
            <FeedbackButtons
              capability="daily-report"
              workspaceId={wid}
              originalOutput={content}
            />
          </div>
        )}

        {/* 流式生成中：实时渲染 markdown */}
        {isStreaming && content.length > 0 && (
          <div className="rounded-[var(--radius-md)] border border-[var(--border-soft)] bg-[var(--surface)] px-[var(--space-5)] py-[var(--space-4)]">
            <Markdown source={content} />
          </div>
        )}
      </div>

      {/* 底部操作栏：保存为文档 */}
      {hasContent && (
        <footer className="flex items-center justify-end gap-[var(--space-3)] border-t border-[var(--border)] px-[var(--space-6)] py-[var(--space-3)]">
          {saved && (
            <span className="text-[length:var(--text-xs)] text-[var(--success)]">
              {t("saved")}
            </span>
          )}
          <button
            type="button"
            onClick={handleSave}
            disabled={saving || !content.trim() || saved}
            className="inline-flex items-center gap-[var(--space-2)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] px-[var(--space-4)] py-[var(--space-2)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg)] transition-colors duration-[var(--motion-fast)] hover:bg-[var(--surface-2)] disabled:cursor-not-allowed disabled:opacity-40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
          >
            {saving ? (
              <>
                <Loader2 size={14} className="animate-spin motion-reduce:animate-none" />
                {t("saving")}
              </>
            ) : (
              <>
                <Save size={14} />
                {t("save")}
              </>
            )}
          </button>
        </footer>
      )}
    </div>
  );
}

"use client";

/**
 * AI 决策辅助面板组件（W3-A 决策辅助增强）。
 *
 * 功能：
 *  - 输入决策问题（如"应该选 A 方案还是 B 方案"）+ 可选补充背景
 *  - 点击分析按钮 → 调用 POST /api/v1/ai/decision-assistant
 *  - AI 基于工作区上下文（任务、决策历史、项目进度）进行多维度分析：
 *    · 展示可选方案卡片（标题、描述、优势、劣势、风险）
 *    · 推荐方案高亮 + 推荐理由
 *    · 历史决策参考列表
 *
 * 样式全走 design token（var(--*)），lucide-react 图标尺寸 14/16。
 * 错误处理：catch 中用 t("error")，不泄露 e.message。
 *
 * i18n：useTranslations("ai.decisionAssistant")，引用但不修改 zh.json/en.json。
 * key 暂未在 messages 文件中定义时，tf helper 回退到内置英文默认值，
 * 保证组件在 key 缺失时仍正常渲染（不抛 IntlError）。
 */

import { useCallback, useState } from "react";
import { useTranslations } from "next-intl";
import {
  Lightbulb,
  Loader2,
  Sparkles,
  AlertCircle,
  X,
  Check,
  ThumbsUp,
  ThumbsDown,
  AlertTriangle,
  History,
  Award,
} from "lucide-react";
import { api, ApiError } from "@/lib/api";
import { useToast } from "@/components/Toast";

// ── 类型定义 ──

/** AI 生成的可选方案 */
interface DecisionOption {
  title: string;
  description: string;
  pros: string[];
  cons: string[];
  risks: string[];
}

/** AI 生成的推荐方案 */
interface Recommendation {
  optionIndex: number;
  reason: string;
}

/** AI 生成的历史决策参考 */
interface HistoricalRef {
  title: string;
  outcome: string;
}

/** 决策辅助完整结果 */
interface DecisionAssistantResult {
  options: DecisionOption[];
  recommendation: Recommendation;
  historicalRefs: HistoricalRef[];
}


// ── 样式常量 ──

/** 输入框样式（design token） */
const fieldControl =
  "w-full px-2.5 py-2 border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] placeholder:text-[var(--meta)]";

/** 主按钮样式 */
const primaryBtn =
  "inline-flex items-center gap-1.5 h-9 px-3 bg-[var(--accent)] text-[var(--accent-fg)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]";

// ── 组件 Props ──

interface DecisionAssistantPanelProps {
  /** 工作区 ID */
  wid: string;
}

// ── 组件实现 ──

export default function DecisionAssistantPanel({
  wid,
}: DecisionAssistantPanelProps) {
  const t = useTranslations("ai.decisionAssistant");
  const { toast } = useToast();


  // ── 状态 ──

  const [question, setQuestion] = useState("");
  const [context, setContext] = useState("");
  const [analyzing, setAnalyzing] = useState(false);
  const [error, setError] = useState("");
  const [result, setResult] = useState<DecisionAssistantResult | null>(null);

  // ── 分析决策 ──

  const handleAnalyze = useCallback(async () => {
    if (analyzing || !question.trim()) return;
    setAnalyzing(true);
    setError("");
    try {
      const data = await api<DecisionAssistantResult>(
        "/api/v1/ai/decision-assistant",
        {
          method: "POST",
          body: JSON.stringify({
            wid,
            question: question.trim(),
            context: context.trim() || undefined,
          }),
        },
      );
      setResult(data);
      if (data.options.length === 0) {
        toast("warning", t("noResults"));
      }
    } catch (e) {
      if (process.env.NODE_ENV === "development")
        console.error("[DecisionAssistantPanel] analyze error:", e);
      const msg = e instanceof ApiError ? e.message : t("analyzeFailed");
      setError(msg);
    } finally {
      setAnalyzing(false);
    }
  }, [analyzing, question, context, wid, toast]);

  // ── 推荐方案索引 ──
  const recommendedIndex = result?.recommendation.optionIndex ?? -1;

  return (
    <div
      className="rounded-[var(--radius-lg)] border border-[var(--border)] bg-[var(--surface)] shadow-[var(--elev-sm)]"
      aria-label={t("title")}
    >
      {/* ── 头部 ── */}
      <header className="flex items-center justify-between px-5 py-3.5 border-b border-[var(--border-soft)]">
        <h2 className="flex items-center gap-2 text-[length:var(--text-md)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
          <Lightbulb size={16} className="text-[var(--accent)]" />
          {t("title")}
        </h2>
      </header>

      {/* ── 正文 ── */}
      <div className="px-5 py-4 space-y-[var(--space-3)]">
        {/* 错误态 */}
        {error && (
          <div className="flex items-start gap-2 px-3 py-2.5 rounded-[var(--radius-md)] bg-[var(--danger-soft)] text-[var(--danger-fg)] text-[length:var(--text-sm)]">
            <AlertCircle size={16} className="shrink-0 mt-0.5" />
            <span className="flex-1">{error}</span>
            <button
              type="button"
              onClick={() => setError("")}
              className="shrink-0 opacity-60 hover:opacity-100 transition-opacity focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] rounded-[var(--radius-sm)]"
              aria-label="close"
            >
              <X size={16} />
            </button>
          </div>
        )}

        {/* 决策问题输入区 */}
        <div className="space-y-2">
          <label
            className="block text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--fg-2)]"
            htmlFor="decision-question"
          >
            {t("questionLabel")}
          </label>
          <textarea
            id="decision-question"
            value={question}
            onChange={(e) => setQuestion(e.target.value)}
            placeholder={t("questionPlaceholder")}
            maxLength={2000}
            rows={3}
            disabled={analyzing}
            className={`${fieldControl} resize-y min-h-[80px] leading-relaxed disabled:opacity-60`}
            aria-label={t("questionLabel")}
          />
          {/* 补充背景（可选） */}
          <label
            className="block text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--meta)]"
            htmlFor="decision-context"
          >
            {t("contextLabel")}
          </label>
          <input
            id="decision-context"
            type="text"
            value={context}
            onChange={(e) => setContext(e.target.value)}
            placeholder={t("contextPlaceholder")}
            maxLength={2000}
            disabled={analyzing}
            className={`${fieldControl} disabled:opacity-60`}
            aria-label={t("contextLabel")}
          />
          {/* 分析按钮 */}
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={handleAnalyze}
              disabled={analyzing || !question.trim()}
              className={primaryBtn}
            >
              {analyzing ? (
                <Loader2 size={16} className="animate-spin motion-reduce:animate-none" />
              ) : (
                <Sparkles size={16} />
              )}
              {analyzing ? t("analyzing") : t("analyze")}
            </button>
            {!question.trim() && (
              <span className="text-[length:var(--text-xs)] text-[var(--meta)]">
                {t("noQuestion")}
              </span>
            )}
          </div>
        </div>

        {/* 加载态 */}
        {analyzing && (
          <div className="flex items-center justify-center py-8 text-[var(--muted)] text-[length:var(--text-sm)]">
            <Loader2
              size={16}
              className="animate-spin mr-2 motion-reduce:animate-none"
            />
            {t("analyzing")}
          </div>
        )}

        {/* 空态 */}
        {!analyzing && !result && (
          <div className="flex flex-col items-center justify-center py-12 text-[var(--muted)] text-[length:var(--text-sm)] gap-2">
            <Lightbulb size={32} className="opacity-40" />
            <p>{t("emptyHint")}</p>
          </div>
        )}

        {/* 分析结果 */}
        {!analyzing && result && (
          <div className="space-y-[var(--space-4)]">
            {/* 可选方案 */}
            {result.options.length > 0 && (
              <div className="space-y-[var(--space-2)]">
                <h3 className="flex items-center gap-1.5 text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
                  <Sparkles size={14} className="text-[var(--accent)]" />
                  {t("options")}
                </h3>
                <div className="space-y-[var(--space-3)]">
                  {result.options.map((option, index) => {
                    const isRecommended = index === recommendedIndex;
                    return (
                      <div
                        key={`option-${index}`}
                        className={`rounded-[var(--radius-md)] border p-[var(--space-3)] space-y-[var(--space-2)] ${
                          isRecommended
                            ? "border-[var(--accent)] bg-[var(--accent-soft)] shadow-[var(--elev-sm)]"
                            : "border-[var(--border)] bg-[var(--surface-2)]"
                        }`}
                      >
                        {/* 方案标题 */}
                        <div className="flex items-start justify-between gap-2">
                          <h4 className="flex items-center gap-1.5 text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
                            <span className="text-[var(--meta)]">
                              {t("optionLabel")} {index + 1}
                            </span>
                            {option.title}
                          </h4>
                          {isRecommended && (
                            <span className="inline-flex items-center gap-1 rounded-[var(--radius-sm)] bg-[var(--accent)] px-1.5 py-0.5 text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--accent-fg)]">
                              <Award size={14} />
                              {t("recommended")}
                            </span>
                          )}
                        </div>
                        {/* 方案描述 */}
                        {option.description && (
                          <p className="text-[length:var(--text-sm)] leading-relaxed text-[var(--fg-2)]">
                            {option.description}
                          </p>
                        )}
                        {/* 优势 */}
                        {option.pros.length > 0 && (
