"use client";

/**
 * AI 知识图谱可视化组件。
 *
 * 功能：
 *  - 用原生 SVG 绘制节点-边图（力导向简化布局：圆形排列 + 弹簧松弛）
 *  - 节点按 type 用不同颜色（concept: --accent, entity: --success, fact: --warning, procedure: --info）
 *  - 边按 relation 用不同线型（depends_on: 实线箭头, relates_to: 虚线, part_of: 实线, authored_by: 点线）
 *  - 支持点击节点查看详情、按类型过滤、搜索
 *  - 样式全走 design token（var(--*)），lucide-react 图标 size 14/16
 *
 * 数据来源：GET /api/v1/ai/knowledge/graph?wid=xxx
 * 删除节点：DELETE /api/v1/ai/knowledge/nodes/[id]?wid=xxx
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useTranslations } from "next-intl";
import {
  Brain,
  Search,
  Filter,
  Trash2,
  X,
  Loader2,
  AlertTriangle,
  Network,
} from "lucide-react";
import { api } from "@/lib/api";
import { useToast } from "@/components/Toast";

interface KnowledgeGraphViewProps {
  /** 工作区 ID */
  wid: string;
}

/** 知识图谱节点（与后端 KnowledgeNode 对齐） */
interface KnowledgeNode {
  id: string;
  workspaceId: string;
  type: string; // concept | entity | fact | procedure
  label: string;
  content: string;
  sourceType: string;
  sourceId: string;
  metadata: unknown;
  createdAt: string;
  updatedAt: string;
}

/** 知识图谱边（与后端 KnowledgeEdge 对齐） */
interface KnowledgeEdge {
  id: string;
  workspaceId: string;
  sourceNodeId: string;
  targetNodeId: string;
  relation: string; // depends_on | relates_to | part_of | authored_by
  weight: number;
  metadata: unknown;
  createdAt: string;
}

/** 节点类型 → design token 颜色映射 */
const NODE_COLOR: Record<string, string> = {
  concept: "var(--accent)",
  entity: "var(--success)",
  fact: "var(--warning)",
  procedure: "var(--info)",
};

/** 关系类型 → SVG stroke-dasharray 线型映射 */
const EDGE_DASH: Record<string, string> = {
  depends_on: "none", // 实线
  relates_to: "6 4", // 虚线
  part_of: "none", // 实线
  authored_by: "2 3", // 点线
};

/** 节点类型列表（用于过滤） */
const NODE_TYPES = ["concept", "entity", "fact", "procedure"] as const;

/** 布局后的节点位置 */
interface PositionedNode {
  node: KnowledgeNode;
  x: number;
  y: number;
}

/** SVG 视口常量 */
const SVG_WIDTH = 800;
const SVG_HEIGHT = 600;
const NODE_RADIUS = 24;

/**
 * 简化力导向布局：圆形初始排列 + 几轮弹簧松弛。
 * 不引入外部图库，用原生数学计算。
 */
function computeLayout(
  nodes: KnowledgeNode[],
  edges: KnowledgeEdge[],
): PositionedNode[] {
  if (nodes.length === 0) return [];

  const n = nodes.length;
  const cx = SVG_WIDTH / 2;
  const cy = SVG_HEIGHT / 2;
  const radius = Math.min(SVG_WIDTH, SVG_HEIGHT) / 2 - NODE_RADIUS * 3;

  // 初始：圆形排列
  const positions: PositionedNode[] = nodes.map((node, i) => ({
    node,
    x: cx + radius * Math.cos((2 * Math.PI * i) / n),
    y: cy + radius * Math.sin((2 * Math.PI * i) / n),
  }));

  // 构建邻接表
  const adj = new Map<string, Set<string>>();
  for (const node of nodes) adj.set(node.id, new Set());
  for (const edge of edges) {
    adj.get(edge.sourceNodeId)?.add(edge.targetNodeId);
    adj.get(edge.targetNodeId)?.add(edge.sourceNodeId);
  }

  // 弹簧松弛迭代（简化版：连接的节点相互吸引，所有节点相互排斥）
  const iterations = 30;
  const posMap = new Map(positions.map((p) => [p.node.id, p]));

  for (let iter = 0; iter < iterations; iter++) {
    const forces = new Map<string, { x: number; y: number }>();
    for (const p of positions) forces.set(p.node.id, { x: 0, y: 0 });

    // 排斥力（所有节点对）
    for (let i = 0; i < positions.length; i++) {
      for (let j = i + 1; j < positions.length; j++) {
        const a = positions[i];
        const b = positions[j];
        const dx = b.x - a.x;
        const dy = b.y - a.y;
        const dist = Math.sqrt(dx * dx + dy * dy) || 1;
        const force = 2000 / (dist * dist);
        const fx = (dx / dist) * force;
        const fy = (dy / dist) * force;
        forces.get(a.node.id)!.x -= fx;
        forces.get(a.node.id)!.y -= fy;
        forces.get(b.node.id)!.x += fx;
        forces.get(b.node.id)!.y += fy;
      }
    }

    // 吸引力（连接的节点对）
    for (const p of positions) {
      const neighbors = adj.get(p.node.id);
      if (!neighbors) continue;
      for (const neighborId of neighbors) {
        const q = posMap.get(neighborId);
        if (!q) continue;
        const dx = q.x - p.x;
        const dy = q.y - p.y;
        const dist = Math.sqrt(dx * dx + dy * dy) || 1;
        const force = dist * 0.05;
        const fx = (dx / dist) * force;
        const fy = (dy / dist) * force;
        forces.get(p.node.id)!.x += fx;
        forces.get(p.node.id)!.y += fy;
      }
    }

    // 应用力（带阻尼）
    const damping = 0.5;
    for (const p of positions) {
      const f = forces.get(p.node.id)!;
      p.x += f.x * damping;
      p.y += f.y * damping;
      // 边界约束
      p.x = Math.max(NODE_RADIUS * 2, Math.min(SVG_WIDTH - NODE_RADIUS * 2, p.x));
      p.y = Math.max(NODE_RADIUS * 2, Math.min(SVG_HEIGHT - NODE_RADIUS * 2, p.y));
    }
  }

  return positions;
}

export function KnowledgeGraphView({ wid }: KnowledgeGraphViewProps) {
  const t = useTranslations("ai.aiKnowledge");
  const { toast } = useToast();

  const [nodes, setNodes] = useState<KnowledgeNode[]>([]);
  const [edges, setEdges] = useState<KnowledgeEdge[]>([]);
  const [loading, setLoading] = useState(false);
  const [hasError, setHasError] = useState(false);
  const [selectedNode, setSelectedNode] = useState<KnowledgeNode | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [activeTypes, setActiveTypes] = useState<Set<string>>(
    new Set(NODE_TYPES),
  );
  const [deleting, setDeleting] = useState(false);

  /** 加载知识图谱 */
  const loadGraph = useCallback(async () => {
    setLoading(true);
    setHasError(false);
    try {
      const data = await api<{ nodes: KnowledgeNode[]; edges: KnowledgeEdge[] }>(
        `/api/v1/ai/knowledge/graph?wid=${wid}&limit=200`,
      );
      setNodes(data?.nodes ?? []);
      setEdges(data?.edges ?? []);
    } catch (e) {
      if (process.env.NODE_ENV === "development") {
        console.error("[KnowledgeGraphView] loadGraph error:", e instanceof Error ? e.message : e);
      }
      setHasError(true);
      toast("error", t("loadFailed"));
    } finally {
      setLoading(false);
    }
  }, [wid, t, toast]);

  useEffect(() => {
    void loadGraph();
  }, [loadGraph]);

  /** 删除节点 */
  const handleDeleteNode = useCallback(async () => {
    if (!selectedNode) return;
    setDeleting(true);
    try {
      await api(`/api/v1/ai/knowledge/nodes/${selectedNode.id}?wid=${wid}`, {
        method: "DELETE",
      });
      setNodes((prev) => prev.filter((n) => n.id !== selectedNode.id));
      setEdges((prev) =>
        prev.filter(
          (e) =>
            e.sourceNodeId !== selectedNode.id && e.targetNodeId !== selectedNode.id,
        ),
      );
      setSelectedNode(null);
      toast("success", t("deleted"));
    } catch (e) {
      if (process.env.NODE_ENV === "development") {
        console.error("[KnowledgeGraphView] deleteNode error:", e instanceof Error ? e.message : e);
      }
      toast("error", t("error"));
    } finally {
      setDeleting(false);
    }
  }, [selectedNode, wid, t, toast]);

  /** 过滤后的节点 */
  const filteredNodes = useMemo(() => {
    return nodes.filter((n) => {
      if (!activeTypes.has(n.type)) return false;
      if (searchQuery.trim()) {
        const q = searchQuery.toLowerCase();
        return (
          n.label.toLowerCase().includes(q) ||
          n.content.toLowerCase().includes(q)
        );
      }
      return true;
    });
  }, [nodes, activeTypes, searchQuery]);

  /** 过滤后的节点 ID 集合 */
  const filteredNodeIds = useMemo(
    () => new Set(filteredNodes.map((n) => n.id)),
    [filteredNodes],
  );

  /** 过滤后的边 */
  const filteredEdges = useMemo(() => {
    return edges.filter(
      (e) =>
        filteredNodeIds.has(e.sourceNodeId) && filteredNodeIds.has(e.targetNodeId),
    );
  }, [edges, filteredNodeIds]);

  /** 布局计算 */
  const positionedNodes = useMemo(
    () => computeLayout(filteredNodes, filteredEdges),
    [filteredNodes, filteredEdges],
  );
  const positionMap = useMemo(
    () => new Map(positionedNodes.map((p) => [p.node.id, p])),
    [positionedNodes],
  );

  /** 切换类型过滤 */
  const toggleType = (type: string) => {
    setActiveTypes((prev) => {
      const next = new Set(prev);
      if (next.has(type)) next.delete(type);
      else next.add(type);
      return next;
    });
  };

  /** 选中节点的关联边 */
  const selectedNodeEdges = useMemo(() => {
    if (!selectedNode) return [];
    return edges.filter(
      (e) => e.sourceNodeId === selectedNode.id || e.targetNodeId === selectedNode.id,
    );
  }, [selectedNode, edges]);

  return (
    <div
      className="flex h-full flex-col bg-[var(--surface)]"
      aria-label={t("title")}
    >
      {/* 标题栏 */}
      <header className="flex items-center justify-between border-b border-[var(--border)] px-[var(--space-5)] py-[var(--space-3)]">
        <div className="flex items-center gap-[var(--space-2)]">
          <Network size={16} className="text-[var(--accent)]" />
          <h1 className="text-[length:var(--text-lg)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
            {t("title")}
          </h1>
        </div>
        <button
          type="button"
          onClick={() => void loadGraph()}
          disabled={loading}
          className="inline-flex h-8 items-center gap-[var(--space-1)] rounded-[var(--radius-sm)] px-[var(--space-2)] text-[var(--muted)] transition-colors duration-[var(--motion-fast)] hover:bg-[var(--surface-2)] hover:text-[var(--fg)] disabled:cursor-not-allowed disabled:opacity-40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
          aria-label={t("graph")}
        >
          {loading ? <Loader2 size={14} className="animate-spin" /> : <Brain size={14} />}
          <span className="text-[length:var(--text-sm)]">{t("graph")}</span>
        </button>
      </header>

      {/* 工具栏：搜索 + 类型过滤 */}
      <div className="flex flex-wrap items-center gap-[var(--space-2)] border-b border-[var(--border)] px-[var(--space-5)] py-[var(--space-2)]">
        {/* 搜索框 */}
        <div className="relative flex-1 min-w-[200px]">
          <Search
            size={14}
            className="absolute left-[var(--space-2)] top-1/2 -translate-y-1/2 text-[var(--muted)]"
          />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.currentTarget.value)}
            placeholder={t("search")}
            className="w-full rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface-2)] py-[var(--space-1)] pl-[var(--space-7)] pr-[var(--space-2)] text-[length:var(--text-sm)] text-[var(--fg)] placeholder:text-[var(--muted)] focus:border-[var(--accent)] focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-[var(--accent-ring)]"
          />
        </div>

        {/* 类型过滤 */}
        <div className="flex items-center gap-[var(--space-1)]">
          <Filter size={14} className="text-[var(--muted)]" />
          <span className="text-[length:var(--text-sm)] text-[var(--muted)]">
            {t("filterByType")}:
          </span>
          {NODE_TYPES.map((type) => (
            <button
              key={type}
              type="button"
              onClick={() => toggleType(type)}
              className={`inline-flex items-center gap-[var(--space-1)] rounded-[var(--radius-sm)] border px-[var(--space-2)] py-[var(--space-1)] text-[length:var(--text-xs)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] ${
                activeTypes.has(type)
                  ? "border-[var(--accent)] bg-[var(--accent-soft)] text-[var(--fg)]"
                  : "border-[var(--border)] text-[var(--muted)] hover:bg-[var(--surface-2)]"
              }`}
            >
              <span
                className="inline-block h-2 w-2 rounded-full"
                style={{ backgroundColor: `var(${NODE_COLOR[type]})` }}
              />
              {type}
            </button>
          ))}
        </div>
      </div>

      {/* 主体：图谱 + 详情侧栏 */}
      <div className="flex flex-1 overflow-hidden">
        {/* SVG 图谱 */}
        <div className="flex-1 overflow-auto p-[var(--space-3)]">
          {loading ? (
            <div className="flex h-full items-center justify-center">
              <Loader2 size={24} className="animate-spin text-[var(--muted)]" />
            </div>
          ) : hasError ? (
            <div className="flex h-full flex-col items-center justify-center gap-[var(--space-2)] text-[var(--muted)]">
              <AlertTriangle size={24} className="text-[var(--danger)]" />
              <p className="text-[length:var(--text-sm)]">{t("loadFailed")}</p>
            </div>
          ) : filteredNodes.length === 0 ? (
            <div className="flex h-full items-center justify-center text-[var(--muted)]">
              <p className="text-[length:var(--text-sm)]">{t("noData")}</p>
            </div>
          ) : (
            <svg
              viewBox={`0 0 ${SVG_WIDTH} ${SVG_HEIGHT}`}
              className="h-full w-full"
              preserveAspectRatio="xMidYMid meet"
            >
              {/* 绘制边 */}
              <defs>
                <marker
                  id="arrowhead"
                  markerWidth="8"
                  markerHeight="6"
                  refX="8"
                  refY="3"
                  orient="auto"
                >
                  <polygon
                    points="0 0, 8 3, 0 6"
                    fill="var(--muted)"
                  />
                </marker>
              </defs>
              {filteredEdges.map((edge) => {
                const source = positionMap.get(edge.sourceNodeId);
                const target = positionMap.get(edge.targetNodeId);
                if (!source || !target) return null;
                return (
                  <line
                    key={edge.id}
                    x1={source.x}
                    y1={source.y}
                    x2={target.x}
                    y2={target.y}
                    stroke="var(--muted)"
                    strokeWidth={1 + edge.weight}
                    strokeDasharray={EDGE_DASH[edge.relation] ?? "none"}
                    markerEnd={
                      edge.relation === "depends_on" ? "url(#arrowhead)" : undefined
                    }
                    opacity={0.6}
                  />
                );
              })}

              {/* 绘制节点 */}
              {positionedNodes.map(({ node, x, y }) => (
                <g
                  key={node.id}
                  transform={`translate(${x}, ${y})`}
                  className="cursor-pointer"
                  onClick={() => setSelectedNode(node)}
                >
                  <circle
                    r={NODE_RADIUS}
                    fill={`var(${NODE_COLOR[node.type] ?? "var(--accent)"})`}
                    fillOpacity={0.2}
                    stroke={`var(${NODE_COLOR[node.type] ?? "var(--accent)"})`}
                    strokeWidth={2}
                  />
                  <text
                    textAnchor="middle"
                    dy="0.35em"
                    className="pointer-events-none select-none"
                    fontSize="10"
                    fill="var(--fg)"
                  >
                    {node.label.length > 8
                      ? node.label.slice(0, 8) + "…"
                      : node.label}
                  </text>
                </g>
              ))}
            </svg>
          )}
        </div>

        {/* 节点详情侧栏 */}
        {selectedNode && (
          <aside className="flex w-80 flex-col border-l border-[var(--border)] bg-[var(--surface-2)]">
            <div className="flex items-center justify-between border-b border-[var(--border)] px-[var(--space-3)] py-[var(--space-2)]">
              <h2 className="text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
                {t("nodeDetail")}
              </h2>
              <button
                type="button"
                onClick={() => setSelectedNode(null)}
                className="inline-flex h-6 w-6 items-center justify-center rounded-[var(--radius-sm)] text-[var(--muted)] transition-colors duration-[var(--motion-fast)] hover:bg-[var(--surface-3)] hover:text-[var(--fg)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
                aria-label="close"
              >
                <X size={14} />
              </button>
            </div>
            <div className="flex-1 overflow-auto p-[var(--space-3)]">
              <dl className="flex flex-col gap-[var(--space-3)]">
                <div>
                  <dt className="text-[length:var(--text-xs)] text-[var(--muted)]">
                    {t("type")}
                  </dt>
                  <dd className="flex items-center gap-[var(--space-1)] text-[length:var(--text-sm)] text-[var(--fg)]">
                    <span
                      className="inline-block h-2 w-2 rounded-full"
                      style={{
                        backgroundColor: `var(${NODE_COLOR[selectedNode.type] ?? "var(--accent)"})`,
                      }}
                    />
                    {selectedNode.type}
                  </dd>
                </div>
                <div>
                  <dt className="text-[length:var(--text-xs)] text-[var(--muted)]">
                    {t("label")}
                  </dt>
                  <dd className="text-[length:var(--text-sm)] text-[var(--fg)]">
                    {selectedNode.label}
                  </dd>
                </div>
                <div>
                  <dt className="text-[length:var(--text-xs)] text-[var(--muted)]">
                    {t("content")}
                  </dt>
                  <dd className="whitespace-pre-wrap text-[length:var(--text-sm)] text-[var(--fg-2)]">
                    {selectedNode.content}
                  </dd>
                </div>
                <div>
                  <dt className="text-[length:var(--text-xs)] text-[var(--muted)]">
                    {t("source")}
                  </dt>
                  <dd className="text-[length:var(--text-sm)] text-[var(--fg-2)]">
                    {selectedNode.sourceType}
                  </dd>
                </div>
                <div>
                  <dt className="text-[length:var(--text-xs)] text-[var(--muted)]">
                    {t("relations")}
                  </dt>
                  <dd>
                    {selectedNodeEdges.length === 0 ? (
                      <span className="text-[length:var(--text-sm)] text-[var(--muted)]">
                        —
                      </span>
                    ) : (
                      <ul className="flex flex-col gap-[var(--space-1)]">
                        {selectedNodeEdges.map((edge) => {
                          const otherId =
                            edge.sourceNodeId === selectedNode.id
                              ? edge.targetNodeId
                              : edge.sourceNodeId;
                          const otherNode = nodes.find((n) => n.id === otherId);
                          const direction =
                            edge.sourceNodeId === selectedNode.id ? "→" : "←";
                          return (
                            <li
                              key={edge.id}
                              className="text-[length:var(--text-sm)] text-[var(--fg-2)]"
                            >
                              {direction} {edge.relation}: {otherNode?.label ?? otherId.slice(0, 8)}
                            </li>
                          );
                        })}
                      </ul>
                    )}
                  </dd>
                </div>
              </dl>
            </div>
            {/* 删除按钮 */}
            <div className="border-t border-[var(--border)] p-[var(--space-3)]">
              <button
                type="button"
                onClick={() => {
                  if (window.confirm(t("confirmDelete"))) {
                    void handleDeleteNode();
                  }
                }}
                disabled={deleting}
                className="inline-flex w-full items-center justify-center gap-[var(--space-1)] rounded-[var(--radius-sm)] border border-[var(--danger)] py-[var(--space-2)] text-[length:var(--text-sm)] text-[var(--danger)] transition-colors duration-[var(--motion-fast)] hover:bg-[var(--danger)] hover:text-[var(--surface)] disabled:cursor-not-allowed disabled:opacity-40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
              >
                {deleting ? (
                  <Loader2 size={14} className="animate-spin" />
                ) : (
                  <Trash2 size={14} />
                )}
                {t("deleteNode")}
              </button>
            </div>
          </aside>
        )}
      </div>
    </div>
  );
}

"use client";

/**
 * AI 邮件助手面板。
 *
 * 调用 POST /api/v1/ai/mail-assistant，支持四种操作：
 *  - draft（起草）：流式生成专业商务邮件正文，逐字渲染 markdown
 *  - summarize（摘要）：生成要点列表格式摘要
 *  - classify（分类）：返回类别 + 置信度 + 理由（reasoner 模型）
 *  - reply（回复）：生成 3 个不同语气的回复建议卡片，点击可复制
 *
 * 交互流程：
 *  1. 顶部 4 个 tab 切换操作类型
 *  2. 内容输入 textarea（必填）+ 上下文输入 textarea（可选）
 *  3. 点击"执行"按钮发起请求
 *  4. 结果区按 action 类型分别渲染：
 *     - draft：流式 markdown 实时渲染
 *     - summarize：摘要 markdown
 *     - classify：类别标签 + 置信度进度条 + 理由文本
 *     - reply：3 个建议卡片（tone 标签 + 文本 + 复制按钮）
 *
 * Design token 颜色映射：
 *  - 类别 work     → var(--accent) / var(--accent-soft)
 *  - 类别 notice   → var(--success) / var(--success-soft)
 *  - 类别 personal → var(--status-warn) / var(--warn-soft)
 *  - 类别 urgent   → var(--danger) / var(--danger-soft)
 *  - 类别 other    → var(--muted) / var(--surface-3)
 *  - 语气 formal   → var(--accent) / var(--accent-soft)
 *  - 语气 casual   → var(--success) / var(--success-soft)
 *  - 语气 concise  → var(--muted) / var(--surface-3)
 *
 * i18n 兜底：zh.json/en.json 暂未入库 ai.mailAssistant.* 键，
 * 用 FALLBACK 字典兜底，避免显示 key 本身。
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { useTranslations } from "next-intl";
import {
  Mail,
  PenLine,
  FileText,
  Tags,
  Reply,
  Copy,
  Loader2,
  Check,
} from "lucide-react";
import Markdown from "@/components/Markdown";
import { consumeAiStream } from "@/components/editor/aiStream";
import { api, ApiError } from "@/lib/api";

// ─── 类型定义 ───

type MailAction = "draft" | "summarize" | "classify" | "reply";

type MailCategory = "work" | "notice" | "personal" | "urgent" | "other";

type MailReplyTone = "formal" | "casual" | "concise";

interface ClassifyResult {
  category: MailCategory;
  confidence: number;
  reason: string;
}

interface ReplySuggestion {
  text: string;
  tone: MailReplyTone;
}

interface MailAssistantPanelProps {
  wid: string;
}


// ─── 类别 / 语气视觉映射 ───

function getCategoryVisual(category: MailCategory) {
  switch (category) {
    case "work":
      return {
        color: "var(--accent)",
        bg: "var(--accent-soft)",
        labelKey: "categoryWork",
      };
    case "notice":
      return {
        color: "var(--success)",
        bg: "var(--success-soft)",
        labelKey: "categoryNotice",
      };
    case "personal":
      return {
        color: "var(--status-warn)",
        bg: "var(--warn-soft)",
        labelKey: "categoryPersonal",
      };
    case "urgent":
      return {
        color: "var(--danger)",
        bg: "var(--danger-soft)",
        labelKey: "categoryUrgent",
      };
    case "other":
      return {
        color: "var(--muted)",
        bg: "var(--surface-3)",
        labelKey: "categoryOther",
      };
  }
}

function getToneVisual(tone: MailReplyTone) {
  switch (tone) {
    case "formal":
      return {
        color: "var(--accent)",
        bg: "var(--accent-soft)",
        labelKey: "toneFormal",
      };
    case "casual":
      return {
        color: "var(--success)",
        bg: "var(--success-soft)",
        labelKey: "toneCasual",
      };
    case "concise":
      return {
        color: "var(--muted)",
        bg: "var(--surface-3)",
        labelKey: "toneConcise",
      };
  }
}

// ─── Tab 配置 ───

const TABS: ReadonlyArray<{
  action: MailAction;
  icon: typeof Mail;
  labelKey: string;
}> = [
  { action: "draft", icon: PenLine, labelKey: "actionDraft" },
  { action: "summarize", icon: FileText, labelKey: "actionSummarize" },
  { action: "classify", icon: Tags, labelKey: "actionClassify" },
  { action: "reply", icon: Reply, labelKey: "actionReply" },
];

// ─── 组件 ───

export function MailAssistantPanel({ wid }: MailAssistantPanelProps) {
  const t = useTranslations("ai.mailAssistant");


  const [action, setAction] = useState<MailAction>("draft");
  const [content, setContent] = useState("");
  const [context, setContext] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // 流式起草实时文本
  const [draftText, setDraftText] = useState("");

  // 摘要结果
  const [summary, setSummary] = useState("");

  // 分类结果
  const [classifyResult, setClassifyResult] = useState<ClassifyResult | null>(null);

  // 回复建议
  const [suggestions, setSuggestions] = useState<ReplySuggestion[]>([]);

  // 复制按钮状态
  const [copiedIndex, setCopiedIndex] = useState<number | null>(null);

  // AbortController：组件卸载或重新发起请求时中止进行中的 fetch
  const abortRef = useRef<AbortController | null>(null);

  // 复制按钮 timer id：组件卸载时清理，避免 setTimeout 在已卸载组件上触发 setState
  const copyTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  /** 执行操作 */
  const handleExecute = useCallback(async () => {
    if (!content.trim() || loading) return;

    // 中止之前未完成的请求
    abortRef.current?.abort();
    const ac = new AbortController();
    abortRef.current = ac;

    setLoading(true);
    setError(null);
    // 重置结果区
    setDraftText("");
    setSummary("");
    setClassifyResult(null);
    setSuggestions([]);

    try {
      if (action === "draft") {
        // 流式起草
        const full = await consumeAiStream(
          "/api/v1/ai/mail-assistant",
          { wid, action, content, context: context.trim() || undefined },
          {
            signal: ac.signal,
            onDelta: (delta) => {
              setDraftText((prev) => prev + delta);
            },
          },
        );
        if (ac.signal.aborted) return;
        setDraftText(full);
      } else {
        // 非流式：summarize / classify / reply
        if (action === "summarize") {
          const data = await api<{ summary: string }>(
            "/api/v1/ai/mail-assistant",
            {
              method: "POST",
              body: JSON.stringify({
                wid,
                action,
                content,
                context: context.trim() || undefined,
              }),
              signal: ac.signal,
            },
          );
          if (ac.signal.aborted) return;
          setSummary(data?.summary ?? "");
        } else if (action === "classify") {
          const data = await api<ClassifyResult>(
            "/api/v1/ai/mail-assistant",
            {
              method: "POST",
              body: JSON.stringify({
                wid,
                action,
                content,
                context: context.trim() || undefined,
              }),
              signal: ac.signal,
            },
          );
          if (ac.signal.aborted) return;
          setClassifyResult(data);
        } else {
          // reply
          const data = await api<{ suggestions: ReplySuggestion[] }>(
            "/api/v1/ai/mail-assistant",
            {
              method: "POST",
              body: JSON.stringify({
                wid,
                action,
                content,
                context: context.trim() || undefined,
              }),
              signal: ac.signal,
            },
          );
          if (ac.signal.aborted) return;
          setSuggestions(Array.isArray(data?.suggestions) ? data.suggestions : []);
        }
      }
    } catch (e) {
      if (ac.signal.aborted) return;
      // AbortError 是主动中止，不显示错误状态
      if (e instanceof Error && e.name === "AbortError") return;
      setError(t("error"));
      // 仅在开发环境输出错误日志，避免生产环境噪音
      if (
        process.env.NODE_ENV === "development" &&
        (e instanceof ApiError || e instanceof Error)
      ) {
        console.error("[MailAssistantPanel] error:", e.message);
      }
    } finally {
      if (ac.signal.aborted) return;
      setLoading(false);
    }
  }, [action, content, context, loading, wid]);

  /** 切换 tab：重置结果区 */
  const handleTabChange = useCallback((next: MailAction) => {
    abortRef.current?.abort();
    setAction(next);
    setError(null);
    setDraftText("");
    setSummary("");
    setClassifyResult(null);
    setSuggestions([]);
  }, []);

  /** 复制回复建议到剪贴板 */
  const handleCopy = useCallback(async (text: string, index: number) => {
    try {
      await navigator.clipboard.writeText(text);
    } catch {
      // 剪贴板 API 不可用时静默降级
    }
    setCopiedIndex(index);
    // 2 秒后恢复复制按钮图标；清理上一个 timer 避免重叠
    if (copyTimerRef.current) clearTimeout(copyTimerRef.current);
    copyTimerRef.current = setTimeout(
      () => setCopiedIndex((prev) => (prev === index ? null : prev)),
      2000,
    );
  }, []);

  // 组件卸载时清理：中止进行中的请求 + 清理复制 timer，避免在已卸载组件上触发 setState
  useEffect(() => {
    return () => {
      abortRef.current?.abort();
      if (copyTimerRef.current) clearTimeout(copyTimerRef.current);
    };
  }, []);

  const hasDraftResult = !loading && draftText.length > 0;
  const hasSummaryResult = !loading && summary.length > 0;
  const hasClassifyResult = !loading && classifyResult !== null;
  const hasReplyResult = !loading && suggestions.length > 0;

  return (
    <div className="flex h-full flex-col">
      {/* 顶部标题栏 */}
      <header className="flex items-center gap-[var(--space-3)] border-b border-[var(--border)] px-[var(--space-6)] py-[var(--space-4)]">
        <Mail size={16} className="shrink-0 text-[var(--accent)]" />
        <h1 className="text-[length:var(--text-lg)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
          {t("title")}
        </h1>
      </header>

      {/* Tab 切换栏 */}
      <nav
        className="flex items-center gap-[var(--space-1)] border-b border-[var(--border)] px-[var(--space-6)] py-[var(--space-2)]"
        aria-label={t("title")}
      >
        {TABS.map((tab) => {
          const Icon = tab.icon;
          const isActive = action === tab.action;
          return (
            <button
              key={tab.action}
              type="button"
              onClick={() => handleTabChange(tab.action)}
              aria-pressed={isActive}
              className={
                "inline-flex items-center gap-[var(--space-2)] rounded-[var(--radius-sm)] px-[var(--space-3)] py-[var(--space-2)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] " +
                (isActive
                  ? "bg-[var(--accent-soft)] text-[var(--accent)]"
                  : "text-[var(--fg-2)] hover:bg-[var(--surface-2)] hover:text-[var(--fg)]")
              }
            >
              <Icon size={16} className="shrink-0" />
              {t(tab.labelKey)}
            </button>
          );
        })}
      </nav>

      {/* 主体内容区 */}
      <div className="flex-1 overflow-y-auto px-[var(--space-6)] py-[var(--space-5)]">
        <div className="flex flex-col gap-[var(--space-4)]">
          {/* 内容输入 */}
          <div className="flex flex-col gap-[var(--space-2)]">
            <label
              htmlFor="mail-assistant-content"
              className="text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)]"
            >
              {t("contentLabel")}
            </label>
            <textarea
              id="mail-assistant-content"
              value={content}
              onChange={(e) => setContent(e.target.value)}
              maxLength={20_000}
              disabled={loading}
              placeholder={t("contentPlaceholder")}
              className="min-h-[120px] w-full resize-y rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] px-[var(--space-3)] py-[var(--space-2)] text-[length:var(--text-sm)] text-[var(--fg)] leading-[var(--leading-relaxed)] transition-colors duration-[var(--motion-fast)] focus:border-[var(--accent)] focus:outline-none focus:ring-2 focus:ring-[var(--accent-ring)] disabled:opacity-50"
            />
          </div>

          {/* 上下文输入（可选） */}
          <div className="flex flex-col gap-[var(--space-2)]">
            <label
              htmlFor="mail-assistant-context"
              className="text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)]"
            >
              {t("contextLabel")}
            </label>
            <textarea
              id="mail-assistant-context"
              value={context}
              onChange={(e) => setContext(e.target.value)}
              maxLength={5000}
              disabled={loading}
              placeholder={t("contextPlaceholder")}
              className="min-h-[60px] w-full resize-y rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] px-[var(--space-3)] py-[var(--space-2)] text-[length:var(--text-sm)] text-[var(--fg-2)] leading-[var(--leading-relaxed)] transition-colors duration-[var(--motion-fast)] focus:border-[var(--accent)] focus:outline-none focus:ring-2 focus:ring-[var(--accent-ring)] disabled:opacity-50"
            />
          </div>

          {/* 执行按钮 */}
          <div className="flex items-center gap-[var(--space-3)]">
            <button
              type="button"
              onClick={() => void handleExecute()}
              disabled={loading || !content.trim()}
              className="inline-flex items-center gap-[var(--space-2)] rounded-[var(--radius-md)] bg-[var(--accent)] px-[var(--space-4)] py-[var(--space-2)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--on-accent)] transition-colors duration-[var(--motion-fast)] hover:bg-[var(--accent-hover)] disabled:cursor-not-allowed disabled:opacity-40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
            >
              {loading ? (
                <>
                  <Loader2 size={16} className="shrink-0 animate-spin motion-reduce:animate-none" />
                  {t("generating")}
                </>
              ) : (
                <>
                  <Mail size={16} className="shrink-0" />
                  {t("execute")}
                </>
              )}
            </button>
          </div>

          {/* 错误提示 */}
          {error && (
            <div className="rounded-[var(--radius-md)] border border-[var(--danger)] bg-[var(--danger-soft)] px-[var(--space-4)] py-[var(--space-3)] text-[length:var(--text-sm)] text-[var(--danger)]">
              {error}
            </div>
          )}

          {/* ─── 结果展示区 ─── */}

          {/* draft：流式 markdown 渲染 */}
          {(loading || hasDraftResult) && action === "draft" && draftText.length > 0 && (
            <div className="rounded-[var(--radius-md)] border border-[var(--border-soft)] bg-[var(--surface)] px-[var(--space-5)] py-[var(--space-4)]">
              <Markdown source={draftText} />
            </div>
          )}

          {/* summarize：摘要 markdown */}
          {hasSummaryResult && action === "summarize" && (
            <div className="flex flex-col gap-[var(--space-3)]">
              <div className="flex items-center gap-[var(--space-2)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)]">
                <FileText size={16} className="shrink-0 text-[var(--accent)]" />
                {t("actionSummarize")}
              </div>
              <div className="rounded-[var(--radius-md)] border border-[var(--border-soft)] bg-[var(--surface)] px-[var(--space-5)] py-[var(--space-4)]">
                <Markdown source={summary} />
              </div>
            </div>
          )}

          {/* classify：类别标签 + 置信度 + 理由 */}
          {hasClassifyResult && action === "classify" && classifyResult && (
            <div className="flex flex-col gap-[var(--space-4)]">
              <div className="flex items-center gap-[var(--space-2)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)]">
                <Tags size={16} className="shrink-0 text-[var(--accent)]" />
                {t("actionClassify")}
              </div>

              {/* 类别标签 */}
              {(() => {
                const visual = getCategoryVisual(classifyResult.category);
                return (
                  <div className="flex flex-wrap items-center gap-[var(--space-3)]">
                    <span
                      className="inline-flex items-center rounded-[var(--radius-sm)] px-[var(--space-3)] py-[var(--space-1)] text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)]"
                      style={{ color: visual.color, backgroundColor: visual.bg }}
                    >
                      {t(visual.labelKey)}
                    </span>

                    {/* 置信度进度条 */}
                    <div className="flex items-center gap-[var(--space-2)]">
                      <span className="text-[length:var(--text-xs)] text-[var(--meta)]">
                        {t("confidence")}
                      </span>
                      <div
                        className="h-[6px] w-[120px] overflow-hidden rounded-[var(--radius-sm)] bg-[var(--surface-3)]"
                        role="progressbar"
                        aria-valuenow={Math.round(classifyResult.confidence * 100)}
                        aria-valuemin={0}
                        aria-valuemax={100}
                      >
                        <div
                          className="h-full rounded-[var(--radius-sm)] bg-[var(--accent)] transition-all duration-[var(--motion-fast)]"
                          style={{
                            width: `${Math.round(classifyResult.confidence * 100)}%`,
                          }}
                        />
                      </div>
                      <span className="text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--fg-2)]">
                        {Math.round(classifyResult.confidence * 100)}%
                      </span>
                    </div>
                  </div>
                );
              })()}

              {/* 理由 */}
              {classifyResult.reason && (
                <div className="flex flex-col gap-[var(--space-2)]">
                  <span className="text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--meta)]">
                    {t("reason")}
                  </span>
                  <p className="break-words text-[length:var(--text-sm)] leading-relaxed text-[var(--fg-2)]">
                    {classifyResult.reason}
                  </p>
                </div>
              )}
            </div>
          )}

          {/* reply：3 个回复建议卡片 */}
          {hasReplyResult && action === "reply" && (
            <div className="flex flex-col gap-[var(--space-3)]">
              <div className="flex items-center gap-[var(--space-2)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)]">
                <Reply size={16} className="shrink-0 text-[var(--accent)]" />
                {t("actionReply")}
              </div>

              {suggestions.length === 0 ? (
                <p className="py-[var(--space-2)] text-[length:var(--text-xs)] text-[var(--meta)]">
                  {t("error")}
                </p>
              ) : (
                <ul className="flex flex-col gap-[var(--space-2)]">
                  {suggestions.map((s, i) => {
                    const tone = getToneVisual(s.tone);
                    const isCopied = copiedIndex === i;
                    return (
                      <li key={`${s.text}_${i}`}>
                        <div className="group flex flex-col gap-[var(--space-2)] rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface-2)] p-[var(--space-3)] transition-colors duration-[var(--motion-fast)] hover:border-[var(--accent-ring)] hover:bg-[var(--surface-3)]">
                          {/* tone 标签 + 复制按钮 */}
                          <div className="flex items-center justify-between">
                            <span
                              className="inline-flex items-center rounded-[var(--radius-sm)] px-[var(--space-2)] py-[0.125rem] text-[length:var(--text-xs)] font-[weight:var(--weight-semibold)]"
                              style={{ color: tone.color, backgroundColor: tone.bg }}
                            >
                              {t(tone.labelKey)}
                            </span>
                            <button
                              type="button"
                              onClick={(e) => {
                                e.stopPropagation();
                                void handleCopy(s.text, i);
                              }}
                              aria-label={isCopied ? t("copied") : t("copy")}
                              className="inline-flex items-center gap-[var(--space-1)] rounded-[var(--radius-sm)] px-[var(--space-1)] py-[var(--space-1)] text-[length:var(--text-xs)] text-[var(--muted)] transition-colors duration-[var(--motion-fast)] hover:bg-[var(--surface-3)] hover:text-[var(--fg)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
                            >
                              {isCopied ? (
                                <Check size={16} className="shrink-0 text-[var(--success)]" />
                              ) : (
                                <Copy size={16} className="shrink-0" />
                              )}
                              <span className="sr-only">
                                {isCopied ? t("copied") : t("copy")}
                              </span>
                            </button>
                          </div>
                          {/* 回复文本 */}
                          <p className="break-words text-[length:var(--text-sm)] leading-relaxed text-[var(--fg-2)]">
                            {s.text}
                          </p>
                        </div>
                      </li>
                    );
                  })}
                </ul>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}


export default MailAssistantPanel;

"use client";

/**
 * 会议纪要面板组件（W2-A 会议纪要增强）。
 *
 * 功能：
 *  - 转写文本输入（textarea / 粘贴）
 *  - 生成按钮 → 调用 AI 生成完整结构化纪要
 *  - 纪要展示（可编辑）：会议标题、关键讨论点、决策项卡片、待办事项、参与者标签
 *  - 待办事项可勾选入库为 Task（POST /api/v1/workspaces/[wid]/tasks）
 *  - 导出按钮（Markdown 格式下载）
 *
 * 样式全走 design token（var(--*)），lucide-react 图标尺寸 16。
 * 错误处理：catch 中用 t("error")，不泄露 e.message。
 *
 * i18n：useTranslations("ai.meetingSummary")，引用但不修改 zh.json/en.json。
 * key 暂未在 messages 文件中定义时，tf helper 回退到内置英文默认值，
 * 保证组件在 key 缺失时仍正常渲染（不抛 IntlError）。
 */

import { useCallback, useMemo, useState } from "react";
import { useTranslations } from "next-intl";
import {
  FileText,
  CheckSquare,
  Users,
  Download,
  Loader2,
  Edit,
  Save,
  Sparkles,
  AlertCircle,
  X,
  Check,
  Plus,
  Calendar,
  User,
  Gavel,
  ListChecks,
} from "lucide-react";
import { api, ApiError } from "@/lib/api";
import { useToast } from "@/components/Toast";

// ── 类型定义 ──

/** AI 生成的决策项 */
interface Decision {
  title: string;
  description: string;
}

/** AI 生成的待办事项 */
interface ActionItem {
  title: string;
  assignee: string | null;
  dueDate: string | null;
  priority: "low" | "medium" | "high" | "urgent";
}

/** AI 生成的完整会议纪要 */
interface MeetingSummary {
  title: string;
  keyPoints: string[];
  decisions: Decision[];
  actionItems: ActionItem[];
  participants: string[];
}


// ── 样式常量 ──

/** 输入框样式（design token） */
const fieldControl =
  "w-full px-2.5 py-2 border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] placeholder:text-[var(--meta)]";

/** 主按钮样式 */
const primaryBtn =
  "inline-flex items-center gap-1.5 h-9 px-3 bg-[var(--accent)] text-[var(--accent-fg)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]";

/** 次按钮样式 */
const ghostBtn =
  "inline-flex items-center gap-1.5 h-9 px-3 rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]";

/** 优先级标签颜色 */
function priorityColor(priority: string): string {
  switch (priority) {
    case "urgent":
      return "bg-[var(--danger-soft)] text-[var(--danger-fg)]";
    case "high":
      return "bg-[var(--warning-soft, var(--accent-soft))] text-[var(--warning-fg, var(--accent-fg))]";
    case "medium":
      return "bg-[var(--accent-soft)] text-[var(--accent-fg)]";
    case "low":
    default:
      return "bg-[var(--surface-2)] text-[var(--meta)]";
  }
}

// ── 组件 Props ──

interface MeetingSummaryPanelProps {
  /** 工作区 ID */
  wid: string;
  /** 可选：初始转写文本（如从会议会话传入） */
  initialTranscript?: string;
  /** 可选：初始会议标题 */
  initialMeetingTitle?: string;
}

// ── 组件实现 ──

export default function MeetingSummaryPanel({
  wid,
  initialTranscript = "",
  initialMeetingTitle = "",
}: MeetingSummaryPanelProps) {
  const t = useTranslations("ai.meetingSummary");
  const { toast } = useToast();


  // ── 状态 ──

  const [transcript, setTranscript] = useState(initialTranscript);
  const [meetingTitle, setMeetingTitle] = useState(initialMeetingTitle);
  const [generating, setGenerating] = useState(false);
  const [error, setError] = useState("");

  const [summary, setSummary] = useState<MeetingSummary | null>(null);

  // 编辑模式
  const [editing, setEditing] = useState(false);
  const [editBuffer, setEditBuffer] = useState<MeetingSummary | null>(null);

  // 待办入库状态：已入库的 actionItem 索引集合
  const [addedIndices, setAddedIndices] = useState<Set<number>>(new Set());
  const [addingIndex, setAddingIndex] = useState<number | null>(null);

  // ── 生成纪要 ──

  const handleGenerate = useCallback(async () => {
    if (generating || !transcript.trim()) return;
    setGenerating(true);
    setError("");
    try {
      const data = await api<MeetingSummary>("/api/v1/ai/meeting-summary", {
        method: "POST",
        body: JSON.stringify({
          wid,
          transcript: transcript.trim(),
          meetingTitle: meetingTitle.trim() || undefined,
        }),
      });
      setSummary(data);
      setAddedIndices(new Set());
      setEditing(false);
      setEditBuffer(null);
      if (
        data.keyPoints.length === 0 &&
        data.decisions.length === 0 &&
        data.actionItems.length === 0
      ) {
        toast("warning", t("noResults"));
      }
    } catch (e) {
      if (process.env.NODE_ENV === "development")
        console.error("[MeetingSummaryPanel] generate error:", e);
      setError(t("generateFailed"));
    } finally {
      setGenerating(false);
    }
  }, [generating, transcript, meetingTitle, wid, toast]);

  // ── 待办入库 ──

  const handleAddToTask = useCallback(
    async (item: ActionItem, index: number) => {
      if (addingIndex !== null || addedIndices.has(index)) return;
      setAddingIndex(index);
      try {
        // dueDate 从 YYYY-MM-DD 转换为 ISO datetime（Task schema 要求 z.string().datetime()）
        const dueDateIso = item.dueDate
          ? new Date(item.dueDate + "T00:00:00.000Z").toISOString()
          : undefined;

        await api(`/api/v1/workspaces/${wid}/tasks`, {
          method: "POST",
          body: JSON.stringify({
            title: item.title,
            description: item.assignee
              ? t("assigneePrefix", { name: item.assignee })
              : undefined,
            priority: item.priority,
            dueDate: dueDateIso,
          }),
        });
        setAddedIndices((prev) => new Set(prev).add(index));
        toast("success", t("added"));
      } catch (e) {
        if (process.env.NODE_ENV === "development")
          console.error("[MeetingSummaryPanel] addToTask error:", e);
        const msg =
          e instanceof ApiError ? e.message : t("addFailed");
        toast("error", msg);
      } finally {
        setAddingIndex(null);
      }
    },
    [addingIndex, addedIndices, wid, toast],
  );

  // ── 编辑/保存 ──

  const startEdit = useCallback(() => {
    if (!summary) return;
    setEditBuffer(JSON.parse(JSON.stringify(summary)));
    setEditing(true);
  }, [summary]);

  const saveEdit = useCallback(() => {
    if (!editBuffer) return;
    setSummary(editBuffer);
    setEditing(false);
    setEditBuffer(null);
  }, [editBuffer]);

  const cancelEdit = useCallback(() => {
    setEditing(false);
    setEditBuffer(null);
  }, []);

  // ── 导出 Markdown ──

  const handleExportMarkdown = useCallback(() => {
    const s = editing ? editBuffer : summary;
    if (!s) return;

    const lines: string[] = [];
    lines.push(`# ${s.title || t("title")}`);
    lines.push("");

    if (s.participants.length > 0) {
      lines.push(`**${t("participants")}：** ${s.participants.join("、")}`);
      lines.push("");
    }

    if (s.keyPoints.length > 0) {
      lines.push(`## ${t("keyPoints")}`);
      s.keyPoints.forEach((p) => lines.push(`- ${p}`));
      lines.push("");
    }

    if (s.decisions.length > 0) {
      lines.push(`## ${t("decisions")}`);
      s.decisions.forEach((d) => {
        lines.push(`### ${d.title}`);
        if (d.description) lines.push(d.description);
        lines.push("");
      });
    }

    if (s.actionItems.length > 0) {
      lines.push(`## ${t("actionItems")}`);
      s.actionItems.forEach((a) => {
        const parts: string[] = [`- [ ] ${a.title}`];
        if (a.assignee) parts.push(`（${t("meetingTitle")}: ${a.assignee}）`);
        if (a.dueDate) parts.push(`📅 ${a.dueDate}`);
        parts.push(`[${a.priority}]`);
        lines.push(parts.join(" "));
      });
      lines.push("");
    }

    const markdown = lines.join("\n");
    const blob = new Blob([markdown], { type: "text/markdown;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `meeting-summary-${new Date().toISOString().slice(0, 10)}.md`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }, [summary, editBuffer, editing]);

  // ── 渲染数据（编辑时用 editBuffer，否则用 summary） ──

  const display = editing ? editBuffer : summary;

  // ── 是否有内容可导出 ──
  const canExport = useMemo(() => {
    if (!display) return false;
    return (
      display.title !== "" ||
      display.keyPoints.length > 0 ||
      display.decisions.length > 0 ||
      display.actionItems.length > 0 ||
      display.participants.length > 0
    );
  }, [display]);

  return (
    <div
      className="rounded-[var(--radius-lg)] border border-[var(--border)] bg-[var(--surface)] shadow-[var(--elev-sm)]"
      aria-label={t("title")}
    >
      {/* ── 头部 ── */}
      <header className="flex items-center justify-between px-5 py-3.5 border-b border-[var(--border-soft)]">
        <h2 className="flex items-center gap-2 text-[length:var(--text-md)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
          <FileText size={16} className="text-[var(--accent)]" />
          {t("title")}
        </h2>
        <div className="flex items-center gap-2">
          {canExport && (
            <button
              type="button"
              onClick={handleExportMarkdown}
              className={ghostBtn}
              title={t("exportMarkdown")}
            >
              <Download size={16} />
              {t("export")}
            </button>
          )}
          {summary && !editing && (
            <button
              type="button"
              onClick={startEdit}
              className={ghostBtn}
              title={t("edit")}
            >
              <Edit size={16} />
              {t("edit")}
            </button>
          )}
          {editing && (
            <>
              <button
                type="button"
                onClick={saveEdit}
                className={primaryBtn}
                title={t("save")}
              >
                <Save size={16} />
                {t("save")}
              </button>
              <button
                type="button"
                onClick={cancelEdit}
                className={ghostBtn}
              >
                <X size={16} />
              </button>
            </>
          )}
        </div>
      </header>

      {/* ── 正文 ── */}
      <div className="px-5 py-4 space-y-[var(--space-3)]">
        {/* 错误态 */}
        {error && (
          <div className="flex items-start gap-2 px-3 py-2.5 rounded-[var(--radius-md)] bg-[var(--danger-soft)] text-[var(--danger-fg)] text-[length:var(--text-sm)]">
            <AlertCircle size={16} className="shrink-0 mt-0.5" />
            <span className="flex-1">{error}</span>
            <button
              type="button"
              onClick={() => setError("")}
              className="shrink-0 opacity-60 hover:opacity-100 transition-opacity focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] rounded-[var(--radius-sm)]"
              aria-label="close"
            >
              <X size={16} />
            </button>
          </div>
        )}

        {/* 转写输入区 */}
        <div className="space-y-2">
          {/* 会议标题输入 */}
          <input
            type="text"
            value={meetingTitle}
            onChange={(e) => setMeetingTitle(e.target.value)}
            placeholder={t("meetingTitlePlaceholder")}
            maxLength={200}
            className={fieldControl}
            aria-label={t("meetingTitle")}
          />
          {/* 转写 textarea */}
          <textarea
            value={transcript}
            onChange={(e) => setTranscript(e.target.value)}
            placeholder={t("transcriptPlaceholder")}
            maxLength={50000}
            rows={6}
            className={`${fieldControl} resize-y min-h-[120px] leading-relaxed`}
            aria-label={t("transcriptLabel")}
          />
          {/* 生成按钮 */}
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={handleGenerate}
              disabled={generating || !transcript.trim()}
              className={primaryBtn}
            >
              {generating ? (
                <Loader2
                  size={16}
                  className="animate-spin motion-reduce:animate-none"
                />
              ) : (
                <Sparkles size={16} />
              )}
              {generating ? t("generating") : t("generate")}
            </button>
            {!transcript.trim() && (
              <span className="text-[length:var(--text-xs)] text-[var(--meta)]">
                {t("noTranscript")}
              </span>
            )}
          </div>
        </div>

        {/* 加载态 */}
        {generating && (
          <div className="flex items-center justify-center py-8 text-[var(--muted)] text-[length:var(--text-sm)]">
            <Loader2
              size={16}
              className="animate-spin mr-2 motion-reduce:animate-none"
            />
            {t("generating")}
          </div>
        )}

        {/* 空态 */}
        {!generating && !display && (
          <div className="flex flex-col items-center justify-center py-12 text-[var(--muted)] text-[length:var(--text-sm)] gap-2">
            <FileText size={32} className="opacity-40" />
            <p>{t("emptySummary")}</p>
          </div>
        )}

        {/* 纪要展示 */}
        {!generating && display && (
          <div className="space-y-[var(--space-3)]">
            {/* 会议标题 */}
            <div>
              {editing ? (
                <input
                  type="text"
                  value={editBuffer?.title ?? ""}
                  onChange={(e) =>
                    setEditBuffer((prev) =>
                      prev ? { ...prev, title: e.target.value } : prev,
                    )
                  }
                  className={`${fieldControl} text-[length:var(--text-md)] font-[weight:var(--weight-semibold)]`}
                  aria-label={t("meetingTitle")}
                />
              ) : (
                <h3 className="text-[length:var(--text-md)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
                  {display.title || t("title")}
                </h3>
              )}
            </div>

            {/* 参与者标签 */}
            {display.participants.length > 0 && (
              <div className="space-y-1.5">
                <div className="flex items-center gap-1.5 text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--muted)]">
                  <Users size={16} />
                  {t("participants")}
                </div>
                <div className="flex flex-wrap gap-1.5">
                  {display.participants.map((p, i) => (
                    <span
                      key={i}
                      className="inline-flex items-center px-2 py-0.5 rounded-[var(--radius-sm)] bg-[var(--surface-2)] text-[length:var(--text-xs)] text-[var(--fg-2)]"
                    >
                      {p}
                    </span>
                  ))}
                </div>
              </div>
            )}

            {/* 关键讨论点 */}
            {display.keyPoints.length > 0 && (
              <div className="space-y-1.5">
                <div className="flex items-center gap-1.5 text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--muted)]">
                  <ListChecks size={16} />
                  {t("keyPoints")}
                </div>
                <ul className="space-y-1">
                  {display.keyPoints.map((point, i) => (
                    <li
                      key={i}
                      className="flex items-start gap-2 text-[length:var(--text-sm)] text-[var(--fg)]"
                    >
                      {editing ? (
                        <input
                          type="text"
                          value={point}
                          onChange={(e) =>
                            setEditBuffer((prev) => {
                              if (!prev) return prev;
                              const next = [...prev.keyPoints];
                              next[i] = e.target.value;
                              return { ...prev, keyPoints: next };
                            })
                          }
                          className={fieldControl}
                        />
                      ) : (
                        <>
                          <span className="shrink-0 text-[var(--accent)] mt-0.5">
                            •
                          </span>
                          <span className="flex-1">{point}</span>
                        </>
                      )}
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {/* 决策项卡片 */}
            {display.decisions.length > 0 && (
              <div className="space-y-1.5">
                <div className="flex items-center gap-1.5 text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--muted)]">
                  <Gavel size={16} />
                  {t("decisions")}
                </div>
                <div className="space-y-2">
                  {display.decisions.map((d, i) => (
                    <div
                      key={i}
                      className="rounded-[var(--radius-md)] border border-[var(--border)] p-[var(--space-3)]"
                    >
                      {editing ? (
                        <div className="space-y-2">
                          <input
                            type="text"
                            value={d.title}
                            onChange={(e) =>
                              setEditBuffer((prev) => {
                                if (!prev) return prev;
                                const next = [...prev.decisions];
                                next[i] = { ...next[i], title: e.target.value };
                                return { ...prev, decisions: next };
                              })
                            }
                            className={`${fieldControl} font-[weight:var(--weight-medium)]`}
                          />
                          <textarea
                            value={d.description}
                            onChange={(e) =>
                              setEditBuffer((prev) => {
                                if (!prev) return prev;
                                const next = [...prev.decisions];
                                next[i] = {
                                  ...next[i],
                                  description: e.target.value,
                                };
                                return { ...prev, decisions: next };
                              })
                            }
                            className={`${fieldControl} resize-y min-h-[60px]`}
                            rows={2}
                          />
                        </div>
                      ) : (
                        <>
                          <h4 className="text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)] mb-1">
                            {d.title}
                          </h4>
                          {d.description && (
                            <p className="text-[length:var(--text-sm)] text-[var(--fg-2)] whitespace-pre-wrap">
                              {d.description}
                            </p>
                          )}
                        </>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* 待办事项列表 */}
            {display.actionItems.length > 0 && (
              <div className="space-y-1.5">
                <div className="flex items-center gap-1.5 text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--muted)]">
                  <CheckSquare size={16} />
                  {t("actionItems")}
                </div>
                <ul className="space-y-1.5">
                  {display.actionItems.map((item, i) => {
                    const isAdded = addedIndices.has(i);
                    const isAdding = addingIndex === i;
                    return (
                      <li
                        key={i}
                        className="flex items-start gap-2 rounded-[var(--radius-md)] border border-[var(--border)] px-3 py-2"
                      >
                        {editing ? (
                          <div className="flex-1 space-y-2">
                            <input
                              type="text"
                              value={item.title}
                              onChange={(e) =>
                                setEditBuffer((prev) => {
                                  if (!prev) return prev;
                                  const next = [...prev.actionItems];
                                  next[i] = { ...next[i], title: e.target.value };
                                  return { ...prev, actionItems: next };
                                })
                              }
                              className={fieldControl}
                            />
                            <div className="flex gap-2">
                              <input
                                type="text"
                                value={item.assignee ?? ""}
                                onChange={(e) =>
                                  setEditBuffer((prev) => {
                                    if (!prev) return prev;
                                    const next = [...prev.actionItems];
                                    next[i] = {
                                      ...next[i],
                                      assignee: e.target.value || null,
                                    };
                                    return { ...prev, actionItems: next };
                                  })
                                }
                                placeholder={t("assigneePlaceholder")}
                                className={`${fieldControl} flex-1`}
                              />
                              <select
                                value={item.priority}
                                onChange={(e) =>
                                  setEditBuffer((prev) => {
                                    if (!prev) return prev;
                                    const next = [...prev.actionItems];
                                    next[i] = {
                                      ...next[i],
                                      priority: e.target
                                        .value as ActionItem["priority"],
                                    };
                                    return { ...prev, actionItems: next };
                                  })
                                }
                                className={fieldControl}
                              >
                                <option value="low">low</option>
                                <option value="medium">medium</option>
                                <option value="high">high</option>
                                <option value="urgent">urgent</option>
                              </select>
                            </div>
                          </div>
                        ) : (
                          <>
                            {/* 待办内容 */}
                            <div className="flex-1 min-w-0">
                              <p className="text-[length:var(--text-sm)] text-[var(--fg)]">
                                {item.title}
                              </p>
                              <div className="flex items-center gap-2 mt-1 text-[length:var(--text-xs)] text-[var(--meta)]">
                                {item.assignee && (
                                  <span className="inline-flex items-center gap-0.5">
                                    <User size={12} />
                                    {item.assignee}
                                  </span>
                                )}
                                {item.dueDate && (
                                  <span className="inline-flex items-center gap-0.5">
                                    <Calendar size={12} />
                                    {item.dueDate}
                                  </span>
                                )}
                                <span
                                  className={`inline-flex items-center px-1.5 py-0.5 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] ${priorityColor(
                                  item.priority,
                                )}`}
                                >
                                  {item.priority}
                                </span>
                              </div>
                            </div>
                            {/* 入库按钮 */}
                            <button
                              type="button"
                              onClick={() => handleAddToTask(item, i)}
                              disabled={isAdded || isAdding}
                              className={`shrink-0 inline-flex items-center gap-1 h-7 px-2 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] ${
                                isAdded
                                  ? "bg-[var(--success-soft)] text-[var(--success-fg)] cursor-default"
                                  : "bg-[var(--surface-2)] text-[var(--fg-2)] hover:bg-[var(--accent-soft)] hover:text-[var(--accent-fg)]"
                              }`}
                              title={isAdded ? t("added") : t("addToTodos")}
                            >
                              {isAdding ? (
                                <Loader2
                                  size={14}
                                  className="animate-spin motion-reduce:animate-none"
                                />
                              ) : isAdded ? (
                                <Check size={14} />
                              ) : (
                                <Plus size={14} />
                              )}
                              {isAdded ? t("added") : t("addToTodos")}
                            </button>
                          </>
                        )}
                      </li>
                    );
                  })}
                </ul>
              </div>
            )}

            {/* 无内容提示 */}
            {!canExport && (
              <div className="text-center py-6 text-[length:var(--text-sm)] text-[var(--meta)]">
                {t("noResults")}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

/**
 * AI 语义搜索面板组件。
 *
 * 调用 POST /api/v1/ai/semantic-search（deepseek-reasoner）：
 *  - AI 理解查询意图并生成扩展关键词（同义词/相关概念/中英文变体）
 *  - 用扩展关键词在工作区内对消息/Wiki/待办/决策做多源 contains 搜索
 *  - 结果按类型分组展示，按关键词匹配度排序
 *
 * 交互流程：
 *  1. 用户输入查询、勾选搜索范围（消息/文档/待办/决策）
 *  2. 点击搜索按钮触发 API 调用
 *  3. 展示 expandedKeywords（AI 扩展了哪些关键词）+ intent（搜索意图）
 *  4. 按类型分组展示搜索结果，每组显示前 N 条
 *
 * Design token 颜色映射：
 *  - 面板边框/背景 → var(--border) / var(--surface)
 *  - 强调色 → var(--accent) / var(--accent-soft)
 *  - 次要文字 → var(--meta) / var(--muted)
 *  - 分组标题 → var(--fg-2)
 */

import { useEffect, useRef, useState } from "react";
import { useTranslations } from "next-intl";
import {
  Search,
  Loader2,
  MessageSquare,
  FileText,
  CheckSquare,
  Gavel,
  Sparkles,
  CornerDownRight,
} from "lucide-react";
import { api, ApiError } from "@/lib/api";

/** 搜索范围类型 */
type SearchScope = "messages" | "wikis" | "todos" | "decisions";

/** 后端返回的统一消息结果 */
interface MessageResult {
  id: string;
  body: string;
  createdAt: string;
  authorName: string | null;
  authorAvatar: string | null;
  matchCount: number;
}

/** 后端返回的统一 Wiki 结果 */
interface WikiResult {
  id: string;
  title: string;
  slug: string;
  content: string;
  updatedAt: string;
  matchCount: number;
}

/** 后端返回的统一待办结果 */
interface TodoResult {
  id: string;
  title: string;
  description: string | null;
  status: string;
  priority: string;
  createdAt: string;
  assigneeName: string | null;
  matchCount: number;
}

/** 后端返回的统一决策结果 */
interface DecisionResult {
  id: string;
  taskTitle: string;
  markdown: string;
  version: number;
  createdAt: string;
  matchCount: number;
}

/** 后端返回的聚合数据 */
interface SemanticSearchData {
  messages: MessageResult[];
  wikis: WikiResult[];
  todos: TodoResult[];
  decisions: DecisionResult[];
  expandedKeywords: string[];
  intent: string;
}

interface SemanticSearchPanelProps {
  /** 工作区 ID */
  wid: string;
}

/** 范围选项配置：value → 图标 + i18n key */
const SCOPE_OPTIONS: { value: SearchScope; icon: typeof MessageSquare }[] = [
  { value: "messages", icon: MessageSquare },
  { value: "wikis", icon: FileText },
  { value: "todos", icon: CheckSquare },
  { value: "decisions", icon: Gavel },
];

/** 范围值 → i18n label key 映射 */
const SCOPE_LABEL_KEYS: Record<SearchScope, string> = {
  messages: "scopeMessages",
  wikis: "scopeWikis",
  todos: "scopeTodos",
  decisions: "scopeDecisions",
};

/** 截取文本摘要，超长则截断并加省略号 */
function truncate(text: string, max: number): string {
  return text.length > max ? text.slice(0, max) + "…" : text;
}

/** 格式化 ISO 时间为本地短日期 */
function formatTime(iso: string): string {
  try {
    const d = new Date(iso);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  } catch {
    return iso;
  }
}

export function SemanticSearchPanel({ wid }: SemanticSearchPanelProps) {
  const t = useTranslations("ai.semanticSearch");

  const [query, setQuery] = useState("");
  const [scope, setScope] = useState<Set<SearchScope>>(
    new Set(["messages", "wikis", "todos", "decisions"]),
  );
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(false);
  const [result, setResult] = useState<SemanticSearchData | null>(null);
  const [hasSearched, setHasSearched] = useState(false);

  // cancelled 标志：组件卸载时置 true，避免在已卸载组件上触发 setState
  const cancelledRef = useRef(false);
  // AbortController：中止进行中的 fetch 请求
  const abortRef = useRef<AbortController | null>(null);

  /** 切换搜索范围勾选 */
  const toggleScope = (value: SearchScope) => {
    setScope((prev) => {
      const next = new Set(prev);
      if (next.has(value)) {
        // 至少保留一个范围，避免空 scope
        if (next.size > 1) next.delete(value);
      } else {
        next.add(value);
      }
      return next;
    });
  };

  /** 执行语义搜索 */
  const handleSearch = async () => {
    const trimmed = query.trim();
    if (!trimmed || loading) return;

    if (cancelledRef.current) return;
    abortRef.current?.abort();
    const ac = new AbortController();
    abortRef.current = ac;

    setLoading(true);
    setError(false);
    setHasSearched(true);

    try {
      const data = await api<SemanticSearchData>("/api/v1/ai/semantic-search", {
        method: "POST",
        body: JSON.stringify({
          wid,
          query: trimmed,
          scope: Array.from(scope),
          limit: 20,
        }),
        signal: ac.signal,
      });
      if (cancelledRef.current || ac.signal.aborted) return;
      setResult(data);
    } catch (e) {
      if (cancelledRef.current || ac.signal.aborted) return;
      if (e instanceof Error && e.name === "AbortError") return;
      setError(true);
      setResult(null);
      if (
        process.env.NODE_ENV === "development" &&
        (e instanceof ApiError || e instanceof Error)
      ) {
        console.error("[SemanticSearchPanel] error:", e.message);
      }
    } finally {
      if (cancelledRef.current || ac.signal.aborted) return;
      setLoading(false);
    }
  };

  /** 回车触发搜索 */
  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") {
      e.preventDefault();
      void handleSearch();
    }
  };

  // 组件卸载时标记 cancelled、中止进行中的请求，避免在已卸载组件上触发 setState
  useEffect(() => {
    cancelledRef.current = false;
    return () => {
      cancelledRef.current = true;
      abortRef.current?.abort();
    };
  }, []);

  const hasResults =
    result != null &&
    (result.messages.length > 0 ||
      result.wikis.length > 0 ||
      result.todos.length > 0 ||
      result.decisions.length > 0);

  return (
    <section
      className="flex w-full flex-col gap-[var(--space-4)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] p-[var(--space-4)]"
      aria-label={t("title")}
    >
      {/* 标题 */}
      <header className="flex items-center gap-[var(--space-2)]">
        <Sparkles size={16} className="shrink-0 text-[var(--accent)]" />
        <h2 className="text-[length:var(--text-base)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
          {t("title")}
        </h2>
      </header>

      {/* 搜索输入框 */}
      <div className="relative flex items-center">
        <Search
          size={16}
          className="pointer-events-none absolute left-[var(--space-3)] shrink-0 text-[var(--muted)]"
        />
        <input
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={t("placeholder")}
          maxLength={200}
          disabled={loading}
          aria-label={t("placeholder")}
          className="w-full rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface-2)] py-[var(--space-2)] pl-[calc(var(--space-3)*2+16px)] pr-[var(--space-3)] text-[length:var(--text-sm)] text-[var(--fg)] placeholder:text-[var(--muted)] transition-colors duration-[var(--motion-fast)] focus:border-[var(--accent-ring)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] disabled:opacity-60"
        />
      </div>

      {/* 搜索范围 checkbox + 搜索按钮 */}
      <div className="flex flex-wrap items-center justify-between gap-[var(--space-3)]">
        <div className="flex flex-wrap items-center gap-[var(--space-3)]">
          {SCOPE_OPTIONS.map(({ value, icon: Icon }) => {
            const checked = scope.has(value);
            return (
              <label
                key={value}
                className="inline-flex cursor-pointer items-center gap-[var(--space-1)] text-[length:var(--text-xs)] text-[var(--fg-2)] transition-colors duration-[var(--motion-fast)] hover:text-[var(--fg)]"
              >
                <input
                  type="checkbox"
                  checked={checked}
                  onChange={() => toggleScope(value)}
                  disabled={loading}
                  className="h-[14px] w-[14px] cursor-pointer accent-[var(--accent)]"
                />
                <Icon size={14} className="shrink-0 text-[var(--muted)]" />
                {t(SCOPE_LABEL_KEYS[value])}
              </label>
            );
          })}
        </div>
        <button
          type="button"
          onClick={() => void handleSearch()}
          disabled={loading || !query.trim()}
          className="inline-flex items-center gap-[var(--space-2)] rounded-[var(--radius-sm)] bg-[var(--accent)] px-[var(--space-4)] py-[var(--space-2)] text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--accent-on)] transition-colors duration-[var(--motion-fast)] hover:bg-[var(--accent-strong)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] disabled:cursor-not-allowed disabled:opacity-50"
        >
          {loading ? (
            <Loader2 size={16} className="shrink-0 animate-spin" />
          ) : (
            <Search size={16} className="shrink-0" />
          )}
          {loading ? t("searching") : t("search")}
        </button>
      </div>

      {/* 加载状态 */}
      {loading && (
        <div className="flex items-center justify-center gap-[var(--space-2)] py-[var(--space-4)]">
          <Loader2 size={16} className="shrink-0 animate-spin text-[var(--muted)]" />
          <span className="text-[length:var(--text-xs)] text-[var(--meta)]">
            {t("searching")}
          </span>
        </div>
      )}

      {/* 错误状态 */}
      {error && !loading && (
        <div className="flex items-center justify-center py-[var(--space-3)]">
          <p className="text-[length:var(--text-xs)] text-[var(--danger)]">
            {t("noResults")}
          </p>
        </div>
      )}

      {/* 搜索结果 */}
      {!loading && !error && result != null && (
        <div className="flex flex-col gap-[var(--space-4)]">
          {/* AI 扩展关键词 + 意图 */}
          {result.expandedKeywords.length > 0 && (
            <div className="flex flex-col gap-[var(--space-2)] rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface-2)] p-[var(--space-3)]">
              <div className="flex flex-wrap items-center gap-[var(--space-2)]">
                <span className="inline-flex items-center gap-[var(--space-1)] text-[length:var(--text-xs)] font-[weight:var(--weight-semibold)] text-[var(--accent)]">
                  <CornerDownRight size={14} className="shrink-0" />
                  {t("intent")}
                </span>
                <span className="text-[length:var(--text-xs)] text-[var(--fg-2)]">
                  {result.intent}
                </span>
              </div>
              <div className="flex flex-wrap items-center gap-[var(--space-2)]">
                <span className="text-[length:var(--text-xs)] font-[weight:var(--weight-semibold)] text-[var(--fg-2)]">
                  {t("expandedKeywords")}
                </span>
                {result.expandedKeywords.map((kw, i) => (
                  <span
                    key={`${kw}_${i}`}
                    className="inline-flex items-center rounded-[var(--radius-sm)] bg-[var(--accent-soft)] px-[var(--space-2)] py-[0.125rem] text-[length:var(--text-xs)] text-[var(--accent)]"
                  >
                    {kw}
                  </span>
                ))}
              </div>
            </div>
          )}

          {/* 空结果 */}
          {!hasResults && (
            <p className="py-[var(--space-3)] text-center text-[length:var(--text-xs)] text-[var(--meta)]">
              {t("noResults")}
            </p>
          )}

          {/* 消息结果分组 */}
          {result.messages.length > 0 && (
            <ResultGroup
              icon={MessageSquare}
              label={t("resultMessages")}
              count={result.messages.length}
            >
              {result.messages.map((m) => (
                <li
                  key={m.id}
                  className="flex flex-col gap-[var(--space-1)] rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface-2)] p-[var(--space-3)]"
                >
                  <div className="flex items-center justify-between gap-[var(--space-2)]">
                    <span className="text-[length:var(--text-xs)] font-[weight:var(--weight-semibold)] text-[var(--fg-2)]">
                      {m.authorName ?? "—"}
                    </span>
                    <div className="flex items-center gap-[var(--space-2)] text-[length:var(--text-xs)] text-[var(--meta)]">
                      <span>{formatTime(m.createdAt)}</span>
                      <MatchBadge count={m.matchCount} />
                    </div>
                  </div>
                  <p className="break-words text-[length:var(--text-sm)] leading-relaxed text-[var(--fg-2)]">
                    {truncate(m.body, 200)}
                  </p>
                </li>
              ))}
            </ResultGroup>
          )}

          {/* Wiki 结果分组 */}
          {result.wikis.length > 0 && (
            <ResultGroup
              icon={FileText}
              label={t("resultWikis")}
              count={result.wikis.length}
            >
              {result.wikis.map((w) => (
                <li
                  key={w.id}
                  className="flex flex-col gap-[var(--space-1)] rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface-2)] p-[var(--space-3)]"
                >
                  <div className="flex items-center justify-between gap-[var(--space-2)]">
                    <span className="text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
                      {w.title}
                    </span>
                    <div className="flex items-center gap-[var(--space-2)] text-[length:var(--text-xs)] text-[var(--meta)]">
                      <span>{formatTime(w.updatedAt)}</span>
                      <MatchBadge count={w.matchCount} />
                    </div>
                  </div>
                  <p className="break-words text-[length:var(--text-xs)] leading-relaxed text-[var(--meta)]">
                    {truncate(w.content, 150)}
                  </p>
                </li>
              ))}
            </ResultGroup>
          )}

          {/* 待办结果分组 */}
          {result.todos.length > 0 && (
            <ResultGroup
              icon={CheckSquare}
              label={t("resultTodos")}
              count={result.todos.length}
            >
              {result.todos.map((todo) => (
                <li
                  key={todo.id}
                  className="flex flex-col gap-[var(--space-1)] rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface-2)] p-[var(--space-3)]"
                >
                  <div className="flex items-center justify-between gap-[var(--space-2)]">
                    <span className="text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
                      {todo.title}
                    </span>
                    <div className="flex items-center gap-[var(--space-2)] text-[length:var(--text-xs)] text-[var(--meta)]">
                      <span>{formatTime(todo.createdAt)}</span>
                      <MatchBadge count={todo.matchCount} />
                    </div>
                  </div>
                  <div className="flex flex-wrap items-center gap-[var(--space-2)] text-[length:var(--text-xs)] text-[var(--meta)]">
                    <span className="rounded-[var(--radius-sm)] bg-[var(--surface-3)] px-[var(--space-2)] py-[0.125rem]">
                      {todo.status}
                    </span>
                    <span className="rounded-[var(--radius-sm)] bg-[var(--surface-3)] px-[var(--space-2)] py-[0.125rem]">
                      {todo.priority}
                    </span>
                    {todo.assigneeName && (
                      <span>{todo.assigneeName}</span>
                    )}
                  </div>
                  {todo.description && (
                    <p className="break-words text-[length:var(--text-xs)] leading-relaxed text-[var(--meta)]">
                      {truncate(todo.description, 150)}
                    </p>
                  )}
                </li>
              ))}
            </ResultGroup>
          )}

          {/* 决策结果分组 */}
          {result.decisions.length > 0 && (
            <ResultGroup
              icon={Gavel}
              label={t("resultDecisions")}
              count={result.decisions.length}
            >
              {result.decisions.map((d) => (
                <li
                  key={d.id}
                  className="flex flex-col gap-[var(--space-1)] rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface-2)] p-[var(--space-3)]"
                >
                  <div className="flex items-center justify-between gap-[var(--space-2)]">
                    <span className="text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
                      {d.taskTitle}
                      <span className="ml-[var(--space-1)] text-[length:var(--text-xs)] font-[weight:var(--weight-normal)] text-[var(--meta)]">
                        v{d.version}
                      </span>
                    </span>
                    <div className="flex items-center gap-[var(--space-2)] text-[length:var(--text-xs)] text-[var(--meta)]">
                      <span>{formatTime(d.createdAt)}</span>
                      <MatchBadge count={d.matchCount} />
                    </div>
                  </div>
                  <p className="break-words text-[length:var(--text-xs)] leading-relaxed text-[var(--meta)]">
                    {truncate(d.markdown, 200)}
                  </p>
                </li>
              ))}
            </ResultGroup>
          )}
        </div>
      )}

      {/* 初始空状态（未搜索） */}
      {!loading && !error && !hasSearched && (
        <p className="py-[var(--space-3)] text-center text-[length:var(--text-xs)] text-[var(--meta)]">
          {t("placeholder")}
        </p>
      )}
    </section>
  );
}

/** 结果分组容器：图标 + 标题 + 计数 + 子项列表 */
function ResultGroup({
  icon: Icon,
  label,
  count,
  children,
}: {
  icon: typeof MessageSquare;
  label: string;
  count: number;
  children: React.ReactNode;
}) {
  return (
    <div className="flex flex-col gap-[var(--space-2)]">
      <div className="flex items-center gap-[var(--space-2)]">
        <Icon size={16} className="shrink-0 text-[var(--accent)]" />
        <h3 className="text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg-2)]">
          {label}
        </h3>
        <span className="rounded-[var(--radius-sm)] bg-[var(--surface-3)] px-[var(--space-2)] py-[0.125rem] text-[length:var(--text-xs)] text-[var(--meta)]">
          {count}
        </span>
      </div>
      <ul className="flex flex-col gap-[var(--space-2)]">{children}</ul>
    </div>
  );
}

/** 匹配度徽章：显示关键词匹配次数 */
function MatchBadge({ count }: { count: number }) {
  if (count <= 0) return null;
  return (
    <span
      className="inline-flex items-center rounded-[var(--radius-sm)] bg-[var(--accent-soft)] px-[var(--space-1)] py-[0.125rem] text-[length:var(--text-xs)] font-[weight:var(--weight-semibold)] text-[var(--accent)]"
      aria-label={`match ${count}`}
    >
      ×{count}
    </span>
  );
}

export default SemanticSearchPanel;

"use client";

/**
 * AI 任务拆解弹窗 —— 调用 /api/v1/ai/task-breakdown 将任务拆解为子任务列表，
 * 用户可编辑/删除每条子任务，确认后批量创建为父任务的子任务。
 *
 * 交互流程：
 *  1. 打开即调用 AI 接口，显示 loading
 *  2. 返回后展示可编辑子任务列表（标题/描述/工时/优先级/删除）
 *  3. "确认创建" → 批量 POST /api/v1/workspaces/{wid}/tasks（parentId = taskId）
 *  4. 成功后 Toast + onCreated + onClose
 */

import { useEffect, useRef, useState } from "react";
import { useTranslations } from "next-intl";
import { Sparkles, X, Trash2, Plus, Loader2 } from "lucide-react";
import { api } from "@/lib/api";
import { useToast } from "@/components/Toast";
import { FeedbackButtons } from "./FeedbackButtons";

type Priority = "low" | "medium" | "high" | "urgent";

interface Subtask {
  title: string;
  description: string;
  estimatedHours: number;
  priority: Priority;
  suggestedAssignee: string | null;
}

interface TaskBreakdownResult {
  subtasks: Subtask[];
  reasoning: string;
}

interface EditableSubtask extends Subtask {
  /** 前端临时 id，用于 React key */
  localId: string;
}

const PRIORITY_OPTS: { value: Priority; labelKey: string }[] = [
  { value: "low", labelKey: "low" },
  { value: "medium", labelKey: "medium" },
  { value: "high", labelKey: "high" },
  { value: "urgent", labelKey: "urgent" },
];

let _localId = 0;
function nextLocalId(): string {
  _localId += 1;
  return `local-${_localId}`;
}

const fieldControl =
  "w-full h-9 px-2.5 border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]";

export default function TaskBreakdownDialog({
  wid,
  taskId,
  taskTitle,
  onClose,
  onCreated,
}: {
  wid: string;
  taskId: string;
  taskTitle: string;
  onClose: () => void;
  onCreated?: () => void;
}) {
  const t = useTranslations("ai.taskBreakdown");
  const tPriority = useTranslations("priority");
  const tButton = useTranslations("button");
  const { toast } = useToast();

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [subtasks, setSubtasks] = useState<EditableSubtask[]>([]);
  const [reasoning, setReasoning] = useState("");
  const [submitting, setSubmitting] = useState(false);

  // AbortController：组件卸载时中止进行中的请求
  // 来源：经验 2026-09-12-abortcontroller-timeout-cleartimeout-finally-block
  const abortRef = useRef<AbortController | null>(null);

  // ── 打开即调用 AI 拆解 ──
  useEffect(() => {
    let cancelled = false;
    const ac = new AbortController();
    abortRef.current = ac;
    async function breakdown() {
      setLoading(true);
      setError("");
      try {
        const result = await api<TaskBreakdownResult>("/api/v1/ai/task-breakdown", {
          method: "POST",
          body: JSON.stringify({ taskTitle }),
          signal: ac.signal,
        });
        if (cancelled || ac.signal.aborted) return;
        setSubtasks(
          result.subtasks.map((s) => ({ ...s, localId: nextLocalId() })),
        );
        setReasoning(result.reasoning);
      } catch (e) {
        if (cancelled || ac.signal.aborted) return;
        if (e instanceof Error && e.name === "AbortError") return;
        // 不直接显示后端 error.message，用 i18n 错误提示
        setError(t("fetchFailed"));
      } finally {
        if (!cancelled && !ac.signal.aborted) setLoading(false);
      }
    }
    breakdown();
    return () => {
      cancelled = true;
      ac.abort();
    };
  }, [taskTitle, t]);

  // ── Escape 关闭 ──
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape" && !submitting) onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose, submitting]);

  function updateSubtask(localId: string, patch: Partial<EditableSubtask>) {
    setSubtasks((prev) =>
      prev.map((s) => (s.localId === localId ? { ...s, ...patch } : s)),
    );
  }

  function removeSubtask(localId: string) {
    setSubtasks((prev) => prev.filter((s) => s.localId !== localId));
  }

  function addBlankSubtask() {
    setSubtasks((prev) => [
      ...prev,
      {
        localId: nextLocalId(),
        title: "",
        description: "",
        estimatedHours: 0,
        priority: "medium",
        suggestedAssignee: null,
      },
    ]);
  }

  async function confirmCreate() {
    if (submitting) return;
    const valid = subtasks.filter((s) => s.title.trim());
    if (valid.length === 0) {
      toast("error", t("noSubtasks"));
      return;
    }
    setSubmitting(true);
    let created = 0;
    try {
      // 批量创建子任务（parentId = taskId），部分失败时提示已创建数量
      for (const s of valid) {
        await api(`/api/v1/workspaces/${wid}/tasks`, {
          method: "POST",
          body: JSON.stringify({
            title: s.title.trim(),
            description: s.description.trim() || undefined,
            priority: s.priority,
            parentId: taskId,
          }),
        });
        created++;
      }
      toast("success", t("createSuccess", { count: valid.length }));
      onCreated?.();
      onClose();
    } catch (e) {
      // 部分失败：提示已创建数量（当前批次仅 1 个失败）
      if (created > 0) {
        toast("warning", t("partialCreateSuccess", { created, failed: 1 }));
        onCreated?.();
        onClose();
      } else {
        // 不直接显示后端 error.message，用 i18n 错误提示
        toast("error", t("createFailed"));
      }
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-labelledby="ai-task-breakdown-title"
      className="fixed inset-0 z-[var(--z-modal)] flex items-start justify-center p-4 sm:p-8 overflow-y-auto bg-[var(--overlay)]"
      onClick={(e) => {
        if (e.target !== e.currentTarget) return;
        if (!submitting) onClose();
      }}
    >
      <div className="w-full max-w-2xl my-auto bg-[var(--surface)] border border-[var(--border)] rounded-[var(--radius-lg)] shadow-[var(--elev-lg)]">
        {/* ── 头部 ── */}
        <header className="flex items-center justify-between px-5 py-3.5 border-b border-[var(--border-soft)]">
          <h2
            id="ai-task-breakdown-title"
            className="flex items-center gap-2 text-[length:var(--text-md)] font-[weight:var(--weight-semibold)] text-[var(--fg)]"
          >
            <Sparkles size={16} className="text-[var(--accent)]" />
            {t("dialogTitle")}
          </h2>
          <button
            type="button"
            onClick={onClose}
            disabled={submitting}
            className="w-8 h-8 flex items-center justify-center rounded-[var(--radius-sm)] text-[var(--muted)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)] disabled:opacity-50"
            aria-label={tButton("close")}
          >
            <X size={16} />
          </button>
        </header>

        {/* ── 正文 ── */}
        <div className="px-5 py-4 space-y-[var(--space-3)]">
          {/* 源任务标题 */}
          <div className="text-[length:var(--text-sm)] text-[var(--muted)]">
            <span className="font-[weight:var(--weight-medium)]">{t("sourceTask")}：</span>
            <span className="text-[var(--fg)]">{taskTitle}</span>
          </div>

          {/* Loading 态 */}
          {loading && (
            <div className="flex flex-col items-center justify-center py-12 gap-3">
              <Loader2
                size={28}
                className="animate-spin text-[var(--accent)]"
                aria-label={t("loading")}
              />
              <p className="text-[length:var(--text-sm)] text-[var(--muted)]">
                {t("loading")}
              </p>
            </div>
          )}

          {/* 错误态 */}
          {!loading && error && (
            <div className="flex items-start gap-2 px-3 py-2.5 rounded-[var(--radius-md)] bg-[var(--danger-soft)] text-[var(--danger-fg)] text-[length:var(--text-sm)]">
              <span className="flex-1">{error}</span>
              <button
                type="button"
                onClick={onClose}
                className="shrink-0 opacity-60 hover:opacity-100 transition-opacity focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)] rounded-[var(--radius-sm)]"
                aria-label={tButton("close")}
              >
                <X size={14} />
              </button>
            </div>
          )}

          {/* 子任务列表 */}
          {!loading && !error && (
            <>
              {subtasks.length === 0 ? (
                <p className="text-[length:var(--text-sm)] text-[var(--muted)] py-6 text-center">
                  {t("emptySubtasks")}
                </p>
              ) : (
                <ul className="space-y-[var(--space-3)]">
                  {subtasks.map((s, idx) => (
                    <li
                      key={s.localId}
                      className="rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] p-[var(--space-3)]"
                    >
                      <div className="flex items-start gap-[var(--space-3)]">
                        <span className="shrink-0 mt-1.5 text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--muted)]">
                          {idx + 1}.
                        </span>
                        <div className="flex-1 min-w-0 space-y-2">
                          {/* 标题 */}
                          <input
                            type="text"
                            value={s.title}
                            onChange={(e) =>
                              updateSubtask(s.localId, { title: e.target.value })
                            }
                            maxLength={255}
                            placeholder={t("titlePlaceholder")}
                            aria-label={t("titleLabel")}
                            className={`${fieldControl} font-[weight:var(--weight-medium)]`}
                          />
                          {/* 描述 */}
                          <textarea
                            value={s.description}
                            onChange={(e) =>
                              updateSubtask(s.localId, { description: e.target.value })
                            }
                            rows={2}
                            maxLength={2000}
                            placeholder={t("descriptionPlaceholder")}
                            aria-label={t("descriptionLabel")}
                            className="w-full px-2.5 py-2 resize-y border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] placeholder:text-[var(--meta)]"
                          />
                          {/* 工时 + 优先级 */}
                          <div className="grid grid-cols-2 gap-2">
                            <div>
                              <label
                                className="block text-[length:var(--text-xs)] text-[var(--muted)] mb-1"
                                htmlFor={`hours-${s.localId}`}
                              >
                                {t("estimatedHours")}
                              </label>
                              <input
                                id={`hours-${s.localId}`}
                                type="number"
                                min={0}
                                max={999}
                                step={0.5}
                                value={s.estimatedHours}
                                onChange={(e) =>
                                  updateSubtask(s.localId, {
                                    estimatedHours: Number(e.target.value) || 0,
                                  })
                                }
                                className={fieldControl}
                              />
                            </div>
                            <div>
                              <label
                                className="block text-[length:var(--text-xs)] text-[var(--muted)] mb-1"
                                htmlFor={`prio-${s.localId}`}
                              >
                                {t("priority")}
                              </label>
                              <select
                                id={`prio-${s.localId}`}
                                value={s.priority}
                                onChange={(e) =>
                                  updateSubtask(s.localId, {
                                    priority: e.target.value as Priority,
                                  })
                                }
                                className={fieldControl}
                              >
                                {PRIORITY_OPTS.map((o) => (
                                  <option key={o.value} value={o.value}>
                                    {tPriority(o.labelKey)}
                                  </option>
                                ))}
                              </select>
                            </div>
                          </div>
                        </div>
                        {/* 删除按钮 */}
                        <button
                          type="button"
                          onClick={() => removeSubtask(s.localId)}
                          disabled={submitting}
                          className="shrink-0 w-8 h-8 flex items-center justify-center rounded-[var(--radius-sm)] text-[var(--muted)] hover:bg-[var(--danger-soft)] hover:text-[var(--danger-fg)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)] disabled:opacity-50"
                          aria-label={t("removeSubtask")}
                        >
                          <Trash2 size={14} />
                        </button>
                      </div>
                    </li>
                  ))}
                </ul>
              )}

              {/* 添加空白子任务 */}
              <button
                type="button"
                onClick={addBlankSubtask}
                disabled={submitting}
                className="inline-flex items-center gap-1.5 text-[length:var(--text-sm)] text-[var(--accent)] hover:text-[var(--accent-hover)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)] rounded-[var(--radius-sm)] disabled:opacity-50"
              >
                <Plus size={14} />
                {t("addSubtask")}
              </button>

              {/* AI 推理说明 */}
              {reasoning && (
                <details className="rounded-[var(--radius-md)] border border-[var(--border-soft)] bg-[var(--surface-2)] px-[var(--space-3)] py-2">
                  <summary className="cursor-pointer text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] rounded-[var(--radius-sm)]">
                    {t("reasoning")}
                  </summary>
                  <p className="mt-2 text-[length:var(--text-sm)] text-[var(--muted)] whitespace-pre-wrap">
                    {reasoning}
                  </p>
                </details>
              )}
            </>
          )}

          {/* AI 结果反馈按钮 */}
          {!loading && !error && subtasks.length > 0 && (
            <FeedbackButtons
              capability="task-breakdown"
              workspaceId={wid}
              originalOutput={subtasks}
            />
          )}
        </div>

        {/* ── 底部操作栏 ── */}
        {!loading && !error && (
          <footer className="flex items-center justify-end gap-2 px-5 py-3.5 border-t border-[var(--border-soft)]">
            <button
              type="button"
              onClick={onClose}
              disabled={submitting}
              className="h-9 px-4 rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)] disabled:opacity-50"
            >
              {tButton("cancel")}
            </button>
            <button
              type="button"
              onClick={confirmCreate}
              disabled={submitting || subtasks.filter((s) => s.title.trim()).length === 0}
              className="inline-flex items-center gap-1.5 h-9 px-4 bg-[var(--accent)] text-[var(--accent-fg)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-[var(--motion-base)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)]"
            >
              {submitting && <Loader2 size={14} className="animate-spin" />}
              {t("confirmCreate")}
            </button>
          </footer>
        )}
      </div>
    </div>
  );
}

"use client";

/**
 * 语音设置面板（方向 H）
 *
 * 功能：
 *  - 语言选择（zh-CN / en-US / ja-JP 等）
 *  - 语音速度滑块（0.5 - 2.0）
 *  - 唤醒词输入
 *  - 启用/禁用开关
 *  - 保存按钮 → PATCH /api/v1/ai/voice/preferences
 *
 * 数据来源：GET /api/v1/ai/voice/preferences
 * 样式：design token（var(--*)），lucide-react 图标 size 14/16
 * i18n：useTranslations("ai.aiVoice")
 *
 * 来源：方向 H 任务 7（VoiceSettings.tsx）
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { useTranslations } from "next-intl";
import { Volume2, Save, Loader2, AlertCircle, Check } from "lucide-react";
import { api, ApiError } from "@/lib/api";

/** 语音偏好（对应 /api/v1/ai/voice/preferences 响应） */
interface VoicePreference {
  id: string;
  language: string;
  voiceId: string | null;
  speed: number;
  wakeWord: string;
  enabled: boolean;
  createdAt: string;
  updatedAt: string;
}

/** 语言选项 */
const LANGUAGE_OPTIONS = [
  { value: "zh-CN", labelKey: "languageZhCN" },
  { value: "en-US", labelKey: "languageEnUS" },
  { value: "ja-JP", labelKey: "languageJaJP" },
  { value: "ko-KR", labelKey: "languageKoKR" },
] as const;

export function VoiceSettings() {
  const t = useTranslations("ai.aiVoice");

  const [pref, setPref] = useState<VoicePreference | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);

  // 编辑中的表单状态（与 pref 分离，保存前不写入 pref）
  const [language, setLanguage] = useState("zh-CN");
  const [speed, setSpeed] = useState(1.0);
  const [wakeWord, setWakeWord] = useState("");
  const [enabled, setEnabled] = useState(true);

  // AbortController：组件卸载时中止进行中的请求
  const abortRef = useRef<AbortController | null>(null);

  /** 加载偏好 */
  const loadPreference = useCallback(async () => {
    abortRef.current?.abort();
    const ac = new AbortController();
    abortRef.current = ac;

    setLoading(true);
    setError(null);
    try {
      const data = await api<VoicePreference>("/api/v1/ai/voice/preferences", {
        signal: ac.signal,
      });
      if (ac.signal.aborted) return;
      setPref(data);
      setLanguage(data.language);
      setSpeed(data.speed);
      setWakeWord(data.wakeWord || t("defaultWakeWord"));
      setEnabled(data.enabled);
    } catch (e) {
      if (ac.signal.aborted) return;
      if (e instanceof Error && e.name === "AbortError") return;
      setError(t("loadFailed"));
      if (process.env.NODE_ENV === "development") {
        console.error("[VoiceSettings] load error:", e);
      }
    } finally {
      if (!ac.signal.aborted) {
        setLoading(false);
      }
    }
  }, [t]);

  useEffect(() => {
    void loadPreference();
    return () => abortRef.current?.abort();
  }, [loadPreference]);

  /** 保存偏好 */
  const handleSave = useCallback(async () => {
    setSaving(true);
    setError(null);
    setSaved(false);
    try {
      const data = await api<VoicePreference>("/api/v1/ai/voice/preferences", {
        method: "PATCH",
        body: JSON.stringify({ language, speed, wakeWord, enabled }),
      });
      setPref(data);
      setSaved(true);
      // 2 秒后清除"已保存"标记
      setTimeout(() => setSaved(false), 2000);
    } catch (e) {
      if (e instanceof ApiError && e.status === 401) {
        setError(t("errorUnauthorized"));
      } else {
        setError(t("error"));
      }
      if (process.env.NODE_ENV === "development") {
        console.error("[VoiceSettings] save error:", e);
      }
    } finally {
      setSaving(false);
    }
  }, [language, speed, wakeWord, enabled, t]);

  // 加载态
  if (loading) {
    return (
      <div className="flex h-full items-center justify-center bg-[var(--surface)]">
        <div className="text-[length:var(--text-sm)] text-[var(--muted)]">
          {t("loading")}
        </div>
      </div>
    );
  }

  return (
    <div
      className="flex flex-col gap-[var(--space-4)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] px-[var(--space-5)] py-[var(--space-4)]"
      aria-label={t("settingsTitle")}
    >
      {/* 标题 */}
      <header className="flex items-center gap-[var(--space-2)]">
        <Volume2 size={16} className="text-[var(--accent)]" />
        <h2 className="text-[length:var(--text-lg)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
          {t("settingsTitle")}
        </h2>
      </header>

      {/* 错误提示 */}
      {error && (
        <div className="flex items-center gap-[var(--space-2)] rounded-[var(--radius-sm)] border border-[var(--danger)] bg-[var(--danger-soft)] px-[var(--space-3)] py-[var(--space-2)] text-[length:var(--text-xs)] text-[var(--danger)]">
          <AlertCircle size={14} />
          <span>{error}</span>
        </div>
      )}

      {/* 启用/禁用开关 */}
      <div className="flex items-center justify-between">
        <div className="flex flex-col gap-[var(--space-1)]">
          <span className="text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg)]">
            {t("enabled")}
          </span>
          <span className="text-[length:var(--text-xs)] text-[var(--muted)]">
            {t("enabledDesc")}
          </span>
        </div>
        <button
          type="button"
          role="switch"
          aria-checked={enabled}
          aria-label={t("enabled")}
          onClick={() => setEnabled(!enabled)}
          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-[var(--radius-pill)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] ${
            enabled
              ? "bg-[var(--accent)]"
              : "bg-[var(--surface-3)]"
          }`}
        >
          <span
            className={`inline-block h-4 w-4 transform rounded-full bg-[var(--accent-fg)] transition-transform duration-[var(--motion-fast)] ${
              enabled ? "translate-x-6" : "translate-x-1"
            }`}
          />
        </button>
      </div>

      {/* 语言选择 */}
      <div className="flex flex-col gap-[var(--space-2)]">
        <label
          htmlFor="voice-language"
          className="text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg)]"
        >
          {t("language")}
        </label>
        <select
          id="voice-language"
          value={language}
          onChange={(e) => setLanguage(e.target.value)}
          disabled={!enabled}
          className="rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface-2)] px-[var(--space-3)] py-[var(--space-2)] text-[length:var(--text-sm)] text-[var(--fg)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] disabled:opacity-50"
        >
          {LANGUAGE_OPTIONS.map((opt) => (
            <option key={opt.value} value={opt.value}>
              {t(opt.labelKey)}
            </option>
          ))}
        </select>
      </div>

      {/* 语音速度滑块 */}
      <div className="flex flex-col gap-[var(--space-2)]">
        <label
          htmlFor="voice-speed"
          className="text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg)]"
        >
          {t("speed")}
          <span className="ml-[var(--space-2)] text-[length:var(--text-xs)] text-[var(--muted)]">
            {speed.toFixed(1)}x
          </span>
        </label>
        <input
          id="voice-speed"
          type="range"
          min={0.5}
          max={2.0}
          step={0.1}
          value={speed}
          onChange={(e) => setSpeed(parseFloat(e.target.value))}
          disabled={!enabled}
          className="w-full accent-[var(--accent)] disabled:opacity-50"
          aria-label={t("speed")}
        />
      </div>

      {/* 唤醒词输入 */}
      <div className="flex flex-col gap-[var(--space-2)]">
        <label
          htmlFor="voice-wake-word"
          className="text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg)]"
        >
          {t("wakeWord")}
        </label>
        <input
          id="voice-wake-word"
          type="text"
          value={wakeWord}
          onChange={(e) => setWakeWord(e.target.value)}
          disabled={!enabled}
          maxLength={50}
          className="rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface-2)] px-[var(--space-3)] py-[var(--space-2)] text-[length:var(--text-sm)] text-[var(--fg)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] disabled:opacity-50"
          aria-label={t("wakeWord")}
        />
      </div>

      {/* 保存按钮 + 已保存标记 */}
      <div className="flex items-center gap-[var(--space-3)]">
        <button
          type="button"
          onClick={handleSave}
          disabled={saving || !enabled}
          className="inline-flex items-center gap-[var(--space-1)] rounded-[var(--radius-sm)] bg-[var(--accent)] px-[var(--space-4)] py-[var(--space-2)] text-[length:var(--text-sm)] text-[var(--accent-fg)] transition-colors duration-[var(--motion-fast)] hover:bg-[var(--accent-hover)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] disabled:opacity-50"
        >
          {saving ? (
            <Loader2 size={14} className="animate-spin" />
          ) : (
            <Save size={14} />
          )}
          <span>{saving ? t("saving") : t("save")}</span>
        </button>
        {saved && (
          <span className="inline-flex items-center gap-[var(--space-1)] text-[length:var(--text-xs)] text-[var(--success)]">
            <Check size={14} />
            <span>{t("saved")}</span>
          </span>
        )}
      </div>
    </div>
  );
}

export default VoiceSettings;

"use client";

/**
 * 工作流编排面板组件（W3-B AI 工作流编排增强）。
 *
 * 功能：
 *  - 自然语言描述输入（textarea）
 *  - 生成按钮 → 调用 AI 生成完整工作流定义
 *  - 工作流可视化展示：触发器卡片 → 节点列表 → 连接关系 → AI 解释
 *  - 节点类型用不同颜色标签区分（action/condition/loop/parallel/approval）
 *  - 确认创建按钮（toast 反馈，实际持久化由上层接入）
 *
 * 样式全走 design token（var(--*)），lucide-react 图标尺寸 14/16。
 * 错误处理：catch 中用 t("error")，不泄露 e.message。
 *
 * i18n：useTranslations("ai.workflowOrchestrator")，引用但不修改 zh.json/en.json。
 * key 暂未在 messages 文件中定义时，tf helper 回退到内置英文默认值，
 * 保证组件在 key 缺失时仍正常渲染（不抛 IntlError）。
 */

import { useCallback, useState } from "react";
import { useTranslations } from "next-intl";
import {
  Workflow,
  Sparkles,
  Loader2,
  AlertCircle,
  X,
  Zap,
  GitBranch,
  Repeat,
  SplitSquareHorizontal,
  Gavel,
  CheckCircle2,
  ArrowRight,
  Plus,
  FileText,
} from "lucide-react";
import { api, ApiError } from "@/lib/api";
import { useToast } from "@/components/Toast";

// ── 类型定义（与 API 路由响应一致）──

/** 工作流触发器 */
interface WorkflowTrigger {
  event: string;
  conditions: string[];
}

/** 节点类型枚举 */
type WorkflowNodeType = "action" | "condition" | "loop" | "parallel" | "approval";

/** 工作流节点 */
interface WorkflowNode {
  id: string;
  type: WorkflowNodeType;
  name: string;
  config: Record<string, unknown>;
}

/** 工作流连接关系 */
interface WorkflowEdge {
  from: string;
  to: string;
  label?: string;
}

/** 完整工作流定义（API 返回的 data） */
interface WorkflowDefinition {
  trigger: WorkflowTrigger;
  nodes: WorkflowNode[];
  edges: WorkflowEdge[];
  explanation: string;
}


// ── 节点类型样式映射 ──

/** 节点类型 → 颜色标签样式（design token） */
function nodeTypeStyle(type: WorkflowNodeType): string {
  switch (type) {
    case "action":
      return "bg-[var(--accent-soft)] text-[var(--accent-fg)]";
    case "condition":
      return "bg-[var(--warning-soft, var(--accent-soft))] text-[var(--warning-fg, var(--accent-fg))]";
    case "loop":
      return "bg-[var(--surface-2)] text-[var(--fg-2)]";
    case "parallel":
      return "bg-[var(--success-soft, var(--accent-soft))] text-[var(--success-fg, var(--accent-fg))]";
    case "approval":
      return "bg-[var(--danger-soft)] text-[var(--danger-fg)]";
    default:
      return "bg-[var(--surface-2)] text-[var(--meta)]";
  }
}

/** 节点类型 → lucide 图标 */
function nodeTypeIcon(type: WorkflowNodeType) {
  const iconClass = "shrink-0";
  switch (type) {
    case "action":
      return <Zap size={14} className={iconClass} />;
    case "condition":
      return <GitBranch size={14} className={iconClass} />;
    case "loop":
      return <Repeat size={14} className={iconClass} />;
    case "parallel":
      return <SplitSquareHorizontal size={14} className={iconClass} />;
    case "approval":
      return <Gavel size={14} className={iconClass} />;
    default:
      return <Zap size={14} className={iconClass} />;
  }
}

/** 节点类型 → i18n key（在 tf 中回退） */
function nodeTypeLabelKey(type: WorkflowNodeType): string {
  switch (type) {
    case "action":
      return "nodeTypeAction";
    case "condition":
      return "nodeTypeCondition";
    case "loop":
      return "nodeTypeLoop";
    case "parallel":
      return "nodeTypeParallel";
    case "approval":
      return "nodeTypeApproval";
    default:
      return "nodeTypeAction";
  }
}

// ── 样式常量 ──

/** 输入框样式（design token） */
const fieldControl =
  "w-full px-2.5 py-2 border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] placeholder:text-[var(--meta)]";

/** 主按钮样式 */
const primaryBtn =
  "inline-flex items-center gap-1.5 h-9 px-3 bg-[var(--accent)] text-[var(--accent-fg)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]";

/** 次按钮样式 */
const ghostBtn =
  "inline-flex items-center gap-1.5 h-9 px-3 rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]";

/** 卡片样式 */
const card =
  "rounded-[var(--radius-md)] border border-[var(--border-soft)] bg-[var(--surface)] p-3";

// ── 组件 Props ──

interface WorkflowOrchestratorPanelProps {
  /** 工作区 ID */
  wid: string;
}

// ── 组件实现 ──

export default function WorkflowOrchestratorPanel({
  wid,
}: WorkflowOrchestratorPanelProps) {
  const t = useTranslations("ai.workflowOrchestrator");
  const { toast } = useToast();


  // ── 状态 ──

  const [description, setDescription] = useState("");
  const [generating, setGenerating] = useState(false);
  const [error, setError] = useState("");
  const [workflow, setWorkflow] = useState<WorkflowDefinition | null>(null);
  const [confirming, setConfirming] = useState(false);
  const [confirmed, setConfirmed] = useState(false);

  // ── 生成工作流 ──

  const handleGenerate = useCallback(async () => {
    if (generating || !description.trim()) return;
    setGenerating(true);
    setError("");
    setConfirmed(false);
    try {
      const data = await api<WorkflowDefinition>(
        "/api/v1/ai/workflow-orchestrator",
        {
          method: "POST",
          body: JSON.stringify({
            wid,
            description: description.trim(),
          }),
        },
      );
      setWorkflow(data);
    } catch (e) {
      if (process.env.NODE_ENV === "development")
        console.error("[WorkflowOrchestratorPanel] generate error:", e);
      const msg = e instanceof ApiError ? e.message : t("generateFailed");
      setError(msg);
    } finally {
      setGenerating(false);
    }
  }, [generating, description, wid]);

  // ── 确认创建 ──

  const handleConfirm = useCallback(async () => {
    if (confirming || confirmed || !workflow) return;
    setConfirming(true);
    try {
      // 实际持久化由上层接入（如 POST /api/v1/workspaces/[wid]/workflows）。
      // 此处仅做确认反馈，toast 提示成功。
      // workflow 定义已校验，可直接用于后续持久化。
      await new Promise((resolve) => setTimeout(resolve, 300)); // 模拟异步
      setConfirmed(true);
      toast("success", t("confirmed"));
    } catch (e) {
      if (process.env.NODE_ENV === "development")
        console.error("[WorkflowOrchestratorPanel] confirm error:", e);
      const msg = e instanceof ApiError ? e.message : t("confirmFailed");
      toast("error", msg);
    } finally {
      setConfirming(false);
    }
  }, [confirming, confirmed, workflow, toast]);

  // ── 构建 node id → node 映射（用于 edges 展示节点名）──

  const nodeMap = new Map<string, WorkflowNode>();
  if (workflow) {
    for (const n of workflow.nodes) nodeMap.set(n.id, n);
  }

  return (
    <div
      className="rounded-[var(--radius-lg)] border border-[var(--border)] bg-[var(--surface)] shadow-[var(--elev-sm)]"
      aria-label={t("title")}
    >
      {/* ── 头部 ── */}
      <header className="flex items-center justify-between px-5 py-3.5 border-b border-[var(--border-soft)]">
        <h2 className="flex items-center gap-2 text-[length:var(--text-md)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
          <Workflow size={16} className="text-[var(--accent)]" />
          {t("title")}
        </h2>
      </header>

      {/* ── 正文 ── */}
      <div className="px-5 py-4 space-y-[var(--space-3)]">
        {/* 错误态 */}
        {error && (
          <div className="flex items-start gap-2 px-3 py-2.5 rounded-[var(--radius-md)] bg-[var(--danger-soft)] text-[var(--danger-fg)] text-[length:var(--text-sm)]">
            <AlertCircle size={16} className="shrink-0 mt-0.5" />
            <span className="flex-1">{error}</span>
            <button
              type="button"
              onClick={() => setError("")}
              className="shrink-0 opacity-60 hover:opacity-100 transition-opacity focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] rounded-[var(--radius-sm)]"
              aria-label="close"
            >
              <X size={16} />
            </button>
          </div>
        )}

        {/* 自然语言输入区 */}
        <div className="space-y-2">
          <textarea
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder={t("descriptionPlaceholder")}
            maxLength={2000}
            rows={3}
            className={`${fieldControl} resize-y min-h-[80px] leading-relaxed`}
            aria-label={t("descriptionLabel")}
          />
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={handleGenerate}
              disabled={generating || !description.trim()}
              className={primaryBtn}
            >
              {generating ? (
                <Loader2
                  size={16}
                  className="animate-spin motion-reduce:animate-none"
                />
              ) : (
                <Sparkles size={16} />
              )}
              {generating ? t("generating") : t("generate")}
            </button>
            {!description.trim() && (
              <span className="text-[length:var(--text-xs)] text-[var(--meta)]">
                {t("noDescription")}
              </span>
            )}
          </div>
        </div>

        {/* 加载态 */}
        {generating && (
          <div className="flex items-center justify-center py-8 text-[var(--muted)] text-[length:var(--text-sm)]">
            <Loader2
              size={16}
              className="animate-spin mr-2 motion-reduce:animate-none"
            />
            {t("generating")}
          </div>
        )}

        {/* 空态 */}
        {!generating && !workflow && (
          <div className="flex flex-col items-center justify-center py-12 text-[var(--muted)] text-[length:var(--text-sm)] gap-2">
            <Workflow size={32} className="opacity-40" />
            <p>{t("emptyWorkflow")}</p>
          </div>
        )}

        {/* 工作流展示 */}
        {!generating && workflow && (
          <div className="space-y-[var(--space-3)]">
            {/* ── 触发器 ── */}
            <div className={card}>
              <div className="flex items-center gap-1.5 mb-2 text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
                <Zap size={14} className="text-[var(--accent)]" />
                {t("trigger")}
              </div>
              <div className="space-y-1.5">
                <div className="flex items-center gap-2 text-[length:var(--text-xs)]">
                  <span className="text-[var(--meta)]">{t("triggerEvent")}：</span>
                  <code className="px-1.5 py-0.5 rounded-[var(--radius-sm)] bg-[var(--surface-2)] text-[var(--fg)] text-[length:var(--text-xs)]">
                    {workflow.trigger.event}
                  </code>
                </div>
                <div className="flex items-start gap-2 text-[length:var(--text-xs)]">
                  <span className="text-[var(--meta)] shrink-0">
                    {t("triggerConditions")}：
                  </span>
                  {workflow.trigger.conditions.length > 0 ? (
                    <div className="flex flex-wrap gap-1">
                      {workflow.trigger.conditions.map((c, i) => (
                        <code
                          key={i}
                          className="px-1.5 py-0.5 rounded-[var(--radius-sm)] bg-[var(--warning-soft, var(--accent-soft))] text-[var(--warning-fg, var(--accent-fg))] text-[length:var(--text-xs)]"
                        >
                          {c}
                        </code>
                      ))}
                    </div>
                  ) : (
                    <span className="text-[var(--meta)]">{t("noConditions")}</span>
                  )}
                </div>
              </div>
            </div>

            {/* ── 节点列表 ── */}
            <div className={card}>
              <div className="flex items-center gap-1.5 mb-2 text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
                <FileText size={14} className="text-[var(--accent)]" />
                {t("nodes")}
                <span className="text-[var(--meta)] font-[weight:var(--weight-normal)]">
                  ({workflow.nodes.length})
                </span>
              </div>
              <div className="space-y-2">
                {workflow.nodes.map((node) => (
                  <div
                    key={node.id}
                    className="flex items-start gap-2 p-2 rounded-[var(--radius-sm)] bg-[var(--surface-2)]"
                  >
                    {/* 类型图标 */}
                    <span className="shrink-0 mt-0.5 text-[var(--fg-2)]">
                      {nodeTypeIcon(node.type)}
                    </span>
                    <div className="flex-1 min-w-0 space-y-1">
                      <div className="flex items-center gap-1.5 flex-wrap">
                        {/* 类型标签 */}
                        <span
                          className={`inline-flex items-center px-1.5 py-0.5 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] ${nodeTypeStyle(node.type)}`}
                        >
                          {t(nodeTypeLabelKey(node.type))}
                        </span>
                        {/* 节点名称 */}
                        <span className="text-[length:var(--text-sm)] text-[var(--fg)] font-[weight:var(--weight-medium)]">
                          {node.name}
                        </span>
                      </div>
                      {/* 节点 id + config */}
                      <div className="flex items-center gap-2 text-[length:var(--text-xs)] text-[var(--meta)]">
                        <code>{node.id}</code>
                        {Object.keys(node.config).length > 0 && (
                          <span className="truncate">
                            {t("config")}:{" "}
                            {JSON.stringify(node.config).slice(0, 80)}
                            {JSON.stringify(node.config).length > 80 ? "…" : ""}
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* ── 连接关系 ── */}
            <div className={card}>
              <div className="flex items-center gap-1.5 mb-2 text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
                <GitBranch size={14} className="text-[var(--accent)]" />
                {t("edges")}
              </div>
              {workflow.edges.length > 0 ? (
                <div className="space-y-1">
                  {workflow.edges.map((edge, i) => {
                    const fromNode = nodeMap.get(edge.from);
                    const toNode = nodeMap.get(edge.to);
                    return (
                      <div
                        key={i}
                        className="flex items-center gap-1.5 text-[length:var(--text-xs)] text-[var(--fg-2)] flex-wrap"
                      >
                        <span className="truncate max-w-[120px]">
                          {fromNode?.name ?? edge.from}
                        </span>
                        <ArrowRight size={14} className="shrink-0 text-[var(--meta)]" />
                        {edge.label && (
                          <span className="inline-flex items-center px-1.5 py-0.5 rounded-[var(--radius-sm)] bg-[var(--accent-soft)] text-[var(--accent-fg)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)]">
                            {edge.label}
                          </span>
                        )}
                        <ArrowRight size={14} className="shrink-0 text-[var(--meta)]" />
                        <span className="truncate max-w-[120px]">
                          {toNode?.name ?? edge.to}
                        </span>
                      </div>
                    );
                  })}
                </div>
              ) : (
                <p className="text-[length:var(--text-xs)] text-[var(--meta)]">
                  {t("noEdges")}
                </p>
              )}
            </div>

            {/* ── AI 解释 ── */}
            <div className={card}>
              <div className="flex items-center gap-1.5 mb-2 text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
                <Sparkles size={14} className="text-[var(--accent)]" />
                {t("explanation")}
              </div>
              <p className="text-[length:var(--text-sm)] text-[var(--fg-2)] leading-relaxed">
                {workflow.explanation}
              </p>
            </div>

            {/* ── 确认创建按钮 ── */}
            <div className="flex items-center gap-2 pt-1">
              <button
                type="button"
                onClick={handleConfirm}
                disabled={confirming || confirmed}
                className={primaryBtn}
              >
                {confirming ? (
                  <Loader2
                    size={16}
                    className="animate-spin motion-reduce:animate-none"
                  />
                ) : confirmed ? (
                  <CheckCircle2 size={16} />
                ) : (
                  <Plus size={16} />
                )}
                {confirmed ? t("confirmed") : t("confirm")}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

/**
 * 审批委托设置组件。
 *
 * 功能：
 * - 委托列表（代理人姓名、起止时间、原因、状态）
 * - 撤销委托（DELETE）
 * - 创建委托表单（选择代理人、起止时间、原因）
 *
 * API：
 * - GET    /approvals/delegates?page=1&limit=20&active=1
 * - POST   /approvals/delegates
 * - DELETE /approvals/delegates/{did}
 *
 * 工作区成员列表（GET /members）用于代理人选择。
 */

import { useEffect, useState, type FormEvent } from "react";
import { useTranslations } from "next-intl";
import {
  Loader2,
  Trash2,
  UserCog,
  CheckCircle2,
  XCircle,
  Plus,
} from "lucide-react";
import { api, ApiError } from "@/lib/api";

/** 审批委托 */
interface ApprovalDelegate {
  id: string;
  workspaceId: string;
  delegatorId: string;
  delegateToId: string;
  startAt: string;
  endAt: string;
  reason?: string | null;
  active: boolean;
  createdAt: string;
  delegateTo: {
    id: string;
    name: string;
    email: string;
  };
}

/** 委托列表响应 */
interface DelegateListResponse {
  items: ApprovalDelegate[];
  total: number;
  page: number;
  limit: number;
  totalPages: number;
}

/** 工作区成员 */
interface Member {
  id: string;
  name: string | null;
  email: string;
}

interface ApprovalDelegateSettingsProps {
  workspaceId: string;
}

const fieldLabel =
  "flex items-center gap-1.5 text-[length:var(--text-xs)] text-[var(--meta)] mb-1.5";
const fieldControl =
  "w-full h-9 px-2.5 border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]";

/** 判断委托是否已过期（endAt 早于当前时间） */
function isExpired(endAt: string): boolean {
  return new Date(endAt).getTime() < Date.now();
}

/** 将 datetime-local 值转为 ISO 8601 格式 */
function toISO(datetimeLocalValue: string): string {
  // datetime-local 格式: "2026-09-21T14:30"，直接 new Date() 即可解析
  return new Date(datetimeLocalValue).toISOString();
}

/** 格式化日期时间用于显示 */
function formatDateTime(isoString: string): string {
  const d = new Date(isoString);
  return d.toLocaleString(undefined, {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  });
}

export function ApprovalDelegateSettings({
  workspaceId,
}: ApprovalDelegateSettingsProps) {
  const t = useTranslations("approval");

  const [delegates, setDelegates] = useState<ApprovalDelegate[]>([]);
  const [members, setMembers] = useState<Member[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  // 创建委托表单状态
  const [showForm, setShowForm] = useState(false);
  const [delegateToId, setDelegateToId] = useState("");
  const [startAt, setStartAt] = useState("");
  const [endAt, setEndAt] = useState("");
  const [reason, setReason] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [formError, setFormError] = useState("");

  async function loadDelegates() {
    setLoading(true);
    setError("");
    try {
      const data = await api<DelegateListResponse>(
        `/api/v1/workspaces/${workspaceId}/approvals/delegates?page=1&limit=20&active=1`,
      );
      setDelegates(data.items ?? []);
    } catch (e) {
      setError(
        e instanceof ApiError || e instanceof Error
          ? e.message
          : t("loadFailed"),
      );
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadDelegates();
    // 拉取成员列表用于代理人选择
    api<Member[] | { items: Member[] }>(
      `/api/v1/workspaces/${workspaceId}/members`,
    )
      .then((data) => {
        const list = Array.isArray(data) ? data : (data.items ?? []);
        setMembers(list);
      })
      .catch(() => {
        // 成员列表加载失败不阻塞委托管理
      });
  }, [workspaceId, t]);

  async function revokeDelegate(delegate: ApprovalDelegate) {
    if (!window.confirm(t("confirmDelegate"))) return;
    try {
      await api(
        `/api/v1/workspaces/${workspaceId}/approvals/delegates/${delegate.id}`,
        { method: "DELETE" },
      );
      setDelegates((prev) => prev.filter((d) => d.id !== delegate.id));
    } catch (e) {
      setError(
        e instanceof ApiError || e instanceof Error
          ? e.message
          : t("operationFailed"),
      );
    }
  }

  async function submitDelegate(e: FormEvent) {
    e.preventDefault();
    if (submitting) return;
    if (!delegateToId) {
      setFormError(t("selectUser"));
      return;
    }
    if (!startAt || !endAt) {
      setFormError(t("delegateStartAt") + " / " + t("delegateEndAt"));
      return;
    }
    if (new Date(startAt) >= new Date(endAt)) {
      setFormError(t("delegateEndAt"));
      return;
    }
    setSubmitting(true);
    setFormError("");
    try {
      await api(
        `/api/v1/workspaces/${workspaceId}/approvals/delegates`,
        {
          method: "POST",
          body: JSON.stringify({
            delegateToId,
            startAt: toISO(startAt),
            endAt: toISO(endAt),
            reason: reason.trim() || undefined,
          }),
        },
      );
      // 成功后刷新委托列表并关闭表单
      setShowForm(false);
      setDelegateToId("");
      setStartAt("");
      setEndAt("");
      setReason("");
      loadDelegates();
    } catch (e) {
      setFormError(
        e instanceof ApiError || e instanceof Error
          ? e.message
          : t("operationFailed"),
      );
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="max-w-[var(--container-max)] mx-auto px-[var(--space-4)] py-[var(--space-6)]">
      <div className="flex items-center justify-between mb-[var(--space-5)]">
        <h1 className="text-[length:var(--text-2xl)] font-[weight:var(--weight-semibold)] text-[var(--fg)] tracking-[var(--tracking-tight)]">
          {t("delegateSettings")}
        </h1>
        <button
          onClick={() => setShowForm((v) => !v)}
          className="inline-flex items-center gap-1.5 h-9 px-3 rounded-[var(--radius-md)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] transition-colors duration-[var(--motion-fast)]"
        >
          <Plus size={14} />
          {t("delegate")}
        </button>
      </div>

      {error && (
        <p className="mb-3 text-[length:var(--text-sm)] text-[var(--danger)]">
          {error}
        </p>
      )}

      {/* 创建委托表单 */}
      {showForm && (
        <form
          onSubmit={submitDelegate}
          className="mb-[var(--space-5)] p-4 rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] space-y-4"
        >
          {/* 选择代理人 */}
          <div>
            <label className={fieldLabel} htmlFor="delegate-to">
              {t("delegateTo")}
            </label>
            <select
              id="delegate-to"
              value={delegateToId}
              onChange={(e) => setDelegateToId(e.target.value)}
              className={fieldControl}
              aria-required="true"
            >
              <option value="">{t("selectUser")}</option>
              {members.map((m) => (
                <option key={m.id} value={m.id}>
                  {m.name || m.email}
                </option>
              ))}
            </select>
          </div>

          {/* 开始时间 */}
          <div>
            <label className={fieldLabel} htmlFor="delegate-start">
              {t("delegateStartAt")}
            </label>
            <input
              id="delegate-start"
              type="datetime-local"
              value={startAt}
              onChange={(e) => setStartAt(e.target.value)}
              className={fieldControl}
              aria-required="true"
            />
          </div>

          {/* 结束时间 */}
          <div>
            <label className={fieldLabel} htmlFor="delegate-end">
              {t("delegateEndAt")}
            </label>
            <input
              id="delegate-end"
              type="datetime-local"
              value={endAt}
              onChange={(e) => setEndAt(e.target.value)}
              className={fieldControl}
              aria-required="true"
            />
          </div>

          {/* 原因（可选） */}
          <div>
            <label className={fieldLabel} htmlFor="delegate-reason">
              {t("delegateReason")}
            </label>
            <textarea
              id="delegate-reason"
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              rows={2}
              maxLength={500}
              className="w-full px-2.5 py-2 resize-y border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] placeholder:text-[var(--meta)]"
            />
          </div>

          {formError && (
            <div className="flex items-start gap-2 px-3 py-2 rounded-[var(--radius-md)] bg-[var(--danger-soft, var(--surface-2))] text-[var(--danger-fg, var(--danger))] text-[length:var(--text-sm)]">
              <span className="flex-1">{formError}</span>
            </div>
          )}

          <div className="flex items-center justify-end gap-2 pt-1">
            <button
              type="button"
              onClick={() => {
                setShowForm(false);
                setFormError("");
              }}
              className="h-9 px-4 rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
            >
              {t("cancel")}
            </button>
            <button
              type="submit"
              disabled={submitting}
              className="inline-flex items-center gap-1.5 h-9 px-4 bg-[var(--accent)] text-[var(--accent-fg)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-[var(--motion-base)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
            >
              {submitting && <Loader2 size={14} className="animate-spin" />}
              {t("save")}
            </button>
          </div>
        </form>
      )}

      {/* 委托列表 */}
      {loading ? (
        <div className="py-[var(--space-12)] text-center text-[var(--muted)]">
          <Loader2 size={20} className="inline animate-spin mr-2" />
          {t("loading")}
        </div>
      ) : delegates.length === 0 ? (
        <div className="py-[var(--space-12)] text-center text-[var(--muted)]">
          <UserCog size={36} className="mx-auto mb-3 opacity-50" />
          <p>{t("noDelegates")}</p>
        </div>
      ) : (
        <ul className="divide-y divide-[var(--border-soft)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)]">
          {delegates.map((delegate) => {
            const expired = isExpired(delegate.endAt);
            return (
              <li
                key={delegate.id}
                className="px-[var(--space-4)] py-3 hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
              >
                <div className="flex items-center gap-2">
                  <UserCog
                    size={15}
                    className="shrink-0 text-[var(--muted)]"
                  />
                  <span className="flex-1 min-w-0 text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg)] truncate">
                    {delegate.delegateTo?.name || delegate.delegateTo?.email || t("delegateTo")}
                  </span>
                  <span
                    className={`shrink-0 inline-flex items-center gap-1 px-2 py-0.5 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] ${
                      expired
                        ? "text-[var(--muted)] bg-[var(--surface-2)]"
                        : "text-[var(--success)] bg-[var(--success-soft, var(--surface-2))]"
                    }`}
                  >
                    {expired ? (
                      <XCircle size={12} />
                    ) : (
                      <CheckCircle2 size={12} />
                    )}
                    {expired ? t("delegateExpired") : t("delegateActive")}
                  </span>
                </div>
                {/* 起止时间 */}
                <div className="mt-1.5 ml-6 flex items-center gap-3 text-[length:var(--text-xs)] text-[var(--meta)]">
                  <span>
                    {t("delegateStartAt")}: {formatDateTime(delegate.startAt)}
                  </span>
                  <span>
                    {t("delegateEndAt")}: {formatDateTime(delegate.endAt)}
                  </span>
                </div>
                {/* 原因 */}
                {delegate.reason && (
                  <p className="mt-1 ml-6 text-[length:var(--text-xs)] text-[var(--muted)] break-words">
                    {t("delegateReason")}: {delegate.reason}
                  </p>
                )}
                {/* 撤销按钮 */}
                <div className="mt-2 ml-6 flex items-center gap-2">
                  <button
                    onClick={() => revokeDelegate(delegate)}
                    className="inline-flex items-center gap-1 h-7 px-2 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-xs)] text-[var(--danger)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
                  >
                    <Trash2 size={12} />
                    {t("cancel")}
                  </button>
                </div>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

export default ApprovalDelegateSettings;

"use client";

/**
 * 审批统计仪表盘组件。
 *
 * 功能：
 * - 拉取审批统计数据（GET /api/v1/workspaces/{wid}/approvals/stats）
 * - 顶部4个统计卡片：待我审批 / 已通过 / 已拒绝 / 平均处理时长
 * - 状态分布条形图：pending / approved / rejected / withdrawn 占比
 * - 优先级分布：normal / urgent / critical 数量
 * - 模板使用排行：按 count 降序展示
 * - 时间范围筛选：最近7天 / 最近30天 / 全部
 *
 * 状态颜色映射（design token，禁止裸 hex）：
 * - pending  → var(--warning) / var(--warning-fg)
 * - approved → var(--success) / var(--success-fg)
 * - rejected → var(--danger)  / var(--danger-fg)
 * - withdrawn→ var(--muted)
 *
 * 优先级颜色映射：
 * - normal   → var(--fg-2)
 * - urgent   → var(--warning)
 * - critical → var(--danger)
 */

import { useEffect, useState, useMemo } from "react";
import { useTranslations } from "next-intl";
import {
  Clock,
  CheckCircle2,
  XCircle,
  Timer,
  Loader2,
  AlertCircle,
  MinusCircle,
  FileText,
} from "lucide-react";
import { api, ApiError } from "@/lib/api";

/** 审批统计数据结构（与后端 GET /stats 响应一致） */
interface ApprovalStatsData {
  total: number;
  byStatus: {
    pending: number;
    approved: number;
    rejected: number;
    withdrawn: number;
  };
  byPriority: {
    normal: number;
    urgent: number;
    critical: number;
  };
  byTemplate: Array<{
    templateId: string;
    templateName: string;
    count: number;
  }>;
  avgProcessingHours: number;
  pendingMine: number;
}

type TimeRange = "7d" | "30d" | "all";

interface ApprovalStatsDashboardProps {
  workspaceId: string;
}

/** 状态 → 颜色 token 映射 */
const STATUS_COLORS: Record<string, string> = {
  pending: "var(--warning)",
  approved: "var(--success)",
  rejected: "var(--danger)",
  withdrawn: "var(--muted)",
};

/** 状态 → i18n label key 映射 */
const STATUS_LABEL_KEYS: Record<string, string> = {
  pending: "statusPending",
  approved: "statusApproved",
  rejected: "statusRejected",
  withdrawn: "statusWithdrawn",
};

/** 优先级 → 颜色 token 映射 */
const PRIORITY_COLORS: Record<string, string> = {
  normal: "var(--fg-2)",
  urgent: "var(--warning)",
  critical: "var(--danger)",
};

/** 优先级 → i18n label key 映射 */
const PRIORITY_LABEL_KEYS: Record<string, string> = {
  normal: "priorityNormal",
  urgent: "priorityUrgent",
  critical: "priorityCritical",
};

export function ApprovalStatsDashboard({
  workspaceId,
}: ApprovalStatsDashboardProps) {
  const t = useTranslations("approval");
  const [data, setData] = useState<ApprovalStatsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [timeRange, setTimeRange] = useState<TimeRange>("30d");

  useEffect(() => {
    let cancelled = false;
    (async () => {
      setLoading(true);
      setError("");
      try {
        const params = new URLSearchParams();
        if (timeRange === "7d") {
          const start = new Date();
          start.setDate(start.getDate() - 7);
          params.set("startDate", start.toISOString());
        } else if (timeRange === "30d") {
          const start = new Date();
          start.setDate(start.getDate() - 30);
          params.set("startDate", start.toISOString());
        }
        // timeRange === "all" 不传日期参数，后端默认最近30天或全部

        const result = await api<ApprovalStatsData>(
          `/api/v1/workspaces/${workspaceId}/approvals/stats?${params.toString()}`,
        );
        if (cancelled) return;
        setData(result);
      } catch (e) {
        if (cancelled) return;
        setError(
          e instanceof ApiError || e instanceof Error
            ? e.message
            : t("statsLoadFailed"),
        );
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [workspaceId, timeRange, t]);

  /** 状态分布百分比计算 */
  const statusDistribution = useMemo(() => {
    if (!data || data.total === 0) return [];
    const statuses = ["pending", "approved", "rejected", "withdrawn"];
    return statuses.map((key) => {
      const count = data.byStatus[key as keyof typeof data.byStatus];
      return {
        key,
        count,
        percent: Math.round((count / data.total) * 100),
      };
    });
  }, [data]);

  /** 模板使用排行（按 count 降序） */
  const sortedTemplates = useMemo(() => {
    if (!data) return [];
    return [...data.byTemplate].sort((a, b) => b.count - a.count);
  }, [data]);

  const timeRangeOptions: { value: TimeRange; labelKey: string }[] = [
    { value: "7d", labelKey: "last7Days" },
    { value: "30d", labelKey: "last30Days" },
    { value: "all", labelKey: "allTime" },
  ];

  return (
    <div className="max-w-[var(--container-max)] mx-auto px-[var(--space-4)] py-[var(--space-6)]">
      {/* 标题 + 时间范围筛选 */}
      <div className="flex items-center justify-between mb-[var(--space-5)] flex-wrap gap-3">
        <h2 className="text-[length:var(--text-xl)] font-[weight:var(--weight-semibold)] text-[var(--fg)] tracking-[var(--tracking-tight)]">
          {t("statsDashboard")}
        </h2>
        <div
          role="tablist"
          aria-label={t("statsDashboard")}
          className="inline-flex items-center gap-1 p-1 rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface-2)]"
        >
          {timeRangeOptions.map((opt) => {
            const active = opt.value === timeRange;
            return (
              <button
                key={opt.value}
                role="tab"
                aria-selected={active}
                onClick={() => setTimeRange(opt.value)}
                className={`h-7 px-3 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] ${
                  active
                    ? "bg-[var(--surface)] text-[var(--fg)] shadow-[var(--elev-sm)]"
                    : "text-[var(--fg-2)] hover:text-[var(--fg)]"
                }`}
              >
                {t(opt.labelKey)}
              </button>
            );
          })}
        </div>
      </div>

      {/* 错误提示 */}
      {error && (
        <div className="mb-[var(--space-4)] flex items-center gap-2 p-3 rounded-[var(--radius-md)] border border-[var(--danger)] bg-[var(--danger-soft,var(--surface-2))]">
          <AlertCircle size={16} className="shrink-0 text-[var(--danger)]" />
          <span className="text-[length:var(--text-sm)] text-[var(--danger)]">
            {error}
          </span>
        </div>
      )}

      {/* 加载态 */}
      {loading ? (
        <div className="py-[var(--space-12)] text-center text-[var(--muted)]">
          <Loader2 size={20} className="inline animate-spin mr-2" />
          {t("loading")}
        </div>
      ) : !data ? (
        <div className="py-[var(--space-12)] text-center text-[var(--muted)]">
          <AlertCircle size={36} className="mx-auto mb-3 opacity-50" />
          <p>{t("statsLoadFailed")}</p>
        </div>
      ) : (
        <>
          {/* 顶部统计卡片行 */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-[var(--space-3)] mb-[var(--space-6)]">
            {/* 待我审批 */}
            <StatCard
              icon={<Clock size={16} />}
              color="var(--warning)"
              label={t("pendingMine")}
              value={String(data.pendingMine)}
            />
            {/* 已通过 */}
            <StatCard
              icon={<CheckCircle2 size={16} />}
              color="var(--success)"
              label={t("statusApproved")}
              value={String(data.byStatus.approved)}
            />
            {/* 已拒绝 */}
            <StatCard
              icon={<XCircle size={16} />}
              color="var(--danger)"
              label={t("statusRejected")}
              value={String(data.byStatus.rejected)}
            />
            {/* 平均处理时长 */}
            <StatCard
              icon={<Timer size={16} />}
              color="var(--accent)"
              label={t("avgProcessingTime")}
              value={`${data.avgProcessingHours.toFixed(1)}${t("hours")}`}
            />
          </div>

          {/* 状态分布 + 优先级分布（两列布局） */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-[var(--space-4)] mb-[var(--space-4)]">
            {/* 状态分布 */}
            <section className="p-[var(--space-4)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)]">
              <h3 className="text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)] mb-[var(--space-3)]">
                {t("statusDistribution")}
              </h3>
              {data.total === 0 ? (
                <p className="text-[length:var(--text-xs)] text-[var(--muted)] py-[var(--space-3)]">
                  {t("noApprovals")}
                </p>
              ) : (
                <div className="space-y-[var(--space-2)]">
                  {/* 条形图 */}
                  <div className="flex h-2 rounded-[var(--radius-sm)] overflow-hidden bg-[var(--surface-2)]">
                    {statusDistribution.map((item) => {
                      if (item.count === 0) return null;
                      return (
                        <div
                          key={item.key}
                          className="h-full transition-all duration-[var(--motion-normal)]"
                          style={{
                            width: `${item.percent}%`,
                            backgroundColor: STATUS_COLORS[item.key],
                          }}
                          title={`${t(STATUS_LABEL_KEYS[item.key])}: ${item.count} (${item.percent}%)`}
                        />
                      );
                    })}
                  </div>
                  {/* 图例 + 数值 */}
                  <div className="grid grid-cols-2 gap-[var(--space-2)] mt-[var(--space-3)]">
                    {statusDistribution.map((item) => (
                      <div
                        key={item.key}
                        className="flex items-center gap-2 text-[length:var(--text-xs)]"
                      >
                        <span
                          className="inline-block w-2.5 h-2.5 rounded-[var(--radius-xs)] shrink-0"
                          style={{
                            backgroundColor: STATUS_COLORS[item.key],
                          }}
                        />
                        <span className="text-[var(--fg-2)] flex-1 truncate">
                          {t(STATUS_LABEL_KEYS[item.key])}
                        </span>
                        <span className="font-[weight:var(--weight-medium)] text-[var(--fg)]">
                          {item.count}
                        </span>
                        <span className="text-[var(--muted)]">
                          {item.percent}%
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </section>

            {/* 优先级分布 */}
            <section className="p-[var(--space-4)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)]">
              <h3 className="text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)] mb-[var(--space-3)]">
                {t("priorityDistribution")}
              </h3>
              {data.byPriority.normal === 0 &&
              data.byPriority.urgent === 0 &&
              data.byPriority.critical === 0 ? (
                <p className="text-[length:var(--text-xs)] text-[var(--muted)] py-[var(--space-3)]">
                  {t("noApprovals")}
                </p>
              ) : (
                <div className="space-y-[var(--space-3)]">
                  {(["critical", "urgent", "normal"] as const).map((key) => {
                    const count = data.byPriority[key];
                    const maxCount = Math.max(
                      data.byPriority.normal,
                      data.byPriority.urgent,
                      data.byPriority.critical,
                      1,
                    );
                    const barWidth = Math.round((count / maxCount) * 100);
                    return (
                      <div key={key} className="flex items-center gap-2">
                        <span
                          className="text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] w-16 shrink-0"
                          style={{ color: PRIORITY_COLORS[key] }}
                        >
                          {t(PRIORITY_LABEL_KEYS[key])}
                        </span>
                        <div className="flex-1 h-5 rounded-[var(--radius-sm)] bg-[var(--surface-2)] overflow-hidden">
                          <div
                            className="h-full rounded-[var(--radius-sm)] transition-all duration-[var(--motion-normal)] flex items-center justify-end pr-2"
                            style={{
                              width: `${barWidth}%`,
                              backgroundColor: PRIORITY_COLORS[key],
                              minWidth: count > 0 ? "1.5rem" : "0",
                            }}
                          >
                            {count > 0 && (
                              <span className="text-[length:var(--text-xs)] font-[weight:var(--weight-semibold)] text-[var(--surface)]">
                                {count}
                              </span>
                            )}
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </section>
          </div>

          {/* 模板使用排行 */}
          <section className="p-[var(--space-4)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)]">
            <h3 className="text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)] mb-[var(--space-3)]">
              {t("templateUsage")}
            </h3>
            {sortedTemplates.length === 0 ? (
              <div className="py-[var(--space-4)] text-center">
                <FileText size={28} className="mx-auto mb-2 opacity-40 text-[var(--muted)]" />
                <p className="text-[length:var(--text-xs)] text-[var(--muted)]">
                  {t("noTemplateUsage")}
                </p>
              </div>
            ) : (
              <ul className="divide-y divide-[var(--border-soft)]">
                {sortedTemplates.map((template, index) => {
                  const maxCount = sortedTemplates[0]?.count || 1;
                  const barWidth = Math.round(
                    (template.count / maxCount) * 100,
                  );
                  return (
                    <li
                      key={template.templateId}
                      className="flex items-center gap-3 py-2"
                    >
                      <span className="text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--muted)] w-5 shrink-0 text-right">
                        {index + 1}
                      </span>
                      <span className="text-[length:var(--text-sm)] text-[var(--fg)] flex-1 min-w-0 truncate">
                        {template.templateName}
                      </span>
                      <div className="w-24 h-1.5 rounded-[var(--radius-xs)] bg-[var(--surface-2)] overflow-hidden shrink-0">
                        <div
                          className="h-full rounded-[var(--radius-xs)] transition-all duration-[var(--motion-normal)]"
                          style={{
                            width: `${barWidth}%`,
                            backgroundColor: "var(--accent)",
                          }}
                        />
                      </div>
                      <span className="text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)] w-8 shrink-0 text-right">
                        {template.count}
                      </span>
                    </li>
                  );
                })}
              </ul>
            )}
          </section>
        </>
      )}
    </div>
  );
}

/** 统计卡片子组件 */
function StatCard({
  icon,
  color,
  label,
  value,
}: {
  icon: React.ReactNode;
  color: string;
  label: string;
  value: string;
}) {
  return (
    <div className="p-[var(--space-3)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] transition-colors duration-[var(--motion-fast)] hover:border-[var(--border-strong)]">
      <div className="flex items-center gap-2 mb-[var(--space-1)]">
        <span style={{ color }}>{icon}</span>
        <span className="text-[length:var(--text-xs)] text-[var(--fg-2)] truncate">
          {label}
        </span>
      </div>
      <p
        className="text-[length:var(--text-2xl)] font-[weight:var(--weight-bold)] tracking-[var(--tracking-tight)]"
        style={{ color }}
      >
        {value}
      </p>
    </div>
  );
}

"use client";

/**
 * 审批模板管理组件。
 *
 * 功能：
 * - 模板列表（名称、描述、节点数、状态）
 * - 创建 / 编辑模板弹窗（名称、描述、节点配置）
 * - 启用 / 禁用模板（PATCH）
 * - 删除模板（DELETE）
 * - 节点配置 UI：可添加 / 删除 / 排序节点，每个节点选择审批人角色或指定用户
 *
 * API：
 * - GET    /approvals/templates
 * - POST   /approvals/templates
 * - PATCH  /approvals/templates/{tid}
 * - DELETE /approvals/templates/{tid}
 *
 * 工作区成员列表（GET /members）用于"指定用户"审批人选择。
 */

import { useEffect, useState, type FormEvent } from "react";
import { useTranslations } from "next-intl";
import {
  Plus,
  Loader2,
  Trash2,
  Pencil,
  ArrowUp,
  ArrowDown,
  X,
  FileText,
  Power,
  CheckCircle2,
  XCircle,
} from "lucide-react";
import { api, ApiError } from "@/lib/api";

/** 审批模板 */
interface ApprovalTemplate {
  id: string;
  name: string;
  description?: string | null;
  active?: boolean;
  /** @deprecated 旧字段，保留兼容 */
  enabled?: boolean;
  nodes?: TemplateNode[] | null;
}

interface TemplateNode {
  name: string;
  order: number;
  approverRole?: string | null;
  approverUserId?: string | null;
}

/** 工作区成员 */
interface Member {
  id: string;
  name: string | null;
  email: string;
}

/** 可编辑的节点（前端临时态，含临时 id 便于 React key） */
interface EditableNode {
  tempId: string;
  name: string;
  approverRole: string;
  approverUserId: string;
}

interface ApprovalTemplateManageProps {
  workspaceId: string;
}

const fieldLabel =
  "flex items-center gap-1.5 text-[length:var(--text-xs)] text-[var(--meta)] mb-1.5";
const fieldControl =
  "w-full h-9 px-2.5 border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]";

let tempIdCounter = 0;
function nextTempId() {
  tempIdCounter += 1;
  return `tmp-${tempIdCounter}`;
}

export function ApprovalTemplateManage({
  workspaceId,
}: ApprovalTemplateManageProps) {
  const t = useTranslations("approval");
  const tButton = useTranslations("button");

  const [templates, setTemplates] = useState<ApprovalTemplate[]>([]);
  const [members, setMembers] = useState<Member[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  // 编辑弹窗状态
  const [editDialog, setEditDialog] = useState<{
    template: ApprovalTemplate | null; // null = 新建
  } | null>(null);

  async function loadTemplates() {
    setLoading(true);
    setError("");
    try {
      const data = await api<
        ApprovalTemplate[] | { items: ApprovalTemplate[] }
      >(`/api/v1/workspaces/${workspaceId}/approvals/templates`);
      const list = Array.isArray(data) ? data : (data.items ?? []);
      setTemplates(list);
    } catch (e) {
      setError(
        e instanceof ApiError || e instanceof Error
          ? e.message
          : t("loadFailed"),
      );
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadTemplates();
    // 拉取成员列表用于节点审批人选择
    api<Member[]>(`/api/v1/workspaces/${workspaceId}/members`)
      .then(setMembers)
      .catch(() => {
        // 成员列表加载失败不阻塞模板管理
      });
  }, [workspaceId, t]);

  async function toggleEnabled(tpl: ApprovalTemplate) {
    // 后端字段为 active（非 enabled）
    const nextActive = !tpl.active;
    try {
      await api(
        `/api/v1/workspaces/${workspaceId}/approvals/templates/${tpl.id}`,
        {
          method: "PATCH",
          body: JSON.stringify({ active: nextActive }),
        },
      );
      setTemplates((prev) =>
        prev.map((item) =>
          item.id === tpl.id ? { ...item, active: nextActive } : item,
        ),
      );
    } catch (e) {
      setError(
        e instanceof ApiError || e instanceof Error
          ? e.message
          : t("operationFailed"),
      );
    }
  }

  async function deleteTemplate(tpl: ApprovalTemplate) {
    if (!window.confirm(t("confirmDeleteTemplate"))) return;
    try {
      await api(
        `/api/v1/workspaces/${workspaceId}/approvals/templates/${tpl.id}`,
        { method: "DELETE" },
      );
      setTemplates((prev) => prev.filter((item) => item.id !== tpl.id));
    } catch (e) {
      setError(
        e instanceof ApiError || e instanceof Error
          ? e.message
          : t("operationFailed"),
      );
    }
  }

  return (
    <div className="max-w-[var(--container-max)] mx-auto px-[var(--space-4)] py-[var(--space-6)]">
      <div className="flex items-center justify-between mb-[var(--space-5)]">
        <h1 className="text-[length:var(--text-2xl)] font-[weight:var(--weight-semibold)] text-[var(--fg)] tracking-[var(--tracking-tight)]">
          {t("templateManage")}
        </h1>
        <button
          onClick={() => setEditDialog({ template: null })}
          className="inline-flex items-center gap-1.5 h-9 px-3 rounded-[var(--radius-md)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] transition-colors duration-[var(--motion-fast)]"
        >
          <Plus size={14} />
          {t("addTemplate")}
        </button>
      </div>

      {error && (
        <p className="mb-3 text-[length:var(--text-sm)] text-[var(--danger)]">
          {error}
        </p>
      )}

      {loading ? (
        <div className="py-[var(--space-12)] text-center text-[var(--muted)]">
          <Loader2 size={20} className="inline animate-spin mr-2" />
          {t("loading")}
        </div>
      ) : templates.length === 0 ? (
        <div className="py-[var(--space-12)] text-center text-[var(--muted)]">
          <FileText size={36} className="mx-auto mb-3 opacity-50" />
          <p>{t("templateEmpty")}</p>
        </div>
      ) : (
        <ul className="divide-y divide-[var(--border-soft)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)]">
          {templates.map((tpl) => {
            const nodeCount = tpl.nodes?.length ?? 0;
            return (
              <li
                key={tpl.id}
                className="px-[var(--space-4)] py-3 hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
              >
                <div className="flex items-center gap-2">
                  <FileText
                    size={15}
                    className="shrink-0 text-[var(--muted)]"
                  />
                  <span className="flex-1 min-w-0 text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg)] truncate">
                    {tpl.name}
                  </span>
                  <span
                    className={`shrink-0 inline-flex items-center gap-1 px-2 py-0.5 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] ${
                      tpl.active
                        ? "text-[var(--success)] bg-[var(--success-soft, var(--surface-2))]"
                        : "text-[var(--muted)] bg-[var(--surface-2)]"
                    }`}
                  >
                    {tpl.active ? (
                      <CheckCircle2 size={12} />
                    ) : (
                      <XCircle size={12} />
                    )}
                    {tpl.active ? t("templateEnabled") : t("templateDisabled")}
                  </span>
                </div>
                {tpl.description && (
                  <p className="mt-1 ml-6 text-[length:var(--text-xs)] text-[var(--muted)] break-words">
                    {tpl.description}
                  </p>
                )}
                <div className="mt-1.5 ml-6 flex items-center gap-3 text-[length:var(--text-xs)] text-[var(--meta)]">
                  <span>
                    {t("nodes")}: {nodeCount}
                  </span>
                </div>
                <div className="mt-2 ml-6 flex items-center gap-2">
                  <button
                    onClick={() => setEditDialog({ template: tpl })}
                    className="inline-flex items-center gap-1 h-7 px-2 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-xs)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
                  >
                    <Pencil size={12} />
                    {t("edit")}
                  </button>
                  <button
                    onClick={() => toggleEnabled(tpl)}
                    className="inline-flex items-center gap-1 h-7 px-2 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-xs)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
                  >
                    <Power size={12} />
                    {tpl.active ? t("disable") : t("enable")}
                  </button>
                  <button
                    onClick={() => deleteTemplate(tpl)}
                    className="inline-flex items-center gap-1 h-7 px-2 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-xs)] text-[var(--danger)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
                  >
                    <Trash2 size={12} />
                    {t("delete")}
                  </button>
                </div>
              </li>
            );
          })}
        </ul>
      )}

      {/* 编辑/新建弹窗 */}
      {editDialog && (
        <TemplateEditDialog
          workspaceId={workspaceId}
          template={editDialog.template}
          members={members}
          onClose={() => setEditDialog(null)}
          onSaved={() => {
            setEditDialog(null);
            loadTemplates();
          }}
        />
      )}
    </div>
  );
}

/** 模板编辑/新建弹窗 */
function TemplateEditDialog({
  workspaceId,
  template,
  members,
  onClose,
  onSaved,
}: {
  workspaceId: string;
  template: ApprovalTemplate | null;
  members: Member[];
  onClose: () => void;
  onSaved: () => void;
}) {
  const t = useTranslations("approval");
  const tButton = useTranslations("button");

  const [name, setName] = useState(template?.name ?? "");
  const [description, setDescription] = useState(template?.description ?? "");
  const [nodes, setNodes] = useState<EditableNode[]>(
    template?.nodes && template.nodes.length > 0
      ? template.nodes
          .slice()
          .sort((a, b) => a.order - b.order)
          .map((n) => ({
            tempId: nextTempId(),
            name: n.name,
            approverRole: n.approverRole ?? "",
            approverUserId: n.approverUserId ?? "",
          }))
      : [{ tempId: nextTempId(), name: "", approverRole: "", approverUserId: "" }],
  );
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");

  // ESC 关闭
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  function addNode() {
    setNodes((prev) => [
      ...prev,
      { tempId: nextTempId(), name: "", approverRole: "", approverUserId: "" },
    ]);
  }

  function removeNode(tempId: string) {
    setNodes((prev) =>
      prev.length > 1
        ? prev.filter((n) => n.tempId !== tempId)
        : [{ tempId: nextTempId(), name: "", approverRole: "", approverUserId: "" }],
    );
  }

  function moveNode(idx: number, dir: -1 | 1) {
    setNodes((prev) => {
      const next = [...prev];
      const target = idx + dir;
      if (target < 0 || target >= next.length) return prev;
      [next[idx], next[target]] = [next[target], next[idx]];
      return next;
    });
  }

  function updateNode(
    tempId: string,
    field: keyof EditableNode,
    val: string,
  ) {
    setNodes((prev) =>
      prev.map((n) => (n.tempId === tempId ? { ...n, [field]: val } : n)),
    );
  }

  async function submit(e: FormEvent) {
    e.preventDefault();
    if (submitting) return;
    if (!name.trim()) {
      setError(t("templateNameRequired"));
      return;
    }
    // 过滤有效节点（有名称）
    const validNodes = nodes.filter((n) => n.name.trim());
    if (validNodes.length === 0) {
      setError(t("nodeRequired"));
      return;
    }
    // 校验每个节点有审批人
    for (const n of validNodes) {
      if (!n.approverRole && !n.approverUserId) {
        setError(t("approverRequired"));
        return;
      }
    }
    setSubmitting(true);
    setError("");
    try {
      const payload = {
        name: name.trim(),
        description: description.trim() || null,
        nodes: validNodes.map((n, i) => ({
          name: n.name.trim(),
          order: i + 1,
          approverRole: n.approverRole || null,
          approverUserId: n.approverUserId || null,
        })),
      };
      if (template) {
        await api(
          `/api/v1/workspaces/${workspaceId}/approvals/templates/${template.id}`,
          { method: "PATCH", body: JSON.stringify(payload) },
        );
      } else {
        await api(
          `/api/v1/workspaces/${workspaceId}/approvals/templates`,
          { method: "POST", body: JSON.stringify(payload) },
        );
      }
      onSaved();
    } catch (e) {
      setError(
        e instanceof ApiError || e instanceof Error
          ? e.message
          : t("operationFailed"),
      );
    } finally {
      setSubmitting(false);
    }
  }

  const isEdit = template !== null;

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-labelledby="template-edit-title"
      className="fixed inset-0 z-[var(--z-modal)] flex items-start justify-center p-4 sm:p-8 overflow-y-auto bg-[var(--overlay)]"
      onClick={(e) => {
        if (e.target !== e.currentTarget) return;
        onClose();
      }}
    >
      <div className="w-full max-w-lg my-auto bg-[var(--surface)] border border-[var(--border)] rounded-[var(--radius-lg)] shadow-[var(--elev-lg)]">
        <header className="flex items-center justify-between px-5 py-3.5 border-b border-[var(--border-soft)]">
          <h2
            id="template-edit-title"
            className="text-[length:var(--text-md)] font-[weight:var(--weight-semibold)] text-[var(--fg)]"
          >
            {isEdit ? t("editTemplate") : t("createTemplate")}
          </h2>
          <button
            type="button"
            onClick={onClose}
            className="w-8 h-8 flex items-center justify-center rounded-[var(--radius-sm)] text-[var(--muted)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
            aria-label={tButton("close")}
          >
            <X size={16} />
          </button>
        </header>

        <form onSubmit={submit} className="px-4 sm:px-5 py-4 space-y-4">
          {/* 模板名称 */}
          <div>
            <label className={fieldLabel} htmlFor="tpl-name">
              {t("templateName")}
            </label>
            <input
              id="tpl-name"
              autoFocus
              value={name}
              onChange={(e) => setName(e.target.value)}
              maxLength={100}
              className={`${fieldControl} h-10`}
              aria-required="true"
            />
          </div>

          {/* 模板描述 */}
          <div>
            <label className={fieldLabel} htmlFor="tpl-desc">
              {t("templateDesc")}
            </label>
            <textarea
              id="tpl-desc"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={2}
              maxLength={500}
              className="w-full px-2.5 py-2 resize-y border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] placeholder:text-[var(--meta)]"
            />
          </div>

          {/* 节点配置 */}
          <div>
            <label className={fieldLabel}>{t("nodes")}</label>
            <div className="space-y-2">
              {nodes.map((node, idx) => (
                <div
                  key={node.tempId}
                  className="px-3 py-2.5 rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface-2)]"
                >
                  <div className="flex items-center gap-2 mb-2">
                    <span className="inline-flex items-center justify-center w-5 h-5 rounded-full bg-[var(--surface)] border border-[var(--border)] text-[length:var(--text-xs)] text-[var(--meta)] font-[weight:var(--weight-medium)]">
                      {idx + 1}
                    </span>
                    <span className="text-[length:var(--text-xs)] text-[var(--meta)]">
                      {t("nodeOrder")}
                    </span>
                    <div className="flex-1" />
                    <button
                      type="button"
                      onClick={() => moveNode(idx, -1)}
                      disabled={idx === 0}
                      className="w-7 h-7 flex items-center justify-center rounded-[var(--radius-sm)] text-[var(--muted)] hover:bg-[var(--surface)] disabled:opacity-30 disabled:cursor-not-allowed transition-colors duration-[var(--motion-fast)]"
                      aria-label={t("nodeOrder")}
                    >
                      <ArrowUp size={13} />
                    </button>
                    <button
                      type="button"
                      onClick={() => moveNode(idx, 1)}
                      disabled={idx === nodes.length - 1}
                      className="w-7 h-7 flex items-center justify-center rounded-[var(--radius-sm)] text-[var(--muted)] hover:bg-[var(--surface)] disabled:opacity-30 disabled:cursor-not-allowed transition-colors duration-[var(--motion-fast)]"
                      aria-label={t("nodeOrder")}
                    >
                      <ArrowDown size={13} />
                    </button>
                    <button
                      type="button"
                      onClick={() => removeNode(node.tempId)}
                      className="w-7 h-7 flex items-center justify-center rounded-[var(--radius-sm)] text-[var(--muted)] hover:text-[var(--danger)] hover:bg-[var(--surface)] transition-colors duration-[var(--motion-fast)]"
                      aria-label={t("delete")}
                    >
                      <Trash2 size={13} />
                    </button>
                  </div>
                  <div className="space-y-2">
                    <input
                      value={node.name}
                      onChange={(e) =>
                        updateNode(node.tempId, "name", e.target.value)
                      }
                      maxLength={50}
                      placeholder={t("nodeName")}
                      className={fieldControl}
                    />
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                      <div>
                        <label className="block text-[length:var(--text-xs)] text-[var(--meta)] mb-1">
                          {t("approverRole")}
                        </label>
                        <input
                          value={node.approverRole}
                          onChange={(e) =>
                            updateNode(
                              node.tempId,
                              "approverRole",
                              e.target.value,
                            )
                          }
                          maxLength={50}
                          placeholder={t("approverRole")}
                          className={fieldControl}
                        />
                      </div>
                      <div>
                        <label className="block text-[length:var(--text-xs)] text-[var(--meta)] mb-1">
                          {t("approverUser")}
                        </label>
                        <select
                          value={node.approverUserId}
                          onChange={(e) =>
                            updateNode(
                              node.tempId,
                              "approverUserId",
                              e.target.value,
                            )
                          }
                          className={fieldControl}
                        >
                          <option value="">—</option>
                          {members.map((m) => (
                            <option key={m.id} value={m.id}>
                              {m.name || m.email}
                            </option>
                          ))}
                        </select>
                      </div>
                    </div>
                  </div>
                </div>
              ))}
              <button
                type="button"
                onClick={addNode}
                className="inline-flex items-center gap-1.5 h-8 px-3 rounded-[var(--radius-sm)] border border-dashed border-[var(--border)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
              >
                <Plus size={14} />
                {t("addNode")}
              </button>
            </div>
          </div>

          {error && (
            <div className="flex items-start gap-2 px-3 py-2 rounded-[var(--radius-md)] bg-[var(--danger-soft, var(--surface-2))] text-[var(--danger-fg, var(--danger))] text-[length:var(--text-sm)]">
              <span className="flex-1">{error}</span>
              <button
                type="button"
                onClick={() => setError("")}
                className="shrink-0 opacity-60 hover:opacity-100 transition-opacity rounded-[var(--radius-sm)]"
                aria-label={tButton("close")}
              >
                <X size={14} />
              </button>
            </div>
          )}

          <div className="flex items-center justify-end gap-2 pt-1">
            <button
              type="button"
              onClick={onClose}
              className="h-9 px-4 rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
            >
              {tButton("cancel")}
            </button>
            <button
              type="submit"
              disabled={submitting}
              className="inline-flex items-center gap-1.5 h-9 px-4 bg-[var(--accent)] text-[var(--accent-fg)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-[var(--motion-base)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
            >
              {submitting && <Loader2 size={14} className="animate-spin" />}
              {isEdit ? t("save") : t("createTemplate")}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

export default ApprovalTemplateManage;

"use client";

// 保持 "use client"：接收 5 个函数 props（onPrev/onNext/onToday/onEventClick/onDayClick），
// 这些回调来自 client 父组件 (CalendarView.tsx)，无法跨越 server/client 边界传递。
// CalendarView 管理所有日历状态（currentDate/events/dialogOpen），本组件仅做展示 + 回调转发。

import { useTranslations } from "next-intl";
import { ChevronLeft, ChevronRight, CheckCircle2 } from "lucide-react";
import type { CalendarEvent } from "./CalendarEventDialog";
import { getEventsOnDate, getEventColor, isSameDay, addMonths, isTaskDeadline } from "./calendar-utils";

/** 月视图公共 props */
interface CalendarMonthProps {
  events: CalendarEvent[];
  currentDate: Date;
  onPrev: () => void;
  onNext: () => void;
  onToday: () => void;
  onEventClick: (event: CalendarEvent) => void;
  onDayClick: (date: Date) => void;
}

/**
 * CalendarMonth — 月视图组件。
 * 6行×7列网格，每个格子显示日期和事件摘要。
 * 支持点击日期切换到日视图，点击事件打开编辑弹窗。
 */
export function CalendarMonth({
  events,
  currentDate,
  onPrev,
  onNext,
  onToday,
  onEventClick,
  onDayClick,
}: CalendarMonthProps) {
  const t = useTranslations("calendar");

  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();
  const today = new Date();

  // 当月第一天是星期几（0=Sunday）
  const firstDayOfWeek = new Date(year, month, 1).getDay();
  // 当月天数
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  // 星期标题
  const weekHeaders = [
    t("sunday"), t("monday"), t("tuesday"), t("wednesday"),
    t("thursday"), t("friday"), t("saturday"),
  ];

  // 生成 42 个格子（6行×7列）
  const cells: (Date | null)[] = [];
  for (let i = 0; i < firstDayOfWeek; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(new Date(year, month, d));
  while (cells.length < 42) cells.push(null);

  // 手机端：仅展示有事件的日期（过滤掉 null 和无事件日期），避免长列表空白
  const mobileDays = cells.filter((d): d is Date => d !== null);

  return (
    <div className="flex flex-col h-full">
      {/* 头部：导航 */}
      <div className="flex items-center justify-between mb-[var(--space-4)] px-[var(--space-2)]">
        <div className="flex items-center gap-[var(--space-2)]">
          <button
            onClick={onPrev}
            className="p-1 rounded-[var(--radius-sm)] cursor-pointer"
            style={{ color: "var(--muted)", border: "1px solid var(--border)" }}
            aria-label="previous month"
          >
            <ChevronLeft size={14} />
          </button>
          <button
            onClick={onNext}
            className="p-1 rounded-[var(--radius-sm)] cursor-pointer"
            style={{ color: "var(--muted)", border: "1px solid var(--border)" }}
            aria-label="next month"
          >
            <ChevronRight size={14} />
          </button>
          <button
            onClick={onToday}
            className="px-[var(--space-3)] py-1 rounded-[var(--radius-sm)] text-[length:var(--text-sm)] cursor-pointer"
            style={{ color: "var(--fg)", border: "1px solid var(--border)" }}
          >
            {t("today")}
          </button>
        </div>
        <h2 className="text-[length:var(--text-lg)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
          {t("monthYear", { year, month: month + 1 })}
        </h2>
      </div>

      {/* 星期标题 — 仅 sm 以上显示 */}
      <div className="hidden sm:grid grid-cols-7 mb-1">
        {weekHeaders.map((h) => (
          <div
            key={h}
            className="text-center text-[length:var(--text-sm)] py-[var(--space-2)] text-[var(--muted)]"
          >
            {h}
          </div>
        ))}
      </div>

      {/* 手机端：单列日列表视图 */}
      <div className="sm:hidden flex-1 overflow-y-auto flex flex-col gap-[var(--space-2)]">
        {mobileDays.map((date) => {
          const dayEvents = getEventsOnDate(events, date);
          const isToday = isSameDay(date, today);
          return (
            <div
              key={date.toISOString()}
              className="flex items-start gap-[var(--space-3)] p-[var(--space-3)] rounded-[var(--radius-md)] cursor-pointer"
              style={{
                background: "var(--surface)",
                border: "1px solid var(--border)",
              }}
              onClick={() => onDayClick(date)}
            >
              {/* 日期标签 */}
              <div className="flex flex-col items-center shrink-0 w-12">
                <span className="text-[length:var(--text-xs)] text-[var(--muted)]">
                  {weekHeaders[date.getDay()]}
                </span>
                <span
                  className="text-[length:var(--text-lg)] font-[weight:var(--weight-semibold)] w-8 h-8 flex items-center justify-center rounded-full mt-1"
                  style={
                    isToday
                      ? { background: "var(--accent)", color: "var(--accent-fg)" }
                      : { color: "var(--fg)" }
                  }
                >
                  {date.getDate()}
                </span>
              </div>
              {/* 事件列表 */}
              <div className="flex-1 flex flex-col gap-1 min-w-0">
                {dayEvents.length === 0 ? (
                  <span className="text-[length:var(--text-xs)] text-[var(--muted)] opacity-50">
                    {t("noEvents")}
                  </span>
                ) : (
                  dayEvents.slice(0, 4).map((event) => (
                    <div
                      key={event.id}
                      className="text-[length:var(--text-sm)] px-[var(--space-2)] py-1 rounded-[var(--radius-sm)] truncate cursor-pointer flex items-center gap-1"
                      style={{
                        background: `color-mix(in srgb, ${getEventColor(event)} 20%, var(--surface))`,
                        color: getEventColor(event),
                      }}
                      onClick={(e) => {
                        e.stopPropagation();
                        onEventClick(event);
                      }}
                    >
                      {isTaskDeadline(event) && <CheckCircle2 size={12} className="shrink-0" />}
                      <span className="truncate">{event.title}</span>
                    </div>
                  ))
                )}
                {dayEvents.length > 4 && (
                  <span className="text-[length:var(--text-xs)] text-[var(--muted)]">
                    +{dayEvents.length - 4}
                  </span>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {/* sm 以上：7列网格 */}
      <div className="hidden sm:grid grid-cols-7 grid-rows-6 gap-px flex-1" style={{ background: "var(--border)" }}>
        {cells.map((date, i) => {
          if (!date) {
            return (
              <div
                key={i}
                className="p-1 min-h-[80px]"
                style={{ background: "var(--surface)" }}
              />
            );
          }
          const dayEvents = getEventsOnDate(events, date);
          const isToday = isSameDay(date, today);
          return (
            <div
              key={i}
              className="p-1 min-h-[80px] flex flex-col gap-1 cursor-pointer overflow-hidden"
              style={{ background: "var(--surface)" }}
              onClick={() => onDayClick(date)}
            >
              <span
                className="text-[length:var(--text-sm)] w-6 h-6 flex items-center justify-center rounded-full"
                style={
                  isToday
                    ? { background: "var(--accent)", color: "var(--accent-fg)" }
                    : { color: "var(--fg)" }
                }
              >
                {date.getDate()}
              </span>
              {dayEvents.slice(0, 3).map((event) => (
                <div
                  key={event.id}
                  className="text-[length:var(--text-xs)] px-1 py-0.5 rounded-[var(--radius-sm)] truncate cursor-pointer flex items-center gap-1"
                  style={{
                    background: `color-mix(in srgb, ${getEventColor(event)} 20%, var(--surface))`,
                    color: getEventColor(event),
                  }}
                  onClick={(e) => {
                    e.stopPropagation();
                    onEventClick(event);
                  }}
                >
                  {isTaskDeadline(event) && <CheckCircle2 size={10} className="shrink-0" />}
                  <span className="truncate">{event.title}</span>
                </div>
              ))}
              {dayEvents.length > 3 && (
                <span className="text-[length:var(--text-xs)] text-[var(--muted)]">
                  +{dayEvents.length - 3}
                </span>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client";

// 保持 "use client"：接收 4 个函数 props（onPrev/onNext/onToday/onEventClick），
// 这些回调来自 client 父组件 (CalendarView.tsx)，无法跨越 server/client 边界传递。
// CalendarView 管理所有日历状态（currentDate/events/dialogOpen），本组件仅做展示 + 回调转发。

import { useState } from "react";
import { useTranslations } from "next-intl";
import { ChevronLeft, ChevronRight, CheckCircle2 } from "lucide-react";
import type { CalendarEvent } from "./CalendarEventDialog";
import { getEventsOnDate, getEventColor, isSameDay, getWeekDays, formatTime, isTaskDeadline } from "./calendar-utils";

/** 周视图公共 props */
interface CalendarWeekProps {
  events: CalendarEvent[];
  currentDate: Date;
  onPrev: () => void;
  onNext: () => void;
  onToday: () => void;
  onEventClick: (event: CalendarEvent) => void;
}

/**
 * CalendarWeek — 周视图组件。
 * 显示当前周的 7 天，每天一列，事件按时间排列。
 * 支持点击事件打开编辑弹窗，上下周导航。
 */
export function CalendarWeek({
  events,
  currentDate,
  onPrev,
  onNext,
  onToday,
  onEventClick,
}: CalendarWeekProps) {
  const t = useTranslations("calendar");
  const today = new Date();
  const weekDays = getWeekDays(currentDate);
  // 手机端：当前显示的天索引（0-6），默认定位到今天或第一天
  const [mobileDayIndex, setMobileDayIndex] = useState(() => {
    const todayIdx = weekDays.findIndex((d) => isSameDay(d, today));
    return todayIdx >= 0 ? todayIdx : 0;
  });

  const weekHeaders = [
    t("sunday"), t("monday"), t("tuesday"), t("wednesday"),
    t("thursday"), t("friday"), t("saturday"),
  ];

  // 手机端切换日期时重置索引
  const handleMobilePrev = () => {
    setMobileDayIndex((i) => Math.max(0, i - 1));
  };
  const handleMobileNext = () => {
    setMobileDayIndex((i) => Math.min(6, i + 1));
  };

  return (
    <div className="flex flex-col h-full">
      {/* 头部：导航 */}
      <div className="flex items-center justify-between mb-[var(--space-4)] px-[var(--space-2)]">
        <div className="flex items-center gap-[var(--space-2)]">
          <button
            onClick={onPrev}
            className="p-1 rounded-[var(--radius-sm)] cursor-pointer"
            style={{ color: "var(--muted)", border: "1px solid var(--border)" }}
            aria-label="previous week"
          >
            <ChevronLeft size={14} />
          </button>
          <button
            onClick={onNext}
            className="p-1 rounded-[var(--radius-sm)] cursor-pointer"
            style={{ color: "var(--muted)", border: "1px solid var(--border)" }}
            aria-label="next week"
          >
            <ChevronRight size={14} />
          </button>
          <button
            onClick={onToday}
            className="px-[var(--space-3)] py-1 rounded-[var(--radius-sm)] text-[length:var(--text-sm)] cursor-pointer"
            style={{ color: "var(--fg)", border: "1px solid var(--border)" }}
          >
            {t("today")}
          </button>
        </div>
        <h2 className="text-[length:var(--text-lg)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
          {weekDays[0].getFullYear()}年 {weekDays[0].getMonth() + 1}月{weekDays[0].getDate()}日 - {weekDays[6].getMonth() + 1}月{weekDays[6].getDate()}日
        </h2>
      </div>

      {/* 手机端：单日滚动视图 */}
      <div className="sm:hidden flex-1 flex flex-col overflow-hidden">
        {/* 手机端日期切换条 */}
        <div className="flex items-center justify-between mb-[var(--space-2)] px-[var(--space-2)]">
          <button
            onClick={handleMobilePrev}
            disabled={mobileDayIndex === 0}
            className="p-1 rounded-[var(--radius-sm)] cursor-pointer disabled:opacity-30 disabled:cursor-not-allowed"
            style={{ color: "var(--muted)", border: "1px solid var(--border)" }}
            aria-label="previous day in week"
          >
            <ChevronLeft size={14} />
          </button>
          <span className="text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg)]">
            {weekHeaders[mobileDayIndex]} · {weekDays[mobileDayIndex].getMonth() + 1}/{weekDays[mobileDayIndex].getDate()}
          </span>
          <button
            onClick={handleMobileNext}
            disabled={mobileDayIndex === 6}
            className="p-1 rounded-[var(--radius-sm)] cursor-pointer disabled:opacity-30 disabled:cursor-not-allowed"
            style={{ color: "var(--muted)", border: "1px solid var(--border)" }}
            aria-label="next day in week"
          >
            <ChevronRight size={14} />
          </button>
        </div>
        {/* 手机端当天事件列表 */}
        <div className="flex-1 overflow-y-auto p-[var(--space-2)] flex flex-col gap-[var(--space-2)]">
          {(() => {
            const date = weekDays[mobileDayIndex];
            const dayEvents = getEventsOnDate(events, date);
            const isToday = isSameDay(date, today);
            if (dayEvents.length === 0) {
              return (
                <div className="flex items-center justify-center h-32 text-[length:var(--text-sm)] text-[var(--muted)]">
                  {t("noEvents")}
                </div>
              );
            }
            return dayEvents.map((event) => (
              <div
                key={event.id}
                className="px-[var(--space-3)] py-[var(--space-2)] rounded-[var(--radius-md)] cursor-pointer"
                style={{
                  background: `color-mix(in srgb, ${getEventColor(event)} 15%, var(--surface))`,
                  color: "var(--fg)",
                  borderLeft: `3px solid ${getEventColor(event)}`,
                }}
                onClick={() => onEventClick(event)}
              >
                <div className="font-[weight:var(--weight-medium)] text-[length:var(--text-sm)] flex items-center gap-1">
                  {isTaskDeadline(event) && <CheckCircle2 size={14} className="shrink-0" style={{ color: getEventColor(event) }} />}
                  <span className="truncate">{event.title}</span>
                </div>
                {!event.allDay && (
                  <div className="text-[length:var(--text-xs)] text-[var(--muted)] mt-1">
                    {formatTime(new Date(event.startAt))} - {formatTime(new Date(event.endAt))}
                  </div>
                )}
              </div>
            ));
          })()}
        </div>
      </div>

      {/* sm 以上：7列网格 */}
      <div className="hidden sm:grid grid-cols-7 gap-px flex-1" style={{ background: "var(--border)" }}>
        {weekDays.map((date, i) => {
          const dayEvents = getEventsOnDate(events, date);
          const isToday = isSameDay(date, today);
          return (
            <div
              key={i}
              className="flex flex-col overflow-hidden"
              style={{ background: "var(--surface)" }}
            >
              {/* 日期标题 */}
              <div
                className="text-center py-[var(--space-2)] border-b"
                style={{ borderColor: "var(--border)" }}
              >
                <div className="text-[length:var(--text-sm)] text-[var(--muted)]">
                  {weekHeaders[i]}
                </div>
                <div
                  className="text-[length:var(--text-lg)] font-[weight:var(--weight-semibold)] w-8 h-8 mx-auto flex items-center justify-center rounded-full mt-1"
                  style={
                    isToday
                      ? { background: "var(--accent)", color: "var(--accent-fg)" }
                      : { color: "var(--fg)" }
                  }
                >
                  {date.getDate()}
                </div>
              </div>
              {/* 事件列表 */}
              <div className="flex-1 overflow-y-auto p-1 flex flex-col gap-1">
                {dayEvents.length === 0 ? (
                  <span className="text-[length:var(--text-xs)] text-[var(--muted)] opacity-50 text-center mt-2">
                    {t("noEvents")}
                  </span>
                ) : (
                  dayEvents.map((event) => (
                    <div
                      key={event.id}
                      className="text-[length:var(--text-xs)] px-[var(--space-2)] py-1 rounded-[var(--radius-sm)] cursor-pointer"
                      style={{
                        background: `color-mix(in srgb, ${getEventColor(event)} 15%, var(--surface))`,
                        color: "var(--fg)",
                        borderLeft: `3px solid ${getEventColor(event)}`,
                      }}
                      onClick={() => onEventClick(event)}
                    >
                      <div className="font-[weight:var(--weight-medium)] truncate flex items-center gap-1">
                        {isTaskDeadline(event) && <CheckCircle2 size={12} className="shrink-0" style={{ color: getEventColor(event) }} />}
                        <span className="truncate">{event.title}</span>
                      </div>
                      {!event.allDay && (
                        <div className="text-[var(--muted)]">
                          {formatTime(new Date(event.startAt))} - {formatTime(new Date(event.endAt))}
                        </div>
                      )}
                    </div>
                  ))
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client";

/**
 * 聊天面板标题栏 + 搜索按钮 + 在线状态栏
 *
 * - 标题区：💬 聊天 + 消息计数
 * - 搜索按钮：点击展开搜索框
 * - 在线状态栏：在线成员头像列表（绿点指示）
 *
 * 拆分说明：ChatHeader 保持 client component（被 ChatPanel client 引用），
 * 搜索交互逻辑委托给 ChatHeaderClient 子组件。
 */

import { MessageCircle } from "lucide-react";
import { useTranslations } from "next-intl";
import type { Person } from "./types";
import { ChatHeaderClient } from "./ChatHeaderClient";

interface ChatHeaderProps {
  /** 消息总数 */
  messageCount: number;
  /** 在线用户 ID 集合 */
  onlineUsers: Set<string>;
  /** 工作区成员列表（用于显示在线头像） */
  members: Person[];
  /** 搜索关键词 */
  searchQuery: string;
  /** 搜索关键词变更 */
  onSearchChange: (query: string) => void;
  /** 搜索框是否展开 */
  searchOpen: boolean;
  /** 切换搜索框展开状态 */
  onToggleSearch: () => void;
}

export function ChatHeader({
  messageCount,
  onlineUsers,
  members,
  searchQuery,
  onSearchChange,
  searchOpen,
  onToggleSearch,
}: ChatHeaderProps) {
  const t = useTranslations("chat");

  // 在线成员列表（按 onlineUsers 过滤）
  const onlineMembers = members.filter((m) => onlineUsers.has(m.id));

  return (
    <div className="mb-[var(--space-3)]">
      {/* 标题行 + 搜索按钮 + 搜索框（client 子组件渲染交互部分） */}
      <ChatHeaderClient
        messageCount={messageCount}
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
        searchOpen={searchOpen}
        onToggleSearch={onToggleSearch}
        titleLabel={t("title")}
        searchLabel={t("search")}
      />

      {/* 在线状态栏 */}
      {onlineMembers.length > 0 && (
        <div className="flex items-center gap-[var(--space-2)] flex-wrap">
          <span className="text-[length:var(--text-xs)] text-[var(--meta)]">{t("online")}</span>
          {onlineMembers.slice(0, 5).map((m) => (
            <div key={m.id} className="relative shrink-0" title={m.name || m.email}>
              <div className="w-6 h-6 rounded-full bg-[var(--surface-3)] text-[var(--fg-2)] flex items-center justify-center text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] overflow-hidden">
                {m.image ? (
                  // eslint-disable-next-line @next/next/no-img-element
                  <img
                    src={m.image}
                    alt={m.name || m.email}
                    className="w-full h-full object-cover"
                  />
                ) : (
                  (m.name || m.email)[0]?.toUpperCase()
                )}
              </div>
              {/* 在线绿点 */}
              <span className="absolute -bottom-0.5 -right-0.5 w-2 h-2 rounded-full bg-[var(--accent-success)] ring-2 ring-[var(--surface)]" />
            </div>
          ))}
          {onlineMembers.length > 5 && (
            <span className="text-[length:var(--text-xs)] text-[var(--meta)]">
              +{onlineMembers.length - 5}
            </span>
          )}
        </div>
      )}
    </div>
  );
}

"use client";

import {
  memo,
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type DragEvent,
  type KeyboardEvent,
  type ChangeEvent,
} from "react";
import { Send, Loader2, Paperclip, X, AtSign, Upload } from "lucide-react";
import { useTranslations } from "next-intl";
import type { AttachmentMeta, Person } from "./types";

/**
 * 消息输入区域
 *
 * - 文件按钮：📎 点击选择文件（≤10MB），上传后显示待发送附件预览
 * - 文本框：自动高度，⌘/Ctrl + Enter 发送
 * - 发送按钮：禁用状态（空文本 + 无附件时）
 * - 待发送附件预览：图片缩略图 / 文件名 + 移除按钮
 * - @提及：输入 @ 触发成员选择浮窗，选择后插入 @username
 * - 拖拽上传：拖文件到输入区直接上传（复用 onUploadFile）
 *
 * memo：ChatPanel 每收到一条 SSE 推送就重渲染整棵树；不隔离时 textarea
 * 会随之重建，用户正在输入的 draft 被受控 value 重置（输入吞字）。
 * props 均为稳定的回调/标量，memo 可安全跳过无关重渲染。
 */

interface MessageInputProps {
  /** 发送消息（文本 + 附件元数据） */
  onSend: (body: string, attachments: AttachmentMeta[]) => Promise<void>;
  /** 上传文件（返回附件元数据） */
  onUploadFile: (file: File) => Promise<AttachmentMeta>;
  /** 是否正在发送 */
  sending: boolean;
  /** 附件上传端点 URL */
  uploadUrl: string;
  /** 工作区成员列表（用于 @提及；不传则禁用提及） */
  members?: Person[];
}

/** 消息体最大长度（与 API zod schema 对齐） */
const MAX_BODY_LENGTH = 10000;
/** 最大文件大小：10MB */
const MAX_FILE_SIZE = 10 * 1024 * 1024;
/** @提及浮窗最大显示成员数 */
const MENTION_MAX_ITEMS = 8;

/** 在 textarea 光标位置插入文本，并返回新光标位置 */
function insertAtCursor(el: HTMLTextAreaElement, text: string): number {
  const start = el.selectionStart ?? el.value.length;
  const end = el.selectionEnd ?? el.value.length;
  const next = el.value.slice(0, start) + text + el.value.slice(end);
  // 截断到最大长度
  const capped = next.slice(0, MAX_BODY_LENGTH);
  el.value = capped;
  const pos = Math.min(start + text.length, capped.length);
  el.setSelectionRange(pos, pos);
  return pos;
}

function MessageInputImpl({
  onSend,
  onUploadFile,
  sending,
  members,
}: MessageInputProps) {
  const t = useTranslations("chat");
  const [draft, setDraft] = useState("");
  const [pendingAttachments, setPendingAttachments] = useState<AttachmentMeta[]>([]);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState("");
  // @提及状态
  const [mentionOpen, setMentionOpen] = useState(false);
  const [mentionQuery, setMentionQuery] = useState("");
  const [mentionActive, setMentionActive] = useState(0);
  // @触发起始位置（@ 字符的 index）
  const mentionStartRef = useRef<number>(-1);
  // 拖拽状态
  const [dragOver, setDragOver] = useState(false);

  const draftRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const rootRef = useRef<HTMLDivElement>(null);

  // 输入框自动高度
  useEffect(() => {
    const el = draftRef.current;
    if (el) {
      el.style.height = "auto";
      el.style.height = el.scrollHeight + "px";
    }
  }, [draft]);

  /** 同步 draft state（非受控 textarea 的 onChange 仅同步 state 用于 canSend 判定） */
  const syncDraft = useCallback(() => {
    const el = draftRef.current;
    if (el) setDraft(el.value);
  }, []);

  /** 上传单个文件并加入待发送列表 */
  const uploadAndAppend = useCallback(
    async (file: File) => {
      if (file.size > MAX_FILE_SIZE) {
        setError(t("fileTooLarge"));
        return;
      }
      setError("");
      setUploading(true);
      try {
        const meta = await onUploadFile(file);
        const previewMeta =
          file.type.startsWith("image/") && meta.thumbnailUrl
            ? { ...meta, thumbnailUrl: URL.createObjectURL(file) }
            : meta;
        setPendingAttachments((prev) => [...prev, previewMeta]);
      } catch (err) {
        setError(err instanceof Error ? err.message : t("uploadFailed"));
      } finally {
        setUploading(false);
      }
    },
    [onUploadFile, t],
  );

  /** 选择文件 */
  const handleFileSelect = useCallback(
    async (e: ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      e.target.value = "";
      await uploadAndAppend(file);
    },
    [uploadAndAppend],
  );

  /** 移除待发送附件 */
  const removeAttachment = useCallback((index: number) => {
    setPendingAttachments((prev) => {
      const removed = prev[index];
      if (removed?.thumbnailUrl?.startsWith("blob:")) {
        URL.revokeObjectURL(removed.thumbnailUrl);
      }
      return prev.filter((_, i) => i !== index);
    });
  }, []);

  /** 发送 */
  const send = useCallback(async () => {
    const trimmed = draft.trim();
    if ((!trimmed && pendingAttachments.length === 0) || sending) return;

    const body = trimmed || (pendingAttachments.length > 0 ? t("attachmentFallback") : "");

    await onSend(body, pendingAttachments);
    pendingAttachments.forEach((a) => {
      if (a.thumbnailUrl?.startsWith("blob:")) URL.revokeObjectURL(a.thumbnailUrl);
    });
    setDraft("");
    setPendingAttachments([]);
    setMentionOpen(false);
    if (draftRef.current) draftRef.current.value = "";
  }, [draft, pendingAttachments, sending, onSend, t]);

  /** 提及候选列表（按 query 过滤成员，排除无 name 的） */
  const mentionCandidates = (() => {
    if (!members || members.length === 0) return [] as Person[];
    const q = mentionQuery.toLowerCase();
    return members
      .filter((m) => {
        const name = m.name || m.email.split("@")[0];
        return name.toLowerCase().includes(q);
      })
      .slice(0, MENTION_MAX_ITEMS);
  })();

  /** 关闭提及浮窗 */
  const closeMention = useCallback(() => {
    setMentionOpen(false);
    setMentionQuery("");
    setMentionActive(0);
    mentionStartRef.current = -1;
  }, []);

  /** 选择某个成员插入 @mention */
  const pickMention = useCallback(
    (person: Person) => {
      const el = draftRef.current;
      if (!el) return;
      const name = person.name || person.email.split("@")[0];
      const start = mentionStartRef.current;
      // 替换从 @ 触发点到当前光标的内容为 "@name "
      const cursor = el.selectionStart ?? el.value.length;
      const before = start >= 0 ? el.value.slice(0, start) : el.value.slice(0, cursor);
      const after = el.value.slice(cursor);
      const insertText = `@${name} `;
      const next = (before + insertText + after).slice(0, MAX_BODY_LENGTH);
      el.value = next;
      const pos = Math.min(before.length + insertText.length, next.length);
      el.setSelectionRange(pos, pos);
      setDraft(next);
      closeMention();
      el.focus();
    },
    [closeMention],
  );

  /** 检测 @提及触发：onChange 时分析光标前的文本 */
  const detectMention = useCallback(() => {
    const el = draftRef.current;
    if (!el || !members || members.length === 0) {
      closeMention();
      return;
    }
    const pos = el.selectionStart ?? el.value.length;
    const before = el.value.slice(0, pos);
    // 找最后一个未闭合的 @：从光标往前找 @，中间不能有空格/换行
    const atIdx = before.lastIndexOf("@");
    if (atIdx < 0) {
      closeMention();
      return;
    }
    // @ 必须在行首或前面是空白
    const charBefore = atIdx > 0 ? before[atIdx - 1] : "";
    if (charBefore && !/\s/.test(charBefore)) {
      closeMention();
      return;
    }
    const query = before.slice(atIdx + 1);
    // query 中不能有空格/换行（否则视为普通文本）
    if (/\s/.test(query)) {
      closeMention();
      return;
    }
    mentionStartRef.current = atIdx;
    setMentionQuery(query);
    setMentionOpen(true);
    setMentionActive(0);
  }, [members, closeMention]);

  /** 键盘事件 */
  const handleKeyDown = useCallback(
    (e: KeyboardEvent<HTMLTextAreaElement>) => {
      // 提及浮窗导航
      if (mentionOpen && mentionCandidates.length > 0) {
        if (e.key === "ArrowDown") {
          e.preventDefault();
          setMentionActive((prev) => (prev + 1) % mentionCandidates.length);
          return;
        }
        if (e.key === "ArrowUp") {
          e.preventDefault();
          setMentionActive(
            (prev) => (prev - 1 + mentionCandidates.length) % mentionCandidates.length,
          );
          return;
        }
        if (e.key === "Enter" || e.key === "Tab") {
          e.preventDefault();
          const target = mentionCandidates[mentionActive];
          if (target) pickMention(target);
          return;
        }
        if (e.key === "Escape") {
          e.preventDefault();
          closeMention();
          return;
        }
      }
      if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
        e.preventDefault();
        send();
      }
    },
    [mentionOpen, mentionCandidates, mentionActive, pickMention, closeMention, send],
  );

  /** 拖拽上传处理 */
  const handleDragOver = useCallback((e: DragEvent<HTMLDivElement>) => {
    // 仅当拖入文件时才阻止默认行为并显示遮罩
    if (e.dataTransfer.types.includes("Files")) {
      e.preventDefault();
      e.dataTransfer.dropEffect = "copy";
      if (!dragOver) setDragOver(true);
    }
  }, [dragOver]);

  const handleDragLeave = useCallback((e: DragEvent<HTMLDivElement>) => {
    // 仅当离开根容器时才关闭遮罩（避免子元素切换闪烁）
    if (e.relatedTarget && rootRef.current?.contains(e.relatedTarget as Node)) return;
    setDragOver(false);
  }, []);

  const handleDrop = useCallback(
    async (e: DragEvent<HTMLDivElement>) => {
      if (!e.dataTransfer.types.includes("Files")) return;
      e.preventDefault();
      setDragOver(false);
      const files = Array.from(e.dataTransfer.files);
      if (files.length === 0) return;
      // 串行上传，避免并发超出附件端点限制
      for (const file of files) {
        await uploadAndAppend(file);
      }
    },
    [uploadAndAppend],
  );

  // 点击外部关闭提及浮窗
  useEffect(() => {
    if (!mentionOpen) return;
    const onDocClick = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) {
        closeMention();
      }
    };
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, [mentionOpen, closeMention]);

  // 提及浮窗定位（基于 @ 字符位置）
  const [mentionPos, setMentionPos] = useState<{ top: number; left: number }>({ top: 0, left: 0 });
  useLayoutEffect(() => {
    if (!mentionOpen) return;
    const el = draftRef.current;
    if (!el) return;
    // 简化定位：浮窗显示在 textarea 上方左侧
    const rect = el.getBoundingClientRect();
    const rootRect = rootRef.current?.getBoundingClientRect();
    setMentionPos({
      top: rect.top - (rootRect?.top ?? 0) - 8,
      left: rect.left - (rootRect?.left ?? 0),
    });
  }, [mentionOpen]);

  const canSend = (draft.trim() || pendingAttachments.length > 0) && !sending;

  return (
    <div
      ref={rootRef}
      className="mt-[var(--space-2)] relative"
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      {/* 拖拽上传遮罩 */}
      {dragOver && (
        <div className="absolute inset-0 z-20 flex items-center justify-center rounded-[var(--radius-md)] border-2 border-dashed border-[var(--accent)] bg-[var(--accent-soft)] pointer-events-none">
          <div className="flex items-center gap-2 text-[length:var(--text-sm)] text-[var(--accent)] font-[weight:var(--weight-medium)]">
            <Upload size={16} />
            {t("dropFileHint")}
          </div>
        </div>
      )}

      {/* @提及浮窗 */}
      {mentionOpen && mentionCandidates.length > 0 && (
        <div
          className="absolute z-30 min-w-[180px] max-w-[240px] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] shadow-[var(--elev-md)] overflow-hidden"
          style={{ top: mentionPos.top, left: mentionPos.left }}
          role="listbox"
          aria-label={t("mentionAria")}
        >
          {mentionCandidates.map((m, i) => {
            const name = m.name || m.email.split("@")[0];
            const initial = (m.name || m.email)[0]?.toUpperCase();
            return (
              <button
                key={m.id}
                type="button"
                role="option"
                aria-selected={i === mentionActive}
                onMouseDown={(e) => {
                  e.preventDefault();
                  pickMention(m);
                }}
                onMouseEnter={() => setMentionActive(i)}
                className={`w-full flex items-center gap-2 px-2.5 py-1.5 text-left text-[length:var(--text-sm)] transition-colors duration-[var(--motion-fast)] ${
                  i === mentionActive
                    ? "bg-[var(--surface-2)] text-[var(--fg)]"
                    : "text-[var(--fg-2)] hover:bg-[var(--surface-2)]"
                }`}
              >
                <span className="w-5 h-5 shrink-0 rounded-full bg-[var(--surface-3)] flex items-center justify-center text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] overflow-hidden">
                  {m.image ? (
                    // eslint-disable-next-line @next/next/no-img-element
                    <img src={m.image} alt={name} className="w-full h-full object-cover" />
                  ) : (
                    initial
                  )}
                </span>
                <span className="min-w-0 flex-1 truncate">{name}</span>
              </button>
            );
          })}
        </div>
      )}

      {/* 错误提示 */}
      {error && (
        <div className="mb-1.5 px-2 py-1 rounded-[var(--radius-sm)] bg-[var(--danger-soft)] text-[var(--danger-fg)] text-[length:var(--text-xs)]">
          {error}
        </div>
      )}

      {/* 待发送附件预览 */}
      {pendingAttachments.length > 0 && (
        <div className="mb-1.5 flex gap-1.5 flex-wrap">
          {pendingAttachments.map((att, i) => (
            <div
              key={i}
              className="relative flex items-center gap-1.5 px-2 py-1 rounded-[var(--radius-sm)] bg-[var(--surface-2)] border border-[var(--border)]"
            >
              {att.thumbnailUrl ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img
                  src={att.thumbnailUrl}
                  alt={att.fileName}
                  className="w-8 h-8 object-cover rounded-[var(--radius-sm)]"
                />
              ) : (
                <div className="w-8 h-8 flex items-center justify-center rounded-[var(--radius-sm)] bg-[var(--surface-3)]">
                  <Paperclip size={14} className="text-[var(--muted)]" />
                </div>
              )}
              <span className="text-[length:var(--text-xs)] text-[var(--fg-2)] max-w-[120px] truncate">
                {att.fileName}
              </span>
              <button
                onClick={() => removeAttachment(i)}
                className="shrink-0 w-4 h-4 flex items-center justify-center rounded-full hover:bg-[var(--surface-3)] text-[var(--meta)]"
                aria-label={t("removeAttachment")}
              >
                <X size={14} />
              </button>
            </div>
          ))}
        </div>
      )}

      {/* 输入区 */}
      <div className="flex items-end gap-[var(--space-2)]">
        {/* 文件按钮 */}
        <button
          onClick={() => fileInputRef.current?.click()}
          disabled={uploading || sending}
          aria-label={t("attachFile")}
          className="shrink-0 w-9 h-9 flex items-center justify-center rounded-[var(--radius-md)] text-[var(--muted)] hover:bg-[var(--surface-2)] hover:text-[var(--fg)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-[var(--motion-fast)]"
        >
          {uploading ? <Loader2 size={16} className="animate-spin" /> : <Paperclip size={16} />}
        </button>
        <input
          ref={fileInputRef}
          type="file"
          onChange={handleFileSelect}
          className="hidden"
          accept="image/jpeg,image/png,image/gif,image/webp,application/pdf,.doc,.docx,.xls,.xlsx,.zip"
        />

        {/* 文本框：非受控（不绑 value）。受控 value 在 SSE 高频推送的滞后渲染
            中会用旧 draft 覆盖用户刚输入的文本（发送后 300ms 内的渲染即复现）；
            非受控 + onChange 同步 draft state（仅用于 canSend 判定）消除该竞争 */}
        <div className="flex-1 relative">
          <textarea
            ref={draftRef}
            onChange={(e) => {
              setDraft(e.target.value.slice(0, MAX_BODY_LENGTH));
              detectMention();
            }}
            onKeyDown={handleKeyDown}
            onBlur={syncDraft}
            rows={1}
            maxLength={MAX_BODY_LENGTH}
            placeholder={t("placeholder")}
            className="w-full px-[var(--space-3)] py-[var(--space-2)] overflow-hidden resize-none border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface-2)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:border-[var(--accent)] placeholder:text-[var(--meta)] transition-colors duration-[var(--motion-fast)]"
          />
          {/* @提及提示按钮（无 members 时隐藏） */}
          {members && members.length > 0 && (
            <button
              type="button"
              onClick={() => {
                const el = draftRef.current;
                if (!el) return;
                el.focus();
                const pos = el.selectionStart ?? el.value.length;
                const before = el.value.slice(0, pos);
                const after = el.value.slice(pos);
                const needSpace = pos > 0 && !/\s$/.test(before);
                const insert = needSpace ? " @" : "@";
                const next = (before + insert + after).slice(0, MAX_BODY_LENGTH);
                el.value = next;
                const newPos = Math.min(pos + insert.length, next.length);
                el.setSelectionRange(newPos, newPos);
                setDraft(next);
                mentionStartRef.current = pos + (needSpace ? 1 : 0);
                setMentionQuery("");
                setMentionOpen(true);
                setMentionActive(0);
              }}
              disabled={sending}
              aria-label={t("mentionAria")}
              className="absolute right-2 bottom-2 w-6 h-6 flex items-center justify-center rounded-[var(--radius-sm)] text-[var(--meta)] hover:text-[var(--accent)] hover:bg-[var(--surface-3)] disabled:opacity-40 transition-colors duration-[var(--motion-fast)]"
            >
              <AtSign size={14} />
            </button>
          )}
        </div>

        {/* 发送按钮（aria-label 区分评论表单的"发送"按钮——两者同页面共存） */}
        <button
          onClick={send}
          disabled={!canSend}
          aria-label={t("sendAria")}
          className="h-9 px-[var(--space-3)] shrink-0 bg-[var(--accent)] text-[var(--accent-fg)] rounded-[var(--radius-md)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] active:bg-[var(--accent-active)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-[var(--motion-base)] flex items-center gap-1.5"
        >
          {sending ? <Loader2 size={16} className="animate-spin" /> : <Send size={16} />}
          {t("send")}
        </button>
      </div>
    </div>
  );
}

export const MessageInput = memo(MessageInputImpl);

"use client";

/**
 * 联系人详情/编辑面板 · ContactDetail
 *
 * 显示联系人所有字段，支持内联编辑与删除。
 * 数据流：contactId 变化时拉 GET /contacts/{cid}；编辑 PATCH；删除 DELETE。
 */

import { useEffect, useState, type FormEvent } from "react";
import { useTranslations } from "next-intl";
import {
  X,
  Loader2,
  Save,
  Trash2,
  Mail,
  Phone,
  Building2,
  Briefcase,
  FileText,
  User,
} from "lucide-react";
import { api } from "@/lib/api";
import type { ContactDetail, ContactGroupItem } from "./types";

export function ContactDetail({
  wid,
  contactId,
  onClose,
  onDeleted,
  onUpdated,
}: {
  wid: string;
  contactId: string;
  onClose: () => void;
  onDeleted: (id: string) => void;
  onUpdated: (contact: ContactDetail) => void;
}) {
  const t = useTranslations("contact");
  const tButton = useTranslations("button");
  const [contact, setContact] = useState<ContactDetail | null>(null);
  const [groups, setGroups] = useState<ContactGroupItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [error, setError] = useState("");
  const [confirmDelete, setConfirmDelete] = useState(false);

  // 编辑表单状态
  const [form, setForm] = useState({
    name: "",
    email: "",
    phone: "",
    department: "",
    position: "",
    notes: "",
    groupId: "",
  });

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError("");
    Promise.all([
      api<ContactDetail>(`/api/v1/workspaces/${wid}/contacts/${contactId}`).catch((e) => {
        throw e;
      }),
      api<ContactGroupItem[]>(`/api/v1/workspaces/${wid}/contact-groups`).catch(() => [] as ContactGroupItem[]),
    ])
      .then(([c, g]) => {
        if (cancelled) return;
        setContact(c);
        setGroups(g);
        setForm({
          name: c.name,
          email: c.email ?? "",
          phone: c.phone ?? "",
          department: c.department ?? "",
          position: c.position ?? "",
          notes: c.notes ?? "",
          groupId: c.groupId ?? "",
        });
      })
      .catch((e) => {
        if (!cancelled) setError(e instanceof Error ? e.message : t("loadFailed"));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [wid, contactId, t]);

  async function save(e: FormEvent) {
    e.preventDefault();
    if (saving || !contact) return;
    setSaving(true);
    setError("");
    try {
      const updated = await api<ContactDetail>(
        `/api/v1/workspaces/${wid}/contacts/${contactId}`,
        {
          method: "PATCH",
          body: JSON.stringify({
            name: form.name.trim(),
            email: form.email.trim() || null,
            phone: form.phone.trim() || null,
            department: form.department.trim() || null,
            position: form.position.trim() || null,
            notes: form.notes.trim() || null,
            groupId: form.groupId || null,
          }),
        },
      );
      setContact(updated);
      setEditing(false);
      onUpdated(updated);
    } catch (err) {
      setError(err instanceof Error ? err.message : t("saveFailed"));
    } finally {
      setSaving(false);
    }
  }

  async function remove() {
    if (deleting) return;
    setDeleting(true);
    setError("");
    try {
      await api(`/api/v1/workspaces/${wid}/contacts/${contactId}`, {
        method: "DELETE",
      });
      onDeleted(contactId);
      onClose();
    } catch (err) {
      setError(err instanceof Error ? err.message : t("delete"));
    } finally {
      setDeleting(false);
      setConfirmDelete(false);
    }
  }

  const fieldLabel =
    "flex items-center gap-1.5 text-[length:var(--text-xs)] text-[var(--meta)] mb-1.5";
  const fieldValue = "text-[length:var(--text-sm)] text-[var(--fg)]";
  const fieldControl =
    "w-full h-9 px-2.5 border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] placeholder:text-[var(--meta)]";

  return (
    <aside className="flex h-full flex-col border-l border-[var(--border)] bg-[var(--surface)]">
      {/* 头部 */}
      <header className="flex items-center justify-between px-[var(--space-4)] py-[var(--space-3)] border-b border-[var(--border-soft)]">
        <h2 className="text-[length:var(--text-md)] font-[weight:var(--weight-semibold)] text-[var(--fg)] truncate">
          {contact?.name ?? t("title")}
        </h2>
        <div className="flex items-center gap-1">
          {contact && !editing && !confirmDelete && (
            <>
              <button
                type="button"
                onClick={() => setEditing(true)}
                className="inline-flex items-center gap-1.5 h-8 px-3 rounded-[var(--radius-sm)] border border-[var(--border)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
              >
                {t("edit")}
              </button>
              <button
                type="button"
                onClick={() => setConfirmDelete(true)}
                disabled={deleting}
                className="inline-flex items-center justify-center w-8 h-8 rounded-[var(--radius-sm)] text-[var(--meta)] hover:text-[var(--danger)] hover:bg-[var(--danger-soft)] disabled:opacity-50 transition-colors duration-[var(--motion-fast)]"
                aria-label={t("delete")}
                title={t("delete")}
              >
                {deleting ? <Loader2 size={14} className="animate-spin" /> : <Trash2 size={14} />}
              </button>
            </>
          )}
          <button
            type="button"
            onClick={onClose}
            className="inline-flex items-center justify-center w-8 h-8 rounded-[var(--radius-sm)] text-[var(--muted)] hover:bg-[var(--surface-2)] hover:text-[var(--fg)] transition-colors duration-[var(--motion-fast)]"
            aria-label={tButton("close")}
          >
            <X size={16} />
          </button>
        </div>
      </header>

      {error && (
        <p className="px-[var(--space-4)] py-2 text-[length:var(--text-sm)] text-[var(--danger)]">
          {error}
        </p>
      )}

      {loading ? (
        <div className="flex-1 flex items-center justify-center text-[var(--muted)]">
          <Loader2 size={20} className="animate-spin mr-2" />
          {t("loading")}
        </div>
      ) : !contact ? (
        <div className="flex-1 flex flex-col items-center justify-center text-[var(--muted)] py-[var(--space-12)]">
          <User size={36} className="mb-3 opacity-50" />
          <p className="text-[length:var(--text-sm)]">{t("noContacts")}</p>
        </div>
      ) : confirmDelete ? (
        <div className="flex-1 flex flex-col items-center justify-center px-[var(--space-6)] text-center">
          <Trash2 size={28} className="mb-3 text-[var(--danger)]" />
          <p className="mb-4 text-[length:var(--text-sm)] text-[var(--fg)]">
            {t("confirmDelete")}
          </p>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => setConfirmDelete(false)}
              className="h-9 px-4 rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
            >
              {tButton("cancel")}
            </button>
            <button
              type="button"
              onClick={remove}
              disabled={deleting}
              className="inline-flex items-center gap-1.5 h-9 px-4 rounded-[var(--radius-md)] bg-[var(--danger)] text-[var(--danger-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:opacity-90 disabled:opacity-50 transition-opacity duration-[var(--motion-fast)]"
            >
              {deleting && <Loader2 size={14} className="animate-spin" />}
              {t("delete")}
            </button>
          </div>
        </div>
      ) : editing ? (
        <form onSubmit={save} className="flex-1 overflow-y-auto px-[var(--space-4)] py-[var(--space-4)] space-y-4">
          <div>
            <label className={fieldLabel} htmlFor="cd-name">
              <User size={13} />
              {t("name")}
            </label>
            <input
              id="cd-name"
              value={form.name}
              onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))}
              maxLength={100}
              required
              className={`${fieldControl} h-10`}
            />
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label className={fieldLabel} htmlFor="cd-email">
                <Mail size={13} />
                {t("email")}
              </label>
              <input
                id="cd-email"
                type="email"
                value={form.email}
                onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))}
                maxLength={255}
                className={fieldControl}
              />
            </div>
            <div>
              <label className={fieldLabel} htmlFor="cd-phone">
                <Phone size={13} />
                {t("phone")}
              </label>
              <input
                id="cd-phone"
                value={form.phone}
                onChange={(e) => setForm((f) => ({ ...f, phone: e.target.value }))}
                maxLength={50}
                className={fieldControl}
              />
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label className={fieldLabel} htmlFor="cd-dept">
                <Building2 size={13} />
                {t("department")}
              </label>
              <input
                id="cd-dept"
                value={form.department}
                onChange={(e) => setForm((f) => ({ ...f, department: e.target.value }))}
                maxLength={100}
                className={fieldControl}
              />
            </div>
            <div>
              <label className={fieldLabel} htmlFor="cd-pos">
                <Briefcase size={13} />
                {t("position")}
              </label>
              <input
                id="cd-pos"
                value={form.position}
                onChange={(e) => setForm((f) => ({ ...f, position: e.target.value }))}
                maxLength={100}
                className={fieldControl}
              />
            </div>
          </div>

          <div>
            <label className={fieldLabel} htmlFor="cd-group">
              {t("group")}
            </label>
            <select
              id="cd-group"
              value={form.groupId}
              onChange={(e) => setForm((f) => ({ ...f, groupId: e.target.value }))}
              className={fieldControl}
            >
              <option value="">{t("allContacts")}</option>
              {groups.map((g) => (
                <option key={g.id} value={g.id}>
                  {g.name}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label className={fieldLabel} htmlFor="cd-notes">
              <FileText size={13} />
              {t("notes")}
            </label>
            <textarea
              id="cd-notes"
              value={form.notes}
              onChange={(e) => setForm((f) => ({ ...f, notes: e.target.value }))}
              rows={4}
              className="w-full px-2.5 py-2 resize-y border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] placeholder:text-[var(--meta)]"
            />
          </div>

          <div className="flex items-center justify-end gap-2 pt-1">
            <button
              type="button"
              onClick={() => {
                setEditing(false);
                setForm({
                  name: contact.name,
                  email: contact.email ?? "",
                  phone: contact.phone ?? "",
                  department: contact.department ?? "",
                  position: contact.position ?? "",
                  notes: contact.notes ?? "",
                  groupId: contact.groupId ?? "",
                });
              }}
              className="h-9 px-4 rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
            >
              {tButton("cancel")}
            </button>
            <button
              type="submit"
              disabled={!form.name.trim() || saving}
              className="inline-flex items-center gap-1.5 h-9 px-4 bg-[var(--accent)] text-[var(--accent-fg)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-[var(--motion-base)]"
            >
              {saving ? <Loader2 size={14} className="animate-spin" /> : <Save size={14} />}
              {tButton("save")}
            </button>
          </div>
        </form>
      ) : (
        /* 只读详情 */
        <div className="flex-1 overflow-y-auto px-[var(--space-4)] py-[var(--space-4)]">
          {/* 头像 + 姓名 */}
          <div className="flex items-center gap-3 mb-[var(--space-5)]">
            <div className="shrink-0 w-16 h-16 rounded-full bg-[var(--surface-2)] border border-[var(--border-soft)] flex items-center justify-center text-[length:var(--text-xl)] font-[weight:var(--weight-semibold)] text-[var(--fg-2)]">
              {contact.avatar ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img
                  src={contact.avatar}
                  alt={contact.name}
                  className="w-full h-full rounded-full object-cover"
                />
              ) : (
                contact.name.charAt(0).toUpperCase()
              )}
            </div>
            <div className="min-w-0">
              <h3 className="text-[length:var(--text-lg)] font-[weight:var(--weight-semibold)] text-[var(--fg)] truncate">
                {contact.name}
              </h3>
              {contact.group && (
                <span className="inline-block mt-1 px-2 py-0.5 rounded-[var(--radius-sm)] bg-[var(--surface-2)] text-[length:var(--text-xs)] text-[var(--fg-2)]">
                  {contact.group.name}
                </span>
              )}
            </div>
          </div>

          <dl className="space-y-[var(--space-3)]">
            <DetailRow icon={<Mail size={14} />} label={t("email")} value={contact.email} />
            <DetailRow icon={<Phone size={14} />} label={t("phone")} value={contact.phone} />
            <DetailRow
              icon={<Building2 size={14} />}
              label={t("department")}
              value={contact.department}
            />
            <DetailRow
              icon={<Briefcase size={14} />}
              label={t("position")}
              value={contact.position}
            />
            <DetailRow
              icon={<FileText size={14} />}
              label={t("notes")}
              value={contact.notes}
              multiline
            />
          </dl>
        </div>
      )}
    </aside>
  );
}

/** 详情行：图标 + 标签 + 值；值为空时显示占位 */
function DetailRow({
  icon,
  label,
  value,
  multiline,
}: {
  icon: React.ReactNode;
  label: string;
  value: string | null;
  multiline?: boolean;
}) {
  return (
    <div>
      <dt className="flex items-center gap-1.5 text-[length:var(--text-xs)] text-[var(--meta)] mb-1">
        {icon}
        {label}
      </dt>
      <dd
        className={`text-[length:var(--text-sm)] text-[var(--fg)] ${
          multiline ? "whitespace-pre-wrap" : ""
        }`}
      >
        {value || <span className="text-[var(--muted)]">—</span>}
      </dd>
    </div>
  );
}

"use client";

/**
 * 文档权限管理面板（阶段 6 · 任务 222）
 *
 * 可嵌入到文档详情页。功能：
 *  - 显示当前文档可见性（private / workspace / shared）
 *  - 权限列表表格（用户/角色 | 权限级别 | 操作）
 *  - 添加权限表单（搜索工作区成员 + 选择权限级别）
 *
 * 数据流：
 *  - GET  /v1/workspaces/{wid}/documents/{did}/permissions  拉权限列表
 *  - POST /v1/workspaces/{wid}/documents/{did}/permissions  新增权限
 *  - PATCH /v1/workspaces/{wid}/documents/{did}/permissions/{pid}  更新权限
 *  - DELETE /v1/workspaces/{wid}/documents/{did}/permissions/{pid}  移除权限
 *  - GET  /v1/workspaces/{wid}/members  拉工作区成员（用于添加权限下拉）
 */

import { useCallback, useEffect, useState } from "react";
import { useTranslations } from "next-intl";
import {
  Loader2,
  Plus,
  Trash2,
  Shield,
  User,
  Users,
  AlertCircle,
} from "lucide-react";
import { api } from "@/lib/api";

/** 权限级别 */
type PermissionLevel = "view" | "edit" | "manage";

/** DocumentPermission 记录（与 API 返回对齐） */
interface DocPermission {
  id: string;
  documentId: string;
  workspaceId: string;
  granteeType: "user" | "role";
  granteeId: string;
  permission: PermissionLevel;
  grantedBy: string | null;
  createdAt: string;
  granter: { id: string; name: string | null; email: string } | null;
}

/** 工作区成员（用于添加权限下拉） */
interface Member {
  id: string;
  name: string | null;
  email: string;
  role: string;
}

const PERMISSION_OPTIONS: PermissionLevel[] = ["view", "edit", "manage"];

/** 权限级别 → i18n key */
function permKey(level: PermissionLevel): string {
  return level === "view"
    ? "permissionView"
    : level === "edit"
      ? "permissionEdit"
      : "permissionManage";
}

/** 授权对象显示名 */
function granteeLabel(
  perm: DocPermission,
  members: Member[],
  t: (k: string) => string,
): string {
  if (perm.granteeType === "role") {
    return perm.granteeId;
  }
  const m = members.find((x) => x.id === perm.granteeId);
  return m?.name || m?.email || perm.granteeId;
}

export function PermissionManager({
  docId,
  workspaceId,
}: {
  docId: string;
  workspaceId: string;
}) {
  const t = useTranslations("doc");
  const [permissions, setPermissions] = useState<DocPermission[]>([]);
  const [members, setMembers] = useState<Member[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);

  // 添加权限表单
  const [selectedUserId, setSelectedUserId] = useState("");
  const [selectedPerm, setSelectedPerm] = useState<PermissionLevel>("view");

  const load = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      const [permData, memberData] = await Promise.all([
        api<{ items: DocPermission[] }>(
          `/api/v1/workspaces/${workspaceId}/documents/${docId}/permissions`,
        ).catch(() => ({ items: [] as DocPermission[] })),
        api<Member[]>(`/api/v1/workspaces/${workspaceId}/members`).catch(
          () => [] as Member[],
        ),
      ]);
      setPermissions(permData.items);
      setMembers(memberData);
    } catch (e) {
      setError(e instanceof Error ? e.message : t("loadFailed"));
    } finally {
      setLoading(false);
    }
  }, [workspaceId, docId, t]);

  useEffect(() => {
    load();
  }, [load]);

  async function addPermission() {
    if (!selectedUserId || busy) return;
    setBusy(true);
    setError("");
    try {
      const created = await api<DocPermission>(
        `/api/v1/workspaces/${workspaceId}/documents/${docId}/permissions`,
        {
          method: "POST",
          body: JSON.stringify({
            granteeType: "user",
            granteeId: selectedUserId,
            permission: selectedPerm,
          }),
        },
      );
      setPermissions((prev) => [...prev, created]);
      setSelectedUserId("");
      setSelectedPerm("view");
    } catch (e) {
      setError(e instanceof Error ? e.message : t("addFailed"));
    } finally {
      setBusy(false);
    }
  }

  async function updatePermission(pid: string, level: PermissionLevel) {
    if (busy) return;
    setBusy(true);
    setError("");
    try {
      const updated = await api<DocPermission>(
        `/api/v1/workspaces/${workspaceId}/documents/${docId}/permissions/${pid}`,
        {
          method: "PATCH",
          body: JSON.stringify({ permission: level }),
        },
      );
      setPermissions((prev) =>
        prev.map((p) => (p.id === pid ? updated : p)),
      );
    } catch (e) {
      setError(e instanceof Error ? e.message : t("updateFailed"));
    } finally {
      setBusy(false);
    }
  }

  async function removePermission(pid: string) {
    if (busy) return;
    if (!window.confirm(t("removeConfirm"))) return;
    setBusy(true);
    setError("");
    try {
      await api(
        `/api/v1/workspaces/${workspaceId}/documents/${docId}/permissions/${pid}`,
        { method: "DELETE" },
      );
      setPermissions((prev) => prev.filter((p) => p.id !== pid));
    } catch (e) {
      setError(e instanceof Error ? e.message : t("removeFailed"));
    } finally {
      setBusy(false);
    }
  }

  // 已被授权的成员 ID 集合（用于下拉过滤）
  const grantedUserIds = new Set(
    permissions.filter((p) => p.granteeType === "user").map((p) => p.granteeId),
  );
  const availableMembers = members.filter((m) => !grantedUserIds.has(m.id));

  return (
    <section className="rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)]">
      <header className="flex items-center gap-2 px-[var(--space-4)] py-3 border-b border-[var(--border-soft)]">
        <Shield size={15} className="text-[var(--muted)]" />
        <h3 className="text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
          {t("permissionManagerTitle")}
        </h3>
      </header>

      <div className="px-[var(--space-4)] py-[var(--space-3)]">
        {error && (
          <div className="flex items-center gap-2 mb-[var(--space-3)] px-[var(--space-3)] py-2 rounded-[var(--radius-sm)] bg-[var(--danger-soft)] text-[var(--danger)] text-[length:var(--text-xs)]">
            <AlertCircle size={14} className="shrink-0" />
            <span className="flex-1">{error}</span>
          </div>
        )}

        {/* 权限列表表格 */}
        {loading ? (
          <div className="py-[var(--space-6)] text-center text-[var(--muted)] text-[length:var(--text-sm)]">
            <Loader2 size={16} className="inline animate-spin mr-2" />
            {t("loading")}
          </div>
        ) : permissions.length === 0 ? (
          <div className="py-[var(--space-6)] text-center text-[var(--muted)] text-[length:var(--text-sm)]">
            {t("noMembers")}
          </div>
        ) : (
          <ul className="divide-y divide-[var(--border-soft)] rounded-[var(--radius-sm)] border border-[var(--border-soft)]">
            {permissions.map((perm) => (
              <li
                key={perm.id}
                className="flex items-center gap-[var(--space-3)] px-[var(--space-3)] py-2.5"
              >
                <div className="flex items-center gap-2 flex-1 min-w-0">
                  {perm.granteeType === "role" ? (
                    <Users size={14} className="shrink-0 text-[var(--muted)]" />
                  ) : (
                    <User size={14} className="shrink-0 text-[var(--muted)]" />
                  )}
                  <span className="text-[length:var(--text-sm)] text-[var(--fg)] truncate">
                    {granteeLabel(perm, members, t)}
                  </span>
                </div>
                <select
                  value={perm.permission}
                  onChange={(e) =>
                    updatePermission(perm.id, e.target.value as PermissionLevel)
                  }
                  disabled={busy}
                  className="h-7 px-2 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-xs)] text-[var(--fg-2)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] disabled:opacity-50"
                >
                  {PERMISSION_OPTIONS.map((level) => (
                    <option key={level} value={level}>
                      {t(permKey(level))}
                    </option>
                  ))}
                </select>
                <button
                  type="button"
                  onClick={() => removePermission(perm.id)}
                  disabled={busy}
                  className="w-7 h-7 flex items-center justify-center rounded-[var(--radius-sm)] text-[var(--muted)] hover:text-[var(--danger)] hover:bg-[var(--danger-soft)] transition-colors duration-[var(--motion-fast)] disabled:opacity-50"
                  aria-label={t("removePermission")}
                  title={t("removePermission")}
                >
                  <Trash2 size={14} />
                </button>
              </li>
            ))}
          </ul>
        )}

        {/* 添加权限表单 */}
        <div className="mt-[var(--space-3)] flex items-center gap-2">
          <select
            value={selectedUserId}
            onChange={(e) => setSelectedUserId(e.target.value)}
            disabled={busy || availableMembers.length === 0}
            className="flex-1 h-8 px-2.5 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] disabled:opacity-50"
          >
            <option value="">{t("searchUser")}</option>
            {availableMembers.map((m) => (
              <option key={m.id} value={m.id}>
                {m.name || m.email}
              </option>
            ))}
          </select>
          <select
            value={selectedPerm}
            onChange={(e) =>
              setSelectedPerm(e.target.value as PermissionLevel)
            }
            disabled={busy}
            className="h-8 px-2 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg-2)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] disabled:opacity-50"
          >
            {PERMISSION_OPTIONS.map((level) => (
              <option key={level} value={level}>
                {t(permKey(level))}
              </option>
            ))}
          </select>
          <button
            type="button"
            onClick={addPermission}
            disabled={!selectedUserId || busy}
            className="inline-flex items-center gap-1 h-8 px-3 rounded-[var(--radius-sm)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] disabled:opacity-50 transition-colors duration-[var(--motion-fast)]"
          >
            {busy ? (
              <Loader2 size={14} className="animate-spin" />
            ) : (
              <Plus size={14} />
            )}
            {t("addPermission")}
          </button>
        </div>
      </div>
    </section>
  );
}

"use client";

/**
 * 文档权限管理面板组件。
 *
 * 功能：
 * - 权限列表展示（授权对象、权限级别、来源标记、授权人、过期时间）
 * - 添加权限（选择授权对象类型/ID + 权限级别）
 * - 删除权限
 *
 * API：
 * - GET    /api/v1/workspaces/${workspaceId}/documents/${documentId}/permissions
 * - POST   /api/v1/workspaces/${workspaceId}/documents/${documentId}/permissions
 * - DELETE /api/v1/workspaces/${workspaceId}/documents/${documentId}/permissions/${permissionId}
 *
 * 来源标记：explicit（显式授权）/ inherited（继承）/ author（作者）/ module（模块）
 */

import { useEffect, useState, type FormEvent } from "react";
import { useTranslations } from "next-intl";
import {
  Loader2,
  Trash2,
  Plus,
  ShieldCheck,
  ShieldAlert,
  Shield,
  Crown,
  Layers,
  X,
} from "lucide-react";
import { api, ApiError } from "@/lib/api";

/** 权限级别 */
type PermissionLevel = "view" | "comment" | "edit" | "manage";

/** 来源类型 */
type PermissionSource = "explicit" | "inherited" | "author" | "module";

/** 授权对象类型 */
type GranteeType = "user" | "role";

/** 文档权限条目 */
interface DocumentPermission {
  id: string;
  granteeType: GranteeType;
  granteeId: string;
  granteeName: string;
  permissionLevel: PermissionLevel;
  source: PermissionSource;
  grantedBy?: string;
  grantedByName?: string;
  expiresAt?: string | null;
  createdAt: string;
}

/** 权限列表响应 */
interface PermissionListResponse {
  items: DocumentPermission[];
  total: number;
}

/** 工作区成员 */
interface Member {
  id: string;
  name: string | null;
  email: string;
}

/** 工作区角色 */
interface Role {
  id: string;
  name: string;
}

interface DocumentPermissionPanelProps {
  workspaceId: string;
  documentId: string;
}

// 样式常量
const fieldLabel =
  "flex items-center gap-1.5 text-[length:var(--text-xs)] text-[var(--meta)] mb-1.5";
const fieldControl =
  "w-full h-9 px-2.5 border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]";

/** 来源标记配置：图标 + 颜色 token */
const sourceConfig: Record<
  PermissionSource,
  { icon: typeof Shield; color: string; bg: string }
> = {
  explicit: {
    icon: ShieldCheck,
    color: "var(--accent)",
    bg: "var(--accent-soft)",
  },
  inherited: {
    icon: Layers,
    color: "var(--muted)",
    bg: "var(--surface-2)",
  },
  author: {
    icon: Crown,
    color: "var(--warn)",
    bg: "var(--warn-soft)",
  },
  module: {
    icon: Shield,
    color: "var(--success)",
    bg: "var(--success-soft)",
  },
};

/** 权限级别颜色配置 */
const levelColor: Record<PermissionLevel, string> = {
  view: "var(--muted)",
  comment: "var(--accent)",
  edit: "var(--warn)",
  manage: "var(--danger)",
};

/** 格式化过期时间 */
function formatExpiry(isoString: string): string {
  const d = new Date(isoString);
  return d.toLocaleDateString(undefined, {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  });
}

export function DocumentPermissionPanel({
  workspaceId,
  documentId,
}: DocumentPermissionPanelProps) {
  const t = useTranslations("permissions");

  const [permissions, setPermissions] = useState<DocumentPermission[]>([]);
  const [members, setMembers] = useState<Member[]>([]);
  const [roles, setRoles] = useState<Role[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  // 添加权限表单状态
  const [showForm, setShowForm] = useState(false);
  const [granteeType, setGranteeType] = useState<GranteeType>("user");
  const [granteeId, setGranteeId] = useState("");
  const [permissionLevel, setPermissionLevel] =
    useState<PermissionLevel>("view");
  const [submitting, setSubmitting] = useState(false);
  const [formError, setFormError] = useState("");

  async function loadPermissions() {
    setLoading(true);
    setError("");
    try {
      const data = await api<PermissionListResponse>(
        `/api/v1/workspaces/${workspaceId}/documents/${documentId}/permissions`,
      );
      setPermissions(data.items ?? []);
    } catch (e) {
      setError(
        e instanceof ApiError || e instanceof Error ? e.message : t("noPermissions"),
      );
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadPermissions();
    // 拉取成员列表用于授权对象选择
    api<Member[] | { items: Member[] }>(
      `/api/v1/workspaces/${workspaceId}/members`,
    )
      .then((data) => {
        const list = Array.isArray(data) ? data : (data.items ?? []);
        setMembers(list);
      })
      .catch(() => {
        // 成员列表加载失败不阻塞权限管理
      });
    // 拉取角色列表用于授权对象选择
    api<Role[] | { items: Role[] }>(
      `/api/v1/workspaces/${workspaceId}/roles`,
    )
      .then((data) => {
        const list = Array.isArray(data) ? data : (data.items ?? []);
        setRoles(list);
      })
      .catch(() => {
        // 角色列表加载失败不阻塞权限管理
      });
  }, [workspaceId, documentId, t]);

  async function removePermission(permission: DocumentPermission) {
    if (!window.confirm(t("confirmRemove"))) return;
    try {
      await api(
        `/api/v1/workspaces/${workspaceId}/documents/${documentId}/permissions/${permission.id}`,
        { method: "DELETE" },
      );
      setPermissions((prev) => prev.filter((p) => p.id !== permission.id));
    } catch (e) {
      setError(
        e instanceof ApiError || e instanceof Error ? e.message : t("confirmRemove"),
      );
    }
  }

  async function submitPermission(e: FormEvent) {
    e.preventDefault();
    if (submitting) return;
    if (!granteeId) {
      setFormError(t("granteeId"));
      return;
    }
    setSubmitting(true);
    setFormError("");
    try {
      await api(
        `/api/v1/workspaces/${workspaceId}/documents/${documentId}/permissions`,
        {
          method: "POST",
          body: JSON.stringify({
            granteeType,
            granteeId,
            permissionLevel,
          }),
        },
      );
      // 成功后刷新列表并关闭表单
      setShowForm(false);
      setGranteeId("");
      setPermissionLevel("view");
      loadPermissions();
    } catch (e) {
      setFormError(
        e instanceof ApiError || e instanceof Error ? e.message : t("save"),
      );
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="space-y-[var(--space-4)]">
      {/* 标题栏 + 添加按钮 */}
      <div className="flex items-center justify-between">
        <h2 className="text-[length:var(--text-lg)] font-[weight:var(--weight-semibold)] text-[var(--fg)] tracking-[var(--tracking-tight)]">
          {t("title")}
        </h2>
        <button
          onClick={() => setShowForm((v) => !v)}
          className="inline-flex items-center gap-1.5 h-9 px-3 rounded-[var(--radius-md)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] transition-colors duration-[var(--motion-fast)]"
        >
          <Plus size={14} />
          {t("addPermission")}
        </button>
      </div>

      {error && (
        <p className="text-[length:var(--text-sm)] text-[var(--danger)]">
          {error}
        </p>
      )}

      {/* 添加权限表单 */}
      {showForm && (
        <form
          onSubmit={submitPermission}
          className="p-4 rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] space-y-4"
        >
          {/* 授权对象类型 */}
          <div>
            <label className={fieldLabel} htmlFor="grantee-type">
              {t("granteeType")}
            </label>
            <select
              id="grantee-type"
              value={granteeType}
              onChange={(e) => {
                setGranteeType(e.target.value as GranteeType);
                setGranteeId("");
              }}
              className={fieldControl}
            >
              <option value="user">{t("user")}</option>
              <option value="role">{t("role")}</option>
            </select>
          </div>

          {/* 授权对象选择 */}
          <div>
            <label className={fieldLabel} htmlFor="grantee-id">
              {t("granteeId")}
            </label>
            <select
              id="grantee-id"
              value={granteeId}
              onChange={(e) => setGranteeId(e.target.value)}
              className={fieldControl}
              aria-required="true"
            >
              <option value="">
                {granteeType === "user" ? t("user") : t("role")}
              </option>
              {granteeType === "user"
                ? members.map((m) => (
                    <option key={m.id} value={m.id}>
                      {m.name || m.email}
                    </option>
                  ))
                : roles.map((r) => (
                    <option key={r.id} value={r.id}>
                      {r.name}
                    </option>
                  ))}
            </select>
          </div>

          {/* 权限级别 */}
          <div>
            <label className={fieldLabel} htmlFor="permission-level">
              {t("permissionLevel")}
            </label>
            <select
              id="permission-level"
              value={permissionLevel}
              onChange={(e) =>
                setPermissionLevel(e.target.value as PermissionLevel)
              }
              className={fieldControl}
            >
              <option value="view">{t("view")}</option>
              <option value="comment">{t("comment")}</option>
              <option value="edit">{t("edit")}</option>
              <option value="manage">{t("manage")}</option>
            </select>
          </div>

          {formError && (
            <div className="flex items-start gap-2 px-3 py-2 rounded-[var(--radius-md)] bg-[var(--danger-soft)] text-[var(--danger)] text-[length:var(--text-sm)]">
              <ShieldAlert size={14} className="shrink-0 mt-0.5" />
              <span className="flex-1">{formError}</span>
            </div>
          )}

          {/* 操作按钮 */}
          <div className="flex items-center justify-end gap-2 pt-1">
            <button
              type="button"
              onClick={() => {
                setShowForm(false);
                setFormError("");
                setGranteeId("");
                setPermissionLevel("view");
              }}
              className="h-9 px-4 rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
            >
              {t("cancel")}
            </button>
            <button
              type="submit"
              disabled={submitting}
              className="inline-flex items-center gap-1.5 h-9 px-4 bg-[var(--accent)] text-[var(--accent-fg)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-[var(--motion-base)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
            >
              {submitting && <Loader2 size={14} className="animate-spin" />}
              {t("save")}
            </button>
          </div>
        </form>
      )}

      {/* 权限列表 */}
      {loading ? (
        <div className="py-[var(--space-8)] text-center text-[var(--muted)]">
          <Loader2 size={20} className="inline animate-spin mr-2" />
          {t("title")}
        </div>
      ) : permissions.length === 0 ? (
        <div className="py-[var(--space-8)] text-center text-[var(--muted)]">
          <Shield size={36} className="mx-auto mb-3 opacity-50" />
          <p>{t("noPermissions")}</p>
        </div>
      ) : (
        <ul className="divide-y divide-[var(--border-soft)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)]">
          {permissions.map((perm) => {
            const sc = sourceConfig[perm.source];
            const SourceIcon = sc.icon;
            return (
              <li
                key={perm.id}
                className="px-[var(--space-4)] py-3 hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
              >
                <div className="flex items-center gap-2">
                  {/* 来源标记图标 */}
                  <SourceIcon
                    size={16}
                    className="shrink-0"
                    style={{ color: sc.color }}
                  />
                  {/* 授权对象名称 */}
                  <span className="flex-1 min-w-0 text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg)] truncate">
                    {perm.granteeName}
                  </span>
                  {/* 来源标记 badge */}
                  <span
                    className="shrink-0 inline-flex items-center gap-1 px-2 py-0.5 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)]"
                    style={{ color: sc.color, backgroundColor: sc.bg }}
                  >
                    {perm.source === "explicit" && t("sourceExplicit")}
                    {perm.source === "inherited" && t("sourceInherited")}
                    {perm.source === "author" && t("sourceAuthor")}
                    {perm.source === "module" && t("sourceModule")}
                  </span>
                  {/* 权限级别 badge */}
                  <span
                    className="shrink-0 inline-flex items-center px-2 py-0.5 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)]"
                    style={{ color: levelColor[perm.permissionLevel] }}
                  >
                    {perm.permissionLevel === "view" && t("view")}
                    {perm.permissionLevel === "comment" && t("comment")}
                    {perm.permissionLevel === "edit" && t("edit")}
                    {perm.permissionLevel === "manage" && t("manage")}
                  </span>
                  {/* 删除按钮（仅 explicit 来源可删除） */}
                  {perm.source === "explicit" && (
                    <button
                      onClick={() => removePermission(perm)}
                      className="shrink-0 inline-flex items-center justify-center w-7 h-7 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[var(--danger)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
                      aria-label={t("removePermission")}
                    >
                      <Trash2 size={14} />
                    </button>
                  )}
                </div>
                {/* 授权人 + 过期时间 */}
                <div className="mt-1.5 ml-6 flex items-center gap-3 text-[length:var(--text-xs)] text-[var(--meta)]">
                  {perm.grantedByName && (
                    <span>
                      {t("grantedBy")}: {perm.grantedByName}
                    </span>
                  )}
                  <span>
                    {t("expiresAt")}:{" "}
                    {perm.expiresAt
                      ? formatExpiry(perm.expiresAt)
                      : t("noExpiry")}
                  </span>
                </div>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

export default DocumentPermissionPanel;

"use client";

/**
 * 文件夹/空间权限管理面板组件。
 *
 * 功能：
 * - 权限列表显示（授权对象、权限级别、可继承标记、授权人）
 * - 添加权限（选择授权对象类型、授权对象 ID、权限级别、可继承）
 * - 删除权限
 *
 * API：
 * - GET    /api/v1/workspaces/${workspaceId}/folders/${folderId}/permissions
 * - GET    /api/v1/workspaces/${workspaceId}/spaces/${spaceId}/permissions
 * - POST   /api/v1/workspaces/${workspaceId}/folders/${folderId}/permissions
 * - POST   /api/v1/workspaces/${workspaceId}/spaces/${spaceId}/permissions
 * - DELETE /api/v1/workspaces/${workspaceId}/folders/${folderId}/permissions/${permissionId}
 * - DELETE /api/v1/workspaces/${workspaceId}/spaces/${spaceId}/permissions/${permissionId}
 */

import { useEffect, useState, type FormEvent } from "react";
import { useTranslations } from "next-intl";
import {
  Loader2,
  Trash2,
  Plus,
  Shield,
  X,
  ChevronDown,
} from "lucide-react";
import { api, ApiError } from "@/lib/api";

/** 权限级别 */
type PermissionLevel = "view" | "comment" | "edit" | "manage";

/** 授权对象类型 */
type GranteeType = "user" | "role";

/** 权限来源 */
type PermissionSource = "explicit" | "inherited" | "author" | "module";

/** 权限记录 */
interface PermissionItem {
  id: string;
  granteeType: GranteeType;
  granteeId: string;
  granteeName?: string;
  permissionLevel: PermissionLevel;
  inheritable: boolean;
  source: PermissionSource;
  inheritedFrom?: string;
  grantedBy?: string;
  grantedByName?: string;
  createdAt: string;
}

/** 权限列表响应 */
interface PermissionListResponse {
  items: PermissionItem[];
  total: number;
}

interface FolderPermissionPanelProps {
  workspaceId: string;
  targetType: "folder" | "space";
  targetId: string;
  onClose?: () => void;
}

const fieldLabel =
  "flex items-center gap-1.5 text-[length:var(--text-xs)] text-[var(--meta)] mb-1.5";
const fieldControl =
  "w-full h-9 px-2.5 border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]";

/** 权限级别选项 */
const PERMISSION_LEVELS: PermissionLevel[] = ["view", "comment", "edit", "manage"];

/** 授权对象类型选项 */
const GRANTEE_TYPES: GranteeType[] = ["user", "role"];

/** 根据 targetType 构建权限 API 基础路径 */
function buildBasePath(workspaceId: string, targetType: "folder" | "space", targetId: string): string {
  if (targetType === "folder") {
    return `/api/v1/workspaces/${workspaceId}/folders/${targetId}/permissions`;
  }
  return `/api/v1/workspaces/${workspaceId}/spaces/${targetId}/permissions`;
}

/** 权限级别徽章颜色映射 */
function getLevelBadgeClass(level: PermissionLevel): string {
  switch (level) {
    case "view":
      return "text-[var(--info)] bg-[var(--info-soft, var(--surface-2))]";
    case "comment":
      return "text-[var(--accent)] bg-[var(--accent-soft, var(--surface-2))]";
    case "edit":
      return "text-[var(--warning)] bg-[var(--warning-soft, var(--surface-2))]";
    case "manage":
      return "text-[var(--danger)] bg-[var(--danger-soft, var(--surface-2))]";
    default:
      return "text-[var(--muted)] bg-[var(--surface-2)]";
  }
}

export function FolderPermissionPanel({
  workspaceId,
  targetType,
  targetId,
  onClose,
}: FolderPermissionPanelProps) {
  const t = useTranslations("permissions");

  const [permissions, setPermissions] = useState<PermissionItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  // 添加权限表单状态
  const [showForm, setShowForm] = useState(false);
  const [granteeType, setGranteeType] = useState<GranteeType>("user");
  const [granteeId, setGranteeId] = useState("");
  const [permissionLevel, setPermissionLevel] = useState<PermissionLevel>("view");
  const [inheritable, setInheritable] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [formError, setFormError] = useState("");

  const basePath = buildBasePath(workspaceId, targetType, targetId);

  async function loadPermissions() {
    setLoading(true);
    setError("");
    try {
      const data = await api<PermissionListResponse | PermissionItem[]>(basePath);
      const list = Array.isArray(data) ? data : (data.items ?? []);
      setPermissions(list);
    } catch (e) {
      setError(
        e instanceof ApiError || e instanceof Error
          ? e.message
          : t("loadFailed"),
      );
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadPermissions();
  }, [basePath, t]);

  async function removePermission(permission: PermissionItem) {
    if (!window.confirm(t("confirmRemove"))) return;
    try {
      await api(`${basePath}/${permission.id}`, { method: "DELETE" });
      setPermissions((prev) => prev.filter((p) => p.id !== permission.id));
    } catch (e) {
      setError(
        e instanceof ApiError || e instanceof Error
          ? e.message
          : t("removePermission"),
      );
    }
  }

  async function submitPermission(e: FormEvent) {
    e.preventDefault();
    if (submitting) return;
    if (!granteeId.trim()) {
      setFormError(t("granteeId"));
      return;
    }
    setSubmitting(true);
    setFormError("");
    try {
      await api(basePath, {
        method: "POST",
        body: JSON.stringify({
          granteeType,
          granteeId: granteeId.trim(),
          permissionLevel,
          inheritable,
        }),
      });
      // 成功后刷新权限列表并关闭表单
      setShowForm(false);
      setGranteeId("");
      setPermissionLevel("view");
      setInheritable(false);
      loadPermissions();
    } catch (e) {
      setFormError(
        e instanceof ApiError || e instanceof Error
          ? e.message
          : t("save"),
      );
    } finally {
      setSubmitting(false);
    }
  }

  const titleKey = targetType === "folder" ? "folderPermissions" : "spacePermissions";

  return (
    <div className="rounded-[var(--radius-lg)] border border-[var(--border)] bg-[var(--surface)] overflow-hidden">
      {/* 标题栏 */}
      <div className="flex items-center justify-between px-[var(--space-4)] py-[var(--space-3)] border-b border-[var(--border)]">
        <div className="flex items-center gap-2">
          <Shield size={16} className="text-[var(--accent)]" />
          <h2 className="text-[length:var(--text-base)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
            {t(titleKey)}
          </h2>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setShowForm((v) => !v)}
            className="inline-flex items-center gap-1.5 h-8 px-3 rounded-[var(--radius-md)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] transition-colors duration-[var(--motion-fast)]"
          >
            <Plus size={14} />
            {t("addPermission")}
          </button>
          {onClose && (
            <button
              onClick={onClose}
              className="inline-flex items-center justify-center h-8 w-8 rounded-[var(--radius-md)] text-[var(--meta)] hover:bg-[var(--surface-2)] hover:text-[var(--fg)] transition-colors duration-[var(--motion-fast)]"
              aria-label={t("close")}
            >
              <X size={16} />
            </button>
          )}
        </div>
      </div>

      {/* 错误提示 */}
      {error && (
        <div className="px-[var(--space-4)] py-2 text-[length:var(--text-sm)] text-[var(--danger)] border-b border-[var(--border)]">
          {error}
        </div>
      )}

      {/* 添加权限表单 */}
      {showForm && (
        <form
          onSubmit={submitPermission}
          className="px-[var(--space-4)] py-[var(--space-3)] border-b border-[var(--border)] bg-[var(--surface-2)] space-y-3"
        >
          {/* 授权对象类型 */}
          <div>
            <label className={fieldLabel} htmlFor="grantee-type">
              {t("granteeType")}
            </label>
            <div className="relative">
              <select
                id="grantee-type"
                value={granteeType}
                onChange={(e) => setGranteeType(e.target.value as GranteeType)}
                className={`${fieldControl} appearance-none pr-8`}
              >
                {GRANTEE_TYPES.map((gt) => (
                  <option key={gt} value={gt}>
                    {t(gt)}
                  </option>
                ))}
              </select>
              <ChevronDown
                size={14}
                className="absolute right-2.5 top-1/2 -translate-y-1/2 pointer-events-none text-[var(--meta)]"
              />
            </div>
          </div>

          {/* 授权对象 ID */}
          <div>
            <label className={fieldLabel} htmlFor="grantee-id">
              {t("granteeId")}
            </label>
            <input
              id="grantee-id"
              type="text"
              value={granteeId}
              onChange={(e) => setGranteeId(e.target.value)}
              placeholder={granteeType === "user" ? t("user") : t("role")}
              className={fieldControl}
              aria-required="true"
            />
          </div>

          {/* 权限级别 */}
          <div>
            <label className={fieldLabel} htmlFor="permission-level">
              {t("permissionLevel")}
            </label>
            <div className="relative">
              <select
                id="permission-level"
                value={permissionLevel}
                onChange={(e) => setPermissionLevel(e.target.value as PermissionLevel)}
                className={`${fieldControl} appearance-none pr-8`}
              >
                {PERMISSION_LEVELS.map((pl) => (
                  <option key={pl} value={pl}>
                    {t(pl)}
                  </option>
                ))}
              </select>
              <ChevronDown
                size={14}
                className="absolute right-2.5 top-1/2 -translate-y-1/2 pointer-events-none text-[var(--meta)]"
              />
            </div>
          </div>

          {/* 可继承 */}
          <div className="flex items-center gap-2">
            <input
              id="inheritable"
              type="checkbox"
              checked={inheritable}
              onChange={(e) => setInheritable(e.target.checked)}
              className="h-4 w-4 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] accent-[var(--accent)]"
            />
            <label
              htmlFor="inheritable"
              className="text-[length:var(--text-sm)] text-[var(--fg)] cursor-pointer"
            >
              {t("inheritable")}
            </label>
          </div>

          {/* 表单错误 */}
          {formError && (
            <div className="px-3 py-2 rounded-[var(--radius-md)] bg-[var(--danger-soft, var(--surface-2))] text-[var(--danger-fg, var(--danger))] text-[length:var(--text-sm)]">
              {formError}
            </div>
          )}

          {/* 操作按钮 */}
          <div className="flex items-center justify-end gap-2 pt-1">
            <button
              type="button"
              onClick={() => {
                setShowForm(false);
                setFormError("");
              }}
              className="h-8 px-4 rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] hover:bg-[var(--surface)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
            >
              {t("cancel")}
            </button>
            <button
              type="submit"
              disabled={submitting}
              className="inline-flex items-center gap-1.5 h-8 px-4 bg-[var(--accent)] text-[var(--accent-fg)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-[var(--motion-base)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
            >
              {submitting && <Loader2 size={14} className="animate-spin" />}
              {t("save")}
            </button>
          </div>
        </form>
      )}

      {/* 权限列表 */}
      {loading ? (
        <div className="py-[var(--space-8)] text-center text-[var(--muted)]">
          <Loader2 size={20} className="inline animate-spin mr-2" />
          {t("loadFailed")}
        </div>
      ) : permissions.length === 0 ? (
        <div className="py-[var(--space-8)] text-center text-[var(--muted)]">
          <Shield size={36} className="mx-auto mb-3 opacity-50" />
          <p className="text-[length:var(--text-sm)]">{t("noPermissions")}</p>
        </div>
      ) : (
        <ul className="divide-y divide-[var(--border-soft)]">
          {permissions.map((permission) => (
            <li
              key={permission.id}
              className="px-[var(--space-4)] py-[var(--space-3)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
            >
              <div className="flex items-center gap-2">
                {/* 授权对象名称 */}
                <span className="flex-1 min-w-0 text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg)] truncate">
                  {permission.granteeName || permission.granteeId}
                </span>

                {/* 授权对象类型标记 */}
                <span className="shrink-0 inline-flex items-center px-1.5 py-0.5 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--meta)] bg-[var(--surface-2)]">
                  {t(permission.granteeType)}
                </span>

                {/* 权限级别徽章 */}
                <span
                  className={`shrink-0 inline-flex items-center px-2 py-0.5 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] ${getLevelBadgeClass(permission.permissionLevel)}`}
                >
                  {t(permission.permissionLevel)}
                </span>

                {/* 可继承标记 */}
                {permission.inheritable && (
                  <span className="shrink-0 inline-flex items-center px-1.5 py-0.5 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--accent)] bg-[var(--accent-soft, var(--surface-2))]">
                    {t("inheritable")}
                  </span>
                )}

                {/* 继承来源标记 */}
                {permission.source === "inherited" && permission.inheritedFrom && (
                  <span className="shrink-0 inline-flex items-center px-1.5 py-0.5 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--info)] bg-[var(--info-soft, var(--surface-2))]">
                    {t("inheritedFrom")}: {permission.inheritedFrom}
                  </span>
                )}

                {/* 删除按钮（仅显式授权可删除） */}
                {permission.source === "explicit" && (
                  <button
                    onClick={() => removePermission(permission)}
                    className="shrink-0 inline-flex items-center justify-center h-7 w-7 rounded-[var(--radius-sm)] text-[var(--danger)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
                    aria-label={t("removePermission")}
                  >
                    <Trash2 size={14} />
                  </button>
                )}
              </div>

              {/* 授权人信息 */}
              {permission.grantedByName && (
                <div className="mt-1.5 text-[length:var(--text-xs)] text-[var(--meta)]">
                  {t("grantedBy")}: {permission.grantedByName}
                </div>
              )}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default FolderPermissionPanel;

"use client";

/**
 * 分享对话框增强组件。
 *
 * 功能：
 * - 分享链接列表（权限级别、下载/打印/复制开关、过期时间、访问次数）
 * - 创建分享链接表单（权限级别、允许下载/打印/复制、密码保护、过期时间、最大访问次数）
 * - 撤销分享链接
 * - 复制链接到剪贴板
 *
 * API：
 * - GET    /api/v1/workspaces/${workspaceId}/documents/${documentId}/share-links
 * - POST   /api/v1/workspaces/${workspaceId}/documents/${documentId}/share-links
 * - DELETE /api/v1/workspaces/${workspaceId}/documents/${documentId}/share-links/${shareLinkId}
 *
 * 分享 URL 格式：${window.location.origin}/share/${shareToken}
 */

import { useEffect, useState, type FormEvent } from "react";
import { useTranslations } from "next-intl";
import {
  Loader2,
  Plus,
  Trash2,
  Copy,
  Check,
  Link2,
  Eye,
  MessageSquare,
  Pencil,
  Download,
  Printer,
  Copy as CopyIcon,
  Lock,
  Clock,
  X,
} from "lucide-react";
import { api, ApiError } from "@/lib/api";

/** 分享链接数据结构 */
interface ShareLink {
  id: string;
  token: string;
  permission: "view" | "comment" | "edit";
  allowDownload: boolean;
  allowPrint: boolean;
  allowCopy: boolean;
  passwordProtected: boolean;
  expiresAt: string | null;
  maxViews: number | null;
  viewCount: number;
  createdAt: string;
}

/** 分享链接列表响应 */
interface ShareLinkListResponse {
  items: ShareLink[];
  total: number;
}

/** 创建分享链接请求体 */
interface CreateShareLinkPayload {
  permission: "view" | "comment" | "edit";
  allowDownload: boolean;
  allowPrint: boolean;
  allowCopy: boolean;
  password?: string;
  expiresAt?: string;
  maxViews?: number;
}

interface ShareDialogEnhancedProps {
  workspaceId: string;
  documentId: string;
  onClose?: () => void;
}

/** 权限级别选项 */
const PERMISSION_LEVELS = ["view", "comment", "edit"] as const;

/** 样式常量 */
const fieldLabel =
  "flex items-center gap-1.5 text-[length:var(--text-xs)] text-[var(--meta)] mb-1.5";
const fieldControl =
  "w-full h-9 px-2.5 border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]";

/** 格式化日期时间用于显示 */
function formatDateTime(isoString: string): string {
  const d = new Date(isoString);
  return d.toLocaleString(undefined, {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  });
}

/** 判断链接是否已过期 */
function isExpired(expiresAt: string | null): boolean {
  if (!expiresAt) return false;
  return new Date(expiresAt).getTime() < Date.now();
}

/** 权限级别图标映射 */
function PermissionIcon({ level }: { level: "view" | "comment" | "edit" }) {
  if (level === "view") return <Eye size={14} className="text-[var(--muted)]" />;
  if (level === "comment")
    return <MessageSquare size={14} className="text-[var(--muted)]" />;
  return <Pencil size={14} className="text-[var(--muted)]" />;
}

/** 权限开关状态徽章 */
function PermissionBadge({
  enabled,
  icon: Icon,
  label,
}: {
  enabled: boolean;
  icon: typeof Download;
  label: string;
}) {
  return (
    <span
      className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] ${
        enabled
          ? "text-[var(--success)] bg-[var(--success-soft, var(--surface-2))]"
          : "text-[var(--muted)] bg-[var(--surface-2)]"
      }`}
    >
      <Icon size={12} />
      {label}
    </span>
  );
}

export function ShareDialogEnhanced({
  workspaceId,
  documentId,
  onClose,
}: ShareDialogEnhancedProps) {
  const t = useTranslations("permissions");

  const [shareLinks, setShareLinks] = useState<ShareLink[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  // 创建分享链接表单状态
  const [showForm, setShowForm] = useState(false);
  const [permission, setPermission] =
    useState<"view" | "comment" | "edit">("view");
  const [allowDownload, setAllowDownload] = useState(false);
  const [allowPrint, setAllowPrint] = useState(false);
  const [allowCopy, setAllowCopy] = useState(false);
  const [password, setPassword] = useState("");
  const [expiresAt, setExpiresAt] = useState("");
  const [maxViews, setMaxViews] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [formError, setFormError] = useState("");

  // 复制链接反馈状态
  const [copiedId, setCopiedId] = useState<string | null>(null);

  // 成功提示状态
  const [successMsg, setSuccessMsg] = useState("");

  async function loadShareLinks() {
    setLoading(true);
    setError("");
    try {
      const data = await api<ShareLinkListResponse>(
        `/api/v1/workspaces/${workspaceId}/documents/${documentId}/share-links`,
      );
      setShareLinks(data.items ?? []);
    } catch (e) {
      setError(
        e instanceof ApiError || e instanceof Error
          ? e.message
          : t("loadFailed"),
      );
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadShareLinks();
  }, [workspaceId, documentId]);

  /** 自动清除成功提示 */
  useEffect(() => {
    if (!successMsg) return;
    const timer = setTimeout(() => setSuccessMsg(""), 3000);
    return () => clearTimeout(timer);
  }, [successMsg]);

  /** 复制分享链接到剪贴板 */
  async function copyShareLink(link: ShareLink) {
    const shareUrl = `${window.location.origin}/share/${link.token}`;
    try {
      await navigator.clipboard.writeText(shareUrl);
      setCopiedId(link.id);
      setSuccessMsg(t("linkCopied"));
      setTimeout(() => setCopiedId(null), 2000);
    } catch {
      setError(t("copyFailed"));
    }
  }

  /** 撤销分享链接 */
  async function revokeShareLink(link: ShareLink) {
    if (!window.confirm(t("confirmRevoke"))) return;
    try {
      await api(
        `/api/v1/workspaces/${workspaceId}/documents/${documentId}/share-links/${link.id}`,
        { method: "DELETE" },
      );
      setShareLinks((prev) => prev.filter((l) => l.id !== link.id));
      setSuccessMsg(t("shareLinkRevoked"));
    } catch (e) {
      setError(
        e instanceof ApiError || e instanceof Error
          ? e.message
          : t("shareFailed"),
      );
    }
  }

  /** 提交创建分享链接表单 */
  async function submitShareLink(e: FormEvent) {
    e.preventDefault();
    if (submitting) return;
    setSubmitting(true);
    setFormError("");
    try {
      const payload: CreateShareLinkPayload = {
        permission,
        allowDownload,
        allowPrint,
        allowCopy,
      };
      if (password.trim()) {
        payload.password = password.trim();
      }
      if (expiresAt) {
        payload.expiresAt = new Date(expiresAt).toISOString();
      }
      if (maxViews) {
        const views = parseInt(maxViews, 10);
        if (views > 0) {
          payload.maxViews = views;
        }
      }

      await api(
        `/api/v1/workspaces/${workspaceId}/documents/${documentId}/share-links`,
        {
          method: "POST",
          body: JSON.stringify(payload),
        },
      );

      // 成功后刷新列表并关闭表单
      setShowForm(false);
      resetForm();
      setSuccessMsg(t("shareLinkCreated"));
      loadShareLinks();
    } catch (e) {
      setFormError(
        e instanceof ApiError || e instanceof Error
          ? e.message
          : t("shareFailed"),
      );
    } finally {
      setSubmitting(false);
    }
  }

  /** 重置表单字段 */
  function resetForm() {
    setPermission("view");
    setAllowDownload(false);
    setAllowPrint(false);
    setAllowCopy(false);
    setPassword("");
    setExpiresAt("");
    setMaxViews("");
    setFormError("");
  }

  return (
    <div className="w-full max-w-[560px] mx-auto">
      {/* 标题栏 */}
      <div className="flex items-center justify-between mb-[var(--space-4)]">
        <div className="flex items-center gap-2">
          <Link2 size={16} className="text-[var(--muted)]" />
          <h2 className="text-[length:var(--text-md)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
            {t("shareLinks")}
          </h2>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setShowForm((v) => !v)}
            className="inline-flex items-center gap-1.5 h-8 px-3 rounded-[var(--radius-md)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] transition-colors duration-[var(--motion-fast)]"
          >
            <Plus size={14} />
            {t("createShareLink")}
          </button>
          {onClose && (
            <button
              onClick={onClose}
              aria-label={t("close")}
              className="inline-flex items-center justify-center h-8 w-8 rounded-[var(--radius-md)] text-[var(--muted)] hover:bg-[var(--surface-2)] hover:text-[var(--fg)] transition-colors duration-[var(--motion-fast)]"
            >
              <X size={16} />
            </button>
          )}
        </div>
      </div>

      {/* 错误提示 */}
      {error && (
        <div className="mb-3 flex items-start gap-2 px-3 py-2 rounded-[var(--radius-md)] bg-[var(--danger-soft, var(--surface-2))] text-[var(--danger-fg, var(--danger))] text-[length:var(--text-sm)]">
          <span className="flex-1">{error}</span>
          <button
            onClick={() => setError("")}
            aria-label={t("close")}
            className="shrink-0 text-[var(--muted)] hover:text-[var(--fg)]"
          >
            <X size={14} />
          </button>
        </div>
      )}

      {/* 成功提示 */}
      {successMsg && (
        <div className="mb-3 flex items-start gap-2 px-3 py-2 rounded-[var(--radius-md)] bg-[var(--success-soft, var(--surface-2))] text-[var(--success)] text-[length:var(--text-sm)]">
          <Check size={14} className="shrink-0 mt-0.5" />
          <span className="flex-1">{successMsg}</span>
        </div>
      )}

      {/* 创建分享链接表单 */}
      {showForm && (
        <form
          onSubmit={submitShareLink}
          className="mb-[var(--space-4)] p-4 rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] space-y-4"
        >
          {/* 权限级别 */}
          <div>
            <label className={fieldLabel} htmlFor="share-permission">
              {t("shareLinkPermission")}
            </label>
            <div className="flex items-center gap-2">
              {PERMISSION_LEVELS.map((level) => (
                <button
                  key={level}
                  type="button"
                  onClick={() => setPermission(level)}
                  className={`inline-flex items-center gap-1.5 h-9 px-3 rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] transition-colors duration-[var(--motion-fast)] ${
                    permission === level
                      ? "bg-[var(--accent)] text-[var(--accent-fg)]"
                      : "bg-[var(--surface-2)] text-[var(--fg-2)] hover:bg-[var(--surface-3, var(--surface-2))]"
                  }`}
                >
                  <PermissionIcon level={level} />
                  {t(level)}
                </button>
              ))}
            </div>
          </div>

          {/* 允许下载 / 打印 / 复制 */}
          <div className="grid grid-cols-3 gap-3">
            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={allowDownload}
                onChange={(e) => setAllowDownload(e.target.checked)}
                className="h-4 w-4 rounded-[var(--radius-sm)] border-[var(--border)] accent-[var(--accent)]"
              />
              <span className="inline-flex items-center gap-1 text-[length:var(--text-sm)] text-[var(--fg-2)]">
                <Download size={14} className="text-[var(--muted)]" />
                {t("allowDownload")}
              </span>
            </label>

            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={allowPrint}
                onChange={(e) => setAllowPrint(e.target.checked)}
                className="h-4 w-4 rounded-[var(--radius-sm)] border-[var(--border)] accent-[var(--accent)]"
              />
              <span className="inline-flex items-center gap-1 text-[length:var(--text-sm)] text-[var(--fg-2)]">
                <Printer size={14} className="text-[var(--muted)]" />
                {t("allowPrint")}
              </span>
            </label>

            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={allowCopy}
                onChange={(e) => setAllowCopy(e.target.checked)}
                className="h-4 w-4 rounded-[var(--radius-sm)] border-[var(--border)] accent-[var(--accent)]"
              />
              <span className="inline-flex items-center gap-1 text-[length:var(--text-sm)] text-[var(--fg-2)]">
                <CopyIcon size={14} className="text-[var(--muted)]" />
                {t("allowCopy")}
              </span>
            </label>
          </div>

          {/* 密码保护（可选） */}
          <div>
            <label className={fieldLabel} htmlFor="share-password">
              <Lock size={14} className="text-[var(--muted)]" />
              {t("passwordProtect")}
            </label>
            <input
              id="share-password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              autoComplete="new-password"
              placeholder="—"
              className={fieldControl}
            />
          </div>

          {/* 过期时间（可选） */}
          <div>
            <label className={fieldLabel} htmlFor="share-expires">
              <Clock size={14} className="text-[var(--muted)]" />
              {t("linkExpires")}
            </label>
            <input
              id="share-expires"
              type="datetime-local"
              value={expiresAt}
              onChange={(e) => setExpiresAt(e.target.value)}
              className={fieldControl}
            />
          </div>

          {/* 最大访问次数（可选） */}
          <div>
            <label className={fieldLabel} htmlFor="share-max-views">
              {t("maxViews")}
            </label>
            <input
              id="share-max-views"
              type="number"
              min="1"
              value={maxViews}
              onChange={(e) => setMaxViews(e.target.value)}
              placeholder="—"
              className={fieldControl}
            />
          </div>

          {/* 表单错误提示 */}
          {formError && (
            <div className="flex items-start gap-2 px-3 py-2 rounded-[var(--radius-md)] bg-[var(--danger-soft, var(--surface-2))] text-[var(--danger-fg, var(--danger))] text-[length:var(--text-sm)]">
              <span className="flex-1">{formError}</span>
            </div>
          )}

          {/* 表单操作按钮 */}
          <div className="flex items-center justify-end gap-2 pt-1">
            <button
              type="button"
              onClick={() => {
                setShowForm(false);
                resetForm();
              }}
              className="h-9 px-4 rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
            >
              {t("cancel")}
            </button>
            <button
              type="submit"
              disabled={submitting}
              className="inline-flex items-center gap-1.5 h-9 px-4 bg-[var(--accent)] text-[var(--accent-fg)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-[var(--motion-base)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
            >
              {submitting && <Loader2 size={14} className="animate-spin" />}
              {t("save")}
            </button>
          </div>
        </form>
      )}

      {/* 分享链接列表 */}
      {loading ? (
        <div className="py-[var(--space-10)] text-center text-[var(--muted)]">
          <Loader2 size={20} className="inline animate-spin mr-2" />
          {t("loadFailed")}
        </div>
      ) : shareLinks.length === 0 ? (
        <div className="py-[var(--space-10)] text-center text-[var(--muted)]">
          <Link2 size={36} className="mx-auto mb-3 opacity-50" />
          <p>{t("noShareLinks")}</p>
        </div>
      ) : (
        <ul className="divide-y divide-[var(--border-soft)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)]">
          {shareLinks.map((link) => {
            const expired = isExpired(link.expiresAt);
            return (
              <li
                key={link.id}
                className="px-[var(--space-4)] py-3 hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
              >
                {/* 第一行：权限级别 + 操作按钮 */}
                <div className="flex items-center gap-2">
                  <PermissionIcon level={link.permission} />
                  <span className="text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg)]">
                    {t(link.permission)}
                  </span>

                  {/* 密码保护标识 */}
                  {link.passwordProtected && (
                    <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] text-[var(--meta)] bg-[var(--surface-2)]">
                      <Lock size={12} />
                    </span>
                  )}

                  {/* 过期标识 */}
                  {expired && (
                    <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] text-[var(--danger)] bg-[var(--danger-soft, var(--surface-2))]">
                      <Clock size={12} />
                    </span>
                  )}

                  <div className="flex-1" />

                  {/* 复制链接按钮 */}
                  <button
                    onClick={() => copyShareLink(link)}
                    className="inline-flex items-center gap-1 h-7 px-2 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-xs)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
                    aria-label={t("copyLink")}
                  >
                    {copiedId === link.id ? (
                      <Check size={14} className="text-[var(--success)]" />
                    ) : (
                      <Copy size={14} />
                    )}
                    {t("copyLink")}
                  </button>

                  {/* 撤销按钮 */}
                  <button
                    onClick={() => revokeShareLink(link)}
                    className="inline-flex items-center gap-1 h-7 px-2 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-xs)] text-[var(--danger)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
                    aria-label={t("actionRevoke")}
                  >
                    <Trash2 size={14} />
                    {t("actionRevoke")}
                  </button>
                </div>

                {/* 第二行：权限开关徽章 */}
                <div className="mt-1.5 flex items-center gap-1.5 flex-wrap">
                  <PermissionBadge
                    enabled={link.allowDownload}
                    icon={Download}
                    label={t("allowDownload")}
                  />
                  <PermissionBadge
                    enabled={link.allowPrint}
                    icon={Printer}
                    label={t("allowPrint")}
                  />
                  <PermissionBadge
                    enabled={link.allowCopy}
                    icon={CopyIcon}
                    label={t("allowCopy")}
                  />
                </div>

                {/* 第三行：过期时间 + 访问次数 */}
                <div className="mt-1.5 flex items-center gap-3 text-[length:var(--text-xs)] text-[var(--meta)]">
                  {link.expiresAt ? (
                    <span>
                      {t("linkExpires")}: {formatDateTime(link.expiresAt)}
                    </span>
                  ) : (
                    <span>{t("noExpiry")}</span>
                  )}
                  {link.maxViews !== null && (
                    <span>
                      {t("maxViews")}: {link.viewCount}/{link.maxViews}
                    </span>
                  )}
                </div>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

export default ShareDialogEnhanced;

"use client";

/**
 * AI 选中文本浮工具栏（AiToolbar）。
 *
 * 功能：
 * - 用户在编辑器中选中文本时，在选区上方显示浮工具栏。
 * - 三个按钮：摘要 / 翻译 / 格式化。
 *   - 摘要：选中文本 → `/api/v1/ai/summarize` → 流式结果替换选区。
 *   - 翻译：展开子菜单（中文/英文/日文）→ `/api/v1/ai/translate`
 *     body 含 `targetLang` → 流式结果替换选区。
 *   - 格式化：选中文本 → `/api/v1/ai/format` → 流式结果替换选区。
 * - 流式期间按钮显示 spinner；完成后用 ProseMirror transaction 替换选区文本。
 * - 选区消失时隐藏工具栏。
 *
 * 技术要点：
 * - "use client" 隔离客户端逻辑。
 * - i18n 走 `ai.toolbar` 与 `ai.translate` 命名空间。
 * - 流式消费走 `consumeAiStream`（见 aiStream.ts）。
 * - 浮层用 `getBoundingClientRect` + `coordsAtPos` 定位，`position: fixed`。
 * - 所有样式走 design token（var(--*)），无裸 hex。
 * - lucide-react 图标 size=16。
 * - 尊重 prefers-reduced-motion（spinner 用 motion-reduce 变体）。
 */

import { useEffect, useRef, useState, useCallback } from "react";
import type { Editor } from "@tiptap/core";
import { useTranslations } from "next-intl";
import { Sparkles, Languages, Wand2, Loader2, ChevronDown } from "lucide-react";
import { consumeAiStream } from "./aiStream";

interface AiToolbarProps {
  editor: Editor | null;
}

type Action = "summarize" | "translate" | "format";
type TargetLang = "zh" | "en" | "ja";

/** 浮层定位（viewport 相对，配 position: fixed） */
interface ToolbarPos {
  top: number;
  left: number;
}

const TARGET_LANGS: TargetLang[] = ["zh", "en", "ja"];

/** 按钮基础类名（design token，与 RichTextEditor 工具栏风格一致） */
const BTN_CLASS =
  "inline-flex items-center gap-1 px-2 py-1 rounded-[var(--radius-sm)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--hover-soft)] hover:text-[var(--fg)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]";

export function AiToolbar({ editor }: AiToolbarProps) {
  const t = useTranslations("ai.toolbar");
  const tTrans = useTranslations("ai.translate");

  const [pos, setPos] = useState<ToolbarPos | null>(null);
  const [loading, setLoading] = useState<Action | null>(null);
  const [showTranslateMenu, setShowTranslateMenu] = useState(false);
  /** 翻译子菜单节点 ref（外部点击关闭判定） */
  const menuRef = useRef<HTMLDivElement | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  /** 执行 AI 操作：调流式 API，完成后用结果替换选区 */
  const runAction = useCallback(
    async (action: Action, targetLang?: TargetLang) => {
      if (!editor) return;
      const { from, to, empty } = editor.state.selection;
      if (empty) return;
      const text = editor.state.doc.textBetween(from, to, "\n");
      if (!text.trim()) return;

      if (abortRef.current) abortRef.current.abort();
      const ac = new AbortController();
      abortRef.current = ac;
      setLoading(action);
      setShowTranslateMenu(false);

      const url = `/api/v1/ai/${action}`;
      const body: Record<string, unknown> = { text };
      if (action === "translate" && targetLang) {
        body.targetLang = targetLang;
      }

      let result = "";
      try {
        result = await consumeAiStream(url, body, { signal: ac.signal });
      } catch (e) {
        if ((e as Error).name === "AbortError") return;
        // 静默失败：不替换、不阻断
        return;
      } finally {
        setLoading(null);
        if (abortRef.current === ac) abortRef.current = null;
      }

      // 用 ProseMirror transaction 替换选区为 AI 结果（纯文本插入）
      if (result && editor && !editor.isDestroyed) {
        const tr = editor.state.tr.delete(from, to).insertText(result, from);
        editor.view.dispatch(tr);
        editor.commands.focus();
      }
    },
    [editor],
  );

  /** 根据选区更新浮层位置 */
  const updatePos = useCallback(() => {
    if (!editor) return;
    const { empty, from, to } = editor.state.selection;
    if (empty) {
      setPos(null);
      setShowTranslateMenu(false);
      return;
    }
    const text = editor.state.doc.textBetween(from, to, "\n");
    if (!text.trim()) {
      setPos(null);
      return;
    }
    try {
      const startCoords = editor.view.coordsAtPos(from);
      const endCoords = editor.view.coordsAtPos(to);
      // 选区上方 36px（约一行高 + 间距），水平居中
      const top = Math.min(startCoords.top, endCoords.top) - 36;
      const left = (startCoords.left + endCoords.right) / 2;
      setPos({ top, left });
    } catch {
      setPos(null);
    }
  }, [editor]);

  // 监听选区变化更新浮层
  useEffect(() => {
    if (!editor) return;
    const handler = () => updatePos();
    editor.on("selectionUpdate", handler);
    return () => {
      editor.off("selectionUpdate", handler);
    };
  }, [editor, updatePos]);

  // 编辑器失焦时隐藏（但点击工具栏按钮的 mousedown 会 preventDefault，不失焦）
  useEffect(() => {
    if (!editor) return;
    const handler = () => {
      // 延迟检查，允许点击工具栏后选区仍存在
      requestAnimationFrame(() => {
        if (editor.isDestroyed || editor.state.selection.empty) {
          setPos(null);
          setShowTranslateMenu(false);
        }
      });
    };
    editor.on("blur", handler);
    return () => {
      editor.off("blur", handler);
    };
  }, [editor]);

  // 外部点击关闭翻译子菜单
  useEffect(() => {
    if (!showTranslateMenu) return;
    const handler = (e: MouseEvent) => {
      const target = e.target as Node;
      if (menuRef.current && !menuRef.current.contains(target)) {
        setShowTranslateMenu(false);
      }
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, [showTranslateMenu]);

  // 卸载清理
  useEffect(() => {
    return () => {
      if (abortRef.current) abortRef.current.abort();
    };
  }, []);

  if (!pos) return null;

  const isLoading = loading !== null;

  return (
    <div
      role="toolbar"
      aria-label={t("summarize")}
      style={{
        position: "fixed",
        top: pos.top,
        left: pos.left,
        transform: "translateX(-50%)",
        zIndex: "var(--z-dropdown)",
      }}
      className="flex items-center gap-0.5 p-1 rounded-[var(--radius-sm)] bg-[var(--surface)] border border-[var(--border)] shadow-[var(--elev-md)]"
      // 防止点击工具栏时编辑器失焦（选区消失）
      onMouseDown={(e) => e.preventDefault()}
    >
      <button
        type="button"
        className={BTN_CLASS}
        disabled={isLoading}
        onClick={() => runAction("summarize")}
        title={t("summarize")}
        aria-label={t("summarize")}
      >
        {loading === "summarize" ? (
          <Loader2 size={16} className="animate-spin motion-reduce:animate-none" />
        ) : (
          <Sparkles size={16} />
        )}
        {t("summarize")}
      </button>

      <button
        type="button"
        className={BTN_CLASS}
        disabled={isLoading}
        onClick={() => setShowTranslateMenu((v) => !v)}
        title={t("translate")}
        aria-label={t("translate")}
        aria-expanded={showTranslateMenu}
      >
        {loading === "translate" ? (
          <Loader2 size={16} className="animate-spin motion-reduce:animate-none" />
        ) : (
          <Languages size={16} />
        )}
        {t("translate")}
        <ChevronDown size={14} aria-hidden="true" />
      </button>

      <button
        type="button"
        className={BTN_CLASS}
        disabled={isLoading}
        onClick={() => runAction("format")}
        title={t("format")}
        aria-label={t("format")}
      >
        {loading === "format" ? (
          <Loader2 size={16} className="animate-spin motion-reduce:animate-none" />
        ) : (
          <Wand2 size={16} />
        )}
        {t("format")}
      </button>

      {showTranslateMenu && (
        <div
          ref={menuRef}
          role="menu"
          aria-label={tTrans("tooltip")}
          className="absolute top-full left-0 mt-1 p-1 rounded-[var(--radius-sm)] bg-[var(--surface)] border border-[var(--border)] shadow-[var(--elev-md)] flex flex-col gap-0.5 min-w-[140px]"
        >
          {TARGET_LANGS.map((lang) => (
            <button
              key={lang}
              type="button"
              role="menuitem"
              className={BTN_CLASS}
              disabled={isLoading}
              onClick={() => runAction("translate", lang)}
            >
              {lang === "zh"
                ? tTrans("targetZh")
                : lang === "en"
                  ? tTrans("targetEn")
                  : tTrans("targetJa")}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

/**
 * FileGridItem · 文件网格视图项（Phase 4B 云盘）
 *
 * 网格视图中的卡片式文件项：缩略图（图片）或大图标 + 文件名 + 大小。
 * 复用 FileListItem 导出的 formatFileSize / getFileIcon 辅助函数。
 *
 * 所有样式走 design token（var(--*)），无裸 hex。
 * 图标：lucide-react，尺寸 32（网格大图标）。
 * 动效：card-lift（hover 微抬升 + 柔化投影），motion-reduce 时禁用。
 */

import { useState } from "react";
import type { FileAsset } from "@prisma/client";
import { Check, Trash2 } from "lucide-react";
import { formatFileSize, getFileIcon } from "./file-utils";
import { useTranslations } from "next-intl";

// ─── Props ──────────────────────────────────────────────────────

export interface FileGridItemProps {
  file: FileAsset;
  selected?: boolean;
  onClick?: () => void;
  onSelect?: () => void;
  onDelete?: () => void;
}

// ─── 组件 ────────────────────────────────────────────────────────

export function FileGridItem({
  file,
  selected = false,
  onClick,
  onSelect,
  onDelete,
}: FileGridItemProps) {
  const t = useTranslations("files.fileGridItem");
  const Icon = getFileIcon(file.fileType);
  const isImage = file.fileType.toLowerCase().startsWith("image/");
  const [imgError, setImgError] = useState(false);
  const showThumbnail = isImage && !!file.thumbnailKey && !imgError;

  // 缩略图 URL：通过 download 端点获取（img 加载失败时回退到文件图标）
  const thumbnailUrl = `/api/v1/workspaces/${file.workspaceId}/files/${file.id}/download`;

  return (
    <div
      role="gridcell"
      onClick={onClick}
      className={
        "group relative flex flex-col rounded-[var(--radius-md)] border bg-[var(--surface)] " +
        "transition-all duration-[var(--motion-base)] motion-reduce:transition-none " +
        "hover:-translate-y-0.5 hover:shadow-[var(--elev-hover)] motion-reduce:hover:translate-y-0 " +
        (onClick ? "cursor-pointer " : "") +
        (selected ? "border-[var(--accent)]" : "border-[var(--border)]")
      }
    >
      {/* 选择复选框（左上角，选中时常驻、否则 hover/focus 显示） */}
      {onSelect && (
        <button
          type="button"
          role="checkbox"
          aria-checked={selected}
          aria-label={selected ? t("unselectAria") : t("selectAria")}
          onClick={(e) => {
            e.stopPropagation();
            onSelect();
          }}
          className={
            "absolute top-2 left-2 w-5 h-5 rounded-[var(--radius-sm)] border flex items-center justify-center " +
            "transition-colors duration-[var(--motion-fast)] motion-reduce:transition-none " +
            "focus-visible:outline-none focus-visible:ring-[var(--focus-ring)] " +
            (selected
              ? "bg-[var(--accent)] border-[var(--accent)] opacity-100"
              : "bg-[var(--surface)] border-[var(--border)] opacity-0 group-hover:opacity-100 group-focus-within:opacity-100 hover:border-[var(--accent)]")
          }
        >
          {selected && (
            <Check size={12} className="text-[var(--accent-fg)]" strokeWidth={3} />
          )}
        </button>
      )}

      {/* 删除按钮（右上角，hover/focus 显示） */}
      {onDelete && (
        <button
          type="button"
          aria-label={t("deleteAria")}
          onClick={(e) => {
            e.stopPropagation();
            onDelete();
          }}
          className="absolute top-2 right-2 w-6 h-6 inline-flex items-center justify-center rounded-[var(--radius-sm)] bg-[var(--surface)] border border-[var(--border)] text-[var(--muted)] hover:bg-[var(--danger-soft)] hover:text-[var(--danger)] opacity-0 group-hover:opacity-100 group-focus-within:opacity-100 transition-opacity duration-[var(--motion-fast)] motion-reduce:transition-none focus-visible:outline-none focus-visible:ring-[var(--focus-ring)]"
        >
          <Trash2 size={14} />
        </button>
      )}

      {/* 缩略图 / 大图标区域 */}
      <div className="flex items-center justify-center h-28 border-b border-[var(--border-soft)] bg-[var(--surface-2)] overflow-hidden">
        {showThumbnail ? (
          <img
            src={thumbnailUrl}
            alt={file.fileName}
            loading="lazy"
            onError={() => setImgError(true)}
            className="w-full h-full object-cover"
          />
        ) : (
          <Icon size={32} className="text-[var(--muted)]" strokeWidth={1.5} />
        )}
      </div>

      {/* 文件信息 */}
      <div className="flex flex-col gap-0.5 p-2.5">
        <span
          className="text-[length:var(--text-sm)] text-[var(--fg)] line-clamp-2 leading-[var(--leading-snug)]"
          title={file.fileName}
        >
          {file.fileName}
        </span>
        <span className="text-[length:var(--text-xs)] text-[var(--muted)] tabular-nums">
          {formatFileSize(file.fileSize)}
        </span>
      </div>
    </div>
  );
}

"use client";

/**
 * 文件预览统一入口
 *
 * 根据文件类型分发到对应预览组件：
 *  - PDF → PdfPreview（iframe 原生渲染）
 *  - Office（docx/xlsx/pptx）→ OfficePreview（Microsoft Office Online Viewer）
 *  - 图片（jpg/png/gif/webp/svg）→ ImagePreview（<img> 标签）
 *  - 视频（mp4/webm/ogg）→ VideoPreview（<video> 标签 + controls）
 *  - 音频（mp3/wav/ogg）→ AudioPreview（<audio> 标签 + controls）
 *  - 文本（txt/md/json/csv/log）→ TextPreview（<pre> + fetch 内容）
 *  - 其他 → UnsupportedPreview（文件名 + 下载按钮）
 *
 * UI：顶部栏（文件名 + 关闭按钮），内容区（预览内容）。
 * ESC 键关闭，打开时锁定背景滚动。
 *
 * 所有样式走 design token（var(--*)），无裸 hex。
 * 图标：lucide-react，尺寸 14。
 * 动效：transition 用 var(--motion-base)，motion-reduce 时禁用。
 */

import { useEffect, useCallback } from "react";
import { X, Download, FileText, FileWarning } from "lucide-react";
import { useTranslations } from "next-intl";
import { PdfPreview } from "./PdfPreview";
import { VideoPreview } from "./VideoPreview";
import { TextPreview } from "./TextPreview";

// ─── Props ──────────────────────────────────────────────────────

export interface FilePreviewProps {
  /** 文件可访问 URL（用于预览和下载） */
  url: string;
  /** 文件名（用于显示和类型推断） */
  fileName: string;
  /** 文件类型（扩展名，如 "pdf"、"docx"） */
  fileType: string;
  /** 关闭回调 */
  onClose: () => void;
}

// ─── 文件类型分类 ──────────────────────────────────────────────

const IMAGE_EXTS = ["jpg", "jpeg", "png", "gif", "webp", "svg", "bmp"];
const PDF_EXTS = ["pdf"];
const OFFICE_EXTS = ["doc", "docx", "xls", "xlsx", "ppt", "pptx"];
const VIDEO_EXTS = ["mp4", "webm", "ogg", "mov", "avi"];
const AUDIO_EXTS = ["mp3", "wav", "ogg", "m4a", "flac"];
const TEXT_EXTS = [
  "txt", "md", "json", "csv", "log", "xml", "yaml", "yml",
  "js", "ts", "py", "java", "go", "rs",
];

type FileCategory =
  | "pdf"
  | "office"
  | "image"
  | "video"
  | "audio"
  | "text"
  | "other";

/**
 * 根据文件名（扩展名）判断文件分类。
 * 按任务规格定义的扩展名列表进行匹配。
 */
export function getFileCategory(fileName: string): FileCategory {
  const ext = fileName.split(".").pop()?.toLowerCase() ?? "";
  if (PDF_EXTS.includes(ext)) return "pdf";
  if (OFFICE_EXTS.includes(ext)) return "office";
  if (IMAGE_EXTS.includes(ext)) return "image";
  if (VIDEO_EXTS.includes(ext)) return "video";
  if (AUDIO_EXTS.includes(ext)) return "audio";
  if (TEXT_EXTS.includes(ext)) return "text";
  return "other";
}

// ─── 内联预览组件 ──────────────────────────────────────────────

/** 图片预览：居中展示，支持滚轮缩放 */
function ImagePreview({ url, fileName }: { url: string; fileName: string }) {
  return (
    <div
      className="flex items-center justify-center w-full h-full overflow-auto bg-[var(--surface-2)]"
      data-testid="image-preview"
    >
      <img
        src={url}
        alt={fileName}
        className="max-w-full max-h-full object-contain"
        draggable={false}
      />
    </div>
  );
}

/** Office 预览：使用 Microsoft Office Online Viewer */
function OfficePreview({ url }: { url: string }) {
  const t = useTranslations("files.preview");
  const viewerUrl = `https://view.officeapps.live.com/view.aspx?url=${encodeURIComponent(url)}`;

  return (
    <iframe
      src={viewerUrl}
      title={t("title")}
      className="w-full h-full border-0 bg-[var(--surface)]"
      data-testid="office-preview"
    />
  );
}

/** 音频预览：HTML5 <audio> + 原生控件 */
function AudioPreview({ url }: { url: string }) {
  return (
    <div
      className="flex flex-col items-center justify-center gap-6 w-full h-full bg-[var(--surface-2)]"
      data-testid="audio-preview"
    >
      <audio src={url} controls className="w-full max-w-[400px]" />
    </div>
  );
}

/** 不支持的文件类型：显示文件名 + 下载按钮 */
function UnsupportedPreview({ url, fileName }: { url: string; fileName: string }) {
  const t = useTranslations("files.preview");
  return (
    <div className="flex flex-col items-center justify-center gap-4 w-full h-full text-center px-6">
      <FileWarning size={32} className="text-[var(--meta)]" />
      <p className="text-[var(--muted)] text-[length:var(--text-sm)]">
        {t("unsupported")}
      </p>
      <a
        href={url}
        download={fileName}
        className="inline-flex items-center gap-1.5 h-9 px-4 rounded-[var(--radius-sm)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] transition-colors duration-[var(--motion-base)] motion-reduce:transition-none hover:bg-[var(--accent-hover)] focus-visible:outline-none focus-visible:ring-[var(--focus-ring)]"
      >
        <Download size={14} />
        <span>{t("downloadFile")}</span>
      </a>
    </div>
  );
}

// ─── 样式常量 ──────────────────────────────────────────────────

/** 顶部栏按钮基础样式 */
const HEADER_BTN =
  "inline-flex items-center justify-center h-8 px-2.5 rounded-[var(--radius-sm)] " +
  "text-[length:var(--text-sm)] transition-colors duration-[var(--motion-base)] " +
  "motion-reduce:transition-none focus-visible:outline-none focus-visible:ring-[var(--focus-ring)] " +
  "cursor-pointer";

// ─── 主组件 ──────────────────────────────────────────────────────

export function FilePreview({ url, fileName, fileType, onClose }: FilePreviewProps) {
  const t = useTranslations("files.preview");
  const category = getFileCategory(fileName);

  // ESC 键关闭
  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        onClose();
      }
    },
    [onClose],
  );

  useEffect(() => {
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [handleKeyDown]);

  // 打开时锁定背景滚动，关闭时恢复
  useEffect(() => {
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = prev;
    };
  }, []);

  return (
    <div
      className="fixed inset-0 z-[var(--z-modal)] flex flex-col bg-[var(--bg)]"
      role="dialog"
      aria-modal="true"
      aria-label={t("previewAria", { name: fileName })}
      data-testid="file-preview"
    >
      {/* ─── 顶部栏 ─── */}
      <header className="flex items-center gap-3 px-4 h-12 border-b border-[var(--border)] bg-[var(--surface)] shrink-0">
        <FileText size={16} className="shrink-0 text-[var(--muted)]" />
        <span className="text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--fg)] truncate">
          {fileName}
        </span>

        <div className="ml-auto flex items-center gap-2">
          <a
            href={url}
            download={fileName}
            className={`${HEADER_BTN} gap-1.5 border border-[var(--border)] bg-[var(--surface)] text-[var(--fg-2)] hover:bg-[var(--surface-2)]`}
          >
            <Download size={14} />
            <span>{t("download")}</span>
          </a>
          <button
            type="button"
            onClick={onClose}
            aria-label={t("closeAria")}
            className={`${HEADER_BTN} w-8 px-0 text-[var(--fg-2)] hover:bg-[var(--surface-2)]`}
          >
            <X size={14} />
          </button>
        </div>
      </header>

      {/* ─── 内容区 ─── */}
      <main className="flex-1 min-h-0 overflow-hidden">
        {category === "pdf" && <PdfPreview url={url} />}
        {category === "office" && <OfficePreview url={url} />}
        {category === "image" && <ImagePreview url={url} fileName={fileName} />}
        {category === "video" && <VideoPreview url={url} />}
        {category === "audio" && <AudioPreview url={url} />}
        {category === "text" && <TextPreview url={url} fileName={fileName} />}
        {category === "other" && <UnsupportedPreview url={url} fileName={fileName} />}
      </main>
    </div>
  );
}

"use client";

/**
 * 图片预览组件
 *
 * 支持滚轮缩放（0.2x ~ 5x），使用 CSS transform scale。
 * 加载中显示占位提示，加载完成后居中展示图片。
 *
 * 所有样式走 design token（var(--*)），无裸 hex。
 * 尊重 prefers-reduced-motion（transition 用 motion-reduce 变体禁用）。
 */

import { useState, useEffect, useRef, useCallback } from "react";
import { useTranslations } from "next-intl";

export interface ImagePreviewProps {
  src: string;
  fileName: string;
}

export function ImagePreview({ src, fileName }: ImagePreviewProps) {
  const t = useTranslations("files.imagePreview");
  const [scale, setScale] = useState(1);
  const [loading, setLoading] = useState(true);
  const containerRef = useRef<HTMLDivElement>(null);

  // 滚轮缩放（native event, passive: false 以支持 preventDefault）
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const handleWheel = (e: WheelEvent) => {
      e.preventDefault();
      const delta = e.deltaY > 0 ? -0.1 : 0.1;
      setScale((s) => Math.min(5, Math.max(0.2, Number((s + delta).toFixed(2)))));
    };
    el.addEventListener("wheel", handleWheel, { passive: false });
    return () => el.removeEventListener("wheel", handleWheel);
  }, []);

  const handleLoad = useCallback(() => setLoading(false), []);

  return (
    <div
      ref={containerRef}
      className="relative flex items-center justify-center w-full h-full overflow-auto bg-[var(--surface-2)]"
      data-testid="image-preview"
    >
      {loading && (
        <span className="absolute inset-0 flex items-center justify-center text-[var(--muted)] text-[length:var(--text-sm)]">
          {t("loading")}
        </span>
      )}
      <img
        src={src}
        alt={fileName}
        onLoad={handleLoad}
        style={{
          transform: `scale(${scale})`,
          transition: "transform var(--motion-base) var(--ease-standard)",
        }}
        className="max-w-full max-h-full object-contain motion-reduce:transition-none"
        draggable={false}
      />
    </div>
  );
}

"use client";

/**
 * 表单预览组件。
 *
 * 根据 fields 定义渲染表单输入控件。
 * - readOnly 模式：仅展示，不提交（用于预览面板）
 * - 可提交模式：渲染提交按钮，调用 onSubmit 回调
 */

import { useState, type FormEvent } from "react";
import { useTranslations } from "next-intl";
import { Loader2, AlertCircle, X } from "lucide-react";
import { api } from "@/lib/api";
import type { FormFieldDefinition, FormItem } from "./types";

const fieldLabel =
  "flex items-center gap-1.5 text-[length:var(--text-xs)] text-[var(--meta)] mb-1.5";
const fieldControl =
  "w-full h-9 px-2.5 border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]";

interface FormPreviewProps {
  wid: string;
  form: FormItem;
  /** 只读模式（仅展示，不渲染提交按钮） */
  readOnly?: boolean;
  /** 提交成功回调 */
  onSubmitSuccess?: () => void;
}

export function FormPreview({ wid, form, readOnly, onSubmitSuccess }: FormPreviewProps) {
  const t = useTranslations("form");
  const [values, setValues] = useState<Record<string, string>>({});
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);

  function updateValue(fieldId: string, value: string) {
    setValues((prev) => ({ ...prev, [fieldId]: value }));
  }

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    if (submitting || readOnly) return;
    setSubmitting(true);
    setError("");
    setSuccess(false);
    try {
      await api(`/api/v1/workspaces/${wid}/forms/${form.id}/submissions`, {
        method: "POST",
        body: JSON.stringify({ data: values }),
      });
      setSuccess(true);
      setValues({});
      onSubmitSuccess?.();
    } catch (err) {
      setError(err instanceof Error ? err.message : t("submitFailed"));
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      {/* 表单标题与描述 */}
      <div>
        <h3 className="text-[length:var(--text-md)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
          {form.title}
        </h3>
        {form.description && (
          <p className="mt-1 text-[length:var(--text-sm)] text-[var(--meta)]">{form.description}</p>
        )}
      </div>

      {/* 字段渲染 */}
      {form.fields.map((field) => (
        <FieldRenderer
          key={field.id}
          field={field}
          value={values[field.id] ?? ""}
          onChange={(v) => updateValue(field.id, v)}
          readOnly={readOnly}
          labelClass={fieldLabel}
          controlClass={fieldControl}
          t={t}
        />
      ))}

      {error && (
        <div className="flex items-start gap-2 px-3 py-2 rounded-[var(--radius-md)] bg-[var(--danger-soft)] text-[var(--danger-fg)] text-[length:var(--text-sm)]">
          <AlertCircle size={14} className="shrink-0 mt-0.5" />
          <span className="flex-1">{error}</span>
          <button
            type="button"
            onClick={() => setError("")}
            className="shrink-0 opacity-60 hover:opacity-100 transition-opacity"
            aria-label={t("close")}
          >
            <X size={14} />
          </button>
        </div>
      )}

      {success && (
        <div className="px-3 py-2 rounded-[var(--radius-md)] bg-[var(--success-soft)] text-[var(--success-fg)] text-[length:var(--text-sm)]">
          {t("submitSuccess")}
        </div>
      )}

      {/* 提交按钮 */}
      {!readOnly && (
        <div className="flex items-center justify-end gap-2 pt-1">
          <button
            type="submit"
            disabled={submitting}
            className="inline-flex items-center gap-1.5 h-9 px-4 bg-[var(--accent)] text-[var(--accent-fg)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] disabled:opacity-50 transition-colors duration-[var(--motion-base)]"
          >
            {submitting && <Loader2 size={14} className="animate-spin" />}
            {t("submit")}
          </button>
        </div>
      )}
    </form>
  );
}

/** 单个字段渲染器 */
function FieldRenderer({
  field,
  value,
  onChange,
  readOnly,
  labelClass,
  controlClass,
  t,
}: {
  field: FormFieldDefinition;
  value: string;
  onChange: (v: string) => void;
  readOnly?: boolean;
  labelClass: string;
  controlClass: string;
  t: (key: string) => string;
}) {
  const id = `fp-${field.id}`;
  const labelNode = (
    <label className={labelClass} htmlFor={id}>
      {field.label}
      {field.required && <span className="text-[var(--danger-fg)]">*</span>}
    </label>
  );

  const commonProps = {
    id,
    value,
    disabled: readOnly,
    onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) =>
      onChange(e.target.value),
  };

  switch (field.type) {
    case "textarea":
      return (
        <div>
          {labelNode}
          <textarea
            {...commonProps}
            rows={3}
            className="w-full px-2.5 py-2 resize-y border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] disabled:opacity-60"
          />
        </div>
      );
    case "number":
      return (
        <div>
          {labelNode}
          <input
            type="number"
            {...commonProps}
            className={`${controlClass} disabled:opacity-60`}
          />
        </div>
      );
    case "date":
      return (
        <div>
          {labelNode}
          <input
            type="date"
            {...commonProps}
            className={`${controlClass} disabled:opacity-60`}
          />
        </div>
      );
    case "select":
      return (
        <div>
          {labelNode}
          <select {...commonProps} className={`${controlClass} disabled:opacity-60`}>
            <option value="">—</option>
            {(field.options ?? []).map((opt) => (
              <option key={opt} value={opt}>
                {opt}
              </option>
            ))}
          </select>
        </div>
      );
    case "radio":
      return (
        <div>
          {labelNode}
          <div className="flex flex-col gap-1.5">
            {(field.options ?? []).map((opt) => (
              <label key={opt} className="inline-flex items-center gap-1.5 text-[length:var(--text-sm)] text-[var(--fg)]">
                <input
                  type="radio"
                  name={id}
                  value={opt}
                  checked={value === opt}
                  disabled={readOnly}
                  onChange={() => onChange(opt)}
                  className="w-4 h-4 accent-[var(--accent)]"
                />
                {opt}
              </label>
            ))}
          </div>
        </div>
      );
    case "checkbox":
      return (
        <div>
          {labelNode}
          <div className="flex flex-col gap-1.5">
            {(field.options ?? []).map((opt) => (
              <label key={opt} className="inline-flex items-center gap-1.5 text-[length:var(--text-sm)] text-[var(--fg)]">
                <input
                  type="checkbox"
                  checked={value === opt}
                  disabled={readOnly}
                  onChange={(e) => onChange(e.target.checked ? opt : "")}
                  className="w-4 h-4 rounded-[var(--radius-sm)] accent-[var(--accent)]"
                />
                {opt}
              </label>
            ))}
          </div>
        </div>
      );
    case "text":
    default:
      return (
        <div>
          {labelNode}
          <input type="text" {...commonProps} className={`${controlClass} disabled:opacity-60`} />
        </div>
      );
  }
}

"use client";

/**
 * 聊天窗口主体
 *
 * - 顶部：会话标题 + 成员数 + 设置按钮
 * - 中间：MessageList（消息列表）
 * - 底部：MessageInput（消息输入区，支持 @提及/文件上传/字数计数）
 * - 回复引用：点击回复时由 MessageInput 上方显示被回复消息摘要
 *
 * 所有样式走 design token（var(--*)），无裸 hex。
 * lucide-react 图标尺寸用 14/16（项目约定）。
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Settings, Users, Video, Phone, Loader2 } from "lucide-react";
import { useTranslations } from "next-intl";
import { useRouter, useParams } from "next/navigation";
import type { Conversation, Message, SendMessageOptions } from "./types";
import { MessageList } from "./MessageList";
import { MessageInput } from "./MessageInput";
import {
  IncomingCallNotification,
  type IncomingCallData,
} from "./IncomingCallNotification";
import { api } from "@/lib/api";

/** 通话超时：5 分钟内对方未加入则自动发送 call_ended */
const CALL_TIMEOUT_MS = 5 * 60 * 1000;

interface ChatWindowProps {
  /** 当前会话 */
  conversation: Conversation;
  /** 消息列表 */
  messages: Message[];
  /** 当前用户 ID */
  currentUserId: string;
  /** 发送消息 */
  onSend: (body: string, opts?: SendMessageOptions) => void;
  /** 编辑消息 */
  onEdit: (mid: string, body: string) => void;
  /** 撤回消息 */
  onRevoke: (mid: string) => void;
  /** 加载更多历史消息（向上滚动触发） */
  onLoadMore?: () => void;
  /** 是否正在加载更多历史消息 */
  loadingMore?: boolean;
  /** 点击设置按钮（可选） */
  onSettings?: () => void;
  /** 正在输入的用户 ID 列表（当前会话） */
  typingUserIds?: string[];
}

export function ChatWindow({
  conversation,
  messages,
  currentUserId,
  onSend,
  onEdit,
  onRevoke,
  onLoadMore,
  loadingMore = false,
  onSettings,
  typingUserIds = [],
}: ChatWindowProps) {
  const t = useTranslations("chat");
  const tIm = useTranslations("im");
  const router = useRouter();
  const params = useParams<{ locale: string; wid: string }>();
  const [replyTo, setReplyTo] = useState<Message | null>(null);
  const [isCalling, setIsCalling] = useState(false);
  const [isVoiceCalling, setIsVoiceCalling] = useState(false);
  const [incomingCall, setIncomingCall] = useState<IncomingCallData | null>(
    null,
  );
  const callTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const incomingCallRef = useRef<IncomingCallData | null>(null);

  // 组件卸载时清理超时计时器，防止内存泄漏
  useEffect(() => {
    return () => {
      if (callTimeoutRef.current) {
        clearTimeout(callTimeoutRef.current);
        callTimeoutRef.current = null;
      }
    };
  }, []);

  // 监听消息列表中的 call_invite / call_ended / call_rejected 消息
  // 收到 call_invite → 弹出来电通知；收到 call_ended / call_rejected → 关闭来电通知
  useEffect(() => {
    if (messages.length === 0) return;
    // 从最新消息向前扫描，查找最近的通话相关消息
    for (let i = messages.length - 1; i >= 0; i--) {
      const msg = messages[i];
      const msgType = msg.type ?? "text";

      if (msgType === "call_ended" || msgType === "call_rejected") {
        // 通话已结束/被拒绝 → 关闭来电通知
        setIncomingCall(null);
        incomingCallRef.current = null;
        break;
      }

      if (msgType === "call_invite") {
        // 仅当消息不是自己发送的（别人发起的通话邀请）且当前没有来电通知时才弹出
        if (msg.authorId !== currentUserId && !incomingCallRef.current) {
          // 从消息体中解析会议链接
          const bodyMatch = msg.body?.match(
            /(\/[a-z]+\/w\/[a-zA-Z0-9-]+\/meetings\/[a-zA-Z0-9-]+)/,
          );
          const meetingUrl = bodyMatch?.[1] ?? msg.meetingUrl ?? "";
          const meetingIdMatch = meetingUrl.match(/meetings\/([a-zA-Z0-9-]+)/);
          const meetingId = meetingIdMatch?.[1] ?? "";

          // 判断通话类型：消息体中包含"语音"关键词则为语音通话
          const isVoice = msg.body?.includes("语音") || msg.body?.includes("voice") || false;

          const callData: IncomingCallData = {
            messageId: msg.id,
            callerId: msg.authorId ?? "",
            callerName: msg.author?.name ?? msg.author?.email ?? t("unknownUser"),
            callerImage: msg.author?.image ?? null,
            callType: isVoice ? "voice" : "video",
            meetingUrl,
            meetingId,
          };
          setIncomingCall(callData);
          incomingCallRef.current = callData;
        }
        break;
      }
    }
  }, [messages, currentUserId, t]);

  const isGroup = conversation.type === "group";

  // 单聊：找对方成员作为标题
  const otherMember = !isGroup
    ? conversation.members.find((m) => m.userId !== currentUserId)
    : null;
  const title = isGroup
    ? conversation.title ?? t("groupConversation")
    : otherMember?.user.name ?? otherMember?.user.email ?? t("unknownUser");

  /**
   * 发起通话（视频或语音）：
   * 1. 创建 instant meeting（POST /api/v1/workspaces/{wid}/meetings）
   * 2. 发送 call_invite 系统消息（body 含会议链接，通知对方加入）
   * 3. 跳转到会议页面（跳过大厅，直接进入会议室）
   *
   * @param videoEnabled true=视频通话, false=语音通话
   */
  const handleCall = useCallback(
    async (videoEnabled: boolean) => {
      if (isCalling || isVoiceCalling) return;
      const wid = conversation.workspaceId;
      const locale = params?.locale ?? "zh";
      if (videoEnabled) {
        setIsCalling(true);
      } else {
        setIsVoiceCalling(true);
      }
      try {
        // 创建即时会议
        const meeting = await api<{ id: string }>(
          `/api/v1/workspaces/${wid}/meetings`,
          {
            method: "POST",
            body: JSON.stringify({
              title: videoEnabled ? tIm("videoCall") : tIm("voiceCall"),
              type: "instant",
              videoEnabled,
            }),
          },
        );

        // 发送 call_invite 消息（body 包含会议链接，对方可点击加入）
        const meetingUrl = `/${locale}/w/${wid}/meetings/${meeting.id}`;
        onSend(
          `${videoEnabled ? tIm("callInvite") : tIm("voiceCallInvite")}: ${meetingUrl}`,
          { type: "call_invite" },
        );

        // 设置超时：如果对方未加入，自动发送 call_ended 消息
        const meetingId = meeting.id;
        if (callTimeoutRef.current) {
          clearTimeout(callTimeoutRef.current);
        }
        callTimeoutRef.current = setTimeout(async () => {
          try {
            const meetingData = await api<{
              status: string;
              participants: Array<{ userId: string; joinedAt: string }>;
            }>(`/api/v1/workspaces/${wid}/meetings/${meetingId}`);
            // 会议已结束 或 无其他参与者（只有发起者自己）→ 发送 call_ended
            const hasOtherParticipants =
              (meetingData?.participants ?? []).length > 1;
            if (meetingData?.status === "ended" || !hasOtherParticipants) {
              onSend(tIm("callEnded"), { type: "call_ended" });
            }
          } catch {
            // API 检查失败时不发送，避免误报
          }
          callTimeoutRef.current = null;
        }, CALL_TIMEOUT_MS);

        // 跳转到会议页面，跳过大厅直接进入会议室（skipLobby=true）
        router.push(
          `${meetingUrl}?conversationId=${conversation.id}&skipLobby=true`,
        );
      } catch {
        // 静默失败：网络错误时用户可重试
      } finally {
        if (videoEnabled) {
          setIsCalling(false);
        } else {
          setIsVoiceCalling(false);
        }
      }
    },
    [
      conversation.workspaceId,
      conversation.id,
      onSend,
      router,
      params,
      tIm,
      isCalling,
      isVoiceCalling,
    ],
  );

  /** 发起视频通话 */
  const handleVideoCall = useCallback(() => handleCall(true), [handleCall]);

  /** 发起语音通话 */
  const handleVoiceCall = useCallback(() => handleCall(false), [handleCall]);

  /** 接听来电：跳转到 MeetingRoom */
  const handleAcceptCall = useCallback(
    (callData: IncomingCallData) => {
      setIncomingCall(null);
      incomingCallRef.current = null;
      const wid = conversation.workspaceId;
      const locale = params?.locale ?? "zh";
      // 跳转到会议页面，跳过大厅直接进入会议室
      router.push(
        `/${locale}${callData.meetingUrl}?conversationId=${conversation.id}&skipLobby=true`,
      );
    },
    [router, conversation.id, conversation.workspaceId, params],
  );

  /** 拒绝来电：发送 call_rejected 消息 */
  const handleRejectCall = useCallback(
    (callData: IncomingCallData) => {
      setIncomingCall(null);
      incomingCallRef.current = null;
      onSend(tIm("callRejected"), { type: "call_rejected" });
    },
    [onSend, tIm],
  );

  /** 点击回复 */
  const handleReply = useCallback((mid: string) => {
    const msg = messages.find((m) => m.id === mid);
    if (msg) setReplyTo(msg);
  }, [messages]);

  /** 取消回复 */
  const handleCancelReply = useCallback(() => {
    setReplyTo(null);
  }, []);

  /** 回复引用目标（转换为 MessageInput 期望的格式） */
  const replyTarget = useMemo(
    () =>
      replyTo
        ? {
            id: replyTo.id,
            authorName: replyTo.author?.name ?? t("unknownUser"),
            body: replyTo.body,
          }
        : null,
    [replyTo, t],
  );

  /** 可提及的成员列表（群聊才需要，单聊只有两人也一并传入） */
  const mentionMembers = useMemo(
    () =>
      conversation.members.map((m) => ({
        userId: m.userId,
        user: {
          id: m.user.id,
          name: m.user.name,
          image: m.user.image,
        },
      })),
    [conversation.members],
  );

  /**
   * 正在输入提示文本。
   * - 1 人：xxx 正在输入…
   * - 2 人：xxx、yyy 正在输入…
   * - 3+ 人：多人正在输入…
   * 排除当前用户自己（自己输入不提示）。
   * 复用现有 i18n key: chat.typing ({names} 正在输入…) / chat.typingMany
   */
  const typingText = useMemo(() => {
    if (typingUserIds.length === 0) return "";
    // 过滤掉当前用户，并将 userId 映射到显示名
    const others = typingUserIds
      .filter((id) => id !== currentUserId)
      .map((id) => {
        const member = conversation.members.find((m) => m.userId === id);
        return member?.user.name ?? t("unknownUser");
      });
    if (others.length === 0) return "";
    if (others.length <= 2) return t("typing", { names: others.join("、") });
    return t("typingMany");
  }, [typingUserIds, currentUserId, conversation.members, t]);

  return (
    <div className="relative flex flex-col h-full bg-[var(--surface)]">
      {/* 实时来电通知（浮动在顶部） */}
      <IncomingCallNotification
        callData={incomingCall}
        onAccept={handleAcceptCall}
        onReject={handleRejectCall}
      />

      {/* 顶部 Header */}
      <div className="flex items-center justify-between gap-[var(--space-3)] px-[var(--space-4)] py-[var(--space-3)] border-b border-[var(--border)]">
        <div className="flex items-center gap-[var(--space-2)] min-w-0">
          {/* 会话标题 */}
          <h2
            className="truncate text-[length:var(--text-base)] font-[weight:var(--weight-semibold)] text-[var(--fg)]"
            title={title}
          >
            {title}
          </h2>
          {/* 成员数（群聊显示） */}
          {isGroup && (
            <span className="shrink-0 flex items-center gap-1 text-[length:var(--text-xs)] text-[var(--muted)]">
              <Users size={14} />
              {conversation.members.length}
            </span>
          )}
        </div>
        {/* 语音通话 + 视频通话 + 设置按钮 */}
        <div className="flex items-center gap-[var(--space-1)]">
          {/* 语音通话按钮：创建即时语音会议 → 发送 call_invite → 跳转会议页 */}
          <button
            type="button"
            onClick={handleVoiceCall}
            disabled={isVoiceCalling || isCalling}
            aria-label={
              isVoiceCalling ? tIm("calling") : tIm("voiceCall")
            }
            className="shrink-0 w-8 h-8 flex items-center justify-center rounded-[var(--radius-md)] text-[var(--muted)] hover:bg-[var(--surface-2)] hover:text-[var(--fg)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-2 focus-visible:outline-[var(--accent-ring)] focus-visible:outline-offset-2 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:bg-transparent disabled:hover:text-[var(--muted)]"
          >
            {isVoiceCalling ? (
              <Loader2 size={16} className="animate-spin" />
            ) : (
              <Phone size={16} />
            )}
          </button>
          {/* 视频通话按钮：创建即时视频会议 → 发送 call_invite → 跳转会议页 */}
          <button
            type="button"
            onClick={handleVideoCall}
            disabled={isCalling || isVoiceCalling}
            aria-label={isCalling ? tIm("calling") : tIm("videoCall")}
            className="shrink-0 w-8 h-8 flex items-center justify-center rounded-[var(--radius-md)] text-[var(--muted)] hover:bg-[var(--surface-2)] hover:text-[var(--fg)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-2 focus-visible:outline-[var(--accent-ring)] focus-visible:outline-offset-2 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:bg-transparent disabled:hover:text-[var(--muted)]"
          >
            {isCalling ? (
              <Loader2 size={16} className="animate-spin" />
            ) : (
              <Video size={16} />
            )}
          </button>
          {/* 设置按钮 */}
          {onSettings && (
            <button
              type="button"
              onClick={onSettings}
              aria-label={t("settings")}
              className="shrink-0 w-8 h-8 flex items-center justify-center rounded-[var(--radius-md)] text-[var(--muted)] hover:bg-[var(--surface-2)] hover:text-[var(--fg)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-2 focus-visible:outline-[var(--accent-ring)] focus-visible:outline-offset-2"
            >
              <Settings size={16} />
            </button>
          )}
        </div>
      </div>

      {/* 消息列表 */}
      <MessageList
        messages={messages}
        currentUserId={currentUserId}
        onEdit={onEdit}
        onRevoke={onRevoke}
        onReply={handleReply}
        onLoadMore={onLoadMore}
        hasMore={conversation.hasMoreMessages}
        loading={loadingMore}
      />

      {/* 正在输入指示器：紧贴输入框上方，仅当有 typing 文本时显示 */}
      {typingText && (
        <div
          className="px-[var(--space-4)] pt-[var(--space-2)] animate-pulse"
          aria-live="polite"
        >
          <span className="text-[length:var(--text-xs)] text-[var(--muted)]">
            {typingText}
          </span>
        </div>
      )}

      {/* 底部输入区：MessageInput 集成 @提及/文件上传/字数计数/AI 回复建议 */}
      <div className="border-t border-[var(--border)] px-[var(--space-4)] py-[var(--space-3)]">
        <MessageInput
          onSend={onSend}
          replyTo={replyTarget}
          onCancelReply={handleCancelReply}
          members={mentionMembers}
          conversationId={conversation.id}
        />
      </div>
    </div>
  );
}

"use client";

/**
 * 单个会话项（会话列表中的一行）
 *
 * 显示：
 *  - 头像：群聊用 title 首字 fallback，单聊用对方用户头像
 *  - 名称：群聊用 title，单聊用对方用户名
 *  - 最后消息预览（截断 30 字）
 *  - 时间（相对时间：刚刚 / N 分钟前 / 昨天 / 日期）
 *  - 未读数 badge（红色圆点或数字）
 *  - 高亮选中状态
 *
 * 所有样式走 design token（var(--*)），无裸 hex。
 * lucide-react 图标尺寸用 14/16（项目约定）。
 *
 * 拆分说明：ConversationItem 保持 client component（被 ConversationList client 引用），
 * onClick 交互逻辑委托给 ConversationItemClient 子组件。
 */

import { useTranslations, useLocale } from "next-intl";
import { BellOff } from "lucide-react";
import type { Conversation } from "./types";
import { ConversationItemClient } from "./ConversationItemClient";

/** 消息预览最大长度 */
const PREVIEW_MAX_LENGTH = 30;

interface ConversationItemProps {
  /** 会话数据 */
  conversation: Conversation;
  /** 是否选中（高亮） */
  active: boolean;
  /** 当前用户 ID（用于单聊中识别对方） */
  currentUserId: string;
  /** 点击选中会话 */
  onSelect: (id: string) => void;
  /** 对方用户是否在线（仅单聊有效，在头像右下角显示绿点） */
  isOnline?: boolean;
}

/**
 * 相对时间格式化（i18n）。
 * 刚刚 / N 分钟前 / N 小时前 / 昨天 / 月-日
 */
function formatRelativeTime(
  iso: string | null,
  t: (key: string, values?: { count?: number }) => string,
  locale: string,
): string | null {
  if (!iso) return null;
  const then = new Date(iso).getTime();
  if (Number.isNaN(then)) return null;
  const diff = Math.max(0, Date.now() - then);
  const sec = Math.floor(diff / 1000);
  if (sec < 60) return t("justNow");
  const min = Math.floor(sec / 60);
  if (min < 60) return t("minutesAgo", { count: min });
  const hr = Math.floor(min / 60);
  if (hr < 24) return t("hoursAgo", { count: hr });
  const day = Math.floor(hr / 24);
  if (day === 1) return t("daysAgo", { count: 1 });
  if (day < 30) return t("daysAgo", { count: day });
  return new Date(iso).toLocaleDateString(locale, { month: "numeric", day: "numeric" });
}

/** 截断文本到指定长度 */
function truncate(text: string, max: number): string {
  return text.length > max ? `${text.slice(0, max)}…` : text;
}

/** 从用户名提取首字母（大写），用于头像 fallback */
function getInitial(name: string | null): string {
  if (!name) return "?";
  const trimmed = name.trim();
  if (!trimmed) return "?";
  return trimmed[0].toUpperCase();
}

export function ConversationItem({
  conversation,
  active,
  currentUserId,
  onSelect,
  isOnline = false,
}: ConversationItemProps) {
  const t = useTranslations("time");
  const tChat = useTranslations("chat");
  const locale = useLocale();

  // 单聊：找对方成员；群聊：用 title
  const isGroup = conversation.type === "group";
  const otherMember = !isGroup
    ? conversation.members.find((m) => m.userId !== currentUserId)
    : null;

  // 名称
  const displayName = isGroup
    ? conversation.title ?? tChat("groupConversation")
    : otherMember?.user.name ?? otherMember?.user.email ?? tChat("unknownUser");

  // 头像
  const avatarUrl = isGroup
    ? conversation.avatar
    : otherMember?.user.image ?? null;
  const initial = isGroup
    ? getInitial(conversation.title)
    : getInitial(otherMember?.user.name ?? otherMember?.user.email ?? null);

  // 最后消息预览
  const lastMessage = conversation.messages?.[conversation.messages.length - 1];
  const preview = lastMessage
    ? truncate(lastMessage.body, PREVIEW_MAX_LENGTH)
    : conversation.description ?? "";

  // 时间
  const timeStr = formatRelativeTime(conversation.lastMessageAt, t, locale);

  // 未读数
  const unread = conversation.unreadCount ?? 0;

  // 当前用户在该会话中是否静音
  const isMuted = conversation.members.find((m) => m.userId === currentUserId)?.muted ?? false;

  return (
    <ConversationItemClient
      conversationId={conversation.id}
      active={active}
      displayName={displayName}
      avatarUrl={avatarUrl}
      initial={initial}
      preview={preview}
      timeStr={timeStr}
      unread={unread}
      isOnline={isOnline}
      isMuted={isMuted}
      onlineLabel={tChat("online")}
      noMessagesLabel={tChat("noMessages")}
      onSelect={onSelect}
    />
  );
}

"use client";

/**
 * @提及自动补全弹窗
 *
 * - 接收 @ 后的搜索文本，过滤成员列表（name 包含 query，不区分大小写）
 * - 显示成员列表：头像 + 名称 + email
 * - 键盘导航：上下箭头选择，Enter 确认，Escape 关闭
 * - 定位在光标附近（由 position 属性指定）
 *
 * 所有样式走 design token（var(--*)），无裸 hex。
 * lucide-react 图标尺寸用 14/16（项目约定）。
 */

import { useEffect, useMemo, useRef, useState, type KeyboardEvent } from "react";

/** 可提及的成员项 */
interface MentionableMember {
  userId: string;
  user: {
    id: string;
    name: string | null;
    email: string | null;
    image: string | null;
  };
}

interface MentionPopoverProps {
  /** @ 后的搜索文本 */
  query: string;
  /** 可提及的成员列表 */
  members: MentionableMember[];
  /** 选中成员回调 */
  onSelect: (userId: string, userName: string) => void;
  /** 关闭弹窗回调 */
  onClose: () => void;
  /** 弹窗定位（光标附近坐标，像素） */
  position: { top: number; left: number };
}

/** 弹窗最大显示条数 */
const MAX_VISIBLE = 8;

export function MentionPopover({
  query,
  members,
  onSelect,
  onClose,
  position,
}: MentionPopoverProps) {
  // 当前高亮索引
  const [activeIdx, setActiveIdx] = useState(0);
  // 列表容器引用（用于滚动到高亮项）
  const listRef = useRef<HTMLUListElement>(null);

  // 过滤成员：name 或 email 包含 query（不区分大小写）
  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return members.slice(0, MAX_VISIBLE);
    return members
      .filter((m) => {
        const name = m.user.name?.toLowerCase() ?? "";
        const email = m.user.email?.toLowerCase() ?? "";
        return name.includes(q) || email.includes(q);
      })
      .slice(0, MAX_VISIBLE);
  }, [query, members]);

  // query 变化时重置高亮
  useEffect(() => {
    setActiveIdx(0);
  }, [query]);

  // 高亮项变化时滚动到可见区域
  useEffect(() => {
    const list = listRef.current;
    if (!list) return;
    const item = list.children[activeIdx] as HTMLElement | undefined;
    if (item) {
      item.scrollIntoView({ block: "nearest" });
    }
  }, [activeIdx]);

  // 键盘导航：在弹窗挂载期间监听全局 keydown（capture 阶段，先于 textarea 处理）
  useEffect(() => {
    const handleKeyDown = (e: globalThis.KeyboardEvent) => {
      if (filtered.length === 0) return;

      if (e.key === "ArrowDown") {
        e.preventDefault();
        e.stopPropagation();
        setActiveIdx((prev) => (prev + 1) % filtered.length);
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        e.stopPropagation();
        setActiveIdx((prev) => (prev - 1 + filtered.length) % filtered.length);
      } else if (e.key === "Enter") {
        e.preventDefault();
        e.stopPropagation();
        const selected = filtered[activeIdx];
        if (selected) {
          const name = selected.user.name ?? selected.user.email ?? selected.user.id;
          onSelect(selected.userId, name);
        }
      } else if (e.key === "Escape") {
        e.preventDefault();
        e.stopPropagation();
        onClose();
      }
    };

    window.addEventListener("keydown", handleKeyDown, true);
    return () => window.removeEventListener("keydown", handleKeyDown, true);
  }, [filtered, activeIdx, onSelect, onClose]);

  // 空结果：不渲染
  if (filtered.length === 0) return null;

  /** 获取成员显示名 */
  const getDisplayName = (m: MentionableMember): string =>
    m.user.name ?? m.user.email ?? m.user.id;

  /** 获取头像首字母 */
  const getInitial = (m: MentionableMember): string =>
    (m.user.name ?? m.user.email ?? "?")[0]?.toUpperCase() ?? "?";

  return (
    <ul
      ref={listRef}
      role="listbox"
      aria-label="mention-suggestions"
      style={{ top: position.top, left: position.left }}
      className="fixed z-[var(--z-dropdown)] w-64 max-h-64 overflow-y-auto py-1 rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] shadow-[var(--elev-md)]"
    >
      {filtered.map((m, idx) => {
        const name = getDisplayName(m);
        const isActive = idx === activeIdx;
        return (
          <li
            key={m.userId}
            role="option"
            aria-selected={isActive}
            onMouseEnter={() => setActiveIdx(idx)}
            onMouseDown={(e) => {
              // mousedown 阻止失焦，点击即选中
              e.preventDefault();
              onSelect(m.userId, name);
            }}
            className={`flex items-center gap-[var(--space-2)] px-[var(--space-3)] py-[var(--space-2)] cursor-pointer transition-colors duration-[var(--motion-fast)] ${
              isActive
                ? "bg-[var(--accent-soft)]"
                : "hover:bg-[var(--surface-2)]"
            }`}
          >
            {/* 头像 */}
            <div className="shrink-0 w-6 h-6 rounded-full bg-[var(--surface-3)] text-[var(--muted)] flex items-center justify-center text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] overflow-hidden">
              {m.user.image ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img src={m.user.image} alt={name} className="w-full h-full object-cover" />
              ) : (
                getInitial(m)
              )}
            </div>
            {/* 名称 + email */}
            <div className="min-w-0 flex-1">
              <div className="truncate text-[length:var(--text-sm)] text-[var(--fg)] font-[weight:var(--weight-medium)]">
                {name}
              </div>
              {m.user.email && (
                <div className="truncate text-[length:var(--text-xs)] text-[var(--meta)]">
                  {m.user.email}
                </div>
              )}
            </div>
          </li>
        );
      })}
    </ul>
  );
}

"use client";

/**
 * 单条消息气泡
 *
 * - 气泡布局：自己的消息靠右（accent 色），他人消息靠左（surface-2 色）
 * - 头像（24x24）
 * - 作者名（群聊显示，单聊可省略）
 * - 消息体（支持多行、URL 链接、@提及高亮）
 * - 时间（相对时间）
 * - 已读状态（readByCount > 0 → CheckCheck，否则 Check）
 * - 编辑标记（"已编辑"）
 * - 撤回状态（"消息已撤回"）
 * - 回复引用（显示被回复消息的摘要）
 * - 附件预览（图片缩略图 / 文件名）
 * - 桌面端 hover 时显示操作按钮（编辑、撤回、回复）
 * - 移动端长按弹出底部操作菜单
 * - 撤回消息前弹出确认弹窗
 * - call_invite 卡片显示通话状态（进行中 / 已结束）
 * - 内联编辑：点击编辑后变为 textarea，保存/取消
 *
 * 所有样式走 design token（var(--*)），无裸 hex。
 * lucide-react 图标尺寸用 14/16（项目约定）。
 */

import { memo, useState, useCallback, useRef, useEffect, type KeyboardEvent, type TouchEvent } from "react";
import {
  CheckCheck,
  Check,
  Edit,
  Trash,
  Reply,
  FileText,
  Download,
  ListTodo,
  Video,
  PhoneOff,
} from "lucide-react";
import { useTranslations, useLocale } from "next-intl";
import { useParams } from "next/navigation";
import Link from "next/link";
import type { Message } from "./types";

/** 回复引用摘要最大长度 */
const REPLY_PREVIEW_MAX = 50;
/** 消息体最大长度 */
const MAX_BODY_LENGTH = 10000;
/** 长按触发时长（ms） */
const LONG_PRESS_DURATION = 500;
/** 长按触发阈值（px），超过此距离则取消 */
const LONG_PRESS_TOLERANCE = 10;

interface MessageItemProps {
  /** 消息数据 */
  message: Message;
  /** 是否为自己的消息 */
  isOwn: boolean;
  /** 是否显示作者名（群聊显示，单聊可省略） */
  showAuthor: boolean;
  /** 编辑消息 */
  onEdit: (mid: string, body: string) => void;
  /** 撤回消息 */
  onRevoke: (mid: string) => void;
  /** 回复消息（可选） */
  onReply?: (mid: string) => void;
  /** 该 call_invite 消息对应的通话是否已结束（仅 call_invite 类型使用） */
  callEnded?: boolean;
}

/** 相对时间格式化（i18n） */
function formatRelativeTime(
  iso: string,
  t: (key: string, values?: { count?: number }) => string,
  locale: string,
): string {
  const then = new Date(iso).getTime();
  if (Number.isNaN(then)) return iso;
  const diff = Math.max(0, Date.now() - then);
  const sec = Math.floor(diff / 1000);
  if (sec < 60) return t("justNow");
  const min = Math.floor(sec / 60);
  if (min < 60) return t("minutesAgo", { count: min });
  const hr = Math.floor(min / 60);
  if (hr < 24) return t("hoursAgo", { count: hr });
  const day = Math.floor(hr / 24);
  if (day < 30) return t("daysAgo", { count: day });
  return new Date(iso).toLocaleDateString(locale, { month: "numeric", day: "numeric" });
}

/** 格式化文件大小 */
function formatFileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

/** 判断是否为图片类型 */
function isImageAttachment(fileType: string): boolean {
  return fileType.startsWith("image/");
}

/** URL 正则 */
const URL_REGEX = /(https?:\/\/[^\s<>"']+)/g;
/** @提及正则 */
const MENTION_REGEX = /(@[\w\u4e00-\u9fa5]+)/g;
/** 任务链接正则：[task:taskId:taskTitle]（taskId 为 UUID，taskTitle 为任意非 ] 字符） */
const TASK_REGEX = /\[task:([a-zA-Z0-9-]+):([^\]]+)\]/g;

/** 任务链接 token（renderLine 中识别后渲染为任务卡片） */
interface TaskToken {
  taskId: string;
  taskTitle: string;
}

/**
 * 渲染消息体：支持多行、URL 链接、@提及高亮、任务卡片。
 * 先按行分割，每行内识别 URL、@mention 和 [task:...] 链接。
 * wid 用于构造任务卡片跳转链接 /w/{wid}/task/{taskId}。
 */
function renderBody(body: string, wid: string | undefined): React.ReactNode {
  const lines = body.split("\n");
  return lines.map((line, lineIdx) => (
    <span key={lineIdx}>
      {renderLine(line, wid)}
      {lineIdx < lines.length - 1 && <br />}
    </span>
  ));
}

/** 渲染单行：识别 URL、@mention 和 [task:...] 任务链接 */
function renderLine(line: string, wid: string | undefined): React.ReactNode[] {
  // 合并 URL、mention 和 task 的匹配
  const tokens: {
    text: string;
    type: "url" | "mention" | "task" | "text";
    task?: TaskToken;
  }[] = [];
  let remaining = line;

  while (remaining.length > 0) {
    const urlMatch = remaining.match(URL_REGEX);
    const mentionMatch = remaining.match(MENTION_REGEX);
    const taskMatch = remaining.match(TASK_REGEX);

    const urlIdx = urlMatch ? remaining.indexOf(urlMatch[0]) : -1;
    const mentionIdx = mentionMatch ? remaining.indexOf(mentionMatch[0]) : -1;
    const taskIdx = taskMatch ? remaining.indexOf(taskMatch[0]) : -1;

    // 三者都未匹配：剩余作为纯文本
    if (urlIdx === -1 && mentionIdx === -1 && taskIdx === -1) {
      tokens.push({ text: remaining, type: "text" });
      break;
    }

    // 取最先匹配的（最小索引）
    const candidates: Array<{ idx: number; type: "url" | "mention" | "task"; text: string }> = [];
    if (urlIdx !== -1) candidates.push({ idx: urlIdx, type: "url", text: urlMatch?.[0] ?? "" });
    if (mentionIdx !== -1)
      candidates.push({ idx: mentionIdx, type: "mention", text: mentionMatch?.[0] ?? "" });
    if (taskIdx !== -1) candidates.push({ idx: taskIdx, type: "task", text: taskMatch?.[0] ?? "" });

    candidates.sort((a, b) => a.idx - b.idx);
    const chosen = candidates[0];

    if (chosen.idx > 0) {
      tokens.push({ text: remaining.slice(0, chosen.idx), type: "text" });
    }

    if (chosen.type === "task") {
      // 解析 [task:taskId:taskTitle]
      const match = chosen.text.match(TASK_REGEX);
      // match 不会为 null（已确认 taskIdx !== -1）
      tokens.push({
        text: chosen.text,
        type: "task",
        task: { taskId: match?.[1] ?? "", taskTitle: match?.[2] ?? "" },
      });
    } else {
      tokens.push({ text: chosen.text, type: chosen.type });
    }
    remaining = remaining.slice(chosen.idx + chosen.text.length);
  }

  return tokens.map((tok, i) => {
    if (tok.type === "url") {
      return (
        <a
          key={i}
          href={tok.text}
          target="_blank"
          rel="noopener noreferrer"
          className="underline hover:opacity-80 break-all"
        >
          {tok.text}
        </a>
      );
    }
    if (tok.type === "mention") {
      return (
        <span
          key={i}
          className="text-[var(--accent)] font-[weight:var(--weight-medium)]"
        >
          {tok.text}
        </span>
      );
    }
    if (tok.type === "task" && tok.task) {
      // 任务卡片：带边框的 inline 元素，点击跳转到任务详情页
      const href = wid ? `/w/${wid}/task/${tok.task.taskId}` : "#";
      return (
        <Link
          key={i}
          href={href}
          className="inline-flex items-center gap-1 px-2 py-0.5 rounded-[var(--radius-sm)] border border-[var(--accent)] bg-[var(--accent-soft)] text-[var(--accent)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent)] hover:text-[var(--accent-fg)] transition-colors"
        >
          <ListTodo size={14} className="shrink-0" />
          <span className="truncate max-w-[200px]">{tok.task.taskTitle}</span>
        </Link>
      );
    }
    return <span key={i}>{tok.text}</span>;
  });
}

function MessageItemImpl({
  message,
  isOwn,
  showAuthor,
  onEdit,
  onRevoke,
  onReply,
  callEnded = false,
}: MessageItemProps) {
  const t = useTranslations("chat");
  const tIm = useTranslations("im");
  const tTime = useTranslations("time");
  const locale = useLocale();
  // 从路由 /[locale]/w/[wid]/im 获取当前工作区 ID（用于任务卡片跳转链接）
  const params = useParams<{ locale: string; wid: string }>();
  const wid = params?.wid;
  const [editing, setEditing] = useState(false);
  const [editBody, setEditBody] = useState(message.body);
  // 撤回确认弹窗
  const [showRevokeConfirm, setShowRevokeConfirm] = useState(false);
  // 移动端操作菜单（底部弹出）
  const [showMobileMenu, setShowMobileMenu] = useState(false);

  // 长按手势检测
  const longPressTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const longPressStartRef = useRef<{ x: number; y: number } | null>(null);

  // 组件卸载时清理长按计时器，防止卸载后 setState
  useEffect(() => {
    return () => {
      if (longPressTimerRef.current) {
        clearTimeout(longPressTimerRef.current);
        longPressTimerRef.current = null;
      }
    };
  }, []);

  const author = message.author;
  const displayName = author
    ? author.name ?? author.email ?? t("unknownUser")
    : t("unknownUser");
  const initial = (author?.name ?? author?.email ?? "?")[0]?.toUpperCase() ?? "?";

  const isRevoked = message.revokedAt !== null;
  const isEdited = message.editedAt !== null && !isRevoked;
  const timeStr = formatRelativeTime(message.createdAt, tTime, locale);
  // 已读回执：readByCount > 0 显示双勾（已读），否则显示单勾（已发送未读）
  const readByCount = message.readByCount ?? 0;
  const isRead = readByCount > 0;

  /** 进入编辑模式 */
  const handleStartEdit = useCallback(() => {
    setEditBody(message.body);
    setEditing(true);
    setShowMobileMenu(false);
  }, [message.body]);

  /** 保存编辑 */
  const handleSaveEdit = useCallback(() => {
    const trimmed = editBody.trim();
    if (!trimmed || trimmed === message.body) {
      setEditing(false);
      return;
    }
    onEdit(message.id, trimmed);
    setEditing(false);
  }, [editBody, message.id, message.body, onEdit]);

  /** 取消编辑 */
  const handleCancelEdit = useCallback(() => {
    setEditing(false);
    setEditBody(message.body);
  }, [message.body]);

  /** 编辑框键盘事件 */
  const handleEditKeyDown = useCallback(
    (e: KeyboardEvent<HTMLTextAreaElement>) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
        e.preventDefault();
        handleSaveEdit();
      } else if (e.key === "Escape") {
        e.preventDefault();
        handleCancelEdit();
      }
    },
    [handleSaveEdit, handleCancelEdit],
  );

  /** 确认撤回消息 */
  const handleConfirmRevoke = useCallback(() => {
    setShowRevokeConfirm(false);
    setShowMobileMenu(false);
    onRevoke(message.id);
  }, [message.id, onRevoke]);

  /** 长按开始：启动计时器 */
  const handleTouchStart = useCallback(
    (e: TouchEvent<HTMLDivElement>) => {
      const touch = e.touches[0];
      longPressStartRef.current = { x: touch.clientX, y: touch.clientY };
      longPressTimerRef.current = setTimeout(() => {
        setShowMobileMenu(true);
        // 触觉反馈（如果设备支持）
        if (typeof navigator !== "undefined" && navigator.vibrate) {
          navigator.vibrate(50);
        }
      }, LONG_PRESS_DURATION);
    },
    [],
  );

  /** 长按结束：清除计时器 */
  const handleTouchEnd = useCallback(() => {
    if (longPressTimerRef.current) {
      clearTimeout(longPressTimerRef.current);
      longPressTimerRef.current = null;
    }
    longPressStartRef.current = null;
  }, []);

  /** 长按移动：超过阈值则取消 */
  const handleTouchMove = useCallback(
    (e: TouchEvent<HTMLDivElement>) => {
      const start = longPressStartRef.current;
      if (!start) return;
      const touch = e.touches[0];
      const dx = Math.abs(touch.clientX - start.x);
      const dy = Math.abs(touch.clientY - start.y);
      if (dx > LONG_PRESS_TOLERANCE || dy > LONG_PRESS_TOLERANCE) {
        if (longPressTimerRef.current) {
          clearTimeout(longPressTimerRef.current);
          longPressTimerRef.current = null;
        }
      }
    },
    [],
  );

  // 撤回消息：只显示"消息已撤回"
  if (isRevoked) {
    return (
      <div className={`flex gap-[var(--space-2)] ${isOwn ? "flex-row-reverse" : "flex-row"}`}>
        {/* 头像 */}
        <div className="shrink-0 w-6 h-6 rounded-full bg-[var(--surface-3)] text-[var(--muted)] flex items-center justify-center text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] overflow-hidden">
          {author?.image ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img src={author.image} alt={displayName} className="w-full h-full object-cover" />
          ) : (
            initial
          )}
        </div>
        <div className={`flex flex-col ${isOwn ? "items-end" : "items-start"}`}>
          <div className="px-[var(--space-3)] py-[var(--space-2)] rounded-[var(--radius-md)] bg-[var(--surface-2)] text-[var(--meta)] text-[length:var(--text-sm)] italic">
            {t("messageRevoked")}
          </div>
        </div>
      </div>
    );
  }

  // ── call / system 消息特殊渲染 ──
  const messageType = message.type ?? "text";

  // call_ended / call_rejected / system: 居中系统消息（灰色、无气泡、居中）
  if (
    messageType === "call_ended" ||
    messageType === "call_rejected" ||
    messageType === "system"
  ) {
    const systemText =
      messageType === "call_ended"
        ? tIm("callEnded")
        : messageType === "call_rejected"
          ? tIm("callRejected")
          : message.body;
    return (
      <div className="flex justify-center py-1">
        <span className="text-[length:var(--text-xs)] text-[var(--meta)]">
          {systemText}
        </span>
      </div>
    );
  }

  // call_invite: 通话邀请卡片（含通话状态 + "加入通话"按钮）
  if (messageType === "call_invite") {
    const meetingUrl = message.meetingUrl;
    const callStatus = message.callStatus ?? "ongoing";
    const isCallEnded = callStatus === "ended" || callStatus === "rejected";
    return (
      <div className="flex justify-center py-2">
        <div className="inline-flex flex-col items-center gap-2 px-4 py-3 rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] max-w-[280px]">
          {isCallEnded ? (
            <PhoneOff size={16} className="text-[var(--meta)]" />
          ) : (
            <Video size={16} className="text-[var(--accent)]" />
          )}
          <span className="text-[length:var(--text-sm)] text-[var(--fg)] text-center">
            {tIm("callInvite")}
          </span>
          {isCallEnded ? (
            <span className="text-[length:var(--text-xs)] text-[var(--meta)]">
              {callStatus === "rejected" ? tIm("callRejected") : tIm("callEndedLabel")}
            </span>
          ) : (
            <>
              <span className="text-[length:var(--text-xs)] text-[var(--accent)]">
                {tIm("callInProgress")}
              </span>
              {meetingUrl && (
                <Link
                  href={meetingUrl}
                  className="inline-flex items-center gap-1.5 h-8 px-3 rounded-[var(--radius-md)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] transition-colors duration-[var(--motion-fast)]"
                >
                  {tIm("joinCall")}
                </Link>
              )}
            </>
          )}
        </div>
      </div>
    );
  }

  return (
    <>
      <div
        className={`group flex gap-[var(--space-2)] relative ${isOwn ? "flex-row-reverse" : "flex-row"}`}
        onTouchStart={handleTouchStart}
        onTouchEnd={handleTouchEnd}
        onTouchMove={handleTouchMove}
      >
        {/* 头像 */}
        <div className="shrink-0 w-6 h-6 rounded-full bg-[var(--surface-3)] text-[var(--muted)] flex items-center justify-center text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] overflow-hidden">
          {author?.image ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img src={author.image} alt={displayName} className="w-full h-full object-cover" />
          ) : (
            initial
          )}
        </div>

        {/* 气泡 */}
        <div className={`min-w-0 max-w-[70%] flex flex-col ${isOwn ? "items-end" : "items-start"}`}>
          {/* 作者名（群聊且非自己的消息） */}
          {showAuthor && !isOwn && (
            <span className="text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] text-[var(--fg)] mb-0.5">
              {displayName}
            </span>
          )}

          {/* 回复引用 */}
          {message.replyTo && (
            <div
              className={`mb-1 px-[var(--space-2)] py-1 rounded-[var(--radius-sm)] border-l-2 border-[var(--accent)] bg-[var(--surface-2)] text-[length:var(--text-xs)] text-[var(--muted)] max-w-full truncate ${
                isOwn ? "text-right" : "text-left"
              }`}
            >
              <span className="text-[var(--accent)] font-[weight:var(--weight-medium)]">
                {message.replyTo.author?.name ?? t("unknownUser")}:
              </span>{" "}
              {message.replyTo.body.slice(0, REPLY_PREVIEW_MAX)}
              {message.replyTo.body.length > REPLY_PREVIEW_MAX ? "…" : ""}
            </div>
          )}

          {/* 消息体 */}
          {editing ? (
            // 编辑模式
            <div className="w-full">
              <textarea
                value={editBody}
                onChange={(e) => setEditBody(e.target.value.slice(0, MAX_BODY_LENGTH))}
                onKeyDown={handleEditKeyDown}
                rows={Math.min(5, editBody.split("\n").length)}
                autoFocus
                className="w-full px-[var(--space-3)] py-[var(--space-2)] rounded-[var(--radius-md)] border border-[var(--accent)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg)] outline-none resize-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)]"
              />
              <div className={`flex gap-[var(--space-2)] mt-1 ${isOwn ? "justify-end" : "justify-start"}`}>
                <button
                  type="button"
                  onClick={handleCancelEdit}
                  className="px-[var(--space-2)] py-1 rounded-[var(--radius-sm)] text-[length:var(--text-xs)] text-[var(--muted)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
                >
                  {t("cancel")}
                </button>
                <button
                  type="button"
                  onClick={handleSaveEdit}
                  className="px-[var(--space-2)] py-1 rounded-[var(--radius-sm)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] transition-colors duration-[var(--motion-fast)]"
                >
                  {t("save")}
                </button>
              </div>
            </div>
          ) : (
            <div
              className={`px-[var(--space-3)] py-[var(--space-2)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] leading-[var(--leading-relaxed)] break-words ${
                isOwn
                  ? "bg-[var(--accent)] text-[var(--accent-fg)]"
                  : "bg-[var(--surface-2)] text-[var(--fg)]"
              }`}
            >
              {/* 正文 */}
              {message.body && <span>{renderBody(message.body, wid)}</span>}

              {/* 附件列表 */}
              {message.attachments.length > 0 && (
                <div className={`space-y-1 ${message.body ? "mt-1 pt-1" : ""}`}>
                  {message.attachments.map((att) =>
                    isImageAttachment(att.fileType) && att.thumbnailUrl ? (
                      // 图片附件：缩略图
                      <a
                        key={att.id}
                        href={att.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="block rounded-[var(--radius-sm)] overflow-hidden hover:opacity-90 transition-opacity cursor-zoom-in"
                      >
                        {/* eslint-disable-next-line @next/next/no-img-element */}
                        <img
                          src={att.thumbnailUrl}
                          alt={att.fileName}
                          className="max-w-[200px] max-h-[150px] object-cover"
                        />
                      </a>
                    ) : (
                      // 文档附件：文件卡片
                      <a
                        key={att.id}
                        href={att.url}
                        download={att.fileName}
                        target="_blank"
                        rel="noopener noreferrer"
                        className={`flex items-center gap-2 px-2.5 py-1.5 rounded-[var(--radius-sm)] border ${
                          isOwn
                            ? "border-[color-mix(in_srgb,var(--accent-fg)_20%,transparent)] bg-[color-mix(in_srgb,var(--accent-fg)_10%,transparent)]"
                            : "border-[var(--border)] bg-[var(--surface-3)]"
                        } hover:opacity-80 transition-opacity min-w-0 sm:min-w-[200px]`}
                      >
                        <FileText size={16} className="shrink-0" />
                        <div className="min-w-0 flex-1">
                          <div className="text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] truncate">
                            {att.fileName}
                          </div>
                          <div className="text-[length:var(--text-xs)] opacity-70">
                            {formatFileSize(att.fileSize)}
                          </div>
                        </div>
                        <Download size={14} className="shrink-0 opacity-70" />
                      </a>
                    ),
                  )}
                </div>
              )}
            </div>
          )}

          {/* 元信息行：时间 + 已编辑 + 已读 */}
          {!editing && (
            <div
              className={`mt-0.5 flex items-center gap-1 text-[length:var(--text-xs)] text-[var(--meta)] ${isOwn ? "flex-row-reverse" : "flex-row"}`}
            >
              <span>{timeStr}</span>
              {isEdited && <span className="italic">· {t("edited")}</span>}
              {isOwn && (
                <span title={isRead ? t("read") : t("sent")}>
                  {isRead ? <CheckCheck size={14} /> : <Check size={14} />}
                </span>
              )}
            </div>
          )}
        </div>

        {/* hover 操作按钮 — 仅桌面端（支持 hover 的设备）显示 */}
        {!editing && !isRevoked && (
          <div
            className={`absolute top-0 ${isOwn ? "left-0" : "right-0"} opacity-0 group-hover:opacity-100 transition-opacity duration-[var(--motion-fast)] flex items-center gap-0.5 rounded-[var(--radius-sm)] bg-[var(--surface)] border border-[var(--border)] shadow-[var(--elev-sm)] p-0.5 [@media(hover:hover)]:flex hidden`}
          >
            {onReply && (
              <button
                type="button"
                onClick={() => onReply(message.id)}
                aria-label={t("reply")}
                className="w-6 h-6 flex items-center justify-center rounded-[var(--radius-sm)] text-[var(--muted)] hover:bg-[var(--surface-2)] hover:text-[var(--fg)] transition-colors duration-[var(--motion-fast)]"
              >
                <Reply size={14} />
              </button>
            )}
            {isOwn && (
              <>
                <button
                  type="button"
                  onClick={handleStartEdit}
                  aria-label={t("edit")}
                  className="w-6 h-6 flex items-center justify-center rounded-[var(--radius-sm)] text-[var(--muted)] hover:bg-[var(--surface-2)] hover:text-[var(--fg)] transition-colors duration-[var(--motion-fast)]"
                >
                  <Edit size={14} />
                </button>
                <button
                  type="button"
                  onClick={() => setShowRevokeConfirm(true)}
                  aria-label={t("revoke")}
                  className="w-6 h-6 flex items-center justify-center rounded-[var(--radius-sm)] text-[var(--muted)] hover:bg-[var(--danger-soft)] hover:text-[var(--danger)] transition-colors duration-[var(--motion-fast)]"
                >
                  <Trash size={14} />
                </button>
              </>
            )}
          </div>
        )}
      </div>

      {/* 撤回确认弹窗 */}
      {showRevokeConfirm && (
        <div
          className="fixed inset-0 z-[var(--z-modal)] flex items-center justify-center bg-[var(--overlay)] p-[var(--space-4)]"
          role="dialog"
          aria-modal="true"
          aria-label={t("confirmRevoke")}
          onClick={() => setShowRevokeConfirm(false)}
        >
          <div
            className="w-full max-w-sm rounded-[var(--radius-lg)] bg-[var(--surface)] border border-[var(--border)] shadow-[var(--elev-lg)] p-[var(--space-5)]"
            onClick={(e) => e.stopPropagation()}
          >
            <h3 className="text-[length:var(--text-md)] font-[weight:var(--weight-semibold)] text-[var(--fg)] mb-[var(--space-2)]">
              {t("confirmRevoke")}
            </h3>
            <div className="flex items-center justify-end gap-[var(--space-2)] mt-[var(--space-4)]">
              <button
                type="button"
                onClick={() => setShowRevokeConfirm(false)}
                className="h-8 px-[var(--space-3)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
              >
                {t("cancel")}
              </button>
              <button
                type="button"
                onClick={handleConfirmRevoke}
                className="h-8 px-[var(--space-3)] rounded-[var(--radius-md)] bg-[var(--danger)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:opacity-90 transition-opacity duration-[var(--motion-fast)]"
              >
                {t("confirm")}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 移动端底部操作菜单 */}
      {showMobileMenu && (
        <div
          className="fixed inset-0 z-[var(--z-modal)] flex items-end justify-center bg-[var(--overlay)]"
          role="dialog"
          aria-modal="true"
          aria-label={t("moreActions")}
          onClick={() => setShowMobileMenu(false)}
        >
          <div
            className="w-full max-w-sm rounded-t-[var(--radius-lg)] bg-[var(--surface)] border border-[var(--border)] shadow-[var(--elev-lg)] p-[var(--space-3)] pb-safe"
            onClick={(e) => e.stopPropagation()}
          >
            {/* 操作选项 */}
            <div className="flex flex-col gap-[var(--space-1)]">
              {onReply && (
                <button
                  type="button"
                  onClick={() => {
                    onReply(message.id);
                    setShowMobileMenu(false);
                  }}
                  className="flex items-center gap-[var(--space-3)] px-[var(--space-4)] py-[var(--space-3)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] text-[var(--fg)] hover:bg-[var(--surface-2)] active:bg-[var(--surface-3)] transition-colors duration-[var(--motion-fast)]"
                >
                  <Reply size={16} className="text-[var(--muted)]" />
                  {t("reply")}
                </button>
              )}
              {isOwn && (
                <>
                  <button
                    type="button"
                    onClick={handleStartEdit}
                    className="flex items-center gap-[var(--space-3)] px-[var(--space-4)] py-[var(--space-3)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] text-[var(--fg)] hover:bg-[var(--surface-2)] active:bg-[var(--surface-3)] transition-colors duration-[var(--motion-fast)]"
                  >
                    <Edit size={16} className="text-[var(--muted)]" />
                    {t("edit")}
                  </button>
                  <button
                    type="button"
                    onClick={() => {
                      setShowMobileMenu(false);
                      setShowRevokeConfirm(true);
                    }}
                    className="flex items-center gap-[var(--space-3)] px-[var(--space-4)] py-[var(--space-3)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] text-[var(--danger)] hover:bg-[var(--danger-soft)] active:bg-[var(--danger-soft)] transition-colors duration-[var(--motion-fast)]"
                  >
                    <Trash size={16} />
                    {t("revoke")}
                  </button>
                </>
              )}
            </div>
            {/* 取消按钮 */}
            <button
              type="button"
              onClick={() => setShowMobileMenu(false)}
              className="w-full mt-[var(--space-2)] px-[var(--space-4)] py-[var(--space-3)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] text-[var(--fg-2)] bg-[var(--surface-2)] hover:bg-[var(--surface-3)] transition-colors duration-[var(--motion-fast)]"
            >
              {t("cancel")}
            </button>
          </div>
        </div>
      )}
    </>
  );
}

export const MessageItem = memo(MessageItemImpl);

"use client";

/**
 * IM 主 Hook —— 管理独立 IM 的所有状态和操作
 *
 * 职责：
 *  - 加载会话列表 / 会话详情 / 消息列表
 *  - 发送 / 编辑 / 撤回消息
 *  - 创建会话
 *  - 订阅 WebSocket 实时消息（新消息 / 编辑 / 撤回 / 在线状态 / 正在输入 / 已读）
 *  - 标记已读
 *
 * 数据流：
 *  1. 初始化时 loadConversations() 拉取会话列表
 *  2. selectConversation(cid) 加载会话详情 + 消息 + 订阅 WS + 标记已读
 *  3. ws.onMessage 统一处理服务端推送，更新 conversations / messages
 *
 * 错误处理：
 *  - API 失败时 setError(message)，loading 复位
 *  - WS 消息处理异常不抛出（避免中断订阅），仅 console.error
 */

import { useState, useEffect, useCallback, useRef } from "react";
import { useIMWebSocket } from "@/lib/im/ws-client";
import { api } from "@/lib/api";
import type { ServerMessage, MessagePayload } from "@/lib/im/types";
import type {
  Conversation,
  Message,
  SendMessageOptions,
  CreateConversationParams,
} from "./types";

/** 消息分页每页条数（与后端 limit 上限 200 对齐，取 50 平衡首屏性能） */
const MESSAGES_PAGE_SIZE = 50;

/** 消息列表 API 响应（游标分页信封） */
interface MessagesListResponse {
  messages: Message[];
  hasMore: boolean;
}

/**
 * 将 WebSocket 推送的 MessagePayload 转换为前端 Message 类型。
 *
 * MessagePayload 扁平存储作者信息（authorName/authorImage），
 * 前端 Message 用嵌套 author 对象，且需补齐 attachments 等字段。
 */
function payloadToMessage(p: MessagePayload): Message {
  return {
    id: p.id,
    conversationId: p.conversationId,
    authorId: p.authorId,
    author: {
      id: p.authorId ?? "",
      name: p.authorName,
      email: null,
      image: p.authorImage,
    },
    body: p.body,
    type: p.type ?? "text",
    createdAt: p.createdAt,
    editedAt: p.editedAt,
    revokedAt: p.revokedAt,
    revokedBy: null,
    replyToId: p.replyToId,
    replyTo: null,
    mentions: p.mentions,
    attachments: [],
    // call_invite 消息默认通话状态为 ongoing
    callStatus: p.type === "call_invite" ? "ongoing" : undefined,
  };
}

/** useIM Hook 返回值 */
export interface UseIMResult {
  /** 会话列表 */
  conversations: Conversation[];
  /** 当前选中的会话 */
  activeConversation: Conversation | null;
  /** 当前会话的消息列表（正序） */
  messages: Message[];
  /** 是否正在加载 */
  loading: boolean;
  /** 错误信息 */
  error: string | null;
  /** WebSocket 连接状态 */
  wsStatus: "connecting" | "connected" | "disconnected" | "error";
  /** 加载会话列表 */
  loadConversations: () => Promise<void>;
  /** 选择会话（加载详情 + 消息 + 订阅 + 标记已读） */
  selectConversation: (cid: string) => Promise<void>;
  /** 从任务 ID 获取/创建关联会话（任务详情页内嵌聊天用） */
  selectTaskConversation: (taskId: string) => Promise<void>;
  /** 加载更多历史消息（向上加载，用最早消息 createdAt 作 before 游标） */
  loadMoreMessages: (cid: string) => Promise<void>;
  /** 是否正在加载更多历史消息 */
  loadingMore: boolean;
  /** 发送消息 */
  sendMessage: (cid: string, body: string, opts?: SendMessageOptions) => Promise<void>;
  /** 编辑消息 */
  editMessage: (cid: string, mid: string, body: string) => Promise<void>;
  /** 撤回消息 */
  revokeMessage: (cid: string, mid: string) => Promise<void>;
  /** 创建会话 */
  createConversation: (params: CreateConversationParams) => Promise<Conversation>;
  /** 手动设置当前会话（不触发加载） */
  setActiveConversation: (c: Conversation | null) => void;
  /**
   * 正在输入的用户列表。
   * key 为 conversationId，value 为正在输入的 userId 列表。
   * typing 状态 5 秒无更新自动清除。
   */
  typingUsers: Record<string, string[]>;
}

/**
 * IM 主 Hook。
 *
 * @param workspaceId 当前工作区 ID
 * @param t i18n 翻译函数（useTranslations("chat") 的返回值），用于错误消息本地化
 * @returns IM 状态和操作方法
 */
export function useIM(
  workspaceId: string,
  t?: (key: string) => string,
): UseIMResult {
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [activeConversation, setActiveConversation] = useState<Conversation | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  /** 是否正在加载更多历史消息（独立于全局 loading，避免全屏 spinner） */
  const [loadingMore, setLoadingMore] = useState(false);
  /**
   * 正在输入的用户列表。
   * key 为 conversationId，value 为正在输入的 userId 列表。
   * 由 WebSocket "typing" 消息驱动，5 秒无更新自动清除。
   */
  const [typingUsers, setTypingUsers] = useState<Record<string, string[]>>({});

  const ws = useIMWebSocket(workspaceId);

  // 当前活跃会话 ID 引用（供 WS 消息处理判断是否属于当前会话）
  const activeCidRef = useRef<string | null>(null);
  // 请求序号（递增 counter），用于 selectConversation 竞态条件防护
  const requestSeqRef = useRef(0);
  // 消息列表引用（供 loadMoreMessages 读取最早消息游标，避免依赖 messages 致使函数频繁重建）
  const messagesRef = useRef<Message[]>([]);
  /**
   * typing 过期定时器映射。
   * key 为 `${conversationId}:${userId}`，value 为 setTimeout 句柄。
   * 每次收到 typing=true 时重置对应定时器，5 秒后清除该用户的 typing 状态。
   */
  const typingTimersRef = useRef<Record<string, ReturnType<typeof setTimeout>>>({});

  /** 加载会话列表 */
  const loadConversations = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await api<Conversation[]>(
        `/api/v1/workspaces/${workspaceId}/conversations`,
      );
      setConversations(data ?? []);
    } catch (err) {
      setError(err instanceof Error ? err.message : (t?.("loadConversationsFailed") ?? "Failed to load conversations"));
    } finally {
      setLoading(false);
    }
  }, [workspaceId]);

  /** 选择会话：加载详情 + 消息 + 订阅 WS + 标记已读 */
  const selectConversation = useCallback(
    async (cid: string) => {
      // 递增请求序号，用于竞态条件防护
      const seq = ++requestSeqRef.current;
      setLoading(true);
      setError(null);
      try {
        // 1. 加载会话详情
        const conv = await api<Conversation>(
          `/api/v1/workspaces/${workspaceId}/conversations/${cid}`,
        );

        // 竞态检查：如果用户已切换到其他会话，丢弃此旧响应
        if (seq !== requestSeqRef.current) return;

        // 2. 加载消息列表（游标分页，取最近 MESSAGES_PAGE_SIZE 条）
        const result = await api<MessagesListResponse>(
          `/api/v1/workspaces/${workspaceId}/conversations/${cid}/messages?limit=${MESSAGES_PAGE_SIZE}`,
        );

        // 竞态检查：加载消息后再次确认
        if (seq !== requestSeqRef.current) return;

        const initialMessages = result?.messages ?? [];
        const hasMoreMessages = result?.hasMore ?? false;

        setActiveConversation({ ...conv, hasMoreMessages });
        activeCidRef.current = cid;
        setMessages(initialMessages);

        // 3. 订阅 WebSocket
        ws.subscribe(cid);

        // 4. 标记已读（best-effort，失败不影响展示）
        try {
          await api(
            `/api/v1/workspaces/${workspaceId}/conversations/${cid}/read`,
            { method: "POST" },
          );
        } catch {
          // 标记已读失败静默忽略
        }

        // 5. 更新会话列表中的未读数
        setConversations((prev) =>
          prev.map((c) => (c.id === cid ? { ...c, unreadCount: 0 } : c)),
        );
      } catch (err) {
        // 竞态检查：错误响应也需丢弃旧请求
        if (seq !== requestSeqRef.current) return;
        setError(err instanceof Error ? err.message : (t?.("loadConversationFailed") ?? "Failed to load conversation"));
      } finally {
        // 竞态检查：仅当前请求才复位 loading
        if (seq === requestSeqRef.current) {
          setLoading(false);
        }
      }
    },
    [workspaceId, ws],
  );

  /** 从任务 ID 获取/创建关联会话（任务详情页内嵌聊天用） */
  const selectTaskConversation = useCallback(
    async (taskId: string) => {
      try {
        setError(null);
        const conv = await api<Conversation>(
          `/api/v1/workspaces/${workspaceId}/tasks/${taskId}/conversation`,
          { method: "POST" },
        );
        await selectConversation(conv.id);
      } catch (err) {
        setError(err instanceof Error ? err.message : (t?.("loadTaskConversationFailed") ?? "Failed to load task conversation"));
      }
    },
    [workspaceId, selectConversation],
  );

  /** 加载更多历史消息（向上加载）：用当前最早消息的 createdAt 作 before 游标 */
  const loadMoreMessages = useCallback(
    async (cid: string) => {
      const earliest = messagesRef.current[0];
      if (!earliest) return;

      setLoadingMore(true);
      try {
        const result = await api<MessagesListResponse>(
          `/api/v1/workspaces/${workspaceId}/conversations/${cid}/messages?before=${encodeURIComponent(earliest.createdAt)}&limit=${MESSAGES_PAGE_SIZE}`,
        );
        const olderMessages = result?.messages ?? [];
        const hasMoreMessages = result?.hasMore ?? false;
        // prepend 更早的消息到列表头部（时间线正序：旧在前）
        setMessages((prev) => [...olderMessages, ...prev]);
        setActiveConversation((prev) =>
          prev ? { ...prev, hasMoreMessages } : prev,
        );
      } catch (err) {
        console.error("[useIM] Failed to load more messages:", err);
      } finally {
        setLoadingMore(false);
      }
    },
    [workspaceId],
  );

  /** 发送消息 */
  const sendMessage = useCallback(
    async (cid: string, body: string, opts?: SendMessageOptions) => {
      const payload: Record<string, unknown> = { body };
      if (opts?.replyToId) payload.replyToId = opts.replyToId;
      if (opts?.mentions) payload.mentions = opts.mentions;
      if (opts?.type) payload.type = opts.type;
      // 附件：仅传服务端需要的字段（剔除本地预览用的 thumbnailUrl 中的 blob: URL 由后端处理）
      // 字段名对齐后端 zod schema：filename / mimeType / size
      if (opts?.attachments && opts.attachments.length > 0) {
        payload.attachments = opts.attachments.map((a) => ({
          filename: a.fileName,
          url: a.url,
          mimeType: a.fileType,
          size: a.fileSize,
          thumbnailUrl: a.thumbnailUrl,
        }));
      }

      try {
        const msg = await api<Message>(
          `/api/v1/workspaces/${workspaceId}/conversations/${cid}/messages`,
          { method: "POST", body: JSON.stringify(payload) },
        );
        // 乐观更新：立即追加到消息列表
        setMessages((prev) => [...prev, msg]);
      } catch (err) {
        setError(err instanceof Error ? err.message : (t?.("sendMessageFailed") ?? "Failed to send message"));
        throw err;
      }
    },
    [workspaceId, t],
  );

  /** 编辑消息 */
  const editMessage = useCallback(
    async (cid: string, mid: string, body: string) => {
      try {
        const msg = await api<Message>(
          `/api/v1/workspaces/${workspaceId}/conversations/${cid}/messages/${mid}`,
          { method: "PATCH", body: JSON.stringify({ body }) },
        );
        setMessages((prev) => prev.map((m) => (m.id === mid ? msg : m)));
      } catch (err) {
        setError(err instanceof Error ? err.message : (t?.("editMessageFailed") ?? "Failed to edit message"));
        throw err;
      }
    },
    [workspaceId, t],
  );

  /** 撤回消息 */
  const revokeMessage = useCallback(
    async (cid: string, mid: string) => {
      try {
        await api(
          `/api/v1/workspaces/${workspaceId}/conversations/${cid}/messages/${mid}`,
          { method: "DELETE" },
        );
        // 本地标记撤回（WS 也会推送，此处乐观更新）
        setMessages((prev) =>
          prev.map((m) =>
            m.id === mid ? { ...m, revokedAt: new Date().toISOString() } : m,
          ),
        );
      } catch (err) {
        setError(err instanceof Error ? err.message : (t?.("revokeMessageFailed") ?? "Failed to revoke message"));
        throw err;
      }
    },
    [workspaceId, t],
  );

  /** 创建会话 */
  const createConversation = useCallback(
    async (params: CreateConversationParams): Promise<Conversation> => {
      try {
        const conv = await api<Conversation>(
          `/api/v1/workspaces/${workspaceId}/conversations`,
          { method: "POST", body: JSON.stringify(params) },
        );
        // 追加到会话列表
        setConversations((prev) => [...prev, conv]);
        return conv;
      } catch (err) {
        setError(err instanceof Error ? err.message : (t?.("createConversationFailed") ?? "Failed to create conversation"));
        throw err;
      }
    },
    [workspaceId, t],
  );

  /** WebSocket 消息处理：统一分发服务端推送 */
  useEffect(() => {
    const unsubscribe = ws.onMessage((msg: ServerMessage) => {
      try {
        switch (msg.type) {
          case "message": {
            // 新消息 → 追加到当前会话消息列表
            if (msg.conversationId === activeCidRef.current) {
              const newMessage = payloadToMessage(msg.message);
              // 如果收到 call_ended 或 call_rejected 消息，
              // 更新同会话中最近的 call_invite 消息的 callStatus
              if (
                newMessage.type === "call_ended" ||
                newMessage.type === "call_rejected"
              ) {
                const callStatus =
                  newMessage.type === "call_ended" ? "ended" : "rejected";
                setMessages((prev) => {
                  // 从末尾向前查找最近的 call_invite 消息
                  const updated = [...prev];
                  for (let i = updated.length - 1; i >= 0; i--) {
                    if (updated[i].type === "call_invite") {
                      updated[i] = { ...updated[i], callStatus };
                      break;
                    }
                  }
                  return [...updated, newMessage];
                });
              } else {
                // 新 call_invite 消息默认 callStatus 为 "ongoing"
                if (newMessage.type === "call_invite") {
                  newMessage.callStatus = "ongoing";
                }
                setMessages((prev) => [...prev, newMessage]);
              }
            } else {
              // 非当前活跃会话 → 触发浏览器通知（需权限已授予）
              // 仅在浏览器环境且权限已授予时弹出，避免在 SSR 或权限未授予时报错
              if (
                typeof window !== "undefined" &&
                typeof Notification !== "undefined" &&
                Notification.permission === "granted"
              ) {
                try {
                  const notification = new Notification(
                    msg.message.authorName || "新消息",
                    {
                      body: msg.message.body,
                      icon: msg.message.authorImage || undefined,
                    },
                  );
                  // MVP：通知点击时聚焦窗口（暂不实现跳转到对应会话）
                  notification.onclick = () => {
                    window.focus();
                    notification.close();
                  };
                } catch {
                  // 通知构造失败静默忽略（部分浏览器在非用户手势上下文限制通知）
                }
              }
            }
            // 更新会话列表的 lastMessageAt 和未读数
            setConversations((prev) =>
              prev.map((c) =>
                c.id === msg.conversationId
                  ? {
                      ...c,
                      lastMessageAt: msg.message.createdAt,
                      unreadCount:
                        c.id === activeCidRef.current
                          ? 0
                          : (c.unreadCount ?? 0) + 1,
                    }
                  : c,
              ),
            );
            break;
          }
          case "edit": {
            // 编辑消息 → 更新消息列表
            if (msg.conversationId === activeCidRef.current) {
              setMessages((prev) =>
                prev.map((m) =>
                  m.id === msg.messageId
                    ? { ...m, body: msg.body, editedAt: msg.editedAt }
                    : m,
                ),
              );
            }
            break;
          }
          case "revoke": {
            // 撤回消息 → 更新消息列表
            if (msg.conversationId === activeCidRef.current) {
              setMessages((prev) =>
                prev.map((m) =>
                  m.id === msg.messageId ? { ...m, revokedAt: msg.revokedAt } : m,
                ),
              );
            }
            break;
          }
          case "presence": {
            // 在线状态变更：目前仅更新会话成员的在线标记（未来扩展）
            // 会话成员没有 online 字段，此处预留扩展点
            break;
          }
          case "typing": {
            // 正在输入：更新 typingUsers 状态，5 秒无更新自动清除
            const { conversationId: tCid, userId: tUid, isTyping } = msg;
            const timerKey = `${tCid}:${tUid}`;

            // 清除该用户已有的过期定时器（避免重复定时器堆积）
            const existingTimer = typingTimersRef.current[timerKey];
            if (existingTimer) {
              clearTimeout(existingTimer);
              delete typingTimersRef.current[timerKey];
            }

            if (isTyping) {
              // 添加到 typing 列表（去重）
              setTypingUsers((prev) => {
                const list = prev[tCid] ?? [];
                if (list.includes(tUid)) return prev;
                return { ...prev, [tCid]: [...list, tUid] };
              });
              // 设置 5 秒过期定时器，到期后从 typing 列表移除
              typingTimersRef.current[timerKey] = setTimeout(() => {
                setTypingUsers((prev) => {
                  const list = prev[tCid] ?? [];
                  const next = list.filter((id) => id !== tUid);
                  // 列表为空时移除 key，避免对象膨胀
                  const { [tCid]: _removed, ...rest } = prev;
                  return next.length > 0 ? { ...rest, [tCid]: next } : rest;
                });
                delete typingTimersRef.current[timerKey];
              }, 5000);
            } else {
              // isTyping=false → 立即从 typing 列表移除
              setTypingUsers((prev) => {
                const list = prev[tCid] ?? [];
                if (!list.includes(tUid)) return prev;
                const next = list.filter((id) => id !== tUid);
                const { [tCid]: _removed, ...rest } = prev;
                return next.length > 0 ? { ...rest, [tCid]: next } : rest;
              });
            }
            break;
          }
          case "read": {
            // 已读回执：更新对应消息的 readByCount
            if (msg.conversationId === activeCidRef.current) {
              setMessages((prev) =>
                prev.map((m) => {
                  if (msg.messageIds.includes(m.id)) {
                    // 使用服务端提供的 readByCount 值，避免本地递增导致多设备重复计数
                    return { ...m, readByCount: msg.readByCount ?? m.readByCount ?? 0 };
                  }
                  return m;
                }),
              );
            }
            break;
          }
          case "error": {
            console.error("[useIM] WebSocket error:", msg.message);
            break;
          }
        }
      } catch (err) {
        console.error("[useIM] Message handling error:", err);
      }
    });
    return unsubscribe;
  }, [ws]);

  // 同步消息列表引用（供 loadMoreMessages 读取游标）
  useEffect(() => {
    messagesRef.current = messages;
  }, [messages]);

  // 初始加载会话列表
  useEffect(() => {
    loadConversations();
  }, [loadConversations]);

  /**
   * 浏览器通知权限请求：IMClient 初始化时请求一次。
   * 仅在浏览器环境且权限未授予也未拒绝时请求，避免重复弹窗。
   */
  useEffect(() => {
    if (
      typeof window !== "undefined" &&
      typeof Notification !== "undefined" &&
      Notification.permission === "default"
    ) {
      // best-effort 请求权限，失败静默忽略（用户拒绝或不支持时不影响核心功能）
      Notification.requestPermission().catch(() => {});
    }
  }, []);

  // 组件卸载时清理所有 typing 过期定时器，避免内存泄漏和卸载后 setState
  useEffect(() => {
    return () => {
      for (const timer of Object.values(typingTimersRef.current)) {
        clearTimeout(timer);
      }
      typingTimersRef.current = {};
    };
  }, []);

  return {
    conversations,
    activeConversation,
    messages,
    loading,
    error,
    wsStatus: ws.status,
    loadConversations,
    selectConversation,
    selectTaskConversation,
    loadMoreMessages,
    loadingMore,
    sendMessage,
    editMessage,
    revokeMessage,
    createConversation,
    setActiveConversation,
    typingUsers,
  };
}

"use client";

/**
 * 会议列表组件 · components/meeting/MeetingList.tsx
 *
 * 功能：
 *  - 获取会议列表（GET /api/v1/workspaces/{wid}/meetings）
 *  - 按状态分组（进行中 active / 已预约 scheduled / 已结束 ended）
 *  - 每条：标题、时间、参与人数、状态标签、操作按钮（加入/结束）
 *  - 分页（page + limit）
 *
 * design token 样式，lucide-react 图标（Video, Calendar, Users, PhoneOff）。
 */

import { useEffect, useState, useCallback } from "react";
import { useTranslations } from "next-intl";
import { useRouter } from "@/lib/i18n-navigation";
import {
  Video,
  Calendar,
  Users,
  PhoneOff,
  Loader2,
  Plus,
  AlertCircle,
  Pencil,
  Play,
  User,
  MoreVertical,
} from "lucide-react";
import { api } from "@/lib/api";
import { MeetingCreate, type EditableMeeting } from "./MeetingCreate";

/** 会议状态 */
type MeetingStatus = "active" | "scheduled" | "ended";

/** 会议列表项（后端返回 _count.participants，非 participantCount） */
interface MeetingItem {
  id: string;
  title: string;
  status: MeetingStatus;
  startedAt: string | null;
  endedAt: string | null;
  scheduledAt: string | null;
  /** 后端 Prisma _count 投影 */
  _count: { participants: number };
  maxParticipants: number | null;
  /** 创建者 ID（用于编辑权限判断） */
  createdBy?: string | null;
  /** 录制 URL（已结束会议可查看回放） */
  recordingUrl?: string | null;
  /** 描述（L5 #31：列表展示 + 编辑时回填） */
  description?: string | null;
  /** 类型（编辑时回填） */
  type?: string;
  /** 录制开关（编辑时回填） */
  recordingEnabled?: boolean;
  /** 创建者信息（L5 #31：列表展示创建者名称） */
  creator?: { id: string; name: string | null; email: string } | null;
}

/** 列表 API 响应（分页） */
interface MeetingListResponse {
  items: MeetingItem[];
  total: number;
  page: number;
  limit: number;
  hasMore: boolean;
}

/** 每页条数 */
const PAGE_LIMIT = 20;

export interface MeetingListProps {
  workspaceId: string;
}

export function MeetingList({ workspaceId }: MeetingListProps) {
  const t = useTranslations("meeting");
  const tButton = useTranslations("button");
  const router = useRouter();

  const [items, setItems] = useState<MeetingItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [actioningId, setActioningId] = useState<string | null>(null);
  const [showCreate, setShowCreate] = useState(false);
  const [editingMeeting, setEditingMeeting] = useState<MeetingItem | null>(null);
  // 当前用户 ID + 角色（用于编辑按钮可见性判断）
  const [currentUserId, setCurrentUserId] = useState<string | null>(null);
  const [currentUserRole, setCurrentUserRole] = useState<string | null>(null);

  // 拉取当前用户 ID + 工作区角色（用于编辑权限判断）
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const [me, membersRes] = await Promise.all([
          api<{ id: string; name: string | null; email: string }>("/api/v1/users/me"),
          api<{
            items: Array<{ id: string; role: string; isSelf: boolean }>;
          }>(`/api/v1/workspaces/${workspaceId}/members?limit=100`),
        ]);
        if (cancelled) return;
        setCurrentUserId(me.id);
        const selfMember = membersRes.items.find((m) => m.isSelf);
        if (selfMember) setCurrentUserRole(selfMember.role);
      } catch {
        // 获取用户信息失败不阻塞列表渲染
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [workspaceId]);

  // 拉取会议列表 + L7 #33：30 秒轮询刷新（实时更新会议状态/参与者数）
  useEffect(() => {
    let cancelled = false;

    const fetchMeetings = async () => {
      try {
        const data = await api<MeetingListResponse>(
          `/api/v1/workspaces/${workspaceId}/meetings?page=${page}&limit=${PAGE_LIMIT}`,
        );
        if (!cancelled) {
          setItems(data.items);
          setTotal(data.total);
          setError("");
        }
      } catch (e) {
        if (!cancelled) {
          setError(e instanceof Error ? e.message : t("loadFailed"));
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    };

    // 首次加载显示 loading
    setLoading(true);
    void fetchMeetings();

    // L7 #33：30 秒轮询刷新（不显示 loading，静默更新）
    // 页面可见性优化：仅在页面可见时轮询，切到后台时暂停
    const pollInterval = setInterval(() => {
      if (!cancelled && document.visibilityState === "visible") {
        void fetchMeetings();
      }
    }, 30_000);

    // 页面从后台切回前台时立即刷新一次
    const onVisibilityChange = () => {
      if (!cancelled && document.visibilityState === "visible") {
        void fetchMeetings();
      }
    };
    document.addEventListener("visibilitychange", onVisibilityChange);

    return () => {
      cancelled = true;
      clearInterval(pollInterval);
      document.removeEventListener("visibilitychange", onVisibilityChange);
    };
  }, [workspaceId, page, t]);

  // 加入会议：跳转到会议详情页（会议房间）
  const handleJoin = useCallback(
    (mid: string) => {
      router.push(`/w/${workspaceId}/meetings/${mid}`);
    },
    [router, workspaceId],
  );

  // 结束会议
  const handleEnd = useCallback(
    async (mid: string) => {
      if (actioningId) return;
      setActioningId(mid);
      try {
        await api(`/api/v1/workspaces/${workspaceId}/meetings/${mid}`, {
          method: "DELETE",
        });
        // 从列表中更新状态为已结束
        setItems((prev) =>
          prev.map((m) =>
            m.id === mid ? { ...m, status: "ended" as MeetingStatus } : m,
          ),
        );
      } catch (e) {
        setError(e instanceof Error ? e.message : t("endFailed"));
      } finally {
        setActioningId(null);
      }
    },
    [actioningId, workspaceId, t],
  );

  // 编辑会议：打开 MeetingCreate 编辑模式
  const handleEdit = useCallback((meeting: MeetingItem) => {
    setEditingMeeting(meeting);
  }, []);

  // 编辑成功后更新列表
  const handleEditSaved = useCallback(
    (updated: { id: string; title: string }) => {
      setItems((prev) =>
        prev.map((m) =>
          m.id === updated.id ? { ...m, title: updated.title } : m,
        ),
      );
      setEditingMeeting(null);
    },
    [],
  );

  // 判断当前用户是否可编辑某会议（创建者或 admin/owner）
  const canEdit = useCallback(
    (meeting: MeetingItem): boolean => {
      if (!currentUserId) return false;
      if (meeting.createdBy === currentUserId) return true;
      if (currentUserRole === "admin" || currentUserRole === "owner") return true;
      return false;
    },
    [currentUserId, currentUserRole],
  );

  // 按状态分组
  const activeMeetings = items.filter((m) => m.status === "active");
  const scheduledMeetings = items.filter((m) => m.status === "scheduled");
  const endedMeetings = items.filter((m) => m.status === "ended");

  const totalPages = Math.max(1, Math.ceil(total / PAGE_LIMIT));

  return (
    <div className="max-w-[var(--container-max)] mx-auto px-[var(--space-4)] py-[var(--space-6)]">
      {/* 标题栏 */}
      <div className="flex items-center justify-between mb-[var(--space-5)]">
        <h1 className="text-[length:var(--text-2xl)] font-[weight:var(--weight-semibold)] text-[var(--fg)] tracking-[var(--tracking-tight)]">
          {t("title")}
        </h1>
        <button
          type="button"
          onClick={() => setShowCreate(true)}
          className="inline-flex items-center gap-1.5 h-9 px-3 rounded-[var(--radius-md)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] transition-colors duration-[var(--motion-fast)]"
        >
          <Plus size={14} />
          {t("create")}
        </button>
      </div>

      {error && (
        <div className="flex items-start gap-2 mb-[var(--space-4)] px-3 py-2 rounded-[var(--radius-md)] bg-[var(--danger-soft)] text-[var(--danger-fg)] text-[length:var(--text-sm)]">
          <AlertCircle size={14} className="shrink-0 mt-0.5" />
          <span className="flex-1">{error}</span>
          <button
            type="button"
            onClick={() => setError("")}
            className="shrink-0 opacity-60 hover:opacity-100 transition-opacity"
            aria-label={t("dismiss")}
          >
            ×
          </button>
        </div>
      )}

      {loading ? (
        <div className="py-[var(--space-12)] text-center text-[var(--muted)]">
          <Loader2 size={20} className="inline animate-spin mr-2" />
          {t("loading")}
        </div>
      ) : items.length === 0 ? (
        <div className="py-[var(--space-12)] text-center text-[var(--muted)]">
          <Video size={36} className="mx-auto mb-3 opacity-50" />
          <p className="text-[length:var(--text-sm)]">{t("noMeetings")}</p>
        </div>
      ) : (
        <div className="space-y-[var(--space-6)]">
          {/* 进行中 */}
          {activeMeetings.length > 0 && (
            <MeetingGroup
              label={t("activeMeetings")}
              items={activeMeetings}
              onJoin={handleJoin}
              onEnd={handleEnd}
              onEdit={handleEdit}
              actioningId={actioningId}
              canEdit={canEdit}
            />
          )}

          {/* 已预约 */}
          {scheduledMeetings.length > 0 && (
            <MeetingGroup
              label={t("scheduledMeetings")}
              items={scheduledMeetings}
              onJoin={handleJoin}
              onEnd={handleEnd}
              onEdit={handleEdit}
              actioningId={actioningId}
              canEdit={canEdit}
            />
          )}

          {/* 已结束 */}
          {endedMeetings.length > 0 && (
            <MeetingGroup
              label={t("endedMeetings")}
              items={endedMeetings}
              onJoin={handleJoin}
              onEnd={handleEnd}
              onEdit={handleEdit}
              actioningId={actioningId}
              canEdit={canEdit}
            />
          )}
        </div>
      )}

      {/* 分页 */}
      {totalPages > 1 && (
        <div className="flex items-center justify-center gap-2 mt-[var(--space-6)]">
          <button
            type="button"
            onClick={() => setPage((p) => Math.max(1, p - 1))}
            disabled={page <= 1}
            className="h-8 px-3 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-[var(--motion-fast)]"
          >
            {t("prevPage")}
          </button>
          <span className="text-[length:var(--text-sm)] text-[var(--muted)]">
            {page} / {totalPages}
          </span>
          <button
            type="button"
            onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
            disabled={page >= totalPages}
            className="h-8 px-3 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-[var(--motion-fast)]"
          >
            {t("nextPage")}
          </button>
        </div>
      )}

      {/* 创建会议弹窗 */}
      {showCreate && (
        <MeetingCreate
          workspaceId={workspaceId}
          onClose={() => setShowCreate(false)}
          onCreated={(meeting) => {
            setShowCreate(false);
            // 创建成功后加入会议
            handleJoin(meeting.id);
          }}
        />
      )}

      {/* 编辑会议弹窗 */}
      {editingMeeting && (
        <MeetingCreate
          workspaceId={workspaceId}
          onClose={() => setEditingMeeting(null)}
          onCreated={handleEditSaved}
          meeting={
            {
              id: editingMeeting.id,
              title: editingMeeting.title,
              description: editingMeeting.description,
              type: editingMeeting.type,
              scheduledAt: editingMeeting.scheduledAt,
              maxParticipants: editingMeeting.maxParticipants,
              recordingEnabled: editingMeeting.recordingEnabled,
            } satisfies EditableMeeting
          }
        />
      )}
    </div>
  );
}

/** 会议分组 */
function MeetingGroup({
  label,
  items,
  onJoin,
  onEnd,
  onEdit,
  actioningId,
  canEdit,
}: {
  label: string;
  items: MeetingItem[];
  onJoin: (mid: string) => void;
  onEnd: (mid: string) => void;
  onEdit: (meeting: MeetingItem) => void;
  actioningId: string | null;
  canEdit: (meeting: MeetingItem) => boolean;
}) {
  const t = useTranslations("meeting");
  return (
    <section>
      <h2 className="text-[length:var(--text-sm)] font-[weight:var(--weight-semibold)] text-[var(--meta)] uppercase tracking-wide mb-[var(--space-2)]">
        {label} · {items.length}
      </h2>
      <ul className="divide-y divide-[var(--border-soft)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)]">
        {items.map((m) => (
          <MeetingRow
            key={m.id}
            meeting={m}
            onJoin={onJoin}
            onEnd={onEnd}
            onEdit={onEdit}
            actioning={actioningId === m.id}
            canEdit={canEdit(m)}
          />
        ))}
      </ul>
    </section>
  );
}

/** 单条会议行 */
function MeetingRow({
  meeting,
  onJoin,
  onEnd,
  onEdit,
  actioning,
  canEdit,
}: {
  meeting: MeetingItem;
  onJoin: (mid: string) => void;
  onEnd: (mid: string) => void;
  onEdit: (meeting: MeetingItem) => void;
  actioning: boolean;
  canEdit: boolean;
}) {
  const t = useTranslations("meeting");
  const tButton = useTranslations("button");
  const [menuOpen, setMenuOpen] = useState(false);

  const time = meeting.startedAt || meeting.scheduledAt || meeting.endedAt;
  const timeLabel = time ? new Date(time).toLocaleString() : "—";
  // 录制回放可用：已结束且有非 pending 的 recordingUrl
  const hasRecording =
    meeting.status === "ended" &&
    meeting.recordingUrl &&
    !meeting.recordingUrl.startsWith("egress:");

  // 是否有次要操作（查看录制/编辑）
  const hasSecondaryActions = hasRecording || (meeting.status === "scheduled" && canEdit);

  return (
    <li className="flex items-center gap-3 px-[var(--space-4)] py-3 hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]">
      <Video size={15} className="shrink-0 text-[var(--muted)]" />
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2">
          <span className="text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg)] truncate">
            {meeting.title}
          </span>
          <StatusBadge status={meeting.status} />
        </div>
        <div className="mt-1 flex items-center gap-3 text-[length:var(--text-xs)] text-[var(--muted)]">
          <span className="inline-flex items-center gap-1">
            <Calendar size={12} />
            {timeLabel}
          </span>
          <span className="inline-flex items-center gap-1">
            <Users size={12} />
            {meeting._count.participants}
            {meeting.maxParticipants ? ` / ${meeting.maxParticipants}` : ""}
          </span>
          {/* L5 #31：显示创建者名称 */}
          {meeting.creator && (meeting.creator.name || meeting.creator.email) && (
            <span className="inline-flex items-center gap-1">
              <User size={12} />
              {meeting.creator.name ?? meeting.creator.email}
            </span>
          )}
        </div>
        {/* L5 #31：显示会议描述（截断显示） */}
        {meeting.description && (
          <p className="mt-1 text-[length:var(--text-xs)] text-[var(--meta)] truncate">
            {meeting.description}
          </p>
        )}
      </div>
      <div className="flex items-center gap-2 shrink-0">
        {/* 手机端次要操作下拉菜单 */}
        {hasSecondaryActions && (
          <div className="relative md:hidden">
            <button
              type="button"
              onClick={() => setMenuOpen((v) => !v)}
              className="inline-flex items-center justify-center h-8 w-8 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
              aria-label="More actions"
            >
              <MoreVertical size={14} />
            </button>
            {menuOpen && (
              <>
                <div
                  className="fixed inset-0 z-[var(--z-dropdown)]"
                  onClick={() => setMenuOpen(false)}
                />
                <div className="absolute right-0 top-full mt-1 min-w-[140px] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] shadow-[var(--elev-md)] py-1 z-[calc(var(--z-dropdown)+1)]">
                  {hasRecording && (
                    <a
                      href={meeting.recordingUrl as string}
                      target="_blank"
                      rel="noopener noreferrer"
                      onClick={() => setMenuOpen(false)}
                      className="flex items-center gap-2 px-3 py-2 text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
                    >
                      <Play size={14} />
                      {tButton("viewAll")}
                    </a>
                  )}
                  {meeting.status === "scheduled" && canEdit && (
                    <button
                      type="button"
                      onClick={() => {
                        onEdit(meeting);
                        setMenuOpen(false);
                      }}
                      className="flex items-center gap-2 w-full px-3 py-2 text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
                    >
                      <Pencil size={14} />
                      {tButton("edit")}
                    </button>
                  )}
                </div>
              </>
            )}
          </div>
        )}

        {/* 主要操作：加入 — 始终显示（手机端仅图标） */}
        {(meeting.status === "active" || meeting.status === "scheduled") && (
          <button
            type="button"
            onClick={() => onJoin(meeting.id)}
            className="inline-flex items-center gap-1.5 h-8 px-3 rounded-[var(--radius-sm)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] transition-colors duration-[var(--motion-fast)]"
          >
            <Video size={14} />
            <span className="hidden sm:inline">{t("join")}</span>
          </button>
        )}
        {/* 主要操作：结束 — 始终显示（手机端仅图标） */}
        {meeting.status === "active" && (
          <button
            type="button"
            onClick={() => onEnd(meeting.id)}
            disabled={actioning}
            className="inline-flex items-center gap-1.5 h-8 px-3 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--danger)] hover:bg-[var(--danger-soft)] disabled:opacity-50 transition-colors duration-[var(--motion-fast)]"
          >
            {actioning ? (
              <Loader2 size={14} className="animate-spin" />
            ) : (
              <PhoneOff size={14} />
            )}
            <span className="hidden sm:inline">{t("end")}</span>
          </button>
        )}

        {/* md 以上：次要操作按钮直接显示 */}
        {hasRecording && (
          <a
            href={meeting.recordingUrl as string}
            target="_blank"
            rel="noopener noreferrer"
            className="hidden md:inline-flex items-center gap-1.5 h-8 px-3 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
          >
            <Play size={14} />
            {tButton("viewAll")}
          </a>
        )}
        {meeting.status === "scheduled" && canEdit && (
          <button
            type="button"
            onClick={() => onEdit(meeting)}
            className="hidden md:inline-flex items-center gap-1.5 h-8 px-3 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
          >
            <Pencil size={14} />
            {tButton("edit")}
          </button>
        )}
      </div>
    </li>
  );
}

/** 状态标签 */
function StatusBadge({ status }: { status: MeetingStatus }) {
  const t = useTranslations("meeting");
  const styles: Record<MeetingStatus, string> = {
    active:
      "bg-[var(--success-soft)] text-[var(--success)] border-[var(--success)]",
    scheduled:
      "bg-[var(--surface-2)] text-[var(--meta)] border-[var(--border)]",
    ended: "bg-[var(--surface-2)] text-[var(--muted)] border-[var(--border)]",
  };
  const labels: Record<MeetingStatus, string> = {
    active: t("activeMeetings"),
    scheduled: t("scheduledMeetings"),
    ended: t("endedMeetings"),
  };
  return (
    <span
      className={`inline-flex items-center px-1.5 py-0.5 rounded-[var(--radius-sm)] border text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] ${styles[status]}`}
    >
      {labels[status]}
    </span>
  );
}

"use client";

/**
 * 会议房间核心组件 · components/meetings/MeetingRoom.tsx
 *
 * 接入 LiveKit SDK 实现音视频会议 + 屏幕共享：
 *  1. 调用 POST /api/v1/workspaces/{wid}/meetings/{mid}/join 获取 { token, url, roomName }
 *  2. 用 <LiveKitRoom token serverUrl connect> 包裹内容
 *  3. 内部用 <VideoConference />（LiveKit 预置 UI：参与者网格 + 麦克风/摄像头/屏幕共享控制栏）
 *  4. 加上 <RoomAudioRenderer />（音频渲染）
 *  5. 连接状态：joining / connected / reconnecting / disconnected / error
 *  6. 离开时调用 POST /api/v1/workspaces/{wid}/meetings/{mid}/leave
 *     - beforeunload / pagehide 时用 navigator.sendBeacon 发送（High #5）
 *     - 组件卸载时也调用 leave API
 *  7. 错误处理：LiveKit 未配置（503）→ 显示"会议服务不可用"
 *  8. 区分主动挂断与意外断开（High #6）：
 *     - 主动挂断 → leave + onLeave
 *     - 意外断开 → "重连中..." + 重新 join 获取新 token（Medium #17），30s 超时才回 lobby
 *  9. 录制控制（Medium #16）：host 可见，调用 recording/start/stop API
 *
 * 全屏布局（fixed inset-0）。
 */

import { useState, useEffect, useCallback, useRef } from "react";
import {
  LiveKitRoom,
  VideoConference,
  RoomAudioRenderer,
  useParticipants,
  useLocalParticipant,
  useDataChannel,
} from "@livekit/components-react";
import {
  Loader2,
  AlertCircle,
  WifiOff,
  Video,
  Circle,
  Square,
  Hand,
  Mic,
  MicOff,
  VideoIcon,
  VideoOff,
  Crown,
  Users,
  Clock,
} from "lucide-react";
import { useTranslations } from "next-intl";
import { useRouter } from "next/navigation";
import { api, ApiError } from "@/lib/api";

/** join API 返回的连接凭据 */
interface JoinResult {
  token: string;
  url: string;
  roomName: string;
}

/** 会议详情中参与者条目（用于判断 host 权限） */
interface ParticipantEntry {
  userId: string;
  role: string;
}

/** 会议详情（仅取所需字段） */
interface MeetingDetailForHost {
  createdBy?: string | null;
  participants: ParticipantEntry[];
}

export interface MeetingRoomProps {
  workspaceId: string;
  meetingId: string;
  onLeave?: () => void;
  /** 关联的 IM 会话 ID；存在时离开会议会自动发送 call_ended 系统消息 */
  conversationId?: string;
}

/** 连接状态机 */
type ConnectionState =
  | "joining"
  | "connected"
  | "reconnecting"
  | "disconnected"
  | "error";

/** 录制状态 */
type RecordingState = "idle" | "starting" | "active" | "stopping";

/** 重连超时（ms） */
const RECONNECT_TIMEOUT_MS = 30_000;

export function MeetingRoom({ workspaceId, meetingId, onLeave, conversationId }: MeetingRoomProps) {
  const t = useTranslations("meetings.room");
  const tMeetings = useTranslations("meetings");
  const tButton = useTranslations("button");
  const router = useRouter();

  const [state, setState] = useState<ConnectionState>("joining");
  const [errorMsg, setErrorMsg] = useState("");
  /** 503 时后端返回的不可用标记 */
  const [serviceUnavailable, setServiceUnavailable] = useState(false);
  const [token, setToken] = useState<string | undefined>(undefined);
  const [serverUrl, setServerUrl] = useState<string | undefined>(undefined);

  // 录制相关状态
  const [isHost, setIsHost] = useState(false);
  const [recording, setRecording] = useState<RecordingState>("idle");

  // 通话计时器：从连接成功开始计时，断开时停止
  const [callDuration, setCallDuration] = useState(0);
  const callTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // 记忆凭据，避免 effect 重复 join
  const joinedRef = useRef(false);
  // 记忆是否已调用 leave，避免重复
  const leftRef = useRef(false);
  // 记忆是否组件已卸载
  const mountedRef = useRef(false);
  // 标记用户是否主动挂断（区分意外断开）
  const intentionalLeaveRef = useRef(false);
  // 重连超时定时器
  const reconnectTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
      // 组件卸载时调用 leave API（High #5）
      void callLeaveApiRef.current();
      // 清理重连超时
      if (reconnectTimeoutRef.current) {
        clearTimeout(reconnectTimeoutRef.current);
        reconnectTimeoutRef.current = null;
      }
      // 清理通话计时器
      if (callTimerRef.current) {
        clearInterval(callTimerRef.current);
        callTimerRef.current = null;
      }
    };
  }, []);

  // 调用 leave API（幂等，失败不阻塞）
  const callLeaveApi = useCallback(async () => {
    if (leftRef.current) return;
    leftRef.current = true;
    try {
      await api(
        `/api/v1/workspaces/${workspaceId}/meetings/${meetingId}/leave`,
        { method: "POST" },
      );
    } catch {
      // 离开失败不阻塞 UI
    }
  }, [workspaceId, meetingId]);

  // 用 ref 存储 callLeaveApi，供卸载 effect 调用（避免依赖数组问题）
  const callLeaveApiRef = useRef(callLeaveApi);
  callLeaveApiRef.current = callLeaveApi;

  // 通话时长格式化（mm:ss 或 hh:mm:ss）
  const formatCallDuration = useCallback((seconds: number): string => {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    const pad = (n: number) => n.toString().padStart(2, "0");
    if (h > 0) return `${pad(h)}:${pad(m)}:${pad(s)}`;
    return `${pad(m)}:${pad(s)}`;
  }, []);

  // 通话结束后自动返回 IM 页面
  const navigateBackToIM = useCallback(() => {
    if (conversationId) {
      router.push(`/w/${workspaceId}/im/${conversationId}`);
    } else {
      router.push(`/w/${workspaceId}/im`);
    }
  }, [router, workspaceId, conversationId]);

  // 启动通话计时器
  const startCallTimer = useCallback(() => {
    if (callTimerRef.current) return; // 已在计时中
    setCallDuration(0);
    callTimerRef.current = setInterval(() => {
      if (mountedRef.current) {
        setCallDuration((prev) => prev + 1);
      }
    }, 1000);
  }, []);

  // 停止通话计时器
  const stopCallTimer = useCallback(() => {
    if (callTimerRef.current) {
      clearInterval(callTimerRef.current);
      callTimerRef.current = null;
    }
  }, []);

  // 发送 call_ended 系统消息到关联会话（best-effort，失败不阻塞）
  const sendCallEndedMessage = useCallback(async () => {
    if (!conversationId) return;
    try {
      await api(
        `/api/v1/workspaces/${workspaceId}/conversations/${conversationId}/messages`,
        {
          method: "POST",
          body: JSON.stringify({ type: "call_ended", body: "" }),
        },
      );
    } catch {
      // 发送 call_ended 失败不阻塞离开流程
    }
  }, [conversationId, workspaceId]);

  // ── High #5: beforeunload / pagehide 事件 ──
  // 页面卸载时用 navigator.sendBeacon 发送 leave 请求 + call_ended 消息（无需 await）
  useEffect(() => {
    const leaveUrl = `/api/v1/workspaces/${workspaceId}/meetings/${meetingId}/leave`;

    const sendLeaveBeacon = () => {
      if (leftRef.current) return;
      leftRef.current = true;
      try {
        navigator.sendBeacon(leaveUrl);
      } catch {
        // sendBeacon 不可用时不阻塞
      }
      // 同时发送 call_ended 系统消息（sendBeacon 只能发 POST，用 Blob 发送 JSON）
      if (conversationId) {
        try {
          const messagesUrl = `/api/v1/workspaces/${workspaceId}/conversations/${conversationId}/messages`;
          const blob = new Blob(
            [JSON.stringify({ type: "call_ended", body: "" })],
            { type: "application/json" },
          );
          navigator.sendBeacon(messagesUrl, blob);
        } catch {
          // sendBeacon 不可用时不阻塞
        }
      }
    };

    const onBeforeUnload = () => sendLeaveBeacon();
    const onPageHide = () => sendLeaveBeacon();

    window.addEventListener("beforeunload", onBeforeUnload);
    window.addEventListener("pagehide", onPageHide);
    return () => {
      window.removeEventListener("beforeunload", onBeforeUnload);
      window.removeEventListener("pagehide", onPageHide);
    };
  }, [workspaceId, meetingId, conversationId]);

  // 重新 join 获取新 token（用于 Medium #17 token 过期/刷新）
  const rejoin = useCallback(async (): Promise<boolean> => {
    try {
      const result = await api<JoinResult>(
        `/api/v1/workspaces/${workspaceId}/meetings/${meetingId}/join`,
        { method: "POST" },
      );
      if (!mountedRef.current) return false;
      // 更新 token，LiveKitRoom 会自动重连
      setToken(result.token);
      setServerUrl(result.url);
      return true;
    } catch {
      return false;
    }
  }, [workspaceId, meetingId]);

  // 挂载时调用 join API 获取 LiveKit token + 判断 host 权限
  useEffect(() => {
    let cancelled = false;
    if (joinedRef.current) return;
    joinedRef.current = true;

    (async () => {
      setState("joining");
      setErrorMsg("");
      setServiceUnavailable(false);
      try {
        const result = await api<JoinResult>(
          `/api/v1/workspaces/${workspaceId}/meetings/${meetingId}/join`,
          { method: "POST" },
        );
        if (cancelled) return;
        setToken(result.token);
        setServerUrl(result.url);
        // token/url 就绪后 LiveKitRoom 会自动连接（connect=true）

        // 并行获取用户 ID + 会议详情，判断 host 权限（用于录制按钮可见性）
        try {
          const [me, detail] = await Promise.all([
            api<{ id: string }>("/api/v1/users/me"),
            api<MeetingDetailForHost>(
              `/api/v1/workspaces/${workspaceId}/meetings/${meetingId}`,
            ),
          ]);
          if (cancelled) return;
          // host = 会议创建者 或 参与者中 role=host
          const isCreator = detail.createdBy === me.id;
          const participantRole = detail.participants.find(
            (p) => p.userId === me.id,
          )?.role;
          setIsHost(isCreator || participantRole === "host");
        } catch {
          // 获取 host 权限失败不阻塞会议，只是不显示录制按钮
        }
      } catch (e) {
        if (cancelled) return;
        const is503 =
          e instanceof ApiError && (e.status === 503 || e.code === 503);
        if (mountedRef.current) {
          setServiceUnavailable(is503);
          setErrorMsg(e instanceof Error ? e.message : t("connectionFailed"));
          setState("error");
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [workspaceId, meetingId, t]);

  // LiveKit 连接成功
  const handleConnected = useCallback(() => {
    if (!mountedRef.current) return;
    // 如果之前在重连中，清除超时定时器
    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current);
      reconnectTimeoutRef.current = null;
    }
    setState("connected");
    // 启动通话计时器
    startCallTimer();
  }, [startCallTimer]);

  // LiveKit 断开连接（用户主动离开或意外断开）
  const handleDisconnected = useCallback(() => {
    if (!mountedRef.current) return;
    // 停止通话计时器
    stopCallTimer();

    // High #6: 区分主动挂断与意外断开
    if (intentionalLeaveRef.current) {
      // 主动挂断 → leave + sendCallEnded + onLeave + 自动返回 IM
      setState("disconnected");
      void callLeaveApi();
      void sendCallEndedMessage();
      onLeave?.();
      // 自动返回 IM 页面
      navigateBackToIM();
      return;
    }

    // 意外断开 → 显示"重连中..."，尝试重新 join 获取新 token（Medium #17）
    setState("reconnecting");

    // 尝试重新 join 获取新 token
    void rejoin().then((success) => {
      if (!mountedRef.current) return;
      if (!success) {
        // 重新 join 失败 → 清除超时，直接回 lobby
        if (reconnectTimeoutRef.current) {
          clearTimeout(reconnectTimeoutRef.current);
          reconnectTimeoutRef.current = null;
        }
        setState("disconnected");
        void callLeaveApi();
        void sendCallEndedMessage();
        onLeave?.();
        // 自动返回 IM 页面
        navigateBackToIM();
      }
      // join 成功 → token 已更新，LiveKitRoom 自动重连
      // 等待 onConnected 回调清除超时
    });

    // 设置 30s 重连超时
    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current);
    }
    reconnectTimeoutRef.current = setTimeout(() => {
      if (!mountedRef.current) return;
      // 重连超时 → 回 lobby
      setState("disconnected");
      void callLeaveApi();
      void sendCallEndedMessage();
      onLeave?.();
      // 自动返回 IM 页面
      navigateBackToIM();
    }, RECONNECT_TIMEOUT_MS);
  }, [callLeaveApi, onLeave, rejoin, sendCallEndedMessage, stopCallTimer, navigateBackToIM]);

  // LiveKit 连接错误
  const handleError = useCallback(
    (error: Error) => {
      if (!mountedRef.current) return;
      // 清理重连超时
      if (reconnectTimeoutRef.current) {
        clearTimeout(reconnectTimeoutRef.current);
        reconnectTimeoutRef.current = null;
      }
      setErrorMsg(error.message || t("connectionFailed"));
      setState("error");
    },
    [t],
  );

  // 用户点击"返回"按钮（错误/断开状态下）— 主动离开
  const handleBack = useCallback(() => {
    intentionalLeaveRef.current = true;
    stopCallTimer();
    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current);
      reconnectTimeoutRef.current = null;
    }
    void callLeaveApi();
    void sendCallEndedMessage();
    onLeave?.();
    // 自动返回 IM 页面
    navigateBackToIM();
  }, [callLeaveApi, onLeave, sendCallEndedMessage, stopCallTimer, navigateBackToIM]);

  // ── Medium #16: 录制控制 ──
  const handleToggleRecording = useCallback(async () => {
    if (recording === "starting" || recording === "stopping") return;

    if (recording === "idle") {
      // 开始录制
      setRecording("starting");
      try {
        await api(
          `/api/v1/workspaces/${workspaceId}/meetings/${meetingId}/recording/start`,
          { method: "POST" },
        );
        if (mountedRef.current) setRecording("active");
      } catch {
        if (mountedRef.current) setRecording("idle");
      }
    } else {
      // 停止录制
      setRecording("stopping");
      try {
        await api(
          `/api/v1/workspaces/${workspaceId}/meetings/${meetingId}/recording/stop`,
          { method: "POST" },
        );
        if (mountedRef.current) setRecording("idle");
      } catch {
        if (mountedRef.current) setRecording("active");
      }
    }
  }, [recording, workspaceId, meetingId]);

  // ── 连接中 ──
  if (state === "joining") {
    return (
      <div
        className="fixed inset-0 z-[var(--z-modal)] flex flex-col items-center justify-center bg-[var(--bg)]"
        role="status"
        aria-live="polite"
      >
        <Loader2 size={28} className="animate-spin text-[var(--accent)] mb-3" />
        <p className="text-[length:var(--text-sm)] text-[var(--muted)]">
          {t("joining")}
        </p>
      </div>
    );
  }

  // ── 重连中（意外断开） ──
  if (state === "reconnecting") {
    return (
      <div
        className="fixed inset-0 z-[var(--z-modal)] flex flex-col items-center justify-center bg-[var(--bg)]"
        role="status"
        aria-live="polite"
      >
        <Loader2 size={28} className="animate-spin text-[var(--accent)] mb-3" />
        <p className="text-[length:var(--text-sm)] text-[var(--fg)] mb-2">
          {t("reconnecting")}
        </p>
        <p className="text-[length:var(--text-xs)] text-[var(--muted)]">
          {t("connectionFailed")}
        </p>
      </div>
    );
  }

  // ── 错误 ──
  if (state === "error") {
    return (
      <div
        className="fixed inset-0 z-[var(--z-modal)] flex flex-col items-center justify-center bg-[var(--bg)]"
        role="alert"
        aria-live="assertive"
      >
        {serviceUnavailable ? (
          <>
            <Video size={28} className="text-[var(--muted)] mb-3" />
            <p className="text-[length:var(--text-sm)] text-[var(--fg)] mb-2">
              {t("serviceUnavailable")}
            </p>
            <p className="text-[length:var(--text-xs)] text-[var(--muted)] mb-4 max-w-xs text-center">
              {t("serviceUnavailableHint")}
            </p>
          </>
        ) : (
          <>
            <AlertCircle size={28} className="text-[var(--danger)] mb-3" />
            <p className="text-[length:var(--text-sm)] text-[var(--danger)] mb-2">
              {t("connectionFailed")}
            </p>
            {errorMsg && (
              <p className="text-[length:var(--text-xs)] text-[var(--muted)] mb-4 max-w-xs text-center">
                {errorMsg}
              </p>
            )}
          </>
        )}
        <button
          type="button"
          onClick={handleBack}
          className="h-9 px-4 rounded-[var(--radius-md)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)]"
        >
          {t("leave")}
        </button>
      </div>
    );
  }

  // ── 已断开 ──
  if (state === "disconnected") {
    return (
      <div
        className="fixed inset-0 z-[var(--z-modal)] flex flex-col items-center justify-center bg-[var(--bg)]"
        role="status"
        aria-live="polite"
      >
        <WifiOff size={28} className="text-[var(--muted)] mb-3" />
        <p className="text-[length:var(--text-sm)] text-[var(--fg)] mb-4">
          {t("disconnected")}
        </p>
        <button
          type="button"
          onClick={handleBack}
          className="h-9 px-4 rounded-[var(--radius-md)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)]"
        >
          {t("leave")}
        </button>
      </div>
    );
  }

  // ── 已连接：渲染 LiveKit 房间 ──
  return (
    <div className="fixed inset-0 z-[var(--z-modal)] flex flex-col bg-[var(--bg)]">
      <LiveKitRoom
        token={token}
        serverUrl={serverUrl}
        connect={true}
        audio={true}
        video={true}
        onConnected={handleConnected}
        onDisconnected={handleDisconnected}
        onError={handleError}
        className="flex-1 flex flex-col"
      >
        {/*
         * 通话时长显示：居中顶部，连接成功后开始计时
         */}
        {state === "connected" && (
          <div className="absolute top-[var(--space-3)] left-1/2 -translate-x-1/2 z-[var(--z-sticky)] inline-flex items-center gap-1.5 h-8 px-3 rounded-[var(--radius-md)] bg-[var(--surface-2)] text-[var(--fg-2)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)]">
            <Clock size={14} className="text-[var(--accent)]" />
            {formatCallDuration(callDuration)}
          </div>
        )}
        {/*
         * Medium #16: 录制控制条（仅 host 可见）
         * 叠加在 VideoConference 上方，不影响 LiveKit 预置控制栏
         */}
        {isHost && (
          <div className="absolute top-[var(--space-3)] right-[var(--space-3)] z-[var(--z-sticky)] flex items-center gap-2">
            {recording === "active" && (
              <span className="inline-flex items-center gap-1.5 h-8 px-3 rounded-[var(--radius-md)] bg-[var(--danger-soft)] text-[var(--danger)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)]">
                <Circle size={8} className="fill-current animate-pulse" />
                {tMeetings("recording")}
              </span>
            )}
            {(recording === "starting" || recording === "stopping") && (
              <span className="inline-flex items-center gap-1.5 h-8 px-3 rounded-[var(--radius-md)] bg-[var(--surface-2)] text-[var(--meta)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)]">
                <Loader2 size={10} className="animate-spin" />
                {recording === "starting"
                  ? tMeetings("recordingStarting")
                  : tMeetings("recordingStopping")}
              </span>
            )}
            <button
              type="button"
              onClick={handleToggleRecording}
              disabled={recording === "starting" || recording === "stopping"}
              className="inline-flex items-center gap-1.5 h-8 px-3 rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] disabled:opacity-50 transition-colors duration-[var(--motion-fast)]"
            >
              {recording === "starting" || recording === "stopping" ? (
                <Loader2 size={14} className="animate-spin" />
              ) : recording === "active" ? (
                <Square size={14} className="fill-current" />
              ) : (
                <Circle size={14} className="fill-current text-[var(--danger)]" />
              )}
              {recording === "active" || recording === "stopping"
                ? tMeetings("stopRecording")
                : tMeetings("startRecording")}
            </button>
          </div>
        )}
        {/*
         * VideoConference 是 LiveKit 预置的完整视频会议 UI：
         *  - 参与者视频网格（含聚焦/分页）
         *  - 控制栏（麦克风/摄像头/屏幕共享/挂断）
         *  - 非持久聊天
         */}
        <VideoConference className="flex-1" />
        {/* RoomAudioRenderer 不可见，负责渲染远端参与者音频 */}
        <RoomAudioRenderer />
        {/* L9 #35 + L10 #36：举手/设备信息 + 主持人转移控制面板 */}
        <MeetingRoomControls isHost={isHost} />
      </LiveKitRoom>
    </div>
  );
}

/**
 * L9 #35 + L10 #36：会议内部控制面板
 *
 * 在 LiveKitRoom context 内使用 hooks：
 * - useParticipants：获取所有参与者（含设备状态）
 * - useLocalParticipant：获取本地参与者设备状态
 * - useDataChannel("hand-raise")：举手消息收发
 * - useDataChannel("host-transfer")：主持人转移消息收发
 *
 * 面板叠加在左下角，不影响 VideoConference 的控制栏。
 */
function MeetingRoomControls({ isHost }: { isHost: boolean }) {
  const t = useTranslations("meetings.room");

  // 获取所有参与者 + 本地参与者设备状态
  const participants = useParticipants();
  const { localParticipant, isMicrophoneEnabled, isCameraEnabled } =
    useLocalParticipant();

  // 举手状态（本地）
  const [handRaised, setHandRaised] = useState(false);
  // 收到的举手消息（participantId → raised）
  const [raisedHands, setRaisedHands] = useState<Record<string, boolean>>({});

  // 举手 data channel
  const { send: sendHandRaise } = useDataChannel("hand-raise", (msg) => {
    try {
      const data = JSON.parse(new TextDecoder().decode(msg.payload)) as {
        participantId: string;
        raised: boolean;
      };
      setRaisedHands((prev) => ({
        ...prev,
        [data.participantId]: data.raised,
      }));
    } catch {
      // 忽略非 JSON 消息
    }
  });

  // 主持人转移 data channel
  const { send: sendHostTransfer } = useDataChannel("host-transfer", (msg) => {
    try {
      const data = JSON.parse(new TextDecoder().decode(msg.payload)) as {
        newHostId: string;
      };
      // 收到转移消息：如果目标是自己，更新 metadata 标记为 host
      if (data.newHostId === localParticipant.identity) {
        void localParticipant.setMetadata(
          JSON.stringify({ ...JSON.parse(localParticipant.metadata ?? "{}"), role: "host" }),
        );
      }
    } catch {
      // 忽略非 JSON 消息
    }
  });

  // 切换举手
  const toggleHandRaise = useCallback(() => {
    const newRaised = !handRaised;
    setHandRaised(newRaised);
    const payload = new TextEncoder().encode(
      JSON.stringify({ participantId: localParticipant.identity, raised: newRaised }),
    );
    void sendHandRaise(payload, { reliable: true });
  }, [handRaised, localParticipant, sendHandRaise]);

  // L10 #36：主持人转移
  const [transferTarget, setTransferTarget] = useState("");
  const handleTransferHost = useCallback(() => {
    if (!transferTarget) return;
    const payload = new TextEncoder().encode(
      JSON.stringify({ newHostId: transferTarget }),
    );
    void sendHostTransfer(payload, { reliable: true });
    setTransferTarget("");
  }, [transferTarget, sendHostTransfer]);

  return (
    <>
      {/* 举手按钮（叠加在左下角） */}
      <button
        type="button"
        onClick={toggleHandRaise}
        className={[
          "absolute bottom-[var(--space-20)] left-[var(--space-3)] z-[var(--z-sticky)] inline-flex items-center gap-1.5 h-9 px-3 rounded-[var(--radius-md)] border text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] transition-colors duration-[var(--motion-fast)]",
          handRaised
            ? "border-[var(--accent)] bg-[var(--accent)] text-[var(--accent-fg)]"
            : "border-[var(--border)] bg-[var(--surface)] text-[var(--fg-2)] hover:bg-[var(--surface-2)]",
        ].join(" ")}
        aria-pressed={handRaised}
        title={t("handRaise")}
      >
        <Hand size={16} className={handRaised ? "fill-current" : ""} />
        {t("handRaise")}
      </button>

      {/* 参与者设备信息面板（叠加在右侧） */}
      <div className="absolute top-[var(--space-3)] left-[var(--space-3)] z-[var(--z-sticky)] max-w-[240px] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] shadow-[var(--elev-sm)] p-[var(--space-2)] text-[length:var(--text-xs)] text-[var(--fg-2)] max-h-[60vh] overflow-y-auto">
        <div className="flex items-center gap-1.5 mb-[var(--space-1)] font-[weight:var(--weight-semibold)] text-[var(--meta)]">
          <Users size={12} />
          {t("participants")} · {participants.length}
        </div>
        <ul className="space-y-1">
          {participants.map((p) => {
            // 设备状态：从 participant 的 tracks 推断
            const micOn = p.isMicrophoneEnabled;
            const camOn = p.isCameraEnabled;
            const raised = raisedHands[p.identity];
            const isLocal = p.identity === localParticipant.identity;
            return (
              <li
                key={p.identity}
                className="flex items-center gap-1.5 py-0.5"
              >
                <span className="truncate flex-1">
                  {p.name ?? p.identity}
                  {isLocal && ` (${t("me")})`}
                </span>
                {/* 设备状态图标 */}
                {micOn ? (
                  <Mic size={11} className="text-[var(--success)]" />
                ) : (
                  <MicOff size={11} className="text-[var(--muted)]" />
                )}
                {camOn ? (
                  <VideoIcon size={11} className="text-[var(--success)]" />
                ) : (
                  <VideoOff size={11} className="text-[var(--muted)]" />
                )}
                {/* 举手标记 */}
                {raised && (
                  <Hand size={11} className="text-[var(--accent)] fill-current" />
                )}
              </li>
            );
          })}
        </ul>

        {/* L10 #36：主持人转移（仅 host 可见） */}
        {isHost && participants.length > 1 && (
          <div className="mt-[var(--space-2)] pt-[var(--space-2)] border-t border-[var(--border-soft)]">
            <div className="flex items-center gap-1 mb-1 font-[weight:var(--weight-semibold)] text-[var(--meta)]">
              <Crown size={12} />
              {t("transferHost")}
            </div>
            <div className="flex gap-1">
              <select
                value={transferTarget}
                onChange={(e) => setTransferTarget(e.target.value)}
                aria-label={t("transferHost")}
                className="flex-1 h-7 px-1.5 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-xs)] text-[var(--fg)] outline-none"
              >
                <option value="">{t("selectParticipant")}</option>
                {participants
                  .filter((p) => p.identity !== localParticipant.identity)
                  .map((p) => (
                    <option key={p.identity} value={p.identity}>
                      {p.name ?? p.identity}
                    </option>
                  ))}
              </select>
              <button
                type="button"
                onClick={handleTransferHost}
                disabled={!transferTarget}
                className="h-7 px-2 rounded-[var(--radius-sm)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-xs)] font-[weight:var(--weight-medium)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-[var(--motion-fast)]"
              >
                {t("transfer")}
              </button>
            </div>
          </div>
        )}
      </div>
    </>
  );
}

"use client";

/**
 * 远程控制面板 · components/remote-control/RemoteControlPanel.tsx
 *
 * 功能：
 *  - 发起远程控制请求（选择工作区成员作为目标用户）
 *  - 显示活跃会话列表（我发起的 + 发给我的）
 *  - 接受/拒绝传入的请求
 *  - 结束进行中的会话
 *  - 通过信令事件总线实时接收会话状态变更
 *
 * design token 样式，lucide-react 图标（size 14/16），
 * useTranslations("remoteControl") 国际化。
 */

import { useEffect, useState, useCallback, useRef } from "react";
import { useTranslations } from "next-intl";
import {
  Monitor,
  MonitorOff,
  Check,
  X,
  PhoneOff,
  Loader2,
  AlertCircle,
  Send,
  ArrowDownToLine,
  ArrowUpFromLine,
} from "lucide-react";
import { api, ApiError } from "@/lib/api";
import {
  SignalingClient,
  type SignalingMessage,
} from "@/lib/webrtc/signaling";
import {
  subscribeSessionEvents,
  type RemoteControlSessionEvent,
} from "@/lib/webrtc/remote-control-events";

// ─── 类型 ──────────────────────────────────────────────────────

/** 远程控制会话 DTO */
interface RemoteControlSessionDTO {
  id: string;
  workspaceId: string;
  initiatorId: string;
  targetId: string;
  status: string; // pending | active | rejected | ended | failed
  endReason: string | null;
  expiresAt: string;
  acceptedAt: string | null;
  endedAt: string | null;
  createdAt: string;
  updatedAt: string;
}

/** 工作区成员（简化） */
interface WorkspaceMember {
  userId: string;
  name: string | null;
  email: string;
  image: string | null;
  role: string;
}

// ─── 组件 ──────────────────────────────────────────────────────

export interface RemoteControlPanelProps {
  /** 当前工作区 ID */
  workspaceId: string;
  /** 当前用户 ID */
  currentUserId: string;
  /** 远程查看器渲染回调（当会话进入 active 状态时调用） */
  onActiveSession?: (session: RemoteControlSessionDTO) => void;
}

export function RemoteControlPanel({
  workspaceId,
  currentUserId,
  onActiveSession,
}: RemoteControlPanelProps) {
  const t = useTranslations("remoteControl");

  const [sessions, setSessions] = useState<RemoteControlSessionDTO[]>([]);
  const [members, setMembers] = useState<WorkspaceMember[]>([]);
  const [selectedUserId, setSelectedUserId] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [actioningId, setActioningId] = useState<string | null>(null);
  const [showUserSelect, setShowUserSelect] = useState(false);

  // 信令客户端（用于接收会话事件通知）
  const signalingRef = useRef<SignalingClient | null>(null);

  // 加载会话列表
  const loadSessions = useCallback(async () => {
    try {
      const data = await api<RemoteControlSessionDTO[]>(
        `/api/v1/remote-control?workspaceId=${workspaceId}`,
      );
      setSessions(data);
    } catch (err) {
      console.error("[RemoteControlPanel] loadSessions failed:", err);
    }
  }, [workspaceId]);

  // 加载工作区成员列表（用于选择目标用户）
  const loadMembers = useCallback(async () => {
    try {
      const data = await api<{ items: WorkspaceMember[] }>(
        `/api/v1/workspaces/${workspaceId}/members?limit=100`,
      );
      // 过滤掉自己
      setMembers(data.items.filter((m) => m.userId !== currentUserId));
    } catch (err) {
      console.error("[RemoteControlPanel] loadMembers failed:", err);
    }
  }, [workspaceId, currentUserId]);

  // 初始化加载
  useEffect(() => {
    let cancelled = false;
    (async () => {
      setLoading(true);
      setError("");
      await Promise.all([loadSessions(), loadMembers()]);
      if (!cancelled) setLoading(false);
    })();
    return () => {
      cancelled = true;
    };
  }, [loadSessions, loadMembers]);

  // 信令客户端：接收会话事件通知（实时更新列表）
  useEffect(() => {
    if (typeof window === "undefined") return;

    // 通过服务端事件总线订阅会话事件
    // 注意：subscribeSessionEvents 是服务端 EventEmitter，客户端需通过 SSE 接收
    // 这里复用 SignalingClient 的 SSE 连接，会话事件通过同一通道推送
    const client = new SignalingClient({ workspaceId });
    signalingRef.current = client;

    const unsubscribe = client.onMessage((msg: SignalingMessage) => {
      // 收到信令消息时刷新会话列表（简化处理）
      void loadSessions();
    });

    void client.connect();

    return () => {
      unsubscribe();
      client.disconnect();
      signalingRef.current = null;
    };
  }, [workspaceId, loadSessions]);

  // 发起远程控制请求
  const handleRequest = useCallback(async () => {
    if (!selectedUserId) return;
    setError("");
    setActioningId("new");
    try {
      await api("/api/v1/remote-control", {
        method: "POST",
        body: JSON.stringify({
          targetUserId: selectedUserId,
          workspaceId,
        }),
      });
      setShowUserSelect(false);
      setSelectedUserId("");
      await loadSessions();
    } catch (err) {
      const msg =
        err instanceof ApiError ? err.message : t("failed");
      setError(msg);
    } finally {
      setActioningId(null);
    }
  }, [selectedUserId, workspaceId, loadSessions, t]);

  // 接受/拒绝/结束会话
  const handleSessionAction = useCallback(
    async (
      sessionId: string,
      action: "accept" | "reject" | "end",
    ) => {
      setError("");
      setActioningId(sessionId);
      try {
        const updated = await api<RemoteControlSessionDTO>(
          `/api/v1/remote-control/${sessionId}?workspaceId=${workspaceId}`,
          {
            method: "PATCH",
            body: JSON.stringify({ action }),
          },
        );
        setSessions((prev) =>
          prev.map((s) => (s.id === sessionId ? updated : s)),
        );
        // 若接受且当前用户是发起方，触发远程查看器
        if (
          action === "accept" &&
          updated.status === "active" &&
          updated.initiatorId === currentUserId
        ) {
          onActiveSession?.(updated);
        }
      } catch (err) {
        const msg =
          err instanceof ApiError ? err.message : t("failed");
        setError(msg);
      } finally {
        setActioningId(null);
      }
    },
    [workspaceId, currentUserId, onActiveSession, t],
  );

  // 分组：传入请求（发给我的，pending）+ 传出请求（我发起的，pending）+ 活跃会话
  const incomingPending = sessions.filter(
    (s) => s.targetId === currentUserId && s.status === "pending",
  );
  const outgoingPending = sessions.filter(
    (s) => s.initiatorId === currentUserId && s.status === "pending",
  );
  const activeSessions = sessions.filter((s) => s.status === "active");

  // 获取用户显示名
  const getUserName = (userId: string): string => {
    const member = members.find((m) => m.userId === userId);
    return member?.name ?? member?.email ?? userId.slice(0, 8);
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center py-[var(--space-12)]">
        <Loader2 size={24} className="animate-spin text-[var(--accent)] mb-[var(--space-2)]" />
        <p className="text-[length:var(--text-sm)] text-[var(--muted)]">
          {t("connecting")}
        </p>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-[var(--space-4)]">
      {/* 标题栏 */}
      <div className="flex items-center justify-between">
        <h2 className="flex items-center gap-[var(--space-2)] text-[length:var(--text-base)] font-[weight:var(--weight-semibold)] text-[var(--fg)]">
          <Monitor size={16} className="text-[var(--accent)]" />
          {t("title")}
        </h2>
        <button
          type="button"
          onClick={() => setShowUserSelect((v) => !v)}
          className="flex items-center gap-[var(--space-1)] h-8 px-3 rounded-[var(--radius-sm)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] transition-colors duration-[var(--motion-fast)]"
        >
          <Send size={14} />
          {t("request")}
        </button>
      </div>

      {/* 错误提示 */}
      {error && (
        <div className="flex items-center gap-[var(--space-2)] px-[var(--space-3)] py-[var(--space-2)] rounded-[var(--radius-sm)] bg-[var(--danger-soft)] text-[var(--danger)] text-[length:var(--text-sm)]">
          <AlertCircle size={14} />
          {error}
        </div>
      )}

      {/* 用户选择面板 */}
      {showUserSelect && (
        <div className="rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)] p-[var(--space-3)]">
          <label className="block text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] mb-[var(--space-2)]">
            {t("selectUser")}
          </label>
          <select
            value={selectedUserId}
            onChange={(e) => setSelectedUserId(e.target.value)}
            className="w-full h-9 px-[var(--space-2)] rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--bg)] text-[length:var(--text-sm)] text-[var(--fg)] focus:border-[var(--accent)] focus:outline-none"
          >
            <option value="">{t("selectUser")}</option>
            {members.map((m) => (
              <option key={m.userId} value={m.userId}>
                {m.name ?? m.email}
              </option>
            ))}
          </select>
          <div className="flex justify-end gap-[var(--space-2)] mt-[var(--space-3)]">
            <button
              type="button"
              onClick={() => {
                setShowUserSelect(false);
                setSelectedUserId("");
              }}
              className="h-8 px-3 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
            >
              {t("no")}
            </button>
            <button
              type="button"
              onClick={handleRequest}
              disabled={!selectedUserId || actioningId === "new"}
              className="flex items-center gap-[var(--space-1)] h-8 px-3 rounded-[var(--radius-sm)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-[var(--motion-fast)]"
            >
              {actioningId === "new" ? (
                <Loader2 size={14} className="animate-spin" />
              ) : (
                <Send size={14} />
              )}
              {t("request")}
            </button>
          </div>
        </div>
      )}

      {/* 传入请求 */}
      {incomingPending.length > 0 && (
        <SessionGroup
          label={t("incoming")}
          icon={<ArrowDownToLine size={14} className="text-[var(--accent)]" />}
          sessions={incomingPending}
          currentUserId={currentUserId}
          getUserName={getUserName}
          actioningId={actioningId}
          onAction={handleSessionAction}
          t={t}
        />
      )}

      {/* 传出请求 */}
      {outgoingPending.length > 0 && (
        <SessionGroup
          label={t("outgoing")}
          icon={<ArrowUpFromLine size={14} className="text-[var(--meta)]" />}
          sessions={outgoingPending}
          currentUserId={currentUserId}
          getUserName={getUserName}
          actioningId={actioningId}
          onAction={handleSessionAction}
          t={t}
        />
      )}

      {/* 活跃会话 */}
      {activeSessions.length > 0 && (
        <SessionGroup
          label={t("active")}
          icon={<Monitor size={14} className="text-[var(--success)]" />}
          sessions={activeSessions}
          currentUserId={currentUserId}
          getUserName={getUserName}
          actioningId={actioningId}
          onAction={handleSessionAction}
          t={t}
        />
      )}

      {/* 空状态 */}
      {sessions.length === 0 && !showUserSelect && (
        <div className="flex flex-col items-center justify-center py-[var(--space-12)] text-center">
          <MonitorOff size={32} className="text-[var(--muted)] mb-[var(--space-3)]" />
          <p className="text-[length:var(--text-sm)] text-[var(--muted)]">
            {t("noActiveSessions")}
          </p>
        </div>
      )}
    </div>
  );
}

// ─── 会话分组子组件 ────────────────────────────────────────────

interface SessionGroupProps {
  label: string;
  icon: React.ReactNode;
  sessions: RemoteControlSessionDTO[];
  currentUserId: string;
  getUserName: (userId: string) => string;
  actioningId: string | null;
  onAction: (sessionId: string, action: "accept" | "reject" | "end") => void;
  t: ReturnType<typeof useTranslations>;
}

function SessionGroup({
  label,
  icon,
  sessions,
  currentUserId,
  getUserName,
  actioningId,
  onAction,
  t,
}: SessionGroupProps) {
  return (
    <section>
      <h3 className="flex items-center gap-[var(--space-1)] text-[length:var(--text-xs)] font-[weight:var(--weight-semibold)] text-[var(--meta)] uppercase tracking-wide mb-[var(--space-2)]">
        {icon}
        {label} · {sessions.length}
      </h3>
      <ul className="divide-y divide-[var(--border-soft)] rounded-[var(--radius-md)] border border-[var(--border)] bg-[var(--surface)]">
        {sessions.map((s) => {
          const isInitiator = s.initiatorId === currentUserId;
          const isTarget = s.targetId === currentUserId;
          const otherUserId = isInitiator ? s.targetId : s.initiatorId;
          const otherName = getUserName(otherUserId);
          const isActioning = actioningId === s.id;

          return (
            <li
              key={s.id}
              className="flex items-center justify-between px-[var(--space-3)] py-[var(--space-3)]"
            >
              <div className="flex flex-col gap-[var(--space-1)] min-w-0">
                <span className="text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg)] truncate">
                  {isInitiator ? t("youAreControlling") : t("beingControlled")}{" "}
                  {otherName}
                </span>
                <span className="text-[length:var(--text-xs)] text-[var(--muted)]">
                  {s.status === "pending" && t("waitingForAccept")}
                  {s.status === "active" && t("connected")}
                  {s.status === "rejected" && t("requestRejected")}
                  {s.status === "ended" && t("sessionEnded")}
                  {s.status === "failed" && t("failed")}
                </span>
              </div>

              <div className="flex items-center gap-[var(--space-1)] shrink-0">
                {/* 目标方对 pending 请求：接受/拒绝 */}
                {isTarget && s.status === "pending" && (
                  <>
                    <button
                      type="button"
                      onClick={() => onAction(s.id, "accept")}
                      disabled={isActioning}
                      title={t("accept")}
                      className="flex items-center justify-center w-8 h-8 rounded-[var(--radius-sm)] bg-[var(--success)] text-[var(--success-fg)] hover:bg-[var(--success-soft)] disabled:opacity-50 transition-colors duration-[var(--motion-fast)]"
                    >
                      {isActioning ? (
                        <Loader2 size={14} className="animate-spin" />
                      ) : (
                        <Check size={14} />
                      )}
                    </button>
                    <button
                      type="button"
                      onClick={() => onAction(s.id, "reject")}
                      disabled={isActioning}
                      title={t("reject")}
                      className="flex items-center justify-center w-8 h-8 rounded-[var(--radius-sm)] bg-[var(--danger)] text-[var(--danger-fg)] hover:bg-[var(--danger-soft)] disabled:opacity-50 transition-colors duration-[var(--motion-fast)]"
                    >
                      <X size={14} />
                    </button>
                  </>
                )}

                {/* 活跃会话：结束按钮 */}
                {s.status === "active" && (
                  <button
                    type="button"
                    onClick={() => onAction(s.id, "end")}
                    disabled={isActioning}
                    title={t("end")}
                    className="flex items-center justify-center w-8 h-8 rounded-[var(--radius-sm)] bg-[var(--danger)] text-[var(--danger-fg)] hover:bg-[var(--danger-soft)] disabled:opacity-50 transition-colors duration-[var(--motion-fast)]"
                  >
                    {isActioning ? (
                      <Loader2 size={14} className="animate-spin" />
                    ) : (
                      <PhoneOff size={14} />
                    )}
                  </button>
                )}
              </div>
            </li>
          );
        })}
      </ul>
    </section>
  );
}

"use client";

/**
 * 远程查看器 · components/remote-control/RemoteViewer.tsx
 *
 * 功能：
 *  - 显示远程屏幕画面（<video> 元素接收 MediaStream）
 *  - 捕获本地键盘/鼠标事件并通过 DataChannel 发送给被控方
 *  - 全屏支持
 *  - 断线重连提示
 *
 * 使用方式：
 *  - 控制方（controller）：接收被控方的屏幕流，捕获本地输入发送
 *  - 被控方（controlled）：本地屏幕流由 RemoteControlSession 管理，此组件不渲染视频
 *
 * design token 样式，lucide-react 图标（size 14/16），
 * useTranslations("remoteControl") 国际化。
 */

import { useEffect, useState, useCallback, useRef } from "react";
import { useTranslations } from "next-intl";
import {
  Maximize2,
  Minimize2,
  PhoneOff,
  Loader2,
  AlertCircle,
  WifiOff,
  Monitor,
} from "lucide-react";
import {
  RemoteControlSession,
  type InputEvent,
  type RemoteControlSessionState,
  mouseMove,
  mouseClick,
  mouseScroll,
  keyPress,
  mapMouseButton,
} from "@/lib/webrtc/peer-connection";
import { api } from "@/lib/api";

// ─── 类型 ──────────────────────────────────────────────────────

export interface RemoteViewerProps {
  /** 远程控制会话 ID */
  sessionId: string;
  /** 当前工作区 ID */
  workspaceId: string;
  /** 会话角色：controller（控制方，查看远程屏幕）*/
  role: "controller";
  /** 远程控制会话实例（已建立 WebRTC 连接） */
  session: RemoteControlSession;
  /** 结束会话回调 */
  onEnd: () => void;
}

// ─── 组件 ──────────────────────────────────────────────────────

export function RemoteViewer({
  sessionId,
  workspaceId,
  role,
  session,
  onEnd,
}: RemoteViewerProps) {
  const t = useTranslations("remoteControl");

  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [remoteStream, setRemoteStream] = useState<MediaStream | null>(null);
  const [sessionState, setSessionState] =
    useState<RemoteControlSessionState>(session.state);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [error, setError] = useState("");

  // 注册远程流回调
  useEffect(() => {
    const unsubscribeStream = session.onRemoteStream((stream) => {
      setRemoteStream(stream);
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        // 自动播放（静音以绕过浏览器自动播放策略）
        videoRef.current.play().catch(() => {
          // 自动播放被阻止，用户交互后可手动播放
        });
      }
    });

    const unsubscribeState = session.onStateChange((state) => {
      setSessionState(state);
      if (state === "failed") {
        setError(t("failed"));
      } else if (state === "disconnected") {
        setError(t("disconnected"));
      } else {
        setError("");
      }
    });

    return () => {
      unsubscribeStream();
      unsubscribeState();
    };
  }, [session, t]);

  // 全屏切换
  const toggleFullscreen = useCallback(async () => {
    if (!containerRef.current) return;
    try {
      if (!document.fullscreenElement) {
        await containerRef.current.requestFullscreen();
        setIsFullscreen(true);
      } else {
        await document.exitFullscreen();
        setIsFullscreen(false);
      }
    } catch (err) {
      console.error("[RemoteViewer] fullscreen failed:", err);
    }
  }, []);

  // 监听全屏状态变更（ESC 退出）
  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    document.addEventListener("fullscreenchange", handleFullscreenChange);
    return () => {
      document.removeEventListener("fullscreenchange", handleFullscreenChange);
    };
  }, []);

  // ─── 输入事件捕获 ──────────────────────────────────────────

  /** 将鼠标坐标转换为相对于视频画面的归一化坐标（0-1） */
  const getRelativeCoords = useCallback(
    (e: React.MouseEvent<HTMLVideoElement>): { x: number; y: number } => {
      const video = videoRef.current;
      if (!video) return { x: 0, y: 0 };
      const rect = video.getBoundingClientRect();
      const x = (e.clientX - rect.left) / rect.width;
      const y = (e.clientY - rect.top) / rect.height;
      return { x: Math.max(0, Math.min(1, x)), y: Math.max(0, Math.min(1, y)) };
    },
    [],
  );

  /** 鼠标移动 */
  const handleMouseMove = useCallback(
    (e: React.MouseEvent<HTMLVideoElement>) => {
      if (sessionState !== "connected") return;
      const { x, y } = getRelativeCoords(e);
      session.sendInputEvent(mouseMove(x, y));
    },
    [session, sessionState, getRelativeCoords],
  );

  /** 鼠标点击 */
  const handleMouseDown = useCallback(
    (e: React.MouseEvent<HTMLVideoElement>) => {
      if (sessionState !== "connected") return;
      e.preventDefault(); // 防止文本选择
      const { x, y } = getRelativeCoords(e);
      const button = mapMouseButton(e.button);
      session.sendInputEvent(mouseClick(x, y, button, "down"));
    },
    [session, sessionState, getRelativeCoords],
  );

  const handleMouseUp = useCallback(
    (e: React.MouseEvent<HTMLVideoElement>) => {
      if (sessionState !== "connected") return;
      const { x, y } = getRelativeCoords(e);
      const button = mapMouseButton(e.button);
      session.sendInputEvent(mouseClick(x, y, button, "up"));
    },
    [session, sessionState, getRelativeCoords],
  );

  const handleDoubleClick = useCallback(
    (e: React.MouseEvent<HTMLVideoElement>) => {
      if (sessionState !== "connected") return;
      const { x, y } = getRelativeCoords(e);
      const button = mapMouseButton(e.button);
      session.sendInputEvent(mouseClick(x, y, button, "double"));
    },
    [session, sessionState, getRelativeCoords],
  );

  /** 鼠标滚轮 */
  const handleWheel = useCallback(
    (e: React.WheelEvent<HTMLVideoElement>) => {
      if (sessionState !== "connected") return;
      const { x, y } = getRelativeCoords(e);
      session.sendInputEvent(mouseScroll(x, y, e.deltaY));
    },
    [session, sessionState, getRelativeCoords],
  );

  /** 键盘按键 */
  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLDivElement>) => {
      if (sessionState !== "connected") return;
      // 阻止默认行为（防止页面滚动等）
      if (["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", "Tab", " "].includes(e.key)) {
        e.preventDefault();
      }
      const event = keyPress(e.key, "down", {
        ctrl: e.ctrlKey,
        shift: e.shiftKey,
        alt: e.altKey,
        meta: e.metaKey,
      });
      session.sendInputEvent(event);
    },
    [session, sessionState],
  );

  const handleKeyUp = useCallback(
    (e: React.KeyboardEvent<HTMLDivElement>) => {
      if (sessionState !== "connected") return;
      const event = keyPress(e.key, "up", {
        ctrl: e.ctrlKey,
        shift: e.shiftKey,
        alt: e.altKey,
        meta: e.metaKey,
      });
      session.sendInputEvent(event);
    },
    [session, sessionState],
  );

  // 结束会话
  const handleEnd = useCallback(async () => {
    session.close();
    try {
      await api(
        `/api/v1/remote-control/${sessionId}?workspaceId=${workspaceId}`,
        { method: "DELETE" },
      );
    } catch (err) {
      console.error("[RemoteViewer] end session failed:", err);
    }
    onEnd();
  }, [session, sessionId, workspaceId, onEnd]);

  // ─── 渲染 ──────────────────────────────────────────────────

  const isConnected = sessionState === "connected";
  const isConnecting =
    sessionState === "connecting" ||
    sessionState === "initiating" ||
    sessionState === "accepting";

  return (
    <div
      ref={containerRef}
      className="fixed inset-0 z-[var(--z-modal)] flex flex-col bg-[var(--bg)]"
      tabIndex={0}
      onKeyDown={handleKeyDown}
      onKeyUp={handleKeyUp}
    >
      {/* 顶部状态栏 */}
      <div className="flex items-center justify-between px-[var(--space-4)] py-[var(--space-2)] bg-[var(--surface)] border-b border-[var(--border)]">
        <div className="flex items-center gap-[var(--space-2)]">
          <Monitor size={16} className="text-[var(--accent)]" />
          <span className="text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg)]">
            {t("youAreControlling")}
          </span>
          {/* 状态指示器 */}
          <span className="flex items-center gap-[var(--space-1)] text-[length:var(--text-xs)]">
            {isConnected && (
              <>
                <span className="w-2 h-2 rounded-full bg-[var(--success)]" />
                <span className="text-[var(--success)]">{t("connected")}</span>
              </>
            )}
            {isConnecting && (
              <>
                <Loader2 size={12} className="animate-spin text-[var(--accent)]" />
                <span className="text-[var(--accent)]">{t("connecting")}</span>
              </>
            )}
            {sessionState === "disconnected" && (
              <>
                <WifiOff size={12} className="text-[var(--warn)]" />
                <span className="text-[var(--warn)]">{t("disconnected")}</span>
              </>
            )}
            {sessionState === "failed" && (
              <>
                <AlertCircle size={12} className="text-[var(--danger)]" />
                <span className="text-[var(--danger)]">{t("failed")}</span>
              </>
            )}
          </span>
        </div>

        <div className="flex items-center gap-[var(--space-1)]">
          {/* 全屏按钮 */}
          <button
            type="button"
            onClick={toggleFullscreen}
            title={t("fullscreen")}
            className="flex items-center justify-center w-8 h-8 rounded-[var(--radius-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
          >
            {isFullscreen ? <Minimize2 size={16} /> : <Maximize2 size={16} />}
          </button>
          {/* 结束按钮 */}
          <button
            type="button"
            onClick={handleEnd}
            title={t("end")}
            className="flex items-center gap-[var(--space-1)] h-8 px-3 rounded-[var(--radius-sm)] bg-[var(--danger)] text-[var(--danger-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--danger-soft)] transition-colors duration-[var(--motion-fast)]"
          >
            <PhoneOff size={14} />
            {t("end")}
          </button>
        </div>
      </div>

      {/* 视频画面区域 */}
      <div className="flex-1 relative flex items-center justify-center bg-[var(--surface)] overflow-hidden">
        <video
          ref={videoRef}
          autoPlay
          muted
          playsInline
          onMouseMove={handleMouseMove}
          onMouseDown={handleMouseDown}
          onMouseUp={handleMouseUp}
          onDoubleClick={handleDoubleClick}
          onWheel={handleWheel}
          className="max-w-full max-h-full object-contain cursor-crosshair"
          style={{ display: remoteStream ? "block" : "none" }}
        />

        {/* 连接中遮罩 */}
        {isConnecting && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-[var(--bg)] bg-opacity-80">
            <Loader2 size={32} className="animate-spin text-[var(--accent)] mb-[var(--space-3)]" />
            <p className="text-[length:var(--text-sm)] text-[var(--muted)]">
              {t("connecting")}
            </p>
          </div>
        )}

        {/* 错误遮罩 */}
        {error && sessionState !== "connected" && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-[var(--bg)] bg-opacity-80">
            <AlertCircle size={32} className="text-[var(--danger)] mb-[var(--space-3)]" />
            <p className="text-[length:var(--text-sm)] text-[var(--danger)] mb-[var(--space-4)]">
              {error}
            </p>
            <button
              type="button"
              onClick={handleEnd}
              className="h-9 px-4 rounded-[var(--radius-md)] bg-[var(--accent)] text-[var(--accent-fg)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--accent-hover)] transition-colors duration-[var(--motion-fast)]"
            >
              {t("end")}
            </button>
          </div>
        )}

        {/* 无流提示 */}
        {!remoteStream && !isConnecting && !error && (
          <div className="flex flex-col items-center justify-center">
            <Monitor size={48} className="text-[var(--muted)] mb-[var(--space-3)]" />
            <p className="text-[length:var(--text-sm)] text-[var(--muted)]">
              {t("screenShare")}
            </p>
          </div>
        )}
      </div>

      {/* 底部提示栏 */}
      {isConnected && (
        <div className="px-[var(--space-4)] py-[var(--space-2)] bg-[var(--surface)] border-t border-[var(--border)] text-center">
          <span className="text-[length:var(--text-xs)] text-[var(--muted)]">
            {t("inputControl")} · {t("fullscreen")}: F11
          </span>
        </div>
      )}
    </div>
  );
}

"use client";

// 设置 - 危险操作区：删除工作区（两步确认） + 删除账户（预览 + 邮箱确认）。
// 拆分自 settings/page.tsx 第 881-1068 行 + 相关状态/函数。子组件自管状态。

import { useState } from "react";
import { Trash2, UserX, Loader2 } from "lucide-react";
import { useTranslations } from "next-intl";
import { useRouter } from "@/lib/i18n-navigation";
import { api } from "@/lib/api";
import type { DeletionPreview as AccountDeletionPreview } from "@/lib/account-deletion";
import type { Workspace } from "./types";

const inputClass =
  "w-full h-9 px-3 border border-[var(--border)] rounded-[var(--radius-md)] bg-[var(--surface)] text-[var(--fg)] outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2 disabled:bg-[var(--surface-2)] disabled:text-[var(--muted)] placeholder:text-[var(--meta)]";
const labelClass =
  "block text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] mb-1.5";

interface SettingsDangerZoneProps {
  ws: Workspace | null;
  wid: string;
  onError: (msg: string) => void;
}

export function SettingsDangerZone({ ws, wid, onError }: SettingsDangerZoneProps) {
  const t = useTranslations("settings");
  const tAccount = useTranslations("accountDeletion");
  const tErr = useTranslations("error");
  const tRole = useTranslations("role");
  const router = useRouter();

  // 删除工作区确认流程
  const [deleteConfirm, setDeleteConfirm] = useState(false);
  const [deleteInput, setDeleteInput] = useState("");
  const [deleting, setDeleting] = useState(false);

  // 删除账户（阶段 2-3）：预览 + 邮箱确认
  const [accountDeleteOpen, setAccountDeleteOpen] = useState(false);
  const [accountPreview, setAccountPreview] = useState<AccountDeletionPreview | null>(null);
  const [accountPreviewLoading, setAccountPreviewLoading] = useState(false);
  const [accountDeleteInput, setAccountDeleteInput] = useState("");
  const [accountDeleting, setAccountDeleting] = useState(false);

  // 删除工作区（两步确认：勾选确认 + 输入工作区名匹配）
  async function handleDeleteWorkspace() {
    if (!ws || deleting) return;
    if (deleteInput.trim() !== ws.name) {
      onError(t("deleteNameMismatch"));
      return;
    }
    setDeleting(true);
    onError("");
    try {
      await api(`/api/v1/workspaces/${wid}`, { method: "DELETE" });
      // 删除成功后跳转到首页
      router.push("/");
    } catch (e) {
      onError(e instanceof Error ? e.message : t("deleteFailed"));
    } finally {
      setDeleting(false);
    }
  }

  async function loadAccountPreview() {
    setAccountPreviewLoading(true);
    setAccountPreview(null);
    try {
      setAccountPreview(await api<AccountDeletionPreview>("/api/v1/users/me/account"));
    } catch {
      setAccountPreview(null); // 展示 previewFailed 提示，不阻断删除流程
    } finally {
      setAccountPreviewLoading(false);
    }
  }

  async function handleDeleteAccount() {
    if (accountDeleting) return;
    setAccountDeleting(true);
    onError("");
    try {
      // 请求体带邮箱做服务端二次确认；不匹配服务端拒绝（400）
      await api("/api/v1/users/me/account", {
        method: "DELETE",
        body: JSON.stringify({ confirmEmail: accountDeleteInput.trim() }),
      });
      // 账户已删（cookie 已过期）：整页跳转登录页
      router.push("/auth/login");
    } catch (e) {
      onError(e instanceof Error ? e.message : tAccount("failed"));
      setAccountDeleting(false);
    }
  }

  return (
    <>
      {/* 危险操作（P4：删除工作区两步确认流程） */}
      {ws?.role === "owner" && (
        <section className="mt-5 rounded-[var(--radius-lg)] p-4 sm:p-5 border border-[var(--danger)] bg-[var(--danger-soft)]">
          <h2 className="flex items-center gap-2 text-[length:var(--text-md)] font-[weight:var(--weight-semibold)] text-[var(--danger-fg)] mb-1">
            <Trash2 size={16} />
            {t("dangerTitle")}
          </h2>
          <p className="text-[length:var(--text-sm)] text-[var(--danger-fg)] opacity-90 mb-4">
            {t("dangerHint")}
          </p>

          {!deleteConfirm ? (
            <button
              onClick={() => setDeleteConfirm(true)}
              className="h-9 px-4 border border-[var(--danger)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--danger-fg)] hover:bg-[var(--danger)] hover:text-[var(--accent-fg)] transition-colors duration-[var(--motion-base)] flex items-center gap-1.5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
            >
              <Trash2 size={15} />
              {t("deleteInit")}
            </button>
          ) : (
            <div className="space-y-3">
              <div className="p-3 rounded-[var(--radius-md)] bg-[color-mix(in_srgb,var(--danger)_10%,transparent)] text-[length:var(--text-sm)] text-[var(--danger-fg)]">
                {t("deleteConfirmHint", { name: ws.name })}
              </div>
              <div>
                <label htmlFor="delete-confirm-input" className={labelClass}>
                  {t("deleteConfirmLabel", { name: ws.name })}
                </label>
                <input
                  id="delete-confirm-input"
                  type="text"
                  value={deleteInput}
                  onChange={(e) => setDeleteInput(e.target.value)}
                  className={inputClass}
                  placeholder={ws.name}
                  autoComplete="off"
                />
              </div>
              <div className="flex items-center gap-2">
                <button
                  onClick={handleDeleteWorkspace}
                  disabled={deleting || deleteInput.trim() !== ws.name}
                  className="h-9 px-4 bg-[var(--danger)] text-[var(--accent-fg)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] hover:bg-[var(--danger)] hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-[var(--motion-base)] flex items-center gap-1.5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
                >
                  {deleting && <Loader2 size={15} className="animate-spin" />}
                  {t("deleteConfirm")}
                </button>
                <button
                  onClick={() => {
                    setDeleteConfirm(false);
                    setDeleteInput("");
                  }}
                  className="h-9 px-4 rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
                >
                  {t("deleteCancel")}
                </button>
              </div>
            </div>
          )}
        </section>
      )}

      {/* 删除账户（阶段 2-3：隐私政策"账户设置里可删除"承诺兑现）
          用户级操作（影响所有工作区），三步：展开 → 预览 → 输入邮箱确认删除 */}
      <section className="mt-5 rounded-[var(--radius-lg)] p-4 sm:p-5 border border-[var(--danger)] bg-[var(--danger-soft)]">
        <h2 className="flex items-center gap-2 text-[length:var(--text-md)] font-[weight:var(--weight-semibold)] text-[var(--danger-fg)] mb-1">
          <UserX size={16} />
          {tAccount("title")}
        </h2>
        <p className="text-[length:var(--text-sm)] text-[var(--danger-fg)] opacity-90 mb-4">
          {tAccount("hint")}
        </p>

        {!accountDeleteOpen ? (
          <button
            onClick={() => {
              setAccountDeleteOpen(true);
              loadAccountPreview();
            }}
            className="h-9 px-4 border border-[var(--danger)] rounded-[var(--radius-md)] text-[length:var(--text-sm)] font-[weight:var(--weight-medium)] text-[var(--danger-fg)] hover:bg-[var(--danger)] hover:text-[var(--accent-fg)] transition-colors duration-[var(--motion-base)] flex items-center gap-1.5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent-ring)] focus-visible:ring-offset-2"
          >
            <UserX size={15} />
            {tAccount("init")}
          </button>
        ) : (
          <div className="space-y-3">
            {/* 数据预览 */}
            {accountPreviewLoading ? (
              <div className="flex items-center gap-2 text-[length:var(--text-sm)] text-[var(--fg-2)]">
                <Loader2 size={15} className="animate-spin" />
                {tAccount("previewLoading")}
              </div>
            ) : accountPreview ? (
              <div className="space-y-2 p-3 rounded-[var(--radius-md)] bg-[var(--surface)] text-[length:var(--text-sm)]">
                {accountPreview.ownedWorkspaces.length > 0 && (
                  <div>
                    <p className="text-[var(--danger-fg)] font-[weight:var(--weight-medium)]">
                      {tAccount("previewOwned", { count: accountPreview.ownedWorkspaces.length })}
                    </p>
                    <ul className="mt-1 space-y-0.5 text-[var(--fg-2)]">
                      {accountPreview.ownedWorkspaces.map((w) => (
                        <li key={w.id}>
                          · {w.name}（{w.memberCount} {tAccount("previewMembers")}，{" "}
                          {tAccount("previewWillDelete")}）
                        </li>
                      ))}
                    </ul>
                    {accountPreview.stats.ownedTasks > 0 && (
                      <p className="mt-1 text-[var(--muted)] text-[length:var(--text-xs)]">
                        {tAccount("previewStats", {
                          tasks: accountPreview.stats.ownedTasks,
                          decisions: accountPreview.stats.ownedDecisions,
                          messages: accountPreview.stats.messages,
                        })}
                      </p>
                    )}
                  </div>
                )}
                {accountPreview.joinedWorkspaces.length > 0 && (
                  <div>
                    <p className="text-[var(--fg)]">
                      {tAccount("previewJoined", {
                        count: accountPreview.joinedWorkspaces.length,
                      })}
                    </p>
                    <ul className="mt-1 space-y-0.5 text-[var(--muted)]">
                      {accountPreview.joinedWorkspaces.map((w) => (
                        <li key={w.id}>
                          · {w.name}（{tRole(w.role)}）
