            <div>
              <label htmlFor="account-delete-input" className={labelClass}>
                {tAccount("confirmLabel")}
              </label>
              <input
                id="account-delete-input"
                type="email"
                value={accountDeleteInput}
                onChange={(e) => setAccountDeleteInput(e.target.value)}
