                        <button
                          onClick={() => {
                            onEdit(wf);
                            setMenuOpenId(null);
                          }}
                          className="flex items-center gap-2 w-full px-3 py-2 text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
                        >
                          <Pencil size={14} />
                          {t("edit")}
                        </button>
                        <button
                          onClick={() => {
                            onShowExecutions(wf);
                            setMenuOpenId(null);
                          }}
                          className="flex items-center gap-2 w-full px-3 py-2 text-[length:var(--text-sm)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
                        >
                          <History size={14} />
                          {t("executions")}
                        </button>
                        <button
                          onClick={() => {
                            handleDelete(wf);
