                >
                  <Pencil size={12} />
                  {t("edit")}
                </button>
                <button
                  onClick={() => onShowExecutions(wf)}
                  className="hidden md:inline-flex items-center gap-1 h-7 px-2 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-xs)] text-[var(--fg-2)] hover:bg-[var(--surface-2)] transition-colors duration-[var(--motion-fast)]"
                >
                  <History size={12} />
                  {t("executions")}
                </button>
                <button
                  onClick={() => handleDelete(wf)}
                  disabled={deletingId === wf.id}
                  className="hidden md:inline-flex items-center gap-1 h-7 px-2 rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--surface)] text-[length:var(--text-xs)] text-[var(--danger-fg)] hover:bg-[var(--danger-soft)] disabled:opacity-50 transition-colors duration-[var(--motion-fast)]"
                >
                  {deletingId === wf.id ? <Loader2 size={12} className="animate-spin" /> : <Trash2 size={12} />}
                  {t("delete")}
                </button>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

"use client";

/**
 * usePinchZoom — 双指捏合缩放 hook。
 *
 * 用 framer-motion useMotionValue 跟踪双指距离，计算缩放比。
 * 缩放范围 0.5~3x，双击复位到 1x。
 * 尊重 prefers-reduced-motion：reduced 时直接设 scale 无动画。
 *
 * @see design/FEATURE-DESIGN-ui-polish.md §4.3 pinch-to-zoom
 */

import { useMotionValue, useReducedMotion } from "framer-motion";
import { useCallback, useRef, useState } from "react";

const MIN_SCALE = 0.5;
const MAX_SCALE = 3;
const DOUBLE_TAP_DELAY = 300;

export interface UsePinchZoomResult {
  /** 当前缩放值（MotionValue，可直接传给 motion.div style={{ scale }}） */
  scale: ReturnType<typeof useMotionValue<number>>;
  /** 展开到目标元素的触摸事件绑定 */
  bind: {
    onTouchStart: (e: React.TouchEvent) => void;
    onTouchMove: (e: React.TouchEvent) => void;
    onTouchEnd: () => void;
    onDoubleClick: () => void;
  };
}

export function usePinchZoom(): UsePinchZoomResult {
  const scale = useMotionValue(1);
  const prefersReduced = useReducedMotion();
  const initialDistanceRef = useRef<number | null>(null);
  const lastTapRef = useRef<number>(0);

  const getDistance = (touches: React.TouchList): number => {
    if (touches.length < 2) return 0;
    const dx = touches[0].clientX - touches[1].clientX;
    const dy = touches[0].clientY - touches[1].clientY;
    return Math.hypot(dx, dy);
  };

  const clampScale = (value: number): number =>
    Math.min(MAX_SCALE, Math.max(MIN_SCALE, value));

  const onTouchStart = useCallback(
    (e: React.TouchEvent) => {
      if (e.touches.length === 2) {
        initialDistanceRef.current = getDistance(e.touches);
      }
    },
    [],
  );

  const onTouchMove = useCallback(
    (e: React.TouchEvent) => {
      if (e.touches.length === 2 && initialDistanceRef.current) {
        const currentDistance = getDistance(e.touches);
        const ratio = currentDistance / initialDistanceRef.current;
        const newScale = clampScale(ratio);
        scale.set(prefersReduced ? Math.round(newScale) : newScale);
      }
    },
    [scale, prefersReduced],
  );

  const onTouchEnd = useCallback(() => {
    initialDistanceRef.current = null;
  }, []);

  // 双击复位
  const onDoubleClick = useCallback(() => {
    const now = Date.now();
    if (now - lastTapRef.current < DOUBLE_TAP_DELAY) {
      scale.set(1);
    }
    lastTapRef.current = now;
  }, [scale]);

  return {
    scale,
    bind: { onTouchStart, onTouchMove, onTouchEnd, onDoubleClick },
  };
}

/**
 * Next.js instrumentation hook — 在服务器启动时执行
 * 用于环境变量校验和优雅关闭注册
 */
export async function register() {
  // 仅在服务端执行（非 Edge Runtime）
  if (process.env.NEXT_RUNTIME === "nodejs") {
    // 环境变量校验（fail-fast）
    const { getEnv } = await import("./lib/env");
    try {
      getEnv();
      console.log("[instrumentation] 环境变量校验通过");
    } catch (err) {
      console.error("[instrumentation] 环境变量校验失败:", err);
      // 生产环境直接退出，开发环境警告但继续
      if (process.env.NODE_ENV === "production") {
        process.exit(1);
      }
    }

    // 优雅关闭处理
    const { setupGracefulShutdown } = await import("./lib/shutdown");
    setupGracefulShutdown();
  }
}

import { NextRequest, NextResponse } from "next/server";
import { auth, authenticate } from "@/lib/auth";
import { apiMsg } from "@/lib/api-messages";

/**
 * AI 路由共享认证与响应辅助。
 *
 * 认证策略与 /api/v1/users/me 同源：优先 Better Auth session（浏览器 cookie），
 * 回退到 JWT access_token（API 客户端 Bearer），保证两种调用方式均可访问。
 */

/**
 * 获取当前用户 ID：优先 Better Auth session，回退到 JWT access_token。
 */
export async function getUserId(req: NextRequest): Promise<string | null> {
  // 1) 先尝试 Better Auth session（浏览器端主路径）
  try {
    const session = await auth.api.getSession({ headers: req.headers });
    if (session?.user?.id) return session.user.id;
  } catch {
    // session 不存在或已过期，回退到 JWT
  }
  // 2) 回退到 JWT access_token（API 客户端 / curl 测试）
  const payload = await authenticate(req);
  return payload?.sub ?? null;
}

/** 未认证响应（401） */
export function unauthorizedResponse(req: NextRequest): NextResponse {
  return NextResponse.json(
    { code: 401, message: apiMsg(req, "unauthorized"), data: null },
    { status: 401 },
  );
}

/** AI 服务未配置响应（503）
 *
 * code 对齐统一数字模式（原 "AI_NOT_CONFIGURED" 字符串违反 { code, data, message } 信封约定）。
 * 接受 req 参数以备国际化；apiMsg 暂无 aiNotConfigured key，先用硬编码英文。
 */
export function aiNotConfiguredResponse(req: NextRequest): NextResponse {
  return NextResponse.json(
    { code: 503, message: "AI service is not configured", data: null },
    { status: 503 },
  );
}

/** 检查 AI 服务是否已配置（DEEPSEEK_API_KEY 或 OPENAI_API_KEY 任一存在且非空） */
export function isAiConfigured(): boolean {
  return !!process.env.DEEPSEEK_API_KEY || !!process.env.OPENAI_API_KEY;
}
/**
 * 获取当前用户 ID + 工作区 ID（用于 AI 使用量跟踪）。
 *
 * userId 优先 Better Auth session，回退到 JWT access_token（与 getUserId 一致）。
 * workspaceId 仅从 JWT payload.wid 获取（Better Auth session 不含 wid）；
 * 若 JWT 不存在（纯 Better Auth session 场景），workspaceId 为 null，
 * 调用方应跳过 usage tracking（AiUsageLog.workspaceId 为必填外键）。
 *
 * @returns { userId, workspaceId } 或 null（未认证）
 */
export async function getUserIdAndWorkspaceId(
  req: NextRequest,
): Promise<{ userId: string; workspaceId: string | null } | null> {
  const userId = await getUserId(req);
  if (!userId) return null;
  const payload = await authenticate(req);
  return { userId, workspaceId: payload?.wid ?? null };
}

/**
 * AI 流式进度反馈工具。
 *
 * 基于 Vercel AI SDK v7 的 `createUIMessageStream` 创建自定义 UI 消息流，
 * 在 LLM 文本流之前发送阶段化进度 data part（`data-progress`），
 * 前端可解析并显示步骤指示器。
 *
 * 提供两个工厂函数：
 *  - `createAiProgressStream`：文本流模式（streamText），用于日报/洞察等 markdown 输出
 *  - `createAiJsonProgressStream`：JSON 模式（generateText），用于审批建议等结构化输出
 *
 * 进度 data part 格式：{ type: "data-progress", data: { stage, message } }
 * 结果 data part 格式：{ type: "data-result", data: <任意 JSON> }
 *
 * 设计决策：进度阶段有真实时序——阶段 1（聚合数据）在 buildPrompt 之前发送，
 * 阶段 2（分析）在 buildPrompt 完成后发送，阶段 3（生成）在 LLM 调用前发送。
 * 这样前端步骤指示器能真实反映后端处理进度，而非一次性闪过。
 */

import {
  createUIMessageStream,
  createUIMessageStreamResponse,
  streamText,
  generateText,
  type LanguageModel,
  type UIMessage,
  type UIMessageChunk,
} from "ai";
import { fireRecordUsage, type UsageTrackingParams } from "@/lib/ai/usage-middleware";

/** 进度 data part 的数据结构（写入流中 `data-progress` 类型的 data 字段） */
export interface AiProgressData {
  /** 阶段编号：1=聚合数据, 2=分析, 3=生成 */
  stage: 1 | 2 | 3;
  /** 阶段描述消息（已国际化，由路由传入） */
  message: string;
}

/** 3 阶段进度消息配置 */
export interface AiProgressStages {
  /** 阶段 1：正在聚合数据 */
  context: string;
  /** 阶段 2：正在分析 */
  analyzing: string;
  /** 阶段 3：正在生成回答 */
  generating: string;
}

/**
 * 写入进度 data part 到流。
 *
 * data part 的 type 为 `data-progress`，data 为 `{ stage, message }`。
 * 用类型断言因为 UIMessageChunk 的 data part 类型是 `data-${string}` 的联合，
 * TypeScript 无法自动推断 `data-progress` 是合法成员。
 */
function writeProgress(
  writer: { write(part: UIMessageChunk): void },
  stage: 1 | 2 | 3,
  message: string,
): void {
  writer.write({
    type: "data-progress",
    data: { stage, message },
  } as UIMessageChunk);
}

/** createAiProgressStream 的参数 */
export interface CreateAiProgressStreamParams {
  /** LLM 模型实例 */
  model: LanguageModel;
  /** System prompt */
  system: string;
  /**
   * 异步构建 user prompt（如聚合数据库上下文）。
   * 在阶段 1（聚合数据）之后、阶段 2（分析）之前执行。
   * 将上下文聚合封装在此函数中，让进度阶段有真实时序。
   */
  buildPrompt: () => Promise<string>;
  /**
   * 可选：使用量跟踪参数。传入后在流结束后异步记录 usage（fire-and-forget）。
   * workspaceId 为 null 时跳过记录。
   */
  usageTracking?: UsageTrackingParams;
}

/**
 * 创建带阶段化进度的 AI 文本流式响应。
 *
 * 流程：
 *  1. 写入阶段 1 进度（正在聚合数据...）
 *  2. 执行 buildPrompt（聚合上下文，可能较慢）
 *  3. 写入阶段 2 进度（正在分析...）
 *  4. 写入阶段 3 进度（正在生成回答...）
 *  5. 调用 streamText 并合并 LLM 文本流
 *
 * @returns Response（SSE 格式，可直接从 Next.js route handler 返回）
 */
export function createAiProgressStream(
  params: CreateAiProgressStreamParams,
  stages: AiProgressStages,
): Response {
  const usageStartTime = params.usageTracking ? Date.now() : 0;
  const stream = createUIMessageStream<UIMessage>({
    execute: async ({ writer }) => {
      // 阶段 1：聚合数据
      writeProgress(writer, 1, stages.context);

      // 执行上下文聚合（可能涉及多次数据库查询，较慢）
      // try-catch：buildPrompt 失败时抛出带上下文的有意义错误，便于调用方排查
      let prompt: string;
      try {
        prompt = await params.buildPrompt();
      } catch (e) {
        throw new Error(
          `[ai-stream] buildPrompt 失败: ${e instanceof Error ? e.message : String(e)}`,
        );
      }

      // 阶段 2：分析
      writeProgress(writer, 2, stages.analyzing);

      // 阶段 3：生成
      writeProgress(writer, 3, stages.generating);

      // 调用 LLM 流式生成并合并到 UI 消息流
      // try-catch：streamText 初始化或流合并失败时抛出有意义错误
      let result;
      try {
        result = streamText({
          model: params.model,
          system: params.system,
          prompt,
          // 流结束后异步记录 usage（fire-and-forget）
          onFinish: params.usageTracking
            ? ({ usage }) => {
                fireRecordUsage(params.usageTracking!, usageStartTime, usage);
              }
            : undefined,
        });
      } catch (e) {
        // usage tracking：记录失败
        if (params.usageTracking) {
          fireRecordUsage(params.usageTracking, usageStartTime, undefined, false);
        }
        throw new Error(
          `[ai-stream] streamText 初始化失败: ${e instanceof Error ? e.message : String(e)}`,
        );
      }
      // await 确保 LLM 流完整合并后再结束 execute，避免流提前关闭
      try {
        await writer.merge(result.toUIMessageStream());
      } catch (e) {
        throw new Error(
          `[ai-stream] 流合并失败: ${e instanceof Error ? e.message : String(e)}`,
        );
      }
    },
  });

  return createUIMessageStreamResponse({ stream });
}

/** createAiJsonProgressStream 的参数 */
export interface CreateAiJsonProgressStreamParams<T> {
  /** LLM 模型实例 */
  model: LanguageModel;
  /** System prompt */
  system: string;
  /**
   * 异步构建 user prompt（如聚合审批实例 + 历史审批）。
   * 在阶段 1（聚合数据）之后、阶段 2（分析）之前执行。
   */
  buildPrompt: () => Promise<string>;
  /**
   * 从 LLM 输出文本解析结构化结果。
   * 解析失败时应返回降级结果（而非抛异常），由调用方决定降级策略。
   */
  parseResult: (text: string) => T;
  /**
   * 可选：使用量跟踪参数。传入后在 LLM 调用结束后异步记录 usage（fire-and-forget）。
   * workspaceId 为 null 时跳过记录。
   */
  usageTracking?: UsageTrackingParams;
}

/**
 * 创建带阶段化进度的 AI JSON 流式响应。
 *
 * 与 `createAiProgressStream` 类似，但使用 `generateText`（非流式）获取完整 LLM 输出，
 * 解析为 JSON 后以 `data-result` data part 发送，前端可解析并渲染结构化 UI。
 *
 * 适用于需要结构化输出（如审批建议的 riskLevel/riskFactors/suggestion）的场景：
 * 流式发送进度 data part，最后发送结果 data part，前端保持结构化展示。
 *
 * @returns Response（SSE 格式，含进度 data part + 结果 data part）
 */
export function createAiJsonProgressStream<T>(
  params: CreateAiJsonProgressStreamParams<T>,
  stages: AiProgressStages,
): Response {
  const usageStartTime = params.usageTracking ? Date.now() : 0;
  const stream = createUIMessageStream<UIMessage>({
    execute: async ({ writer }) => {
      // 阶段 1：聚合数据
      writeProgress(writer, 1, stages.context);

      // 执行上下文聚合
      // try-catch：buildPrompt 失败时抛出带上下文的有意义错误
      let prompt: string;
      try {
        prompt = await params.buildPrompt();
      } catch (e) {
        throw new Error(
          `[ai-stream] buildPrompt 失败: ${e instanceof Error ? e.message : String(e)}`,
        );
      }

      // 阶段 2：分析
      writeProgress(writer, 2, stages.analyzing);

      // 阶段 3：生成
      writeProgress(writer, 3, stages.generating);

      // 调用 LLM（非流式，获取完整输出后解析 JSON）
      // try-catch：generateText 可能因网络/限流/模型异常失败
      let result;
      try {
        result = await generateText({
          model: params.model,
          system: params.system,
          prompt,
        });
      } catch (e) {
        // usage tracking：记录失败
        if (params.usageTracking) {
          fireRecordUsage(params.usageTracking, usageStartTime, undefined, false);
        }
        throw new Error(
          `[ai-stream] generateText 失败: ${e instanceof Error ? e.message : String(e)}`,
        );
      }

      // usage tracking：记录成功（fire-and-forget）
      if (params.usageTracking) {
        fireRecordUsage(
          params.usageTracking,
          usageStartTime,
          result.usage
            ? { inputTokens: result.usage.inputTokens, outputTokens: result.usage.outputTokens }
            : undefined,
        );
      }

      // 解析结果并写入 data-result data part
      // try-catch：parseResult 失败时抛出有意义错误（虽然接口约定 parseResult 应返回降级结果，
      // 但防御性捕获以防调用方未遵守约定）
      let parsed: T;
      try {
        parsed = params.parseResult(result.text);
      } catch (e) {
        throw new Error(
          `[ai-stream] parseResult 失败: ${e instanceof Error ? e.message : String(e)}`,
        );
      }
      writer.write({
        type: "data-result",
        data: parsed,
      } as UIMessageChunk);
    },
  });

  return createUIMessageStreamResponse({ stream });
}

/**
 * 多维表格查询引擎 —— 纯函数库，无 React 依赖。
 *
 * 可被 API 路由（Node.js）和前端组件共用，负责对 DatabaseRecord 数组
 * 应用筛选（filter）、排序（sort）和分组（group）。
 *
 * 设计：
 *  - 纯函数，无副作用，不修改输入数组（排序返回新数组）
 *  - 类型感知：根据 DatabaseField.type 做类型感知比较与匹配
 *  - 筛选支持 AND/OR 逻辑组合
 *  - 排序支持多字段优先级（sorts 数组顺序即优先级递减）
 *  - 分组支持单值与多值（multiselect/user）字段，一条记录可属多个分组
 *
 * 来源：Phase 3D 多维表格筛选/排序/分组
 */

// ─── 类型定义 ────────────────────────────────────────────────

/** 字段类型（与 Prisma DatabaseField.type 对应，运行时为 string） */
export type FieldType =
  | "text"
  | "number"
  | "select"
  | "multiselect"
  | "date"
  | "checkbox"
  | "user"
  | "url"
  | "email";

/** 筛选操作符 */
export type FilterOperator =
  | "equals"
  | "not_equals"
  | "contains"
  | "starts_with"
  | "is_empty"
  | "is_not_empty"
  | "before"
  | "after"
  | "within"
  | "is"
  | "is_not";

/** 筛选条件 */
export interface FilterCondition {
  fieldId: string;
  operator: FilterOperator;
  value: unknown;
}

/** 排序条件 */
export interface SortCondition {
  fieldId: string;
  direction: "asc" | "desc";
}

/** 筛选 + 排序 + 分组查询选项 */
export interface QueryOptions {
  filters?: FilterCondition[];
  filterLogic?: "AND" | "OR";
  sorts?: SortCondition[];
  groupFieldId?: string;
  /** 当前用户 ID，用于解析 "current_user" 筛选值（is/is_not 操作符） */
  currentUserId?: string;
}

/** 多维表格字段（与 Prisma DatabaseField 形状一致） */
export interface DatabaseField {
  id: string;
  databaseId: string;
  name: string;
  type: string;
  options: unknown;
  sortOrder: number;
}

/** 多维表格记录（与 Prisma DatabaseRecord 形状一致，data 为 { fieldId: value }） */
export interface DatabaseRecord {
  id: string;
  databaseId: string;
  data: Record<string, unknown>;
  sortOrder: number;
}

/** 分组结果 */
export interface GroupedRecords {
  key: string;
  records: DatabaseRecord[];
}

/** select 字段选项 */
export interface SelectOption {
  id: string;
  label: string;
  color?: string;
}

/** 查询结果 */
export interface QueryResult {
  groups: GroupedRecords[];
  total: number;
}

// ─── 内部常量 ────────────────────────────────────────────────

/** 未分组标签（值为空时归入此分组） */
const UNGROUPED_KEY = "未分组";

/** 全部分组标签（未指定 groupFieldId 时的单组） */
const ALL_GROUP_KEY = "全部";

// ─── 内部 helper ─────────────────────────────────────────────

/** 从记录中取字段值（防御 data 为空） */
function getFieldValue(record: DatabaseRecord, fieldId: string): unknown {
  if (typeof record.data !== "object" || record.data === null) return undefined;
  return record.data[fieldId];
}

/** 判断空值：null/undefined/空字符串/空数组 */
function isEmptyValue(v: unknown): boolean {
  if (v === null || v === undefined) return true;
  if (typeof v === "string" && v === "") return true;
  if (Array.isArray(v) && v.length === 0) return true;
  return false;
}

/** 严格相等，处理数组（multiselect 无序相等） */
function strictEquals(a: unknown, b: unknown): boolean {
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    return a.every((x) => b.includes(x));
  }
  return a === b;
}

/** 数符号（-1/0/1），避免大数减法溢出 */
function sign(n: number): number {
  return n < 0 ? -1 : n > 0 ? 1 : 0;
}

/** 值转 Date，无效返回 null */
function toDate(v: unknown): Date | null {
  if (v === null || v === undefined) return null;
  if (v instanceof Date) return isNaN(v.getTime()) ? null : v;
  if (typeof v === "string" || typeof v === "number") {
    const d = new Date(v);
    return isNaN(d.getTime()) ? null : d;
  }
  return null;
}

/** 日期比较，空值排后，返回 sign（-1/0/1） */
function compareDates(a: unknown, b: unknown): number {
  const da = toDate(a);
  const db = toDate(b);
  if (da === null && db === null) return 0;
  if (da === null) return 1;
  if (db === null) return -1;
  return sign(da.getTime() - db.getTime());
}

/**
 * within 预设范围：返回 [start, end] 闭区间。
 * 用原生 Date API 计算，周以周一为起始。
 */
function getPresetRange(preset: string, now: Date): [Date, Date] | null {
  const y = now.getFullYear();
  const m = now.getMonth();
  const d = now.getDate();

  switch (preset) {
    case "this_week": {
      const day = now.getDay(); // 0=Sun..6=Sat
      const offset = day === 0 ? 6 : day - 1; // 周一为起始
      return [
        new Date(y, m, d - offset, 0, 0, 0, 0),
        new Date(y, m, d - offset + 6, 23, 59, 59, 999),
      ];
    }
    case "this_month":
      return [new Date(y, m, 1, 0, 0, 0, 0), new Date(y, m + 1, 0, 23, 59, 59, 999)];
    case "this_year":
      return [new Date(y, 0, 1, 0, 0, 0, 0), new Date(y, 11, 31, 23, 59, 59, 999)];
    case "this_quarter": {
      const q = Math.floor(m / 3);
      const startMonth = q * 3;
      return [
        new Date(y, startMonth, 1, 0, 0, 0, 0),
        new Date(y, startMonth + 3, 0, 23, 59, 59, 999),
      ];
    }
    case "last_week": {
      const day = now.getDay();
      const offset = day === 0 ? 6 : day - 1;
      return [
        new Date(y, m, d - offset - 7, 0, 0, 0, 0),
        new Date(y, m, d - offset - 1, 23, 59, 59, 999),
      ];
    }
    case "last_month":
      return [new Date(y, m - 1, 1, 0, 0, 0, 0), new Date(y, m, 0, 23, 59, 59, 999)];
    case "last_year":
      return [new Date(y - 1, 0, 1, 0, 0, 0, 0), new Date(y - 1, 11, 31, 23, 59, 59, 999)];
    case "last_7_days":
      return [new Date(y, m, d - 6, 0, 0, 0, 0), now];
    case "last_30_days":
      return [new Date(y, m, d - 29, 0, 0, 0, 0), now];
    default:
      return null;
  }
}

/** within 范围匹配 */
function withinRange(value: unknown, preset: unknown): boolean {
  const date = toDate(value);
  if (date === null) return false;
  if (typeof preset !== "string") return false;
  const range = getPresetRange(preset, new Date());
  if (range === null) return false;
  const [start, end] = range;
  const t = date.getTime();
  return t >= start.getTime() && t <= end.getTime();
}

/** 解析用户筛选值："current_user" → currentUserId，否则原样 */
function resolveUserValue(conditionValue: unknown, currentUserId?: string): string | null {
  if (typeof conditionValue !== "string") return null;
  if (conditionValue === "current_user") return currentUserId ?? null;
  return conditionValue;
}

/** 用户匹配：fieldValue 可能是单值或数组（多指派人） */
function matchUser(fieldValue: unknown, conditionValue: unknown, currentUserId?: string): boolean {
  const resolved = resolveUserValue(conditionValue, currentUserId);
  if (resolved === null) return false;
  if (Array.isArray(fieldValue)) {
    return fieldValue.includes(resolved);
  }
  return fieldValue === resolved;
}

/** 单条件匹配 */
function matchCondition(
  record: DatabaseRecord,
  condition: FilterCondition,
  currentUserId?: string,
): boolean {
  const value = getFieldValue(record, condition.fieldId);
  const op = condition.operator;

  switch (op) {
    case "is_empty":
      return isEmptyValue(value);
    case "is_not_empty":
      return !isEmptyValue(value);
    case "equals":
      return strictEquals(value, condition.value);
    case "not_equals":
      return !strictEquals(value, condition.value);
    case "contains":
      return (
        typeof value === "string" &&
        typeof condition.value === "string" &&
        value.toLowerCase().includes(condition.value.toLowerCase())
      );
    case "starts_with":
      return (
        typeof value === "string" &&
        typeof condition.value === "string" &&
        value.toLowerCase().startsWith(condition.value.toLowerCase())
      );
    case "before":
      return compareDates(value, condition.value) < 0;
    case "after":
      return compareDates(value, condition.value) > 0;
    case "within":
      return withinRange(value, condition.value);
    case "is":
      return matchUser(value, condition.value, currentUserId);
    case "is_not":
      return !matchUser(value, condition.value, currentUserId);
    default:
      return false;
  }
}

/** 类型感知值比较（排序用），空值始终排后 */
function compareValues(a: unknown, b: unknown, fieldType: string): number {
  const aEmpty = isEmptyValue(a);
  const bEmpty = isEmptyValue(b);
  if (aEmpty && bEmpty) return 0;
  if (aEmpty) return 1;
  if (bEmpty) return -1;

  switch (fieldType) {
    case "number": {
      const na = Number(a);
      const nb = Number(b);
      if (isNaN(na) && isNaN(nb)) return 0;
      if (isNaN(na)) return 1;
      if (isNaN(nb)) return -1;
      return sign(na - nb);
    }
    case "date": {
      const da = toDate(a);
      const db = toDate(b);
      if (da === null && db === null) return 0;
      if (da === null) return 1;
      if (db === null) return -1;
      return sign(da.getTime() - db.getTime());
    }
    case "checkbox": {
      const ba = a === true || a === "true" || a === 1;
      const bb = b === true || b === "true" || b === 1;
      return sign((ba ? 1 : 0) - (bb ? 1 : 0));
    }
    default: {
      // text/select/multiselect/url/email/user: 字符串比较
      // multiselect/user 数组用逗号拼接后比较
      const sa = Array.isArray(a) ? a.join(",") : String(a);
      const sb = Array.isArray(b) ? b.join(",") : String(b);
      return sa < sb ? -1 : sa > sb ? 1 : 0;
    }
  }
}

/** 将字段值转为分组 key 数组（多值字段一条记录可属多个分组） */
function toGroupKeys(value: unknown, fieldType: string): string[] {
  if (isEmptyValue(value)) return [UNGROUPED_KEY];
  if (Array.isArray(value)) {
    // multiselect/user 多值：每个元素一个分组
    const keys = value.map((v) => String(v));
    return keys.length > 0 ? keys : [UNGROUPED_KEY];
  }
  if (typeof value === "boolean") return [value ? "是" : "否"];
  return [String(value)];
}

// ─── 导出函数 ────────────────────────────────────────────────

/**
 * 应用筛选条件。
 * @param records 记录数组
 * @param fields 字段定义（用于过滤掉引用不存在字段的无效条件）
 * @param filters 筛选条件数组
 * @param logic AND=全部满足，OR=任一满足
 * @param currentUserId 可选，用于解析 "current_user" 筛选值
 */
export function applyFilters(
  records: DatabaseRecord[],
  fields: DatabaseField[],
  filters: FilterCondition[],
  logic: "AND" | "OR",
  currentUserId?: string,
): DatabaseRecord[] {
  if (filters.length === 0) return records;
  // 过滤掉引用不存在字段的条件（字段可能已被删除）
  const fieldIds = new Set(fields.map((f) => f.id));
  const validFilters = filters.filter((c) => fieldIds.has(c.fieldId));
  if (validFilters.length === 0) return records;

  return records.filter((record) => {
    const results = validFilters.map((c) => matchCondition(record, c, currentUserId));
    return logic === "AND" ? results.every(Boolean) : results.some(Boolean);
  });
}

/**
 * 应用排序（多字段优先级递减）。
 * 不修改原数组，返回新排序数组。空值始终排后。
 * @param sorts 排序条件数组，顺序即优先级（前面的优先）
 */
export function applySorts(
  records: DatabaseRecord[],
  fields: DatabaseField[],
  sorts: SortCondition[],
): DatabaseRecord[] {
  if (sorts.length === 0) return records;
  const fieldMap = new Map(fields.map((f) => [f.id, f]));
  const sorted = [...records];
  sorted.sort((a, b) => {
    for (const sort of sorts) {
      const field = fieldMap.get(sort.fieldId);
      if (!field) continue;
      const av = getFieldValue(a, sort.fieldId);
      const bv = getFieldValue(b, sort.fieldId);
      const cmp = compareValues(av, bv, field.type);
      if (cmp !== 0) return sort.direction === "asc" ? cmp : -cmp;
    }
    return 0;
  });
  return sorted;
}

/**
 * 应用分组。
 * 按 groupFieldId 指定字段的值分组；未设置值的归入 "未分组"。
 * multiselect/user 多值字段：一条记录可属多个分组。
 * 分组顺序：按 key 字母序升序，"未分组" 始终在最后。
 */
export function applyGrouping(
  records: DatabaseRecord[],
  fields: DatabaseField[],
  groupFieldId: string,
): GroupedRecords[] {
  const field = fields.find((f) => f.id === groupFieldId);
  if (!field) return [{ key: ALL_GROUP_KEY, records: [...records] }];

  const groups = new Map<string, DatabaseRecord[]>();
  for (const record of records) {
    const value = getFieldValue(record, groupFieldId);
    const keys = toGroupKeys(value, field.type);
    for (const key of keys) {
      let group = groups.get(key);
      if (!group) {
        group = [];
        groups.set(key, group);
      }
      group.push(record);
    }
  }

  const result: GroupedRecords[] = Array.from(groups.entries()).map(([key, recs]) => ({
    key,
    records: recs,
  }));
  // 排序：未分组在最后，其余按 key 字母序升序
  result.sort((a, b) => {
    if (a.key === UNGROUPED_KEY && b.key !== UNGROUPED_KEY) return 1;
    if (b.key === UNGROUPED_KEY && a.key !== UNGROUPED_KEY) return -1;
    return a.key < b.key ? -1 : a.key > b.key ? 1 : 0;
  });
  return result;
}

/**
 * 主查询函数：对记录数组应用筛选 → 排序 → 分组。
 * 返回分组结果与筛选后总数（total 不含分组，仅筛选后的记录数）。
 */
export function queryRecords(
  records: DatabaseRecord[],
  fields: DatabaseField[],
  options: QueryOptions,
): QueryResult {
  const { filters, filterLogic, sorts, groupFieldId, currentUserId } = options;

  // 1. 筛选
  const filtered =
    filters && filters.length > 0
      ? applyFilters(records, fields, filters, filterLogic ?? "AND", currentUserId)
      : records;

  // 2. 排序
  const sorted = sorts && sorts.length > 0 ? applySorts(filtered, fields, sorts) : filtered;

  // 3. 分组
  const groups = groupFieldId
    ? applyGrouping(sorted, fields, groupFieldId)
    : [{ key: ALL_GROUP_KEY, records: sorted }];

  return { groups, total: filtered.length };
}

/** 从字段 options 中读取 select 选项列表（options 结构：{ options: SelectOption[] }） */
export function getFieldSelectOptions(field: DatabaseField): SelectOption[] {
  if (typeof field.options !== "object" || field.options === null) return [];
  const opts = field.options as { options?: unknown };
  if (!Array.isArray(opts.options)) return [];
  return opts.options as SelectOption[];
}

