import { describe, it, expect, vi } from "vitest";
import {
  API_MESSAGES,
  apiLocale,
  apiMsg,
  type ApiMsgKey,
} from "@/lib/api-messages";

// Mock NextRequest
function mockReq(opts: {
  cookie?: string;
  acceptLanguage?: string;
}): import("next/server").NextRequest {
  const headers = new Headers();
  if (opts.acceptLanguage) {
    headers.set("accept-language", opts.acceptLanguage);
  }
  const cookies: { name: string; value: string }[] = [];
  if (opts.cookie) {
    cookies.push({ name: "NEXT_LOCALE", value: opts.cookie });
  }
  return {
    cookies: {
      get: (name: string) => cookies.find((c) => c.name === name),
    },
    headers,
  } as unknown as import("next/server").NextRequest;
}

describe("api-messages - 双语常量完整性", () => {
  it("每个 key 都有 zh 和 en 两个语言", () => {
    for (const key of Object.keys(API_MESSAGES) as ApiMsgKey[]) {
      const entry = API_MESSAGES[key];
      expect(entry).toHaveProperty("zh");
      expect(entry).toHaveProperty("en");
      expect(typeof entry.zh).toBe("string");
      expect(typeof entry.en).toBe("string");
      expect(entry.zh.length).toBeGreaterThan(0);
      expect(entry.en.length).toBeGreaterThan(0);
    }
  });

  it("zh 和 en 文案不完全相同（排除合理例外）", () => {
    // 部分合理例外：缩写或专有名词
    const EXEMPT = new Set(["ok"]);
    for (const key of Object.keys(API_MESSAGES) as ApiMsgKey[]) {
      if (EXEMPT.has(key)) continue;
      const entry = API_MESSAGES[key];
      expect(entry.zh).not.toBe(entry.en);
    }
  });
});

describe("apiLocale - 语言协商", () => {
  it("NEXT_LOCALE cookie = zh → 返回 zh", () => {
    const req = mockReq({ cookie: "zh" });
    expect(apiLocale(req)).toBe("zh");
  });

  it("NEXT_LOCALE cookie = en → 返回 en", () => {
    const req = mockReq({ cookie: "en" });
    expect(apiLocale(req)).toBe("en");
  });

  it("无 cookie + Accept-Language 含 zh → 返回 zh", () => {
    const req = mockReq({ acceptLanguage: "zh-CN,zh;q=0.9,en;q=0.8" });
    expect(apiLocale(req)).toBe("zh");
  });

  it("无 cookie + Accept-Language 含 en → 返回 en", () => {
    const req = mockReq({ acceptLanguage: "en-US,en;q=0.9" });
    expect(apiLocale(req)).toBe("en");
  });

  it("无 cookie + 无 Accept-Language → 回退 zh", () => {
    const req = mockReq({});
    expect(apiLocale(req)).toBe("zh");
  });

  it("无 cookie + Accept-Language 不含 zh/en → 回退 zh", () => {
    const req = mockReq({ acceptLanguage: "fr-FR,fr;q=0.9" });
    expect(apiLocale(req)).toBe("zh");
  });

  it("cookie 优先于 Accept-Language", () => {
    const req = mockReq({ cookie: "en", acceptLanguage: "zh-CN" });
    expect(apiLocale(req)).toBe("en");
  });
});

describe("apiMsg - 取文案", () => {
  it("zh locale 返回中文文案", () => {
    const req = mockReq({ cookie: "zh" });
    expect(apiMsg(req, "taskNotFound")).toBe("任务不存在");
  });

  it("en locale 返回英文文案", () => {
    const req = mockReq({ cookie: "en" });
    expect(apiMsg(req, "taskNotFound")).toBe("Task not found");
  });

  it("默认 locale（zh）返回中文文案", () => {
    const req = mockReq({});
    expect(apiMsg(req, "unauthorized")).toBe("未授权");
  });
});

import { describe, it, expect } from "vitest";
import {
  parseActionItems,
  ACTION_TEMPLATES,
  type ParsedActionItem,
} from "@/lib/decision-action-parser";

describe("parseActionItems", () => {
  it("解析未勾选的行动项", () => {
    const md = `- [ ] @alice 2024-01-15 完成设计`;
    const items = parseActionItems(md);
    expect(items).toHaveLength(1);
    expect(items[0].checked).toBe(false);
    expect(items[0].assigneeName).toBe("alice");
    expect(items[0].dueDate).toBe("2024-01-15");
    expect(items[0].title).toBe("完成设计");
  });

  it("解析已勾选的行动项", () => {
    const md = `- [x] @bob 2024-02-01 完成开发`;
    const items = parseActionItems(md);
    expect(items).toHaveLength(1);
    expect(items[0].checked).toBe(true);
  });

  it("大写 X 也识别为已勾选", () => {
    const md = `- [X] @bob 2024-02-01 完成开发`;
    const items = parseActionItems(md);
    expect(items[0].checked).toBe(true);
  });

  it("无 @指派人 且无日期的行不触发", () => {
    const md = `- [ ] 普通待办事项`;
    const items = parseActionItems(md);
    expect(items).toHaveLength(0);
  });

  it("只有 @指派人 也触发", () => {
    const md = `- [ ] @alice 完成评审`;
    const items = parseActionItems(md);
    expect(items).toHaveLength(1);
    expect(items[0].assigneeName).toBe("alice");
    expect(items[0].dueDate).toBeNull();
  });

  it("只有日期也触发", () => {
    const md = `- [ ] 2024-03-01 完成测试`;
    const items = parseActionItems(md);
    expect(items).toHaveLength(1);
    expect(items[0].assigneeName).toBeNull();
    expect(items[0].dueDate).toBe("2024-03-01");
  });

  it("解析优先级标签", () => {
    const md = `- [ ] @alice 2024-01-15 完成设计 #high`;
    const items = parseActionItems(md);
    expect(items[0].priority).toBe("high");
  });

  it("默认优先级为 medium", () => {
    const md = `- [ ] @alice 2024-01-15 完成设计`;
    const items = parseActionItems(md);
    expect(items[0].priority).toBe("medium");
  });

  it("支持所有优先级级别", () => {
    for (const prio of ["low", "medium", "high", "urgent"] as const) {
      const md = `- [ ] @alice 2024-01-15 任务 #${prio}`;
      const items = parseActionItems(md);
      expect(items[0].priority).toBe(prio);
    }
  });

  it("优先级标签大写也识别", () => {
    const md = `- [ ] @alice 2024-01-15 任务 #HIGH`;
    const items = parseActionItems(md);
    expect(items[0].priority).toBe("high");
  });

  it("多行混合解析", () => {
    const md = `
## 执行计划

- [ ] @alice 2024-01-15 完成设计 #high
- [x] @bob 2024-02-01 完成开发 #medium
- [ ] 普通待办（不触发）
- [ ] @charlie 2024-03-01 完成测试 #low
`;
    const items = parseActionItems(md);
    expect(items).toHaveLength(3);
    expect(items[0].assigneeName).toBe("alice");
    expect(items[1].checked).toBe(true);
    expect(items[2].assigneeName).toBe("charlie");
  });

  it("lineIndex 正确记录行号", () => {
    const md = `\n\n- [ ] @alice 2024-01-15 任务`;
    const items = parseActionItems(md);
    expect(items[0].lineIndex).toBe(2);
  });

  it("标题为空时使用默认标题", () => {
    const md = `- [ ] @alice 2024-01-15`;
    const items = parseActionItems(md);
    expect(items[0].title).toBe("未命名行动项");
  });

  it("标题清理：去除多余空格", () => {
    const md = `- [ ] @alice   2024-01-15   完成   设计   #high`;
    const items = parseActionItems(md);
    expect(items[0].title).toBe("完成 设计");
  });

  it("空字符串返回空数组", () => {
    expect(parseActionItems("")).toEqual([]);
  });

  it("无行动项的文本返回空数组", () => {
    expect(parseActionItems("普通文本\n更多文本")).toEqual([]);
  });
});

